-- ============================================================
-- 圣经全文（新改訳2017）· 数据文件 2/6
-- 先运行 bible_cuv_schema.sql 建表（已运行过可跳过），再按序号运行。
-- 可重复运行（冲突自动跳过）。本文件 5200 节。
-- ============================================================
insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('JPN', '申命记', 5, 10, 14, '見よ。天と、もろもろの天の天、地とそこにあるすべてのものは、あなたの神、主のものである。'),
('JPN', '申命记', 5, 10, 15, '主はただあなたの父祖たちを慕って、彼らを愛された。そのため彼らの後の子孫であるあなたがたを、あらゆる民の中から選ばれた。今日のとおりである。'),
('JPN', '申命记', 5, 10, 16, 'あなたがたは心の包皮に割礼を施しなさい。もう、うなじを固くする者であってはならない。'),
('JPN', '申命记', 5, 10, 17, 'あなたがたの神、主は神の神、主の主、偉大で力があり、恐ろしい神。えこひいきをせず、賄賂を取らず、'),
('JPN', '申命记', 5, 10, 18, 'みなしごや、やもめのためにさばきを行い、寄留者を愛して、これに食物と衣服を与えられる。'),
('JPN', '申命记', 5, 10, 19, 'あなたがたは寄留者を愛しなさい。あなたがたもエジプトの地で寄留の民だったからである。'),
('JPN', '申命记', 5, 10, 20, 'あなたの神、主を恐れ、主に仕えなさい。主にすがり、御名によって誓いなさい。'),
('JPN', '申命记', 5, 10, 21, 'この方こそあなたの賛美、この方こそあなたの神であって、あなたが自分の目で見たこれらの大いなる恐るべきことを、あなたのために行われた方である。'),
('JPN', '申命记', 5, 10, 22, 'あなたの父祖たちは七十人でエジプトへ下ったが、今や、あなたの神、主はあなたを空の星のように多くされた。'),
('JPN', '申命记', 5, 11, 1, 'あなたはあなたの神、主を愛し、主への務めを果たし、主の掟と定めと命令をいつも守りなさい。'),
('JPN', '申命记', 5, 11, 2, '今日、心得なさい。あなたがたの子どもたちが、あなたがたの神、主の訓練を、その偉大さを、その力強い御手と伸ばされた御腕、そのしるしとみわざを経験し目撃したわけではないことを。'),
('JPN', '申命记', 5, 11, 3, '主がエジプトで、エジプトの王ファラオとその全土に対してなさったこと、'),
('JPN', '申命记', 5, 11, 4, 'またエジプトの軍勢とその馬と戦車に対してなさったこと、すなわち、彼らがあなたがたの後を追って来たとき、葦の海の水を彼らの上にあふれさせ、主がこれを滅ぼして、今日に至っていること、'),
('JPN', '申命记', 5, 11, 5, 'またあなたがたがこの場所に来るまでに、荒野であなたがたに対してなさったこと、'),
('JPN', '申命记', 5, 11, 6, 'またルベンの子エリアブの子である、ダタンとアビラムに対してなさったこと、すなわち、イスラエル全体のただ中で地がその口を開け、彼らとその家族、その天幕、また彼らにつく生けるものすべてを吞み込んだことなど、'),
('JPN', '申命记', 5, 11, 7, 'これら主がなさった偉大なみわざのすべてを自分の目で見たのは、あなたがたである。'),
('JPN', '申命记', 5, 11, 8, 'あなたがたは、私が今日あなたに命じるすべての命令を守りなさい。それは、あなたがたが強くなり、あなたがたが渡って行って所有しようとしている地を所有するため、'),
('JPN', '申命记', 5, 11, 9, 'また、主があなたがたの父祖たちに誓って、彼らとその子孫に与えると言われたその土地、すなわち、乳と蜜の流れる地で、あなたの日々が長く続くようにするためである。'),
('JPN', '申命记', 5, 11, 10, 'なぜなら、あなたが入って行って所有しようとしている地は、あなたがたが出て来たエジプトの地のようではないからである。エジプトであなたは、野菜畑でするように、自分で種を蒔き、自分の力で水をやっていた。'),
('JPN', '申命记', 5, 11, 11, 'しかし、あなたがたが渡って行って所有しようとしている地は、山と谷の地であり、天からの雨で潤っている。'),
('JPN', '申命记', 5, 11, 12, 'そこは、あなたの神、主が求められる地で、年の初めから年の終わりまで、あなたの神、主が絶えずその上に目をとどめておられる地である。'),
('JPN', '申命记', 5, 11, 13, 'もしわたしが今日あなたがたに命じる命令、すなわち、あなたがたの神、主を愛し、心を尽くし、いのちを尽くして仕えよという命令に、あなたがたが確かに聞き従うなら、'),
('JPN', '申命记', 5, 11, 14, 'わたしは時にかなって、あなたがたの地に雨、初めの雨と後の雨をもたらす。あなたは穀物と新しいぶどう酒と油を集めることができる。'),
('JPN', '申命记', 5, 11, 15, 'また、わたしはあなたの家畜のため野に草を与える。あなたは食べて満ち足りる。'),
('JPN', '申命记', 5, 11, 16, '気をつけなさい。あなたがたの心が惑わされ横道に外れて、ほかの神々に仕え、それを拝むことのないように。'),
('JPN', '申命记', 5, 11, 17, 'そうでないと、主の怒りがあなたがたに向かって燃え上がり、主が天を閉ざし、雨は降らず、地はその産物を出さなくなる。こうしてあなたがたは、主が与えようとしているその良い地から、たちまち滅び去ることになる。'),
('JPN', '申命记', 5, 11, 18, 'あなたがたは、わたしのこのことばを心とたましいに刻み、それをしるしとして手に結び付け、記章として額の上に置きなさい。'),
('JPN', '申命记', 5, 11, 19, 'それをあなたがたの子どもたちに教えなさい。あなたが家に座っているときも道を歩くときも、寝るときも起きるときも、これを彼らに語りなさい。'),
('JPN', '申命记', 5, 11, 20, 'これをあなたの家の戸口の柱と門に書き記しなさい。'),
('JPN', '申命记', 5, 11, 21, 'それは、主があなたがたの父祖たちに与えると誓った地で、あなたがたの日数とあなたがたの子孫の日数が、天が地の上にある日数のように多くなるためである。'),
('JPN', '申命记', 5, 11, 22, 'もしあなたがたが、私の命じるこのすべての命令を確かに守り行い、あなたがたの神、主を愛して主のすべての道に歩み、主にすがるなら、'),
('JPN', '申命记', 5, 11, 23, '主はこれらの国々をことごとくあなたがたの前から追い払い、あなたがたは、自分たちよりも大きくて強い国々を占領することができる。'),
('JPN', '申命记', 5, 11, 24, 'あなたがたが足の裏で踏む場所は、ことごとくあなたがたのものとなる。荒野からレバノンまで、あの川、ユーフラテス川から西の海に至るまでがあなたがたの領土となる。'),
('JPN', '申命记', 5, 11, 25, 'だれ一人として、あなたがたの前に立ちはだかる者はいない。あなたがたの神、主は、あなたがたに約束されたとおり、あなたがたが足を踏み入れる地の全面に、あなたがたに対するおののきと恐れを生じさせる。'),
('JPN', '申命记', 5, 11, 26, '見よ、私は今日、あなたがたの前に祝福とのろいを置く。'),
('JPN', '申命记', 5, 11, 27, '祝福とは、私が今日あなたがたに命じる、あなたがたの神、主の命令に聞き従った場合であり、'),
('JPN', '申命记', 5, 11, 28, 'のろいとは、あなたがたの神、主の命令に聞き従わず、私が今日あなたがたに命じる道から外れて、あなたがたの知らなかったほかの神々に従って行った場合である。'),
('JPN', '申命记', 5, 11, 29, 'あなたが入って行って所有しようとしている地に、あなたの神、主があなたを導き入れたら、あなたはゲリジム山の上には祝福を、エバル山の上にはのろいを置かなければならない。'),
('JPN', '申命记', 5, 11, 30, 'それらの山はヨルダン川の向こう側、日の入る方の、アラバに住むカナン人の地にあり、ギルガルの向かい、モレの樫の木の付近にあるではないか。'),
('JPN', '申命记', 5, 11, 31, 'あなたがたはヨルダン川を渡り、あなたがたの神、主があなたがたに与えようとしておられる地に入って行って、それを所有しようとしている。あなたがたがそこを所有し、そこに住むとき、'),
('JPN', '申命记', 5, 11, 32, '私が今日あなたがたの前に与える、すべての掟と定めを守り行わなければならない。'),
('JPN', '申命记', 5, 12, 1, 'これは、あなたの父祖の神、主があなたに与えて所有させてくださった地で、あなたがたがその土地に生きるすべての日々に、守り行わなければならない掟と定めである。'),
('JPN', '申命记', 5, 12, 2, 'あなたがたが追い払おうとする異邦の民がその神々に仕えた場所は、高い山の上でも、丘の上でも、また青々と茂るどの木の下でも、それをことごとく破壊しなければならない。'),
('JPN', '申命记', 5, 12, 3, '彼らの祭壇を打ち壊し、石の柱を打ち砕き、アシェラ像を火で焼き、神々の彫像を切り倒して、それらの名をその場所から消し去りなさい。'),
('JPN', '申命记', 5, 12, 4, 'あなたがたの神、主に対しては、そのように礼拝してはならない。'),
('JPN', '申命记', 5, 12, 5, 'ただ、あなたがたの神、主がご自分の住まいとして御名を置くために、あなたがたの全部族のうちから選ばれる場所を尋ねて、そこへ行かなければならない。'),
('JPN', '申命记', 5, 12, 6, 'あなたがたは全焼のささげ物、いけにえ、十分の一、あなたがたが供える奉納物、誓願のささげ物、進んで献げるもの、あなたがたの牛や羊の初子をそこに携えて行きなさい。'),
('JPN', '申命记', 5, 12, 7, 'そこであなたがたは家族の者とともに、あなたがたの神、主の前で食事をし、あなたの神、主が祝福してくださった、あなたがたのすべての手のわざを喜び楽しみなさい。'),
('JPN', '申命记', 5, 12, 8, 'あなたがたは、私たちが今日ここでしているようにしてはならない。それぞれが自分の目にかなうことをしている。'),
('JPN', '申命记', 5, 12, 9, 'あなたがたがまだ、あなたの神、主があなたに与えようとしておられる安住の地、ゆずりの地に入っていないからである。'),
('JPN', '申命记', 5, 12, 10, 'あなたがたがヨルダン川を渡り、あなたがたの神、主があなたがたに受け継がせようとしておられる地に住み、主が周囲のすべての敵からあなたがたを守って安息を与え、あなたがたが安らかに住むようになったら、'),
('JPN', '申命记', 5, 12, 11, 'あなたがたの神、主が御名を住まわせるために選ばれる場所へ、私が命じるすべての物を携えて行かなければならない。あなたがたの全焼のささげ物といけにえ、十分の一と、あなたがたが供える奉納物、それに主に誓う最良の誓願のささげ物である。'),
('JPN', '申命记', 5, 12, 12, 'あなたがたは息子、娘、男奴隷、女奴隷とともに、あなたがたの神、主の前で喜び楽しみなさい。また、あなたがたの町囲みの中にいるレビ人とも、そうしなさい。レビ人には、あなたがたと同じようには相続地が割り当てられないからである。'),
('JPN', '申命记', 5, 12, 13, '全焼のささげ物を、自分勝手な場所で献げないように気をつけなさい。'),
('JPN', '申命记', 5, 12, 14, 'ただ主があなたの部族の一つのうちに選ばれる場所で、あなたは全焼のささげ物を献げ、そこで、私があなたに命じるすべてのことを行いなさい。'),
('JPN', '申命记', 5, 12, 15, 'しかし、あなたの神、主があなたに下さった祝福にしたがって、あなたのどの町囲みの中でも、いつでも自分の欲するとき動物を屠り、その肉を食べることができる。汚れた人もきよい人も、かもしかや鹿と同じようにそれを食べることができる。'),
('JPN', '申命记', 5, 12, 16, 'ただし血は食べてはならない。それを地面に水のように注ぎ出さなければならない。'),
('JPN', '申命记', 5, 12, 17, 'あなたは穀物や新しいぶどう酒、オリーブ油の十分の一のささげ物、牛や羊の初子、またあなたが誓うすべての誓願のささげ物、進んで献げるもの、あなたの供える奉献物のすべてを、あなたの町囲みの中で食べることはできない。'),
('JPN', '申命记', 5, 12, 18, 'ただ、あなたの神、主が選ばれる場所で、あなたの息子、娘、男奴隷、女奴隷、およびあなたの町囲みの中にいるレビ人とともに、あなたの神、主の前でそれらを食べなければならない。あなたの神、主の前で、あなたのすべての手のわざを喜び楽しみなさい。'),
('JPN', '申命记', 5, 12, 19, 'あなたは一生、あなたの土地でレビ人をないがしろにしないように気をつけなさい。'),
('JPN', '申命记', 5, 12, 20, 'あなたの神、主が、あなたに告げたとおりにあなたの領土を広くしてくださって、あなたが肉を食べたくなるときには、「肉が食べたい」と言ってよい。あなたは食べたいだけ肉を食べてもよい。'),
('JPN', '申命记', 5, 12, 21, 'もしあなたの神、主が御名を置くために選ばれる場所が遠く離れているなら、私があなたに命じたように、あなたは主が与えられた牛と羊を屠り、あなたの町囲みの中で食べたいだけ食べてもよい。'),
('JPN', '申命记', 5, 12, 22, 'かもしかや鹿を食べるように、それを食べてもよい。汚れた人ときよい人が一緒にそれを食べてもよい。'),
('JPN', '申命记', 5, 12, 23, 'ただ、血は決して食べてはならない。血はいのちだからである。いのちを肉と一緒に食べてはならない。'),
('JPN', '申命记', 5, 12, 24, '血を食べてはならない。それを地面に水のように注ぎ出さなければならない。'),
('JPN', '申命记', 5, 12, 25, '血を食べてはならない。あなたも、あなたの後の子孫も幸せになるためである。あなたは主の目にかなうことを行わなければならない。'),
('JPN', '申命记', 5, 12, 26, 'ただし、あなたが献げるべき聖なるものと、誓願のささげ物は、主が選ばれる場所へ携えて行かなければならない。'),
('JPN', '申命记', 5, 12, 27, 'あなたの全焼のささげ物はその肉と血を、あなたの神、主の祭壇の上に献げなさい。あなたのいけにえの血は、あなたの神、主の祭壇の上に注ぎ出さなければならない。その肉は食べてもよい。'),
('JPN', '申命记', 5, 12, 28, '気をつけて、私が命じるこれらのすべてのことばに聞き従いなさい。それはあなたが、あなたの神、主の目にかなう良いことを行って、あなたも後の子孫も永久に幸せになるためである。'),
('JPN', '申命记', 5, 12, 29, 'あなたが入って行って所有しようとしている国々をあなたの神、主があなたの前から絶ち滅ぼし、あなたがそれらを所有して、その地に住むようになったら、'),
('JPN', '申命记', 5, 12, 30, 'よく気をつけて、彼らがあなたの前から根絶やしにされた後に、彼らに倣って罠に陥らないようにしなさい。「これらの異邦の民はどのように神々に仕えたのだろう。私もそうしてみよう」と言って、彼らの神々を求めることのないようにしなさい。'),
('JPN', '申命记', 5, 12, 31, 'あなたの神、主に対して彼らのように礼拝してはならない。彼らは主が憎むあらゆる忌み嫌うべきことをその神々に行い、自分たちの息子、娘を自分たちの神々のために火で焼くことさえしたのである。'),
('JPN', '申命记', 5, 12, 32, 'あなたがたは、私があなたがたに命じるすべてのことを守り行わなければならない。これにつけ加えたり減らしたりしてはならない。'),
('JPN', '申命记', 5, 13, 1, 'あなたがたのうちに預言者または夢見る者が現れ、あなたに何かのしるしや不思議を示し、'),
('JPN', '申命记', 5, 13, 2, 'あなたに告げたそのしるしと不思議が実現して、「さあ、あなたが知らなかったほかの神々に従い、これに仕えよう」と言っても、'),
('JPN', '申命记', 5, 13, 3, 'その預言者、夢見る者のことばに聞き従ってはならない。あなたがたの神、主は、あなたがたが心を尽くし、いのちを尽くして、本当にあなたがたの神、主を愛しているかどうかを知ろうとして、あなたがたを試みておられるからである。'),
('JPN', '申命记', 5, 13, 4, 'あなたがたの神、主に従って歩み、主を恐れなければならない。主の命令を守り、御声に聞き従い、主に仕え、主にすがらなければならない。'),
('JPN', '申命记', 5, 13, 5, 'その預言者あるいは夢見る者は殺されなければならない。なぜならその人は、あなたがたをエジプトの地から導き出して奴隷の家から贖い出された、あなたがたの神、主に対して、あなたがたが反逆するようにそそのかし、あなたがたの神、主が歩めと命じた道から、あなたを迷わせようとするからである。あなたがたの中からその悪い者を除き去りなさい。'),
('JPN', '申命记', 5, 13, 6, 'あなたと母を同じくする兄弟、あるいはあなたの息子、娘、あるいはあなたの愛妻、あるいはあなたの無二の親友がひそかにあなたをそそのかして、「さあ、ほかの神々に仕えよう」と言うかもしれない。これはあなたも先祖たちも知らなかった神々で、'),
('JPN', '申命记', 5, 13, 7, '地の果てから果てまで、あなたの近くにいる、あるいはあなたから遠く離れている、あなたがたの周りのあらゆる民の神々である。'),
('JPN', '申命记', 5, 13, 8, 'あなたはそういう者に同意しようとしたり、耳を貸したりしてはならない。そのような者にあわれみをかけたり、容赦したり、かばったりしてはならない。'),
('JPN', '申命记', 5, 13, 9, '必ずその人を殺さなければならない。彼を処刑するには、まず、あなたが彼に手を下し、その後で、民全員が手を下すようにしなさい。'),
('JPN', '申命记', 5, 13, 10, '彼を石で打ちなさい。彼は死ななければならない。彼は、エジプトの地、奴隷の家からあなたを導き出されたあなたの神、主から、あなたを迷わせようとしたからである。'),
('JPN', '申命记', 5, 13, 11, 'イスラエルはみな聞いて恐れ、二度とこのような悪をあなたがたのうちで行わないであろう。'),
('JPN', '申命记', 5, 13, 12, 'もしあなたの神、主があなたに与えて住まわせる町の一つで、'),
('JPN', '申命记', 5, 13, 13, 'よこしまな者たちがあなたのうちから出て、「さあ、あなたがたが知らなかったほかの神々に仕えよう」と言って町の住民を迷わせたと聞いたなら、'),
('JPN', '申命记', 5, 13, 14, 'あなたは調べ、探り、よく問いたださなければならない。もしそのような忌み嫌うべきことが、あなたがたのうちで行われたことが事実で確かなら、'),
('JPN', '申命记', 5, 13, 15, 'あなたはその町の住民を必ず剣の刃で討たなければならない。その町とそこにいるすべての者、その家畜も剣の刃で聖絶しなさい。'),
('JPN', '申命记', 5, 13, 16, 'そのすべての略奪物を広場の中央に集め、その町と略奪物のすべてを、あなたの神、主への焼き尽くすささげ物として火で燃やさなければならない。その町は永久に廃墟となり、再建されることはない。'),
('JPN', '申命记', 5, 13, 17, 'その聖絶の物は、一部でも、あなたの手の中にとどまることがあってはならない。それは主が燃える怒りを収めて、あなたにあわれみを施し、あなたの父祖たちに誓ったとおりに、あなたをあわれんで、あなたを増やすためである。'),
('JPN', '申命记', 5, 13, 18, 'というのは、あなたは必ずあなたの神、主の御声に聞き従って、私が今日あなたに命じるすべての主の命令を守り、あなたの神、主の目にかなうことを行わなければならないからである。'),
('JPN', '申命记', 5, 14, 1, 'あなたがたは、あなたがたの神、主の子どもである。死人のために自分の身を傷つけたり、また額を剃り上げたりしてはならない。'),
('JPN', '申命记', 5, 14, 2, 'あなたは、あなたの神、主の聖なる民だからである。主は地の面のあらゆる民の中からあなたを選んで、ご自分の宝の民とされた。'),
('JPN', '申命记', 5, 14, 3, 'あなたは、忌み嫌うべきものは、どのようなものも食べてはならない。'),
('JPN', '申命记', 5, 14, 4, 'あなたがたが食べてもよい動物は牛、羊、やぎ、'),
('JPN', '申命记', 5, 14, 5, '鹿、かもしか、のろ鹿、野やぎ、くじか、大鹿、野羊。'),
('JPN', '申命记', 5, 14, 6, 'ひづめが分かれ、完全に二つに割れているもので、反芻するものはすべて食べてもよい。'),
('JPN', '申命记', 5, 14, 7, 'ただし、反芻するもの、あるいは、ひづめが分かれているものの中でも、らくだ、野うさぎ、岩だぬきは食べてはならない。これらは反芻するが、ひづめが分かれていないので、あなたがたには汚れたものである。'),
('JPN', '申命记', 5, 14, 8, '豚もそうである。ひづめは分かれているが、反芻しないので、あなたがたには汚れたものである。それらの肉を食べてはならない。また、それらの死骸に触れてもいけない。'),
('JPN', '申命记', 5, 14, 9, '水の中にいるすべてのもののうちで次のものを、あなたがたは食べてもよい。ひれと鱗のあるものはすべて食べてもよい。'),
('JPN', '申命记', 5, 14, 10, 'ひれや鱗のないものはすべて、食べてはならない。それは、あなたがたには汚れたものである。'),
('JPN', '申命记', 5, 14, 11, 'きよい鳥はすべて食べてもよい。'),
('JPN', '申命记', 5, 14, 12, 'しかし、食べてならないのは次のものである。禿鷲、禿鷹、黒禿鷹、'),
('JPN', '申命记', 5, 14, 13, '黒鳶、隼、鳶の類、'),
('JPN', '申命记', 5, 14, 14, '烏の類すべて、'),
('JPN', '申命记', 5, 14, 15, 'だちょう、夜鷹、かもめ、鷹の類、'),
('JPN', '申命记', 5, 14, 16, 'ふくろう、みみずく、白ふくろう、'),
('JPN', '申命记', 5, 14, 17, '森ふくろう、野雁、鵜、'),
('JPN', '申命记', 5, 14, 18, 'こうのとり、鷺の類、やつがしら、こうもり。'),
('JPN', '申命记', 5, 14, 19, '羽があって群がるものはすべて、あなたがたには汚れたものである。それらを食べてはならない。'),
('JPN', '申命记', 5, 14, 20, '羽のあるきよいものはすべて食べてもよい。'),
('JPN', '申命记', 5, 14, 21, 'あなたがたは自然に死んだものをいっさい食べてはならない。あなたの町囲みの中にいる寄留者にそれを与えて、彼がそれを食べるのはよい。あるいは異国人に売りなさい。あなたは、あなたの神、主の聖なる民だからである。あなたは子やぎをその母の乳で煮てはならない。'),
('JPN', '申命记', 5, 14, 22, 'あなたは毎年、種を蒔いて畑から得るすべての収穫の十分の一を、必ず献げなければならない。'),
('JPN', '申命记', 5, 14, 23, '主が御名を住まわせるために選ばれる場所、あなたの神、主の前であなたの穀物、新しいぶどう酒、油の十分の一、そして牛や羊の初子を食べなさい。あなたが、いつまでも、あなたの神、主を恐れることを学ぶためである。'),
('JPN', '申命记', 5, 14, 24, 'もしあなたの神、主が御名を置くために選ばれる場所が遠くて、あなたの神、主に祝福していただくために運んで行くことができないほど、道のりが長いなら、'),
('JPN', '申命记', 5, 14, 25, 'あなたはそれを金に換え、その金を包んで手に取り、あなたの神、主が選ばれる場所に行きなさい。'),
('JPN', '申命记', 5, 14, 26, 'あなたは、そこでその金を、すべてあなたの欲するもの、牛、羊、ぶどう酒、強い酒、また何であれ、あなたが望むものに換えなさい。そしてあなたの神、主の前で食べ、あなたの家族とともに喜び楽しみなさい。'),
('JPN', '申命记', 5, 14, 27, 'あなたの町囲みの中にいるレビ人をないがしろにしてはならない。彼は、あなたと同じようには相続地を割り当てられないからである。'),
('JPN', '申命记', 5, 14, 28, '三年の終わりごとに、その年の収穫の十分の一を全部持ち出し、あなたの町囲みの中に置いておかなければならない。'),
('JPN', '申命记', 5, 14, 29, 'そうすれば、あなたと同じようには相続地を割り当てられないレビ人や、あなたの町囲みの中にいる寄留者や、孤児や、やもめが来て食べ、満ち足りるであろう。それはあなたの神、主があなたのすべての手のわざを祝福してくださるためである。'),
('JPN', '申命记', 5, 15, 1, 'あなたは七年の終わりごとに、負債の免除をしなければならない。'),
('JPN', '申命记', 5, 15, 2, 'その免除の仕方は次のとおりである。貸し主はみな、その隣人に貸したものを免除する。その隣人や同胞から取り立ててはならない。主が負債の免除を布告されたからである。'),
('JPN', '申命记', 5, 15, 3, '異国人からは取り立ててもよいが、あなたの同胞があなたに借りているものは免除しなければならない。'),
('JPN', '申命记', 5, 15, 4, 'もっとも、あなたの神、主が相続地としてあなたに与えて所有させようとしておられる地で、主が必ずあなたを祝福されるので、あなたのうちには貧しい人がいなくなるであろう。'),
('JPN', '申命记', 5, 15, 5, 'ただしそれは、もしあなたが、あなたの神、主の御声に確かに聞き従い、私が今日あなたに命じるこのすべての命令を守り行ったなら、である。'),
('JPN', '申命记', 5, 15, 6, 'あなたの神、主はあなたに約束したようにあなたを祝福されるから、あなたは多くの国々に貸すが、あなたが借りることはない。また、あなたは多くの国々を支配するが、彼らがあなたを支配することはない。'),
('JPN', '申命记', 5, 15, 7, 'あなたの神、主があなたに与えようとしておられる地で、あなたのどの町囲みの中ででも、あなたの同胞の一人が貧しい者であるとき、その貧しい同胞に対してあなたの心を頑なにしてはならない。また手を閉ざしてはならない。'),
('JPN', '申命记', 5, 15, 8, '必ずあなたの手を彼に開き、その必要としているものを十分に貸し与えなければならない。'),
('JPN', '申命记', 5, 15, 9, 'あなたは心によこしまな考えを抱き、「第七年、免除の年が近づいた」と言って、貧しい同胞に物惜しみして、何も与えないことのないように気をつけなさい。その人があなたのことで主に叫ぶなら、あなたは罪責を負うことになる。'),
('JPN', '申命记', 5, 15, 10, '必ず彼に与えなさい。また、与えるとき物惜しみをしてはならない。このことのゆえに、あなたの神、主は、あなたのすべての働きと手のわざを祝福してくださるからである。'),
('JPN', '申命记', 5, 15, 11, '貧しい人が国のうちから絶えることはないであろう。それゆえ私はあなたに命じる。「あなたの地にいるあなたの同胞で、困窮している人と貧しい人には、必ずあなたの手を開かなければならない。」'),
('JPN', '申命记', 5, 15, 12, 'もしあなたの同胞、ヘブル人の男あるいは女が、あなたのところに売られてきて六年間あなたに仕えたなら、七年目には自由の身として、あなたのもとから去らせなければならない。'),
('JPN', '申命记', 5, 15, 13, 'その人を自由の身として去らせるときは、何も持たせずに去らせてはならない。'),
('JPN', '申命记', 5, 15, 14, '必ず、あなたの羊の群れと打ち場と踏み場のうちから取って、彼に分けてやらなければならない。あなたの神、主があなたに祝福として与えられたものを与えなければならない。'),
('JPN', '申命记', 5, 15, 15, 'あなたは、エジプトの地で奴隷であったこと、そして、あなたの神、主があなたを贖い出されたことを覚えていなければならない。それゆえ、私は今日このことをあなたに命じるのである。'),
('JPN', '申命记', 5, 15, 16, 'しかし、その人があなたとあなたの家族を愛し、あなたのもとにいて幸せなので、「あなたのもとから去りたくありません」と言うなら、'),
('JPN', '申命记', 5, 15, 17, 'あなたはきりを取って、彼の耳を戸に刺しなさい。彼はいつまでもあなたの奴隷となる。女奴隷にも同じようにしなければならない。'),
('JPN', '申命记', 5, 15, 18, '彼を自由の身として去らせるときには、厳しくしてはならない。彼は六年間、雇い人の賃金の二倍の分あなたに仕えたからである。こうして、あなたの神、主は、あなたのなすすべてのことにおいて、あなたを祝福してくださる。'),
('JPN', '申命记', 5, 15, 19, 'あなたの牛の群れや羊の群れに生まれた雄の初子はみな、あなたの神、主に聖別しなければならない。牛の初子を使って働いてはならない。また羊の初子の毛を刈ってはならない。'),
('JPN', '申命记', 5, 15, 20, '毎年あなたの神、主の前で、主が選ばれる場所で、あなたは家族とともにそれを食べなければならない。'),
('JPN', '申命记', 5, 15, 21, 'もしそれに欠陥、すなわち足が萎えていたり目が見えなかったり、何らかの著しい欠陥があれば、あなたの神、主にそれをいけにえとして屠ってはならない。'),
('JPN', '申命记', 5, 15, 22, 'あなたは町囲みの中で、汚れた人もきよい人も一緒に、かもしかや鹿と同じようにそれを食べてもよい。'),
('JPN', '申命记', 5, 15, 23, 'ただし、その血を食べてはならない。それを地面に水のように注ぎ出さなければならない。'),
('JPN', '申命记', 5, 16, 1, 'アビブの月を守り、あなたの神、主の過越を祝いなさい。アビブの月に、あなたの神、主が夜のうちにエジプトからあなたを導き出されたからである。'),
('JPN', '申命记', 5, 16, 2, '主が御名を住まわせるために選ばれる場所で、あなたの神、主に、過越のいけにえとして羊と牛を屠りなさい。'),
('JPN', '申命记', 5, 16, 3, 'そこでは種入りのパンを食べてはならない。七日間、種なしパン、苦しみのパンを食べなさい。あなたはエジプトの地から急いで出て来たからである。それは、あなたがエジプトの地から出て来た日を、一生の間覚えているためである。'),
('JPN', '申命记', 5, 16, 4, '七日間はパン種が、あなたの土地のどこにも見当たらないようにしなければならない。また、最初の日の夕方にいけにえとして屠ったその肉を、朝まで残しておいてはならない。'),
('JPN', '申命记', 5, 16, 5, '過越のいけにえを屠ることができるのは、あなたの神、主が与えてくださるあなたの町囲みのどこでもよいのではない。'),
('JPN', '申命记', 5, 16, 6, 'ただ、あなたの神、主が御名を住まわせるために選ばれるその場所で、夕方、日の沈むころ、あなたがエジプトから出た時刻に、過越のいけにえを屠らなければならない。'),
('JPN', '申命记', 5, 16, 7, 'そして、あなたの神、主が選ばれるその場所でそれを調理して食べなさい。そして朝、自分の天幕に戻りなさい。'),
('JPN', '申命记', 5, 16, 8, '六日間、種なしパンを食べなければならない。七日目には、あなたの神、主へのきよめの集会がある。仕事をしてはならない。'),
('JPN', '申命记', 5, 16, 9, 'また七週間を数えなければならない。鎌を立ち穂に入れ始めるときから、七週間を数え始めなければならない。'),
('JPN', '申命记', 5, 16, 10, 'そして、あなたの神、主のために七週の祭りを行い、あなたの神、主の祝福に応じて、進んで献げるささげ物をあなたの手によって豊かに献げなさい。'),
('JPN', '申命记', 5, 16, 11, 'あなたはあなたの息子、娘、男女の奴隷、あなたの町囲みの中にいるレビ人、あなたがたのうちの寄留者、孤児、やもめとともに、あなたの神、主の前で、あなたの神、主が御名を住まわせるために選ばれる場所で喜び楽しみなさい。'),
('JPN', '申命记', 5, 16, 12, 'あなたがエジプトで奴隷であったことを覚え、これらの掟を守り行いなさい。'),
('JPN', '申命记', 5, 16, 13, 'あなたの打ち場とあなたの踏み場から取り入れが済んだとき、七日間、仮庵の祭りをしなければならない。'),
('JPN', '申命记', 5, 16, 14, 'この祭りのときには、あなたも、あなたの息子、娘、男女の奴隷、あなたの町囲みの中にいるレビ人、寄留者、孤児、やもめもともに喜び楽しみなさい。'),
('JPN', '申命记', 5, 16, 15, 'あなたの神、主のために、主が選ばれる場所で七日間、祭りをしなければならない。あなたの神、主があなたのすべての収穫、あなたの手のすべてのわざを祝福されるからである。あなたは大いに喜びなさい。'),
('JPN', '申命记', 5, 16, 16, 'あなたのうちの男子はみな、年に三度、種なしパンの祭り、七週の祭り、仮庵の祭りのときに、あなたの神、主が選ばれる場所で御前に出なければならない。主の前には何も持たずに出てはならない。'),
('JPN', '申命记', 5, 16, 17, 'あなたの神、主が与えてくださった祝福に応じて、それぞれ自分の贈り物を持って出なければならない。'),
('JPN', '申命记', 5, 16, 18, 'あなたの神、主があなたに与えようとしておられる、あなたのすべての町囲みの中に、あなたの部族ごとに、さばき人たちと、つかさたちを任命しなければならない。彼らは公正に民をさばかなければならない。'),
('JPN', '申命记', 5, 16, 19, 'あなたはさばきを曲げてはならない。人を偏って見てはならない。賄賂を取ってはならない。賄賂は知恵のある人を盲目にし、正しい人の言い分をゆがめるからである。'),
('JPN', '申命记', 5, 16, 20, '正義を、ただ正義を追い求めなければならない。そうすれば、あなたは生き、あなたの神、主が与えようとしておられる地を自分の所有とすることができる。'),
('JPN', '申命记', 5, 16, 21, 'あなたが築く、あなたの神、主の祭壇のそばに、どのような木でできたアシェラ像も立ててはならない。'),
('JPN', '申命记', 5, 16, 22, 'あなたは、あなたの神、主が憎まれる石の柱を立ててはならない。'),
('JPN', '申命记', 5, 17, 1, '悪性の欠陥のある牛や羊は、いかなるものでも、あなたの神、主にいけにえとして屠ってはならない。それは、あなたの神、主が忌み嫌われるものだからである。'),
('JPN', '申命记', 5, 17, 2, 'あなたの神、主があなたに与えようとしておられる町囲みのどの一つでも、その中で男であれ女であれ、あなたの神、主の目に悪であることを行い、主の契約を破り、'),
('JPN', '申命记', 5, 17, 3, '行ってほかの神々に仕え、また、太陽や月や天の万象など、私が命じなかったものを拝む者があり、'),
('JPN', '申命记', 5, 17, 4, 'それがあなたに告げられて、あなたが聞いたなら、あなたはよく調査しなさい。もしそのことが事実で確かであり、この忌み嫌うべきことがイスラエルのうちで行われたのなら、'),
('JPN', '申命记', 5, 17, 5, 'あなたは、この悪しきことを行った男または女を町の広場に連れ出し、男でも女でも彼らを石で打ちなさい。彼らは死ななければならない。'),
('JPN', '申命记', 5, 17, 6, '二人の証人または三人の証人の証言によって、死刑に処さなければならない。一人の証言で死刑に処してはならない。'),
('JPN', '申命记', 5, 17, 7, '死刑に処するには、まず証人たちが手を下し、それから民全員が手を下す。こうして、あなたがたの中からその悪い者を除き去りなさい。'),
('JPN', '申命记', 5, 17, 8, 'もし町囲みの中で争い事が起こり、それが流血、権利、傷害に関わる事件で、あなたがさばきかねるものであれば、あなたはただちに、あなたの神、主が選ばれる場所に上り、'),
('JPN', '申命记', 5, 17, 9, 'レビ人の祭司たち、あるいは、そのときに立てられているさばき人のもとに行って尋ねなさい。彼らはあなたに判決のことばを告げるであろう。'),
('JPN', '申命记', 5, 17, 10, 'あなたは、主が選ばれるその場所で彼らが告げる判決にしたがって行い、すべて彼らがあなたに教えることを守り行いなさい。'),
('JPN', '申命记', 5, 17, 11, '彼らがあなたに教えるおしえにしたがって、彼らがあなたに述べるさばきにしたがって行動しなければならない。彼らが告げる判決から右にも左にも外れてはならない。'),
('JPN', '申命记', 5, 17, 12, 'もし人が、あなたの神、主に仕えてそこに立つ祭司やさばき人に聞き従わず、不遜なふるまいをするなら、その者は死ななければならない。あなたはイスラエルのうちからその悪い者を除き去りなさい。'),
('JPN', '申命记', 5, 17, 13, 'そうすれば、民はみな聞いて恐れ、もう不遜なふるまいをすることはないであろう。'),
('JPN', '申命记', 5, 17, 14, 'あなたの神、主があなたに与えようとしておられる地に入って行って、それを占領し、そこに住むようになったとき、あなたが「周りのすべての国々と同じように私も自分の上に王を立てたい」と言うなら、'),
('JPN', '申命记', 5, 17, 15, '必ず、あなたの神、主が選ばれる者をあなたの上に王として立てなければならない。あなたの同胞の中から、あなたの上に王を立てなければならない。同胞でない異国人をあなたの上に立てることはできない。'),
('JPN', '申命记', 5, 17, 16, 'ただし王は、決して自分のために馬を増やしてはならない。馬を増やすために民をエジプトに戻らせてはならない。主は「二度とこの道を戻ってはならない」とあなたがたに言われた。'),
('JPN', '申命记', 5, 17, 17, 'また王は、自分のために多くの妻を持って、心がそれることがあってはならない。自分のために銀や金を過剰に持ってはならない。'),
('JPN', '申命记', 5, 17, 18, 'その王国の王座に就いたら、レビ人の祭司たちの前にある書から自分のために、このみおしえを巻物に書き写し、'),
('JPN', '申命记', 5, 17, 19, '自分の手もとに置き、一生の間これを読まなければならない。それは、王が自分の神、主を恐れ、このみおしえのすべてのことばと、これらの掟を守り行うことを学ぶためである。'),
('JPN', '申命记', 5, 17, 20, 'それは、王の心が自分の同胞の上に高ぶることのないようにするため、また命令から右にも左にも外れることがなく、彼とその子孫がイスラエルのうちで、長くその王国を治めることができるようにするためである。'),
('JPN', '申命记', 5, 18, 1, 'レビ人の祭司たち、レビ部族はすべて、イスラエルと同じようには相続地の割り当てを受けてはならない。彼らは主への食物のささげ物を、自分への割り当ての分として食べていく。'),
('JPN', '申命记', 5, 18, 2, '彼らは、その兄弟たちの部族の中で相続地を持たない。主が約束されたとおり、主ご自身が彼らのゆずりである。'),
('JPN', '申命记', 5, 18, 3, '祭司たちが民から、すなわち、牛でも羊でも、いけにえを献げる者たちから受けるべきものについての定めは、次のとおりである。肩と両頬と胃の部分は祭司に与える。'),
('JPN', '申命记', 5, 18, 4, 'あなたの穀物や新しいぶどう酒や油などの初物、および羊の毛の初物も彼に与える。'),
('JPN', '申命记', 5, 18, 5, '彼とその子孫がいつまでも主の御名によって奉仕に立つために、あなたの神、主があなたの全部族の中から彼を選ばれたのである。'),
('JPN', '申命记', 5, 18, 6, 'もしレビ人が、自分が住んでいる、イスラエル中のどの町囲みの中からでも出ることを望むなら、主が選ばれる場所に望むままに行くことができる。'),
('JPN', '申命记', 5, 18, 7, '彼は、その場所で主の前に立つ自分の同族レビ人と全く同じように、自分の神、主の御名によって奉仕することができる。'),
('JPN', '申命记', 5, 18, 8, '彼の取り分は、相続財産を売った分は別として、彼らが食べる取り分と同じである。'),
('JPN', '申命记', 5, 18, 9, 'あなたの神、主があなたに与えようとしておられる地に入ったとき、あなたは、その異邦の民の忌み嫌うべき慣わしをまねてはならない。'),
('JPN', '申命记', 5, 18, 10, 'あなたのうちに、自分の息子、娘に火の中を通らせる者、占いをする者、卜者、まじない師、呪術者、'),
('JPN', '申命记', 5, 18, 11, '呪文を唱える者、霊媒をする者、口寄せ、死者に伺いを立てる者があってはならない。'),
('JPN', '申命记', 5, 18, 12, 'これらのことを行う者はみな、主が忌み嫌われるからである。これらの忌み嫌うべきことのゆえに、あなたの神、主はあなたの前から彼らを追い払われるのである。'),
('JPN', '申命记', 5, 18, 13, 'あなたは、あなたの神、主のもとで全き者でなければならない。'),
('JPN', '申命记', 5, 18, 14, '確かに、あなたが追い払おうとしているこれらの異邦の民は、卜者や占い師に聞き従ってきた。しかし、あなたの神、主はあなたがそうすることを許さない。'),
('JPN', '申命记', 5, 18, 15, 'あなたの神、主はあなたのうちから、あなたの同胞の中から、私のような一人の預言者をあなたのために起こされる。あなたがたはその人に聞き従わなければならない。'),
('JPN', '申命记', 5, 18, 16, 'これは、あなたがホレブでのあの集まりの日に、あなたの神、主に求めて、「私の神、主の御声は二度と聞きたくありません。この大きな火はもう見たくありません。私は死にたくありません」と言ったことによるものである。'),
('JPN', '申命记', 5, 18, 17, 'それで主は私に言われた。「彼らの言ったことはもっともだ。'),
('JPN', '申命记', 5, 18, 18, 'わたしは彼らの同胞のうちから、彼らのためにあなたのような一人の預言者を起こして、彼の口にわたしのことばを授ける。彼はわたしが命じることすべてを彼らに告げる。'),
('JPN', '申命记', 5, 18, 19, 'わたしの名によって彼が告げる、わたしのことばに聞き従わない者があれば、わたしはその人に責任を問う。'),
('JPN', '申命记', 5, 18, 20, 'ただし、預言者であっても、わたしが告げよと命じていないことを、不遜にもわたしの名によって告げたり、あるいは、ほかの神々の名によって告げたりする者がいるなら、その預言者は死ななければならない。」'),
('JPN', '申命记', 5, 18, 21, 'あなたが心の中で、「私たちは主が語られたのではないことばを、どのようにして知ることができるだろうか」と言うような場合、'),
('JPN', '申命记', 5, 18, 22, '預言者が主の名によって語っても、そのことが起こらず、実現しないなら、それは主が語られたことばではない。その預言者が不遜にもそれを語ったのである。彼におびえることはない。'),
('JPN', '申命记', 5, 19, 1, 'あなたの神、主があなたに与えようとしておられる地の国々を、あなたの神、主が絶ち滅ぼし、あなたがそれらを占領し、それらの町々や家々に住むようになったとき、'),
('JPN', '申命记', 5, 19, 2, 'あなたの神、主があなたに与えて所有させようとしておられるその地に、三つの町を取り分けなければならない。'),
('JPN', '申命记', 5, 19, 3, 'あなたは距離を測定し、あなたの神、主があなたに受け継がせる地域を三つに区分しなければならない。殺人者はだれでも、そこに逃れることができる。'),
('JPN', '申命记', 5, 19, 4, 'これは、その場所に逃れて生きることができる場合、すなわち、前から憎んでいたわけではない隣人を、意図せずに打ち殺してしまった殺人者に関する規定である。'),
('JPN', '申命记', 5, 19, 5, 'たとえば、隣人と一緒に、木を切り出そうと森に入り、木を切るために斧を手にして振り上げたところ、斧の頭が柄から抜けて隣人に当たり、その人が死んだ場合、その者はこれらの町の一つに逃れて生きることができる。'),
('JPN', '申命记', 5, 19, 6, '血の復讐をする者が怒りの心に燃え、その殺人者を追いかけ、道が遠いためにその人に追いついて、打ち殺すようなことがあってはならない。その人は前から相手を憎んでいたわけではないから、死刑に当たらない。'),
('JPN', '申命记', 5, 19, 7, 'それゆえ私はあなたに命じて、「三つの町を取り分けよ」と言ったのである。'),
('JPN', '申命记', 5, 19, 8, 'あなたの神、主が、あなたの父祖たちに誓ったとおりにあなたの領土を広げ、また、父祖たちに与えると約束した地をすべてあなたに与えられたなら、'),
('JPN', '申命记', 5, 19, 9, 'すなわち、私が今日あなたに命じるこのすべての命令をあなたが守り行い、あなたの神、主を愛し、いつまでもその道を歩むなら、そのとき、この三つの町にさらに三つの町を追加しなさい。'),
('JPN', '申命记', 5, 19, 10, 'あなたの神、主が相続地としてあなたに与えようとしておられる地で、咎のない者の血が流されることがなく、また、あなたが血の責任を負うことのないようにするためである。'),
('JPN', '申命记', 5, 19, 11, 'しかし、もし人が自分の隣人を憎み、待ち伏せして襲いかかり、彼を打って死なせ、これらの町の一つに逃れるようなことがあれば、'),
('JPN', '申命记', 5, 19, 12, '彼の町の長老たちは人を遣わして彼をそこから引き出し、血の復讐をする者の手に渡さなければならない。彼は死ななければならない。'),
('JPN', '申命记', 5, 19, 13, '彼にあわれみをかけてはならない。咎のない者の血を流す罪をイスラエルから除き去りなさい。それは、あなたのためになる。'),
('JPN', '申命记', 5, 19, 14, 'あなたの神、主があなたに与えて所有させようとしておられる地、すなわち、あなたの受け継ぐ相続地で、あなたは先代の人々が定めた隣人との地境を移してはならない。'),
('JPN', '申命记', 5, 19, 15, 'いかなる咎でも、いかなる罪でも、すべて人が犯した罪過は、一人の証人によって立証されてはならない。二人の証人の証言、または三人の証人の証言によって、そのことは立証されなければならない。'),
('JPN', '申命记', 5, 19, 16, '悪意のある証人が立って、ある人に不正な証言をする場合には、'),
('JPN', '申命记', 5, 19, 17, '争い合うこの二人の者は主の前に、その時の祭司たちとさばき人たちの前に立たなければならない。'),
('JPN', '申命记', 5, 19, 18, 'さばき人たちはよく調べたうえで、もしその証人が偽りの証人であり、自分の同胞について偽りの証言をしていたのであれば、'),
('JPN', '申命记', 5, 19, 19, 'あなたがたは、彼がその同胞にしようと企んでいたとおりに彼に対して行い、あなたがたの中からその悪い者を除き去りなさい。'),
('JPN', '申命记', 5, 19, 20, 'ほかの人々も聞いて恐れ、再びこのような悪事をあなたのうちで行うことはないであろう。'),
('JPN', '申命记', 5, 19, 21, 'あわれみをかけてはならない。いのちにはいのちを、目には目を、歯には歯を、手には手を、足には足を。'),
('JPN', '申命记', 5, 20, 1, 'あなたが敵と戦おうと出て行くとき、馬や戦車や、あなたよりも多い軍勢を見ても、彼らを恐れてはならない。あなたをエジプトの地から連れ上ったあなたの神、主があなたとともにおられるのだから。'),
('JPN', '申命记', 5, 20, 2, 'あなたがたが戦いに臨むときには、祭司が進み出て民に語りかけ、'),
('JPN', '申命记', 5, 20, 3, '彼らに言いなさい。「聞け、イスラエルよ。あなたがたは今日、敵との戦いに臨もうとしている。弱気になってはならない。恐れてはならない。うろたえてはならない。彼らのことでおののいてはならない。'),
('JPN', '申命记', 5, 20, 4, 'あなたがたの神、主があなたがたとともに行って、あなたがたのために敵と戦い、あなたがたに勝利を得させてくださるからである。」'),
('JPN', '申命记', 5, 20, 5, 'つかさたちは民に語りかけて言いなさい。「新しい家を建てて、まだそれを奉献していない者はいないか。その人は家に帰るがよい。戦死して、ほかの人がそれを奉献するといけないから。'),
('JPN', '申命记', 5, 20, 6, 'ぶどう畑を作って、まだその初物を味わっていない者はいないか。その人は家に帰るがよい。戦死して、ほかの者が初物を味わうといけないから。'),
('JPN', '申命记', 5, 20, 7, '女と婚約して、まだ結婚していない者はいないか。その人は家に帰るがよい。戦死して、ほかの人が彼女と結婚するといけないから。」'),
('JPN', '申命记', 5, 20, 8, 'つかさたちは、さらに民に語りかけて言わなければならない。「恐れて弱気になっている者はいないか。その人は自分の家に帰るがよい。兄弟たちの心がその人の心のように萎えるといけないから。」'),
('JPN', '申命记', 5, 20, 9, 'つかさたちが民に語り終えたら、軍の長たちが民の指揮を執りなさい。'),
('JPN', '申命记', 5, 20, 10, 'あなたが、ある町を攻略しようとしてその町に近づいたときには、まず降伏を勧めなさい。'),
('JPN', '申命记', 5, 20, 11, 'もし町が降伏に同意して門を開くなら、その中にいる民はみな、あなたのために苦役に服させ、あなたに仕えさせなさい。'),
('JPN', '申命记', 5, 20, 12, 'しかし、もしあなたに降伏せず、戦おうとするなら、これを包囲しなさい。'),
('JPN', '申命记', 5, 20, 13, 'あなたの神、主がそれをあなたの手に渡されたら、その町の男をみな剣の刃で討ちなさい。'),
('JPN', '申命记', 5, 20, 14, 'しかし、女、子ども、家畜、また町の中にあるすべてのもの、そのすべての略奪物は戦利品として取ってよい。あなたの神、主があなたに与えられた、敵からの略奪物をあなたは自由にすることができる。'),
('JPN', '申命记', 5, 20, 15, 'あなたから非常に遠く離れている町々に対しては、すべてこのようにしなければならない。次に示す国々の町は違う。'),
('JPN', '申命记', 5, 20, 16, 'あなたの神、主が相続地として与えようとしておられる次の民の町々では、息のある者を一人も生かしておいてはならない。'),
('JPN', '申命记', 5, 20, 17, 'すなわち、ヒッタイト人、アモリ人、カナン人、ペリジ人、ヒビ人、エブス人は、あなたの神、主が命じられたとおり必ず聖絶しなければならない。'),
('JPN', '申命记', 5, 20, 18, 'それは、彼らが、その神々に行っていたすべての忌み嫌うべきことをするようにあなたがたに教え、あなたがたが、あなたがたの神、主の前に罪ある者とならないようにするためである。'),
('JPN', '申命记', 5, 20, 19, 'あなたが長い間、ある町を包囲して、これを攻め取ろうとするとき、斧を振るって、そこの木を切り倒してはならない。その木から食べるのはよいが、切り倒してはならない。まさか野の木が、あなたの前から逃げ出して包囲の中に入ってしまう人間でもあるまい。'),
('JPN', '申命记', 5, 20, 20, 'ただ、実を結ばないと分かっている木だけは切り倒してもよい。それを切り倒して、あなたと戦っている町が陥落するまで、その町に対してそれで砦を築いてもよい。'),
('JPN', '申命记', 5, 21, 1, 'あなたの神、主があなたに与えて所有させようとしておられる地で、刺し殺された者が野に倒れているのが見つかり、だれが殺したのか分からない場合、'),
('JPN', '申命记', 5, 21, 2, 'あなたの長老たちとさばき人たちは出て行って、刺し殺された者から周りの町々への距離を測りなさい。'),
('JPN', '申命记', 5, 21, 3, 'そして、刺し殺された者に最も近い町が分かれば、その町の長老たちは、まだ使役されたことも、くびきを負って引いたこともない雌の子牛を取りなさい。'),
('JPN', '申命记', 5, 21, 4, 'その町の長老たちはその雌の子牛を、まだ耕されたことも種を蒔かれたこともない、絶えず流れる谷川へ連れて下り、その谷で雌の子牛の首を折りなさい。'),
('JPN', '申命记', 5, 21, 5, 'それから、レビの子らである祭司たちが進み出なさい。あなたの神、主が、ご自分に仕えさせ、また主の御名によって祝福を宣言するために選ばれた者は彼らであり、いかなる争いも、いかなる傷害事件も彼らの判決によるからである。'),
('JPN', '申命记', 5, 21, 6, '刺し殺された者に最も近いその町の長老たちはみな、谷で首を折られた雌の子牛の上で手を洗い、'),
('JPN', '申命记', 5, 21, 7, '証言して言いなさい。「私たちの手はこの血を流しておらず、私たちの目はそれを見ていない。'),
('JPN', '申命记', 5, 21, 8, '主よ、あなたが贖い出された御民イスラエルをお赦しください。咎のない者の血を流す罪を、御民イスラエルのうちに負わせないでください。」こうして彼らは流血の咎を赦される。'),
('JPN', '申命记', 5, 21, 9, 'このようにして、あなたは、主の目にかなうことを行うとき、咎のない者の血を流す罪をあなたがたの中から除き去ることができる。'),
('JPN', '申命记', 5, 21, 10, 'あなたが敵との戦いに出て行き、あなたの神、主がその敵をあなたの手に渡し、あなたがそれを捕虜として捕らえたとき、'),
('JPN', '申命记', 5, 21, 11, 'その捕虜の中に姿の美しい女を見て、恋い慕い、自分の妻としようとする場合には、'),
('JPN', '申命记', 5, 21, 12, '彼女をあなたの家の中に連れて行きなさい。彼女は頭を剃り、爪を切り、'),
('JPN', '申命记', 5, 21, 13, '捕虜の衣を脱ぎ、あなたの家にいて、自分の父と母のため一か月の間、泣き悲しまなければならない。その後、あなたは彼女のところに入り、彼女の夫となり、彼女はあなたの妻となる。'),
('JPN', '申命记', 5, 21, 14, 'もしあなたが彼女を気に入らなくなったなら、彼女を自由に去らせなさい。決して金で売ってはならない。あなたはすでに彼女を意のままにしたのであるから、彼女を奴隷として扱ってはならない。'),
('JPN', '申命记', 5, 21, 15, 'ある人が二人の妻を持ち、一人は愛され、もう一人は嫌われていて、愛されている者も嫌われている者もその人に男の子を産み、長子が、嫌われている妻の子である場合、'),
('JPN', '申命记', 5, 21, 16, 'その人が息子たちに財産を受け継がせる日に、長子である、その嫌われている妻の子を差し置いて、愛されている妻の子を長子として扱うことはできない。'),
('JPN', '申命记', 5, 21, 17, '嫌われている妻の子を長子として認め、自分の全財産の中から二倍の取り分を彼に与えなければならない。その子は父の力の初穂であるから、長子の権利は彼のものである。'),
('JPN', '申命记', 5, 21, 18, 'ある人に強情で逆らう子がいて、父の言うことも母の言うことも聞かず、父母に懲らしめられても聞こうとしない場合、'),
('JPN', '申命记', 5, 21, 19, 'その父と母はその子を捕らえ、町の門にいる町の長老たちのところへ連れ出し、'),
('JPN', '申命记', 5, 21, 20, '町の長老たちに、「私たちのこの息子は強情で逆らいます。私たちの言うことに聞き従いません。放蕩で大酒飲みです」と言いなさい。'),
('JPN', '申命记', 5, 21, 21, '町の人はみな彼を石で打ちなさい。彼は死ななければならない。あなたがたの中からその悪い者を除き去りなさい。イスラエルはみな聞いて恐れるであろう。'),
('JPN', '申命记', 5, 21, 22, 'ある人に死刑に当たる罪過があって処刑され、あなたが彼を木にかける場合、'),
('JPN', '申命记', 5, 21, 23, 'その死体を次の日まで木に残しておいてはならない。その日のうちに必ず埋葬しなければならない。木にかけられた者は神にのろわれた者だからである。あなたの神、主が相続地としてあなたに与えようとしておられる土地を汚してはならない。'),
('JPN', '申命记', 5, 22, 1, 'あなたの同族の者の牛または羊が迷っているのを見て、見ぬふりをしていてはならない。あなたの同族の者のところに、それを必ず連れ戻さなければならない。'),
('JPN', '申命记', 5, 22, 2, 'もしその同族の者が近くの者ではなく、あなたがその人を知らないなら、それを自分の家に連れて来て、同族の者が捜しに来るまであなたのところに置き、それから彼に返しなさい。'),
('JPN', '申命记', 5, 22, 3, '彼のろばについても同じようにしなければならない。彼の衣についても同じようにしなければならない。すべてあなたの同族の者がなくした物をあなたが見つけたなら、同じようにしなければならない。見ぬふりをしていることはできない。'),
('JPN', '申命记', 5, 22, 4, 'あなたの同族の者のろば、または牛が道で倒れているのを見て、見ぬふりをしてはならない。必ず、彼と一緒にそれを起こしてやらなければならない。'),
('JPN', '申命记', 5, 22, 5, '女は男の衣装を身に着けてはならない。また男は女の衣服を着てはならない。このようなことをする者はみな、あなたの神、主が忌み嫌われる。'),
('JPN', '申命记', 5, 22, 6, 'たまたま道で木の上か地面に鳥の巣を見つけ、それにひなか卵があり、母鳥がひなか卵を抱いている場合、その母鳥を子と一緒に捕ってはならない。'),
('JPN', '申命记', 5, 22, 7, '必ず母鳥を去らせて、子を捕らなければならない。それは、あなたが幸せになり、あなたの日々が長く続くようになるためである。'),
('JPN', '申命记', 5, 22, 8, '新しい家を建てるときは屋上に手すりを付けなさい。だれかがそこから落ちても、あなたの家が血の責任を負うことのないようにするためである。'),
('JPN', '申命记', 5, 22, 9, 'ぶどう畑に二種類の種を蒔いてはならない。あなたが蒔いた種と、ぶどう畑の収穫全体とが、聖なるものとして取り分けられてしまうことのないように。'),
('JPN', '申命记', 5, 22, 10, '牛とろばとを組にして耕してはならない。'),
('JPN', '申命记', 5, 22, 11, '羊毛と亜麻糸を混ぜて織った衣服を着てはならない。'),
('JPN', '申命记', 5, 22, 12, '身にまとう衣の四隅に房を作らなければならない。'),
('JPN', '申命记', 5, 22, 13, '人が妻を迎えて彼女のところに入ったが、彼女を嫌い、'),
('JPN', '申命记', 5, 22, 14, '口実を設けて、「私はこの女を妻として近づいたが、処女のしるしを見なかった」と言って汚名を着せる場合、'),
('JPN', '申命记', 5, 22, 15, 'その娘の父と母はその娘の処女のしるしを取り、門のところにいる町の長老たちのもとにそれを持って行きなさい。'),
('JPN', '申命记', 5, 22, 16, 'その娘の父は長老たちに、「私は娘をこの男に妻として与えましたが、彼は娘を嫌いました。'),
('JPN', '申命记', 5, 22, 17, 'ご覧ください。彼は口実を設けて、『あなたの娘には処女のしるしを見なかった』と言いました。しかし、これが私の娘の処女のしるしです」と言って、町の長老たちの前にその衣を広げなさい。'),
('JPN', '申命记', 5, 22, 18, 'その町の長老たちはこの男を捕らえて懲らしめ、'),
('JPN', '申命记', 5, 22, 19, '銀百シェケルの罰金を科し、その娘の父に与えなければならない。彼がイスラエルの一人の処女に汚名を着せたからである。彼女はその男の妻としてとどまり、その男は一生、彼女を離縁することはできない。'),
('JPN', '申命记', 5, 22, 20, 'しかし、もしこのことが真実であり、その娘に処女のしるしが見つからないなら、'),
('JPN', '申命记', 5, 22, 21, 'その娘を父の家の入り口のところに連れ出し、町の人々は彼女に石を投げ、彼女を殺さなければならない。彼女が父の家で淫行をして、イスラエルの中で恥辱となることをしたからである。あなたがたの中からその悪い者を除き去りなさい。'),
('JPN', '申命记', 5, 22, 22, '夫のある女と寝ている男が見つかった場合は、その女と寝ていた男もその女も、二人とも死ななければならない。こうして、あなたはイスラエルの中からその悪い者を除き去りなさい。'),
('JPN', '申命记', 5, 22, 23, 'ある男と婚約中の処女の娘がいて、ほかの男が町で彼女を見かけて一緒に寝た場合、'),
('JPN', '申命记', 5, 22, 24, 'あなたがたはその二人をその町の門のところに連れ出し、石を投げて殺さなければならない。その女は町の中にいながら叫ばなかったからであり、その男は隣人の妻を辱めたからである。こうして、あなたがたの中からその悪い者を除き去りなさい。'),
('JPN', '申命记', 5, 22, 25, 'もしある男が野で婚約中の娘を見かけ、彼女を捕まえて一緒に寝たなら、彼女と寝たその男だけが死ななければならない。'),
('JPN', '申命记', 5, 22, 26, 'その娘には何もしてはならない。その娘には死刑に当たる罪過はない。この場合は、ある人が隣人に襲いかかり、いのちを奪ったのと同じである。'),
('JPN', '申命记', 5, 22, 27, 'この男は野で彼女を見かけたのであり、婚約中の娘は叫んだが、救う者がいなかったのであるから。'),
('JPN', '申命记', 5, 22, 28, 'ある男が、まだ婚約していない処女の娘を見かけ、彼女を捕らえて一緒に寝ているのを見つけられた場合、'),
('JPN', '申命记', 5, 22, 29, '娘と寝た男は娘の父に銀五十シェケルを渡さなければならない。彼女はこの男の妻となる。彼女を辱めたのであるから、彼は一生この女を離縁することはできない。'),
('JPN', '申命记', 5, 22, 30, 'だれも、父の妻を妻にして自分の父の恥をさらしてはならない。'),
('JPN', '申命记', 5, 23, 1, '睾丸のつぶれた者、陰茎を切り取られた者は主の集会に加わってはならない。'),
('JPN', '申命记', 5, 23, 2, '不倫の子は主の集会に加わってはならない。その十代目の子孫さえ主の集会に加わることはできない。'),
('JPN', '申命记', 5, 23, 3, 'アンモン人とモアブ人は主の集会に加わってはならない。その十代目の子孫さえ、決して主の集会に加わることはできない。'),
('JPN', '申命记', 5, 23, 4, 'これは、あなたがたがエジプトから出て来た道中で、彼らがパンと水をもってあなたがたを迎えることをせず、アラム・ナハライムのペトルからベオルの子バラムを雇って、あなたに呪いをもたらそうとしたからである。'),
('JPN', '申命记', 5, 23, 5, 'しかし、あなたの神、主はバラムに耳を貸そうとはせず、かえってあなたの神、主はあなたのために呪いを祝福に変えられた。あなたの神、主はあなたを愛しておられたからである。'),
('JPN', '申命记', 5, 23, 6, 'あなたは一生、彼らの平安も彼らの幸せも決して求めてはならない。'),
('JPN', '申命记', 5, 23, 7, 'あなたはエドム人を忌み嫌ってはならない。これはあなたの兄弟だからである。エジプト人を忌み嫌ってはならない。あなたはその地で寄留者だったからである。'),
('JPN', '申命记', 5, 23, 8, '彼らに生まれた子どもたちは、三代目には主の集会に加わることができる。'),
('JPN', '申命记', 5, 23, 9, 'あなたが敵に向かって陣を敷くときには、すべての汚れたことから身を守らなければならない。'),
('JPN', '申命记', 5, 23, 10, 'もしあなたのうちに、夜、精を漏らして身を汚した者があれば、その人は陣営の外に出なければならない。陣営の中に入ってはならない。'),
('JPN', '申命记', 5, 23, 11, '夕暮れ近くになったら水を浴び、日没とともに陣営の中に戻ることができる。'),
('JPN', '申命记', 5, 23, 12, 'また、陣営の外に一つの場所を設け、そこへ出て行って用をたすようにしなければならない。'),
('JPN', '申命记', 5, 23, 13, '武器とともに小さな鍬を持ち、外でかがむときはそれで穴を掘り、用をたしてから排泄物をおおわなければならない。'),
('JPN', '申命记', 5, 23, 14, 'あなたの神、主が、あなたを救い出し、敵をあなたに渡すために、あなたの陣営の中を歩まれるからである。こうして、あなたの陣営は聖でなければならない。主があなたの中で恥ずべきものを見て、あなたから離れ去ることのないようにしなさい。'),
('JPN', '申命记', 5, 23, 15, '主人のもとからあなたのところに逃れて来た奴隷を、その主人に引き渡してはならない。'),
('JPN', '申命记', 5, 23, 16, 'あなたがたのうちに、あなたの町囲みの中のどこでも彼が好むままに選んだ場所に、あなたとともに住まわせなければならない。彼を虐げてはならない。'),
('JPN', '申命记', 5, 23, 17, 'イスラエルの女子は神殿娼婦になってはならない。イスラエルの男子は神殿男娼になってはならない。'),
('JPN', '申命记', 5, 23, 18, 'いかなる誓願のためであっても、遊女の儲けや犬の稼ぎをあなたの神、主の家に携えて行ってはならない。これはどちらも、あなたの神、主が忌み嫌われるからである。'),
('JPN', '申命记', 5, 23, 19, '金銭の利息であれ食物の利息であれ、すべて利息をつけて貸すことのできるものの利息を、あなたの同胞から取ってはならない。'),
('JPN', '申命记', 5, 23, 20, '異国人からは利息を取ってもよいが、あなたの同胞からは利息を取ってはならない。それは、あなたが入って行って所有しようとしている地で、あなたの神、主があなたのすべての手のわざを祝福されるためである。'),
('JPN', '申命记', 5, 23, 21, 'あなたの神、主に誓願をするとき、それを遅れずに果たさなければならない。なぜなら、あなたの神、主は必ずあなたからそれを要求し、こうしてあなたが罪責を負うことになるからである。'),
('JPN', '申命记', 5, 23, 22, '誓願をやめる場合、あなたに罪責は生じない。'),
('JPN', '申命记', 5, 23, 23, 'あなたの唇から出たことを守り、あなたの口で約束して、自分から進んであなたの神、主に誓願したとおりに行わなければならない。'),
('JPN', '申命记', 5, 23, 24, '隣人のぶどう畑に入ったとき、あなたは思う存分、満ち足りるまでぶどうを食べてもよいが、あなたのかごに入れてはならない。'),
('JPN', '申命记', 5, 23, 25, '隣人の麦畑の中に入ったとき、あなたは穂を手で摘んでもよい。しかし、隣人の麦畑で鎌を使ってはならない。'),
('JPN', '申命记', 5, 24, 1, '人が妻をめとり夫となった後で、もし、妻に何か恥ずべきことを見つけたために気に入らなくなり、離縁状を書いてその女の手に渡し、彼女を家から去らせ、'),
('JPN', '申命记', 5, 24, 2, 'そして彼女が家を出て行って、ほかの人の妻となり、'),
('JPN', '申命记', 5, 24, 3, 'さらに次の夫も彼女を嫌い、離縁状を書いて彼女の手に渡し、彼女を家から去らせた場合、あるいは、彼女を妻とした、あとの夫が死んだ場合には、'),
('JPN', '申命记', 5, 24, 4, '彼女を去らせた初めの夫は、彼女が汚された後に再び彼女を自分の妻とすることはできない。それは、主の前に忌み嫌うべきことだからである。あなたの神、主が相続地としてあなたに与えようとしておられる地に、罪をもたらしてはならない。'),
('JPN', '申命记', 5, 24, 5, '人が新妻を迎えたときは、その人を戦に出してはならない。何の義務も負わせてはならない。彼は一年の間、自分の家のために自由の身になって、迎えた妻を喜ばせなければならない。'),
('JPN', '申命记', 5, 24, 6, 'ひき臼、あるいはその上石を質に取ってはならない。いのちそのものを質に取ることになるからである。'),
('JPN', '申命记', 5, 24, 7, '人がその同胞、イスラエルの子らのうちの一人を誘拐し、奴隷として扱うか売りとばしたことが見つかった場合、誘拐した者は死ななければならない。こうして、あなたの中からその悪い者を除き去りなさい。'),
('JPN', '申命记', 5, 24, 8, 'ツァラアトに冒された患部には気をつけて、すべてレビ人の祭司が教えるとおりに、よく守り行わなければならない。私が彼らに命じたとおりに守り行わなければならない。'),
('JPN', '申命记', 5, 24, 9, 'あなたがたがエジプトから出て来たとき、その道中で、あなたの神、主がミリアムにされたことを思い出しなさい。'),
('JPN', '申命记', 5, 24, 10, '隣人に何かを貸すとき、担保を取りにその家に入ってはならない。'),
('JPN', '申命记', 5, 24, 11, 'あなたは外に立っていなければならない。あなたが貸そうとするその人が、外にいるあなたのところに担保を持って出て来なければならない。'),
('JPN', '申命记', 5, 24, 12, 'もしその人が貧しい人なら、その担保を取ったままで寝てはならない。'),
('JPN', '申命记', 5, 24, 13, '日没のころには、その担保を必ず返さなければならない。彼は自分の上着を着て寝て、あなたを祝福するであろう。また、そのことはあなたの神、主の前であなたの義となる。'),
('JPN', '申命记', 5, 24, 14, '貧しく困窮している雇い人は、あなたの同胞でも、あなたの地の、あなたの町囲みの中にいる寄留者でも虐げてはならない。'),
('JPN', '申命记', 5, 24, 15, 'その人の賃金はその日のうちに、日没前に支払わなければならない。彼は困窮し、それを当てにしているのだから。彼があなたのことを主に訴えて、あなたが罪責を負うことのないようにしなさい。'),
('JPN', '申命记', 5, 24, 16, '父が子のために殺されてはならない。子が父のために殺されてはならない。人が殺されるのは自分の罪過のゆえでなければならない。'),
('JPN', '申命记', 5, 24, 17, '寄留者や孤児の権利を侵してはならない。やもめの衣服を質に取ってはならない。'),
('JPN', '申命记', 5, 24, 18, 'あなたがエジプトで奴隷であったこと、そしてあなたの神、主が、そこからあなたを贖い出されたことを覚えていなければならない。それゆえ私はあなたに、このことをせよと命じる。'),
('JPN', '申命记', 5, 24, 19, 'あなたが畑で穀物の刈り入れをして、束の一つを畑に置き忘れたときは、それを取りに戻ってはならない。それは寄留者や孤児、やもめのものとしなければならない。あなたの神、主があなたのすべての手のわざを祝福してくださるためである。'),
('JPN', '申命记', 5, 24, 20, 'あなたがオリーブの実を打ち落とすときは、後になってまた枝を打ってはならない。それは寄留者や孤児、やもめのものとしなければならない。'),
('JPN', '申命记', 5, 24, 21, 'ぶどう畑のぶどうを収穫するときは、後になってまたそれを摘み取ってはならない。それは寄留者や孤児、やもめのものとしなければならない。'),
('JPN', '申命记', 5, 24, 22, 'あなたは、自分がエジプトの地で奴隷であったことを覚えていなければならない。それゆえ私はあなたに、このことをせよと命じる。'),
('JPN', '申命记', 5, 25, 1, '人と人との間で争いがあり、その人たちが裁判に出頭して、正しいほうを正しいとし、悪いほうを悪いとする判定がなされたとき、'),
('JPN', '申命记', 5, 25, 2, 'もしその悪い者がむち打ちにすべき者なら、さばき人は彼を伏させ、自分の前で、その邪悪さに応じた数だけ打たなければならない。'),
('JPN', '申命记', 5, 25, 3, '四十までは彼をむち打ってよいが、それ以上はいけない。それ以上多くむち打たれれば、あなたの同胞はあなたの目の前で卑しめられることになる。'),
('JPN', '申命记', 5, 25, 4, '脱穀をしている牛に口籠をはめてはならない。'),
('JPN', '申命记', 5, 25, 5, '兄弟が一緒に住んでいて、そのうちの一人が死に、彼に息子がいない場合、死んだ者の妻は家族以外のほかの男に嫁いではならない。その夫の兄弟がその女のところに入り、これを妻とし、夫の兄弟としての義務を果たさなければならない。'),
('JPN', '申命记', 5, 25, 6, 'そして彼女が産む最初の男子が、死んだ兄弟の名を継ぎ、その名がイスラエルから消し去られないようにしなければならない。'),
('JPN', '申命记', 5, 25, 7, 'しかし、もしその人が自分の兄弟の妻を妻としたくないなら、その兄弟の妻は、町の門の長老たちのところに行って言わなければならない。「私の夫の兄弟は、自分の兄弟のためにその名をイスラエルのうちに残そうとはせず、夫の兄弟としての義務を私に果たそうとしません。」'),
('JPN', '申命记', 5, 25, 8, '町の長老たちは彼を呼び寄せ、話さなければならない。もし彼が「私は彼女を妻としたくない」と言い張るなら、'),
('JPN', '申命记', 5, 25, 9, '彼の兄弟の妻は、長老たちの目の前で彼に近寄り、その足から履き物を脱がせ、その顔に唾して、彼に答えて言わなければならない。「兄弟の家を建てない男はこのようにされる。」'),
('JPN', '申命记', 5, 25, 10, '彼の名はイスラエルの中で、「履き物を脱がされた者の家」と呼ばれる。'),
('JPN', '申命记', 5, 25, 11, '二人の者が互いに争っているとき、一方の者の妻が近づき、自分の夫を打つ者の手から救い出そうとして手を伸ばし、相手の隠しどころをつかんだなら、'),
('JPN', '申命记', 5, 25, 12, 'その女の手を切り落としなさい。あわれみをかけてはならない。'),
('JPN', '申命记', 5, 25, 13, 'あなたには、袋に大小異なる重り石があってはならない。'),
('JPN', '申命记', 5, 25, 14, 'あなたには、家に大小異なる升があってはならない。'),
('JPN', '申命记', 5, 25, 15, 'あなたには、完全で正しい重り石と、完全で正しい升がなければならない。あなたの神、主があなたに与えようとしておられるその土地で、あなたの日々が長く続くようにするためである。'),
('JPN', '申命记', 5, 25, 16, 'こう言うのは、このようなことをして不正を行う者すべてを、あなたの神、主が忌み嫌われるからである。'),
('JPN', '申命记', 5, 25, 17, '覚えていなさい。あなたがたがエジプトから出て来たとき、その道中でアマレクがあなたにしたことを。'),
('JPN', '申命记', 5, 25, 18, '彼らは神を恐れることなく、あなたが疲れて弱っているときに、道であなたに会い、あなたのうしろの落伍者をすべて切り倒したのである。'),
('JPN', '申命记', 5, 25, 19, 'あなたの神、主が相続地としてあなたに与えて所有させようとしておられる地で、あなたの神、主が周囲のすべての敵からあなたを守って、安息を与えられるようになったときには、あなたはアマレクの記憶を天の下から消し去らなければならない。このことを忘れてはならない。'),
('JPN', '申命记', 5, 26, 1, 'あなたの神、主が相続地としてあなたに与えようとしておられる地に入って行き、それを占領し、そこに住むようになったときは、'),
('JPN', '申命记', 5, 26, 2, 'あなたの神、主が与えようとしておられる地から収穫する、大地のすべての実りの初物の一部を取って、かごに入れ、あなたの神、主が御名を住まわせるために選ばれる場所へ行かなければならない。'),
('JPN', '申命记', 5, 26, 3, 'そして、そのとき任務についている祭司のもとに行って、「今日、あなたの神、主に報告いたします。私は主が私たちに与えると父祖たちに誓われた地に入りました」と言いなさい。'),
('JPN', '申命记', 5, 26, 4, '祭司があなたの手からそのかごを受け取り、あなたの神、主の祭壇の前に置いたら、'),
('JPN', '申命记', 5, 26, 5, 'あなたは、あなたの神、主の前で次のように告白しなさい。「私の父はさすらいのアラム人でしたが、わずかな人数を連れてエジプトに下り、そこに寄留しました。しかしそこで、強くて数の多い、大いなる国民になりました。'),
('JPN', '申命记', 5, 26, 6, 'しかし、エジプト人は私たちを虐待し、苦しめ、私たちに激しい労働を課しました。'),
('JPN', '申命记', 5, 26, 7, '私たちが私たちの父祖の神、主に叫ぶと、主は私たちの声を聞き、私たちの苦しみと労苦と虐げられている有様をご覧になりました。'),
('JPN', '申命记', 5, 26, 8, 'そこで、主は力強い御手と伸ばされた御腕によって、恐ろしい力と、しるしと不思議をもって私たちをエジプトから導き出し、'),
('JPN', '申命记', 5, 26, 9, 'この場所に導き入れ、乳と蜜の流れる地、この地を私たちに与えてくださいました。'),
('JPN', '申命记', 5, 26, 10, '今ここに私は、主よ、あなたが私に与えてくださった大地の実りの初物を持って参りました。」あなたは、あなたの神、主の前にそれを供え、あなたの神、主の前で礼拝しなければならない。'),
('JPN', '申命记', 5, 26, 11, 'あなたの神、主があなたとあなたの家に与えられたすべての恵みを、あなたはレビ人および、あなたがたのうちの寄留者とともに喜びなさい。'),
('JPN', '申命记', 5, 26, 12, '第三年、十分の一の年にあなたの収穫の十分の一をすべて納め終え、これをレビ人、寄留者、孤児、やもめに与えて、彼らがあなたの町囲みの中で食べて満ち足りたとき、'),
('JPN', '申命记', 5, 26, 13, 'あなたは、あなたの神、主の前で言いなさい。「あなたが私に下された命令のとおり、私は聖なるささげ物すべてを家から取り分け、それをレビ人、寄留者、孤児、やもめに与えました。私はあなたの命令を一つも破らず、またそれらを忘れませんでした。'),
('JPN', '申命记', 5, 26, 14, 'その一部でも、喪中に食べたり、また汚れているときに取り分けたりしませんでした。また、その一部でも死者に供えたこともありません。私は、私の神、主の御声に聞き従い、すべてあなたが私に命じられたとおりにいたしました。'),
('JPN', '申命记', 5, 26, 15, 'あなたの聖なる住まいの天から見下ろして、御民イスラエルと、あなたが私たちの父祖たちに誓われたとおり私たちに下さった土地、乳と蜜の流れる地とを祝福してください。」'),
('JPN', '申命记', 5, 26, 16, '今日、あなたの神、主は、これらの掟と定めを行うように、あなたに命じておられる。あなたは心を尽くし、いのちを尽くして、それを守り行いなさい。'),
('JPN', '申命记', 5, 26, 17, 'あなたは今日、この主をあなたの神とし、主の道に歩み、主の掟と命令と定めを守り、御声に聞き従うと誓約した。'),
('JPN', '申命记', 5, 26, 18, '今日、主は、あなたに約束したとおり、あなたが主のすべての命令を守り主の宝の民となること、'),
('JPN', '申命记', 5, 26, 19, 'あなたを、主が造られたすべての国々の上に高く上げて栄誉と名声と栄えとし、約束のとおり、あなたが、あなたの神、主の聖なる民となることを誓約されたのである。'),
('JPN', '申命记', 5, 27, 1, 'モーセとイスラエルの長老たちは、民にこう命じた。「私が今日あなたがたに命じるすべての命令を守りなさい。'),
('JPN', '申命记', 5, 27, 2, 'あなたがたがヨルダン川を渡り、あなたの神、主が与えようとしておられる地に入る日には、大きな石を立て、それらに石灰を塗りなさい。'),
('JPN', '申命记', 5, 27, 3, '渡ったら、それらの上に、このみおしえのすべてのことばを書き記しなさい。それは、あなたの父祖の神、主が約束されたとおり、あなたの神、主があなたに与えようとしておられる地、乳と蜜の流れる地にあなたが入るためである。'),
('JPN', '申命记', 5, 27, 4, 'あなたがたがヨルダン川を渡ったら、私が今日あなたがたに命じるこれらの石をエバル山に立て、それに石灰を塗りなさい。'),
('JPN', '申命记', 5, 27, 5, 'そこに、あなたの神、主のために祭壇を、石の祭壇を築きなさい。それには鉄の道具を当ててはならない。'),
('JPN', '申命记', 5, 27, 6, '自然のままの石で、あなたの神、主の祭壇を築かなければならない。その上で、あなたの神、主に全焼のささげ物を献げなさい。'),
('JPN', '申命记', 5, 27, 7, 'またそこで交わりのいけにえを献げて、それを食べ、あなたの神、主の前で喜び楽しみなさい。'),
('JPN', '申命记', 5, 27, 8, 'それらの石の上に、このみおしえのことばすべてを、よく確認して書き記しなさい。」'),
('JPN', '申命记', 5, 27, 9, 'それから、モーセとレビ人の祭司たちはイスラエル全体に告げた。「イスラエルよ、静まって聞きなさい。今日あなたは、あなたの神、主の民となった。'),
('JPN', '申命记', 5, 27, 10, 'あなたの神、主の御声に聞き従い、私が今日あなたに命じる主の命令と掟を行いなさい。」'),
('JPN', '申命记', 5, 27, 11, 'その日モーセは民に命じた。'),
('JPN', '申命记', 5, 27, 12, 'あなたがたがヨルダン川を渡ったとき、次の者たちは、民を祝福するためにゲリジム山に立たなければならない。シメオン、レビ、ユダ、イッサカル、ヨセフ、ベニヤミン。'),
('JPN', '申命记', 5, 27, 13, 'また次の者たちは、のろいのためにエバル山に立たなければならない。ルベン、ガド、アシェル、ゼブルン、ダン、ナフタリ。'),
('JPN', '申命记', 5, 27, 14, 'レビ人は、イスラエルのすべての人に大声で宣言しなければならない。'),
('JPN', '申命记', 5, 27, 15, '「職人の手のわざである、主が忌み嫌われる彫像や鋳像を造り、これをひそかに安置する者はのろわれる。」民はみな答えて、アーメンと言いなさい。'),
('JPN', '申命记', 5, 27, 16, '「自分の父や母を軽んじる者はのろわれる。」民はみな、アーメンと言いなさい。'),
('JPN', '申命记', 5, 27, 17, '「隣人との地境を移す者はのろわれる。」民はみな、アーメンと言いなさい。'),
('JPN', '申命记', 5, 27, 18, '「目の見えない人を道に迷わせる者はのろわれる。」民はみな、アーメンと言いなさい。'),
('JPN', '申命记', 5, 27, 19, '「寄留者、孤児、やもめのさばきを曲げる者はのろわれる。」民はみな、アーメンと言いなさい。'),
('JPN', '申命记', 5, 27, 20, '「父の妻と寝る者は、自分の父の恥をさらすのであるから、のろわれる。」民はみな、アーメンと言いなさい。'),
('JPN', '申命记', 5, 27, 21, '「どのような動物であれ、それと寝る者はのろわれる。」民はみな、アーメンと言いなさい。'),
('JPN', '申命记', 5, 27, 22, '「父の娘であれ母の娘であれ、自分の姉妹と寝る者はのろわれる。」民はみな、アーメンと言いなさい。'),
('JPN', '申命记', 5, 27, 23, '「自分の妻の母と寝る者はのろわれる。」民はみな、アーメンと言いなさい。'),
('JPN', '申命记', 5, 27, 24, '「ひそかに隣人を打ち殺す者はのろわれる。」民はみな、アーメンと言いなさい。'),
('JPN', '申命记', 5, 27, 25, '「賄賂を受け取り、人を打ち殺して、咎のない者の血を流す者はのろわれる。」民はみな、アーメンと言いなさい。'),
('JPN', '申命记', 5, 27, 26, '「このみおしえのことばを守ろうとせず、これを実行しない者はのろわれる。」民はみな、アーメンと言いなさい。'),
('JPN', '申命记', 5, 28, 1, 'もし、あなたが、あなたの神、主の御声に確かに聞き従い、私が今日あなたに命じる主のすべての命令を守り行うなら、あなたの神、主は、地のすべての国々の上にあなたを高く上げられる。'),
('JPN', '申命记', 5, 28, 2, 'あなたが、あなたの神、主の御声に聞き従うので、次のすべての祝福があなたに臨み、あなたについて行く。'),
('JPN', '申命记', 5, 28, 3, 'あなたは町にあっても祝福され、野にあっても祝福される。'),
('JPN', '申命记', 5, 28, 4, 'あなたの胎の実も大地の実りも、家畜が産むもの、群れの中の子牛も群れの中の子羊も祝福される。'),
('JPN', '申命记', 5, 28, 5, 'あなたのかごも、こね鉢も祝福される。'),
('JPN', '申命记', 5, 28, 6, 'あなたは入るときにも祝福され、出て行くときにも祝福される。'),
('JPN', '申命记', 5, 28, 7, '主は、あなたに向かい立つ敵どもをあなたの前で敗走させる。彼らは一つの道からあなたを攻めて来るが、あなたの前で七つの道に逃げ去る。'),
('JPN', '申命记', 5, 28, 8, '主はあなたのために、あなたの穀物倉とあなたのすべての手のわざが祝福されるように命じられる。あなたの神、主があなたに与えようとしておられる地で、あなたを祝福される。'),
('JPN', '申命记', 5, 28, 9, 'あなたが、あなたの神、主の命令を守り主の道を歩むなら、主はあなたに誓われたとおり、あなたをご自分の聖なる民として立ててくださる。'),
('JPN', '申命记', 5, 28, 10, '地上のあらゆる民はあなたに主の名がつけられているのを見て、あなたを恐れるであろう。'),
('JPN', '申命记', 5, 28, 11, '主があなたに与えるとあなたの父祖たちに誓われたその地で、主はあなたの胎の実、家畜が産むもの、大地の実りを豊かに恵んでくださる。'),
('JPN', '申命记', 5, 28, 12, '主はその恵みの倉、天を開き、時にかなって雨をあなたの地に与え、あなたのすべての手のわざを祝福される。それで、あなたは多くの国々に貸すが、借りることはない。'),
('JPN', '申命记', 5, 28, 13, '私が今日あなたに命じる、あなたの神、主の命令に聞き従い、守り行うなら、主はあなたをかしらとし、尾とはされない。あなたはただ上になり、下になることはない。'),
('JPN', '申命记', 5, 28, 14, '私が今日あなたがたに命じるこのすべてのことばから右や左に外れ、ほかの神々に従い、それに仕えてはならない。'),
('JPN', '申命记', 5, 28, 15, 'しかし、もしあなたの神、主の御声に聞き従わず、私が今日あなたに命じる、主のすべての命令と掟を守り行わないなら、次のすべてののろいがあなたに臨み、あなたをとらえる。'),
('JPN', '申命记', 5, 28, 16, 'あなたは町にあってものろわれ、野にあってものろわれる。'),
('JPN', '申命记', 5, 28, 17, 'あなたのかごも、こね鉢ものろわれる。'),
('JPN', '申命记', 5, 28, 18, 'あなたの胎の実も大地の実りも、群れの中の子牛も群れの中の子羊ものろわれる。'),
('JPN', '申命记', 5, 28, 19, 'あなたは入るときにものろわれ、出て行くときにものろわれる。'),
('JPN', '申命记', 5, 28, 20, '主は、あなたのなすすべての手のわざに、のろいと混乱と懲らしめを送り、ついにあなたは根絶やしにされて、たちまちにして滅びる。これは、わたしを捨てたあなたの行いが悪いからである。'),
('JPN', '申命记', 5, 28, 21, '主は疫病をあなたの身にまといつかせ、ついには、あなたが入って行って所有しようとしている地から、あなたを絶ち滅ぼす。'),
('JPN', '申命记', 5, 28, 22, '主は肺病、熱病、高熱病、悪性熱病、また干ばつ、立ち枯れ、黒穂病であなたを打つ。これらのものは、あなたが滅びるまで、あなたを追いかける。'),
('JPN', '申命记', 5, 28, 23, 'あなたの頭上の天は青銅となり、あなたの下の地は鉄となる。'),
('JPN', '申命记', 5, 28, 24, '主はあなたの地に降る雨をほこりに変え、天から砂ぼこりが降って来て、ついにはあなたは根絶やしにされる。'),
('JPN', '申命记', 5, 28, 25, '主はあなたを敵の前で敗走させる。あなたは一つの道から攻めて行くが、敵の前で七つの道に逃げて行く。あなたのことは地上のすべての王国にとっておののきのもととなる。'),
('JPN', '申命记', 5, 28, 26, 'あなたの死体は空のすべての鳥と地の獣の餌食となり、しかも、これを追い払う者もいない。'),
('JPN', '申命记', 5, 28, 27, '主はエジプトの腫物、腫れもの、湿疹、疥癬をもってあなたを打ち、あなたは癒やされることがない。'),
('JPN', '申命记', 5, 28, 28, '主はあなたを打って錯乱させ、盲目にし、心を混乱させる。'),
('JPN', '申命记', 5, 28, 29, 'あなたは目の見えない人が暗闇で手さぐりするように、真昼に手さぐりするようになる。あなたは何をしても成功せず、いつも虐げられ、略奪されるだけである。あなたを救う者はいない。'),
('JPN', '申命记', 5, 28, 30, 'あなたが女と婚約しても、ほかの男が彼女と寝る。家を建てても、その中には住めない。ぶどう畑を作っても、その初物を味わうことはない。'),
('JPN', '申命记', 5, 28, 31, 'あなたの牛が目の前で屠られても、あなたはそれを食べることはない。あなたのろばが目の前から略奪されても、返って来ない。あなたの羊が敵の手に渡されても、あなたを助ける者はいない。'),
('JPN', '申命记', 5, 28, 32, 'あなたの息子と娘はほかの民に渡され、あなたの目は絶えず彼らを慕って衰えるが、あなたはどうすることもできない。'),
('JPN', '申命记', 5, 28, 33, 'あなたの大地の実りもあなたの労苦の実もみな、あなたの知らない民が食べる。あなたはいつまでも虐げられ、踏みにじられるだけである。'),
('JPN', '申命记', 5, 28, 34, 'あなたの目に見る光景で、あなたは気がふれる。'),
('JPN', '申命记', 5, 28, 35, '主はあなたの膝とももを悪性の腫物で打たれ、あなたは癒やされることがない。それは足の裏から頭の頂にまで及ぶ。'),
('JPN', '申命记', 5, 28, 36, '主は、あなたと、あなたが自分の上に立てた王とを、あなたも、あなたの先祖たちも知らなかった国に行かせる。あなたはそこで木や石の、ほかの神々に仕える。'),
('JPN', '申命记', 5, 28, 37, '主があなたを追いやられる先の、あらゆる民の間で、あなたは恐怖のもと、物笑いの種、なぶりものとなる。'),
('JPN', '申命记', 5, 28, 38, '畑に多くの種を持って出ても、あなたは少ししか収穫できない。いなごが食い尽くすからである。'),
('JPN', '申命记', 5, 28, 39, 'ぶどう畑を作って手入れをしても、そのぶどう酒を飲むことも、ぶどうを取り入れることもできない。虫がそれを食べるからである。'),
('JPN', '申命记', 5, 28, 40, '領土のいたるところにオリーブの木があっても、あなたは身に油を塗ることができない。オリーブの実が落ちてしまうからである。'),
('JPN', '申命记', 5, 28, 41, '息子や娘が生まれても、あなたのものとはならない。彼らは捕らわれて行くからである。'),
('JPN', '申命记', 5, 28, 42, 'あなたのすべての木と、大地の実りは、害虫が取り上げてしまう。'),
('JPN', '申命记', 5, 28, 43, 'あなたのうちの寄留者はあなたの上にますます高く上って行き、あなたはますます低く下って行く。'),
('JPN', '申命记', 5, 28, 44, '彼はあなたに貸すが、あなたが彼に貸すことはない。彼はかしらとなり、あなたは尾となる。'),
('JPN', '申命记', 5, 28, 45, 'これらすべてののろいが、あなたに臨み、あなたを追いかけ、あなたに追いつき、ついにあなたは根絶やしにされる。あなたが、あなたの神、主の御声に聞き従わず、主が命じられた命令と掟を守らなかったからである。'),
('JPN', '申命记', 5, 28, 46, 'これらのことは、あなたとあなたの子孫に対して、いつまでも、しるしとなり、また不思議となる。'),
('JPN', '申命记', 5, 28, 47, 'あなたがすべてのものに豊かになる中で、あなたの神、主に喜んで心の底から仕えようとしないので、'),
('JPN', '申命记', 5, 28, 48, 'あなたは飢え渇き、裸となり、あらゆるものに欠乏し、主があなたに差し向ける敵に仕えることになる。主はあなたの首に鉄のくびきをはめ、ついにはあなたを根絶やしにされる。'),
('JPN', '申命记', 5, 28, 49, '主は遠く地の果てから一つの国を来させ、鷲が獲物に向かって舞い降りるように、あなたを襲わせる。その話すことばをあなたが聞いたこともない国である。'),
('JPN', '申命记', 5, 28, 50, 'その国は横柄で、老人に敬意を払わず、幼い者をあわれまず、'),
('JPN', '申命记', 5, 28, 51, 'あなたの家畜が産むものや大地の実りを食い尽くし、ついにあなたは根絶やしにされる。彼らは穀物も新しいぶどう酒も油も、群れの中の子牛も群れの中の子羊も、あなたには少しも残さず、ついにはあなたを滅ぼす。'),
('JPN', '申命记', 5, 28, 52, 'その国は、あなたの国中のすべての町囲みの中にあなたを閉じ込め、ついには、あなたが頼みとする高く堅固な城壁は落とされる。彼らが、あなたの神、主が与えられた国中のすべての町囲みの中にあなたを閉じ込めるとき、'),
('JPN', '申命记', 5, 28, 53, 'あなたは包囲と、敵がもたらす窮乏のために、あなたの神、主が与えてくださった、あなたの胎の実である息子や娘の肉を食べるようになる。'),
('JPN', '申命记', 5, 28, 54, 'あなたのうちの最も優しく、ことのほか上品な男でさえ、兄弟や愛する妻や、まだ残っている子どもたちに対してさえ物惜しみをし、'),
('JPN', '申命记', 5, 28, 55, '自分が食べている子どもの肉をだれにも分け与えようとはしない。あなたのすべての町囲みの中には、包囲と、敵がもたらす窮乏のために、何も残されていないからである。'),
('JPN', '申命记', 5, 28, 56, 'あなたのうちの優しく上品な女で、あまりにも上品で優しいために、足の裏を地面に付けようともしない者でさえ、愛する夫や、息子や娘に物惜しみをし、'),
('JPN', '申命记', 5, 28, 57, 'さらには、あらゆる欠乏のために、自分の脚の間から出た後産や自分が産んだ子さえ、ひそかに食べることまでする。あなたの町囲みの中が包囲と、敵がもたらす窮乏の中にあるからである。'),
('JPN', '申命记', 5, 28, 58, 'もしあなたが、この書物に記されている、このおしえのすべてのことばを守り行わず、この栄光に満ちた恐るべき御名、あなたの神、主を恐れないなら、'),
('JPN', '申命记', 5, 28, 59, '主はあなたへの災害、あなたの子孫への災害を驚くべき仕方で下される。大きな長く続く災害、長く続く悪性の病気である。'),
('JPN', '申命记', 5, 28, 60, '主は、あなたが怖がっていたエジプトのあらゆる悪疫を、再びあなたにもたらされる。それがあなたにまといつく。'),
('JPN', '申命记', 5, 28, 61, '主は、このみおしえの書に記されていない、あらゆる病気、あらゆる災害までもあなたの上に臨ませ、ついにあなたは根絶やしにされる。'),
('JPN', '申命记', 5, 28, 62, 'あなたがたは空の星のように多かったが、少人数しか残されない。あなたの神、主の御声に聞き従わなかったからである。'),
('JPN', '申命记', 5, 28, 63, 'かつて、主があなたがたを幸せにし、あなたがたを増やすことを喜ばれたように、主は、あなたがたを滅ぼし、あなたがたを根絶やしにすることを喜ばれる。あなたがたは、あなたが入って行って所有しようとしている地から引き抜かれる。'),
('JPN', '申命记', 5, 28, 64, '主は地の果てから地の果てまでのあらゆる民の間にあなたを散らす。あなたはそこで、あなたも、あなたの先祖たちも知らなかった、木や石で造られたほかの神々に仕える。'),
('JPN', '申命记', 5, 28, 65, 'これら異邦の民の間にあって、あなたは一息つくこともできず、足の裏を休める場もない。主はそこで、あなたの心を不安にし、目を衰えさせ、たましいを弱らせる。'),
('JPN', '申命记', 5, 28, 66, 'あなたのいのちは危険にさらされ、あなたは夜も昼もおののき、自分が生きることさえ、おぼつかなくなる。'),
('JPN', '申命记', 5, 28, 67, 'あなたは朝には「ああ夕方であればよいのに」と言い、夕方には「ああ朝であればよいのに」と言う。あなたの心に抱くおののきと、あなたの目に見る光景のゆえである。'),
('JPN', '申命记', 5, 28, 68, '私がかつて「あなたはもう二度とこれを見ない」と言った道を通って、主はあなたを船で再びエジプトに戻される。あなたがたが、そこで自分を男奴隷や女奴隷として敵に身売りしようとしても、買ってくれる者はいない。'),
('JPN', '申命记', 5, 29, 1, 'これらは、モアブの地で、主がモーセに命じて、イスラエルの子らと結ばせた契約のことばである。ホレブで彼らと結ばれた契約とは別である。'),
('JPN', '申命记', 5, 29, 2, 'モーセはイスラエルをみな呼び寄せて言った。あなたがたは、エジプトの地で、ファラオとそのすべての家臣たちとその全土に対して、主があなたがたの目の前でなさったことをことごとく見た。'),
('JPN', '申命记', 5, 29, 3, 'すなわち、あなたが自分の目で見たあの大きな試み、あの大きなしるしと不思議である。'),
('JPN', '申命记', 5, 29, 4, 'しかし、主は今日に至るまで、あなたがたに悟る心と見る目と聞く耳を与えられなかった。'),
('JPN', '申命记', 5, 29, 5, '私は四十年の間、荒野であなたがたを導いたが、あなたがたが身に着けている上着はすり切れず、その履き物もすり切れなかった。'),
('JPN', '申命记', 5, 29, 6, 'あなたがたはパンも食べず、ぶどう酒も強い酒も飲まなかった。それは、「わたしがあなたがたの神、主である」と、あなたがたが知るためであった。'),
('JPN', '申命记', 5, 29, 7, 'あなたがたがこの場所に来たとき、ヘシュボンの王シホンとバシャンの王オグが出て来て、私たちを迎え撃ったが、私たちは彼らを討ち破った。'),
('JPN', '申命记', 5, 29, 8, '私たちは彼らの地を取り、これを相続地としてルベン人とガド人と、マナセ人の半部族に分け与えた。'),
('JPN', '申命记', 5, 29, 9, 'あなたがたはこの契約のことばを守り、それを行いなさい。あなたがたのすることがすべて栄えるためである。'),
('JPN', '申命记', 5, 29, 10, '今日あなたがたはみな、あなたがたの神、主の前に立っている。すなわち、あなたがたの部族のかしらたち、長老たち、つかさたち、イスラエルのすべての人々、'),
('JPN', '申命记', 5, 29, 11, 'あなたがたの子どもと妻、宿営の内にいる寄留者、薪を割る者から水を汲む者に至るまでいる。'),
('JPN', '申命记', 5, 29, 12, 'それは、あなたの神、主が今日あなたと結ばれる、あなたの神、主の契約とのろいの誓いとにあなたが入るためであり、'),
('JPN', '申命记', 5, 29, 13, '先に主があなたに約束されたように、またあなたの父祖、アブラハム、イサク、ヤコブに誓われたように、今日あなたを立ててご自分の民とし、またご自分があなたの神となられるためである。'),
('JPN', '申命记', 5, 29, 14, 'しかし私は、ただあなたがたとだけ、この契約とのろいの誓いを結ぶのではない。'),
('JPN', '申命记', 5, 29, 15, '今日ここで私たちの神、主の前に私たちとともに立っている者たちとも、今日、私たちとともにここにはいない者たちとも結ぶのである。'),
('JPN', '申命记', 5, 29, 16, '事実、あなたがた自身、私たちがエジプトの地に住んでいたこと、また私たちが異邦の民の中を通って来たことをよく知っている。'),
('JPN', '申命记', 5, 29, 17, 'また、あなたがたは、彼らのところにあった忌むべきもの、すなわち木や石や銀や金の偶像を見た。'),
('JPN', '申命记', 5, 29, 18, '万が一にも、今日その心が私たちの神、主を離れて、これらの異邦の民の神々のもとに行って仕えるような男、女、氏族、部族があなたがたのうちにあってはならない。あなたがたのうちに、毒草や苦よもぎを生じる根があってはならない。'),
('JPN', '申命记', 5, 29, 19, 'こののろいの誓いのことばを聞いたとき、心の中で自分を祝福し、「私は自分の頑なな心のままに歩んでも大丈夫だ」と言うなら、潤った者も渇いた者も等しく滅びることになる。'),
('JPN', '申命记', 5, 29, 20, '主はその者を決して赦そうとはされない。むしろ、そのとき、主の怒りとねたみがその者に対して燃え上がり、この書に記されている、すべてののろいの誓いがその者の上にのしかかり、主はその者の名を天の下から消し去られる。'),
('JPN', '申命记', 5, 29, 21, '主は、このみおしえの書に記されている契約の、すべてののろいの誓いにしたがい、その者をイスラエルの全部族から選り分けて、わざわいを下される。'),
('JPN', '申命记', 5, 29, 22, '後の世代、あなたがたの後に起こるあなたがたの子孫や、遠くの地から来る異国人は、その地の災害と、主がそこで起こされた病気を見て言うであろう。'),
('JPN', '申命记', 5, 29, 23, 'その全土は硫黄と塩によって焼け土となり、種も蒔かれず、芽も出ず、草一本も生えなくなっていて、主が怒りと憤りでくつがえされた、ソドム、ゴモラ、アデマ、ツェボイムの破滅のようなので、'),
('JPN', '申命记', 5, 29, 24, 'すべての国々は言うであろう。「何のために、主はこの地にこのようなことをされたのか。この激しい燃える怒りは何なのか。」'),
('JPN', '申命记', 5, 29, 25, '人々は言うであろう。「それは彼らが、彼らの父祖の神、主が彼らをエジプトの地から導き出したときに結ばれた契約を捨て、'),
('JPN', '申命记', 5, 29, 26, '彼らの知らない、また彼らに割り当てられたのでもない、ほかの神々のもとに行って仕え、それらを拝んだからだ。'),
('JPN', '申命记', 5, 29, 27, 'それで主の怒りがこの地に向かって燃え上がり、この書に記されたすべてののろいが、この地にもたらされたのだ。'),
('JPN', '申命记', 5, 29, 28, '主は怒りと憤りと激怒をもって彼らをこの地から根こそぎにし、ほかの地に彼らを投げ捨てられた。今日のとおりに。」'),
('JPN', '申命记', 5, 29, 29, '隠されていることは、私たちの神、主のものである。しかし現されたことは永遠に私たちと私たちの子孫のものであり、それは私たちがこのみおしえのすべてのことばを行うためである。'),
('JPN', '申命记', 5, 30, 1, '私があなたの前に置いた祝福とのろい、これらすべてのことがあなたに臨み、あなたの神、主があなたをそこへ追い散らしたすべての国々の中で、あなたが我に返り、'),
('JPN', '申命记', 5, 30, 2, 'あなたの神、主に立ち返り、私が今日あなたに命じるとおりに、あなたも、あなたの子どもたちも、心を尽くし、いのちを尽くし、御声に聞き従うなら、'),
('JPN', '申命记', 5, 30, 3, 'あなたの神、主はあなたを元どおりにし、あなたをあわれみ、あなたの神、主があなたを散らした先の、あらゆる民の中から、再びあなたを集められる。'),
('JPN', '申命记', 5, 30, 4, 'たとえ、あなたが天の果てに追いやられていても、あなたの神、主はそこからあなたを集め、そこからあなたを連れ戻される。'),
('JPN', '申命记', 5, 30, 5, 'あなたの神、主はあなたの先祖が所有していた地にあなたを導き入れ、あなたはそれを所有する。主はあなたを幸せにし、先祖たちよりもその数を増やされる。'),
('JPN', '申命记', 5, 30, 6, 'あなたの神、主は、あなたの心と、あなたの子孫の心に割礼を施し、あなたが心を尽くし、いのちを尽くして、あなたの神、主を愛し、そうしてあなたが生きるようにされる。'),
('JPN', '申命记', 5, 30, 7, 'あなたの神、主はあなたの敵に、あなたを迫害した、あなたを憎む者たちに、これらすべてののろいを下される。'),
('JPN', '申命记', 5, 30, 8, 'あなたは再び主の御声に聞き従い、私が今日あなたに命じる主のすべての命令を行うようになる。'),
('JPN', '申命记', 5, 30, 9, 'あなたの神、主はあなたのすべての手のわざ、あなたの胎の実、家畜が産むもの、大地の実りを豊かに与えて、あなたを栄えさせてくださる。まことに主は、あなたの父祖たちを喜ばれたように、再び、あなたを栄えさせて喜ばれる。'),
('JPN', '申命记', 5, 30, 10, 'これは、あなたが、あなたの神、主の御声に聞き従い、このみおしえの書に記されている主の命令と掟を守り、心のすべて、たましいのすべてをもって、あなたの神、主に立ち返るからである。'),
('JPN', '申命记', 5, 30, 11, 'まことに、私が今日あなたに命じるこの命令は、あなたにとって難しすぎるものではなく、遠くかけ離れたものでもない。'),
('JPN', '申命记', 5, 30, 12, 'これは天にあるわけではないので、「だれが私たちのために天に上り、それを取って来て、私たちが行えるように聞かせてくれるのか」と言わなくてよい。'),
('JPN', '申命记', 5, 30, 13, 'また、これは海のかなたにあるわけではないので、「だれが私たちのために海のかなたに渡り、それを取って来て、私たちが行えるように聞かせてくれるのか」と言わなくてよい。'),
('JPN', '申命记', 5, 30, 14, 'まことに、みことばは、あなたのすぐ近くにあり、あなたの口にあり、あなたの心にあって、あなたはこれを行うことができる。'),
('JPN', '申命记', 5, 30, 15, '見よ、私は確かに今日あなたの前に、いのちと幸い、死とわざわいを置く。'),
('JPN', '申命记', 5, 30, 16, 'もしあなたが、私が今日あなたに命じる命令に聞き、あなたの神、主を愛し、主の道に歩み、主の命令と掟と定めを守るなら、あなたは生きて数を増やし、あなたの神、主は、あなたが入って行って所有しようとしている地で、あなたを祝福される。'),
('JPN', '申命记', 5, 30, 17, 'しかし、もしあなたが心を背け、聞き従わず、誘惑されてほかの神々を拝み、これに仕えるなら、'),
('JPN', '申命记', 5, 30, 18, '今日、私はあなたがたに宣言する。あなたがたは必ず滅び失せる。あなたがヨルダン川を渡り、入って行って所有しようとしているその土地で、あなたの日々が長く続くことはない。'),
('JPN', '申命记', 5, 30, 19, '私は今日、あなたがたに対して天と地を証人に立てる。私は、いのちと死、祝福とのろいをあなたの前に置く。あなたはいのちを選びなさい。あなたもあなたの子孫も生き、'),
('JPN', '申命记', 5, 30, 20, 'あなたの神、主を愛し、御声に聞き従い、主にすがるためである。まことにこの方こそあなたのいのちであり、あなたの日々は長く続く。あなたは、主があなたの父祖、アブラハム、イサク、ヤコブに与えると誓われたその土地の上に住むことになる。'),
('JPN', '申命记', 5, 31, 1, 'それからモーセは行って、次のことばをイスラエル全体に告げて、'),
('JPN', '申命记', 5, 31, 2, '彼らに向かって言った。「私は今日、百二十歳だ。もう出入りすることができない。主は私に『あなたはこのヨルダン川を渡ることはできない』と言われた。'),
('JPN', '申命记', 5, 31, 3, 'あなたの神、主ご自身があなたに先立って渡って行き、この方があなたの前からこれらの国々を根絶やしにされ、あなたはこれらを占領する。ヨシュアが、主が告げられたように、あなたに先立って渡るのだ。'),
('JPN', '申命记', 5, 31, 4, '主は、主が根絶やしにした、アモリ人の王シホンとオグおよび彼らの国に対して行ったように、彼らに対しても行われる。'),
('JPN', '申命记', 5, 31, 5, '主は彼らをあなたがたに渡される。あなたがたは、私が命じたすべての命令どおり、彼らに行わなければならない。'),
('JPN', '申命记', 5, 31, 6, '強くあれ。雄々しくあれ。彼らを恐れてはならない。おののいてはならない。あなたの神、主ご自身があなたとともに進まれるからだ。主はあなたを見放さず、あなたを見捨てない。」'),
('JPN', '申命记', 5, 31, 7, 'それからモーセはヨシュアを呼び寄せ、全イスラエルの目の前で彼に言った。「強くあれ。雄々しくあれ。主がこの民の父祖たちに与えると誓われた地に、彼らとともに入るのはあなたであり、それを彼らに受け継がせるのもあなたである。'),
('JPN', '申命记', 5, 31, 8, '主ご自身があなたに先立って進まれる。主があなたとともにおられる。主はあなたを見放さず、あなたを見捨てない。恐れてはならない。おののいてはならない。」'),
('JPN', '申命记', 5, 31, 9, 'モーセはこのみおしえを書き記し、主の契約の箱を運ぶレビ族の祭司たちと、イスラエルのすべての長老たちにこれを与えた。'),
('JPN', '申命记', 5, 31, 10, 'モーセは彼らに命じた。「七年の終わりごとに、すなわち免除の年の定めの時、仮庵の祭りに、'),
('JPN', '申命记', 5, 31, 11, 'イスラエル全体が、主が選ばれる場所に、あなたの神、主の前に出るためにやって来たとき、あなたはイスラエル全体の前で、彼らの耳にこのみおしえを読んで聞かせなければならない。'),
('JPN', '申命记', 5, 31, 12, '民を、男も女も子どもも集めなさい。あなたの町囲みの中にいる寄留者も。彼らがこれを聞いて学び、あなたがたの神、主を恐れ、このみおしえのすべてのことばを守り行うようにするためである。'),
('JPN', '申命记', 5, 31, 13, 'これを知らない、彼らの子どもたちもこれを聞き、あなたがたがヨルダン川を渡って所有しようとしている地で、彼らが生きるかぎり、あなたがたの神、主を恐れることを学ばなければならない。」'),
('JPN', '申命记', 5, 31, 14, 'それから主はモーセに言われた。「今や、あなたの死ぬ日が近づいている。ヨシュアを呼び寄せ、あなたがたは会見の天幕に立て。わたしは彼に命令を下そう。」モーセとヨシュアは行って、会見の天幕に立った。'),
('JPN', '申命记', 5, 31, 15, '主は天幕で雲の柱のうちに現れた。雲の柱は天幕の入り口にとどまった。'),
('JPN', '申命记', 5, 31, 16, '主はモーセに言われた。「見よ、あなたは間もなく先祖とともに眠りにつこうとしている。この民は入って行こうとしている地の異国の神々を慕い、自分たちのうちで淫行を行い、わたしを捨てて、わたしがこの民と結んだわたしの契約を破る。'),
('JPN', '申命记', 5, 31, 17, 'その日、わたしの怒りはこの民に対して燃え上がり、わたしも彼らを捨て、わたしの顔を彼らから隠す。彼らが焼き尽くされ、多くのわざわいと苦難が彼らに降りかかると、その日この民は、『これらのわざわいが私たちに降りかかるのは、私たちのうちに私たちの神がおられないからではないか』と言う。'),
('JPN', '申命记', 5, 31, 18, 'わたしはその日、彼らが行ったすべての悪のゆえに必ずわたしの顔を隠す。彼らがほかの神々の方に向かったからである。'),
('JPN', '申命记', 5, 31, 19, '今、次の歌を書き記し、それをイスラエルの子らに教え、彼らの口にそれを置け。この歌をイスラエルの子らに対するわたしの証しとするためである。'),
('JPN', '申命记', 5, 31, 20, 'わたしが彼らを、彼らの父祖たちに誓った乳と蜜の流れる土地に導き入れるとき、彼らは食べて満ち足り、肥え太り、そして、ほかの神々の方に向かってこれに仕え、わたしを侮ってわたしの契約を破る。'),
('JPN', '申命记', 5, 31, 21, '多くのわざわいと苦難が降りかかるとき、この歌が彼らに対して証しをする。彼らの子孫の口からそれが忘れられることはないからである。わたしが誓った地に彼らを導き入れる以前から、彼らが今しようとしている計画を、わたしはよく知っているからである。」'),
('JPN', '申命记', 5, 31, 22, 'モーセは、その日、この歌を書き記してイスラエルの子らに教えた。'),
('JPN', '申命记', 5, 31, 23, 'それから主はヌンの子ヨシュアに命じられた。「強くあれ。雄々しくあれ。あなたはイスラエルの子らを、わたしが彼らに誓った地に導き入れるのだ。わたしが、あなたとともにいる。」'),
('JPN', '申命记', 5, 31, 24, 'モーセがこのみおしえのことばを、その最後まで書物に書き終えたとき、'),
('JPN', '申命记', 5, 31, 25, 'モーセは主の契約の箱を運ぶレビ人に命じた。'),
('JPN', '申命记', 5, 31, 26, '「このみおしえの書を取り、あなたがたの神、主の契約の箱のそばに置きなさい。その場所で、あなたに対する証しとしなさい。'),
('JPN', '申命记', 5, 31, 27, '私は、あなたがどれほど逆らう者であるか、うなじを固くする者であるかをよく知っている。見よ。私があなたがたとともに生きている今でさえ、あなたがたは主に逆らってきた。私の死後は、なおさらであろう。'),
('JPN', '申命记', 5, 31, 28, 'あなたがたの部族の長老たちと、つかさたちをみな、私のもとに集めなさい。私はこれらのことばを彼らに聞こえるように語ろう。私は天と地を彼らに対する証人に立てる。'),
('JPN', '申命记', 5, 31, 29, '私の死後、あなたがたがきっと堕落して、私があなたがたに命じた道から外れること、また、後の日に、わざわいがあなたがたに降りかかることを私はよく知っているからだ。それは、あなたがたが主の目に悪であることを行い、あなたがたの手のわざによって主の怒りを引き起こすからである。」'),
('JPN', '申命记', 5, 31, 30, 'モーセはイスラエルの集会全体に聞こえるように、次の歌のことばを終わりまで唱えた。'),
('JPN', '申命记', 5, 32, 1, '天よ、耳を傾けよ。私は語ろう。地よ、聞け。私の口のことばを。'),
('JPN', '申命记', 5, 32, 2, '私のおしえは雨のように下り、私のことばは露のように滴る。若草の上の小雨のように。青草の上の夕立のように。'),
('JPN', '申命记', 5, 32, 3, 'まことに私は主の御名を告げ知らせる。栄光を私たちの神に帰せよ。'),
('JPN', '申命记', 5, 32, 4, '主は岩。主のみわざは完全。まことに主の道はみな正しい。主は真実な神で偽りがなく、正しい方、直ぐな方である。'),
('JPN', '申命记', 5, 32, 5, '自分の汚れで主との交わりを損なう、主の子らではない、よこしまで曲がった世代。'),
('JPN', '申命记', 5, 32, 6, 'あなたがたはこのようにして主に恩を返すのか。愚かで知恵のない民よ。主はあなたを造った父ではないか。主はあなたを造り上げ、あなたを堅く立てた方ではないか。'),
('JPN', '申命记', 5, 32, 7, '昔の日々を思い出し、代々の年を思え。あなたの父に問え。彼はあなたに告げ知らせる。長老たちに問え。彼らはあなたに話す。'),
('JPN', '申命记', 5, 32, 8, 'いと高き方が、国々に相続地を持たせ、人の子らを割り振られたとき、イスラエルの子らの数にしたがって、もろもろの民の境を決められた。'),
('JPN', '申命记', 5, 32, 9, '主は、測り縄で割り当て地を定められた。ご自分の民、ヤコブへのゆずりの地を。'),
('JPN', '申命记', 5, 32, 10, '主は荒野の地で、荒涼とした荒れ地で彼を見つけ、これを抱き、世話をし、ご自分の瞳のように守られた。'),
('JPN', '申命记', 5, 32, 11, '鷲が巣のひなを呼び覚まし、そのひなの上を舞い、翼を広げてこれを取り、羽に乗せて行くように。'),
('JPN', '申命记', 5, 32, 12, 'ただ主だけでこれを導き、主とともに異国の神はいなかった。'),
('JPN', '申命记', 5, 32, 13, '主はこれを地の高い所に上らせ、野の産物を食べさせた。主は岩からの蜜と硬い岩からの油でこれを養い、'),
('JPN', '申命记', 5, 32, 14, '牛の凝乳と羊の乳を最良の子羊とともに、バシャンのものである雄羊と雄やぎを小麦の最良のものとともに、与えてくださった。あなたは泡立つぶどう酒を飲んだ。'),
('JPN', '申命记', 5, 32, 15, 'エシュルンは肥え太ったとき、足で蹴った。あなたは肥え太り、頑丈でつややかになり、自分を造った神を捨て、自分の救いの岩を軽んじた。'),
('JPN', '申命记', 5, 32, 16, '彼らは異なる神々で主のねたみを引き起こし、忌み嫌うべきもので、主の怒りを燃えさせた。'),
('JPN', '申命记', 5, 32, 17, '彼らは、神ではない悪霊どもにいけにえを献げた。彼らの知らなかった神々に、近ごろ出て来た新しい神々、先祖が恐れもしなかった神々に。'),
('JPN', '申命记', 5, 32, 18, 'あなたは自分を生んだ岩をおろそかにし、産みの苦しみをした神を忘れてしまった。'),
('JPN', '申命记', 5, 32, 19, '主は見て、彼らを突き放された。主の息子と娘たちへの怒りゆえに。'),
('JPN', '申命记', 5, 32, 20, '主は言われた。「わたしの顔を彼らから隠し、彼らの終わりがどうなるかを見よう。彼らは、ねじれた世代、真実のない子らであるから。'),
('JPN', '申命记', 5, 32, 21, '彼らは、神でないものでわたしのねたみを引き起こし、彼らの空しいものでわたしの怒りを燃えさせた。わたしも、民でない者たちで彼らのねたみを引き起こし、愚かな国民で彼らの怒りを燃えさせる。'),
('JPN', '申命记', 5, 32, 22, '火はわたしの怒りで燃え上がり、よみの底まで燃えていく。地とその産物を焼き尽くし、山々の基まで焼き払う。'),
('JPN', '申命记', 5, 32, 23, 'わたしはわざわいを彼らの上に積み重ね、わたしの矢を彼らに向けて射尽くす。'),
('JPN', '申命记', 5, 32, 24, '飢えによる荒廃、災害による壊滅、激しい悪疫、野獣の牙、これらを、地を這う蛇の毒とともに彼らに送る。'),
('JPN', '申命记', 5, 32, 25, '外では剣が子を失わせ、内には恐怖がある。若い男にも若い女にも、乳飲み子も白髪の老人にも。'),
('JPN', '申命记', 5, 32, 26, 'わたしは思った。彼らを一掃し、人々から彼らの記憶を消してしまおうと。'),
('JPN', '申命记', 5, 32, 27, 'もしも、わたしが敵のののしりを気にかけなかったら──彼らを苦しめる者どもが誤解してはいけない。『われわれの手で勝ったのだ。これはみな、主がしたことではない』と言うといけない。」'),
('JPN', '申命记', 5, 32, 28, 'まことに彼らは思慮の欠けた国民、彼らのうちに英知はない。'),
('JPN', '申命记', 5, 32, 29, 'もしも知恵があったなら、彼らはこれを悟ったであろうに。自分の終わりもわきまえたであろうに。'),
('JPN', '申命记', 5, 32, 30, '彼らの岩が彼らを売らず、主が彼らを引き渡されなかったなら、どのようにして一人が千人を追い、二人が万人を敗走させたであろうか。'),
('JPN', '申命记', 5, 32, 31, 'まことに彼らの岩は私たちの岩に及ばない。敵もこれを認めている。'),
('JPN', '申命记', 5, 32, 32, 'まことに彼らのぶどうの木は、ソドムのぶどうの木から、ゴモラのぶどう畑からのもの。彼らのぶどうは毒ぶどう。その房は苦い。'),
('JPN', '申命记', 5, 32, 33, 'そのぶどう酒は蛇の毒、コブラの恐ろしい毒。'),
('JPN', '申命记', 5, 32, 34, '「これはわたしのもとに蓄えてあり、わたしの倉に封じ込められているではないか。'),
('JPN', '申命记', 5, 32, 35, '復讐と報復はわたしのもの。それは彼らの足がよろめくときのため。彼らのわざわいの日は近く、来たるべき時が速やかに来る。」'),
('JPN', '申命记', 5, 32, 36, '主は御民をかばい、主のしもべらをあわれまれる。彼らの力が去り、奴隷も自由の者もいなくなるのをご覧になって。'),
('JPN', '申命记', 5, 32, 37, '主は言われる。「彼らの神々はどこにいるのか。彼らが身を避けた岩はどこにあるのか。'),
('JPN', '申命记', 5, 32, 38, '彼らのいけにえの脂肪を食らい、注ぎのぶどう酒を飲んだ者どもはどこにいるのか。彼らを立たせて、あなたがたを助けさせ、あなたがたの隠れ場とならせよ。'),
('JPN', '申命记', 5, 32, 39, '今、見よ、わたし、わたしこそがそれである。わたしのほかに神はいない。わたしは殺し、また生かす。わたしは傷つけ、また癒やす。わたしの手からは、だれも救い出せない。'),
('JPN', '申命记', 5, 32, 40, 'まことに、わたしは誓って言う。『わたしは永遠に生きる。'),
('JPN', '申命记', 5, 32, 41, 'わたしが、きらめく剣を研ぎ、手にさばきを握るとき、わたしは敵に復讐をし、わたしを憎む者たちに報いる。'),
('JPN', '申命记', 5, 32, 42, 'わたしの矢を血に酔わせ、わたしの剣に肉を食わせる。刺し殺された者や捕らわれ人の血に酔わせ、敵のかしらたちの首を食わせる。』」'),
('JPN', '申命记', 5, 32, 43, '国々よ、御民のために喜び歌え。主がご自分のしもべの血に報復し、ご自分の敵に復讐を遂げて、ご自分の民とその地のために宥めを行われる。'),
('JPN', '申命记', 5, 32, 44, 'モーセはヌンの子ホセアと一緒に行って、この歌のすべてのことばを民の耳に語り聞かせた。'),
('JPN', '申命记', 5, 32, 45, 'モーセはイスラエル全体にこのことばをみな語り終えて、'),
('JPN', '申命记', 5, 32, 46, '彼らに言った。「あなたがたは、私が今日あなたがたを戒める、このすべてのことばを心にとどめなさい。それをあなたがたの子どもたちに命じて、このみおしえのすべてのことばを守り行わせなさい。'),
('JPN', '申命记', 5, 32, 47, 'これは、あなたがたにとって空虚なことばではなく、あなたがたのいのちであるからだ。このことばによって、ヨルダン川を渡って行って所有しようとしているその土地で、あなたの日々が長く続くことになる。」'),
('JPN', '申命记', 5, 32, 48, 'この同じ日に主はモーセに告げられた。'),
('JPN', '申命记', 5, 32, 49, '「エリコの向かいにあるモアブの地の、このアバリム高地のネボ山に登り、わたしがイスラエルの子らに与えて所有させようとしているカナンの地を見よ。'),
('JPN', '申命记', 5, 32, 50, 'あなたの兄弟アロンがホル山で死んで、その民に加えられたように、あなたも、これから登るその山で死に、あなたの民に加えられる。'),
('JPN', '申命记', 5, 32, 51, 'それは、あなたがたがツィンの荒野のメリバテ・カデシュの水のほとりで、イスラエルの子らの間でわたしの信頼を裏切り、イスラエルの子らの間で、わたしを聖なる者としなかったからである。'),
('JPN', '申命记', 5, 32, 52, 'あなたは、わたしがイスラエルの子らに与えようとしている地を目の前に見るが、その地へ入って行くことはできない。」'),
('JPN', '申命记', 5, 33, 1, '次は神の人モーセが、その死を前にしてイスラエルの子らを祝福した、祝福のことばである。'),
('JPN', '申命记', 5, 33, 2, '彼は言った。「主はシナイから来て、セイルから彼らを照らし、パランの山から光を放ち、幾万もの聖なる者のところから近づいて来られる。その右手に彼らの御使いたちを伴って。'),
('JPN', '申命记', 5, 33, 3, 'まことに、あなたはもろもろの民を愛する方、御手のうちにすべての聖なる者がいる。彼らはあなたの足もとにひれ伏し、あなたの御告げを受ける。'),
('JPN', '申命记', 5, 33, 4, 'みおしえはモーセが私たちに命じ、それをヤコブの会衆の所有とした。'),
('JPN', '申命记', 5, 33, 5, '民のかしらたちがイスラエルの部族とともに集まったとき、主はエシュルンで王となられた。」'),
('JPN', '申命记', 5, 33, 6, '「ルベンは生きて、死なないように。その人数が少なくても。」'),
('JPN', '申命记', 5, 33, 7, 'ユダについては、こう言った。「主よ。ユダの声を聞き、彼をその民のもとに連れ戻してください。彼は自分の手で戦っています。彼の敵の前で助けとなってください。」'),
('JPN', '申命记', 5, 33, 8, 'レビについては、こう言った。「あなたのトンミムとウリムを、あなたにある敬虔な者に与えてください。あなたは彼をマサで試み、メリバの水のほとりで彼と争われました。'),
('JPN', '申命记', 5, 33, 9, '彼は自分の父と母について『私は彼らを顧みない』と言い、自分の兄弟も認めず、自分の子さえ知らないとし、ただ、あなたの仰せのことばを守り、あなたの契約から目を離しませんでした。'),
('JPN', '申命记', 5, 33, 10, '彼らはあなたの定めをヤコブに、あなたのみおしえをイスラエルに教えます。彼らはあなたの御前で香をたき、全焼のささげ物をあなたの祭壇に献げます。'),
('JPN', '申命记', 5, 33, 11, '主よ。彼の財産を祝福し、その手のわざを受け入れてください。彼に向かい立つ者の腰を打ち砕き、彼を憎む者たちが立ち上がれないようにしてください。」'),
('JPN', '申命记', 5, 33, 12, 'ベニヤミンについては、こう言った。「主に愛されている者。彼は安らかに主のそばに住まい、主はいつも彼をかばう。彼は主の背中に負われる。」'),
('JPN', '申命记', 5, 33, 13, 'ヨセフについては、こう言った。「彼の地は主に祝福されたもの。天の賜物の露、下に横たわる大いなる水の賜物、'),
('JPN', '申命记', 5, 33, 14, '太陽がもたらす賜物、月が生み出す賜物、'),
('JPN', '申命记', 5, 33, 15, 'いにしえの山々からの最上のもの、永遠の丘からの賜物、'),
('JPN', '申命记', 5, 33, 16, '地とそこに満ちているものの賜物、柴の茂みの中におられた方の恵み、これらがヨセフの頭の上に、その兄弟たちの中から選り抜かれた者の頭の頂に臨むように。'),
('JPN', '申命记', 5, 33, 17, '彼の牛の初子には威厳があり、その角は野牛の角。これをもって地の果ての果てまで、もろもろの民をことごとく突き倒して行く。このような者がエフライムに幾万、このような者がマナセに幾千。」'),
('JPN', '申命记', 5, 33, 18, 'ゼブルンについては、こう言った。「ゼブルンよ、喜べ。あなたが外に出て行くときに。イッサカルよ、あなたは天幕の中で。'),
('JPN', '申命记', 5, 33, 19, '彼らはもろもろの民を山に招き、そこで義のいけにえを献げる。彼らが海の富と、砂に隠されている宝で育まれるからである。」'),
('JPN', '申命记', 5, 33, 20, 'ガドについては、こう言った。「ガドの土地を広げる方はほむべきかな。ガドは雌獅子のように伏し、腕や頭の頂をかみ裂く。'),
('JPN', '申命记', 5, 33, 21, '彼は自分のために最良の地を見つけた。そこには指導者の分が割り当てられていたのだ。彼は民の先頭に立ち、主の正義と主の公正をイスラエルのために行った。」'),
('JPN', '申命记', 5, 33, 22, 'ダンについては、こう言った。「ダンは獅子の子。バシャンから躍り出る。」'),
('JPN', '申命记', 5, 33, 23, 'ナフタリについては、こう言った。「ナフタリは恵みに満ち足り、主の祝福に満ちている。彼は西と南を所有せよ。」'),
('JPN', '申命记', 5, 33, 24, 'アシェルについては、こう言った。「アシェルは子らの中で最も祝福されている。その兄弟たちに愛されて、その足を油の中に浸すようになれ。'),
('JPN', '申命记', 5, 33, 25, 'あなたのかんぬきは鉄と青銅。あなたの力が、生きるかぎり続くように。」'),
('JPN', '申命记', 5, 33, 26, '「エシュルンよ、神に並ぶ者はほかにない。神はあなたを助けるため天に乗り、威光のうちに雲に乗られる。'),
('JPN', '申命记', 5, 33, 27, 'いにしえよりの神は、住まう家。下には永遠の腕がある。神はあなたの前から敵を追い払い、『根絶やしにせよ』と命じられた。'),
('JPN', '申命记', 5, 33, 28, 'こうしてイスラエルは安らかに住まい、ヤコブの泉だけが穀物と新しいぶどう酒の地を満たす。天も露を滴らす。'),
('JPN', '申命记', 5, 33, 29, '幸いなイスラエルよ、だれがあなたのような、主に救われた民であろうか。主はあなたを助ける盾、あなたの勝利の剣。敵はあなたに屈し、あなたは彼らの背を踏みつける。」'),
('JPN', '申命记', 5, 34, 1, 'モーセはモアブの草原からネボ山、すなわち、エリコの向かいにあるピスガの頂に登った。主は彼に次の全地方をお見せになった。ギルアデをダンまで、'),
('JPN', '申命记', 5, 34, 2, 'ナフタリの全土、エフライムとマナセの地、ユダの全土を西の海まで、'),
('JPN', '申命记', 5, 34, 3, 'ネゲブと低地を、すなわち、なつめ椰子の町エリコの平地をツォアルまで。'),
('JPN', '申命记', 5, 34, 4, 'そして主は彼に言われた。「わたしがアブラハム、イサク、ヤコブに『あなたの子孫に与える』と誓った地はこれである。わたしはこれをあなたの目に見せたが、あなたがそこへ渡って行くことはできない。」'),
('JPN', '申命记', 5, 34, 5, 'こうしてその場所で、主のしもべモーセは主の命によりモアブの地で死んだ。'),
('JPN', '申命记', 5, 34, 6, '主は彼を、ベテ・ペオルの向かいにあるモアブの地の谷に葬られたが、今日に至るまで、その墓を知る者はいない。'),
('JPN', '申命记', 5, 34, 7, 'モーセが死んだときは百二十歳であったが、彼の目はかすまず、気力も衰えていなかった。'),
('JPN', '申命记', 5, 34, 8, 'イスラエルの子らはモアブの草原で三十日間、モーセのために泣き悲しんだ。こうして、モーセのために泣き悲しむ喪の期間は終わった。'),
('JPN', '申命记', 5, 34, 9, 'ヌンの子ヨシュアは知恵の霊に満たされていた。モーセがかつて彼の上にその手を置いたからである。イスラエルの子らは彼に聞き従い、主がモーセに命じられたとおりに行った。'),
('JPN', '申命记', 5, 34, 10, 'モーセのような預言者は、もう再びイスラエルには起こらなかった。彼は、主が顔と顔を合わせて選び出したのであった。'),
('JPN', '申命记', 5, 34, 11, 'それは、主が彼をエジプトの地に遣わして、ファラオとそのすべての家臣たち、およびその全土に対して、あらゆるしるしと不思議を行わせるためであり、'),
('JPN', '申命记', 5, 34, 12, 'また、モーセが全イスラエルの目の前で、あらゆる力強い権威と、あらゆる恐るべき威力をふるうためであった。'),
('JPN', '约书亚记', 6, 1, 1, '主のしもべモーセの死後、主はモーセの従者、ヌンの子ヨシュアに告げられた。'),
('JPN', '约书亚记', 6, 1, 2, '「わたしのしもべモーセは死んだ。今、あなたとこの民はみな、立ってこのヨルダン川を渡り、わたしがイスラエルの子らに与えようとしている地に行け。'),
('JPN', '约书亚记', 6, 1, 3, 'わたしがモーセに約束したとおり、あなたがたが足の裏で踏む場所はことごとく、すでにあなたがたに与えている。'),
('JPN', '约书亚记', 6, 1, 4, 'あなたがたの領土は荒野からあのレバノン、そしてあの大河ユーフラテス川まで、ヒッタイト人の全土、日の入る方の大海までとなる。'),
('JPN', '约书亚记', 6, 1, 5, 'あなたの一生の間、だれ一人としてあなたの前に立ちはだかる者はいない。わたしはモーセとともにいたように、あなたとともにいる。わたしはあなたを見放さず、あなたを見捨てない。'),
('JPN', '约书亚记', 6, 1, 6, '強くあれ。雄々しくあれ。あなたはわたしが父祖たちに与えると誓った地を、この民に受け継がせなければならないからだ。'),
('JPN', '约书亚记', 6, 1, 7, 'ただ強くあれ。雄々しくあれ。わたしのしもべモーセがあなたに命じた律法のすべてを守り行うためである。これを離れて、右にも左にもそれてはならない。あなたが行くところどこででも、あなたが栄えるためである。'),
('JPN', '约书亚记', 6, 1, 8, 'このみおしえの書をあなたの口から離さず、昼も夜もそれを口ずさめ。そのうちに記されていることすべてを守り行うためである。そのとき、あなたは自分がすることで繁栄し、そのとき、あなたは栄えるからである。'),
('JPN', '约书亚记', 6, 1, 9, 'わたしはあなたに命じたではないか。強くあれ。雄々しくあれ。恐れてはならない。おののいてはならない。あなたが行くところどこででも、あなたの神、主があなたとともにいるのだから。」'),
('JPN', '约书亚记', 6, 1, 10, 'ヨシュアは民のつかさたちに命じた。'),
('JPN', '约书亚记', 6, 1, 11, '「宿営の中を巡って、民に命じなさい。『食糧を準備しなさい。三日のうちに、あなたがたはこのヨルダン川を渡るからだ。あなたがたの神、主があなたがたに与えて所有させようとしておられる地を占領するために、あなたがたは進むのだ。』」'),
('JPN', '约书亚记', 6, 1, 12, 'その一方で、ルベン人、ガド人、およびマナセの半部族にヨシュアは言った。'),
('JPN', '约书亚记', 6, 1, 13, '「主のしもべモーセがあなたがたに命じて、『あなたがたの神、主はあなたがたに安息を与え、この地を与えようとしておられる』と言ったことばを思い出しなさい。'),
('JPN', '约书亚记', 6, 1, 14, 'あなたがたの妻子たちと家畜は、モーセがあなたがたに与えた、このヨルダンの川向こうにとどまりなさい。しかし、あなたがた勇士はみな、隊列を組み、あなたがたの兄弟たちより先に渡って行って、彼らを助けなければならない。'),
('JPN', '约书亚记', 6, 1, 15, '主があなたがたの兄弟たちにも、あなたがたと同様に安息を与え、彼らもあなたがたの神、主が与えようとしておられる地を所有したら、あなたがたは主のしもべモーセがあなたがたに与えた、このヨルダンの川向こう、日の出る方にある自分たちの所有の地に帰り、それを所有することができる。」'),
('JPN', '约书亚记', 6, 1, 16, '彼らはヨシュアに答えた。「あなたが私たちに命じたことは、何でも行います。あなたが遣わすところには、どこでも参ります。'),
('JPN', '约书亚记', 6, 1, 17, '私たちは、あらゆる点でモーセに聞き従ったように、あなたに聞き従います。どうかあなたの神、主が、モーセとともにおられたように、あなたとともにおられますように。'),
('JPN', '约书亚记', 6, 1, 18, 'あなたの命令に逆らい、あなたが私たちに命じることばに聞き従わない者はみな、殺されなければなりません。あなたは、ただ強く雄々しくあってください。」'),
('JPN', '约书亚记', 6, 2, 1, 'ヌンの子ヨシュアは、シティムから、ひそかに二人の者を偵察として遣わして言った。「さあ、あの地とエリコを見て来なさい。」彼らは行って、ラハブという名の遊女の家に入り、そこに泊まった。'),
('JPN', '约书亚记', 6, 2, 2, 'ある人がエリコの王に、「イスラエル人の数名の男たちが今夜、この地を探ろうとして入って来ました」と告げた。'),
('JPN', '约书亚记', 6, 2, 3, 'それで、エリコの王はラハブのところに人を遣わして言った。「おまえのところに来て、おまえの家に入った者たちを出せ。その者たちは、この地のすべてを探ろうとしてやって来たのだから。」'),
('JPN', '约书亚记', 6, 2, 4, 'ところが、彼女はその二人をかくまって言った。「そうです。その人たちは私のところに来ました。でも、どこから来たのか、私は知りません。'),
('JPN', '约书亚记', 6, 2, 5, '暗くなって門が閉じられるころ、その人たちは出て行きました。どこへ行ったのか、私は知りません。急いで彼らを追ってごらんなさい。追いつけるかもしれません。」'),
('JPN', '约书亚记', 6, 2, 6, '彼女は二人を屋上へ上がらせ、屋上に積んであった亜麻の茎の中におおい隠していた。'),
('JPN', '约书亚记', 6, 2, 7, '追っ手たちはヨルダン川の道をたどり、渡し場までその人たちを追って行った。門は、彼らを追う追っ手たちが出て行くと、すぐに閉じられた。'),
('JPN', '约书亚记', 6, 2, 8, '二人がまだ寝ないうちに、彼女は屋上の彼らのところへ上がり、'),
('JPN', '约书亚记', 6, 2, 9, '彼らに言った。「主がこの地をあなたがたに与えておられること、私たちがあなたがたに対する恐怖に襲われていること、そして、この地の住民がみな、あなたがたのために震えおののいていることを、私はよく知っています。'),
('JPN', '约书亚记', 6, 2, 10, 'あなたがたがエジプトから出て来たとき、主があなたがたのために葦の海の水を涸らされたこと、そして、あなたがたが、ヨルダンの川向こうにいたアモリ人の二人の王シホンとオグにしたこと、二人を聖絶したことを私たちは聞いたからです。'),
('JPN', '约书亚记', 6, 2, 11, '私たちは、それを聞いたとき心が萎えて、あなたがたのために、だれもが気力を失ってしまいました。あなたがたの神、主は、上は天において、下は地において、神であられるからです。'),
('JPN', '约书亚记', 6, 2, 12, '今、主にかけて私に誓ってください。私はあなたがたに誠意を尽くしたのですから、あなたがたもまた、私の父の家に誠意を尽くし、私に確かなしるしを与え、'),
('JPN', '约书亚记', 6, 2, 13, '私の父、母、兄弟、姉妹、また、これに属するものをすべて生かして、私たちのいのちを死から救い出す、と誓ってください。」'),
('JPN', '约书亚记', 6, 2, 14, '二人は彼女に言った。「私たちはあなたがたに自分のいのちをかけて誓う。あなたがたが私たちのことをだれにも告げないなら、主が私たちにこの地を与えてくださるとき、あなたに誠意と真実を尽くそう。」'),
('JPN', '约书亚记', 6, 2, 15, 'そこで、ラハブは綱で窓から彼らをつり降ろした。彼女の家は城壁に建て込まれていて、彼女はその城壁の中に住んでいた。'),
('JPN', '约书亚记', 6, 2, 16, '彼女は二人に言った。「山地の方へ行ってください。追っ手たちがあなたがたに出くわすといけませんから。彼らが引き揚げるまで、三日間そこに身を隠していてください。その後で、あなたがたが行く道を行かれたらよいでしょう。」'),
('JPN', '约书亚记', 6, 2, 17, '二人は彼女に言った。「もしこのようにあなたが行わないなら、あなたが私たちに誓わせた、あなたへのこの誓いから私たちは解かれます。'),
('JPN', '约书亚记', 6, 2, 18, '見なさい、私たちはこの地に入って来ます。私たちをつり降ろした窓に、この赤いひもを結び付けておきなさい。あなたの父、母、兄弟、そして、あなたの一族全員をあなたの家に集めておきなさい。'),
('JPN', '约书亚记', 6, 2, 19, 'あなたの家の戸口から外に出る者がいれば、その人の血はその人自身の頭上に降りかかり、私たちに罪はありません。しかし、あなたと一緒に家の中にいる者のだれにでも手が下されたなら、その人の血は私たちの頭上に降りかかります。'),
('JPN', '约书亚记', 6, 2, 20, 'だが、もしあなたが私たちの、このことをだれかに告げるなら、あなたが私たちに誓わせた、あなたへの誓いから私たちは解かれます。」'),
('JPN', '约书亚记', 6, 2, 21, '彼女は「おことばどおりにしましょう」と言い、二人を送り出した。彼らは去り、彼女は窓に赤いひもを結んだ。'),
('JPN', '约书亚记', 6, 2, 22, '彼らはそこを去って山地の方へ行き、追っ手たちが引き揚げるまで、三日そこにとどまった。追っ手たちは道中くまなく捜したが、彼らは見つからなかった。'),
('JPN', '约书亚记', 6, 2, 23, '二人は帰途についた。山地から下り、川を渡り、ヌンの子ヨシュアのところに来て、その身に起こったことをことごとく彼に話した。'),
('JPN', '约书亚记', 6, 2, 24, '彼らはヨシュアに言った。「主はあの地をことごとく私たちの手にお与えになりました。確かに、あの地の住民はみな、私たちのゆえに震えおののいています。」'),
('JPN', '约书亚记', 6, 3, 1, 'ヨシュアは翌朝早く起き、すべてのイスラエルの子らとともにシティムを旅立ち、ヨルダン川のところまで来て、それを渡る前にそこに泊まった。'),
('JPN', '约书亚记', 6, 3, 2, '三日後、つかさたちは宿営の中を巡り、'),
('JPN', '约书亚记', 6, 3, 3, '民に命じた。「あなたがたの神、主の契約の箱を見、さらにレビ人の祭司たちがそれを担いでいるのを見たら、自分のいる場所を出発して、その後を進みなさい。'),
('JPN', '约书亚记', 6, 3, 4, 'あなたがたが行くべき道を知るためである。あなたがたは今まで、この道を通ったことがないからだ。ただし、あなたがたと箱の間に二千キュビトほどの距離をおけ。箱に近づいてはならない。」'),
('JPN', '约书亚记', 6, 3, 5, 'ヨシュアは民に言った。「あなたがたは自らを聖別しなさい。明日、主があなたがたのただ中で不思議を行われるから。」'),
('JPN', '约书亚记', 6, 3, 6, 'ヨシュアは祭司たちに「契約の箱を担ぎ、民の先頭に立って渡りなさい」と命じた。そこで彼らは契約の箱を担ぎ、民の先頭に立って進んだ。'),
('JPN', '约书亚记', 6, 3, 7, '主はヨシュアに告げられた。「今日から全イスラエルの目の前で、わたしはあなたを大いなる者とする。わたしがモーセとともにいたように、あなたとともにいることを彼らが知るためである。'),
('JPN', '约书亚记', 6, 3, 8, 'あなたは契約の箱を担ぐ祭司たちに『ヨルダン川の水際に来たら、ヨルダン川の中に立ち続けよ』と命じよ。」'),
('JPN', '约书亚记', 6, 3, 9, 'ヨシュアはイスラエルの子らに言った。「ここに来て、あなたがたの神、主のことばを聞きなさい。」'),
('JPN', '约书亚记', 6, 3, 10, 'ヨシュアは言った。「生ける神があなたがたの中にいて、自分たちの前からカナン人、ヒッタイト人、ヒビ人、ペリジ人、ギルガシ人、アモリ人、エブス人を必ず追い払われることを、あなたがたは次のことで知るようになる。'),
('JPN', '约书亚记', 6, 3, 11, '見よ。全地の主の契約の箱が、あなたがたの先頭に立ってヨルダン川を渡ろうとしている。'),
('JPN', '约书亚记', 6, 3, 12, '今、部族ごとに一人ずつ、イスラエルの部族から十二人を取りなさい。'),
('JPN', '约书亚记', 6, 3, 13, '全地の主である主の箱を担ぐ祭司たちの足の裏が、ヨルダン川の水の中にとどまるとき、ヨルダン川の水は、川上から流れ下る水がせき止められ、一つの堰となって立ち止まる。」'),
('JPN', '约书亚记', 6, 3, 14, '民がヨルダン川を渡ろうとして彼らの天幕から出発したとき、契約の箱を担ぐ祭司たちは民の先頭にいた。'),
('JPN', '约书亚记', 6, 3, 15, '箱を担ぐ者たちがヨルダン川まで来たとき、ヨルダン川は刈り入れの期間中で、どこの川岸にも水があふれていた。ところが、箱を担ぐ祭司たちの足が水際の水に浸ると、'),
('JPN', '约书亚记', 6, 3, 16, '川上から流れ下る水が立ち止まった。一つの堰が、はるかかなた、ツァレタンのそばにある町アダムで立ち上がり、アラバの海、すなわち塩の海へ流れ下る水は完全にせき止められて、民はエリコに面したところを渡った。'),
('JPN', '约书亚记', 6, 3, 17, '主の契約の箱を担ぐ祭司たちは、ヨルダン川の真ん中の乾いたところにしっかりと立ち止まった。イスラエル全体は乾いたところを渡り、ついに民全員がヨルダン川を渡り終えた。'),
('JPN', '约书亚记', 6, 4, 1, '民全員がヨルダン川を渡り終えると、主はヨシュアに告げられた。'),
('JPN', '约书亚记', 6, 4, 2, '「民の中から部族ごとに一人ずつ十二人を取り、'),
('JPN', '约书亚记', 6, 4, 3, 'その者たちに命じよ。『ヨルダン川の真ん中、祭司たちが足をしっかりととどめたその場所から十二の石を取り、それらを携えて渡り、あなたがたが今夜泊まる宿営地に据えよ。』」'),
('JPN', '约书亚记', 6, 4, 4, 'そこでヨシュアは、イスラエルの子らの中から部族ごとに一人ずつ、あらかじめ任命しておいた十二人を呼び出した。'),
('JPN', '约书亚记', 6, 4, 5, 'ヨシュアは彼らに言った。「あなたがたの神、主の箱の前、ヨルダン川の真ん中へ渡って行き、イスラエルの子らの部族の数に合わせて各自が石を一つ、その肩に担ぎなさい。'),
('JPN', '约书亚记', 6, 4, 6, 'それがあなたがたの中で、しるしとなるようにするためだ。後になって、あなたがたの子どもたちが『この石はどういうものなのですか』と尋ねたとき、'),
('JPN', '约书亚记', 6, 4, 7, 'あなたがたは彼らにこう言いなさい。『ヨルダン川の水が主の契約の箱の前でせき止められたのだ。箱がヨルダン川を渡るとき、ヨルダン川の水はせき止められた。この石はイスラエルの子らにとって永久に記念となるのだ。』」'),
('JPN', '约书亚记', 6, 4, 8, 'イスラエルの子らはヨシュアが命じたとおりにした。主がヨシュアに告げられたとおり、イスラエルの部族の数に合わせて、ヨルダン川の真ん中から十二の石を取り、宿営地に携えて行って、そこに据えた。'),
('JPN', '约书亚记', 6, 4, 9, 'これらの十二の石はヨルダン川の真ん中で、契約の箱を担いだ祭司たちが足をとどめた場所にあったもので、ヨシュアがそれらを積み上げたのである。それらは今日までそこにある。'),
('JPN', '约书亚记', 6, 4, 10, '箱を担ぐ祭司たちは、民に告げるようにと主がヨシュアに命じられたことがすべて終わるまで、ヨルダン川の真ん中に立ち続けていた。すべてモーセがヨシュアに命じたとおりである。その間に民は急いで渡った。'),
('JPN', '约书亚记', 6, 4, 11, '民全員が渡り終えた後、民が見ている前で主の箱と祭司たちが渡った。'),
('JPN', '约书亚记', 6, 4, 12, 'ルベン人とガド人と、マナセの半部族は、モーセが彼らに告げたとおり、隊列を組んでイスラエルの子らの先頭を進んで行った。'),
('JPN', '约书亚记', 6, 4, 13, 'このようにして、武装した約四万の軍勢は主の前を、戦いのためにエリコの草原へと進んで行った。'),
('JPN', '约书亚记', 6, 4, 14, 'その日、主は全イスラエルの目の前で、ヨシュアを大いなる者とされた。それで彼らは、モーセを恐れたように、ヨシュアをその一生の間、恐れた。'),
('JPN', '约书亚记', 6, 4, 15, '主はヨシュアに告げられた。'),
('JPN', '约书亚记', 6, 4, 16, '「ヨルダン川から上がって来るよう、あかしの箱を担ぐ祭司たちに命じよ。」'),
('JPN', '约书亚记', 6, 4, 17, 'それでヨシュアは祭司たちに「ヨルダン川から上がって来なさい」と命じた。'),
('JPN', '约书亚记', 6, 4, 18, '主の契約の箱を担ぐ祭司たちがヨルダン川の真ん中から上がって来て、祭司たちの足の裏が水際の乾いた陸地に上がったとき、ヨルダン川の水は元の場所に戻り、以前のように、川岸いっぱいに満ちて流れた。'),
('JPN', '约书亚记', 6, 4, 19, 'さて、民は第一の月の十日にヨルダン川から上がって、エリコの東の境にあるギルガルに宿営した。'),
('JPN', '约书亚记', 6, 4, 20, 'ヨシュアは、ヨルダン川から取ったあの十二の石をギルガルに積み上げ、'),
('JPN', '约书亚记', 6, 4, 21, 'イスラエルの子らに言った。「後になって、あなたがたの子どもたちがその父たちに『この石はどういうものなのですか』と尋ねたときには、'),
('JPN', '约书亚记', 6, 4, 22, 'あなたがたは子どもたちに『イスラエルは乾いた地面の上を歩いて、このヨルダン川を渡ったのだ』と知らせなさい。'),
('JPN', '约书亚记', 6, 4, 23, 'あなたがたの神、主が、あなたがたが渡り終えるまで、あなたがたのためにヨルダン川の水を涸らしてくださったからだ。このことは、あなたがたの神、主が葦の海になさったこと、すなわち、私たちが渡り終えるまで、私たちのためにその海を涸らしてくださったのと同じである。'),
('JPN', '约书亚记', 6, 4, 24, 'それは、地のあらゆる民が主の手が強いことを知るためであり、あなたがたがいつも、自分たちの神、主を恐れるためである。」'),
('JPN', '约书亚记', 6, 5, 1, 'ヨルダン川の反対側、すなわち西側にいるアモリ人のすべての王たちと、海沿いにいるカナン人のすべての王たちは、主がイスラエル人の前で、彼らが渡り終えるまでヨルダン川の水を涸らしたことを聞くと、心が萎え、イスラエル人のゆえに気力を失ってしまった。'),
('JPN', '约书亚记', 6, 5, 2, 'そのとき、主はヨシュアに告げられた。「火打石の小刀を作り、もう一度イスラエルの子らに割礼を施せ。」'),
('JPN', '约书亚记', 6, 5, 3, 'ヨシュアは自ら火打石の小刀を作り、ギブアテ・ハ・アラロテでイスラエルの子らに割礼を施した。'),
('JPN', '约书亚记', 6, 5, 4, 'ヨシュアが割礼を施した理由はこうである。エジプトを出たすべての民のうち男子、すなわち戦士たちはすべて、エジプトを出てから途中で荒野で死んだ。'),
('JPN', '约书亚记', 6, 5, 5, '出て来た民はみな割礼を受けていたが、エジプトを出てから途中で荒野で生まれた民はみな、割礼を受けていなかった。'),
('JPN', '约书亚记', 6, 5, 6, 'イスラエルの子らは四十年間荒野を歩き回り、その間に民全体が、すなわちエジプトを出た戦士たち全員が、死に絶えてしまったからである。彼らが主の御声に聞き従わなかったので、私たちに与えると主が彼らの父祖たちに誓った地、乳と蜜の流れる地を、主は彼らには見せないと誓われたのである。'),
('JPN', '约书亚记', 6, 5, 7, 'そして、息子たちを彼らに代わって起こされた。ヨシュアは彼らに割礼を施したのである。彼らが途中で割礼を受けておらず、無割礼だったからである。'),
('JPN', '约书亚记', 6, 5, 8, '民はみな割礼を受けると、傷が治るまで宿営の自分たちのところにとどまった。'),
('JPN', '约书亚记', 6, 5, 9, '主はヨシュアに告げられた。「今日、わたしはエジプトの恥辱をあなたがたから取り除いた。」それで、その場所の名はギルガルと呼ばれた。今日もそうである。'),
('JPN', '约书亚记', 6, 5, 10, 'イスラエルの子らはギルガルに宿営し、その月の十四日の夕方、エリコの草原で過越のいけにえを献げた。'),
('JPN', '约书亚记', 6, 5, 11, '過越のいけにえを献げた翌日、彼らはその地の産物、種なしパンと炒り麦を、その日のうちに食べた。'),
('JPN', '约书亚记', 6, 5, 12, 'マナは、彼らがその地の産物を食べた翌日からやみ、イスラエルの子らがマナを得ることはもうなかった。その年、彼らはカナンの地で収穫した物を食べた。'),
('JPN', '约书亚记', 6, 5, 13, 'ヨシュアがエリコにいたとき、目を上げて見ると、一人の人が抜き身の剣を手に持って彼の前方に立っていた。ヨシュアは彼のところへ歩み寄って言った。「あなたは私たちの味方ですか、それとも敵ですか。」'),
('JPN', '约书亚记', 6, 5, 14, '彼は言った。「いや、わたしは主の軍の将として、今、来たのだ。」ヨシュアは顔を地に付けて伏し拝み、彼に言った。「わが主は、何をこのしもべに告げられるのですか。」'),
('JPN', '约书亚记', 6, 5, 15, '主の軍の将はヨシュアに言った。「あなたの足の履き物を脱げ。あなたの立っている所は聖なる場所である。」そこで、ヨシュアはそのようにした。'),
('JPN', '约书亚记', 6, 6, 1, 'エリコはイスラエルの子らの前に城門を堅く閉ざして、出入りする者はいなかった。'),
('JPN', '约书亚记', 6, 6, 2, '主はヨシュアに告げられた。「見よ、わたしはエリコとその王、勇士たちをあなたの手に渡した。'),
('JPN', '约书亚记', 6, 6, 3, 'あなたがた戦士はみな町の周りを回れ。町の周囲を一周せよ。六日間そのようにせよ。'),
('JPN', '约书亚记', 6, 6, 4, '七人の祭司たちは七つの雄羊の角笛を手にして、箱の前を進め。七日目には、あなたがたは七回、町の周りを回り、祭司たちは角笛を吹き鳴らせ。'),
('JPN', '约书亚记', 6, 6, 5, '祭司たちが雄羊の角笛を長く吹き鳴らし、あなたがたがその角笛の音を聞いたら、民はみな大声でときの声をあげよ。そうすれば町の城壁は崩れ落ちる。民はそれぞれ、まっすぐに攻め上れ。」'),
('JPN', '约书亚记', 6, 6, 6, 'ヌンの子ヨシュアは祭司たちに呼びかけた。「契約の箱を担ぎなさい。七人の祭司たちは七つの雄羊の角笛を持ち、主の箱の前を進みなさい。」'),
('JPN', '约书亚记', 6, 6, 7, 'そして民に言った。「進んで行き、町の周りを回りなさい。武装した者たちは主の箱の前を進みなさい。」'),
('JPN', '约书亚记', 6, 6, 8, 'ヨシュアが民にそう言ったとき、七人の祭司たちは、七つの雄羊の角笛を持って主の前を進み、角笛を吹き鳴らした。主の契約の箱はそのうしろを進み、'),
('JPN', '约书亚记', 6, 6, 9, '武装した者たちは、角笛を吹き鳴らす祭司たちの前を行き、しんがりは角笛を吹き鳴らしながら箱のうしろを進んだ。'),
('JPN', '约书亚记', 6, 6, 10, 'ヨシュアは民に命じた。「あなたがたはときの声をあげてはならない。声を聞かせてはならない。口からことばを出してはならない。『ときの声をあげよ』と私が言うその日に、ときの声をあげよ。」'),
('JPN', '约书亚记', 6, 6, 11, 'こうして主の箱は町の周りを回り、その周囲を一周した。彼らは宿営に帰り、宿営で夜を過ごした。'),
('JPN', '约书亚记', 6, 6, 12, '翌朝ヨシュアは早く起き、祭司たちは主の箱を担いだ。'),
('JPN', '约书亚记', 6, 6, 13, '七人の祭司たちは、七つの雄羊の角笛を持って主の箱の前を進み、角笛を吹き鳴らした。武装した者たちは、彼らの先頭に立って行き、しんがりは角笛を吹き鳴らしながら主の箱のうしろを進んだ。'),
('JPN', '约书亚记', 6, 6, 14, '彼らは二日目も町の周りを一周回り、宿営に帰った。六日間そのようにした。'),
('JPN', '约书亚记', 6, 6, 15, '七日目、朝早く夜が明けかかるころ彼らは起き、同じようにして町の周りを七周回った。この日だけは町の周りを七周回った。'),
('JPN', '约书亚记', 6, 6, 16, '七周目に祭司たちが角笛を吹き鳴らしたとき、ヨシュアは民に言った。「ときの声をあげよ。主がこの町をあなたがたに与えてくださったからだ。'),
('JPN', '约书亚记', 6, 6, 17, 'この町とその中にあるすべてのものは主のために聖絶せよ。遊女ラハブと、その家にともにいる者たちだけは、みな生かしておけ。彼女は私たちが送った使いたちをかくまってくれたからだ。'),
('JPN', '约书亚记', 6, 6, 18, 'あなたがたは聖絶の物には手を出すな。あなたがた自身が聖絶されないようにするため、すなわち、聖絶の物の一部を取ってイスラエルの宿営を聖絶の物とし、これにわざわいをもたらさないようにするためである。'),
('JPN', '约书亚记', 6, 6, 19, 'ただし、銀や金、および青銅や鉄の器はすべて主のために聖別されたものである。それらは主の宝物倉に入れよ。」'),
('JPN', '约书亚记', 6, 6, 20, '民はときの声をあげ、祭司たちは角笛を吹き鳴らした。角笛の音を聞いて民が大声でときの声をあげると、城壁は崩れ落ちた。そこで民はそれぞれ、まっすぐに攻め上り、その町を攻め取り、'),
('JPN', '约书亚记', 6, 6, 21, '町のものをすべて、男も女も若者も年寄りも、また牛、羊、ろばも剣の刃で聖絶した。'),
('JPN', '约书亚记', 6, 6, 22, 'ところで、ヨシュアはこの地を偵察した二人の男に言った。「あの遊女の家に行き、あなたがたが彼女に誓ったとおり、その女とその女に連なるすべての者を連れ出しなさい。」'),
('JPN', '约书亚记', 6, 6, 23, '偵察した若者たちは行って、ラハブとその父、母、兄弟、彼女に連なるすべての者を連れ出した。彼女の親族をみな連れ出し、イスラエルの宿営の外にとどめておいた。'),
('JPN', '约书亚记', 6, 6, 24, '彼らはその町とその中にあるすべてのものを火で焼いた。銀や金、および青銅や鉄の器だけは主の家の宝物倉に納めた。'),
('JPN', '约书亚记', 6, 6, 25, 'しかし、遊女ラハブと、その一族と、彼女に連なるすべての者をヨシュアが生かしておいたので、彼女はイスラエルの中に住んで今日に至っている。エリコを偵察させようとしてヨシュアが送った使いたちを、彼女がかくまったからである。'),
('JPN', '约书亚记', 6, 6, 26, 'ヨシュアは、そのとき誓った。「この町エリコの再建を企てる者は主の前にのろわれよ。その礎を据える者は長子を失い、その門を建てる者は末の子を失う。」'),
('JPN', '约书亚记', 6, 6, 27, '主がヨシュアとともにおられたので、彼のうわさはこの地にあまねく広まった。'),
('JPN', '约书亚记', 6, 7, 1, 'しかし、イスラエルの子らは聖絶の物のことで主の信頼を裏切った。ユダ部族のゼラフの子ザブディの子であるカルミの子アカンが、聖絶の物の一部を取った。それで、主の怒りがイスラエルの子らに向かって燃え上がった。'),
('JPN', '约书亚记', 6, 7, 2, 'ヨシュアは部下をエリコからベテルの東、ベテ・アベンの近くにあるアイに遣わし、彼らに言った。「上って行って、あの地を偵察せよ。」部下たちは上って行って、アイを偵察した。'),
('JPN', '约书亚记', 6, 7, 3, '彼らはヨシュアのもとに帰って来て言った。「民をみな上って行かせるには及びません。二、三千人ぐらいを上らせて、アイを討たせるとよいでしょう。彼らはわずかですから、民をみな送って骨折らせるには及びません。」'),
('JPN', '约书亚记', 6, 7, 4, 'そこで民のうち、およそ三千人がそこに上って行ったが、彼らはアイの人々の前から逃げた。'),
('JPN', '约书亚记', 6, 7, 5, 'アイの人々は彼らの中の三十六人を打ち殺し、彼らを門の前からシェバリムまで追って、下り坂で彼らを討った。民の心は萎え、水のようになった。'),
('JPN', '约书亚记', 6, 7, 6, 'ヨシュアは衣を引き裂き、イスラエルの長老たちとともに、主の箱の前で夕方まで地にひれ伏し、自分たちの頭にちりをかぶった。'),
('JPN', '约书亚记', 6, 7, 7, 'ヨシュアは言った。「ああ、神、主よ。あなたはどうして、この民にヨルダン川をあえて渡らせ、私たちをアモリ人の手に渡して滅ぼそうとされるのですか。私たちは、ヨルダンの川向こうに居残ることで満足していたのです。'),
('JPN', '约书亚记', 6, 7, 8, 'ああ、主よ。イスラエルが敵の前に背を見せた今となっては、何を申し上げることができるでしょう。'),
('JPN', '约书亚记', 6, 7, 9, 'カナン人やこの地の住民がみな、これを聞いて私たちを攻め囲み、私たちの名を地から断ってしまうでしょう。あなたは、あなたの大いなる御名のために何をなさるのですか。」'),
('JPN', '约书亚记', 6, 7, 10, '主はヨシュアに告げられた。「立て。なぜ、あなたはひれ伏しているのか。'),
('JPN', '约书亚记', 6, 7, 11, 'イスラエルは罪ある者となった。彼らはわたしが命じたわたしの契約を破った。聖絶の物の一部を取り、盗み、欺いて、それを自分のものの中に入れることまでした。'),
('JPN', '约书亚记', 6, 7, 12, 'だから、イスラエルの子らは敵の前に立つことができず、敵の前に背を見せたのだ。彼らが聖絶の者となったからである。あなたがたの中から、その聖絶の物を滅ぼし尽くしてしまわないなら、わたしはもはやあなたがたとともにはいない。'),
('JPN', '约书亚记', 6, 7, 13, '立て。民を聖別せよ。そしてこう言え。あなたがたは、明日のために自らを聖別しなさい。イスラエルの神、主がこう告げられるからだ。『イスラエルよ、あなたの中に聖絶の物がある。あなたがたがその聖絶の物を、あなたがたの中から取り除くまでは、敵の前に立つことができない。'),
('JPN', '约书亚记', 6, 7, 14, '明日の朝、部族ごとに進み出よ。主がくじで取り分ける部族は氏族ごとに進み出、主がくじで取り分ける氏族は家族ごとに進み出、主がくじで取り分ける家族は男一人ひとり進み出よ。'),
('JPN', '约书亚记', 6, 7, 15, '聖絶の物のことでくじで取り分けられた者は、彼も彼に属するすべてのものも、火で焼かれなければならない。彼が主の契約を破ったからであり、彼がイスラエルの中で恥辱となることをしたからである。』」'),
('JPN', '约书亚记', 6, 7, 16, '翌朝ヨシュアは早く起き、イスラエルを部族ごとに進み出させた。ユダ部族がくじで取り分けられた。'),
('JPN', '约书亚记', 6, 7, 17, 'ユダの諸氏族を進み出させると、ゼラフ人の氏族がくじで取り分けられた。ゼラフ人の氏族を男一人ひとり進み出させると、ザブディがくじで取り分けられた。'),
('JPN', '约书亚记', 6, 7, 18, 'ザブディの家族を男一人ひとり進み出させると、ユダ部族のゼラフの子ザブディの子カルミの子のアカンが、くじで取り分けられた。'),
('JPN', '约书亚记', 6, 7, 19, 'ヨシュアはアカンに言った。「わが子よ。イスラエルの神、主に栄光を帰し、主に告白しなさい。おまえが何をしたのか、私に告げなさい。私に隠してはいけない。」'),
('JPN', '约书亚记', 6, 7, 20, 'アカンはヨシュアに答えた。「確かに、私はイスラエルの神、主に対して罪を犯しました。私は次のようなことをしました。'),
('JPN', '约书亚记', 6, 7, 21, '私は分捕り物の中に、シンアルの美しい外套一着と、銀二百シェケルと、重さ五十シェケルの金の延べ棒一本があるのを見て欲しくなり、それらを取りました。それらは今、私の天幕の中の地面の下に隠してあり、銀もそこにあります。」'),
('JPN', '约书亚记', 6, 7, 22, 'そこでヨシュアは使いたちを送った。彼らは天幕に走って行った。すると、それらはアカンの天幕に隠されていて、銀もその下にあった。'),
('JPN', '约书亚记', 6, 7, 23, '使いたちはそれらを天幕の中から取り出し、ヨシュアとすべてのイスラエルの子らのところに持って来て、主の前に置いた。')
on conflict (version, book, chapter, verse) do nothing;
insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('JPN', '约书亚记', 6, 7, 24, 'ヨシュアは全イスラエルとともに、ゼラフの子アカンと銀、外套、金の延べ棒、および彼の息子、娘、牛、ろば、羊、天幕、それに彼のすべての所有物を取って、アコルの谷へ運んだ。'),
('JPN', '约书亚记', 6, 7, 25, 'ヨシュアは言った。「なぜ、おまえは私たちにわざわいをもたらしたのか。主は今日、おまえにわざわいをもたらされる。」全イスラエルは彼を石で打ち殺し、彼の所有物を火で焼き、それらに石を投げつけた。'),
('JPN', '约书亚记', 6, 7, 26, '人々はアカンの上に石くれの大きな山を積み上げた。今日もそのままである。主は燃える怒りを収められた。それで、その場所の名はアコルの谷と呼ばれた。今日もそうである。'),
('JPN', '约书亚记', 6, 8, 1, '主はヨシュアに言われた。「恐れてはならない。おののいてはならない。戦う民をすべて率い、立ってアイに攻め上れ。見よ、わたしはアイの王と、その民、その町、その地をあなたの手に与えた。'),
('JPN', '约书亚记', 6, 8, 2, 'あなたがエリコとその王にしたとおりに、アイとその王にもせよ。その分捕り物と家畜だけは、あなたがたの戦利品としてよい。あなたは町の裏手に伏兵を置け。」'),
('JPN', '约书亚记', 6, 8, 3, 'そこでヨシュアは戦う民すべてとともに、アイに上って行くために立ち上がった。ヨシュアは三万人の勇士を選んで夜のうちに派遣し、'),
('JPN', '约书亚记', 6, 8, 4, '彼らに命じた。「見よ、あなたがたは町の裏手から町に向かう伏兵だ。町からあまり遠く離れないで、みな身構えていなさい。'),
('JPN', '约书亚记', 6, 8, 5, '私と、私とともにいる兵はみな町に近づく。アイの人々がこの前と同じように、私たちに立ち向かって出て来たら、私たちは彼らの前から逃げることにする。'),
('JPN', '约书亚记', 6, 8, 6, '彼らは私たちを追って出て来るので、私たちは彼らを町からおびき出すことになる。彼らは『この前と同じように、われわれの前を逃げて行く』と言うだろうから。私たちは彼らの前で逃げることにする。'),
('JPN', '约书亚记', 6, 8, 7, 'あなたがたは伏せているところから立ち上がり、町を占領せよ。あなたがたの神、主がその町をあなたがたの手に渡される。'),
('JPN', '约书亚记', 6, 8, 8, 'その町を攻め取ったら、その町に火を放て。主のことばどおりに行うのだ。見よ、私はあなたがたに命じる。」'),
('JPN', '约书亚记', 6, 8, 9, 'ヨシュアは彼らを派遣し、彼らは待ち伏せの場所へ行き、ベテルとアイの間、アイの西側にとどまった。ヨシュアはその夜、兵とともに夜を過ごした。'),
('JPN', '约书亚记', 6, 8, 10, '翌朝ヨシュアは早く起きて、兵を召集し、イスラエルの長老たちとともに、兵の先頭に立ってアイに上って行った。'),
('JPN', '约书亚记', 6, 8, 11, '彼とともにいた戦う民はみな、上って行った。彼らは町の前に近づき、アイの北側に陣を敷いた。彼とアイの間には谷があった。'),
('JPN', '约书亚记', 6, 8, 12, '彼は約五千人を取り、ベテルとアイの間、町の西側に伏兵として配置した。'),
('JPN', '约书亚记', 6, 8, 13, '兵は町の北側に全陣営を置き、町の西側にはその後陣を置いた。ヨシュアはその夜、谷の中に下って行った。'),
('JPN', '约书亚记', 6, 8, 14, 'アイの王がそのことに気づくと、町の男たち、王とその兵はみな、急いで朝早く起き出し、イスラエルに立ち向かって戦うために、アラバの手前の決めておいた場所に出て来た。しかし、王は町の裏手に伏兵がいることを知らなかった。'),
('JPN', '约书亚记', 6, 8, 15, 'ヨシュアと全イスラエルは彼らの前で打たれるふりをし、荒野への道を逃げた。'),
('JPN', '约书亚记', 6, 8, 16, 'アイにいた兵はみな彼らの後を追うために呼び集められ、ヨシュアを追撃し、町から誘い出された。'),
('JPN', '约书亚记', 6, 8, 17, 'そのため、イスラエルの後を追って出なかった者は、アイとベテルに一人もいなかった。彼らは町を開け放しのまま捨てておいて、イスラエルを追撃した。'),
('JPN', '约书亚记', 6, 8, 18, '主はヨシュアに告げられた。「あなたの手にある投げ槍をアイの方に伸ばせ。わたしがアイをあなたの手に渡すから。」ヨシュアは手にある投げ槍を町の方に伸ばした。'),
('JPN', '约书亚记', 6, 8, 19, 'すると、伏兵はすぐその場所から立ち上がった。ヨシュアが手を伸ばすやいなや彼らは走り、町に入ってそれを攻め取り、ただちに町に火を放った。'),
('JPN', '约书亚记', 6, 8, 20, 'アイの人々はうしろを振り返って見た。すると、町の煙が天に立ち上っていて、彼らには、どちらにも逃げる手立てがなかった。荒野へ逃げていたイスラエルの兵は、追って来た者たちの方に向き直った。'),
('JPN', '约书亚记', 6, 8, 21, 'ヨシュアと全イスラエルは、伏兵が町を攻め取り、町の煙が立ち上るのを見たので、引き返してアイの人々を討った。'),
('JPN', '约书亚记', 6, 8, 22, '伏兵たちは町から出て来て彼らに向かった。そのため彼らは両側からイスラエルの挟み撃ちにあった。ヨシュアたちは、彼らを打ち殺し、生き残った者も、逃れた者も一人も残されないまでにした。'),
('JPN', '约书亚记', 6, 8, 23, 'しかし、アイの王は生け捕りにして、ヨシュアのもとに連れて来た。'),
('JPN', '约书亚记', 6, 8, 24, 'イスラエルがアイのすべての住民を野で、すなわち彼らが追って来た荒野で殺したとき、アイの住民はみな一人残らず剣の刃に倒れた。全イスラエルはアイに引き返し、町を剣の刃で討った。'),
('JPN', '约书亚记', 6, 8, 25, 'その日、倒れた者は男女合わせて一万二千人、アイのすべての人々であった。'),
('JPN', '约书亚记', 6, 8, 26, 'ヨシュアはアイの住民をことごとく聖絶するまで、投げ槍を差し出した手をもとに戻さなかった。'),
('JPN', '约书亚记', 6, 8, 27, 'イスラエルは主がヨシュアに命じられたことばのとおり、その町の家畜と分捕り物だけを自分たちの戦利品とした。'),
('JPN', '约书亚记', 6, 8, 28, 'ヨシュアはアイを焼き、永久に荒れ果てた丘とした。今日もそうである。'),
('JPN', '约书亚记', 6, 8, 29, 'さらに、ヨシュアはアイの王を夕方まで木にかけてさらし、日の入るころ人々に命じた。それで彼らはその死体を木から降ろし、町の門の入り口に投げ捨て、その上に大きな石塚を積み上げた。今日もそうである。'),
('JPN', '约书亚记', 6, 8, 30, 'それからヨシュアはエバル山に、イスラエルの神、主のために一つの祭壇を築いた。'),
('JPN', '约书亚记', 6, 8, 31, 'それは、主のしもべモーセがイスラエルの子らに命じたとおり、またモーセの律法の書に記されているとおり、鉄の道具を当てない自然のままの石の祭壇であった。彼らはその上で主に全焼のささげ物を献げ、交わりのいけにえを献げた。'),
('JPN', '约书亚记', 6, 8, 32, 'ヨシュアはその場所で、モーセがイスラエルの子らの前で書いた律法の写しを、石の上に書いた。'),
('JPN', '约书亚记', 6, 8, 33, '全イスラエル、その長老たち、つかさたち、さばき人たちは、寄留者もこの地で生まれた者も同様に、主の契約の箱を担ぐレビ人の祭司たちの前で、箱のこちら側と向こう側とに分かれ、半分はゲリジム山の前に、もう半分はエバル山の前に立った。それは主のしもべモーセが以前命じたように、イスラエルの民を祝福するためであった。'),
('JPN', '约书亚记', 6, 8, 34, 'その後、ヨシュアは、みおしえの書に記されているとおりに、律法のすべてのことばを、祝福ものろいも読み上げた。'),
('JPN', '约书亚记', 6, 8, 35, 'モーセが命じたすべてのことばの中で、ヨシュアが、イスラエルの集会全体、および女と子どもたち、および彼らの間で生活する寄留者の前で読み上げなかったことばは、一つもなかった。'),
('JPN', '约书亚记', 6, 9, 1, 'さて、ヨルダン川の西側の山地、シェフェラ、レバノンに至る大海の全沿岸のヒッタイト人、アモリ人、カナン人、ペリジ人、ヒビ人、エブス人の王たちはみな、これを聞くと、'),
('JPN', '约书亚记', 6, 9, 2, 'ともに集まり、一つになってヨシュアおよびイスラエルと戦おうとした。'),
('JPN', '约书亚记', 6, 9, 3, 'ギブオンの住民たちは、ヨシュアがエリコとアイに対して行ったことを聞くと、'),
('JPN', '约书亚记', 6, 9, 4, '彼らもまた策略をめぐらし、変装をした。古びた袋と、古びて破れて継ぎ当てをしたぶどう酒の皮袋をろばに負わせ、'),
('JPN', '约书亚记', 6, 9, 5, '繕った古い履き物を足にはき、古びた上着を身に着けた。彼らの食糧のパンはみな乾いて、ぼろぼろになっていた。'),
('JPN', '约书亚记', 6, 9, 6, '彼らはギルガルの陣営のヨシュアのところに来て、彼とイスラエルの人々に言った。「私たちは遠い国から参りました。ですから今、私たちと盟約を結んでください。」'),
('JPN', '约书亚记', 6, 9, 7, 'イスラエルの子らはそのヒビ人たちに言った。「おそらく、あなたがたは、私たちのただ中に住んでいるのだろう。どうして私たちがあなたがたと盟約を結べるだろうか。」'),
('JPN', '约书亚记', 6, 9, 8, '彼らはヨシュアに言った。「私たちは、あなたのしもべです。」ヨシュアは彼らに言った。「あなたがたは何者か。どこから来たのか。」'),
('JPN', '约书亚记', 6, 9, 9, '彼らは彼に言った。「しもべどもは、あなたの神、主の名のゆえにとても遠い国から参りました。主のうわさ、および主がエジプトで行われたすべてのこと、'),
('JPN', '约书亚记', 6, 9, 10, '主がヨルダンの川向こうのアモリ人の二人の王、ヘシュボンの王シホン、およびアシュタロテにいたバシャンの王オグになさった、すべてのことを聞いたからです。'),
('JPN', '约书亚记', 6, 9, 11, '私たちの長老や、私たちの国の住民はみな私たちに言いました。『旅のための食糧を手にして彼らに会いに出かけなさい。そして彼らに、「私たちは、あなたがたのしもべです。今、どうか私たちと盟約を結んでください」と言いなさい。』'),
('JPN', '约书亚记', 6, 9, 12, 'これが私たちのパンです。私たちがあなたがたのところに来ようと出た日、それぞれ自分の家で食糧として準備したときには、まだ温かかったのですが、今はご覧のとおり、干からびて、ぼろぼろになってしまいました。'),
('JPN', '约书亚记', 6, 9, 13, 'これがぶどう酒の皮袋です。私たちがこれらを満たしたときには新しかったのですが、ご覧のとおり破れてしまいました。これが私たちの上着と私たちの履き物です。とても長い旅のため古びてしまいました。」'),
('JPN', '约书亚记', 6, 9, 14, 'そこで人々は彼らの食糧の一部を受け取った。しかし、主の指示を求めなかった。'),
('JPN', '约书亚记', 6, 9, 15, 'ヨシュアは彼らと和を講じ、彼らを生かしておく盟約を結んだ。会衆の上に立つ族長たちは彼らに誓った。'),
('JPN', '约书亚记', 6, 9, 16, '彼らと盟約を結んでから三日たったとき、人々は彼らが近くの者たちで、自分たちのただ中に住んでいるということを聞いた。'),
('JPN', '约书亚记', 6, 9, 17, 'そこでイスラエルの子らは出発し、三日目に彼らの町々に着いた。彼らの町々とはギブオン、ケフィラ、ベエロテ、およびキルヤテ・エアリムであった。'),
('JPN', '约书亚记', 6, 9, 18, 'イスラエルの子らは彼らを討たなかった。会衆の上に立つ族長たちがイスラエルの神、主にかけて彼らに誓ったからである。しかし、全会衆は族長たちに向かって不平を言った。'),
('JPN', '约书亚记', 6, 9, 19, '族長たちはみな全会衆に言った。「私たちはイスラエルの神、主にかけて彼らに誓った。だから今、私たちは彼らに触れることはできない。'),
('JPN', '约书亚记', 6, 9, 20, '私たちは彼らにこうしよう。彼らを生かしておこう。そうすれば、私たちが彼らに誓った誓いのために、御怒りが私たちの上に下ることはないだろう。」'),
('JPN', '约书亚记', 6, 9, 21, '族長たちは全会衆に言った。「彼らを生かしておこう。」彼らは全会衆のために薪を割る者、水を汲む者となった。族長たちが彼らについて言ったとおりである。'),
('JPN', '约书亚记', 6, 9, 22, 'ヨシュアは彼らを呼び寄せて、彼らに言った。「あなたがたは私たちのただ中に住んでいながら、なぜ、『私たちは、あなたがたからとても遠いところの者です』と言って私たちを欺いたのか。'),
('JPN', '约书亚记', 6, 9, 23, '今、あなたがたはのろわれる。あなたがたの中から、奴隷たち、私の神の家のために薪を割る者と水を汲む者が絶えることはない。」'),
('JPN', '约书亚记', 6, 9, 24, '彼らはヨシュアに答えた。「しもべどもは、はっきり知らされました。あなたの神、主がこの全土をあなたがたに与え、その地の全住民をあなたがたの前から根絶やしにするように、しもべモーセにお命じになったことを。それで私たちは、自分のいのちのことであなたがたを非常に恐れ、このようなことをしたのです。'),
('JPN', '约书亚记', 6, 9, 25, 'ご覧ください。今、私たちはあなたの手の中にあります。あなたのお気に召すように、お目にかなうように私たちを扱ってください。」'),
('JPN', '约书亚记', 6, 9, 26, 'ヨシュアは彼らが言うようにし、彼らをイスラエルの子らの手から救った。それで彼らは殺されなかった。'),
('JPN', '约书亚记', 6, 9, 27, 'ヨシュアはその日、彼らを会衆のため、また主の祭壇のため、主が選ばれる場所で薪を割る者と水を汲む者とし、今日に至っている。'),
('JPN', '约书亚记', 6, 10, 1, 'エルサレムの王アドニ・ツェデクは、ヨシュアがアイを攻め取って、それを聖絶し、エリコとその王にしたようにアイとその王にもしたこと、またギブオンの住民がイスラエルと和を講じて、彼らのただ中にいることを聞いた。'),
('JPN', '约书亚记', 6, 10, 2, '彼とその民は非常に恐れた。ギブオンが王国の都の一つのように大きな町であり、またアイよりも大きく、そこの人々がみな勇士だったからである。'),
('JPN', '约书亚记', 6, 10, 3, 'エルサレムの王アドニ・ツェデクはヘブロンの王ホハム、ヤルムテの王ピルアム、ラキシュの王ヤフィア、エグロンの王デビルに人を遣わして言った。'),
('JPN', '约书亚记', 6, 10, 4, '「私のところに上って来て、私を助けてください。ギブオンを討ちましょう。ギブオンがヨシュア、およびイスラエルの子らと和を講じたからです。」'),
('JPN', '约书亚记', 6, 10, 5, 'それでアモリ人の五人の王、すなわち、エルサレムの王、ヘブロンの王、ヤルムテの王、ラキシュの王、エグロンの王、彼らとその全陣営は集結し、上って行ってギブオンに向かって陣を敷き、戦いを挑んだ。'),
('JPN', '约书亚记', 6, 10, 6, 'ギブオンの人々はヨシュアのところ、ギルガルの陣営に人を遣わして言った。「しもべどもから手を引かないで、急いで私たちのところに上って来て、私たちを救い、助けてください。山地に住むアモリ人の王たちがみな、私たちに向かって集まっているのです。」'),
('JPN', '约书亚记', 6, 10, 7, 'ヨシュアはすべての戦う民たちとすべての勇士たちとともに、ギルガルから上って行った。'),
('JPN', '约书亚记', 6, 10, 8, '主はヨシュアに告げられた。「彼らを恐れてはならない。わたしが彼らをあなたの手に渡したからだ。あなたの前に立ちはだかる者は彼らの中に一人としていない。」'),
('JPN', '约书亚记', 6, 10, 9, 'ヨシュアは夜通しギルガルから上って行って、突然彼らを襲った。'),
('JPN', '约书亚记', 6, 10, 10, '主は彼らをイスラエルの前でかき乱された。イスラエルはギブオンで彼らを激しく討ち、ベテ・ホロンの上り坂を通って彼らを追い、アゼカとマケダに至るまで彼らを討った。'),
('JPN', '约书亚记', 6, 10, 11, '彼らがイスラエルの前から逃げて、ベテ・ホロンの下り坂にいたとき、主が天から彼らの上に、大きな石をアゼカに至るまで降らせられたので、彼らは死んだ。イスラエルの子らが剣で殺した者よりも、雹の石で死んだ者のほうが多かった。'),
('JPN', '约书亚记', 6, 10, 12, '主がアモリ人をイスラエルの子らに渡されたその日、ヨシュアは主に語り、イスラエルの見ている前で言った。「太陽よ、ギブオンの上で動くな。月よ、アヤロンの谷で。」'),
('JPN', '约书亚记', 6, 10, 13, '民がその敵に復讐するまで、太陽は動かず、月はとどまった。これは『ヤシャルの書』に確かに記されている。太陽は天の中間にとどまって、まる一日ほど、急いで沈むことはなかった。'),
('JPN', '约书亚记', 6, 10, 14, '主が人の声を聞き入れられたこのような日は、前にも後にもなかった。主がイスラエルのために戦われたからである。'),
('JPN', '约书亚记', 6, 10, 15, 'ヨシュアは全イスラエルとともにギルガルの陣営に戻った。'),
('JPN', '约书亚记', 6, 10, 16, 'これらの五人の王たちは逃げ、マケダの洞穴に隠れた。'),
('JPN', '约书亚记', 6, 10, 17, 'すると、マケダの洞穴に隠れている五人の王たちが見つかったという知らせがヨシュアに入った。'),
('JPN', '约书亚记', 6, 10, 18, 'ヨシュアは言った。「洞穴の口に大きな石を転がし、そのそばに人を置いて彼らを見張りなさい。'),
('JPN', '约书亚记', 6, 10, 19, 'しかし、あなたがたは、そこにとどまってはならない。敵の後を追い、彼らのしんがりを攻撃しなさい。彼らを自分の町に逃げ込ませてはならない。あなたがたの神、主が彼らをあなたがたの手に渡されたからだ。」'),
('JPN', '约书亚记', 6, 10, 20, 'ヨシュアとイスラエルの子らが非常に激しく彼らを討ち、ついに彼らが一掃されるまで攻撃し終わったとき、彼らのうちの生き残った者たちは城壁のある町々に逃げ込んだ。'),
('JPN', '约书亚记', 6, 10, 21, '兵はみな無事にマケダの陣営のヨシュアのもとに戻った。イスラエルの子らをののしる者は一人もいなかった。'),
('JPN', '约书亚记', 6, 10, 22, 'ヨシュアは言った。「洞穴の口を開き、あの五人の王たちを、その洞穴から私のもとに引き出して来なさい。」'),
('JPN', '约书亚记', 6, 10, 23, '彼らはそのとおりにした。その五人の王たち、すなわち、エルサレムの王、ヘブロンの王、ヤルムテの王、ラキシュの王、エグロンの王を洞穴から彼のもとに引き出して来た。'),
('JPN', '约书亚记', 6, 10, 24, '彼らがその王たちをヨシュアのもとに引き出したとき、ヨシュアはイスラエルのすべての人を呼び寄せ、自分と一緒に行った戦士の指揮官たちに言った。「近寄って、この王たちの首を踏みつけなさい。」彼らは近寄り、王たちの首を踏みつけた。'),
('JPN', '约书亚记', 6, 10, 25, 'ヨシュアは彼らに言った。「恐れてはならない。おののいてはならない。強くあれ。雄々しくあれ。あなたがたの戦うすべての敵に主がこのようにされる。」'),
('JPN', '约书亚记', 6, 10, 26, 'その後、ヨシュアは王たちを討って殺し、五本の木にかけ、夕方まで木にかけておいた。'),
('JPN', '约书亚记', 6, 10, 27, '日の入るころになって、ヨシュアは命じて彼らを木から降ろし、彼らが隠れていた洞穴の中に投げ込んだ。その洞穴の口には大きな石が置かれ、今日に至っている。'),
('JPN', '约书亚记', 6, 10, 28, 'その日、ヨシュアはマケダを攻め取り、この町とその王を剣の刃で討った。彼らとそこにいたすべての者を聖絶し、一人も残さなかった。彼はエリコの王にしたようにマケダの王にした。'),
('JPN', '约书亚记', 6, 10, 29, 'ヨシュアは全イスラエルとともにマケダからリブナに進み、リブナと戦った。'),
('JPN', '约书亚记', 6, 10, 30, '主は、この町もその王もイスラエルの手に渡された。それで彼は、その町とそこにいたすべての者を剣の刃で討ち、そこに一人も残さなかった。彼はエリコの王にしたようにその王にした。'),
('JPN', '约书亚记', 6, 10, 31, 'ヨシュアは、全イスラエルとともにリブナからラキシュに進み、これに向かって陣を敷き、ラキシュと戦った。'),
('JPN', '约书亚记', 6, 10, 32, '主はラキシュをイスラエルの手に渡された。ヨシュアは二日目にそれを攻め取り、その町と、そこにいたすべての者を剣の刃で討った。すべて彼がリブナにしたとおりであった。'),
('JPN', '约书亚记', 6, 10, 33, 'そのとき、ゲゼルの王ホラムがラキシュを助けようとして上って来た。ヨシュアは、ホラムとその民を一人も残さず討った。'),
('JPN', '约书亚记', 6, 10, 34, 'ヨシュアは、全イスラエルとともにラキシュからエグロンに進んだ。彼らは、それに向かって陣を敷き、それと戦い、'),
('JPN', '约书亚记', 6, 10, 35, 'その日に、エグロンを攻め取り、剣の刃で討った。そしてその日、そこにいたすべての者を聖絶した。すべて彼がラキシュにしたとおりであった。'),
('JPN', '约书亚记', 6, 10, 36, 'ヨシュアは、全イスラエルとともにエグロンからヘブロンに上った。彼らはそれと戦い、'),
('JPN', '约书亚记', 6, 10, 37, 'それを攻め取り、ヘブロンとその王、およびそのすべての町、そこにいたすべての者を剣の刃で討ち、一人も残さなかった。すべて彼がエグロンにしたとおりであった。彼はその町と、そこにいたすべての者を聖絶した。'),
('JPN', '约书亚记', 6, 10, 38, 'ヨシュアは全イスラエルとともにデビルに引き返し、これと戦い、'),
('JPN', '约书亚记', 6, 10, 39, 'それとその王、およびそのすべての町を攻め取り、剣の刃で彼らを討った。そして、そこにいたすべての者を聖絶し、一人も残さなかった。彼がデビルとその王にしたことはヘブロンにしたとおりであり、またリブナとその王にしたとおりであった。'),
('JPN', '约书亚记', 6, 10, 40, 'ヨシュアはその全地、すなわち、山地、ネゲブ、シェフェラ、傾斜地、そのすべての王たちを討ち、一人も残さなかった。息のある者はみな聖絶した。イスラエルの神、主が命じられたとおりであった。'),
('JPN', '约书亚记', 6, 10, 41, 'ヨシュアはカデシュ・バルネアからガザまで、および、ゴシェンの全土をギブオンに至るまで討った。'),
('JPN', '约书亚记', 6, 10, 42, 'これらすべての王たちと彼らの地を、ヨシュアは一度に攻め取った。イスラエルの神、主がイスラエルのために戦われたからである。'),
('JPN', '约书亚记', 6, 10, 43, 'ヨシュアは全イスラエルとともにギルガルの陣営に戻った。'),
('JPN', '约书亚记', 6, 11, 1, 'ハツォルの王ヤビンはこのことを聞いて、マドンの王ヨバブ、シムロンの王、アクシャフの王、'),
('JPN', '约书亚记', 6, 11, 2, 'また、北方の山地、キネレテの南のアラバ、シェフェラ、西方のドルの高地の王たち、'),
('JPN', '约书亚记', 6, 11, 3, 'すなわち、東西のカナン人、アモリ人、ヒッタイト人、ペリジ人、山地のエブス人、ヘルモンのふもと、ミツパの地のヒビ人に人を遣わした。'),
('JPN', '约书亚记', 6, 11, 4, '彼らはその全陣営とともに出て来た。海辺の砂のように大勢の兵で、馬や戦車も非常に多かった。'),
('JPN', '约书亚记', 6, 11, 5, 'これらの王たちはみな集まり、進んで行き、イスラエルと戦うためにメロムの水のほとりでともに陣を敷いた。'),
('JPN', '约书亚记', 6, 11, 6, '主はヨシュアに告げられた。「彼らを恐れてはならない。明日の今ごろ、わたしは彼らをことごとく、イスラエルの前で刺し殺された者とするからだ。あなたは彼らの馬の足の筋を切り、彼らの戦車を火で焼け。」'),
('JPN', '约书亚记', 6, 11, 7, 'ヨシュアはすべての戦う民とともに、メロムの水のほとりにいる彼らを急襲した。'),
('JPN', '约书亚记', 6, 11, 8, '主は彼らをイスラエルの手に渡された。イスラエルは彼らを討ち、大シドンおよびミスレフォト・マイムまで、東の方ではミツパの谷まで彼らを追い、一人も残さず討った。'),
('JPN', '约书亚记', 6, 11, 9, 'ヨシュアは主が告げられたとおりに彼らにした。彼らの馬の足の筋を切り、彼らの戦車を火で焼いた。'),
('JPN', '约书亚记', 6, 11, 10, 'ヨシュアはそのとき引き返して、ハツォルを攻め取った。その王は剣で討った。ハツォルは当時、これらすべての王国の盟主だったからである。'),
('JPN', '约书亚记', 6, 11, 11, 'ヨシュアたちはそこにいたすべてのものを剣の刃で討ち、聖絶した。息のある者は一人も残らなかった。彼はハツォルを火で焼いた。'),
('JPN', '约书亚记', 6, 11, 12, 'ヨシュアは、これらの王たちのすべての町を攻め取り、そのすべての王たちを剣の刃で討ち、聖絶した。主のしもべモーセが命じたとおりであった。'),
('JPN', '约书亚记', 6, 11, 13, 'イスラエルは、丘の上に立っている町々はどれも焼かなかった。ただし、ヨシュアは例外としてハツォルだけは焼いた。'),
('JPN', '约书亚记', 6, 11, 14, 'これらの町々のすべての分捕り物と家畜を、イスラエルの子らは戦利品として自分たちのものとした。人間だけはみな剣の刃で討ち、根絶やしにした。息のある者は一人も残さなかった。'),
('JPN', '约书亚记', 6, 11, 15, '主がそのしもべモーセに命じられたとおりに、モーセはヨシュアに命じ、ヨシュアはそのとおりに行った。主がモーセに命じられたすべてのことばを、彼は一言も省かなかった。'),
('JPN', '约书亚记', 6, 11, 16, 'ヨシュアはこの全地、すなわち、山地、ネゲブの全地域、ゴシェンの全土、シェフェラ、アラバ、イスラエルの山地とそのシェフェラを奪い取った。'),
('JPN', '约书亚记', 6, 11, 17, '彼は、セイルへ上って行くハラク山から、ヘルモン山のふもとの、レバノンの谷にあるバアル・ガドまでを攻め取った。その王たちをことごとく捕らえ、彼らを討って殺した。'),
('JPN', '约书亚记', 6, 11, 18, '長い間にわたってヨシュアはこれらすべての王たちと戦った。'),
('JPN', '约书亚记', 6, 11, 19, 'ギブオンの住民であるヒビ人以外に、イスラエルの子らと和を講じた町は一つもなかった。イスラエルの子らは戦って、すべてを奪い取った。'),
('JPN', '约书亚记', 6, 11, 20, '彼らの心を頑なにし、イスラエルに立ち向かって戦わせたのは、主から出たことであった。それは、彼らを容赦なく聖絶するため、主がモーセに命じられたとおりに彼らを根絶やしにするためであった。'),
('JPN', '约书亚记', 6, 11, 21, 'そのときヨシュアは行って、アナク人を山地、ヘブロン、デビル、アナブ、ユダのすべての山地、イスラエルのすべての山地から断った。その町々とともにヨシュアは彼らを聖絶した。'),
('JPN', '约书亚记', 6, 11, 22, 'こうしてアナク人は、イスラエルの子らの地には残らなかった。ただガザ、ガテ、アシュドデに残るのみとなった。'),
('JPN', '约书亚记', 6, 11, 23, 'ヨシュアはすべて主がモーセに告げられたとおりに、その地をことごとく奪い取った。ヨシュアはこの地を、イスラエルの部族への割り当てにしたがって、相続地としてイスラエルに与えた。そして、その地に戦争はやんだ。'),
('JPN', '约书亚记', 6, 12, 1, 'ヨルダンの川向こう、日の昇る方で、アルノン川からヘルモン山までの全東アラバにおいて、イスラエルの子らが討ち、占領した地の王たちは次のとおりである。'),
('JPN', '约书亚记', 6, 12, 2, 'ヘシュボンに住んでいた、アモリ人の王シホン。彼はアルノンの渓谷の縁にあるアロエルから、その渓谷の中、およびギルアデの半分、そしてアンモン人の国境ヤボク川まで、'),
('JPN', '约书亚记', 6, 12, 3, 'またアラバ、すなわち、キネレテ湖の東まで、またアラバの海すなわち塩の海の東まで、ベテ・ハ・エシモテへの道まで、そして南はピスガの傾斜地のふもとまでを支配していた。'),
('JPN', '约书亚记', 6, 12, 4, 'アシュタロテとエデレイに住む、レファイムの生き残りの一人である、バシャンの王オグの領土。'),
('JPN', '约书亚记', 6, 12, 5, '彼はヘルモン山、サルカ、ゲシュル人とマアカ人との国境に至るバシャンの全土、ギルアデの半分、ヘシュボンの王シホンの国境までを支配していた。'),
('JPN', '约书亚记', 6, 12, 6, '主のしもべモーセとイスラエルの子らは、彼らを討った。主のしもべモーセはルベン人とガド人と、マナセの半部族に、その地を所有地として与えた。'),
('JPN', '约书亚记', 6, 12, 7, 'ヨルダン川のその反対側、西の方で、レバノンの谷のバアル・ガドから、セイルへ上るハラク山までで、ヨシュアとイスラエルの人々が討ったその地の王たちは、次のとおりである。ヨシュアはイスラエルの部族に、彼らへの割り当てにしたがって、この地を所有地として与えた。'),
('JPN', '约书亚记', 6, 12, 8, 'この王たちは山地、シェフェラ、アラバ、傾斜地、荒野、ネゲブに住んでいて、ヒッタイト人、アモリ人、カナン人、ペリジ人、ヒビ人、エブス人であった。'),
('JPN', '约书亚记', 6, 12, 9, 'エリコの王、一人。ベテルの隣のアイの王、一人。'),
('JPN', '约书亚记', 6, 12, 10, 'エルサレムの王、一人。ヘブロンの王、一人。'),
('JPN', '约书亚记', 6, 12, 11, 'ヤルムテの王、一人。ラキシュの王、一人。'),
('JPN', '约书亚记', 6, 12, 12, 'エグロンの王、一人。ゲゼルの王、一人。'),
('JPN', '约书亚记', 6, 12, 13, 'デビルの王、一人。ゲデルの王、一人。'),
('JPN', '约书亚记', 6, 12, 14, 'ホルマの王、一人。アラドの王、一人。'),
('JPN', '约书亚记', 6, 12, 15, 'リブナの王、一人。アドラムの王、一人。'),
('JPN', '约书亚记', 6, 12, 16, 'マケダの王、一人。ベテルの王、一人。'),
('JPN', '约书亚记', 6, 12, 17, 'タプアハの王、一人。ヘフェルの王、一人。'),
('JPN', '约书亚记', 6, 12, 18, 'アフェクの王、一人。シャロンの王、一人。'),
('JPN', '约书亚记', 6, 12, 19, 'マドンの王、一人。ハツォルの王、一人。'),
('JPN', '约书亚记', 6, 12, 20, 'シムロン・メロンの王、一人。アクシャフの王、一人。'),
('JPN', '约书亚记', 6, 12, 21, 'タアナクの王、一人。メギドの王、一人。'),
('JPN', '约书亚记', 6, 12, 22, 'ケデシュの王、一人。カルメルのヨクネアムの王、一人。'),
('JPN', '约书亚记', 6, 12, 23, 'ドルの高地の、ドルの王、一人。ギルガルのゴイムの王、一人。'),
('JPN', '约书亚记', 6, 12, 24, 'ティルツァの王、一人。全部で三十一人の王である。'),
('JPN', '约书亚记', 6, 13, 1, 'ヨシュアは年を重ねて老人になっていた。主は彼に告げられた。「あなたは年を重ね、老人になった。しかし、占領すべき地は非常にたくさん残っている。'),
('JPN', '约书亚记', 6, 13, 2, '残っている地は次のとおりである。ペリシテ人の全地域、ゲシュル人の全土。'),
('JPN', '约书亚记', 6, 13, 3, 'エジプトの東のシホルから、北は、カナン人のものと見なされているエクロンの国境まで、すなわち、ペリシテ人の五人の領主が支配する、ガザ人、アシュドデ人、アシュケロン人、ガテ人、エクロン人の地と、南のアビム人の地。'),
('JPN', '约书亚记', 6, 13, 4, 'カナン人の全土とシドン人のメアラ、アモリ人の国境のアフェクまでの地。'),
('JPN', '约书亚记', 6, 13, 5, 'ゲバル人の地と、ヘルモン山のふもとのバアル・ガドからレボ・ハマテまでの、レバノンの日の昇る方の全域。'),
('JPN', '约书亚记', 6, 13, 6, 'レバノンからミスレフォテ・マイムまでの山地の全住民、すなわちすべてのシドン人。わたしは彼らをイスラエルの子らの前から追い払う。わたしがあなたに命じたとおり、あなたはその地をイスラエルに相続地としてくじで分けよ。'),
('JPN', '约书亚记', 6, 13, 7, '今、この地を九部族とマナセの半部族に相続地として割り当てよ。」'),
('JPN', '约书亚记', 6, 13, 8, 'ルベン人とガド人はマナセの残りの半部族と並んで、ヨルダンの川向こうである東側で、モーセが自分たちに与えた相続地を受け取っていた。主のしもべモーセが彼らに与えたとおりである。'),
('JPN', '约书亚记', 6, 13, 9, 'アルノンの渓谷の縁にあるアロエルから、その渓谷にある町、またディボンまでのメデバの全台地、'),
('JPN', '约书亚记', 6, 13, 10, 'ヘシュボンで王であったアモリ人の王シホンの、アンモン人との国境までのすべての町、'),
('JPN', '约书亚记', 6, 13, 11, 'ギルアデ、ゲシュル人とマアカ人の領土、ヘルモン山全域、サルカまでのバシャン全域、'),
('JPN', '约书亚记', 6, 13, 12, 'アシュタロテとエデレイで王であった、バシャンのオグの王国全域。オグはレファイムの生き残りであった。モーセは彼らを討ち、追い払った。'),
('JPN', '约书亚记', 6, 13, 13, 'しかし、イスラエルの子らは、ゲシュル人とマアカ人を追い払わなかったので、ゲシュルとマアカはイスラエルのただ中に住んだ。今日もそうである。'),
('JPN', '约书亚记', 6, 13, 14, 'モーセは相続地をレビ部族だけには与えなかった。主が約束されたとおり、イスラエルの神、主への食物のささげ物こそが彼らへのゆずりの分である。'),
('JPN', '约书亚记', 6, 13, 15, 'モーセは、ルベン部族の諸氏族に相続地を与えた。'),
('JPN', '约书亚记', 6, 13, 16, '彼らの地域は、アルノンの渓谷の縁にあるアロエルから、その渓谷にある町、またメデバの全台地、'),
('JPN', '约书亚记', 6, 13, 17, 'ヘシュボンと、台地にあるすべての町、ディボン、バモテ・バアル、ベテ・バアル・メオン、'),
('JPN', '约书亚记', 6, 13, 18, 'ヤハツ、ケデモテ、メファアテ、'),
('JPN', '约书亚记', 6, 13, 19, 'キルヤタイム、シブマ、谷間の丘にあるツェレテ・ハ・シャハル、'),
('JPN', '约书亚记', 6, 13, 20, 'ベテ・ペオル、ピスガの傾斜地、ベテ・ハ・エシモテ、'),
('JPN', '约书亚记', 6, 13, 21, '台地のすべての町、ヘシュボンで王であったアモリ人の王シホンの全王国。モーセはシホンと、その地に住む、シホンの首長であったミディアンの君主たち、すなわち、エウィ、レケム、ツル、フル、レバを討った。'),
('JPN', '约书亚记', 6, 13, 22, 'これらの刺し殺された者に加えて、ベオルの子、占い師バラムをイスラエルの子らは剣で殺した。'),
('JPN', '约书亚记', 6, 13, 23, 'ルベン族の地域は、ヨルダン川とその地域である。これがルベン族の諸氏族の相続地で、その町々とそれらの村々である。'),
('JPN', '约书亚记', 6, 13, 24, 'モーセは、ガド部族、すなわちガド族の諸氏族に相続地を与えた。'),
('JPN', '约书亚记', 6, 13, 25, '彼らの地域はヤゼル、ギルアデのすべての町、アンモン人の地の半分で、ラバに面するアロエルまで、'),
('JPN', '约书亚记', 6, 13, 26, 'ヘシュボンからラマテ・ハ・ミツパとベトニムまで、マハナイムからデビルの国境まで。'),
('JPN', '约书亚记', 6, 13, 27, '谷間ではベテ・ハ・ラム、ベテ・ニムラ、スコテ、ツァフォン。ヘシュボンの王シホンの王国の残りの地、すなわち、ヨルダン川とその地域では、ヨルダンの川向こう、東の方、キネレテ湖の端まで。'),
('JPN', '约书亚记', 6, 13, 28, 'これがガド族の諸氏族の相続地で、その町々と村々である。'),
('JPN', '约书亚记', 6, 13, 29, 'モーセは、マナセの半部族に相続地を与えた。それはマナセの半部族の諸氏族に属する。'),
('JPN', '约书亚记', 6, 13, 30, '彼らの地域はマハナイムからバシャン全域、バシャンの王オグの全王国、バシャンのハボテ・ヤイル全域にある六十の町、'),
('JPN', '约书亚记', 6, 13, 31, 'ギルアデの半分、バシャンのオグの王国の町アシュタロテとエデレイ。これらは、マナセの子マキルの子孫、すなわち、マキル族の半分の諸氏族に属する。'),
('JPN', '约书亚记', 6, 13, 32, 'これらは、ヨルダンの川向こう、エリコの東側にあるモアブの草原で、モーセが割り当てた相続地である。'),
('JPN', '约书亚记', 6, 13, 33, 'レビ部族にはモーセは相続地を与えなかった。主が彼らに約束されたとおり、イスラエルの神、主が彼らへのゆずりである。'),
('JPN', '约书亚记', 6, 14, 1, 'イスラエルの子らがカナンの地でゆずりとして受け継いだのは、次のとおりである。祭司エルアザルと、ヌンの子ヨシュアと、イスラエルの子らの部族の一族のかしらたちは、その地を彼らに'),
('JPN', '约书亚记', 6, 14, 2, '相続地としてくじで割り当てた。主がモーセを通して、九部族と半部族について命じられたとおりである。'),
('JPN', '约书亚记', 6, 14, 3, '二部族と半部族には、ヨルダンの川向こうにモーセがすでに相続地を与え、レビ人には彼らの間に相続地を与えていなかった。'),
('JPN', '约书亚记', 6, 14, 4, 'ヨセフの子孫はマナセとエフライムの二部族になっていたからである。また、レビ族には、住む町と所有する家畜の放牧地以外には、何の割り当て地も与えなかった。'),
('JPN', '约书亚记', 6, 14, 5, 'イスラエルの子らは主がモーセに命じられたとおりに行い、その地を相続地として割り当てた。'),
('JPN', '约书亚记', 6, 14, 6, 'ユダ族の人々がギルガルのヨシュアのところにやって来た。その一人ケナズ人エフンネの子カレブがヨシュアに言った。「主がカデシュ・バルネアで、私とあなたについて神の人モーセに話されたことを、あなたはよくご存じのはずです。'),
('JPN', '约书亚记', 6, 14, 7, '主のしもべモーセがこの地を偵察させるために、私をカデシュ・バルネアから遣わしたとき、私は四十歳でした。私は自分の心にあるとおりを彼に報告しました。'),
('JPN', '约书亚记', 6, 14, 8, '私とともに上って行った私の兄弟たちは民の心をくじきました。しかし私は、私の神、主に従い通しました。'),
('JPN', '约书亚记', 6, 14, 9, 'その日、モーセは誓いました。『あなたの足が踏む地は必ず、永久に、あなたとあなたの子孫の相続地となる。あなたが私の神、主に従い通したからである。』'),
('JPN', '约书亚记', 6, 14, 10, 'ご覧ください。イスラエルが荒野を歩んでいたときに、主がこのことばをモーセに語って以来四十五年、主は語られたとおりに私を生かしてくださいました。ご覧ください。今日、私は八十五歳です。'),
('JPN', '约书亚记', 6, 14, 11, 'モーセが私を遣わした日と同様に、今も私は壮健です。私の今の力はあの時の力と変わらず、戦争にも日常の出入りにも耐えうるものです。'),
('JPN', '约书亚记', 6, 14, 12, '今、主があの日に語られたこの山地を、私に与えてください。そこにアナク人がいて城壁のある大きな町々があることは、あの日あなたも聞いていることです。しかし主が私とともにいてくだされば、主が約束されたように、私は彼らを追い払うことができます。」'),
('JPN', '约书亚记', 6, 14, 13, 'ヨシュアはエフンネの子カレブを祝福し、彼にヘブロンを相続地として与えた。'),
('JPN', '约书亚记', 6, 14, 14, 'このようにして、ヘブロンはケナズ人エフンネの子カレブの相続地となった。今日もそうである。彼がイスラエルの神、主に従い通したからである。'),
('JPN', '约书亚记', 6, 14, 15, 'ヘブロンの名は、かつてはキルヤテ・アルバであった。これは、アルバがアナク人の中の最も偉大な人物であったことによる。こうして、その地に戦争はやんだ。'),
('JPN', '约书亚记', 6, 15, 1, 'ユダ部族の諸氏族がくじで割り当てられた地は、エドムの国境に至り、その南端は、南の方のツィンの荒野であった。'),
('JPN', '约书亚记', 6, 15, 2, '南の境界線は、塩の海の端、南に面する入江から'),
('JPN', '约书亚记', 6, 15, 3, 'アクラビムの坂の南に出てツィンを過ぎ、カデシュ・バルネアの南を上ってヘツロンを過ぎ、アダルへ上ってカルカへ回り、'),
('JPN', '约书亚记', 6, 15, 4, 'アツモンを過ぎてエジプト川に出る。境界線の終わりは海である。これがあなたがたの南の境界線となる。'),
('JPN', '约书亚记', 6, 15, 5, '東の境界線は塩の海で、ヨルダン川の河口までとなる。北側の境界線は、ヨルダン川の河口、海の入江から始まる。'),
('JPN', '约书亚记', 6, 15, 6, 'その境界線はベテ・ホグラを上り、ベテ・ハ・アラバの北を過ぎる。それから境界線はルベンの子ボハンの石を上る。'),
('JPN', '约书亚记', 6, 15, 7, 'さらに境界線はアコルの谷間からデビルに上り、谷の南のアドミムの坂の反対側にあるギルガルに向かって北上する。それから境界線はエン・シェメシュの水を過ぎ、その終わりはエン・ロゲルであった。'),
('JPN', '约书亚记', 6, 15, 8, 'さらに境界線はベン・ヒノムの谷を上ってエブス、すなわちエルサレムの南の傾斜地に至る。それから境界線は、ヒノムの谷を見下ろす西の方の山の頂、レファイムの谷間の北の端を上る。'),
('JPN', '约书亚记', 6, 15, 9, 'さらに境界線は、この山の頂からメ・ネフトアハの泉の方に折れ、エフロン山の町々に出る。それから境界線はバアラ、すなわちキルヤテ・エアリムの方に折れる。'),
('JPN', '约书亚记', 6, 15, 10, 'さらに境界線はバアラから西へ回ってセイル山に至り、エアリム山の傾斜地、すなわちケサロンの北側を過ぎ、ベテ・シェメシュに下り、ティムナを過ぎる。'),
('JPN', '约书亚记', 6, 15, 11, 'そして境界線はエクロンの北の傾斜地に出る。それから境界線はシカロンの方に折れ、バアラ山を過ぎ、ヤブネエルに出る。境界線の終わりは海である。'),
('JPN', '约书亚记', 6, 15, 12, '西の境界線は大海とその沿岸である。これがユダ族の諸氏族の周囲の境界線である。'),
('JPN', '约书亚记', 6, 15, 13, 'ヨシュアは自分への主の命により、エフンネの子カレブに、ユダ族の中でキルヤテ・アルバ、すなわちヘブロンを割り当て地として与えた。アルバはアナクの父である。'),
('JPN', '约书亚记', 6, 15, 14, 'カレブはそこからアナクの三人の息子、シェシャイ、アヒマン、タルマイを追い払った。これらはアナクの子である。'),
('JPN', '约书亚记', 6, 15, 15, 'そして彼は、そこからデビルの住民のところに攻め上った。デビルの名は、かつてはキルヤテ・セフェルであった。'),
('JPN', '约书亚记', 6, 15, 16, 'そのときカレブは言った。「キルヤテ・セフェルを討って、これを攻め取る者に、私の娘アクサを妻として与えよう。」'),
('JPN', '约书亚记', 6, 15, 17, 'カレブの同族ケナズの子オテニエルがそれを攻め取ったので、カレブは娘アクサを彼に妻として与えた。'),
('JPN', '约书亚记', 6, 15, 18, '嫁ぐとき、彼女は夫に、自分の父に畑を求めるようにしきりに促した。彼女がろばから降りると、カレブは「あなたは何が欲しいのか」と彼女に言った。'),
('JPN', '约书亚记', 6, 15, 19, 'アクサは言った。「私にお祝いを下さい。ネゲブの地を私に下さるのですから、湧き水を下さい。」そこでカレブは上の泉と下の泉を彼女に与えた。'),
('JPN', '约书亚记', 6, 15, 20, 'ユダ部族の諸氏族の相続地は次のとおりである。'),
('JPN', '约书亚记', 6, 15, 21, 'エドムの国境の方、ネゲブにあるユダ部族の最南端の町々はカブツェエル、エデル、ヤグル、'),
('JPN', '约书亚记', 6, 15, 22, 'キナ、ディモナ、アデアダ、'),
('JPN', '约书亚记', 6, 15, 23, 'ケデシュ、ハツォル、イテナン、'),
('JPN', '约书亚记', 6, 15, 24, 'ジフ、テレム、ベアロテ、'),
('JPN', '约书亚记', 6, 15, 25, 'ハツォル・ハダタ、ケリヨテ・ヘツロン、すなわちハツォル、'),
('JPN', '约书亚记', 6, 15, 26, 'アマム、シェマ、モラダ、'),
('JPN', '约书亚记', 6, 15, 27, 'ハツァル・ガダ、ヘシュモン、ベテ・ペレテ、'),
('JPN', '约书亚记', 6, 15, 28, 'ハツァル・シュアル、ベエル・シェバ、ビズヨテヤ、'),
('JPN', '约书亚记', 6, 15, 29, 'バアラ、イイム、エツェム、'),
('JPN', '约书亚记', 6, 15, 30, 'エルトラデ、ケシル、ホルマ、'),
('JPN', '约书亚记', 6, 15, 31, 'ツィクラグ、マデマナ、サンサナ、'),
('JPN', '约书亚记', 6, 15, 32, 'レバオテ、シルヒム、アイン、リンモンである。合計二十九の町とそれらの村々。'),
('JPN', '约书亚记', 6, 15, 33, 'シェフェラではエシュタオル、ツォルア、アシュナ、'),
('JPN', '约书亚记', 6, 15, 34, 'ザノアハ、エン・ガニム、タプアハ、エナム、'),
('JPN', '约书亚记', 6, 15, 35, 'ヤルムテ、アドラム、ソコ、アゼカ、'),
('JPN', '约书亚记', 6, 15, 36, 'シャアライム、アディタイム、ゲデラ、ゲデロタイムである。十四の町とその村々。'),
('JPN', '约书亚记', 6, 15, 37, 'ツェナン、ハダシャ、ミグダル・ガド、'),
('JPN', '约书亚记', 6, 15, 38, 'ディルアン、ミツパ、ヨクテエル、'),
('JPN', '约书亚记', 6, 15, 39, 'ラキシュ、ボツカテ、エグロン、'),
('JPN', '约书亚记', 6, 15, 40, 'カボン、ラフマス、キテリシュ、'),
('JPN', '约书亚记', 6, 15, 41, 'ゲデロテ、ベテ・ダゴン、ナアマ、マケダ。十六の町とその村々。'),
('JPN', '约书亚记', 6, 15, 42, 'リブナ、エテル、アシャン、'),
('JPN', '约书亚记', 6, 15, 43, 'エフタ、アシュナ、ネツィブ、'),
('JPN', '约书亚记', 6, 15, 44, 'ケイラ、アクジブ、マレシャ。九つの町とその村々。'),
('JPN', '约书亚记', 6, 15, 45, 'エクロンと、それに属する町々と、その村々。'),
('JPN', '约书亚记', 6, 15, 46, 'エクロンから海まで、アシュドデに隣接したすべての町と、その村々。'),
('JPN', '约书亚记', 6, 15, 47, 'アシュドデと、それに属する町々と、その村々。ガザと、それに属する町々と、その村々。エジプト川に至るまで、大海とその沿岸。'),
('JPN', '约书亚记', 6, 15, 48, '山地ではシャミル、ヤティル、ソコ、'),
('JPN', '约书亚记', 6, 15, 49, 'ダンナ、キルヤテ・サナ、すなわちデビル、'),
('JPN', '约书亚记', 6, 15, 50, 'アナブ、エシュテモア、アニム、'),
('JPN', '约书亚记', 6, 15, 51, 'ゴシェン、ホロン、ギロ。十一の町とその村々。'),
('JPN', '约书亚记', 6, 15, 52, 'アラブ、ドマ、エシュアン、'),
('JPN', '约书亚记', 6, 15, 53, 'ヤニム、ベテ・タプアハ、アフェカ、'),
('JPN', '约书亚记', 6, 15, 54, 'フムタ、キルヤテ・アルバ、すなわちヘブロン、ツィオル。九つの町とその村々。'),
('JPN', '约书亚记', 6, 15, 55, 'マオン、カルメル、ジフ、ユタ、'),
('JPN', '约书亚记', 6, 15, 56, 'イズレエル、ヨクデアム、ザノアハ、'),
('JPN', '约书亚记', 6, 15, 57, 'カイン、ギブア、ティムナ。十の町とその村々。'),
('JPN', '约书亚记', 6, 15, 58, 'ハルフル、ベテ・ツル、ゲドル、'),
('JPN', '约书亚记', 6, 15, 59, 'マアラテ、ベテ・アノテ、エルテコン。六つの町とその村々。'),
('JPN', '约书亚记', 6, 15, 60, 'キルヤテ・バアル、すなわちキルヤテ・エアリムと、ラバ。二つの町とその村々。'),
('JPN', '约书亚记', 6, 15, 61, '荒野ではベテ・ハ・アラバ、ミディン、セカカ、'),
('JPN', '约书亚记', 6, 15, 62, 'ニブシャン、塩の町、エン・ゲディ。六つの町とその村々。'),
('JPN', '约书亚记', 6, 15, 63, 'エルサレムの住民エブス人を、ユダ族は追い払うことができなかった。エブス人はユダ族とともにエルサレムに住んだ。今日もそうである。'),
('JPN', '约书亚记', 6, 16, 1, 'ヨセフ族にくじで当たった地の境界線は、エリコのあたりのヨルダン川からエリコの泉の東側へ、そして荒野の方へ向かい、エリコから上って山地のベテルに至り、'),
('JPN', '约书亚记', 6, 16, 2, 'ベテルからルズに出てアルキ人の領土アタロテを過ぎ、'),
('JPN', '约书亚记', 6, 16, 3, '西の方、ヤフレテ人の領土に下り、下ベテ・ホロンの地境、さらにゲゼルに至る。その終わりは海である。'),
('JPN', '约书亚记', 6, 16, 4, 'ヨセフ族、マナセとエフライムは自分たちの相続地を受け継いだ。'),
('JPN', '约书亚记', 6, 16, 5, 'エフライム族の諸氏族の地域は、次のとおりである。彼らの相続地の領域は東の方、アテロテ・アダルから上ベテ・ホロンに至る。'),
('JPN', '约书亚记', 6, 16, 6, 'そして境界線は西に向かい、さらに北方のミクメタテに出る。そこから境界線は東に回ってタアナテ・シロに至り、そこを過ぎてヤノアハの東に進み、'),
('JPN', '约书亚记', 6, 16, 7, 'ヤノアハからアタロテとナアラに下り、エリコに達し、ヨルダン川に出る。'),
('JPN', '约书亚记', 6, 16, 8, 'また境界線はタプアハから西へ、カナ川に向かう。その終わりは海である。これがエフライム部族の諸氏族の相続地である。'),
('JPN', '约书亚记', 6, 16, 9, 'そして、マナセ族の相続地の中に、エフライム族のために取り分けられた町々、そのすべての町とそれらの村々がある。'),
('JPN', '约书亚记', 6, 16, 10, 'ただし、彼らは、ゲゼルに住むカナン人を追い払わなかった。カナン人はエフライムのただ中に住んだ。今日もそうである。カナン人は強制労働に服すことになった。'),
('JPN', '约书亚记', 6, 17, 1, 'マナセ部族の地は次のとおりにくじで割り当てられた。マナセはヨセフの長子であった。マナセの長子で、ギルアデの父であるマキルは戦士であったので、ギルアデとバシャンが彼のものとなった。'),
('JPN', '约书亚记', 6, 17, 2, '残りのマナセ族の諸氏族、すなわち、アビエゼル族、ヘレク族、アスリエル族、シェケム族、ヘフェル族、シェミダ族にも割り当てられた。これはヨセフの子マナセの、男の子孫の諸氏族である。'),
('JPN', '约书亚记', 6, 17, 3, 'マナセの子マキルの子ギルアデの子ヘフェルの子ツェロフハデには、息子がなく娘だけであった。娘たちの名はマフラ、ノア、ホグラ、ミルカ、ティルツァであった。'),
('JPN', '约书亚记', 6, 17, 4, '彼女たちは、祭司エルアザルとヌンの子ヨシュアと族長たちの前に進み出て言った。「主は、私たちにも自分たちの親類の間に相続地を与えるよう、モーセに命じられました。」ヨシュアは主の命により、彼女たちにも、彼女たちの父の兄弟たちの間に相続地を与えた。'),
('JPN', '约书亚记', 6, 17, 5, 'マナセには、ヨルダンの川向こうのギルアデとバシャンの地のほかに、十の割り当て地があてがわれた。'),
('JPN', '约书亚记', 6, 17, 6, 'マナセの女の子孫が、男の子孫の間に相続地を受け継いだからである。ギルアデの地はマナセのほかの子孫のものとなった。'),
('JPN', '约书亚记', 6, 17, 7, 'マナセの境界線はアシェルからシェケムに面したミクメタテである。その境界線は南へ、エン・タプアハの住民のところに行く。'),
('JPN', '约书亚记', 6, 17, 8, 'タプアハの地はマナセに属していたが、マナセの境界のタプアハはエフライム族に属していた。'),
('JPN', '约书亚记', 6, 17, 9, 'そして境界線はカナ川を下る。川の南側にある町々は、マナセの町々の間にはあるが、エフライムに属している。マナセの地域は川の北側にある。その終わりは海である。'),
('JPN', '约书亚记', 6, 17, 10, 'その南はエフライムのもの、北はマナセのものである。また海がその境界である。マナセは北でアシェルに達し、東でイッサカルに達する。'),
('JPN', '约书亚记', 6, 17, 11, 'イッサカルとアシェルの中にある、ベテ・シェアンとそれに属する村々、イブレアムとそれに属する村々、ドルの住民とそれに属する村々、エン・ドルの住民とそれに属する村々、タアナクの住民とそれに属する村々、メギドの住民とそれに属する村々はマナセに属している。その三番目は高地である。'),
('JPN', '约书亚记', 6, 17, 12, 'しかしマナセ族は、これらの町々を占領することができなかった。カナン人はこの地に継続して住んだ。'),
('JPN', '约书亚记', 6, 17, 13, 'イスラエル人が強くなったときにはカナン人を苦役につかせたが、彼らを追い払うことはなかった。'),
('JPN', '约书亚记', 6, 17, 14, 'ヨセフ族はヨシュアに告げた。「あなたはなぜ、私にただ一つのくじによる相続地、ただ一つの割り当て地しか分けてくださらないのですか。これほど数の多い民になるまで、主が私を祝福してくださったのに。」'),
('JPN', '约书亚记', 6, 17, 15, 'ヨシュアは彼らに言った。「あなたが数の多い民であるのなら、森に上って行きなさい。そこでペリジ人やレファイム人の地を切り開くがよい。エフライムの山地はあなたには狭すぎるのだから。」'),
('JPN', '约书亚记', 6, 17, 16, 'ヨセフ族は言った。「山地は私たちに十分ではありません。しかし、平地に住んでいるカナン人はみな、ベテ・シェアンとそれに属する村々にいる者も、イズレエルの平野にいる者も、鉄の戦車を持っています。」'),
('JPN', '约书亚记', 6, 17, 17, 'ヨシュアはヨセフの家、すなわち、エフライムとマナセに言った。「あなたは数の多い民で大きな力がある。あなたには、くじによる割り当て地が一つだけではいけない。'),
('JPN', '约书亚记', 6, 17, 18, '山地もあなたのものとしなければならない。それが森だとしても切り開いて、その隅々まであなたのものとしなさい。カナン人が鉄の戦車を持っていても、強くても、あなたは彼らを追い払わなければならない。」'),
('JPN', '约书亚记', 6, 18, 1, 'イスラエルの子らの全会衆はシロに集まり、そこに会見の天幕を建てた。この地は彼らに服していたが、'),
('JPN', '约书亚记', 6, 18, 2, 'イスラエルの子らの中に、相続地を割り当てられていない七部族が残っていた。'),
('JPN', '约书亚记', 6, 18, 3, 'ヨシュアはイスラエルの子らに言った。「あなたがたの父祖の神、主があなたがたに与えられた地を占領しに行くのを、あなたがたはいつまで延ばしているのか。'),
('JPN', '约书亚记', 6, 18, 4, '部族ごとに三人の者を出しなさい。私は彼らを送り出そう。彼らが立ち上がってその地を行き巡り、自分たちの相続地にしたがってその地について書き記し、私のところに戻って来るためである。'),
('JPN', '约书亚记', 6, 18, 5, '彼ら自身でそれを七つの割り当て地に分割しなさい。ユダは南にある自分の地域にとどまり、ヨセフの家は北にある自分の地域にとどまる。'),
('JPN', '约书亚记', 6, 18, 6, 'あなたがたはその地の七つの割り当て地を書き記し、私のところに持って来なさい。私はここで、私たちの神、主の前で、あなたがたのためにくじを引こう。'),
('JPN', '约书亚记', 6, 18, 7, 'しかし、レビ人はあなたがたの間に割り当て地を持たない。主の祭司として仕えることが彼らへのゆずりだからである。ガドとルベンと、マナセの半部族は、ヨルダンの川向こう、東の方で自分たちの相続地を受けている。主のしもべモーセが彼らに与えたものである。」'),
('JPN', '约书亚记', 6, 18, 8, 'その人たちは立って出て行った。その際ヨシュアは、その地について書き記すために出て行く者たちに命じた。「さあ、あなたがたはその地を行き巡り、その地について書き記し、私のところに帰って来なさい。ここシロで、主の前で、私はあなたがたのためにくじを引こう。」'),
('JPN', '约书亚记', 6, 18, 9, 'その人たちは行って、その地を巡り、それぞれの町を七つの割り当て地に分けて書物に書き記し、シロの宿営にいるヨシュアのもとに来た。'),
('JPN', '约书亚记', 6, 18, 10, 'ヨシュアはシロで、すなわち主の前で、彼らのためにくじを引いた。ヨシュアはそこで、彼らへの割り当てにしたがって、その地をイスラエルの子らに分割した。'),
('JPN', '约书亚记', 6, 18, 11, 'ベニヤミン部族の諸氏族のくじが引かれた。くじで当たった彼らの地域はユダ族とヨセフ族の間にあった。'),
('JPN', '约书亚记', 6, 18, 12, '北側の境界線はヨルダン川から始まる。その境界線はエリコの北の傾斜地に上り、西の方へ山地を上る。その終わりはベテ・アベンの荒野である。'),
('JPN', '约书亚记', 6, 18, 13, 'さらに境界線はそこからルズに向かい、ルズの南の傾斜地を過ぎる。ルズはベテルである。それから境界線は、下ベテ・ホロンの南にある山の近くのアテロテ・アダルを下る。'),
('JPN', '约书亚记', 6, 18, 14, 'さらに境界線は折れ、西側を、ベテ・ホロンの南向かいの山から南へ回る。その終わりはユダ族の町キルヤテ・バアル、すなわちキルヤテ・エアリムである。これが西側である。'),
('JPN', '约书亚记', 6, 18, 15, '南側はキルヤテ・エアリムの外れを起点とする。その境界線は西に出て、メ・ネフトアハの泉に出る。'),
('JPN', '约书亚记', 6, 18, 16, 'さらに境界線は、レファイムの谷間にあるベン・ヒノムの谷を北から見下ろす山の外れへ下り、ヒノムの谷をエブスの南の傾斜地に下り、エン・ロゲルを下り、'),
('JPN', '约书亚记', 6, 18, 17, '北の方に折れ、エン・シェメシュに出て、アドミムの坂の反対側にあるゲリロテに出て、ルベンの子ボハンの石に下り、'),
('JPN', '约书亚记', 6, 18, 18, 'アラバに面する傾斜地を北へ進み、アラバに下る。'),
('JPN', '约书亚记', 6, 18, 19, 'そして境界線はベテ・ホグラの傾斜地を北へ進む。境界線の終わりは塩の海の北の入江、ヨルダン川の南端である。これが南の境界である。'),
('JPN', '约书亚记', 6, 18, 20, 'ヨルダン川が東側の境界線である。これがベニヤミン族の諸氏族の相続地であり、その周囲の境界線である。'),
('JPN', '约书亚记', 6, 18, 21, 'ベニヤミン部族の諸氏族の町々はエリコ、ベテ・ホグラ、エメク・ケツィツ、'),
('JPN', '约书亚记', 6, 18, 22, 'ベテ・ハ・アラバ、ツェマライム、ベテル、'),
('JPN', '约书亚记', 6, 18, 23, 'アビム、パラ、オフラ、'),
('JPN', '约书亚记', 6, 18, 24, 'ケファル・ハ・アンモニ、オフニ、ゲバ。十二の町とその村々。'),
('JPN', '约书亚记', 6, 18, 25, 'ギブオン、ラマ、ベエロテ、'),
('JPN', '约书亚记', 6, 18, 26, 'ミツパ、ケフィラ、モツァ、'),
('JPN', '约书亚记', 6, 18, 27, 'レケム、イルペエル、タルアラ、'),
('JPN', '约书亚记', 6, 18, 28, 'ツェラ、エレフ、エブスすなわちエルサレム、ギブア、キルヤテ。十四の町とその村々。これがベニヤミン族の諸氏族の相続地である。'),
('JPN', '约书亚记', 6, 19, 1, '二番目のくじはシメオン、すなわち、シメオン部族の諸氏族に当たった。彼らの相続地はユダ族の相続地の中にあった。'),
('JPN', '约书亚记', 6, 19, 2, '彼らの相続地はベエル・シェバ、シェバ、モラダ、'),
('JPN', '约书亚记', 6, 19, 3, 'ハツァル・シュアル、バラ、エツェム、'),
('JPN', '约书亚记', 6, 19, 4, 'エルトラデ、ベトル、ホルマ、'),
('JPN', '约书亚记', 6, 19, 5, 'ツィクラグ、ベテ・マルカボテ、ハツァル・スサ、'),
('JPN', '约书亚记', 6, 19, 6, 'ベテ・レバオテ、シャルヘン。十三の町とその村々。'),
('JPN', '约书亚记', 6, 19, 7, 'アイン、リンモン、エテル、アシャン。四つの町とその村々。'),
('JPN', '约书亚记', 6, 19, 8, 'これらの町々の周りにあって、バアラテ・ベエル、ラマテ・ネゲブにまで及ぶすべての村。これがシメオン部族の諸氏族の相続地である。'),
('JPN', '约书亚记', 6, 19, 9, 'シメオン族の相続地はユダ族の割り当て地から取られた。ユダ族の割り当て地が彼らには広すぎたので、彼らの相続地の中にシメオン族は相続地を受けたのである。'),
('JPN', '约书亚记', 6, 19, 10, '三番目のくじはゼブルン族の諸氏族のために引かれた。彼らの相続地の領域はサリデに及んでいた。'),
('JPN', '约书亚记', 6, 19, 11, '境界線は西へ上って行き、マルアラに至り、ダベシェテに達し、またヨクネアムの向かいの川に達した。'),
('JPN', '约书亚记', 6, 19, 12, 'サリデから反対方向へ、東、すなわち日の昇る方へ向かうと、キスロテ・タボルの地境に至り、ダベラテに出てヤフィアに上る。'),
('JPN', '约书亚记', 6, 19, 13, 'そこから東、すなわち日の出る方へ進んで、ガテ・ヘフェルとエテ・カツィンを過ぎ、リンモンに出てネアの方に折れる。'),
('JPN', '约书亚记', 6, 19, 14, '北の境界線はそこでハナトンに回る。その終わりはエフタフ・エルの谷である。'),
('JPN', '约书亚记', 6, 19, 15, 'カタテ、ナハラル、シムロン、イデアラ、ベツレヘム。十二の町とその村々。'),
('JPN', '约书亚记', 6, 19, 16, 'これがゼブルン族の諸氏族の相続地であり、その町々とそれらの村々である。'),
('JPN', '约书亚记', 6, 19, 17, '四番目のくじはイッサカル、すなわち、イッサカル族の諸氏族に当たった。'),
('JPN', '约书亚记', 6, 19, 18, '彼らの地域はイズレエル、ケスロテ、シュネム、'),
('JPN', '约书亚记', 6, 19, 19, 'ハファライム、シオン、アナハラテ、'),
('JPN', '约书亚记', 6, 19, 20, 'ラビテ、キシュヨン、エベツ、'),
('JPN', '约书亚记', 6, 19, 21, 'レメテ、エン・ガニム、エン・ハダ、ベテ・パツェツである。'),
('JPN', '约书亚记', 6, 19, 22, 'その境界線はタボルに達し、シャハツィマとベテ・シェメシュに向かう。境界線の終わりはヨルダン川である。十六の町とその村々。'),
('JPN', '约书亚记', 6, 19, 23, 'これがイッサカル部族の諸氏族の相続地であり、その町々とそれらの村々である。'),
('JPN', '约书亚记', 6, 19, 24, '五番目のくじはアシェル部族の諸氏族に当たった。'),
('JPN', '约书亚记', 6, 19, 25, '彼らの地域はヘルカテ、ハリ、ベテン、アクシャフ、'),
('JPN', '约书亚记', 6, 19, 26, 'アラメレク、アムアデ、ミシュアルである。西に向かってカルメルとシホル・リブナテに達し、'),
('JPN', '约书亚记', 6, 19, 27, '日の昇る方、すなわちベテ・ダゴンに戻り、ゼブルンに、さらに北の方でエフタフ・エルの谷に達し、ベテ・ハ・エメク、ネイエルを経て左の方、カブルに出て、'),
('JPN', '约书亚记', 6, 19, 28, 'エブロン、レホブ、ハモン、カナを経て大シドンに至る。'),
('JPN', '约书亚记', 6, 19, 29, 'その境界線はラマの方に戻り、城壁のある町ツロに至る。それから境界線はホサの方に戻る。その終わりは海である。マハレブ、アクジブ、'),
('JPN', '约书亚记', 6, 19, 30, 'ウマ、アフェク、レホブ。二十二の町とその村々。'),
('JPN', '约书亚记', 6, 19, 31, 'これがアシェル部族の諸氏族の相続地であり、その町々とそれらの村々である。'),
('JPN', '约书亚记', 6, 19, 32, '六番目のくじはナフタリ族に、すなわち、ナフタリ族の諸氏族に当たった。'),
('JPN', '约书亚记', 6, 19, 33, '彼らの地域は、ヘレフと、ツァアナニムの樫の木から、アダミ・ハ・ネケブ、ヤブネエルを経てラクムに至る。その終わりはヨルダン川である。'),
('JPN', '约书亚记', 6, 19, 34, 'その境界線は西の方、すなわちアズノテ・タボルに戻り、そこからフコクに出て、南でゼブルンに達し、西でアシェルに達し、日の昇る方のヨルダン川でユダに達する。'),
('JPN', '约书亚记', 6, 19, 35, '城壁のある町はツィディム、ツェル、ハマテ、ラカテ、キネレテ、'),
('JPN', '约书亚记', 6, 19, 36, 'アダマ、ラマ、ハツォル、'),
('JPN', '约书亚记', 6, 19, 37, 'ケデシュ、エデレイ、エン・ハツォル、'),
('JPN', '约书亚记', 6, 19, 38, 'イルオン、ミグダル・エル、ホレム、ベテ・アナト、ベテ・シェメシュ。十九の町とその村々。'),
('JPN', '约书亚记', 6, 19, 39, 'これがナフタリ部族の諸氏族の相続地であり、その町々とそれらの村々である。'),
('JPN', '约书亚记', 6, 19, 40, '七番目のくじはダン部族の諸氏族に当たった。'),
('JPN', '约书亚记', 6, 19, 41, '彼らの相続地の領域はツォルア、エシュタオル、イル・シェメシュ、'),
('JPN', '约书亚记', 6, 19, 42, 'シャアラビン、アヤロン、イテラ、'),
('JPN', '约书亚记', 6, 19, 43, 'エロン、ティムナ、エクロン、'),
('JPN', '约书亚记', 6, 19, 44, 'エルテケ、ギベトン、バアラテ、'),
('JPN', '约书亚记', 6, 19, 45, 'エフデ、ベネ・ベラク、ガテ・リンモン、'),
('JPN', '约书亚记', 6, 19, 46, 'メ・ハ・ヤルコン、ラコン、およびヤッファに面する地域である。'),
('JPN', '约书亚记', 6, 19, 47, 'ダン族の地域は彼らから失われたので、ダン族は上って行き、レシェムと戦った。彼らはそこを取り、剣の刃で討つと、これを占領してそこに住み、自分たちの先祖ダンの名にちなんでレシェムをダンと呼んだ。'),
('JPN', '约书亚记', 6, 19, 48, 'これがダン部族の諸氏族の相続地であり、その町々とそれらの村々である。'),
('JPN', '约书亚记', 6, 19, 49, '地を地域ごとに相続地として割り当て終えたとき、イスラエルの子らは、自分たちの間に一つの相続地をヌンの子ヨシュアに与えた。'),
('JPN', '约书亚记', 6, 19, 50, '主の命により、ヨシュアが求めた町、すなわち、エフライムの山地にあるティムナテ・セラフを彼に与えた。彼は町を建てて、そこに住んだ。'),
('JPN', '约书亚记', 6, 19, 51, 'これらは祭司エルアザル、ヌンの子ヨシュア、そしてイスラエルの諸部族の一族のかしらたちが、シロにおいて会見の天幕の入り口、すなわち主の前で、くじによって割り当てた相続地である。彼らは地の割り当てを終えた。'),
('JPN', '约书亚记', 6, 20, 1, '主はヨシュアに告げられた。'),
('JPN', '约书亚记', 6, 20, 2, '「イスラエルの子らに告げよ。『わたしがモーセを通してあなたがたに告げておいた、逃れの町を定めよ。'),
('JPN', '约书亚记', 6, 20, 3, '意図せずに誤って人を打ち殺してしまった殺人者が、そこに逃げ込むためである。血の復讐をする者から逃れる場所とせよ。'),
('JPN', '约书亚记', 6, 20, 4, '人がこれらの町の一つに逃げ込む場合、その人はその町の門の入り口に立ち、その町の長老たちに聞こえるようにその事情を述べよ。彼らは自分たちの町に彼を受け入れ、彼に場所を与える。そして彼は彼らとともに住む。'),
('JPN', '约书亚记', 6, 20, 5, 'たとえ血の復讐をする者が彼を追って来ても、その手に殺人者を渡してはならない。彼は隣人を意図せずに打ち殺してしまったのであって、前からその人を憎んでいたわけではないからである。'),
('JPN', '约书亚记', 6, 20, 6, 'その人は会衆の前に立ってさばきを受けるまで、あるいはその時の大祭司が死ぬまでその町に住む。その後で、殺人者は自分の町、自分の家、自分が逃げ出した町に帰って行くことができる。』」'),
('JPN', '约书亚记', 6, 20, 7, '彼らはナフタリの山地のガリラヤのケデシュ、エフライムの山地のシェケム、ユダの山地のキルヤテ・アルバ、すなわちヘブロンを聖別した。'),
('JPN', '约书亚记', 6, 20, 8, 'ヨルダンの川向こう、エリコの東の方ではルベン部族から台地の荒野のベツェルを、ガド部族からギルアデのラモテを、マナセ部族からバシャンのゴランをこれに当てた。'),
('JPN', '约书亚记', 6, 20, 9, 'これらはすべてのイスラエルの子ら、および彼らの間に寄留している者のために設けられた町である。すべて、誤って人を打ち殺してしまった者がそこに逃げ込むためであり、会衆の前に立たないうちに、血の復讐をする者の手によって死ぬことがないようにするためである。'),
('JPN', '约书亚记', 6, 21, 1, 'レビ人の一族のかしらたちは、祭司エルアザル、ヌンの子ヨシュア、そしてイスラエルの人々の部族の、一族のかしらたちのところに近寄って来て、'),
('JPN', '约书亚记', 6, 21, 2, 'カナンの地のシロで彼らに告げた。「主は、住む町と家畜の放牧地を私たちに与えるよう、モーセを通して命じられました。」'),
('JPN', '约书亚记', 6, 21, 3, 'イスラエルの子らは主の命により、自分たちの相続地から次の町々とその放牧地をレビ人に与えた。'),
('JPN', '约书亚记', 6, 21, 4, 'ケハテ人諸氏族のためにくじが引かれた。ユダ部族、シメオン部族、ベニヤミン部族から、くじによって十三の町がレビ人の祭司アロンの子らのものになった。'),
('JPN', '约书亚记', 6, 21, 5, 'エフライム部族の諸氏族、ダン部族、マナセの半部族から、くじによって十の町が、残りのケハテ族のものになった。'),
('JPN', '约书亚记', 6, 21, 6, 'イッサカル部族の諸氏族、アシェル部族、ナフタリ部族、バシャンのマナセの半部族から、くじによって十三の町がゲルション族のものになった。'),
('JPN', '约书亚记', 6, 21, 7, 'ルベン部族、ガド部族、ゼブルン部族から、十二の町がメラリ人の諸氏族のものになった。'),
('JPN', '约书亚记', 6, 21, 8, 'イスラエルの子らは、主がモーセを通して命じられたとおりに、次の町々とその放牧地をくじによってレビ人に与えた。'),
('JPN', '约书亚记', 6, 21, 9, 'ユダ部族、シメオン部族からは次に名を挙げる町を与えた。'),
('JPN', '约书亚记', 6, 21, 10, 'これらは、レビ族に属するケハテ人諸氏族の一つ、アロンの子らのものになった。最初のくじが彼らに当たったからである。'),
('JPN', '约书亚记', 6, 21, 11, '彼らにはユダの山地にあるキルヤテ・アルバ、すなわちヘブロンとその周囲の放牧地を与えた。アルバはアナクの父である。'),
('JPN', '约书亚记', 6, 21, 12, 'しかし、この町の畑と村々はエフンネの子カレブに、その所有地として与えた。'),
('JPN', '约书亚记', 6, 21, 13, '祭司アロンの子らに与えられたのは、殺人者の逃れの町ヘブロンとその放牧地、リブナとその放牧地、'),
('JPN', '约书亚记', 6, 21, 14, 'ヤティルとその放牧地、エシュテモアとその放牧地、'),
('JPN', '约书亚记', 6, 21, 15, 'ホロンとその放牧地、デビルとその放牧地、'),
('JPN', '约书亚记', 6, 21, 16, 'アインとその放牧地、ユタとその放牧地、ベテ・シェメシュとその放牧地。これら二部族から与えられた九つの町である。'),
('JPN', '约书亚记', 6, 21, 17, 'またベニヤミン部族の中からのギブオンとその放牧地、ゲバとその放牧地、'),
('JPN', '约书亚记', 6, 21, 18, 'アナトテとその放牧地、アルモンとその放牧地の四つの町である。'),
('JPN', '约书亚记', 6, 21, 19, 'アロンの子らである祭司たちの町は、全部で十三の町とその放牧地である。'),
('JPN', '约书亚记', 6, 21, 20, 'レビ人であるケハテ人諸氏族に属する、ケハテ人の残りには、エフライム部族から、くじによって次の町々が与えられた。'),
('JPN', '约书亚记', 6, 21, 21, '彼らに与えられたのは、エフライムの山地にある殺人者の逃れの町シェケムとその放牧地、ゲゼルとその放牧地、'),
('JPN', '约书亚记', 6, 21, 22, 'キブツァイムとその放牧地、ベテ・ホロンとその放牧地の四つの町。'),
('JPN', '约书亚记', 6, 21, 23, 'またダン部族からエルテケとその放牧地、ギベトンとその放牧地、'),
('JPN', '约书亚记', 6, 21, 24, 'アヤロンとその放牧地、ガテ・リンモンとその放牧地の四つの町。'),
('JPN', '约书亚记', 6, 21, 25, 'またマナセの半部族からタアナクとその放牧地、ガテ・リンモンとその放牧地の二つの町。'),
('JPN', '约书亚记', 6, 21, 26, '残りのケハテ族の諸氏族には、全部で十の町とその放牧地が与えられた。'),
('JPN', '约书亚记', 6, 21, 27, 'レビ人の諸氏族の一つゲルション族に与えられたのは、マナセの半部族から、殺人者の逃れの町バシャンのゴランとその放牧地、ベエシュテラとその放牧地の二つの町。'),
('JPN', '约书亚记', 6, 21, 28, 'またイッサカル部族からキシュヨンとその放牧地、ダベラテとその放牧地、'),
('JPN', '约书亚记', 6, 21, 29, 'ヤルムテとその放牧地、エン・ガニムとその放牧地の四つの町。'),
('JPN', '约书亚记', 6, 21, 30, 'またアシェル部族からミシュアルとその放牧地、アブドンとその放牧地、'),
('JPN', '约书亚记', 6, 21, 31, 'ヘルカテとその放牧地、レホブとその放牧地の四つの町。'),
('JPN', '约书亚记', 6, 21, 32, 'またナフタリ部族から、殺人者の逃れの町であるガリラヤのケデシュとその放牧地、ハモテ・ドルとその放牧地、カルタンとその放牧地の三つの町。'),
('JPN', '约书亚记', 6, 21, 33, 'ゲルション人の諸氏族の町は、全部で十三の町とその放牧地である。'),
('JPN', '约书亚记', 6, 21, 34, 'レビ人の残りのメラリ人諸氏族に与えられたのは、ゼブルン部族から、ヨクネアムとその放牧地、カルタとその放牧地、'),
('JPN', '约书亚记', 6, 21, 35, 'またディムナとその放牧地、ナハラルとその放牧地の四つの町。'),
('JPN', '约书亚记', 6, 21, 36, 'またルベン部族からベツェルとその放牧地、ヤハツとその放牧地、'),
('JPN', '约书亚记', 6, 21, 37, 'ケデモテとその放牧地、メファアテとその放牧地の四つの町。'),
('JPN', '约书亚记', 6, 21, 38, 'ガド部族から殺人者の逃れの町、ギルアデのラモテとその放牧地、マハナイムとその放牧地、'),
('JPN', '约书亚记', 6, 21, 39, 'ヘシュボンとその放牧地、ヤゼルとその放牧地、これら四つの町すべて。'),
('JPN', '约书亚记', 6, 21, 40, 'これらの町はすべて、レビ人の諸氏族の残りの、メラリ族の諸氏族のものであり、くじによって与えられた十二の町である。'),
('JPN', '约书亚记', 6, 21, 41, 'イスラエルの子らの所有地の中で、レビ人の町は全部で四十八の町とその放牧地である。'),
('JPN', '约书亚记', 6, 21, 42, 'これらの町はそれぞれその周囲に放牧地があった。これらの町はすべてそうであった。'),
('JPN', '约书亚记', 6, 21, 43, '主は、イスラエルの父祖たちに与えると誓った地をすべて、イスラエルに与えられた。彼らはそれを占領し、そこに住んだ。'),
('JPN', '约书亚记', 6, 21, 44, '主は、彼らの父祖たちに誓ったように、周囲の者から守って彼らに安息を与えられた。すべての敵の中にも、一人として彼らの前に立ちはだかる者はいなかった。主はすべての敵を彼らの手に渡された。'),
('JPN', '约书亚记', 6, 21, 45, '主がイスラエルの家に告げられた良いことは、一つもたがわず、すべて実現した。'),
('JPN', '约书亚记', 6, 22, 1, 'そのとき、ヨシュアはルベン人、ガド人、およびマナセの半部族を呼び寄せて、'),
('JPN', '约书亚记', 6, 22, 2, '彼らに言った。「あなたがたは、主のしもべモーセがあなたがたに命じたことをことごとく守り、私があなたがたに命じたすべてのことについても、私の声に聞き従った。'),
('JPN', '约书亚记', 6, 22, 3, '今日まで、この長い間あなたがたの兄弟たちを捨てず、あなたがたの神、主の命令に対する務めを果たしてきた。'),
('JPN', '约书亚记', 6, 22, 4, '今あなたがたの神、主は、約束したとおりに、あなたがたの兄弟たちに安息を与えられた。今、主のしもべモーセがヨルダンの川向こうであなたがたに与えた、自分たちの所有地、自分たちの天幕に引き返しなさい。'),
('JPN', '约书亚记', 6, 22, 5, 'ただ、主のしもべモーセがあなたがたに命じた命令と律法をよく守り行い、あなたがたの神、主を愛し、そのすべての道に歩み、その命令を守り、主にすがり、心を尽くし、いのちを尽くして主に仕えなさい。」'),
('JPN', '约书亚记', 6, 22, 6, 'ヨシュアが彼らを祝福し、送り出したので、彼らは自分たちの天幕に行った。'),
('JPN', '约书亚记', 6, 22, 7, 'マナセの半部族にはモーセがバシャンに所有地を与えたが、残りの半部族には、ヨシュアがヨルダン川の反対側、すなわち西の方に、彼らの兄弟たちと並んで所有地を与えた。ヨシュアは彼らを天幕に送り出すとき、彼らを祝福して、'),
('JPN', '约书亚记', 6, 22, 8, 'こう言った。「あなたがたは多くの財、つまり、非常に多くの家畜と銀、金、青銅、鉄、たくさんの衣服を持って天幕に帰りなさい。敵からの分捕り物はあなたがたの兄弟たちと分け合いなさい。」'),
('JPN', '约书亚记', 6, 22, 9, 'ルベン族、ガド族、マナセの半部族は、カナンの地にあるシロでイスラエルの子らと別れ、モーセを通して示された主の命により、彼らが得た自分の所有地、すなわちギルアデの地へ帰って行った。'),
('JPN', '约书亚记', 6, 22, 10, 'ルベン族、ガド族、マナセの半部族はカナンの地のヨルダン川の流域まで来たとき、そこ、ヨルダン川のそばに一つの祭壇を築いた。それは遠くから見えるほど大きな祭壇であった。'),
('JPN', '约书亚记', 6, 22, 11, 'イスラエルの子らは、「ルベン族、ガド族、マナセの半部族がカナンの地の国境、ヨルダン川のイスラエルの子らの側の流域に、祭壇を築いた」と聞いた。'),
('JPN', '约书亚记', 6, 22, 12, 'イスラエルの子らがそれを聞いたとき、イスラエルの全会衆は彼らと戦おうとシロに集まった。'),
('JPN', '约书亚记', 6, 22, 13, 'イスラエルの子らは、ギルアデの地のルベン族、ガド族、マナセの半部族のところに祭司エルアザルの子ピネハスを送った。'),
('JPN', '约书亚记', 6, 22, 14, '彼に同行したのは、イスラエルの全部族の中から一族につき族長一人ずつ、計十人の族長であった。彼らはみな、イスラエルの分団の中で一族のかしらであった。'),
('JPN', '约书亚记', 6, 22, 15, '彼らはギルアデの地のルベン族、ガド族、およびマナセの半部族のところに行き、彼らに告げた。'),
('JPN', '约书亚记', 6, 22, 16, '「主の全会衆はこう言っている。『これは何事か。あなたがたが今日、主に従うことをやめてイスラエルの神の信頼を裏切るとは。あなたがたは自分のために祭壇を築いて、今日、主に反逆したのだ。'),
('JPN', '约书亚记', 6, 22, 17, 'ペオルでの不義は、私たちにとって小さなことだっただろうか。私たちは今日まで、あの不義から身をきよめていないではないか。そのために神の罰が主の会衆の上に下ったのだ。'),
('JPN', '约书亚记', 6, 22, 18, 'あなたがたは今日、主に従うことをやめようとしている。あなたがたは今日、主に反逆しようとしている。明日、イスラエルの全会衆に向かって主は怒られるだろう。'),
('JPN', '约书亚记', 6, 22, 19, 'ただし、あなたがたの所有地が汚れているのなら、主の幕屋が建つ主の所有地に渡って来て、私たちの間に所有地を得なさい。私たちの神、主の祭壇のほかに自分たちのために祭壇を築いて、主に反逆してはならない。私たちに反逆してはならない。'),
('JPN', '约书亚记', 6, 22, 20, 'ゼラフの子アカンが、聖絶の物のことで主の信頼を裏切り、イスラエルの全会衆の上に御怒りが下ったではないか。彼の不義によって死んだ者は彼一人ではなかった。』」'),
('JPN', '约书亚记', 6, 22, 21, 'ルベン族、ガド族、マナセの半部族はイスラエルの分団のかしらたちに答えて言った。'),
('JPN', '约书亚记', 6, 22, 22, '「神の神、主よ、神の神、主はご存じです。イスラエルもこれを知りますように。もしこれが、主に対する反逆や不信の罪をもってなされたのなら、今日、私たちをお救いにならないでください。'),
('JPN', '约书亚记', 6, 22, 23, '私たちが祭壇を築いたことが、主に従うのをやめることであるなら、あるいは、その上で全焼のささげ物や穀物のささげ物を献げるため、あるいはその上で交わりのいけにえを献げるためであるなら、主ご自身が私たちを責めてくださいますように。'),
('JPN', '约书亚记', 6, 22, 24, 'しかし、私たちがこのことをしたのは次のことを恐れたからです。後になって、あなたがたの子らが、私たちの子らに次のように言うかもしれません。『あなたがたとイスラエルの神、主との間に何の関係があるのか。'),
('JPN', '约书亚记', 6, 22, 25, '主はヨルダン川を、私たちと、あなたがたルベン族、ガド族との間の境界とされた。あなたがたは主のうちに取り分がない。』こうして、あなたがたの子らが私たちの子らに、主を恐れることをやめさせるかもしれません。'),
('JPN', '约书亚记', 6, 22, 26, '私たちは考えました。さあ、私たちは自分たちのために祭壇を築こう、と。全焼のささげ物のためではなく、いけにえのためでもありません。'),
('JPN', '约书亚记', 6, 22, 27, 'それは、私たちとあなたがたとの間、私たちの後の世代との間の証拠となり、私たちが全焼のささげ物といけにえと交わりのいけにえを献げて、主の前で主への奉仕をするためです。こうすれば、後になって、あなたがたの子らが私たちの子らに『あなたがたは主のうちに取り分がない』と言うことはないでしょう。'),
('JPN', '约书亚记', 6, 22, 28, '私たちは考えました。後になって、もし私たち、また私たちの子孫がそう言われたとしても、私たちはこう言うことができる。『私たちの父祖が造った主の祭壇の型を見よ。これは全焼のささげ物のためでもなく、いけにえのためでもなく、私たちとあなたがたとの間の証拠なのだ』と。'),
('JPN', '约书亚记', 6, 22, 29, '私たちが、主の幕屋の前にある私たちの神、主の祭壇のほかに、全焼のささげ物や穀物のささげ物や、いけにえを献げる祭壇を築いて、今日、主に反逆して主に従うことをやめるなど、絶対にあり得ないことです。」'),
('JPN', '约书亚记', 6, 22, 30, '祭司ピネハス、会衆の上に立つ族長たち、彼とともにいたイスラエルの分団のかしらたちはルベン族、ガド族、マナセ族が語ったことばを聞いて、それに満足した。'),
('JPN', '约书亚记', 6, 22, 31, 'エルアザルの子、祭司ピネハスはルベン族、ガド族、マナセ族に言った。「今日、私たちは、主が私たちの中におられることを知った。あなたがたが主の信頼を裏切らなかったからである。あなたがたは今、イスラエルの子らを主の手から救い出した。」'),
('JPN', '约书亚记', 6, 22, 32, 'エルアザルの子、祭司ピネハスと族長たちは、ルベン族およびガド族と別れ、ギルアデの地からカナンの地のイスラエルの子らのところに帰り、このことを報告した。'),
('JPN', '约书亚记', 6, 22, 33, 'イスラエルの子らはこれに満足した。彼らは神をほめたたえた。そしてもはや、ルベン族とガド族が住んでいる地を滅ぼすために戦をしよう、とは言わなかった。'),
('JPN', '约书亚记', 6, 22, 34, 'ルベン族とガド族はその祭壇に「これは私たちの間での、主が神であることの証しだ」と言って名をつけた。'),
('JPN', '约书亚记', 6, 23, 1, '主が、周囲のすべての敵からイスラエルを守って安息を与えられてから、多くの日がたち、ヨシュアは年を重ねて老人になっていた。'),
('JPN', '约书亚记', 6, 23, 2, 'ヨシュアは全イスラエル、その長老たち、かしらたち、さばき人たち、つかさたちを呼び寄せて彼らに言った。「私は年を重ねて老人になった。'),
('JPN', '约书亚记', 6, 23, 3, 'あなたがたは、自分たちの神、主が自分たちのために、これらすべての国々に行ったことをすべて見てきた。あなたがたのために戦ったのは、あなたがたの神、主である。'),
('JPN', '约书亚记', 6, 23, 4, '見よ。私はヨルダン川から日の入る方の大海まで、これらの残っている国々と、すでに私が絶ち滅ぼしたすべての国々を、相続地としてあなたがたの部族にくじで分けた。'),
('JPN', '约书亚记', 6, 23, 5, 'あなたがたの神、主ご自身が、彼らをあなたがたの前から追い払い、あなたがたの目の前から追い出される。あなたがたの神、主があなたがたに告げたように彼らの地を占領しなさい。'),
('JPN', '约书亚记', 6, 23, 6, 'また、モーセの律法の書に記されていることを、ことごとく断固として守り行いなさい。そこから右にも左にも外れず、'),
('JPN', '约书亚记', 6, 23, 7, 'これらの国々、あなたがたの中に残っている、これらの異邦の民と交わらないようにするためである。彼らの神々の名を口にしてはならない。それらによって誓ってはならない。それらに仕えてはならない。それらを拝んではならない。'),
('JPN', '约书亚记', 6, 23, 8, 'ただ今日までしてきたように、あなたがたの神、主にすがりなさい。'),
('JPN', '约书亚记', 6, 23, 9, '主は、大きくて強い異邦の民をあなたがたの前から追い払われた。だから今日まで、あなたがたの前に立ちはだかることのできる者は、一人としていなかった。'),
('JPN', '约书亚记', 6, 23, 10, 'あなたがたは一人で千人を追うことができる。あなたがたの神、主ご自身が、あなたがたに約束したとおり、あなたがたのために戦われるからである。'),
('JPN', '约书亚记', 6, 23, 11, 'だからあなたがたは自分自身に十分に気をつけて、あなたがたの神、主を愛しなさい。'),
('JPN', '约书亚记', 6, 23, 12, 'しかし、もしも、あなたがたが再び堕落して、これらの異邦の民の生き残っている者、すなわち、あなたがたの中に残っているこれらの者たちと親しく交わり、彼らと姻戚関係に入り、あなたがたが彼らの中に入って行き、彼らもあなたがたの中に入って来ることがあれば、'),
('JPN', '约书亚记', 6, 23, 13, 'あなたがたは、このことをしっかりと知らなければならない。あなたがたの神、主は、もはやこれらの異邦の民をあなたがたの前から追い払われない。彼らはあなたがたにとって、罠となり、落とし穴となり、あなたがたの脇腹にむちとなり、あなたがたの目にとげとなる。そして、あなたがたは自分たちの神、主がお与えになったこの良い地から滅び失せる。'),
('JPN', '约书亚记', 6, 23, 14, '見よ。今日、私は地のすべての人が行く道を行こうとしている。あなたがたは心を尽くし、いのちを尽くして、知りなさい。あなたがたの神、主があなたがたについて約束されたすべての良いことは、一つもたがわなかったことを。それらはみな、あなたがたのために実現し、一つもたがわなかった。'),
('JPN', '约书亚记', 6, 23, 15, 'あなたがたの神、主があなたがたに約束されたすべての良いことが、あなたがたに実現したように、主はまた、すべての悪いことをあなたがたにもたらし、ついには、あなたがたの神、主がお与えになったこの良い地からあなたがたを根絶やしにされる。'),
('JPN', '约书亚记', 6, 23, 16, '主があなたがたに命じられた、あなたがたの神、主の契約を破り、行ってほかの神々に仕え、それらを拝むなら、主の怒りはあなたがたに対して燃え上がり、あなたがたは、主がお与えになったこの良い地から速やかに滅び失せる。」'),
('JPN', '约书亚记', 6, 24, 1, 'ヨシュアはイスラエルの全部族をシェケムに集め、イスラエルの長老たち、かしらたち、さばき人たち、つかさたちを呼び寄せた。彼らが神の前に立ったとき、'),
('JPN', '约书亚记', 6, 24, 2, 'ヨシュアは民全体に言った。「イスラエルの神、主はこう告げられる。『あなたがたの父祖たち、アブラハムの父でありナホルの父であるテラは昔、ユーフラテス川の向こうに住み、ほかの神々に仕えていた。'),
('JPN', '约书亚记', 6, 24, 3, 'わたしはあなたがたの父祖アブラハムを、あの大河の向こうから連れて来てカナンの全土を歩かせ、子孫を増し、イサクを与えた。'),
('JPN', '约书亚记', 6, 24, 4, 'そして、わたしはイサクにヤコブとエサウを与え、エサウにはセイルの山地を与えてそれを所有させた。一方、ヤコブと彼の子たちはエジプトに下った。'),
('JPN', '约书亚记', 6, 24, 5, 'わたしはモーセとアロンを遣わし、エジプトに災害を下した。わたしがそのただ中で行ったとおりである。その後、わたしはあなたがたを導き出した。'),
('JPN', '约书亚记', 6, 24, 6, 'わたしはあなたがたの父祖たちをエジプトから導き出した。あなたがたが海まで来たとき、エジプト人は、戦車と騎兵であなたがたの父祖たちを葦の海まで追いつめた。'),
('JPN', '约书亚记', 6, 24, 7, '彼らは主に叫び求め、主はあなたがたとエジプト人の間に暗闇を置き、海に彼らを襲わせ、彼らをおおわせた。あなたがたの目は、わたしがエジプトで行ったことを見た。そして、あなたがたは長い間、荒野に住んだ。'),
('JPN', '约书亚记', 6, 24, 8, 'わたしは、ヨルダンの川向こうに住んでいたアモリ人の地に、あなたがたを導き入れた。彼らはあなたがたと戦ったが、わたしは彼らをあなたがたの手に渡し、あなたがたは彼らの地を占領した。わたしはあなたがたの前から彼らを一掃した。'),
('JPN', '约书亚记', 6, 24, 9, 'モアブの王、ツィポルの子バラクは立ってイスラエルと戦い、あなたがたを呪うために、人を遣わしてベオルの子バラムを呼び寄せた。'),
('JPN', '约书亚记', 6, 24, 10, 'しかし、わたしはバラムに耳を傾けようとしなかった。彼はかえって、あなたがたを祝福し、こうして、わたしはあなたがたをバラクの手から救い出した。'),
('JPN', '约书亚记', 6, 24, 11, 'あなたがたはヨルダン川を渡り、エリコに来た。エリコの住民やアモリ人、ペリジ人、カナン人、ヒッタイト人、ギルガシ人、ヒビ人、エブス人はあなたがたと戦った。しかし、わたしは彼らをあなたがたの手に渡し、'),
('JPN', '约书亚记', 6, 24, 12, 'あなたがたの前にスズメバチを送ったので、スズメバチがアモリ人の二人の王をあなたがたの前から追い払った。あなたがたの剣にもよらず、あなたがたの弓にもよらなかった。'),
('JPN', '约书亚记', 6, 24, 13, 'わたしは、あなたが労したのではない地と、あなたがたが建てたのではない町々をあなたがたに与えた。あなたがたはそこに住み、自分で植えたのではない、ぶどう畑とオリーブ畑から食べている。』'),
('JPN', '约书亚记', 6, 24, 14, '今、あなたがたは主を恐れ、誠実と真実をもって主に仕え、あなたがたの先祖たちが、あの大河の向こうやエジプトで仕えた神々を取り除き、主に仕えなさい。'),
('JPN', '约书亚记', 6, 24, 15, '主に仕えることが不満なら、あの大河の向こうにいた、あなたがたの先祖が仕えた神々でも、今あなたがたが住んでいる地のアモリ人の神々でも、あなたがたが仕えようと思うものを、今日選ぶがよい。ただし、私と私の家は主に仕える。」'),
('JPN', '约书亚记', 6, 24, 16, '民は答えた。「私たちが主を捨てて、ほかの神々に仕えるなど、絶対にあり得ないことです。'),
('JPN', '约书亚记', 6, 24, 17, '私たちの神、主は、私たちと私たちの先祖たちをエジプトの地、奴隷の家から導き上られた方、そして、私たちの目の前であの数々の大きなしるしを行い、私たちが進んだすべての道で、また私たちが通ったあらゆる民の中で、私たちを守ってくださった方だからです。'),
('JPN', '约书亚记', 6, 24, 18, '主はあらゆる民を、この地に住んでいたアモリ人を私たちの前から追い払われました。私たちもまた、主に仕えます。このお方が私たちの神だからです。」'),
('JPN', '约书亚记', 6, 24, 19, 'ヨシュアは民に言った。「あなたがたは主に仕えることはできない。主は聖なる神、ねたみの神であり、あなたがたの背きや罪を赦さないからである。'),
('JPN', '约书亚记', 6, 24, 20, 'あなたがたが主を捨てて異国の神々に仕えるなら、あなたがたを幸せにした後でも、主は翻って、あなたがたにわざわいを下し、あなたがたを滅ぼし尽くす。」'),
('JPN', '约书亚记', 6, 24, 21, '民はヨシュアに言った。「いいえ。私たちは主に仕えます。」'),
('JPN', '约书亚记', 6, 24, 22, 'ヨシュアは民に言った。「主を選んで主に仕えることの証人はあなたがた自身です。」彼らは「私たちが証人です」と言った。'),
('JPN', '约书亚记', 6, 24, 23, '「今、あなたがたの中にある異国の神々を取り除き、イスラエルの神、主に心を傾けなさい。」'),
('JPN', '约书亚记', 6, 24, 24, '民はヨシュアに言った。「私たちの神、主に仕え、主の御声に聞き従います。」'),
('JPN', '约书亚记', 6, 24, 25, 'ヨシュアはその日、民と契約を結び、シェケムで彼らのために掟と定めを置いた。'),
('JPN', '约书亚记', 6, 24, 26, 'ヨシュアはこれらのことばを神のみおしえの書に記し、大きな石を取り、主の聖所にある樫の木の下に立てた。'),
('JPN', '约书亚记', 6, 24, 27, 'ヨシュアは民全体に言った。「見よ、この石は私たちに対して証しとなる。この石は、主が私たちに語られたすべてのことばを聞いたからである。あなたがたが自分の神を否むことがないように、これはあなたがたに対して証しとなる。」'),
('JPN', '约书亚记', 6, 24, 28, 'ヨシュアは民をそれぞれ自分の相続地に送り出した。'),
('JPN', '约书亚记', 6, 24, 29, 'これらのことの後、主のしもべ、ヌンの子ヨシュアは百十歳で死んだ。'),
('JPN', '约书亚记', 6, 24, 30, '人々は彼をガアシュ山の北、エフライムの山地にある、彼の相続地の領域にあるティムナテ・セラフに葬った。'),
('JPN', '约书亚记', 6, 24, 31, 'ヨシュアがいた間、また、主がイスラエルのために行われたすべてのわざを経験して、ヨシュアより長生きした長老たちがいた間、イスラエルは主に仕えた。'),
('JPN', '约书亚记', 6, 24, 32, 'イスラエルの子らがエジプトから携え上ったヨセフの遺骸は、シェケムの地、すなわち、ヤコブが百ケシタでシェケムの父ハモルの子たちから買い取った野の一画に葬った。そこはヨセフ族の相続地となっていた。'),
('JPN', '约书亚记', 6, 24, 33, 'アロンの子エルアザルは死んだ。彼は、自分の子ピネハスに与えられた、エフライムの山地にあるギブアに葬られた。'),
('JPN', '士师记', 7, 1, 1, 'ヨシュアの死後、イスラエルの子らは主に尋ねた。「だれが私たちのために最初に上って行って、カナン人と戦うべきでしょうか。」'),
('JPN', '士师记', 7, 1, 2, 'すると、主は言われた。「ユダが上って行くべきである。見よ、わたしはその地を彼の手に渡した。」'),
('JPN', '士师记', 7, 1, 3, 'ユダは自分の兄弟シメオンに言った。「私と一緒に、私に割り当てられた地に上ってください。私たちはカナン人と戦うのです。私も、あなたに割り当てられた地に一緒に行きます。」そこでシメオンは彼と一緒に行った。'),
('JPN', '士师记', 7, 1, 4, 'ユダが上って行くと、主はカナン人とペリジ人を彼らの手に渡されたので、彼らはベゼクで一万人を討ち取った。'),
('JPN', '士师记', 7, 1, 5, '彼らはベゼクでアドニ・ベゼクに出会い、彼と戦ってカナン人とペリジ人を討った。'),
('JPN', '士师记', 7, 1, 6, 'ところが、アドニ・ベゼクが逃げたので、彼らは後を追って捕らえ、その両手両足の親指を切り落とした。'),
('JPN', '士师记', 7, 1, 7, 'アドニ・ベゼクは言った。「かつて、両手両足の親指を切り落とされた七十人の王たちが、私の食卓の下でパン屑を拾い集めていたものだ。私がしたとおりに、神は私に報いを返された。」彼らはアドニ・ベゼクをエルサレムに連れて行き、彼はそこで死んだ。'),
('JPN', '士师记', 7, 1, 8, 'ユダ族は、エルサレムを攻めてこれを取り、剣の刃で討って町に火を放った。'),
('JPN', '士师记', 7, 1, 9, 'その後、ユダ族は、山地やネゲブやシェフェラに住んでいるカナン人と戦うために下って行った。'),
('JPN', '士师记', 7, 1, 10, 'ユダはヘブロンに住んでいるカナン人を攻めた。ヘブロンの名は、かつてはキルヤテ・アルバであった。彼らはシェシャイとアヒマンとタルマイを討った。'),
('JPN', '士师记', 7, 1, 11, '彼らは、そこから進んでデビルの住民を攻めた。デビルの名は、かつてはキルヤテ・セフェルであった。'),
('JPN', '士师记', 7, 1, 12, 'そのときカレブは言った。「キルヤテ・セフェルを討って、これを攻め取る者に、私の娘アクサを妻として与えよう。」'),
('JPN', '士师记', 7, 1, 13, 'カレブの同族ケナズの子オテニエルがそれを攻め取ったので、カレブは娘アクサを彼に妻として与えた。'),
('JPN', '士师记', 7, 1, 14, '嫁ぐとき、彼女は夫に、自分の父に畑を求めるよう、しきりに促した。彼女がろばから降りると、カレブは「何が欲しいのか」と彼女に言った。'),
('JPN', '士师记', 7, 1, 15, 'アクサは彼に言った。「どうか私にお祝いを下さい。ネゲブの地を私に下さるのですから、湧き水を下さい。」そこでカレブは上の泉と下の泉を彼女に与えた。'),
('JPN', '士师记', 7, 1, 16, 'モーセのしゅうとがその一族であるケニ人たちは、ユダ族と一緒に、なつめ椰子の町からアラドの南にあるユダの荒野に上って行き、そこの民とともに住んだ。'),
('JPN', '士师记', 7, 1, 17, 'ユダは兄弟シメオンと一緒に行って、ツェファテに住んでいたカナン人を討ち、それを聖絶し、その町にホルマという名をつけた。'),
('JPN', '士师记', 7, 1, 18, 'ユダは、ガザとその地域、アシュケロンとその地域、エクロンとその地域を攻め取った。'),
('JPN', '士师记', 7, 1, 19, '主がユダとともにおられたので、ユダは山地を占領した。しかし、平地の住民は鉄の戦車を持っていたので、ユダは彼らを追い払えなかった。'),
('JPN', '士师记', 7, 1, 20, 'モーセが約束したとおり、ヘブロンはカレブに与えられ、カレブはそこからアナクの三人の息子を追い払った。'),
('JPN', '士师记', 7, 1, 21, 'エルサレムに住んでいるエブス人に関しては、ベニヤミン族がこれを追い払わなかったので、エブス人は今日までベニヤミン族とともにエルサレムに住んでいる。'),
('JPN', '士师记', 7, 1, 22, 'ヨセフの一族もまた、ベテルに上って行った。主は彼らとともにおられた。'),
('JPN', '士师记', 7, 1, 23, 'ヨセフの一族はベテルを探った。この町の名は、かつてはルズであった。'),
('JPN', '士师记', 7, 1, 24, '見張りの者たちは、その町から出て来た人を見て言った。「この町に入るところを教えてほしい。そうすれば私たちも、あなたに誠意を尽くすから。」'),
('JPN', '士师记', 7, 1, 25, '彼が町の出入り口を教えたので、彼らは剣の刃でこの町を討った。しかし、その人とその氏族の者はみな自由にしてやった。'),
('JPN', '士师记', 7, 1, 26, 'その人はヒッタイト人の地に行って町を建て、その名をルズと呼んだ。これが今日までその名である。'),
('JPN', '士师记', 7, 1, 27, 'マナセは、ベテ・シェアンとそれに属する村々、タアナクとそれに属する村々、ドルの住民とそれに属する村々、イブレアムの住民とそれに属する村々、メギドの住民とそれに属する村々は占領しなかった。それで、カナン人はその土地に住み続けた。'),
('JPN', '士师记', 7, 1, 28, 'イスラエルは強くなったとき、カナン人を苦役に服させたが、彼らを完全に追い払うことはしなかった。'),
('JPN', '士师记', 7, 1, 29, 'エフライムはゲゼルの住民であるカナン人を追い払わなかったので、カナン人はゲゼルで彼らのただ中に住んだ。'),
('JPN', '士师记', 7, 1, 30, 'ゼブルンはキテロンの住民とナハロルの住民を追い払わなかったので、カナン人は彼らのただ中に住み、苦役に服した。'),
('JPN', '士师记', 7, 1, 31, 'アシェルはアッコの住民やシドンの住民、またアフラブ、アクジブ、ヘルバ、アフィク、レホブの住民を追い払わなかった。'),
('JPN', '士师记', 7, 1, 32, 'それで、アシェル人は、その土地に住むカナン人のただ中に住んだ。カナン人を追い払わなかったのである。'),
('JPN', '士师记', 7, 1, 33, 'ナフタリはベテ・シェメシュの住民やベテ・アナトの住民を追い払わずに、その土地に住むカナン人のただ中に住んだ。しかし、ベテ・シェメシュとベテ・アナトの住民は、彼らのために苦役に服した。'),
('JPN', '士师记', 7, 1, 34, 'アモリ人はダン族を山地に追いつめ、平地に下りることを許さなかった。'),
('JPN', '士师记', 7, 1, 35, 'こうしてアモリ人は、ハル・ヘレス、アヤロン、そしてシャアルビムに住み続けたが、ヨセフの一族が勢力を増すと、彼らは苦役に服した。'),
('JPN', '士师记', 7, 1, 36, 'アモリ人の領地は、アクラビムの坂からセラを経た上の方であった。'),
('JPN', '士师记', 7, 2, 1, '主の使いがギルガルからボキムに上って来た。そして言った。「わたしはあなたがたをエジプトから上らせて、あなたがたの父祖たちに誓った地に連れて来て言った。『わたしはあなたがたと結んだわたしの契約を決して破らない。'),
('JPN', '士师记', 7, 2, 2, 'あなたがたは、この地の住民と契約を結んではならない。彼らの祭壇を打ち壊さなければならない。』ところが、あなたがたはわたしの声に聞き従わなかった。なぜこのようなことをしたのか。'),
('JPN', '士师记', 7, 2, 3, 'それでわたしも言う。『わたしはあなたがたの前から彼らを追い払わない。彼らはあなたがたの敵となり、彼らの神々はあなたがたにとって罠となる。』」'),
('JPN', '士师记', 7, 2, 4, '主の使いがこれらのことばをイスラエルの子ら全体に語ったとき、民は声をあげて泣いた。'),
('JPN', '士师记', 7, 2, 5, '彼らはその場所の名をボキムと呼んで、その場所で主にいけにえを献げた。'),
('JPN', '士师记', 7, 2, 6, 'ヨシュアが民を送り出したので、イスラエルの子らはそれぞれ土地を占領しようと、自分の相続する地へ出て行った。'),
('JPN', '士师记', 7, 2, 7, 'ヨシュアがいた間、また、主がイスラエルのために行われたすべての大いなるわざを見て、ヨシュアより長生きした長老たちがいた間、民は主に仕えた。'),
('JPN', '士师记', 7, 2, 8, '主のしもべ、ヌンの子ヨシュアは百十歳で死んだ。'),
('JPN', '士师记', 7, 2, 9, '人々は彼をガアシュ山の北、エフライムの山地にある、彼の相続地の領域にあるティムナテ・ヘレスに葬った。'),
('JPN', '士师记', 7, 2, 10, 'その世代の者たちもみな、その先祖たちのもとに集められた。そして彼らの後に、主を知らず、主がイスラエルのために行われたわざも知らない、別の世代が起こった。'),
('JPN', '士师记', 7, 2, 11, 'すると、イスラエルの子らは主の目に悪であることを行い、もろもろのバアルに仕えた。'),
('JPN', '士师记', 7, 2, 12, '彼らは、エジプトの地から自分たちを導き出した父祖の神、主を捨てて、ほかの神々、すなわち彼らの周りにいるもろもろの民の神々に従い、それらを拝んで、主の怒りを引き起こした。'),
('JPN', '士师记', 7, 2, 13, '彼らが主を捨てて、バアルとアシュタロテに仕えたので、'),
('JPN', '士师记', 7, 2, 14, '主の怒りがイスラエルに向かって燃え上がり、主は彼らを略奪する者の手に渡して略奪されるままにし、周りの敵の手に彼らを売り渡された。彼らはもはや、敵に立ち向かうことができなかった。'),
('JPN', '士师记', 7, 2, 15, '彼らがどこへ行っても、主の手は彼らにわざわいをもたらした。主が告げ、主が彼らに誓われたとおりであった。彼らは大いに苦しんだ。'),
('JPN', '士师记', 7, 2, 16, 'そのとき、主はさばきつかさを起こして、略奪する者の手から彼らを救われた。'),
('JPN', '士师记', 7, 2, 17, 'ところが、彼らはそのさばきつかさにも聞き従わず、ほかの神々を慕って淫行を行い、それらを拝んだ。彼らの先祖が主の命令に聞き従って歩んだ道から早くも外れて、先祖たちのようには行わなかった。'),
('JPN', '士师记', 7, 2, 18, '主が彼らのためにさばきつかさを起こしたとき、主はさばきつかさとともにおられ、そのさばきつかさが生きている間、彼らを敵の手から救われた。これは、圧迫し、虐げる者を前にして彼らがうめいたので、主があわれまれたからである。'),
('JPN', '士师记', 7, 2, 19, 'しかし、さばきつかさが死ぬと、彼らは元に戻って先祖たちよりもいっそう堕落し、ほかの神々に従い、それらに仕え、それらを拝んだ。彼らはその行いや、頑なな生き方から離れなかった。'),
('JPN', '士师记', 7, 2, 20, 'そのため、主の怒りがイスラエルに向かって燃え上がった。主は言われた。「この民は、わたしが彼らの先祖たちに命じたわたしの契約を破り、わたしの声に聞き従わなかったから、'),
('JPN', '士师记', 7, 2, 21, 'わたしもまた、ヨシュアが死んだときに残しておいたいかなる異邦の民も、彼らの前から追い払わない。'),
('JPN', '士师记', 7, 2, 22, 'これは、先祖たちが守ったように、彼らも主の道を守って歩むかどうか、これらの国民によってイスラエルを試みるためである。」'),
('JPN', '士师记', 7, 2, 23, 'こうして、主はこれらの異邦の民をただちに追い払うことをせずに残しておき、ヨシュアの手に渡されなかったのである。'),
('JPN', '士师记', 7, 3, 1, '次が、主が残しておかれた異邦の民である。主がそうされたのは、カナンでの戦いを全く知らないすべてのイスラエルを試みるためであり、'),
('JPN', '士师记', 7, 3, 2, 'ただ、イスラエルの次世代の者、特にまだ戦いを知らない者たちに、戦いを教え、知らせるためであった。'),
('JPN', '士师记', 7, 3, 3, 'すなわち、ペリシテ人の五人の領主たち、またすべてのカナン人、シドン人、そしてヒビ人である。ヒビ人は、バアル・ヘルモン山からレボ・ハマテにまで及ぶレバノンの山地に住んでいた。'),
('JPN', '士师记', 7, 3, 4, 'これは、彼らによってイスラエルを試み、主がモーセを通して先祖たちに命じた命令に、イスラエルが聞き従うかどうかを知るためであった。'),
('JPN', '士师记', 7, 3, 5, 'イスラエル人は、カナン人、ヒッタイト人、アモリ人、ペリジ人、ヒビ人、エブス人のただ中に住み、'),
('JPN', '士师记', 7, 3, 6, '彼らの娘を自分たちの妻とし、また自分たちの娘を彼らの息子に与えて、彼らの神々に仕えた。'),
('JPN', '士师记', 7, 3, 7, 'こうしてイスラエルの子らは、主の目に悪であることを行い、彼らの神、主を忘れて、もろもろのバアルやアシェラに仕えた。'),
('JPN', '士师记', 7, 3, 8, '主の怒りがイスラエルに向かって燃え上がり、主は彼らをアラム・ナハライムの王クシャン・リシュアタイムの手に売り渡されたので、イスラエルの子らは八年の間、クシャン・リシュアタイムに仕えた。'),
('JPN', '士师记', 7, 3, 9, 'イスラエルの子らが主に叫び求めたとき、主はイスラエルの子らのために一人の救助者を起こして、彼らを救われた。それはカレブの同族ケナズの子オテニエルである。'),
('JPN', '士师记', 7, 3, 10, '主の霊が彼の上に臨み、彼はイスラエルをさばいた。彼が戦いに出て行くと、主はアラムの王クシャン・リシュアタイムを彼の手に渡されたので、彼の手はクシャン・リシュアタイムを抑えた。'),
('JPN', '士师记', 7, 3, 11, '国は四十年の間、穏やかであった。こうして、ケナズの子オテニエルは死んだ。'),
('JPN', '士师记', 7, 3, 12, 'イスラエルの子らは、主の目に悪であることを重ねて行った。そこで主はモアブの王エグロンを強くして、イスラエルに逆らわせた。彼らが主の目に悪であることを行ったからである。'),
('JPN', '士师记', 7, 3, 13, 'エグロンはアンモン人とアマレク人を彼のもとに集め、イスラエルを攻めて打ち破った。彼らはなつめ椰子の町を占領した。'),
('JPN', '士师记', 7, 3, 14, 'こうして、イスラエルの子らは十八年の間、モアブの王エグロンに仕えた。'),
('JPN', '士师记', 7, 3, 15, 'イスラエルの子らが主に叫び求めたとき、主は彼らのために、一人の救助者を起こされた。ベニヤミン人ゲラの子で、左利きのエフデである。イスラエルの子らは、彼の手に託してモアブの王エグロンに貢ぎ物を送った。'),
('JPN', '士师记', 7, 3, 16, 'エフデは長さ約一キュビトの両刃の剣を作り、それを衣の下、右ももの上に帯で締め、'),
('JPN', '士师记', 7, 3, 17, 'モアブの王エグロンに貢ぎ物を携えて行った。エグロンはたいへん太った男であった。'),
('JPN', '士师记', 7, 3, 18, '貢ぎ物を献げ終わると、エフデは貢ぎ物を運んで来た者たちを見送り、'),
('JPN', '士师记', 7, 3, 19, '彼自身はギルガルのそばの石切り場のところから引き返して来て、こう言った。「王様、私はあなたに秘密のお知らせがあります。」すると王は「今は、言うな」と言ったので、そばに立っていた者たちはみな、彼のところから出て行った。'),
('JPN', '士师记', 7, 3, 20, 'エフデが王のところに行くと、王は、屋上にある彼専用の涼しい部屋に一人で座していた。エフデが「あなたに神のお告げがあります」と言うと、王はその座から立ち上がった。'),
('JPN', '士师记', 7, 3, 21, 'このとき、エフデは左手を伸ばし、右ももから剣を取り出して、王の腹を刺した。'),
('JPN', '士师记', 7, 3, 22, '柄も刃と一緒に入ってしまった。彼が剣を王の腹から抜かなかったので、脂肪が刃をふさいでしまった。エフデは小窓から出た。'),
('JPN', '士师记', 7, 3, 23, 'エフデは廊下へ出て行き、屋上の部屋の戸を閉じた。このようにして、彼はかんぬきをかけた。'),
('JPN', '士师记', 7, 3, 24, '彼が出て行くと、王のしもべたちがやって来た。彼らが見ると、屋上の部屋にかんぬきがかけられていたので、彼らは「王はきっと涼み部屋で用をたしておられるのだろう」と思った。'),
('JPN', '士师记', 7, 3, 25, 'しかし、いつまで待っても、王が屋上の部屋の戸を一向に開けようとしないので、しもべたちは鍵を取って戸を開けた。すると、なんと、彼らの主人は床に倒れて死んでいた。'),
('JPN', '士师记', 7, 3, 26, 'エフデは、しもべたちが手間取っている間に逃れ、石切り場のところを通って、セイラに逃れた。'),
('JPN', '士师记', 7, 3, 27, '到着すると、彼はエフライムの山地で角笛を吹き鳴らした。イスラエルの子らは、彼と一緒に山地から下って行った。彼がその先頭に立った。'),
('JPN', '士师记', 7, 3, 28, 'エフデは彼らに言った。「私の後について来なさい。主はあなたがたの敵モアブ人を、あなたがたの手に渡されたから。」そこで彼らはエフデの後について下り、モアブへ通じるヨルダン川の渡し場を攻め取って、一人もそこを渡らせなかった。'),
('JPN', '士师记', 7, 3, 29, 'このとき彼らは約一万人のモアブ人を討ち取った。そのモアブ人はみな、頑強で、力のある者たちだったが、一人として逃れた者はいなかった。'),
('JPN', '士师记', 7, 3, 30, 'こうして、モアブはその日イスラエルの手に下り、国は八十年の間、穏やかであった。'),
('JPN', '士师记', 7, 3, 31, 'エフデの後にアナトの子シャムガルが起こり、牛を追う棒でペリシテ人六百人を打ち殺した。彼もまた、イスラエルを救った。'),
('JPN', '士师记', 7, 4, 1, 'イスラエルの子らは、主の目に悪であることを重ねて行った。エフデは死んでいた。'),
('JPN', '士师记', 7, 4, 2, '主は、ハツォルを治めていたカナンの王ヤビンの手に彼らを売り渡された。ヤビンの軍の長はシセラで、ハロシェテ・ハ・ゴイムに住んでいた。'),
('JPN', '士师记', 7, 4, 3, 'すると、イスラエルの子らは主に叫び求めた。ヤビンには鉄の戦車が九百台あり、そのうえ二十年の間、イスラエルの子らをひどく圧迫したからである。'),
('JPN', '士师记', 7, 4, 4, 'ラピドテの妻で女預言者のデボラが、そのころイスラエルをさばいていた。'),
('JPN', '士师记', 7, 4, 5, '彼女は、エフライムの山地のラマとベテルの間にあるデボラのなつめ椰子の木の下に座し、イスラエルの子らは、さばきを求めて彼女のところに上って来た。'),
('JPN', '士师记', 7, 4, 6, 'あるとき、デボラは人を遣わして、ナフタリのケデシュからアビノアムの子バラクを呼び寄せ、彼に言った。「イスラエルの神、主はこう命じられたではありませんか。『行って、タボル山に陣を敷け。ナフタリ族とゼブルン族の中から一万人を取れ。'),
('JPN', '士师记', 7, 4, 7, 'わたしはヤビンの軍の長シセラとその戦車と大軍を、キション川のあなたのところに引き寄せ、彼をあなたの手に渡す』と。」'),
('JPN', '士师记', 7, 4, 8, 'バラクは彼女に言った。「もしあなたが私と一緒に行ってくださるなら、行きましょう。しかし、もしあなたが私と一緒に行ってくださらないなら、行きません。」'),
('JPN', '士师记', 7, 4, 9, 'そこでデボラは言った。「私は必ずあなたと一緒に行きます。ただし、あなたが行こうとしている道では、あなたに誉れは与えられません。主は女の手にシセラを売り渡されるからです。」こうして、デボラは立ってバラクと一緒にケデシュへ行った。'),
('JPN', '士师记', 7, 4, 10, 'バラクはゼブルンとナフタリをケデシュに呼び集め、一万人を引き連れて上った。デボラも彼と一緒に上った。'),
('JPN', '士师记', 7, 4, 11, 'ケニ人ヘベルは、モーセのしゅうとホバブの子孫のケニ人たちから離れて、ケデシュに近いツァアナニムの樫の木のそばで天幕を張っていた。'),
('JPN', '士师记', 7, 4, 12, '一方シセラに、アビノアムの子バラクがタボル山に登ったと知らされた。'),
('JPN', '士师记', 7, 4, 13, 'シセラは自分の戦車すべて、すなわち鉄の戦車九百台と、彼と一緒にいた兵をみな、ハロシェテ・ハ・ゴイムからキション川に呼び集めた。'),
('JPN', '士师记', 7, 4, 14, 'デボラはバラクに言った。「立ち上がりなさい。今日、主があなたの手にシセラを渡される。主があなたに先立って出て行かれるではありませんか。」そこで、バラクはタボル山から下り、一万人が彼の後に従った。'),
('JPN', '士师记', 7, 4, 15, '主は、シセラとそのすべての戦車とすべての陣営の者を、剣の刃をもってバラクの前で混乱させられた。シセラは戦車から飛び降り、自らの足で逃げた。'),
('JPN', '士师记', 7, 4, 16, 'それでバラクは、戦車と陣営をハロシェテ・ハ・ゴイムまで追いつめた。こうして、シセラの陣営の者はみな剣の刃に倒れ、残された者は一人もいなかった。'),
('JPN', '士师记', 7, 4, 17, 'しかし、シセラは自らの足でケニ人ヘベルの妻ヤエルの天幕に逃げた。ハツォルの王ヤビンとケニ人ヘベルの家は友好関係にあったからである。'),
('JPN', '士师记', 7, 4, 18, 'ヤエルはシセラを迎えに出て来て、彼に言った。「お立ち寄りください、ご主人様。私のところにお立ち寄りください。ご心配には及びません。」シセラが彼女の天幕に入ったので、ヤエルは彼を布でおおった。'),
('JPN', '士师记', 7, 4, 19, 'シセラはヤエルに言った。「どうか、水を少し飲ませてくれ。喉が渇いているから。」ヤエルは乳の皮袋を開けて彼に飲ませ、また彼をおおった。'),
('JPN', '士师记', 7, 4, 20, 'シセラはまた彼女に言った。「天幕の入り口に立っていてくれ。もしだれかが来て、ここにだれかいないかと尋ねたら、いないと言うように。」'),
('JPN', '士师记', 7, 4, 21, 'だが、ヘベルの妻ヤエルは天幕の杭を取ると、槌を手にしてそっと彼に近づき、そのこめかみに杭を打ち込んで地に突き刺した。彼は疲れて熟睡していたのである。こうして彼は死んだ。'),
('JPN', '士师记', 7, 4, 22, 'ちょうどそのとき、バラクがシセラを追って来たので、ヤエルは彼を迎えに出て言った。「おいでください。あなたが捜している人をお見せしましょう。」彼がヤエルのところに行くと、なんと、シセラが倒れて死んでおり、そのこめかみには杭が刺さっていた。'),
('JPN', '士师记', 7, 4, 23, 'こうして神は、その日、イスラエル人の前でカナンの王ヤビンを屈服させた。'),
('JPN', '士师记', 7, 4, 24, 'イスラエル人の勢力は、カナンの王ヤビンに対してますます強くなり、ついにカナンの王ヤビンを滅ぼすに至った。'),
('JPN', '士师记', 7, 5, 1, 'その日、デボラとアビノアムの子バラクは、こう歌った。'),
('JPN', '士师记', 7, 5, 2, '「イスラエルでかしらたちが先頭に立ち、民が進んで身を献げるとき、主をほめたたえよ。'),
('JPN', '士师记', 7, 5, 3, '聞け、王たち。耳を傾けよ、君主たち。私、この私は主に向かって歌う。イスラエルの神、主にほめ歌を歌う。'),
('JPN', '士师记', 7, 5, 4, '主よ。あなたがセイルから出て、エドムの野から進んで行かれたとき、大地は揺れ、天も滴り、密雲も水を滴らせました。'),
('JPN', '士师记', 7, 5, 5, '山々は主の前に流れ去りました。シナイさえもイスラエルの神である主の前に。'),
('JPN', '士师记', 7, 5, 6, 'アナトの子シャムガルの時代、またヤエルの時代に、隊商は絶え、旅人は脇道を通った。'),
('JPN', '士师记', 7, 5, 7, '農夫は絶えた。イスラエルに絶えた。私デボラが立ち、イスラエルに母として立ったときまで。'),
('JPN', '士师记', 7, 5, 8, '新しい神々が選ばれたとき、そのとき、戦いは門まで及んでいたが、イスラエルの四万人のうちに、盾と槍が見られただろうか。'),
('JPN', '士师记', 7, 5, 9, '私の心はイスラエルの指導者たちに、民のうちの進んで身を献げる者たちに向かう。主をほめたたえよ。'),
('JPN', '士师记', 7, 5, 10, '茶色の雌ろばに乗る者たち、敷き物の上に座す者たち、道を歩く者たちよ、語り伝えよ。'),
('JPN', '士师记', 7, 5, 11, '水飲み場で水を分ける者たちの声を聞いて。そこで彼らは主の義と、イスラエルにいる主の村人たちの義をたたえる。そのとき、主の民は城門に下って行った。'),
('JPN', '士师记', 7, 5, 12, '目覚めよ、目覚めよ、デボラ。目覚めよ、目覚めよ、歌声をあげよ。起きよ、バラク。捕虜を引いて行け、アビノアムの子よ。'),
('JPN', '士师记', 7, 5, 13, 'そのとき、生き残った者は貴人のように下りて来た。主の民は私のところに勇士のように下りて来た。'),
('JPN', '士师记', 7, 5, 14, 'エフライムからはその根がアマレクにある者が下りて来た。ベニヤミンはあなたの後に続いてあなたの民のうちにいる。マキルからは指導者たちがゼブルンからは指揮を執る者たちが下りて来た。'),
('JPN', '士师记', 7, 5, 15, 'イッサカルの長たちはデボラとともにいた。イッサカルはバラクと同じく歩兵たちとともに平地に送られた。ルベンの諸支族の決意は固かった。'),
('JPN', '士师记', 7, 5, 16, 'なぜ、あなたは二つの鞍袋の間に座って、羊の群れに笛吹くのを聞いていたのか。ルベンの諸支族の間には、深い反省があった。'),
('JPN', '士师记', 7, 5, 17, 'ギルアデはヨルダンの川向こうにとどまった。ダンはなぜ船に残ったのか。アシェルは海辺に座り、その波止場のそばにとどまっていた。'),
('JPN', '士师记', 7, 5, 18, 'ゼブルンは、いのちを賭して死をいとわぬ民。野の高い所にいるナフタリも。'),
('JPN', '士师记', 7, 5, 19, '王たちはやって来て戦った。そのとき、カナンの王たちは戦った。メギドの流れのそばのタアナクで。彼らが銀の分捕り品を取ることはなかった。'),
('JPN', '士师记', 7, 5, 20, '天から、もろもろの星が下って来て戦った。その軌道から離れて、シセラと戦った。'),
('JPN', '士师记', 7, 5, 21, 'キション川は彼らを押し流した。昔からの川、キション川が。わがたましいよ、力強く進め。'),
('JPN', '士师记', 7, 5, 22, 'そのとき、馬のひづめは地を踏み鳴らし、その荒馬は全力で疾走する。'),
('JPN', '士师记', 7, 5, 23, '主の使いは言った。『メロズをのろえ、その住民を激しくのろえ。彼らは主の手助けに来ず、勇士たちとともに、主の手助けに来なかったからだ。』'),
('JPN', '士师记', 7, 5, 24, '女の中で最も祝福されるのはヤエル、ケニ人ヘベルの妻。天幕に住む女の中で最も祝福されている。'),
('JPN', '士师记', 7, 5, 25, 'シセラが水を求めると、彼女は乳を与え、高価な鉢で凝乳を差し出した。'),
('JPN', '士师记', 7, 5, 26, 'ヤエルは杭を手にし、右手に職人の槌をかざしシセラを打って、その頭に打ち込み、こめかみを砕いて刺し貫いた。'),
('JPN', '士师记', 7, 5, 27, '彼女の足もとに彼は膝をつき、倒れ、横たわった。彼女の足もとに彼は膝をつき、倒れた。膝をついた場所で、倒れて滅びた。'),
('JPN', '士师记', 7, 5, 28, '窓から見下ろして、シセラの母は格子窓から見下ろして嘆いた。『なぜ、あれの車が来るのは遅れているのか。なぜ、あれの戦車の動きは鈍いのか。』'),
('JPN', '士师记', 7, 5, 29, '知恵のある女官たちは彼女に答え、彼女も同じことばを繰り返した。'),
('JPN', '士师记', 7, 5, 30, '『彼らは分捕り物を見つけ出し、それを分けているのではありませんか。勇士それぞれには一人か二人の娘を、シセラには染め織物を分捕り物として。分捕り物として、刺繡した染め織物を、刺繡した染め織物二枚を首に、分捕り物として。』'),
('JPN', '士师记', 7, 5, 31, 'このように、主よ、あなたの敵がみな滅び、主を愛する者が、力強く昇る太陽のようになりますように。」こうして、国は四十年の間、穏やかであった。'),
('JPN', '士师记', 7, 6, 1, 'イスラエルの子らは、主の目に悪であることを行った。そこで、主は七年の間、彼らをミディアン人の手に渡された。'),
('JPN', '士师记', 7, 6, 2, 'ミディアン人の勢力がイスラエルに対して強くなったので、イスラエル人はミディアン人を避けて、山々にある洞窟や洞穴や要害を自分たちのものとした。'),
('JPN', '士师记', 7, 6, 3, 'イスラエルが種を蒔くと、いつもミディアン人、アマレク人、そして東方の人々が上って来て、彼らを襲った。'),
('JPN', '士师记', 7, 6, 4, '彼らはイスラエル人に向かって陣を敷き、その地の産物をガザに至るまで荒らして、いのちをつなぐ糧も、羊も牛もろばもイスラエルに残さなかった。'),
('JPN', '士师记', 7, 6, 5, '実に、彼らは自分たちの家畜と天幕を持って上り、いなごの大群のように押しかけて来た。彼らとそのらくだは数えきれないほどであった。彼らは国を荒らそうと入って来たのであった。'),
('JPN', '士师记', 7, 6, 6, 'こうして、イスラエルはミディアン人の前で非常に弱くなった。すると、イスラエルの子らは主に叫び求めた。'),
('JPN', '士师记', 7, 6, 7, 'イスラエルの子らがミディアン人のゆえに主に叫び求めたとき、'),
('JPN', '士师记', 7, 6, 8, '主は一人の預言者をイスラエルの子らに遣わされた。預言者は彼らに言った。「イスラエルの神、主はこう言われる。わたしはあなたがたをエジプトから上らせ、奴隷の家から導き出し、'),
('JPN', '士师记', 7, 6, 9, 'エジプト人の手と、圧迫するすべての者の手から助け出し、あなたがたの前から彼らを追い出して、その地をあなたがたに与えた。'),
('JPN', '士师记', 7, 6, 10, 'わたしはあなたがたに言った。『わたしが主、あなたがたの神である。あなたがたが住んでいる地のアモリ人の神々を恐れてはならない』と。ところが、あなたがたはわたしの声に聞き従わなかった。」'),
('JPN', '士师记', 7, 6, 11, 'さて主の使いが来て、アビエゼル人ヨアシュに属するオフラにある樫の木の下に座った。このとき、ヨアシュの子ギデオンは、ぶどうの踏み場で小麦を打っていた。ミディアン人から隠れるためであった。'),
('JPN', '士师记', 7, 6, 12, '主の使いが彼に現れて言った。「力ある勇士よ、主があなたとともにおられる。」'),
('JPN', '士师记', 7, 6, 13, 'ギデオンは御使いに言った。「ああ、主よ。もし主が私たちとともにおられるなら、なぜこれらすべてのことが、私たちに起こったのですか。『主は私たちをエジプトから上らせたではないか』と言って、先祖が伝えたあの驚くべきみわざはみな、どこにあるのですか。今、主は私たちを捨てて、ミディアン人の手に渡されたのです。」'),
('JPN', '士师记', 7, 6, 14, 'すると、主は彼の方を向いて言われた。「行け、あなたのその力で。あなたはイスラエルをミディアン人の手から救うのだ。わたしがあなたを遣わすのではないか。」'),
('JPN', '士师记', 7, 6, 15, 'ギデオンは言った。「ああ、主よ。どうすれば私はイスラエルを救えるでしょうか。ご存じのように、私の氏族はマナセの中で最も弱く、そして私は父の家で一番若いのです。」'),
('JPN', '士师记', 7, 6, 16, '主はギデオンに言われた。「わたしはあなたとともにいる。あなたは一人を討つようにミディアン人を討つ。」'),
('JPN', '士师记', 7, 6, 17, 'すると、ギデオンは言った。「もし私がみこころにかなうのでしたら、私と話しておられるのがあなたであるというしるしを、私に見せてください。'),
('JPN', '士师记', 7, 6, 18, 'どうか、私が戻って来るまでここを離れないでください。贈り物を持って来て、御前に供えますので。」主は、「あなたが戻って来るまで、ここにいよう」と言われた。'),
('JPN', '士师记', 7, 6, 19, 'ギデオンは行って、子やぎ一匹を調理し、粉一エパで種なしパンを作った。そして、その肉をかごに入れ、また肉汁を壺に入れ、樫の木の下にいる方のところに持って来て差し出した。'),
('JPN', '士师记', 7, 6, 20, '神の使いは彼に言った。「肉と種なしパンを取って、この岩の上に置き、その肉汁を注げ。」そこで、ギデオンはそのようにした。'),
('JPN', '士师记', 7, 6, 21, '主の使いは、手にしていた杖の先を伸ばして、肉と種なしパンに触れた。すると、火が岩から燃え上がって、肉と種なしパンを焼き尽くしてしまった。主の使いは去って見えなくなった。'),
('JPN', '士师记', 7, 6, 22, 'ギデオンには、この方が主の使いであったことが分かった。ギデオンは言った。「ああ、神、主よ。私は顔と顔を合わせて主の使いを見てしまいました。」'),
('JPN', '士师记', 7, 6, 23, '主は彼に言われた。「安心せよ。恐れるな。あなたは死なない。」'),
('JPN', '士师记', 7, 6, 24, 'ギデオンはそこに主のために祭壇を築いて、これをアドナイ・シャロムと名づけた。これは今日まで、アビエゼル人のオフラに残っている。'),
('JPN', '士师记', 7, 6, 25, 'その夜、主はギデオンに言われた。「あなたの父の若い雄牛で、七歳の第二の雄牛を取り、あなたの父が持っているバアルの祭壇を壊し、そのそばにあるアシェラ像を切り倒せ。'),
('JPN', '士师记', 7, 6, 26, 'あなたの神、主のために、その砦の頂に石を積んで祭壇を築け。あの第二の雄牛を取り、切り倒したアシェラ像の木で全焼のささげ物を献げよ。」'),
('JPN', '士师记', 7, 6, 27, 'そこで、ギデオンは自分のしもべの中から十人を引き連れて、主が言われたとおりに行った。しかし、彼は父の家の者や、町の人々を恐れたので、昼間はそれをせず、夜に行った。'),
('JPN', '士师记', 7, 6, 28, '町の人々が翌朝早く起きて見ると、なんと、バアルの祭壇は打ち壊され、そのそばにあったアシェラ像は切り倒され、新しく築かれた祭壇の上には、第二の雄牛が献げられていた。'),
('JPN', '士师记', 7, 6, 29, 'そこで、彼らは互いに言った。「だれがこのようなことをしたのか。」彼らは調べて尋ね回り、「ヨアシュの子ギデオンがこれをしたのだ」と言った。'),
('JPN', '士师记', 7, 6, 30, '町の人々はヨアシュに言った。「おまえの息子を引っ張り出して殺せ。あれはバアルの祭壇を打ち壊し、そばにあったアシェラ像も切り倒したのだ。」'),
('JPN', '士师记', 7, 6, 31, 'すると、ヨアシュは自分に向かって来たすべての者に言った。「あなたがたは、バアルのために争おうというのか。あなたがたは、それを救おうとするのか。バアルのために争う者は、朝までに殺される。もしバアルが神であるなら、自分の祭壇が打ち壊されたのだから、自分で争えばよいのだ。」'),
('JPN', '士师记', 7, 6, 32, 'こうして、その日、父は「バアルは自分で彼と争えばよい。なぜなら彼はバアルの祭壇を打ち壊したのだから」と言って、ギデオンをエルバアルと呼んだ。'),
('JPN', '士师记', 7, 6, 33, 'ミディアン人やアマレク人、また東方の人々はみな連合してヨルダン川を渡り、イズレエルの平野に陣を敷いた。'),
('JPN', '士师记', 7, 6, 34, '主の霊がギデオンをおおったので、彼が角笛を吹き鳴らすと、アビエゼル人が集まって来て、彼に従った。'),
('JPN', '士师记', 7, 6, 35, 'ギデオンはマナセの全域に使者を遣わしたので、彼らもまた、呼び集められて彼に従った。また彼は、アシェル、ゼブルン、そしてナフタリに使者を遣わし、彼らも上って来て合流した。'),
('JPN', '士师记', 7, 6, 36, 'ギデオンは神に言った。「もしあなたが言われたとおり、私の手によってイスラエルを救おうとされるのなら、'),
('JPN', '士师记', 7, 6, 37, 'ご覧ください。私は刈り取った一匹分の羊の毛を打ち場に置きます。もしその羊の毛だけに露が降りていて、土全体が乾いていたら、あなたが言われたとおり、私の手によって、あなたがイスラエルをお救いになると私に分かります。」'),
('JPN', '士师记', 7, 6, 38, 'すると、そのようになった。ギデオンが翌日朝早く、羊の毛を押しつけて、その羊の毛から露を絞り出すと、鉢は水でいっぱいになった。'),
('JPN', '士师记', 7, 6, 39, 'ギデオンは神に言った。「私に向かって御怒りを燃やさないでください。私にもう一度だけ言わせてください。どうか、この羊の毛でもう一度だけ試みさせてください。今度はこの羊の毛だけが乾いていて、土全体には露が降りるようにしてください。」'),
('JPN', '士师记', 7, 6, 40, '神はその夜、そのようにされた。羊の毛だけが乾いていて、土全体には露が降りていたのであった。'),
('JPN', '士师记', 7, 7, 1, 'エルバアルすなわちギデオンと、彼とともにいた兵はみな、朝早くハロデの泉のそばに陣を敷いた。ミディアン人の陣営は、その北、モレの丘に沿った平地にあった。'),
('JPN', '士师记', 7, 7, 2, '主はギデオンに言われた。「あなたと一緒にいる兵は多すぎるので、わたしはミディアン人を彼らの手に渡さない。イスラエルが『自分の手で自分を救った』と言って、わたしに向かって誇るといけないからだ。'),
('JPN', '士师记', 7, 7, 3, '今、兵たちの耳に呼びかけよ。『だれでも恐れおののく者は帰り、ギルアデ山から離れよ』と。」すると、兵のうちの二万二千人が帰って行き、一万人が残った。'),
('JPN', '士师记', 7, 7, 4, '主はギデオンに言われた。「兵はまだ多すぎる。彼らを連れて水辺に下って行け。わたしはそこで、あなたのために彼らをより分けよう。わたしがあなたに、『この者はあなたと一緒に行くべきである』と言うなら、その者はあなたと一緒に行かなければならない。またわたしがあなたに、『この者はあなたと一緒に行くべきではない』と言うなら、だれも行ってはならない。」'),
('JPN', '士师记', 7, 7, 5, 'そこでギデオンは兵を連れて、水辺に下って行った。主はギデオンに言われた。「犬がなめるように、舌で水をなめる者は残らず別にせよ。また、飲むために膝をつく者もすべてそうせよ。」'),
('JPN', '士师记', 7, 7, 6, 'すると、手で口に水を運んですすった者の数が三百人であった。残りの兵はみな、膝をついて水を飲んだ。'),
('JPN', '士师记', 7, 7, 7, '主はギデオンに言われた。「手で水をすすった三百人で、わたしはあなたがたを救い、ミディアン人をあなたの手に渡す。残りの兵はみな、それぞれ自分のところに帰らせよ。」'),
('JPN', '士师记', 7, 7, 8, 'そこで三百人の者は、兵の食糧と角笛を手に取った。こうして、ギデオンはイスラエル人をみな、それぞれ自分の天幕に送り返し、三百人の者だけを引きとどめた。ミディアン人の陣営は、彼から見て下の方の平地にあった。'),
('JPN', '士师记', 7, 7, 9, 'その夜、主はギデオンに言われた。「立って、あの陣営に攻め下れ。それをあなたの手に渡したから。'),
('JPN', '士师记', 7, 7, 10, 'もし、あなたが下って行くことを恐れるなら、あなたの従者プラと一緒に陣営に下って行き、'),
('JPN', '士师记', 7, 7, 11, '彼らが何を言っているかを聞け。その後、あなたの手は強くなって、陣営に攻め下ることができる。」ギデオンと従者プラは、陣営の中の隊列の端まで下って行った。'),
('JPN', '士师记', 7, 7, 12, 'ミディアン人やアマレク人、またすべての東方の民が、いなごのように大勢、平地に伏していた。彼らのらくだは、海辺の砂のように多くて数えきれなかった。'),
('JPN', '士师记', 7, 7, 13, 'ギデオンがそこに来ると、ちょうど一人の者が仲間に夢の話をしていた。「聞いてくれ。私は夢を見た。見ると、大麦のパンの塊が一つ、ミディアン人の陣営に転がって来て、天幕に至り、それを打ったので、それは崩れ落ちて、ひっくり返った。こうして天幕は倒れてしまった。」'),
('JPN', '士师记', 7, 7, 14, 'すると、その仲間は答えて言った。「それはイスラエル人ヨアシュの子ギデオンの剣でなくて何であろうか。神が彼の手に、ミディアン人と全陣営を渡されたのだ。」'),
('JPN', '士师记', 7, 7, 15, 'ギデオンはこの夢の話と解釈を聞いたとき、主を礼拝し、イスラエルの陣営に戻って言った。「立て。主はミディアン人の陣営をあなたがたの手に渡された。」'),
('JPN', '士师记', 7, 7, 16, '彼は三百人を三隊に分け、全員の手に角笛と空の壺を持たせ、その壺の中にたいまつを入れさせて、'),
('JPN', '士师记', 7, 7, 17, '彼らに言った。「私を見て、あなたがたも同じようにしなければならない。見よ。私が陣営の端に着いたら、私がするように、あなたがたもしなければならない。'),
('JPN', '士师记', 7, 7, 18, '私と、私と一緒にいるすべての者が角笛を吹いたら、あなたがたもまた、全陣営を囲んで角笛を吹き鳴らし、『主のため、ギデオンのため』と言わなければならない。」'),
('JPN', '士师记', 7, 7, 19, '真夜中の夜番が始まるとき、ギデオンと、彼と一緒にいた百人の者が陣営の端に着いた。ちょうどそのとき、番兵が交代したばかりであったので、彼らは角笛を吹き鳴らし、その手に持っていた壺を打ち壊した。'),
('JPN', '士师记', 7, 7, 20, '三隊の者が角笛を吹き鳴らして、壺を打ち砕き、左手にたいまつを、右手に吹き鳴らす角笛を固く握って「主のため、ギデオンのための剣」と叫んだ。'),
('JPN', '士师记', 7, 7, 21, '彼らはそれぞれ持ち場に立ち、陣営を取り囲んだので、陣営の者はみな走り出し、大声をあげて逃げた。'),
('JPN', '士师记', 7, 7, 22, '三百人が角笛を吹き鳴らしている間に、主は陣営全体にわたって同士討ちが起こるようにされたので、軍勢はツェレラの方のベテ・ハ・シタや、タバテの近くのアベル・メホラの岸辺まで逃げた。'),
('JPN', '士师记', 7, 7, 23, 'イスラエル人は、ナフタリ、アシェル、また全マナセから呼び集められて、ミディアン人を追撃した。'),
('JPN', '士师记', 7, 7, 24, 'ギデオンはエフライムの山地全域に使者を遣わして言った。「下りて来て、ミディアン人を迎え撃て。彼らから、ベテ・バラまでの流れと、ヨルダン川を攻め取れ。」エフライム人はみな呼び集められ、ベテ・バラまでの流れと、ヨルダン川を攻め取った。'),
('JPN', '士师记', 7, 7, 25, '彼らはミディアン人の二人の首長オレブとゼエブを捕らえ、オレブをオレブの岩で殺し、ゼエブをゼエブのぶどうの踏み場で殺した。こうしてエフライム人はミディアン人を追撃したが、オレブとゼエブの首は、ヨルダン川の反対側にいたギデオンのところに持って行った。'),
('JPN', '士师记', 7, 8, 1, 'エフライムの人々はギデオンに言った。「あなたは私たちに何ということをしたのか。ミディアン人と戦いに行くとき、私たちに呼びかけなかったとは。」こうして彼らはギデオンを激しく責めた。'),
('JPN', '士师记', 7, 8, 2, 'ギデオンは彼らに言った。「あなたがたに比べて、私が今、何をしたというのですか。アビエゼルのぶどうの収穫よりも、エフライムの取り残した実のほうが良かったではありませんか。'),
('JPN', '士师记', 7, 8, 3, '神はあなたがたの手にミディアン人の首長オレブとゼエブを渡されました。あなたがたに比べて、私が何をなし得たというのですか。」ギデオンがこのように話すと、彼らの怒りは和らいだ。'),
('JPN', '士师记', 7, 8, 4, 'それからギデオンは、彼に従う三百人とヨルダン川を渡った。彼らは疲れていたが、追撃を続けた。'),
('JPN', '士师记', 7, 8, 5, '彼はスコテの人々に言った。「どうか、私について来た兵に円形パンを下さい。彼らは疲れているからです。私はミディアン人の王ゼバフとツァルムナを追っているのです。」'),
('JPN', '士师记', 7, 8, 6, 'すると、スコテの首長たちは言った。「おまえは今、ゼバフとツァルムナの手首を手にしているのか。われわれがおまえの部隊にパンを与えなければならないとは。」'),
('JPN', '士师记', 7, 8, 7, 'ギデオンは言った。「そういうことなら、主が私の手にゼバフとツァルムナを渡されるとき、私は荒野の茨やとげで、おまえのからだを打ちのめす。」'),
('JPN', '士师记', 7, 8, 8, 'ギデオンはそこからペヌエルに上って行き、同じように彼らに話した。すると、ペヌエルの人々もスコテの人々と同じように彼らに答えた。'),
('JPN', '士师记', 7, 8, 9, 'そこでギデオンはまたペヌエルの人々に言った。「私が無事に帰って来たら、このやぐらを打ち壊す。」'),
('JPN', '士师记', 7, 8, 10, 'ゼバフとツァルムナはカルコルにいたが、約一万五千人からなる陣営の者もともにいた。これは東方の民の陣営全体のうち、生き残った者のすべてであった。剣を使う者十二万人が、すでに倒されていた。'),
('JPN', '士师记', 7, 8, 11, 'そこでギデオンは、ノバフとヨグボハの東の、天幕に住む人々の道を上って行き、陣営を討った。陣営は安心しきっていた。'),
('JPN', '士师记', 7, 8, 12, 'ゼバフとツァルムナは逃げたが、ギデオンは彼らの後を追った。彼は、ミディアンの二人の王ゼバフとツァルムナを捕らえ、その全陣営を震え上がらせた。'),
('JPN', '士师记', 7, 8, 13, 'こうして、ヨアシュの子ギデオンは、ヘレスの坂道を通って戦いから帰って来た。'),
('JPN', '士师记', 7, 8, 14, '彼はスコテの人々の中から一人の若者を捕らえて尋問した。すると、その若者はギデオンのために、スコテの首長たちと七十七人の長老たちの名を書いた。'),
('JPN', '士师记', 7, 8, 15, 'ギデオンはスコテの人々のところに行き、そして言った。「見よ、ゼバフとツァルムナを。彼らは、おまえたちが私をそしって、『おまえは、今、ゼバフとツァルムナの手首を手にしているのか。おまえに従う疲れた者たちに、われわれがパンを与えなければならないとは』と言ったあの者たちだ。」'),
('JPN', '士师记', 7, 8, 16, 'ギデオンはその町の長老たちを捕らえ、また荒野の茨やとげを取って、それでスコテの人々に思い知らせた。'),
('JPN', '士师记', 7, 8, 17, 'また彼はペヌエルのやぐらを打ち壊して、町の人々を殺した。'),
('JPN', '士师记', 7, 8, 18, 'それから、ギデオンはゼバフとツァルムナに言った。「おまえたちがタボルで殺した者たちはどんな人たちだったか。」彼らは答えた。「彼らはあなたによく似ていました。どの人も王子のような姿でした。」'),
('JPN', '士师记', 7, 8, 19, 'ギデオンは言った。「私の兄弟、私の母の息子たちだ。主は生きておられる。おまえたちが彼らを生かしておいてくれたなら、私はおまえたちを殺しはしなかったのだが。」'),
('JPN', '士师记', 7, 8, 20, 'そしてギデオンは自分の長男エテルに「立って、彼らを殺しなさい」と言ったが、若者は自分の剣を抜かなかった。彼はまだ若く、恐ろしかったからである。'),
('JPN', '士师记', 7, 8, 21, 'そこで、ゼバフとツァルムナは言った。「あなたが立って、私たちに討ちかかりなさい。人の勇気はそれぞれ違うのだから。」ギデオンは立って、ゼバフとツァルムナを殺し、彼らのらくだの首に掛けてあった三日月形の飾りを取った。'),
('JPN', '士师记', 7, 8, 22, 'イスラエル人はギデオンに言った。「あなたも、あなたの子も、あなたの孫も、私たちを治めてください。あなたが私たちをミディアン人の手から救ったのですから。」'),
('JPN', '士师记', 7, 8, 23, 'しかしギデオンは彼らに言った。「私はあなたがたを治めません。また、私の息子も治めません。主があなたがたを治められます。」'),
('JPN', '士师记', 7, 8, 24, 'ギデオンはまた彼らに言った。「あなたがたに一つお願いしたい。各自の分捕り物の耳輪を私に下さい。」殺された者たちはイシュマエル人で、金の耳輪をつけていた。'),
('JPN', '士师记', 7, 8, 25, '彼らは「もちろん差し上げます」と答えて、上着を広げ、各自がその分捕り物の耳輪をその中に投げ込んだ。'),
('JPN', '士师记', 7, 8, 26, 'ギデオンが求めた金の耳輪の重さは、金千七百シェケルであった。このほかに、三日月形の飾りや、耳飾りや、ミディアンの王たちの着ていた赤紫の衣、またほかに、彼らのらくだの首に掛けてあった首飾りなどもあった。'),
('JPN', '士师记', 7, 8, 27, 'ギデオンは、それでエポデを一つ作り、彼の町オフラにそれを置いた。イスラエルはみなそれを慕って、そこで淫行を行った。それはギデオンとその一族にとって罠となった。'),
('JPN', '士师记', 7, 8, 28, 'こうしてミディアン人はイスラエル人の前に屈服させられ、二度とその頭を上げなかった。国はギデオンの時代、四十年の間、穏やかであった。'),
('JPN', '士师记', 7, 8, 29, 'ヨアシュの子エルバアルは帰り、自分の家に住んだ。'),
('JPN', '士师记', 7, 8, 30, 'ギデオンには彼の腰から生まれ出た息子が七十人いた。彼には大勢の妻がいたからである。'),
('JPN', '士师记', 7, 8, 31, 'シェケムにいた側女もまた、彼に一人の男の子を産んだ。そこでギデオンはアビメレクという名をつけた。'),
('JPN', '士师记', 7, 8, 32, 'ヨアシュの子ギデオンは幸せな晩年を過ごして死に、アビエゼル人のオフラにある父ヨアシュの墓に葬られた。'),
('JPN', '士师记', 7, 8, 33, 'ギデオンが死ぬと、イスラエルの子らはすぐに元に戻り、もろもろのバアルを慕って淫行を行い、バアル・ベリテを自分たちの神とした。'),
('JPN', '士师记', 7, 8, 34, 'イスラエルの子らは、周囲のすべての敵の手から救い出してくださった彼らの神、主を、心に留めなかった。'),
('JPN', '士师记', 7, 8, 35, '彼らは、エルバアル、すなわちギデオンがイスラエルのために尽くしたあらゆる善意にふさわしい誠意を、彼の家族に対して尽くさなかった。'),
('JPN', '士师记', 7, 9, 1, 'さて、エルバアルの子アビメレクは、シェケムにいる母の身内の者たちのところに行き、彼らと母の一族の氏族全員に告げて言った。'),
('JPN', '士师记', 7, 9, 2, '「どうかシェケムのすべての住民の耳に告げてください。『あなたがたにとって、エルバアルの息子七十人全員であなたがたを治めるのと、ただ一人があなたがたを治めるのとでは、どちらがよいか。私があなたがたの骨肉であることを思い起こすがよい』と。」'),
('JPN', '士师记', 7, 9, 3, 'アビメレクの母の身内の者たちが、彼の代わりに、これらのことをみな、シェケムのすべての住民の耳に告げたとき、彼らの心はアビメレクに傾いた。彼らが「彼は私たちの身内の者だ」と思ったからである。'),
('JPN', '士师记', 7, 9, 4, '彼らは、バアル・ベリテの神殿から銀七十シェケルを取り出して彼に与えた。アビメレクはそれで、粗暴なならず者たちを雇った。彼らはアビメレクに従った。'),
('JPN', '士师记', 7, 9, 5, 'アビメレクはオフラにある彼の父の家に行って、自分の兄弟であるエルバアルの息子たち七十人を一つの石の上で殺した。しかし、エルバアルの末の子ヨタムは隠れていたので生き残った。'),
('JPN', '士师记', 7, 9, 6, 'シェケムのすべての住民とベテ・ミロのすべての人々は集まり、行って、シェケムにある石柱のそばの樫の木の傍らで、アビメレクを王とした。'),
('JPN', '士师记', 7, 9, 7, 'このことがヨタムに告げられたとき、彼は行って、ゲリジム山の頂上に立ち、声を張り上げ、彼らに叫んだ。「私に聞け、シェケムの人々よ。そうすれば神はあなたがたに耳を傾けてくださる。'),
('JPN', '士师记', 7, 9, 8, '木々が出かけて行って、自分たちの上に王を立てて油を注ごうとした。木々はオリーブの木に言った。『私たちの王となってください。』'),
('JPN', '士师记', 7, 9, 9, 'すると、オリーブの木は彼らに言った。『私は、神と人をあがめるために使われる私の油を捨て置いて、木々の上にそよぐために行かなければならないのだろうか。』'),
('JPN', '士师记', 7, 9, 10, '木々はいちじくの木に言った。『あなたが来て、私たちの王となってください。』'),
('JPN', '士师记', 7, 9, 11, 'しかし、いちじくの木は彼らに言った。『私は、私の甘みと良い実を捨て置いて、木々の上にそよぐために行かなければならないのだろうか。』'),
('JPN', '士师记', 7, 9, 12, '木々はぶどうの木に言った。『あなたが来て、私たちの王となってください。』'),
('JPN', '士师记', 7, 9, 13, 'しかし、ぶどうの木は彼らに言った。『私は、神と人を喜ばせる私の新しいぶどう酒を捨て置いて、木々の上にそよぐために行かなければならないのだろうか。』'),
('JPN', '士师记', 7, 9, 14, 'そこで、すべての木が茨に言った。『あなたが来て、私たちの王となってください。』'),
('JPN', '士师记', 7, 9, 15, '茨は木々に言った。『もしあなたがたが誠意をもって私に油を注ぎ、あなたがたの王とするなら、来て、私の陰に身を避けよ。もしそうでなければ、茨から火が出て、レバノンの杉の木を焼き尽くすだろう。』'),
('JPN', '士师记', 7, 9, 16, '今、あなたがたは誠意と真心をもって行動して、アビメレクを王にしたのか。あなたがたはエルバアルとその家族に良くして、彼の手柄に報いたのか。'),
('JPN', '士师记', 7, 9, 17, '私の父は、あなたがたのために戦い、自分のいのちをかけて、あなたがたをミディアン人の手から助け出したのだ。'),
('JPN', '士师记', 7, 9, 18, 'しかし、あなたがたは今日、私の父の家に背いて立ち上がり、その息子たち七十人を一つの石の上で殺し、また、あなたがたの身内の者だからというので、女奴隷の子アビメレクをシェケムの住民たちの上に王として立てた。'),
('JPN', '士师记', 7, 9, 19, 'もしあなたがたが、今日、エルバアルとその家族に対して誠意と真心をもって行動したのなら、あなたがたはアビメレクによって喜ぶがよい。彼も、あなたがたによって喜ぶがよい。'),
('JPN', '士师记', 7, 9, 20, 'もしそうでなかったなら、アビメレクから火が出て、シェケムの住民とベテ・ミロを焼き尽くし、シェケムの住民とベテ・ミロからも火が出て、アビメレクを焼き尽くすだろう。」'),
('JPN', '士师记', 7, 9, 21, 'それから、ヨタムは逃げ去ってベエルに行き、兄弟アビメレクの顔を避けてそこに住んだ。'),
('JPN', '士师记', 7, 9, 22, 'アビメレクは三年間、イスラエルを支配した。'),
('JPN', '士师记', 7, 9, 23, '神は、わざわいの霊をアビメレクとシェケムの住民の間に送られたので、シェケムの住民たちはアビメレクを裏切った。'),
('JPN', '士师记', 7, 9, 24, 'こうして、エルバアルの七十人の息子たちに対する暴虐への報いが現れ、彼らの血が、彼らを殺した兄弟アビメレクと、アビメレクに手を貸してその兄弟たちを殺したシェケムの住民たちの上に降りかかった。'),
('JPN', '士师记', 7, 9, 25, 'シェケムの住民たちは、アビメレクを待ち伏せする者たちを山々の頂上に置き、また道を通り過ぎるすべての者から略奪した。やがて、このことがアビメレクに告げられた。'),
('JPN', '士师记', 7, 9, 26, 'エベデの子ガアルとその身内の者たちが来て、シェケムを通りかかったとき、シェケムの住民たちは彼を信用した。'),
('JPN', '士师记', 7, 9, 27, '住民たちは畑に出て行って、ぶどうを収穫して踏み、祭りを催して自分たちの神の宮に入って行き、食べたり飲んだりしてアビメレクをののしった。'),
('JPN', '士师记', 7, 9, 28, 'そのとき、エベデの子ガアルは言った。「アビメレクとは何者か。シェケムとは何者か。われわれが彼に仕えなければならないとは。彼はエルバアルの子、ゼブルは彼に仕える者ではないか。シェケムの父ハモルの人々に仕えよ。なぜわれわれはアビメレクに仕えなければならないのか。'),
('JPN', '士师记', 7, 9, 29, 'だれか、この兵を私の手に与えてくれないものか。そうすれば、私はアビメレクを追い出すのだが。」彼はアビメレクに「おまえの軍勢を増やして、出て来い」と言った。'),
('JPN', '士师记', 7, 9, 30, 'この町の長ゼブルは、エベデの子ガアルの言ったことを聞いて怒りを燃やし、'),
('JPN', '士师记', 7, 9, 31, 'ひそかにアビメレクのところに使者を遣わして言った。「今、エベデの子ガアルとその身内の者たちがシェケムに来ています。なんと、彼らは町をあなたに背かせようとしています。'),
('JPN', '士师记', 7, 9, 32, '今、あなたとあなたとともにいる兵が、夜のうちに立って、野で待ち伏せし、'),
('JPN', '士师记', 7, 9, 33, '朝早く、太陽が昇るころ、町に襲いかかるようにしてください。すると、ガアルと、彼とともにいる兵があなたに向かって出て来るでしょう。あなたは手当たり次第、彼らを攻撃することができます。」'),
('JPN', '士师记', 7, 9, 34, 'そこで、アビメレクと、彼とともにいた兵はみな、夜のうちに立って、四隊に分かれてシェケムに向かって待ち伏せた。'),
('JPN', '士师记', 7, 9, 35, 'エベデの子ガアルが出て来て、町の門の入り口に立ったとき、アビメレクと、彼とともにいた兵は、待ち伏せしていたところから立ち上がった。'),
('JPN', '士师记', 7, 9, 36, 'ガアルはその兵を見て、ゼブルに言った。「見よ、兵が山々の頂から下りて来る。」ゼブルは彼に言った。「あなたには、山々の影が人のように見えるのです。」'),
('JPN', '士师记', 7, 9, 37, 'ガアルはまた続けて言った。「見よ、兵がこの地の一番高いところから下りて来る。さらに一隊がメオンニムの樫の木の方から来る。」'),
('JPN', '士师记', 7, 9, 38, 'ゼブルは彼に言った。「『アビメレクとは何者か。われわれが彼に仕えなければならないとは』と言ったあなたの口は、いったいどこにあるのですか。あなたが見くびっていたのは、この兵ではありませんか。さあ今、出て行って、彼と戦いなさい。」'),
('JPN', '士师记', 7, 9, 39, 'そこで、ガアルはシェケムの住民たちの先頭に立って出て行き、アビメレクと戦った。'),
('JPN', '士师记', 7, 9, 40, 'アビメレクが彼を追ったので、ガアルは彼の前から逃げた。多くの者が刺し殺されて倒れ、門の入り口にまで及んだ。'),
('JPN', '士师记', 7, 9, 41, 'アビメレクはアルマにとどまったが、ゼブルは、ガアルとその身内の者たちを追い払って、彼らをシェケムにとどまらせなかった。'),
('JPN', '士师记', 7, 9, 42, '翌日、兵が野に出て行くと、そのことがアビメレクに告げられた。'),
('JPN', '士师记', 7, 9, 43, 'そこで、アビメレクは自分の兵を引き連れ、三隊に分けて、野で待ち伏せた。彼が見ていると、見よ、兵が町から出て来た。そこで彼は立ち上がって彼らを討った。'),
('JPN', '士师记', 7, 9, 44, 'アビメレクと、彼とともにいた一隊は町に襲いかかって、その門の入り口に立った。一方、残りの二隊は野にいたすべての者を襲って打ち殺した。'),
('JPN', '士师记', 7, 9, 45, 'アビメレクは、その日一日中、町を攻め、この町を占領して、その中の民を殺した。彼は町を破壊して、そこに塩をまいた。')
on conflict (version, book, chapter, verse) do nothing;
insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('JPN', '士师记', 7, 9, 46, 'シェケムのやぐらの住民たちはみな、これを聞いてエル・ベリテの神殿の地下室に入った。'),
('JPN', '士师记', 7, 9, 47, 'シェケムのやぐらの住民たち全員が集まったことがアビメレクに告げられたとき、'),
('JPN', '士师记', 7, 9, 48, 'アビメレクは、自分とともにいた兵全員とツァルモン山に登った。アビメレクは手に斧を取って木の枝を切り、これを持ち上げて自分の肩に担ぎ、ともにいる兵に言った。「あなたがたは私が何をしたかを見ただろう。急いで私と同じようにしなさい。」'),
('JPN', '士师记', 7, 9, 49, 'そこで兵も、みなそれぞれ枝を切ってアビメレクについて行き、枝を地下室の上に置いて火をつけ、地下室を焼いた。こうしてシェケムのやぐらの者たち、男女約千人がみな死んだ。'),
('JPN', '士师记', 7, 9, 50, 'それからアビメレクはテベツに行き、テベツに向かって陣を敷いて、これを占領した。'),
('JPN', '士师记', 7, 9, 51, 'この町の中に堅固なやぐらがあった。すべての男女、町の住民たち全員はそこへ逃げて立てこもり、やぐらの屋根に上った。'),
('JPN', '士师记', 7, 9, 52, 'アビメレクはやぐらのところまで来て、これを攻め、やぐらの入り口に近づいて、これを火で焼こうとした。'),
('JPN', '士师记', 7, 9, 53, 'そのとき、一人の女がアビメレクの頭にひき臼の上石を投げつけて、彼の頭蓋骨を砕いた。'),
('JPN', '士师记', 7, 9, 54, 'アビメレクは急いで、道具持ちの若者を呼んで言った。「おまえの剣を抜いて、私にとどめを刺せ。女が殺したのだと私について人が言わないように。」若者が彼を刺したので、彼は死んだ。'),
('JPN', '士师记', 7, 9, 55, 'イスラエル人はアビメレクが死んだのを見て、一人ひとり自分のところへ帰って行った。'),
('JPN', '士师记', 7, 9, 56, 'こうして神は、アビメレクが兄弟七十人を殺して自分の父に行った、その悪の報いを彼に返された。'),
('JPN', '士师记', 7, 9, 57, '神はまた、シェケムの人々のすべての悪の報いを彼らの頭上に返された。エルバアルの子ヨタムののろいが彼らに臨んだ。'),
('JPN', '士师记', 7, 10, 1, 'アビメレクの後、イスラエルを救うために、イッサカル人、ドドの子プワの息子トラが立ち上がった。彼はエフライムの山地にあるシャミルに住んでいた。'),
('JPN', '士师记', 7, 10, 2, '彼は二十三年間イスラエルをさばき、死んでシャミルに葬られた。'),
('JPN', '士师记', 7, 10, 3, '彼の後にギルアデ人ヤイルが立ち上がり、二十二年間イスラエルをさばいた。'),
('JPN', '士师记', 7, 10, 4, '彼には三十人の息子がいた。彼らは三十頭のろばに乗り、三十の町を持っていた。それらは今日まで、ハボテ・ヤイルと呼ばれ、ギルアデの地にある。'),
('JPN', '士师记', 7, 10, 5, 'ヤイルは死んでカモンに葬られた。'),
('JPN', '士师记', 7, 10, 6, 'イスラエルの子らは再び、主の目に悪であることを行い、もろもろのバアルやアシュタロテ、アラムの神々、シドンの神々、モアブの神々、アンモン人の神々、ペリシテ人の神々に仕えた。こうして彼らは主を捨て、主に仕えなかった。'),
('JPN', '士师记', 7, 10, 7, '主の怒りはイスラエルに向かって燃え上がり、主は彼らをペリシテ人の手とアンモン人の手に売り渡された。'),
('JPN', '士师记', 7, 10, 8, '彼らはその年、イスラエル人を打ち砕き、十八年の間、ヨルダンの川向こう、ギルアデにあるアモリ人の地にいたすべてのイスラエル人を虐げた。'),
('JPN', '士师记', 7, 10, 9, 'アンモン人がヨルダン川を渡って、ユダ、ベニヤミン、およびエフライムの家と戦ったので、イスラエルは大変な苦境に立たされた。'),
('JPN', '士师记', 7, 10, 10, 'そのとき、イスラエルの子らは主に叫んだ。「私たちはあなたに罪を犯しました。私たちの神を捨ててバアルの神々に仕えたのです。」'),
('JPN', '士师记', 7, 10, 11, '主はイスラエルの子らに言われた。「わたしは、かつてエジプト人、アモリ人、アンモン人、ペリシテ人から、'),
('JPN', '士师记', 7, 10, 12, 'また、シドン人、アマレク人、マオン人があなたがたを虐げてあなたがたがわたしに叫んだとき、あなたがたを彼らの手から救ったではないか。'),
('JPN', '士师记', 7, 10, 13, 'しかし、あなたがたはわたしを捨てて、ほかの神々に仕えた。だから、わたしはこれ以上あなたがたを救わない。'),
('JPN', '士师记', 7, 10, 14, '行け。そして、あなたがたが選んだ神々に叫べ。あなたがたの苦しみの時には、彼らが救ってくれるだろう。」'),
('JPN', '士师记', 7, 10, 15, 'イスラエルの子らは主に言った。「私たちは罪を犯しました。あなたが良いと思われるように何でも私たちにしてください。ただ、どうか今日、私たちを救い出してください。」'),
('JPN', '士师记', 7, 10, 16, '彼らが自分たちのうちから異国の神々を取り去って主に仕えたので、主はイスラエルの苦痛を見るに忍びなくなられた。'),
('JPN', '士师记', 7, 10, 17, 'このころ、アンモン人が呼び集められて、ギルアデに陣を敷いた。一方、イスラエル人も集まって、ミツパに陣を敷いた。'),
('JPN', '士师记', 7, 10, 18, 'ギルアデの民や、その首長たちは互いに言い合った。「アンモン人と戦いを始める者はだれか。その人がギルアデの住民すべてのかしらとなるのだ。」'),
('JPN', '士师记', 7, 11, 1, 'さて、ギルアデ人エフタは勇士であったが、彼は遊女の子であった。エフタの父親はギルアデであった。'),
('JPN', '士师记', 7, 11, 2, 'ギルアデの妻も、男の子たちを産んだ。この妻の子どもたちが成長したとき、彼らはエフタを追い出して、彼に言った。「あなたはほかの女の息子だから、私たちの父の家を継いではならない。」'),
('JPN', '士师记', 7, 11, 3, 'そこで、エフタは兄弟たちのところから逃げて行き、トブの地に住んだ。エフタのもとには、ならず者が集まっていて、彼と一緒に出入りしていた。'),
('JPN', '士师记', 7, 11, 4, 'それからしばらくして、アンモン人がイスラエルに戦争を仕掛けてきた。'),
('JPN', '士师记', 7, 11, 5, 'アンモン人がイスラエルに戦争を仕掛けてきたとき、ギルアデの長老たちはトブの地からエフタを連れ戻そうと出かけて行き、'),
('JPN', '士师记', 7, 11, 6, 'エフタに言った。「来て、私たちの首領になってください。そしてアンモン人と戦いましょう。」'),
('JPN', '士师记', 7, 11, 7, 'エフタはギルアデの長老たちに言った。「あなたがたは私を憎んで、父の家から追い出したではないか。苦しみにあったからといって、今なぜ私のところにやって来るのか。」'),
('JPN', '士师记', 7, 11, 8, 'すると、ギルアデの長老たちはエフタに言った。「だからこそ、今、私たちはあなたのところに戻って来たのです。あなたは私たちと一緒に行き、アンモン人と戦って、私たちギルアデの住民すべてのかしらになってください。」'),
('JPN', '士师记', 7, 11, 9, 'エフタはギルアデの長老たちに言った。「もしあなたがたが私を連れ戻してアンモン人と戦わせ、主が彼らを私に渡してくださったなら、私はあなたがたのかしらとなろう。」'),
('JPN', '士师记', 7, 11, 10, 'ギルアデの長老たちはエフタに言った。「主が私たちの間の証人となられます。私たちは必ずあなたの言われるとおりにします。」'),
('JPN', '士师记', 7, 11, 11, 'エフタがギルアデの長老たちと一緒に行き、民が彼を自分たちのかしらとし、首領としたとき、エフタは自分が言ったことをみな、ミツパで主の前に告げた。'),
('JPN', '士师记', 7, 11, 12, 'エフタはアンモン人の王に使者たちを遣わして言った。「あなたは私とどういう関わりがあるのですか。私のところに攻めて来て、この国と戦おうとするとは。」'),
('JPN', '士师记', 7, 11, 13, 'すると、アンモン人の王はエフタの使者たちに答えた。「イスラエルがエジプトから上って来たとき、アルノン川からヤボク川、それにヨルダン川に至るまでの私の土地を取ったからだ。今、これらの地を穏やかに返しなさい。」'),
('JPN', '士师记', 7, 11, 14, 'エフタは再びアンモン人の王に使者たちを遣わして、'),
('JPN', '士师记', 7, 11, 15, 'こう言った。「エフタはこう言う。イスラエルはモアブの地も、アンモン人の地も取ってはいない。'),
('JPN', '士师记', 7, 11, 16, 'イスラエルはエジプトから上って来たとき、荒野を通って葦の海まで歩き、それからカデシュまで来た。'),
('JPN', '士师记', 7, 11, 17, 'そこでイスラエルはエドムの王に使者たちを遣わして言った。『どうか、あなたの国を通らせてください』と。ところが、エドムの王は聞き入れなかった。同様にモアブの王にも使者たちを遣わしたが、彼も受け入れなかったので、イスラエルはカデシュにとどまった。'),
('JPN', '士师记', 7, 11, 18, 'それから荒野を行き、エドムの地とモアブの地を迂回し、モアブの地の東まで来て、アルノン川の対岸に宿営した。しかし、モアブの領土には入らなかった。アルノンはモアブの国境だったからだ。'),
('JPN', '士师记', 7, 11, 19, 'そこでイスラエルは、ヘシュボンの王で、アモリ人の王シホンに使者たちを遣わして言った。『どうか、あなたの国を通らせて、目的地に行かせてください』と。'),
('JPN', '士师记', 7, 11, 20, 'しかし、シホンはイスラエルを信用せず、その領土を通らせなかったばかりか、兵をみな集めてヤハツに陣を敷き、イスラエルと戦った。'),
('JPN', '士师记', 7, 11, 21, 'イスラエルの神、主が、シホンとその兵全員をイスラエルの手に渡されたので、イスラエルは彼らを打ち破った。そしてイスラエルは、その地方に住んでいたアモリ人の全地を占領した。'),
('JPN', '士师记', 7, 11, 22, 'こうしてイスラエルは、アルノン川からヤボク川まで、および荒野からヨルダン川までのアモリ人の全領土を占領したのだ。'),
('JPN', '士师记', 7, 11, 23, '今すでに、イスラエルの神、主が、ご自分の民イスラエルの前からアモリ人を追い払われたというのに、あなたはその地を取ろうとしている。'),
('JPN', '士师记', 7, 11, 24, 'あなたは、あなたの神ケモシュがあなたに占領させようとする地を占領しないのか。私たちは、私たちの神、主が、私たちの前から追い払ってくださる者の土地をみな占領するのだ。'),
('JPN', '士师记', 7, 11, 25, '今、あなたはモアブの王ツィポルの子バラクよりもまさっているだろうか。彼はイスラエルと争ったり、戦ったりしたことがあったか。'),
('JPN', '士师记', 7, 11, 26, 'イスラエルが、ヘシュボンとそれに属する村々、アロエルとそれに属する村々、アルノン川の川岸のすべての町に三百年間住んでいたのに、なぜあなたがたは、その間にそれを取り戻さなかったのか。'),
('JPN', '士师记', 7, 11, 27, '私はあなたに罪を犯していないのに、あなたは私に戦いを挑んで、私に害を加えようとしている。審判者であられる主が、今日、イスラエル人とアンモン人の間をさばいてくださるように。」'),
('JPN', '士师记', 7, 11, 28, 'しかし、アンモン人の王はエフタが送ったことばを聞き入れなかった。'),
('JPN', '士师记', 7, 11, 29, '主の霊がエフタの上に下ったとき、彼はギルアデとマナセを通り、ギルアデのミツパを経て、そしてギルアデのミツパからアンモン人のところへ進んで行った。'),
('JPN', '士师记', 7, 11, 30, 'エフタは主に誓願を立てて言った。「もしあなたが確かにアンモン人を私の手に与えてくださるなら、'),
('JPN', '士师记', 7, 11, 31, '私がアンモン人のところから無事に帰って来たとき、私の家の戸口から私を迎えに出て来る者を主のものといたします。私はその人を全焼のささげ物として献げます。」'),
('JPN', '士师记', 7, 11, 32, 'こうして、エフタはアンモン人のところに進んで行き、彼らと戦った。主は彼らをエフタの手に渡された。'),
('JPN', '士师记', 7, 11, 33, '彼はアロエルからミニテに至るまでの二十の町、またアベル・ケラミムに至るまでを非常に激しく討ったので、アンモン人はイスラエル人に屈服した。'),
('JPN', '士师记', 7, 11, 34, 'エフタがミツパの自分の家に帰ると、なんと、自分の娘がタンバリンを鳴らし、踊りながら迎えに出て来ているではないか。彼女はひとり子で、エフタには彼女のほかに、息子も娘もなかった。'),
('JPN', '士师记', 7, 11, 35, 'エフタは彼女を見るや、自分の衣を引き裂いて言った。「ああ、私の娘よ、おまえは本当に私を打ちのめしてしまった。おまえは私を苦しめる者となった。私は主に向かって口を開いたのだから、もう取り消すことはできないのだ。」'),
('JPN', '士师记', 7, 11, 36, 'すると、娘は父に言った。「お父様、あなたは主に対して口を開かれたのです。口に出されたとおりのことを私にしてください。主があなたのために、あなたの敵アンモン人に復讐なさったのですから。」'),
('JPN', '士师记', 7, 11, 37, '娘は父に言った。「このように私にさせてください。私に二か月の猶予を下さい。私は山々をさまよい歩き、自分が処女であることを友だちと泣き悲しみたいのです。」'),
('JPN', '士师记', 7, 11, 38, 'エフタは、「行きなさい」と言って、娘を二か月の間、出してやったので、彼女は友だちと一緒に行き、山々の上で自分が処女であることを泣き悲しんだ。'),
('JPN', '士师记', 7, 11, 39, '二か月が終わって、娘は父のところに帰って来たので、父は誓った誓願どおりに彼女に行った。彼女はついに男を知らなかった。イスラエルではしきたりができて、'),
('JPN', '士师记', 7, 11, 40, '年ごとに四日間、イスラエルの娘たちは出て行って、ギルアデ人エフタの娘のために嘆きの歌を歌うのであった。'),
('JPN', '士师记', 7, 12, 1, 'エフライム人が集まってツァフォンへ進んだとき、彼らはエフタに言った。「なぜ、あなたは進んで行ってアンモン人と戦ったとき、一緒に行くように私たちに呼びかけなかったのか。あなたの家をあなたもろとも火で焼き払おう。」'),
('JPN', '士师记', 7, 12, 2, 'エフタは彼らに言った。「かつて、私と私の民がアンモン人と激しく争ったとき、私はあなたがたに助けを求めたが、あなたがたは彼らの手から私を救ってくれなかった。'),
('JPN', '士师记', 7, 12, 3, 'あなたがたが救ってくれないことが分かったので、私はいのちをかけてアンモン人のところへ進んで行った。そのとき、主は彼らを私の手に渡されたのだ。なぜ、あなたがたは今日になって、私のところに上って来て、私と戦おうとするのか。」'),
('JPN', '士师记', 7, 12, 4, 'エフタはギルアデの人々をみな集めてエフライムと戦った。ギルアデの人々はエフライムを打ち破った。これは、エフライムが「あなたがたはエフライムからの逃亡者だ。ギルアデ人はエフライムとマナセのうちにいるべきだ」と言ったからである。'),
('JPN', '士师记', 7, 12, 5, 'ギルアデ人はさらに、エフライムに面するヨルダン川の渡し場を攻め取った。エフライムの逃亡者が「渡らせてくれ」と言うとき、ギルアデの人々はその人に、「あなたはエフライム人か」と尋ね、その人が「そうではない」と答えると、'),
('JPN', '士师记', 7, 12, 6, 'その人に、「『シボレテ』と言え」と言い、その人が「スィボレテ」と言って、正しく発音できないと、その人を捕まえてヨルダン川の渡し場で殺した。こうしてそのとき、四万二千人のエフライム人が倒れた。'),
('JPN', '士师记', 7, 12, 7, 'エフタはイスラエルを六年間さばいた。ギルアデ人エフタは死んで、ギルアデの町に葬られた。'),
('JPN', '士师记', 7, 12, 8, '彼の後に、ベツレヘム出身のイブツァンがイスラエルをさばいた。'),
('JPN', '士师记', 7, 12, 9, '彼には三十人の息子がいた。また、彼は三十人の娘を自分の氏族以外の者に嫁がせ、息子たちのために、よそから三十人の娘たちを妻に迎えた。彼は七年間イスラエルをさばいた。'),
('JPN', '士师记', 7, 12, 10, 'イブツァンは死んで、ベツレヘムに葬られた。'),
('JPN', '士师记', 7, 12, 11, '彼の後に、ゼブルン人エロンがイスラエルをさばいた。彼は十年間イスラエルをさばいた。'),
('JPN', '士师记', 7, 12, 12, 'ゼブルン人エロンは死んで、ゼブルンの地アヤロンに葬られた。'),
('JPN', '士师记', 7, 12, 13, '彼の後に、ピルアトン人ヒレルの子アブドンがイスラエルをさばいた。'),
('JPN', '士师记', 7, 12, 14, '彼には四十人の息子と三十人の孫がいて、七十頭のろばに乗っていた。彼は八年間イスラエルをさばいた。'),
('JPN', '士师记', 7, 12, 15, 'ピルアトン人ヒレルの子アブドンは死んで、アマレク人の山地にあるエフライムの地ピルアトンに葬られた。'),
('JPN', '士师记', 7, 13, 1, 'イスラエルの子らは、主の目に悪であることを重ねて行った。そこで主は四十年間、彼らをペリシテ人の手に渡された。'),
('JPN', '士师记', 7, 13, 2, 'さて、ダンの氏族に属するツォルア出身の一人の人がいて、名をマノアといった。彼の妻は不妊で、子を産んだことがなかった。'),
('JPN', '士师记', 7, 13, 3, '主の使いがその女に現れて、彼女に言った。「見よ。あなたは不妊で、子を産んだことがない。しかし、あなたは身ごもって男の子を産む。'),
('JPN', '士师记', 7, 13, 4, '今後あなたは気をつけよ。ぶどう酒や強い酒を飲んではならない。汚れた物をいっさい食べてはならない。'),
('JPN', '士师记', 7, 13, 5, '見よ。あなたは身ごもって男の子を産む。その子の頭にかみそりを当ててはならない。その子は胎内にいるときから、神に献げられたナジル人だから。彼はイスラエルをペリシテ人の手から救い始める。」'),
('JPN', '士师记', 7, 13, 6, 'その女は夫のところに行き、次のように言った。「神の人が私のところに来られました。その姿は神の使いのようで、たいへん恐ろしいものでした。私はその方がどちらから来られたか伺いませんでした。その方も私に名をお告げになりませんでした。'),
('JPN', '士师记', 7, 13, 7, 'けれども、その方は私に言われました。『見よ。あなたは身ごもって男の子を産む。今後、ぶどう酒や強い酒を飲んではならない。汚れた物をいっさい食べてはならない。その子は胎内にいるときから死ぬ日まで、神に献げられたナジル人だから』と。」'),
('JPN', '士师记', 7, 13, 8, 'そこで、マノアは主に願って言った。「ああ、主よ。どうか、あなたが遣わされたあの神の人を再び私たちのところに来させ、生まれてくる子に何をすればよいか教えてください。」'),
('JPN', '士师记', 7, 13, 9, '神はマノアの声を聞き入れられた。それで神の使いが再びこの女のところに来た。彼女は畑に座っていて、夫マノアは彼女と一緒にはいなかった。'),
('JPN', '士师记', 7, 13, 10, 'この女は急いで走って行き、夫に告げた。「早く来てください。あの日、私のところに来られたあの方が、また私に現れました。」'),
('JPN', '士师记', 7, 13, 11, 'マノアは立ち上がって妻の後について行き、その人のところに行って尋ねた。「この女にお話しになった方はあなたなのですか。」その人は言った。「わたしだ。」'),
('JPN', '士师记', 7, 13, 12, 'マノアは言った。「今にも、あなたのおことばは実現するでしょう。その子のための定めと慣わしはどのようなものでしょうか。」'),
('JPN', '士师记', 7, 13, 13, '主の使いはマノアに言った。「わたしがこの女に言ったすべてのことに気をつけなければならない。'),
('JPN', '士师记', 7, 13, 14, 'ぶどうからできる物はいっさい食べてはならない。ぶどう酒や、強い酒も飲んではならない。汚れた物はいっさい食べてはならない。わたしが彼女に命じたことはみな守らなければならない。」'),
('JPN', '士师记', 7, 13, 15, 'マノアは主の使いに言った。「私たちにあなたをお引き止めできるでしょうか。あなたのために子やぎを料理したいのですが。」'),
('JPN', '士师记', 7, 13, 16, '主の使いはマノアに言った。「たとえ、あなたがわたしを引き止めても、わたしはあなたの食物は食べない。もし全焼のささげ物を献げたいなら、それは主に献げなさい。」マノアはその方が主の使いであることを知らなかったのである。'),
('JPN', '士师记', 7, 13, 17, 'そこで、マノアは主の使いに言った。「お名前は何とおっしゃいますか。あなたのおことばが実現しましたら、私たちはあなたをほめたたえたいのです。」'),
('JPN', '士师记', 7, 13, 18, '主の使いは彼に言った。「なぜ、あなたはそれを聞くのか。わたしの名は不思議という。」'),
('JPN', '士师记', 7, 13, 19, 'そこでマノアは、子やぎと穀物のささげ物を取り、それを岩の上で主に献げた。主のなさる不思議なことを、マノアとその妻は見ていた。'),
('JPN', '士师记', 7, 13, 20, '炎が祭壇から天に向かって上ったとき、主の使いは祭壇の炎の中を上って行った。マノアとその妻はそれを見て、地にひれ伏した。'),
('JPN', '士师记', 7, 13, 21, '主の使いは再びマノアとその妻に現れることはなかった。そのときマノアは、その人が主の使いであったことを知った。'),
('JPN', '士师记', 7, 13, 22, 'マノアは妻に言った。「私たちは必ず死ぬ。神を見たのだから。」'),
('JPN', '士师记', 7, 13, 23, '妻は彼に言った。「もし私たちを殺そうと思われたのなら、主は私たちの手から、全焼のささげ物と穀物のささげ物をお受けにならなかったでしょう。また、これらのことをみな、私たちにお示しにならなかったでしょうし、今しがた、こうしたことを私たちにお告げにならなかったはずです。」'),
('JPN', '士师记', 7, 13, 24, 'この女は男の子を産み、その子をサムソンと名づけた。その子は大きくなり、主は彼を祝福された。'),
('JPN', '士师记', 7, 13, 25, '主の霊は、ツォルアとエシュタオルの間の、マハネ・ダンで彼を揺り動かし始めた。'),
('JPN', '士师记', 7, 14, 1, 'サムソンは、ティムナに下って行ったとき、ペリシテ人の娘で、ティムナにいる一人の女を見た。'),
('JPN', '士师记', 7, 14, 2, '彼は上って行って、父と母に告げた。「私はティムナで一人の女を見ました。ペリシテ人の娘です。今、彼女を私の妻に迎えてください。」'),
('JPN', '士师记', 7, 14, 3, '父と母は言った。「あなたの身内の娘たちの中に、また、私の民全体の中に、女が一人もいないとでも言うのか。無割礼のペリシテ人から妻を迎えるとは。」サムソンは父に言った。「彼女を私の妻に迎えてください。彼女が気に入ったのです。」'),
('JPN', '士师记', 7, 14, 4, '彼の父と母は、それが主によることだとは知らなかった。主は、ペリシテ人と事を起こす機会を求めておられたのである。そのころ、ペリシテ人がイスラエルを支配していた。'),
('JPN', '士师记', 7, 14, 5, 'サムソンは彼の父と母とともにティムナに下り、ティムナのぶどう畑にやって来た。すると見よ、一頭の若い獅子が吼えたけりながら彼に向かって来た。'),
('JPN', '士师记', 7, 14, 6, 'このとき、主の霊が激しく彼の上に下ったので、彼はまるで子やぎを引き裂くように、何も手に持たず獅子を引き裂いた。サムソンは自分がしたことを父にも母にも告げなかった。'),
('JPN', '士师记', 7, 14, 7, 'サムソンは下って行って、その女と話した。サムソンは彼女が気に入った。'),
('JPN', '士师记', 7, 14, 8, 'しばらくたってから、サムソンは彼女を妻にしようと戻って行った。あの獅子の死骸を見ようと、脇道に入って行くと、なんと、獅子のからだに蜜蜂の群れがいて、蜜があった。'),
('JPN', '士师记', 7, 14, 9, '彼はそれを両手にかき集めて、歩きながら食べた。彼は自分の父母のところに行って、それを彼らに与えたので、彼らも食べた。その蜜を獅子のからだからかき集めたことは、彼らには告げなかった。'),
('JPN', '士师记', 7, 14, 10, '彼の父がその女のところに下って来たとき、サムソンはそこで祝宴を催した。若い男たちはそのようにするのが常だった。'),
('JPN', '士师记', 7, 14, 11, '人々はサムソンを見て、客を三十人連れて来た。彼らはサムソンに付き添った。'),
('JPN', '士师记', 7, 14, 12, 'サムソンは彼らに言った。「さあ、あなたがたに一つの謎をかけよう。もし、あなたがたが七日の祝宴の間に、それを見事に私に解き明かし、答えを見つけることができたなら、あなたがたに亜麻布三十着と晴れ着三十着を差し上げよう。'),
('JPN', '士师记', 7, 14, 13, 'もし、それを解き明かすことができなければ、あなたがたが私に、亜麻布の衣服三十着と晴れ着三十着を差し出すことにしよう。」彼らは言った。「謎をかけなさい。われわれは聞こう。」'),
('JPN', '士师记', 7, 14, 14, 'そこで、サムソンは彼らに言った。「食らうものから食べ物が出た。強いものから甘い物が出た。」彼らは三日たっても、その謎を解き明かすことができなかった。'),
('JPN', '士师记', 7, 14, 15, '七日目になって、彼らはサムソンの妻に言った。「おまえの夫を口説いて、あの謎をわれわれに明かしなさい。そうしないと、火でおまえとおまえの父の家を焼き払ってしまうぞ。おまえたちはわれわれからはぎ取ろうとして招待したのか。そうではないだろう。」'),
('JPN', '士师记', 7, 14, 16, 'そこで、サムソンの妻は夫に泣きすがって言った。「あなたは私を嫌ってばかりいて、私を愛してくださいません。あなたは私の同族の人たちに謎をかけて、それを私に明かしてくださいません。」サムソンは彼女に言った。「見なさい。私は父にも母にもそれを解き明かしてはいないのだ。おまえに解き明かさなければならないのか。」'),
('JPN', '士师记', 7, 14, 17, '彼女は祝宴が続いていた七日間、サムソンに泣きすがった。七日目になって、彼女がしきりにせがんだので、サムソンは彼女に明かした。それで、彼女はその謎を自分の同族の人たちに明かした。'),
('JPN', '士师记', 7, 14, 18, '町の人々は、七日目の日が沈む前にサムソンに言った。「蜂蜜よりも甘いものは何か。雄獅子よりも強いものは何か。」すると、サムソンは彼らに言った。「もし、私の雌の子牛で耕さなかったなら、あなたがたは私の謎を解けなかっただろうに。」'),
('JPN', '士师记', 7, 14, 19, 'そのとき、主の霊が激しくサムソンの上に下った。彼はｖｋに下って行って、そこの住民を三十人打ち殺し、彼らからはぎ取って、謎を明かした者たちにその晴れ着をやり、怒りに燃えて父の家に帰った。'),
('JPN', '士师记', 7, 14, 20, 'サムソンの妻は、彼に付き添った客の一人のものとなった。'),
('JPN', '士师记', 7, 15, 1, 'しばらくたって、小麦の刈り入れの時に、サムソンは子やぎを一匹持って自分の妻を訪ね、「私の妻の部屋に入りたい」と言ったが、彼女の父は入らせなかった。'),
('JPN', '士师记', 7, 15, 2, '彼女の父は言った。「私は、あなたがあの娘を嫌ったのだと思って、あなたの客の一人に与えた。妹のほうがきれいではないか。あれの代わりに妹をあなたのものにしてくれ。」'),
('JPN', '士师记', 7, 15, 3, 'サムソンは彼らに言った。「今度、私がペリシテ人に害を加えても、私は潔白だ。」'),
('JPN', '士师记', 7, 15, 4, 'それからサムソンは出て行って、ジャッカルを三百匹捕らえた。そして、たいまつを取り、尾と尾をつなぎ合わせて、二本の尾の間にそれぞれ一本のたいまつをくくり付けた。'),
('JPN', '士师记', 7, 15, 5, '彼はそのたいまつに火をつけ、それらのジャッカルをペリシテ人の麦畑の中に放し、束ねて積んである麦から、立ち穂、オリーブ畑に至るまで燃やした。'),
('JPN', '士师记', 7, 15, 6, 'ペリシテ人たちは言った。「だれがこんなことをしたのか。」すると彼らは「あのティムナ人の婿サムソンだ。あの人が彼の妻を取り上げて、客の一人にやったからだ」と言った。ペリシテ人は上って来て、彼女とその父を火で焼いた。'),
('JPN', '士师记', 7, 15, 7, 'サムソンは彼らに言った。「おまえたちがこういうことをするなら、私は必ずおまえたちに復讐する。その後で、私は手を引こう。」'),
('JPN', '士师记', 7, 15, 8, 'サムソンは彼らの足腰を打って、大きな打撃を与えた。それから、彼は下って行って、エタムの岩の裂け目に住んだ。'),
('JPN', '士师记', 7, 15, 9, 'ペリシテ人が上って来て、ユダに向かって陣を敷き、レヒを侵略したとき、'),
('JPN', '士师记', 7, 15, 10, 'ユダの人々は言った。「なぜおまえたちは、私たちを攻めに上って来たのか。」彼らは言った。「われわれはサムソンを縛って、彼がわれわれにしたように、彼にもしてやるために上って来たのだ。」'),
('JPN', '士师记', 7, 15, 11, 'そこで、ユダの人々三千人がエタムの岩の裂け目に下って行って、サムソンに言った。「おまえは、ペリシテ人がわれわれの支配者であることを知らないのか。おまえはどうしてこんなことをしてくれたのか。」サムソンは言った。「彼らが私にしたとおり、私は彼らにしたのだ。」'),
('JPN', '士师记', 7, 15, 12, '彼らはサムソンに言った。「われわれはおまえを縛って、ペリシテ人の手に渡すために下って来たのだ。」サムソンは言った。「あなたがたは私に討ちかからないと誓いなさい。」'),
('JPN', '士师记', 7, 15, 13, '彼らは答えた。「決してしない。ただおまえをしっかり縛って、彼らの手に渡すだけだ。われわれは決しておまえを殺さない。」こうして、彼らは二本の新しい綱で彼を縛り、その岩から彼を引き上げた。'),
('JPN', '士师记', 7, 15, 14, 'サムソンがレヒに来たとき、ペリシテ人は大声をあげて彼に近づいた。すると、主の霊が激しく彼の上に下り、彼の腕に掛かっていた綱は火のついた亜麻糸のようになって、その縄目が手から解け落ちた。'),
('JPN', '士师记', 7, 15, 15, 'サムソンは真新しいろばのあご骨を見つけ、手を伸ばして取り、それで千人を打ち殺した。'),
('JPN', '士师记', 7, 15, 16, 'サムソンは言った。「ろばのあご骨で、山と積み上げた。ろばのあご骨で、千人を打ち殺した。」'),
('JPN', '士师记', 7, 15, 17, 'こう言い終わると、彼はそのあご骨を投げ捨てた。彼はその場所を、ラマテ・レヒと名づけた。'),
('JPN', '士师记', 7, 15, 18, 'そのとき、彼はひどく渇きを覚え、主を呼び求めて言った。「あなたは、しもべの手で、この大きな救いを与えてくださいました。しかし今、私は喉が渇いて死にそうで、無割礼の者どもの手に落ちようとしています。」'),
('JPN', '士师记', 7, 15, 19, 'すると、神はレヒにあるくぼんだ地を裂かれたので、そこから水が出た。サムソンは水を飲んで元気を回復し、生き返った。それゆえ、その名はエン・ハ・コレと呼ばれた。それは今日もレヒにある。'),
('JPN', '士师记', 7, 15, 20, 'こうして、サムソンはペリシテ人の時代に二十年間イスラエルをさばいた。'),
('JPN', '士师记', 7, 16, 1, 'サムソンはガザへ行き、そこで遊女を見つけて、彼女のところに入った。'),
('JPN', '士师记', 7, 16, 2, '「サムソンがここにやって来た」と、ガザの人々に告げる者があったので、彼らはそこを取り囲み、町の門で一晩中、彼を待ち伏せた。彼らは「明け方まで待ち、彼を殺そう」と言って、一晩中鳴りを潜めていた。'),
('JPN', '士师记', 7, 16, 3, 'サムソンは真夜中まで寝ていたが、真夜中に起き上がり、町の門の扉と二本の門柱をつかんで、かんぬきごと引き抜き、それを肩に担いで、ヘブロンに面する山の頂に運んで行った。'),
('JPN', '士师记', 7, 16, 4, 'その後、サムソンは、ソレクの谷にいる女を愛した。彼女の名はデリラといった。'),
('JPN', '士师记', 7, 16, 5, 'ペリシテ人の領主たちが彼女のところに来て、言った。「サムソンを口説いて、彼の強い力がどこにあるのか、またどうしたら私たちが彼に勝ち、縛り上げて苦しめることができるかを調べなさい。そうすれば、私たちは一人ひとり、あなたに銀千百枚をあげよう。」'),
('JPN', '士师记', 7, 16, 6, 'そこで、デリラはサムソンに言った。「どうか私に教えてください。あなたの強い力はどこにあるのですか。どうすればあなたを縛って苦しめることができるのでしょうか。」'),
('JPN', '士师记', 7, 16, 7, 'サムソンは言った。「もし、まだ干していない七本の新しい弓の弦で私を縛るなら、私は弱くなり、並みの人のようになるだろう。」'),
('JPN', '士师记', 7, 16, 8, 'そこで、ペリシテ人の領主たちは、干していない七本の新しい弓の弦を彼女のところに持って来たので、彼女はそれでサムソンを縛り上げた。'),
('JPN', '士师记', 7, 16, 9, '彼女は、待ち伏せる者を奥の部屋に置いておき、「サムソン、ペリシテ人があなたを襲って来ます」と言った。しかし、サムソンはまるで麻の撚り糸が火に触れて切れるように、弓の弦を断ち切った。こうして、彼の力の源は知られなかった。'),
('JPN', '士师记', 7, 16, 10, 'デリラはサムソンに言った。「まあ、あなたは私をだまして噓をつきましたね。今度こそ、どうしたらあなたを縛れるか教えてください。」'),
('JPN', '士师记', 7, 16, 11, 'サムソンは言った。「もし、仕事に使ったことのない新しい綱で、私をしっかり縛るなら、私は弱くなり、並みの人のようになるだろう。」'),
('JPN', '士师记', 7, 16, 12, 'そこで、デリラは新しい綱を取って、それで彼を縛り、「サムソン、ペリシテ人があなたを襲って来ます」と言った。奥の部屋には待ち伏せしている者がいた。しかし、サムソンは腕からその綱を、糸のように断ち切った。'),
('JPN', '士师记', 7, 16, 13, 'デリラは、またサムソンに言った。「今まで、あなたは私をだまして噓をついてきました。どうしたらあなたを縛れるか、私に教えてください。」サムソンは、「もしおまえが機の経糸と一緒に私の髪の毛七房を織り込み、機のおさで締めつけておくならば」と言った。'),
('JPN', '士师记', 7, 16, 14, '彼女は機のおさで締めつけて言った。「サムソン、ペリシテ人があなたを襲って来ます。」すると、サムソンは眠りから覚めて、機のおさと機の経糸を引き抜いた。'),
('JPN', '士师记', 7, 16, 15, '彼女はサムソンに言った。「あなたの心が私にはないのに、どうして『おまえを愛している』と言えるのでしょう。あなたはこれで三回も私をだまして、あなたの強い力がどこにあるのか教えてくださいませんでした。」'),
('JPN', '士师记', 7, 16, 16, 'こうして、毎日彼女が同じことばでしきりにせがみ、責め立てたので、彼は死ぬほど辛かった。'),
('JPN', '士师记', 7, 16, 17, 'ついにサムソンは、自分の心をすべて彼女に明かして言った。「私の頭には、かみそりが当てられたことがない。私は母の胎にいるときから神に献げられたナジル人だからだ。もし私の髪の毛が剃り落とされたら、私の力は私から去り、私は弱くなって普通の人のようになるだろう。」'),
('JPN', '士师记', 7, 16, 18, 'デリラは、サムソンが自分の心をすべて明かしたことが分かったので、こう言って、人を遣わし、ペリシテ人の領主たちを呼び寄せた。「今度こそ上って来てください。サムソンは心をすべて私に明かしました。」ペリシテ人の領主たちは、彼女のところに上って来たとき、その手に銀を持って来た。'),
('JPN', '士师记', 7, 16, 19, '彼女は膝の上でサムソンを眠らせ、人を呼んで彼の髪の毛七房を剃り落とさせた。彼女は彼を苦しめ始め、彼の力は彼を離れた。'),
('JPN', '士师记', 7, 16, 20, '彼女が「サムソン、ペリシテ人があなたを襲って来ます」と言ったとき、彼は眠りから覚めて、「今度も前のように出て行って、からだをひとゆすりしてやろう」と言った。彼は、主が自分から離れられたことを知らなかった。'),
('JPN', '士师记', 7, 16, 21, 'ペリシテ人は彼を捕らえ、その両目をえぐり出した。そして彼をガザに引き立てて行って、青銅の足かせを掛けてつないだ。こうしてサムソンは牢の中で臼をひいていた。'),
('JPN', '士师记', 7, 16, 22, 'しかし、サムソンの髪の毛は、剃り落とされてからまた伸び始めた。'),
('JPN', '士师记', 7, 16, 23, 'さて、ペリシテ人の領主たちは、自分たちの神ダゴンに盛大ないけにえを献げて楽しもうと集まり、そして言った。「われわれの神は、敵サムソンをわれわれの手に渡してくださった。」'),
('JPN', '士师记', 7, 16, 24, '民はサムソンを見たとき、自分たちの神をほめたたえて言った。「われわれの神は、われわれの敵を、われわれの手に渡してくださった。この国を荒らして、われわれ大勢を殺した者を。」'),
('JPN', '士师记', 7, 16, 25, '彼らは上機嫌になったとき、「サムソンを呼んで来い。見せ物にしよう」と言って、サムソンを牢から呼び出した。彼は彼らの前で笑いものになった。彼らがサムソンを柱の間に立たせたとき、'),
('JPN', '士师记', 7, 16, 26, 'サムソンは自分の手を固く握っている若者に言った。「私の手を放して、この神殿を支えている柱にさわらせ、それに寄りかからせてくれ。」'),
('JPN', '士师记', 7, 16, 27, '神殿は男や女でいっぱいであった。ペリシテ人の領主たちもみなそこにいた。屋上にも約三千人の男女がいて、見せ物にされたサムソンを見ていた。'),
('JPN', '士师记', 7, 16, 28, 'サムソンは主を呼び求めて言った。「神、主よ、どうか私を心に留めてください。ああ神よ、どうか、もう一度だけ私を強めてください。私の二つの目のために、一度にペリシテ人に復讐したいのです。」'),
('JPN', '士师记', 7, 16, 29, 'サムソンは、神殿を支えている二本の中柱を探り当て、一本に右手を、もう一本に左手を当てて、それで自らを支えた。'),
('JPN', '士师记', 7, 16, 30, 'サムソンは、「ペリシテ人と一緒に死のう」と言って、力を込めてそれを押し広げた。すると神殿は、その中にいた領主たちとすべての民の上に落ちた。こうして、サムソンが死ぬときに殺した者は、彼が生きている間に殺した者よりも多かった。'),
('JPN', '士师记', 7, 16, 31, '彼の身内の者や父の家の者たちがみな下って来て、彼を引き取り、ツォルアとエシュタオルの間にある父マノアの墓に運び上げて葬った。サムソンは二十年間イスラエルをさばいた。'),
('JPN', '士师记', 7, 17, 1, 'エフライムの山地の出で、その名をミカという人がいた。'),
('JPN', '士师记', 7, 17, 2, '彼は母に言った。「銀千百枚が盗まれたとき、あなたはのろいの誓いをされ、私の耳にもそのことを言われました。実は、その銀は私が持っています。私がそれを盗んだのです。」すると母は言った。「主が私の息子を祝福されますように。」'),
('JPN', '士师记', 7, 17, 3, '彼が母にその銀千百枚を返したとき、母は言った。「私は自分の手でその銀を聖別して、主に献げていました。自分の子のために、それで彫像と鋳像を造ろうとしていたのです。今は、それをあなたに返します。」'),
('JPN', '士师记', 7, 17, 4, '彼が母にその銀を戻したので、母は銀二百枚を取って銀細工人に与えた。銀細工人はそれで彫像と鋳像を造った。こうして、それはミカの家にあった。'),
('JPN', '士师记', 7, 17, 5, 'このミカという人には神の宮があった。彼はエポデとテラフィムを作り、その息子の一人を任命して、自分の祭司としていた。'),
('JPN', '士师记', 7, 17, 6, 'そのころ、イスラエルには王がなく、それぞれが自分の目に良いと見えることを行っていた。'),
('JPN', '士师记', 7, 17, 7, 'ユダのベツレヘム出身で、ユダの氏族に属する一人の若者がいた。彼はレビ人で、そこに寄留していた。'),
('JPN', '士师记', 7, 17, 8, 'その人はユダの町ベツレヘムを出て、寄留する所を求めて旅を続け、エフライムの山地にあるミカの家まで来たのだった。'),
('JPN', '士师记', 7, 17, 9, 'ミカは彼に言った。「あなたはどこから来たのですか。」彼は答えた。「私はユダのベツレヘムから来たレビ人です。私は寄留する所を求めて、旅をしているのです。」'),
('JPN', '士师记', 7, 17, 10, 'そこでミカは言った。「私と一緒に住んで、私のために父となり、また祭司となってください。あなたに毎年、銀十枚と、衣服一そろいと、食糧を差し上げます。」するとこのレビ人は同意した。'),
('JPN', '士师记', 7, 17, 11, 'このレビ人は心を決めてミカと一緒に住むことにした。この若者はミカの息子の一人のようになった。'),
('JPN', '士师记', 7, 17, 12, 'ミカがこのレビ人を任命したので、この若者は彼の祭司となり、ミカの家にいた。'),
('JPN', '士师记', 7, 17, 13, 'そこで、ミカは言った。「今、私は、主が私を幸せにしてくださることを知った。レビ人が私の祭司になったのだから。」'),
('JPN', '士师记', 7, 18, 1, 'そのころ、イスラエルには王がいなかった。ダン部族は、自分たちが住む相続地を求めていた。イスラエルの諸部族の中にあって、その時まで彼らには相続地が割り当てられていなかったからであった。'),
('JPN', '士师记', 7, 18, 2, 'そこでダン族は、彼らの諸氏族全体の中から五人の者を、ツォルアとエシュタオルから勇士たちを派遣し、土地を偵察して調べることにした。彼らは五人に言った。「行って、あの地を調べなさい。」五人はエフライムの山地にあるミカの家まで行って、そこで一夜を明かした。'),
('JPN', '士师记', 7, 18, 3, 'ミカの家のそばに来たとき、彼らはあのレビ人の若者の声に気づいた。そこで、彼らはそこに立ち寄り、彼に言った。「だれがあなたをここに連れて来たのですか。ここで何をしているのですか。ここに何の用事があるのですか。」'),
('JPN', '士师记', 7, 18, 4, '彼は、ミカがこれこれのことをして雇ってくれたので、ミカの祭司になったのだ、と言った。'),
('JPN', '士师记', 7, 18, 5, '彼らは言った。「どうか神に伺ってください。私たちのしているこの旅が、成功するかどうかを知りたいのです。」'),
('JPN', '士师记', 7, 18, 6, 'その祭司は彼らに言った。「安心して行きなさい。あなたがたのしている旅は、主がお認めになっています。」'),
('JPN', '士师记', 7, 18, 7, '五人の者たちは進んで行ってライシュに着き、そこの住民が安らかに住んでいて、シドン人の慣わしにしたがい、平穏で安心しきっているのを見た。この地には足りないものは何もなく、彼らを抑えつける者もいなかった。彼らはシドン人から遠く離れていて、そのうえ、だれとも交渉がなかった。'),
('JPN', '士师记', 7, 18, 8, '五人の者たちが、ツォルアとエシュタオルの身内の者たちのところに帰って来ると、身内の者たちは彼らに、どうだったか、と尋ねた。'),
('JPN', '士师记', 7, 18, 9, '彼らは言った。「さあ、彼らに向かって攻め上ろう。私たちはその土地を見たが、実にすばらしい。あなたがたはためらっているが、ぐずぐずせずに進んで行って、あの地を占領しよう。'),
('JPN', '士师记', 7, 18, 10, 'あなたがたが行くときは、安心しきった民のところに行けるのだ。しかもその地は広々としている。神はそれをあなたがたの手に渡してくださった。その場所には、地にあるもので欠けているものは何もない。」'),
('JPN', '士师记', 7, 18, 11, 'そこで、ダンの氏族の者六百人は、武具を着けてツォルアとエシュタオルを出発し、'),
('JPN', '士师记', 7, 18, 12, '上って行って、ユダのキルヤテ・エアリムに宿営した。それゆえ、その場所は今日に至るまで、マハネ・ダンと呼ばれている。それはキルヤテ・エアリムの西部にある。'),
('JPN', '士师记', 7, 18, 13, '彼らはそこからさらにエフライムの山地へと進み、ミカの家に着いた。'),
('JPN', '士师记', 7, 18, 14, 'ライシュの地を偵察に行っていた五人は、身内の者たちに告げた。「これらの建物の中にエポデやテラフィム、彫像や鋳像があるのを知っているか。今、あなたたちは何をすべきか分かっているはずだ。」'),
('JPN', '士师记', 7, 18, 15, 'そこで、彼らはそこに行き、あのレビ人の若者の家、ミカの家に来て、彼の安否を尋ねた。'),
('JPN', '士师记', 7, 18, 16, '武具を着けた六百人のダンの人々は、門の入り口に立っていた。'),
('JPN', '士师记', 7, 18, 17, 'あの地を偵察に行った五人の者たちは上って行き、そこに入り、彫像とエポデとテラフィムと鋳像を取った。祭司は、武具を着けた六百人の者と、門の入り口に立っていた。'),
('JPN', '士师记', 7, 18, 18, 'これら五人がミカの家に入り、彫像とエポデとテラフィムと鋳像を取ったとき、祭司は彼らに言った。「何をしているのですか。」'),
('JPN', '士师记', 7, 18, 19, '彼らは祭司に言った。「黙っていなさい。手を口に当てて、私たちと一緒に来て、私たちのために父となり、また祭司となりなさい。あなたは一人の人の、家の祭司となるのと、イスラエルで部族また氏族の祭司となるのと、どちらがよいのか。」'),
('JPN', '士师记', 7, 18, 20, '祭司の心は躍った。彼はエポデとテラフィムと彫像を取り、この人々の中に入って行った。'),
('JPN', '士师记', 7, 18, 21, '彼らは向きを変え、子ども、家畜、家財を先頭にして進んで行った。'),
('JPN', '士师记', 7, 18, 22, '彼らがミカの家からかなり離れたころ、ミカは近所の家の者たちを集めて、ダン族に追いついた。'),
('JPN', '士师记', 7, 18, 23, '彼らがダン族に呼びかけると、ダンの人々は振り向いて、ミカに言った。「あなたはどうしたのだ。人を集めたりして。」'),
('JPN', '士师记', 7, 18, 24, 'ミカは言った。「あなたがたは、私が造った神々と、それに祭司を奪って行きました。私のところには何が残っているでしょうか。私に向かって『どうしたのだ』と言うとは、いったい何事です。」'),
('JPN', '士师记', 7, 18, 25, 'ダン族はミカに言った。「あなたの声が私たちの中で聞こえないようにしなさい。そうしないと、気の荒い連中があなたがたに討ちかかり、あなたは、自分のいのちも、家族のいのちも失うだろう。」'),
('JPN', '士师记', 7, 18, 26, 'こうして、ダン族は去って行った。ミカは、彼らが自分よりも強いのを見てとり、向きを変えて自分の家に帰った。'),
('JPN', '士师记', 7, 18, 27, '彼らは、ミカが造った物とミカの祭司とを奪い、ライシュに行って、平穏で安心しきっている民を襲い、剣の刃で彼らを討って、火でその町を焼いた。'),
('JPN', '士师记', 7, 18, 28, 'だれも救い出す者はいなかった。その町はシドンから遠く離れていて、そのうえ、だれとも交渉がなかったからである。その町はベテ・レホブの近くの平地にあった。彼らは町を建てて、そこに住んだ。'),
('JPN', '士师记', 7, 18, 29, '彼らは、イスラエルに生まれた自分たちの先祖ダンの名にちなんで、その町にダンという名をつけた。しかし、その町の名は、もともとライシュであった。'),
('JPN', '士师记', 7, 18, 30, 'さて、ダン族は自分たちのために彫像を立てた。モーセの子ゲルショムの子ヨナタンとその子孫が、その地の捕囚のときまで、ダン部族の祭司であった。'),
('JPN', '士师记', 7, 18, 31, 'こうして、神の宮がシロにあった間中、彼らはミカの造った彫像を自分たちのために立てていた。'),
('JPN', '士师记', 7, 19, 1, 'イスラエルに王がいなかった時代のこと、一人のレビ人が、エフライムの山地の奥に寄留していた。この人は、側女として、ユダのベツレヘムから一人の女を迎えた。'),
('JPN', '士师记', 7, 19, 2, 'ところが、その側女は彼を裏切って、彼のところを去り、ユダのベツレヘムにある自分の父の家に行って、そこに四か月間いた。'),
('JPN', '士师记', 7, 19, 3, '夫は、若い者と一くびきのろばを連れて、彼女の後を追って出かけた。彼女の心に訴えて連れ戻すためであった。彼女が夫を自分の父の家に入れたとき、娘の父は彼を見て、喜んで迎えた。'),
('JPN', '士师记', 7, 19, 4, '娘の父であるしゅうとが引き止めたので、彼はしゅうとのもとに三日間とどまった。こうして、彼らは食べて飲んで夜を過ごした。'),
('JPN', '士师记', 7, 19, 5, '四日目になって、彼が朝早く、立ち上がって出発しようとすると、娘の父は婿に言った。「パンを一切れ食べて元気をつけ、その後で出発しなさい。」'),
('JPN', '士师记', 7, 19, 6, 'そこで、二人は座って、ともに食べて飲んだ。娘の父はその人に言った。「ぜひ、もう一晩泊まることにして、楽しみなさい。」'),
('JPN', '士师记', 7, 19, 7, 'その人が立ち上がって出発しようとすると、しゅうとが彼にしきりに勧めたので、彼はまたそこに泊まって一夜を明かした。'),
('JPN', '士师记', 7, 19, 8, '五日目の朝早く、彼が出発しようとすると、娘の父は言った。「ぜひ、元気をつけて、日が傾くまでゆっくりしていきなさい。」そこで、二人は食事をした。'),
('JPN', '士师记', 7, 19, 9, 'その人が、自分の側女と若い者を連れて出発しようとすると、娘の父であるしゅうとは彼に言った。「ご覧なさい。もう日が暮れかかっています。どうか、もう一晩お泊まりなさい。もう日も傾いています。ここに泊まって楽しみ、明日の朝早く旅立って、あなたの天幕に帰ればよいでしょう。」'),
('JPN', '士师记', 7, 19, 10, 'その人は泊まりたくなかったので、立ち上がって出発し、エブスすなわちエルサレムの向かい側までやって来た。鞍をつけた一くびきのろばと、側女が一緒であった。'),
('JPN', '士师记', 7, 19, 11, '彼らがエブスの近くに来たとき、日はすっかり傾いていた。そこで、若い者は主人に言った。「道を外れてあのエブス人の町に向かい、そこで一夜を明かすことにしたらいかがでしょう。」'),
('JPN', '士师记', 7, 19, 12, '彼の主人は言った。「私たちは、イスラエル人ではない異国人の町には立ち寄らない。さあ、ギブアまで進もう。」'),
('JPN', '士师记', 7, 19, 13, '彼はまた若い者に言った。「さあ、ギブアかラマのどちらかの地に着いて、そこで一夜を明かそう。」'),
('JPN', '士师记', 7, 19, 14, '彼らは進んで行ったが、ベニヤミンに属するギブアの近くまで来たとき、日が沈んだ。'),
('JPN', '士师记', 7, 19, 15, '彼らはギブアに行って泊まろうとして、そこに立ち寄り、町に入って広場に座った。彼らを迎えて家に泊めてくれる者は、だれもいなかった。'),
('JPN', '士师记', 7, 19, 16, 'そこへ、夕暮れになって畑仕事から帰る一人の老人がやって来た。この人はエフライムの山地の人で、ギブアに寄留していた。この土地の人々はベニヤミン族であった。'),
('JPN', '士师记', 7, 19, 17, '目を上げて、町の広場にいる旅人を見たとき、この老人は「どちらへ行かれますか。どこから来られたのですか」と尋ねた。'),
('JPN', '士师记', 7, 19, 18, 'その人は彼に言った。「私たちはユダのベツレヘムから、エフライムの山地の奥まで旅を続けているのです。私はその奥地の者で、ユダのベツレヘムまで行って来ました。今、主の家へ帰る途中ですが、だれも私を家に迎えてくれる人がいません。'),
('JPN', '士师记', 7, 19, 19, 'ろばのためには、藁も飼葉もあり、また、私とこの女、しもべどもと一緒にいる若い者のためには、パンも酒もあります。足りない物は何もありません。」'),
('JPN', '士师记', 7, 19, 20, '老人は言った。「安心なさい。足りない物はすべて私に任せなさい。ただ、広場で夜を過ごしてはいけません。」'),
('JPN', '士师记', 7, 19, 21, 'こうして老人は彼を自分の家に連れて行き、ろばに飼葉をやった。彼らは足を洗って、食べて飲んだ。'),
('JPN', '士师记', 7, 19, 22, '彼らが楽しんでいると、なんと、町の男たちで、よこしまな者たちが、その家を取り囲んで戸をたたき続け、家の主人である老人に言った。「おまえの家に来たあの男を引き出せ。あの男を知りたい。」'),
('JPN', '士师记', 7, 19, 23, 'そこで、家の主人であるその人は、彼らのところに出て行って言った。「それはいけない、兄弟たちよ。どうか悪いことはしないでくれ。あの人が私の家に入った後で、そんな恥ずべきことはしないでくれ。'),
('JPN', '士师记', 7, 19, 24, 'ここに処女の私の娘と、あの人の側女がいる。今、二人を連れ出すから、二人を辱めて、あなたがたの好きなようにしなさい。しかしあの人には、そのような恥ずべきことをしないでくれ。」'),
('JPN', '士师记', 7, 19, 25, 'しかし、男たちは彼に聞こうとしなかった。そこで、その旅人は自分の側女をつかんで、外にいる彼らのところへ出した。彼らは彼女を犯して、夜通し朝まで暴行を加え、夜が明けるころに彼女を放した。'),
('JPN', '士师记', 7, 19, 26, '夜明け前に、その女は自分の主人がいるその人の家の戸口に来て、明るくなるまで倒れていた。'),
('JPN', '士师记', 7, 19, 27, '彼女の主人は、朝起きて家の戸を開け、出発しようとして外に出た。見ると、そこに自分の側女である女が、手を敷居にかけて家の入り口で倒れていた。'),
('JPN', '士师记', 7, 19, 28, '彼は女に「立ちなさい。さあ行こう」と言ったが、何の返事もなかった。そこで、その人は彼女をろばに乗せ、立って自分のところへ向かって行った。'),
('JPN', '士师记', 7, 19, 29, '彼は自分の家に着くと、刀を取り、自分の側女をつかんで、その肢体を十二の部分に切り分け、イスラエルの全土に送った。'),
('JPN', '士师记', 7, 19, 30, 'それを見た者はみな、「イスラエルの子らがエジプトの地から上って来た日から今日まで、このようなことは起こったこともなければ、見たこともない。このことをよく考え、相談し、意見を述べよ」と言った。'),
('JPN', '士师记', 7, 20, 1, 'そこで、イスラエルの子らはみな出て来た。ダンからベエル・シェバ、およびギルアデの地に及ぶその会衆は、一斉にミツパの主のもとに集まった。'),
('JPN', '士师记', 7, 20, 2, '民全体、イスラエルの全部族のかしらたちが、神の民の集会に参加した。剣を使う歩兵も四十万人いた。'),
('JPN', '士师记', 7, 20, 3, 'ベニヤミン族は、イスラエルの子らがミツパに上って来たことを聞いた。イスラエルの子らは、「このような悪いことがどうして起こったのか、話してください」と言った。'),
('JPN', '士师记', 7, 20, 4, '殺された女の夫であるレビ人は答えた。「私は側女と一緒に、ベニヤミンに属するギブアに行き、一夜を明かそうとしました。'),
('JPN', '士师记', 7, 20, 5, 'すると、ギブアの者たちが私を襲い、夜中に私のいる家を取り囲み、私を殺そうと図りましたが、彼らは私の側女に暴行を加えました。それで彼女は死にました。'),
('JPN', '士师记', 7, 20, 6, 'そこで私は側女をつかみ、彼女を切り分け、それをイスラエルの全相続地に送りました。これは、彼らがイスラエルの中で淫らな恥辱となることを行ったからです。'),
('JPN', '士师记', 7, 20, 7, 'さあ、あなたがたすべてのイスラエルの子らよ。今ここで、意見を述べて、相談してください。」'),
('JPN', '士师记', 7, 20, 8, 'そこで、民はみな一斉に立ち上がって言った。「私たちは、だれも自分の天幕に帰らない。だれも自分の家に戻らない。'),
('JPN', '士师记', 7, 20, 9, '今、私たちがギブアに対してしようとすることはこうだ。くじを引いて、向かって行こう。'),
('JPN', '士师记', 7, 20, 10, '私たちは、イスラエルの全部族について、百人につき十人、千人につき百人、一万人につき千人を選んで、兵たちのための食糧を持たせよう。そしてベニヤミンのギブアに行かせ、ベニヤミンがイスラエルで犯したこのすべての恥ずべき行いに対して、報復させよう。」'),
('JPN', '士师记', 7, 20, 11, 'こうして、イスラエルの人々はみな団結し、一斉にその町に集まった。'),
('JPN', '士师记', 7, 20, 12, 'イスラエルの諸部族は、ベニヤミン部族全体に人を遣わして言った。「おまえたちのうちに起こったあの悪事は何事か。'),
('JPN', '士师记', 7, 20, 13, '今、ギブアにいるあのよこしまな者たちを渡せ。彼らを殺して、イスラエルから悪を除き去ろう。」しかしベニヤミン族は、自分たちの同胞イスラエルの子らの言うことを聞こうとしなかった。'),
('JPN', '士师记', 7, 20, 14, 'それどころか、ベニヤミン族はイスラエルの子らと戦おうと、町々から出て来てギブアに集結した。'),
('JPN', '士师记', 7, 20, 15, 'その日、ベニヤミン族は、町々から剣を使う者二万六千人を召集した。そのほかに、ギブアの住民から七百人の精鋭を召集した。'),
('JPN', '士师记', 7, 20, 16, '兵全体のうちで、この七百人の精鋭が左利きであった。彼らはみな、一本の毛を狙って石を投げても、的を外すことがなかった。'),
('JPN', '士师记', 7, 20, 17, 'イスラエルの人々は、ベニヤミンを除き、剣を使う者四十万人を召集した。彼らはみな戦士であった。'),
('JPN', '士师记', 7, 20, 18, 'イスラエルの子らは立ち上がって、ベテルに上り、神に伺った。「私たちのうち、だれが最初に上って行って、ベニヤミン族と戦うべきでしょうか。」主は言われた。「ユダが最初だ。」'),
('JPN', '士师记', 7, 20, 19, '朝になると、イスラエルの子らは立ち上がり、ギブアに対して陣を敷いた。'),
('JPN', '士师记', 7, 20, 20, 'イスラエルの人々はベニヤミンとの戦いに出て行き、彼らと戦うためにギブアに対して陣備えをした。'),
('JPN', '士师记', 7, 20, 21, 'ベニヤミン族はギブアから出て来て、その日、イスラエルのうち二万二千人を滅ぼした。'),
('JPN', '士师记', 7, 20, 22, 'しかし、イスラエルの人々の軍勢は奮い立って、最初の日に陣を敷いた場所で、再び戦いの備えをした。'),
('JPN', '士师记', 7, 20, 23, 'イスラエルの子らは上って行って、主の前で夕方まで泣き、主に伺った。「再び、同胞ベニヤミン族に近づいて戦うべきでしょうか。」主は言われた。「攻め上れ。」'),
('JPN', '士师记', 7, 20, 24, 'そこで、イスラエルの子らは次の日、ベニヤミン族に向かって行ったが、'),
('JPN', '士师记', 7, 20, 25, 'ベニヤミンも次の日、ギブアから出て来て彼らを迎え撃ち、再びイスラエルの子らのうち一万八千人をその場で殺した。これらの者はみな、剣を使う者であった。'),
('JPN', '士师记', 7, 20, 26, 'イスラエルの子らはみな、こぞってベテルに上って行って泣き、そこで主の前に座り、その日は夕方まで断食をし、全焼のささげ物と交わりのいけにえを主の前に献げた。'),
('JPN', '士师记', 7, 20, 27, 'イスラエルの子らは主に伺った──当時、神の契約の箱はそこにあり、'),
('JPN', '士师记', 7, 20, 28, 'また当時、アロンの子エルアザルの子ピネハスが、御前に仕えていた──イスラエルの子らは言った。「私はまた出て行って、私の同胞ベニヤミン族と戦うべきでしょうか。それとも、やめるべきでしょうか。」主は言われた。「攻め上れ。明日、わたしは彼らをあなたがたの手に渡す。」'),
('JPN', '士师记', 7, 20, 29, 'そこで、イスラエルはギブアの周りに伏兵を置いた。'),
('JPN', '士师记', 7, 20, 30, '三日目にイスラエルの子らは、ベニヤミン族のところに攻め上り、先のようにギブアに対して陣備えをした。'),
('JPN', '士师记', 7, 20, 31, 'ベニヤミン族は、この兵たちを迎え撃つために出て、町からおびき出された。彼らは、一方はベテルに、もう一方はギブアに至る大路で、この前のようにこの兵たちを討ち始め、イスラエルのうちの約三十人が野で剣に倒れた。'),
('JPN', '士师记', 7, 20, 32, 'ベニヤミン族は「彼らは最初の時と同じように、われわれの前に打ち負かされる」と考えた。しかし、イスラエルの子らは「さあ、逃げよう。そして彼らを町から大路におびき出そう」と言った。'),
('JPN', '士师记', 7, 20, 33, 'イスラエルの人々はみな、持ち場から立ち上がって、バアル・タマルで陣備えをした。一方、イスラエルの伏兵たちは、自分たちの持ち場、マアレ・ゲバから躍り出た。'),
('JPN', '士师记', 7, 20, 34, 'こうして、全イスラエルの精鋭一万人がギブアに向かって進んだ。戦いは激しかった。ベニヤミン族は、わざわいが自分たちに迫っているのに気づかなかった。'),
('JPN', '士师记', 7, 20, 35, '主がイスラエルの前でベニヤミンを打たれたので、イスラエルの子らは、その日、ベニヤミンの二万五千百人を殺した。これらの者はみな、剣を使う者であった。'),
('JPN', '士师记', 7, 20, 36, 'ベニヤミン族は、自分たちが打ち負かされたのを見た。イスラエルの人々はベニヤミンに陣地を明け渡した。それは、ギブアに向けて備えていた伏兵を信頼したからであった。'),
('JPN', '士师记', 7, 20, 37, '伏兵は急いでギブアを襲った。伏兵はその勢いに乗って、町中を剣の刃で討った。'),
('JPN', '士师记', 7, 20, 38, 'イスラエルの人々と伏兵の間には合図が決められていて、町からのろしが上がったら、'),
('JPN', '士师记', 7, 20, 39, 'イスラエルの人々が引き返して戦うことになっていた。ベニヤミンが攻撃を始めて、剣に倒れる者が約三十人、イスラエルの人々の中に出たとき、彼らは「きっと前の戦いの時と同じように、彼らはわれわれに打ち負かされるに違いない」と考えた。'),
('JPN', '士师记', 7, 20, 40, 'のろしが煙の柱となって町から上り始めた。ベニヤミンがうしろを振り向くと、見よ、町全体が煙となって天に上っていた。'),
('JPN', '士师记', 7, 20, 41, 'そこへイスラエルの人々が引き返して来たので、ベニヤミンの人々はわざわいが自分たちに迫っているのを見て、うろたえた。'),
('JPN', '士师记', 7, 20, 42, '彼らはイスラエルの人々の前から逃れて荒野の方へ向かったが、戦いは彼らに追い迫り、町々から出て来た者も合流して彼らを殺した。'),
('JPN', '士师记', 7, 20, 43, 'イスラエルの人々はベニヤミンを包囲して追いつめ、メヌハから、東の方の、ギブアの向こう側まで踏みにじった。'),
('JPN', '士师记', 7, 20, 44, 'こうして、ベニヤミンの一万八千人が倒れた。これらはみな、力ある者たちであった。'),
('JPN', '士师记', 7, 20, 45, 'またほかの者は荒野の方に向かってリンモンの岩まで逃げたが、イスラエルの人々は、大路でそのうちの五千人を討ち取り、なお残りをギデオムまで追いかけて、二千人を打ち倒した。'),
('JPN', '士师记', 7, 20, 46, 'その日、ベニヤミンの中で倒れた者は剣を使う者たち合わせて二万五千人で、彼らはみな、力ある者たちであった。'),
('JPN', '士师记', 7, 20, 47, 'しかし、六百人の者は荒野の方に向かってリンモンの岩に逃げ、四か月の間、リンモンの岩にとどまった。'),
('JPN', '士师记', 7, 20, 48, 'イスラエルの人々は、ベニヤミン族のところへ引き返し、無傷のままだった町も家畜も、見つかったものをすべて剣の刃で討ち、また見つかったすべての町に火を放った。'),
('JPN', '士师记', 7, 21, 1, 'イスラエルの人々はミツパで、「私たちはだれも、娘をベニヤミンに妻として与えない」と誓っていた。'),
('JPN', '士师记', 7, 21, 2, '民はベテルに来て、そこで夕方まで神の前に座り、声をあげて激しく泣いた。'),
('JPN', '士师记', 7, 21, 3, '彼らは言った。「イスラエルの神、主よ。なぜ、イスラエルにこのようなことが起こって、今日イスラエルから一つの部族が欠けるようになったのですか。」'),
('JPN', '士师记', 7, 21, 4, '翌日になって、民は朝早く、そこに一つの祭壇を築いて、全焼のささげ物と交わりのいけにえを献げた。'),
('JPN', '士师记', 7, 21, 5, 'イスラエルの子らは、「イスラエルの全部族のうち、だれが、集団の一員として主のもとに上って来なかったのか」と言った。これは彼らが、ミツパの主のもとに上って来なかった者について、「その者は必ず殺されなければならない」と堅く誓いを立てていたからである。'),
('JPN', '士师记', 7, 21, 6, 'イスラエルの子らは、その同胞ベニヤミンのことで悔やんで言った。「今日、イスラエルから一つの部族が切り捨てられた。'),
('JPN', '士师记', 7, 21, 7, 'あの残った者たちに妻を迎えるには、どうすればよいだろうか。私たちは主によって、自分たちの娘を彼らに妻として与えないと誓ってしまったのだ。」'),
('JPN', '士师记', 7, 21, 8, 'そこで、彼らは「イスラエルの部族のうちで、どの部族がミツパに、主のもとに上って来なかったのか」と言った。見ると、ヤベシュ・ギルアデから陣営に来て、集団に加わっている者は一人もいなかった。'),
('JPN', '士师记', 7, 21, 9, '民が点呼したところ、ヤベシュ・ギルアデの住民が一人もそこにいなかった。'),
('JPN', '士师记', 7, 21, 10, '会衆は、一万二千人の勇士をそこに送って命じた。「行って、ヤベシュ・ギルアデの住民を剣の刃で討て。女も子どもも。'),
('JPN', '士师记', 7, 21, 11, 'これは、あなたがたが行うべきことである。すべての男、そして男と寝たことのある女は、すべて聖絶しなければならない。」'),
('JPN', '士师记', 7, 21, 12, 'こうして、彼らはヤベシュ・ギルアデの住民の中から、男と寝たことがなく、男を知らない若い処女四百人を見つけ出した。彼らは、この女たちをカナンの地にあるシロの陣営に連れて来た。'),
('JPN', '士师记', 7, 21, 13, 'そこで全会衆は、リンモンの岩にいるベニヤミン族に人を遣わして、彼らに和解を呼びかけた。'),
('JPN', '士师记', 7, 21, 14, 'そのとき、ベニヤミンが戻って来たので、ヤベシュ・ギルアデの女のうちから生かしておいた女たちを彼らに与えたが、彼らには足りなかった。'),
('JPN', '士师记', 7, 21, 15, '民はベニヤミンのことで悔やんでいた。主がイスラエルの部族の間を裂かれたからである。'),
('JPN', '士师记', 7, 21, 16, '会衆の長老たちは言った。「あの残った者たちに妻を迎えるには、どうすればよいか。ベニヤミンのうちから女が根絶やしにされたのだ。」'),
('JPN', '士师记', 7, 21, 17, 'また言った。「ベニヤミンの逃れた者たちに、跡継ぎがいなければならない。イスラエルから部族の一つが消し去られてはならない。'),
('JPN', '士师记', 7, 21, 18, 'しかし、自分たちの娘を彼らに妻として与えることはできない。イスラエルの子らは『ベニヤミンに妻を与える者はのろわれる』と誓っているからだ。」'),
('JPN', '士师记', 7, 21, 19, 'そこで、彼らは言った。「そうだ。毎年、シロで主の祭りがある。」──この町はベテルの北にあって、ベテルからシェケムに上る大路の日の昇る方、レボナの南にある──'),
('JPN', '士师记', 7, 21, 20, '彼らはベニヤミン族に命じた。「行って、ぶどう畑で待ち伏せして、'),
('JPN', '士师记', 7, 21, 21, '見ていなさい。もしシロの娘たちが輪になって踊りに出て来たら、あなたがたはぶどう畑から出て、シロの娘たちの中から、それぞれ自分のために妻を捕らえ、ベニヤミンの地に行きなさい。'),
('JPN', '士师记', 7, 21, 22, 'もし、女たちの父か兄弟が私たちに苦情を言いに来たら、私たちはこう言います。『私たちゆえに、彼らをあわれんでやってください。戦争のときに、私たちは彼ら一人ひとりに妻を取らせなかったし、あなたがたも娘を彼らに与えませんでした。もし与えていたなら、今ごろ、あなたがたは責めある者とされていたでしょう』と。」'),
('JPN', '士师记', 7, 21, 23, 'ベニヤミン族はそのようにした。彼らは女たちを自分たちの数にしたがって連れて来た。彼女たちは、彼らが略奪した踊り手たちであった。それから彼らは出かけて、自分たちの相続地に帰り、町々を再建して、そこに住んだ。'),
('JPN', '士师记', 7, 21, 24, 'イスラエルの子らは、そのとき、そこからそれぞれ自分の部族と氏族のもとに戻り、そこからそれぞれ自分の相続地に出て行った。'),
('JPN', '士师记', 7, 21, 25, 'そのころ、イスラエルには王がなく、それぞれが自分の目に良いと見えることを行っていた。'),
('JPN', '路得记', 8, 1, 1, 'さばきつかさが治めていたころ、この地に飢饉が起こった。そのため、ユダのベツレヘム出身のある人が妻と二人の息子を連れてモアブの野へ行き、そこに滞在することにした。'),
('JPN', '路得记', 8, 1, 2, 'その人の名はエリメレク、妻の名はナオミ、二人の息子の名はマフロンとキルヨンで、ユダのベツレヘム出身のエフラテ人であった。彼らはモアブの野へ行き、そこにとどまった。'),
('JPN', '路得记', 8, 1, 3, 'するとナオミの夫エリメレクは死に、彼女と二人の息子が後に残された。'),
('JPN', '路得记', 8, 1, 4, '二人の息子はモアブの女を妻に迎えた。一人の名はオルパで、もう一人の名はルツであった。彼らは約十年の間そこに住んだ。'),
('JPN', '路得记', 8, 1, 5, 'するとマフロンとキルヨンの二人もまた死に、ナオミは二人の息子と夫に先立たれて、後に残された。'),
('JPN', '路得记', 8, 1, 6, 'ナオミは嫁たちと連れ立って、モアブの野から帰ることにした。主がご自分の民を顧みて、彼らにパンを下さった、とモアブの地で聞いたからである。'),
('JPN', '路得记', 8, 1, 7, '彼女は二人の嫁と一緒に、今まで住んでいた場所を出て、ユダの地に戻るため帰途についた。'),
('JPN', '路得记', 8, 1, 8, 'ナオミは二人の嫁に言った。「あなたたちは、それぞれ自分の母の家に帰りなさい。あなたたちが、亡くなった者たちと私にしてくれたように、主があなたたちに恵みを施してくださいますように。'),
('JPN', '路得记', 8, 1, 9, 'また、主が、あなたたちがそれぞれ、新しい夫の家で安らかに暮らせるようにしてくださいますように。」そして二人に口づけしたので、彼女たちは声をあげて泣いた。'),
('JPN', '路得记', 8, 1, 10, '二人はナオミに言った。「私たちは、あなたの民のところへ一緒に戻ります。」'),
('JPN', '路得记', 8, 1, 11, 'ナオミは言った。「帰りなさい、娘たち。なぜ私と一緒に行こうとするのですか。私のお腹にまだ息子たちがいて、あなたたちの夫になるとでもいうのですか。'),
('JPN', '路得记', 8, 1, 12, '帰りなさい、娘たちよ。さあ行きなさい。私は年をとって、もう夫は持てません。たとえ私が自分に望みがあると思い、今晩にでも夫を持って、息子たちを産んだとしても、'),
('JPN', '路得记', 8, 1, 13, 'だからといって、あなたたちは息子たちが大きくなるまで待つというのですか。だからといって、夫を持たないままでいるというのですか。娘たちよ、それはいけません。それは、あなたたちよりも、私にとってとても辛いことです。主の御手が私に下ったのですから。」'),
('JPN', '路得记', 8, 1, 14, '彼女たちはまた声をあげて泣いた。オルパは姑に別れの口づけをしたが、ルツは彼女にすがりついた。'),
('JPN', '路得记', 8, 1, 15, 'ナオミは言った。「ご覧なさい。あなたの弟嫁は、自分の民とその神々のところに帰って行きました。あなたも弟嫁の後について帰りなさい。」'),
('JPN', '路得记', 8, 1, 16, 'ルツは言った。「お母様を捨て、別れて帰るように、仕向けないでください。お母様が行かれるところに私も行き、住まれるところに私も住みます。あなたの民は私の民、あなたの神は私の神です。'),
('JPN', '路得记', 8, 1, 17, 'あなたが死なれるところで私も死に、そこに葬られます。もし、死によってでも、私があなたから離れるようなことがあったら、主が幾重にも私を罰してくださるように。」'),
('JPN', '路得记', 8, 1, 18, 'ナオミは、ルツが自分と一緒に行こうと固く決心しているのを見て、もうそれ以上は言わなかった。'),
('JPN', '路得记', 8, 1, 19, '二人は旅をして、ベツレヘムに着いた。彼女たちがベツレヘムに着くと、町中が二人のことで騒ぎ出し、女たちは「まあ、ナオミではありませんか」と言った。'),
('JPN', '路得记', 8, 1, 20, 'ナオミは彼女たちに言った。「私をナオミと呼ばないで、マラと呼んでください。全能者が私を大きな苦しみにあわせたのですから。'),
('JPN', '路得记', 8, 1, 21, '私は出て行くときは満ち足りていましたが、主は私を素手で帰されました。どうして私をナオミと呼ぶのですか。主が私を卑しくし、全能者が私を辛い目にあわせられたというのに。」'),
('JPN', '路得记', 8, 1, 22, 'こうして、ナオミは帰って来た。モアブの野から戻った嫁、モアブの女ルツと一緒であった。ベツレヘムに着いたのは、大麦の刈り入れが始まったころであった。'),
('JPN', '路得记', 8, 2, 1, 'さて、ナオミには、夫エリメレクの一族に属する一人の有力な親戚がいた。その人の名はボアズであった。'),
('JPN', '路得记', 8, 2, 2, 'モアブの女ルツはナオミに言った。「畑に行かせてください。そして、親切にしてくれる人のうしろで落ち穂を拾い集めさせてください。」ナオミは「娘よ、行っておいで」と言った。'),
('JPN', '路得记', 8, 2, 3, 'ルツは出かけて行って、刈り入れをする人たちの後について畑で落ち穂を拾い集めた。それは、はからずもエリメレクの一族に属するボアズの畑であった。'),
('JPN', '路得记', 8, 2, 4, 'ちょうどそのとき、ボアズがベツレヘムからやって来て、刈る人たちに言った。「主があなたがたとともにおられますように。」彼らは、「主があなたを祝福されますように」と答えた。'),
('JPN', '路得记', 8, 2, 5, 'ボアズは、刈る人たちの世話をしている若い者に言った。「あれはだれの娘か。」'),
('JPN', '路得记', 8, 2, 6, '刈る人たちの世話をしている若い者は答えた。「あれは、ナオミと一緒にモアブの野から戻って来たモアブの娘です。'),
('JPN', '路得记', 8, 2, 7, '彼女は『刈る人たちの後について、束のところで落ち穂を拾い集めさせてください』と言いました。ここに来て、朝から今までほとんど家で休みもせず、ずっと立ち働いています。」'),
('JPN', '路得记', 8, 2, 8, 'ボアズはルツに言った。「娘さん、よく聞きなさい。ほかの畑に落ち穂を拾いに行ってはいけません。ここから移ってもいけません。私のところの若い女たちのそばを離れず、ここにいなさい。'),
('JPN', '路得记', 8, 2, 9, '刈り取っている畑を見つけたら、彼女たちの後について行きなさい。私は若い者たちに、あなたの邪魔をしてはならない、と命じておきました。喉が渇いたら、水がめのところに行って、若い者たちが汲んだ水を飲みなさい。」'),
('JPN', '路得记', 8, 2, 10, '彼女は顔を伏せ、地面にひれ伏して彼に言った。「どうして私に親切にし、気遣ってくださるのですか。私はよそ者ですのに。」'),
('JPN', '路得记', 8, 2, 11, 'ボアズは答えた。「あなたの夫が亡くなってから、あなたが姑にしたこと、それに自分の父母や生まれ故郷を離れて、これまで知らなかった民のところに来たことについて、私は詳しく話を聞いています。'),
('JPN', '路得记', 8, 2, 12, '主があなたのしたことに報いてくださるように。あなたがその翼の下に身を避けようとして来たイスラエルの神、主から、豊かな報いがあるように。」'),
('JPN', '路得记', 8, 2, 13, '彼女は言った。「ご主人様、私はあなたのご好意を得たいと存じます。あなたは私を慰め、このはしための心に語りかけてくださいました。私はあなたのはしための一人にも及びませんのに。」'),
('JPN', '路得记', 8, 2, 14, '食事の時、ボアズはルツに言った。「ここに来て、このパンを食べ、あなたのパン切れを酢に浸しなさい。」彼女が刈る人たちのそばに座ったので、彼は炒り麦を彼女に取ってやった。彼女はそれを食べ、十分食べて、余りを残しておいた。'),
('JPN', '路得记', 8, 2, 15, '彼女が落ち穂を拾い集めようとして立ち上がると、ボアズは若い者たちに命じた。「彼女には束の間でも落ち穂を拾い集めさせなさい。彼女にみじめな思いをさせてはならない。'),
('JPN', '路得记', 8, 2, 16, 'それだけでなく、彼女のために束からわざと穂を抜き落として、拾い集めさせなさい。彼女を叱ってはいけない。」'),
('JPN', '路得记', 8, 2, 17, 'こうして、ルツは夕方まで畑で落ち穂を拾い集めた。集めたものを打つと、大麦一エパほどであった。'),
('JPN', '路得记', 8, 2, 18, '彼女はそれを背負って町に行き、集めたものを姑に見せた。また、先に十分に食べたうえで残しておいたものを取り出して、姑に渡した。'),
('JPN', '路得记', 8, 2, 19, '姑は彼女に言った。「今日、どこで落ち穂を拾い集めたのですか。どこで働いたのですか。あなたに目を留めてくださった方に祝福がありますように。」彼女は姑に、だれのところで働いてきたかを告げた。「今日、私はボアズという名の人のところで働きました。」'),
('JPN', '路得记', 8, 2, 20, 'ナオミは嫁に言った。「生きている者にも、死んだ者にも、御恵みを惜しまない主が、その方を祝福されますように。」ナオミは、また言った。「その方は私たちの近親の者で、しかも、買い戻しの権利のある親類の一人です。」'),
('JPN', '路得记', 8, 2, 21, 'モアブの女ルツは言った。「その方はまた、『私のところの刈り入れが全部終わるまで、うちの若い者たちのそばについていなさい』と言われました。」'),
('JPN', '路得记', 8, 2, 22, 'ナオミは嫁のルツに言った。「娘よ、それは良かった。あの方のところの若い女たちと一緒に畑に出られるのですから。ほかの畑でいじめられなくてすみます。」'),
('JPN', '路得记', 8, 2, 23, 'それで、ルツはボアズのところの若い女たちから離れないで、大麦の刈り入れと小麦の刈り入れが終わるまで落ち穂を拾い集めた。こうして、彼女は姑と暮らした。'),
('JPN', '路得记', 8, 3, 1, '姑のナオミは彼女に言った。「娘よ。あなたが幸せになるために、身の落ち着き所を私が探してあげなければなりません。'),
('JPN', '路得记', 8, 3, 2, 'あなたが一緒にいた若い女たちの主人ボアズは、私たちの親戚ではありませんか。ちょうど今夜、あの方は打ち場で大麦をふるい分けようとしています。'),
('JPN', '路得记', 8, 3, 3, 'あなたはからだを洗って油を塗り、晴れ着をまとって打ち場に下って行きなさい。けれども、あの方が食べたり飲んだりし終わるまでは、気づかれないようにしなさい。'),
('JPN', '路得记', 8, 3, 4, 'あの方が寝るとき、その場所を見届け、後で入って行ってその足もとをまくり、そこで寝なさい。あの方はあなたがすべきことを教えてくれるでしょう。」'),
('JPN', '路得记', 8, 3, 5, 'ルツは姑に言った。「おっしゃることは、みないたします。」'),
('JPN', '路得记', 8, 3, 6, 'こうして、彼女は打ち場に下って行き、姑が命じたことをすべて行った。'),
('JPN', '路得记', 8, 3, 7, 'ボアズは食べたり飲んだりして、気分が良くなり、積み重ねてある麦の傍らに行って寝た。彼女はこっそりと行って、ボアズの足もとをまくり、そこに寝た。'),
('JPN', '路得记', 8, 3, 8, '夜中になって、その人は驚いて起き直った。見ると、一人の女の人が自分の足もとに寝ていた。'),
('JPN', '路得记', 8, 3, 9, '彼は言った。「あなたはだれだ。」彼女は言った。「私はあなたのはしためルツです。あなたの覆いを、あなたのはしための上に広げてください。あなたは買い戻しの権利のある親類です。」'),
('JPN', '路得记', 8, 3, 10, 'ボアズは言った。「娘さん、主があなたを祝福されるように。あなたが示した、今回の誠実さは、先の誠実さにまさっています。あなたは、貧しい者でも富んだ者でも、若い男の後は追いかけませんでした。'),
('JPN', '路得记', 8, 3, 11, '娘さん、もう恐れる必要はありません。あなたが言うことはすべてしてあげましょう。この町の人々はみな、あなたがしっかりした女であることを知っています。'),
('JPN', '路得记', 8, 3, 12, 'ところで、確かに私は買い戻しの権利のある親類ですが、私よりももっと近い、買い戻しの権利のある親類がいます。'),
('JPN', '路得记', 8, 3, 13, '今晩はここで過ごしなさい。朝になって、もしその人があなたに親類の役目を果たすなら、それでよいでしょう。その人に親類の役目を果たしてもらいましょう。もし、その人が親類の役目を果たすことを望まないなら、私があなたを買い戻します。主は生きておられます。さあ、朝までお休みなさい。」'),
('JPN', '路得记', 8, 3, 14, 'ルツは朝まで彼の足もとで寝て、だれかれの見分けがつかないうちに起きた。彼は「打ち場に彼女が来たことが知られてはならない」と思い、'),
('JPN', '路得记', 8, 3, 15, '「あなたが着ている上着を持って、それをしっかりつかんでいなさい」と言った。彼女がそれをしっかりつかむと、彼は大麦六杯を量り、それを彼女に背負わせた。それから、彼は町へ行った。'),
('JPN', '路得记', 8, 3, 16, '彼女が姑のところに行くと、姑は尋ねた。「娘よ、どうでしたか。」ルツは、その人が自分にしてくれたことをすべて姑に告げて、'),
('JPN', '路得记', 8, 3, 17, 'こう言った。「あなたの姑のところに手ぶらで帰ってはならないと言って、あの方はこの大麦六杯を下さいました。」'),
('JPN', '路得记', 8, 3, 18, '姑は言った。「娘よ、このことがどう収まるか分かるまで待っていなさい。あの方は、今日このことを決めてしまわなければ落ち着かないでしょうから。」'),
('JPN', '路得记', 8, 4, 1, '一方、ボアズは門のところへ上って行って、そこに座った。すると、ちょうど、ボアズが言ったあの買い戻しの権利のある親類が通りかかった。ボアズは彼に言った。「どうぞこちらに来て、ここにお座りください。」彼はそこに来て座った。'),
('JPN', '路得记', 8, 4, 2, 'ボアズは町の長老十人を招いて、「ここにお座りください」と言ったので、彼らも座った。'),
('JPN', '路得记', 8, 4, 3, 'ボアズは、その買い戻しの権利のある親類に言った。「モアブの野から帰って来たナオミは、私たちの身内のエリメレクの畑を売ることにしています。'),
('JPN', '路得记', 8, 4, 4, '私はそれをあなたの耳に入れ、ここに座っている人たちと私の民の長老たちの前で、それを買ってくださいと言おうと思ったのです。もし、あなたがそれを買い戻すつもりなら、それを買い戻してください。けれども、もし、それを買い戻さないのなら、私にそう言って知らせてください。あなたを差し置いてそれを買い戻す人はいません。私はあなたの次です。」彼は言った。「私が買い戻しましょう。」'),
('JPN', '路得记', 8, 4, 5, 'ボアズは言った。「あなたがナオミの手からその畑を買い受けるときには、死んだ人の名を相続地に存続させるために、死んだ人の妻であったモアブの女ルツも引き受けなければなりません。」'),
('JPN', '路得记', 8, 4, 6, 'するとその買い戻しの権利のある親類は言った。「私には、その土地を自分のために買い戻すことはできません。自分自身の相続地を損なうことになるといけませんから。私に代わって、あなたが買い戻してください。私は買い戻すことができません。」'),
('JPN', '路得记', 8, 4, 7, '昔イスラエルでは、買い戻しや権利の譲渡をする場合、すべての取り引きを有効にするために、一方が自分の履き物を脱いで、それを相手に渡す習慣があった。これがイスラエルにおける認証の方法であった。'),
('JPN', '路得记', 8, 4, 8, 'それで、この買い戻しの権利のある親類はボアズに、「あなたがお買いなさい」と言って、自分の履き物を脱いだ。'),
('JPN', '路得记', 8, 4, 9, 'ボアズは、長老たちとすべての民に言った。「あなたがたは、今日、私がナオミの手から、エリメレクのものすべて、キルヨンとマフロンのものすべてを買い取ったことの証人です。'),
('JPN', '路得记', 8, 4, 10, 'また、死んだ人の名を相続地に存続させるために、私は、マフロンの妻であったモアブの女ルツも買って、私の妻としました。死んだ人の名を、その身内の者たちの間から、またその町の門から絶えさせないためです。今日、あなたがたはその証人です。」'),
('JPN', '路得记', 8, 4, 11, '門にいたすべての民と長老たちは言った。「私たちは証人です。どうか、主が、あなたの家に嫁ぐ人を、イスラエルの家を建てたラケルとレアの二人のようにされますように。また、あなたがエフラテで力ある働きをし、ベツレヘムで名を打ち立てますように。'),
('JPN', '路得记', 8, 4, 12, 'どうか、主がこの娘を通してあなたに授ける子孫によって、タマルがユダに産んだペレツの家のように、あなたの家がなりますように。」'),
('JPN', '路得记', 8, 4, 13, 'ボアズはルツを迎え、彼女は彼の妻となった。ボアズは彼女のところに入り、主はルツを身ごもらせ、彼女は男の子を産んだ。'),
('JPN', '路得记', 8, 4, 14, '女たちはナオミに言った。「主がほめたたえられますように。主は、今日あなたに、買い戻しの権利のある者が途絶えないようにされました。その子の名がイスラエルで打ち立てられますように。'),
('JPN', '路得记', 8, 4, 15, 'その子はあなたを元気づけ、老後のあなたを養うでしょう。あなたを愛するあなたの嫁、七人の息子にもまさる嫁が、その子を産んだのですから。」'),
('JPN', '路得记', 8, 4, 16, 'ナオミはその子を取り、胸に抱いて、養い育てた。'),
('JPN', '路得记', 8, 4, 17, '近所の女たちは、「ナオミに男の子が生まれた」と言って、その子に名をつけた。彼女たちはその名をオベデと呼んだ。オベデは、ダビデの父であるエッサイの父となった。'),
('JPN', '路得记', 8, 4, 18, 'これはペレツの系図である。ペレツはヘツロンを生み、'),
('JPN', '路得记', 8, 4, 19, 'ヘツロンはラムを生み、ラムはアミナダブを生み、'),
('JPN', '路得记', 8, 4, 20, 'アミナダブはナフションを生み、ナフションはサルマを生み、'),
('JPN', '路得记', 8, 4, 21, 'サルマはボアズを生み、ボアズはオベデを生み、'),
('JPN', '路得记', 8, 4, 22, 'オベデはエッサイを生み、エッサイはダビデを生んだ。'),
('JPN', '撒母耳记上', 9, 1, 1, 'エフライムの山地ラマタイム出身のツフ人の一人で、その名をエルカナという人がいた。この人はエロハムの子で、エロハムはエリフの子、エリフはトフの子、トフはエフライム人ツフの子であった。'),
('JPN', '撒母耳记上', 9, 1, 2, 'エルカナには二人の妻がいた。一人の名はハンナといい、もう一人の名はペニンナといった。ペニンナには子がいたが、ハンナには子がいなかった。'),
('JPN', '撒母耳记上', 9, 1, 3, 'この人は、毎年自分の町から上って行き、シロで万軍の主を礼拝し、いけにえを献げることにしていた。そこでは、エリの二人の息子、ホフニとピネハスが主の祭司をしていた。'),
('JPN', '撒母耳记上', 9, 1, 4, 'そのようなある日、エルカナはいけにえを献げた。彼は、妻のペニンナ、そして彼女のすべての息子、娘たちに、それぞれの受ける分を与えるようにしていたが、'),
('JPN', '撒母耳记上', 9, 1, 5, 'ハンナには特別の受ける分を与えていた。主は彼女の胎を閉じておられたが、彼がハンナを愛していたからである。'),
('JPN', '撒母耳记上', 9, 1, 6, 'また、彼女に敵対するペニンナは、主がハンナの胎を閉じておられたことで、彼女をひどく苛立たせ、その怒りをかき立てた。'),
('JPN', '撒母耳记上', 9, 1, 7, 'そのようなことが毎年行われ、ハンナが主の家に上って行くたびに、ペニンナは彼女の怒りをかき立てるのだった。こういうわけで、ハンナは泣いて、食事をしようともしなかった。'),
('JPN', '撒母耳记上', 9, 1, 8, '夫エルカナは彼女に言った。「ハンナ、なぜ泣いているのか。どうして食べないのか。どうして、あなたの心は苦しんでいるのか。あなたにとって、私は十人の息子以上の者ではないか。」'),
('JPN', '撒母耳记上', 9, 1, 9, 'シロでの飲食が終わった後、ハンナは立ち上がった。ちょうどそのとき、祭司エリは主の神殿の門柱のそばで、椅子に座っていた。'),
('JPN', '撒母耳记上', 9, 1, 10, 'ハンナの心は痛んでいた。彼女は激しく泣いて、主に祈った。'),
('JPN', '撒母耳记上', 9, 1, 11, 'そして誓願を立てて言った。「万軍の主よ。もし、あなたがはしための苦しみをご覧になり、私を心に留め、このはしためを忘れず、男の子を下さるなら、私はその子を一生の間、主にお渡しします。そしてその子の頭にかみそりを当てません。」'),
('JPN', '撒母耳记上', 9, 1, 12, 'ハンナが主の前で長く祈っている間、エリは彼女の口もとをじっと見ていた。'),
('JPN', '撒母耳记上', 9, 1, 13, 'ハンナは心で祈っていたので、唇だけが動いて、声は聞こえなかった。それでエリは彼女が酔っているのだと思った。'),
('JPN', '撒母耳记上', 9, 1, 14, 'エリは彼女に言った。「いつまで酔っているのか。酔いをさましなさい。」'),
('JPN', '撒母耳记上', 9, 1, 15, 'ハンナは答えた。「いいえ、祭司様。私は心に悩みのある女です。ぶどう酒も、お酒も飲んではおりません。私は主の前に心を注ぎ出していたのです。'),
('JPN', '撒母耳记上', 9, 1, 16, 'このはしためを、よこしまな女と思わないでください。私は募る憂いと苛立ちのために、今まで祈っていたのです。」'),
('JPN', '撒母耳记上', 9, 1, 17, 'エリは答えた。「安心して行きなさい。イスラエルの神が、あなたの願ったその願いをかなえてくださるように。」'),
('JPN', '撒母耳记上', 9, 1, 18, '彼女は、「はしためが、あなたのご好意を受けられますように」と言った。それから彼女は帰って食事をした。その顔は、もはや以前のようではなかった。'),
('JPN', '撒母耳记上', 9, 1, 19, '彼らは翌朝早く起きて、主の前で礼拝をし、ラマにある自分たちの家に帰って来た。エルカナは妻ハンナを知った。主は彼女を心に留められた。'),
('JPN', '撒母耳记上', 9, 1, 20, '年が改まって、ハンナは身ごもって男の子を産んだ。そして「私がこの子を主にお願いしたのだから」と言って、その名をサムエルと呼んだ。'),
('JPN', '撒母耳记上', 9, 1, 21, '夫のエルカナは、年ごとのいけにえを主に献げ、自分の誓願を果たすために、家族そろって上って行こうとした。'),
('JPN', '撒母耳记上', 9, 1, 22, 'しかしハンナは、夫に「この子が乳離れして、私がこの子を連れて行き、この子が主の御顔を拝して、いつまでもそこにとどまるようになるまでは」と言って、上って行かなかった。'),
('JPN', '撒母耳记上', 9, 1, 23, '夫のエルカナは彼女に言った。「あなたが良いと思うようにしなさい。この子が乳離れするまでとどまりなさい。ただ、主がそのおことばを実現してくださるように。」こうしてハンナはとどまって、その子が乳離れするまで乳を飲ませた。'),
('JPN', '撒母耳记上', 9, 1, 24, 'その子が乳離れしたとき、彼女は子牛三頭、小麦粉一エパ、ぶどう酒の皮袋一つを携えてその子を伴って上り、シロにある主の家に連れて行った。その子はまだ幼かった。'),
('JPN', '撒母耳记上', 9, 1, 25, '彼らは子牛を屠り、その子をエリのところに連れて行った。'),
('JPN', '撒母耳记上', 9, 1, 26, 'ハンナは言った。「ああ、祭司様。あなたは生きておられます。祭司様。私はかつて、ここであなたのそばに立って、主に祈った女です。'),
('JPN', '撒母耳记上', 9, 1, 27, 'この子のことを、私は祈ったのです。主は私がお願いしたとおり、私の願いをかなえてくださいました。'),
('JPN', '撒母耳记上', 9, 1, 28, 'それで私もまた、この子を主におゆだねいたします。この子は一生涯、主にゆだねられたものです。」こうして彼らはそこで主を礼拝した。'),
('JPN', '撒母耳记上', 9, 2, 1, 'ハンナは祈った。「私の心は主にあって大いに喜び、私の角は主によって高く上がります。私の口は敵に向かって大きく開きます。私があなたの救いを喜ぶからです。'),
('JPN', '撒母耳记上', 9, 2, 2, '主のように聖なる方はいません。まことに、あなたのほかにはだれもいないのです。私たちの神のような岩はありません。'),
('JPN', '撒母耳记上', 9, 2, 3, 'おごり高ぶって、多くのことを語ってはなりません。横柄なことばを口にしてはなりません。まことに主は、すべてを知る神。そのみわざは測り知れません。'),
('JPN', '撒母耳记上', 9, 2, 4, '勇士が弓を砕かれ、弱い者が力を帯びます。'),
('JPN', '撒母耳记上', 9, 2, 5, '満ち足りていた者がパンのために雇われ、飢えていた者に、飢えることがなくなります。不妊の女が七人の子を産み、子だくさんの女が、打ちしおれてしまいます。'),
('JPN', '撒母耳记上', 9, 2, 6, '主は殺し、また生かします。よみに下し、また引き上げます。'),
('JPN', '撒母耳记上', 9, 2, 7, '主は貧しくし、また富ませ、低くし、また高くします。'),
('JPN', '撒母耳记上', 9, 2, 8, '主は、弱い者をちりから起こし、貧しい者をあくたから引き上げ、高貴な者とともに座らせ、彼らに栄光の座を継がせます。まことに、地の柱は主のもの。その上に主は世界を据えられました。'),
('JPN', '撒母耳记上', 9, 2, 9, '主は敬虔な者たちの足を守られます。しかし、悪者どもは、闇の中に滅び失せます。人は、自分の能力によっては勝てないからです。'),
('JPN', '撒母耳记上', 9, 2, 10, '主は、はむかう者を打ち砕き、その者に天から雷鳴を響かせられます。主は地の果ての果てまでさばかれます。主が、ご自分の王に力を与え、主に油注がれた者の角を高く上げてくださいますように。」'),
('JPN', '撒母耳记上', 9, 2, 11, 'エルカナはラマにある自分の家に帰った。幼子は、祭司エリのもとで主に仕えていた。'),
('JPN', '撒母耳记上', 9, 2, 12, 'さて、エリの息子たちはよこしまな者たちで、主を知らなかった。'),
('JPN', '撒母耳记上', 9, 2, 13, '民に関わる祭司の定めについてもそうであった。だれかが、いけにえを献げていると、まだ肉を煮ている間に、祭司の子弟が三又の肉刺しを手にしてやって来て、'),
('JPN', '撒母耳记上', 9, 2, 14, 'これを大鍋や、釜、大釜、鍋に突き入れ、肉刺しで取り上げたものをみな、祭司が自分のものとして取っていた。このようなことが、シロで、そこに来るイスラエルのすべての人に対してなされていた。'),
('JPN', '撒母耳记上', 9, 2, 15, 'そのうえ、脂肪が焼かれる前に祭司の子弟がやって来て、いけにえを献げる人に「祭司に焼くための肉を渡しなさい。祭司は煮た肉をあなたから受け取らない。生の肉だけだ」と言うので、'),
('JPN', '撒母耳记上', 9, 2, 16, '人が「まず脂肪をすっかり焼いて、好きなだけお取りください」と言うと、祭司の子弟は、「いや、今渡すのだ。でなければ、私は力ずくで取る」と言った。'),
('JPN', '撒母耳记上', 9, 2, 17, 'このように、子弟たちの罪は、主の前で非常に大きかった。この人たちは主へのささげ物を侮ったのである。'),
('JPN', '撒母耳记上', 9, 2, 18, 'さてサムエルは、亜麻布のエポデを身にまとった幼いしもべとして、主の前に仕えていた。'),
('JPN', '撒母耳记上', 9, 2, 19, '彼の母は彼のために小さな上着を作り、毎年、夫とともに年ごとのいけにえを献げに上って行くとき、それを持って行った。'),
('JPN', '撒母耳记上', 9, 2, 20, 'エリは、エルカナとその妻を祝福して、「主にゆだねられた子の代わりとして、主が、この妻によって、あなたに子孫を与えてくださいますように」と言い、彼らは自分の住まいに帰るのであった。'),
('JPN', '撒母耳记上', 9, 2, 21, '主はハンナを顧み、彼女は身ごもって、三人の息子と二人の娘を産んだ。少年サムエルは主のみもとで成長した。'),
('JPN', '撒母耳记上', 9, 2, 22, 'さて、エリはたいへん年をとっていたが、息子たちがイスラエル全体に行っていることの一部始終を、それに彼らが会見の天幕の入り口で仕えている女たちと寝ていることを聞いていた。'),
('JPN', '撒母耳记上', 9, 2, 23, 'それでエリは彼らに言った。「なぜ、おまえたちはそんなことをするのか。私はこの民の皆から、おまえたちのした悪いことについて聞いているのだ。'),
('JPN', '撒母耳记上', 9, 2, 24, '息子たちよ、そういうことをしてはいけない。私は主の民が言いふらしているうわさを聞くが、それは良いものではない。'),
('JPN', '撒母耳记上', 9, 2, 25, '人が人に対して罪を犯すなら、神がその仲裁をしてくださる。だが、主に対して人が罪を犯すなら、だれがその人のために仲裁に立つだろうか。」しかし、彼らは父の言うことを聞こうとしなかった。彼らを殺すことが主のみこころだったからである。'),
('JPN', '撒母耳记上', 9, 2, 26, '一方、少年サムエルは、主にも人にもいつくしまれ、ますます成長した。'),
('JPN', '撒母耳记上', 9, 2, 27, '神の人がエリのところに来て、彼に言った。「主はこう言われる。あなたの父の家がエジプトでファラオの家に属していたとき、わたしは彼らに自分を明らかに現したではないか。'),
('JPN', '撒母耳记上', 9, 2, 28, 'わたしは、イスラエルの全部族からその家を選んでわたしの祭司とし、わたしの祭壇に上って香をたき、わたしの前でエポデを着るようにした。こうして、イスラエルの子らの食物のささげ物をすべて、あなたの父の家に与えた。'),
('JPN', '撒母耳记上', 9, 2, 29, 'なぜあなたがたは、わたしが命じたわたしへのいけにえ、わたしへのささげ物を、わたしの住まいで足蹴にするのか。なぜあなたは、わたしよりも自分の息子たちを重んじて、わたしの民イスラエルのすべてのささげ物のうちの、最上の部分で自分たちを肥やそうとするのか。'),
('JPN', '撒母耳记上', 9, 2, 30, 'それゆえ──イスラエルの神、主のことば──あなたの家と、あなたの父の家は、永遠にわたしの前に歩むとわたしは確かに言ったものの、今や──主のことば──それは絶対にあり得ない。わたしを重んじる者をわたしは重んじ、わたしを蔑む者は軽んじられるからだ。'),
('JPN', '撒母耳记上', 9, 2, 31, '見よ、その時代が来る。そのとき、わたしはあなたの腕と、あなたの父の家の腕を切り落とす。あなたの家には年長者がいなくなる。'),
('JPN', '撒母耳记上', 9, 2, 32, 'イスラエルが幸せにされるどんなときにも、あなたはわたしの住まいの衰退を見るようになる。あなたの家には、いつまでも、年長者がいない。'),
('JPN', '撒母耳记上', 9, 2, 33, 'わたしは、あなたのために、わたしの祭壇から一人の人を断ち切らないでおく。そのことはあなたの目を衰えさせ、あなたのたましいをやつれさせる。あなたの家に生まれてくる者はみな、人の手によって死ぬ。'),
('JPN', '撒母耳记上', 9, 2, 34, 'あなたの二人の息子、ホフニとピネハスの身に降りかかることが、あなたへのしるしである。二人とも同じ日に死ぬ。'),
('JPN', '撒母耳记上', 9, 2, 35, 'わたしは、わたしの心と思いの中で事を行う忠実な祭司を、わたしのために起こし、彼のために確かな家を建てよう。彼は、わたしに油注がれた者の前をいつまでも歩む。'),
('JPN', '撒母耳记上', 9, 2, 36, 'あなたの家の生き残った者はみな、銀貨一枚とパン一つを求めて彼のところに来てひれ伏し、『どうか、祭司の務めの一つでも私にあてがって、パンを一切れ食べさせてください』と言う。」'),
('JPN', '撒母耳记上', 9, 3, 1, 'さて、少年サムエルはエリのもとで主に仕えていた。そのころ、主のことばはまれにしかなく、幻も示されなかった。'),
('JPN', '撒母耳记上', 9, 3, 2, 'その日、エリは自分のところで寝ていた。彼の目はかすんできて、見えなくなっていた。'),
('JPN', '撒母耳记上', 9, 3, 3, '神のともしびが消される前であり、サムエルは、神の箱が置かれている主の神殿で寝ていた。'),
('JPN', '撒母耳记上', 9, 3, 4, '主はサムエルを呼ばれた。彼は、「はい、ここにおります」と言って、'),
('JPN', '撒母耳记上', 9, 3, 5, 'エリのところに走って行き、「はい、ここにおります。お呼びになりましたので」と言った。エリは「呼んでいない。帰って、寝なさい」と言った。それでサムエルは戻って寝た。'),
('JPN', '撒母耳记上', 9, 3, 6, '主はもう一度、サムエルを呼ばれた。サムエルは起きて、エリのところに行き、「はい、ここにおります。お呼びになりましたので」と言った。エリは「呼んでいない。わが子よ。帰って、寝なさい」と言った。'),
('JPN', '撒母耳记上', 9, 3, 7, 'サムエルは、まだ主を知らなかった。まだ主のことばは彼に示されていなかった。'),
('JPN', '撒母耳记上', 9, 3, 8, '主は三度目にサムエルを呼ばれた。彼は起きて、エリのところに行き、「はい、ここにおります。お呼びになりましたので」と言った。エリは、主が少年を呼んでおられるということを悟った。'),
('JPN', '撒母耳记上', 9, 3, 9, 'それで、エリはサムエルに言った。「行って、寝なさい。主がおまえを呼ばれたら、『主よ、お話しください。しもべは聞いております』と言いなさい。」サムエルは行って、自分のところで寝た。'),
('JPN', '撒母耳记上', 9, 3, 10, '主が来て、そばに立ち、これまでと同じように、「サムエル、サムエル」と呼ばれた。サムエルは「お話しください。しもべは聞いております」と言った。'),
('JPN', '撒母耳记上', 9, 3, 11, '主はサムエルに言われた。「見よ、わたしはイスラエルに一つのことをしようとしている。だれでもそれを聞く者は、両耳が鳴る。'),
('JPN', '撒母耳记上', 9, 3, 12, 'その日わたしは、エリの家についてわたしが語ったことすべてを、初めから終わりまでエリに実行する。'),
('JPN', '撒母耳记上', 9, 3, 13, 'わたしは、彼の家を永遠にさばくと彼に告げる。それは息子たちが自らにのろいを招くようなことをしているのを知りながら、思いとどまらせなかった咎のためだ。'),
('JPN', '撒母耳记上', 9, 3, 14, 'だから、わたしはエリの家について誓う。エリの家の咎は、いけにえによっても、穀物のささげ物によっても、永遠に赦されることはない。」'),
('JPN', '撒母耳记上', 9, 3, 15, 'サムエルは朝まで寝て、それから主の家の扉を開けた。サムエルは、この黙示のことをエリに知らせるのを恐れた。'),
('JPN', '撒母耳记上', 9, 3, 16, 'エリはサムエルを呼んで言った。「わが子サムエルよ。」サムエルは「はい、ここにおります」と言った。'),
('JPN', '撒母耳记上', 9, 3, 17, 'エリは言った。「主がおまえに語られたことばは、何だったのか。私に隠さないでくれ。もし、主がおまえに語られたことばの一つでも私に隠すなら、神がおまえを幾重にも罰せられるように。」'),
('JPN', '撒母耳记上', 9, 3, 18, 'サムエルは、すべてのことをエリに知らせて、何も隠さなかった。エリは言った。「その方は主だ。主が御目にかなうことをなさるように。」'),
('JPN', '撒母耳记上', 9, 3, 19, 'サムエルは成長した。主は彼とともにおられ、彼のことばを一つも地に落とすことはなかった。'),
('JPN', '撒母耳记上', 9, 3, 20, '全イスラエルは、ダンからベエル・シェバに至るまで、サムエルが主の預言者として堅く立てられたことを知った。'),
('JPN', '撒母耳记上', 9, 3, 21, '主は再びシロで現れた。主はシロで主のことばによって、サムエルにご自分を現されたのである。'),
('JPN', '撒母耳记上', 9, 4, 1, 'サムエルのことばが全イスラエルに行き渡ったころ、イスラエルはペリシテ人に対する戦いのために出て行き、エベン・エゼルのあたりに陣を敷いた。一方、ペリシテ人はアフェクに陣を敷いた。'),
('JPN', '撒母耳记上', 9, 4, 2, 'ペリシテ人はイスラエルを迎え撃つ陣備えをした。戦いが広がると、イスラエルはペリシテ人に打ち負かされ、約四千人が野の戦場で打ち殺された。'),
('JPN', '撒母耳记上', 9, 4, 3, '兵が陣営に戻って来たとき、イスラエルの長老たちは言った。「どうして主は、今日、ペリシテ人の前でわれわれを打たれたのだろう。シロから主の契約の箱をわれわれのところに持って来よう。そうすれば、その箱がわれわれの間に来て、われわれを敵の手から救うだろう。」'),
('JPN', '撒母耳记上', 9, 4, 4, '兵たちはシロに人を送り、そこから、ケルビムに座しておられる万軍の主の契約の箱を担いで来させた。そこに、神の契約の箱とともに、エリの二人の息子、ホフニとピネハスがいた。'),
('JPN', '撒母耳记上', 9, 4, 5, '主の契約の箱が陣営に来たとき、全イスラエルは大歓声をあげた。それで地はどよめいた。'),
('JPN', '撒母耳记上', 9, 4, 6, 'ペリシテ人はその歓声を聞いて、「ヘブル人の陣営の、あの大歓声は何だろう」と言った。そして主の箱が陣営に来たと知ったとき、'),
('JPN', '撒母耳记上', 9, 4, 7, 'ペリシテ人は恐れて、「神が陣営に来た」と言った。そして言った。「ああ、困ったことだ。今までに、こんなことはなかった。'),
('JPN', '撒母耳记上', 9, 4, 8, 'ああ、困ったことだ。だれがこの力ある神々の手から、われわれを救い出してくれるだろうか。これは、荒野で、ありとあらゆる災害をもってエジプトを打った神々だ。'),
('JPN', '撒母耳记上', 9, 4, 9, 'さあ、ペリシテ人よ。奮い立て。男らしくふるまえ。そうでないと、ヘブル人がおまえたちに仕えたように、おまえたちがヘブル人に仕えるようになる。男らしくふるまって戦え。」'),
('JPN', '撒母耳记上', 9, 4, 10, 'こうしてペリシテ人は戦った。イスラエルは打ち負かされ、それぞれ自分たちの天幕に逃げ、非常に大きな打撃となった。イスラエルの歩兵三万人が倒れた。'),
('JPN', '撒母耳记上', 9, 4, 11, '神の箱は奪われ、エリの二人の息子、ホフニとピネハスは死んだ。'),
('JPN', '撒母耳记上', 9, 4, 12, '一人のベニヤミン人が戦場から走って来て、その日シロに着いた。衣は裂け、頭には土をかぶっていた。'),
('JPN', '撒母耳记上', 9, 4, 13, '彼が着いたとき、エリはちょうど、道のそばの椅子に座って見張っていた。神の箱のことを気遣っていたからであった。この男が町に入って来て報告すると、町中こぞって泣き叫んだ。'),
('JPN', '撒母耳记上', 9, 4, 14, 'エリがこの泣き叫ぶ声を聞いて、「この騒々しい声は何だ」と言うと、男は大急ぎでやって来てエリに知らせた。'),
('JPN', '撒母耳记上', 9, 4, 15, 'エリは九十八歳で、その目はこわばり、何も見えなくなっていた。'),
('JPN', '撒母耳记上', 9, 4, 16, '男はエリに言った。「私は戦場から来た者です。私は、今日、戦場から逃げて来ました。」するとエリは「わが子よ、状況はどうなっているのか」と言った。'),
('JPN', '撒母耳记上', 9, 4, 17, '知らせを持って来た者は答えて言った。「イスラエルはペリシテ人の前から逃げ、兵のうちに打ち殺された者が多く出ました。それに、あなたの二人のご子息、ホフニとピネハスも死に、神の箱は奪われました。」'),
('JPN', '撒母耳记上', 9, 4, 18, '彼が神の箱のことを告げたとき、エリはその椅子から門のそばにあおむけに倒れ、首を折って死んだ。年寄りで、からだが重かったからである。エリは四十年間、イスラエルをさばいた。'),
('JPN', '撒母耳记上', 9, 4, 19, '彼の嫁、ピネハスの妻は身ごもっていて出産間近であったが、神の箱が奪われて、しゅうとと夫が死んだという知らせを聞いたとき、陣痛が起こり、身をかがめて子を産んだ。'),
('JPN', '撒母耳记上', 9, 4, 20, '彼女は死にかけていて、彼女の世話をしていた女たちが「恐れることはありません。男の子が生まれましたから」と言ったが、彼女は答えもせず、気にも留めなかった。'),
('JPN', '撒母耳记上', 9, 4, 21, '彼女は、「栄光がイスラエルから去った」と言って、その子をイ・カボデと名づけた。これは、神の箱が奪われたこと、また、しゅうとと夫のことを指したのであった。'),
('JPN', '撒母耳记上', 9, 4, 22, '彼女は言った。「栄光はイスラエルから去った。神の箱が奪われたから。」'),
('JPN', '撒母耳记上', 9, 5, 1, 'ペリシテ人は神の箱を奪って、エベン・エゼルからアシュドデまで運んで来た。'),
('JPN', '撒母耳记上', 9, 5, 2, 'それからペリシテ人は神の箱を取り、ダゴンの神殿に運んで来て、ダゴンの傍らに置いた。'),
('JPN', '撒母耳记上', 9, 5, 3, 'アシュドデの人たちが、翌日、朝早く起きて見ると、なんと、ダゴンは主の箱の前に、地にうつぶせになって倒れていた。そこで彼らはダゴンを取り、元の場所に戻した。'),
('JPN', '撒母耳记上', 9, 5, 4, '次の日、朝早く彼らが起きて見ると、やはり、ダゴンは主の箱の前に、地にうつぶせになって倒れていた。ダゴンの頭と両手は切り離されて敷居のところにあり、胴体だけがそこに残っていた。'),
('JPN', '撒母耳记上', 9, 5, 5, 'それで今日に至るまで、ダゴンの祭司たちやダゴンの神殿に入る者はみな、アシュドデにあるダゴンの敷居を踏まない。'),
('JPN', '撒母耳记上', 9, 5, 6, '主の手はアシュドデの人たちの上に重くのしかかり、アシュドデとその地域の人たちを腫物で打って脅かした。'),
('JPN', '撒母耳记上', 9, 5, 7, 'アシュドデの人たちは、この有様を見て言った。「イスラエルの神の箱は、われわれのもとにとどまってはならない。その手は、われわれとわれわれの神ダゴンの上に厳しいものであるから。」'),
('JPN', '撒母耳记上', 9, 5, 8, 'それで彼らは人を遣わして、ペリシテ人の領主を全員そこに集め、「イスラエルの神の箱をどうしたらよいでしょうか」と言った。領主たちは「イスラエルの神の箱は、ガテに移るようにせよ」と言った。そこで彼らはイスラエルの神の箱を移した。'),
('JPN', '撒母耳记上', 9, 5, 9, 'それがガテに移された後、主の手はこの町に下り、非常に大きな恐慌を引き起こし、この町の人々を上の者も下の者もみな打ったので、彼らに腫物ができた。'),
('JPN', '撒母耳记上', 9, 5, 10, 'ガテの人たちは神の箱をエクロンに送った。神の箱がエクロンにやって来たとき、エクロンの人たちは大声で叫んで言った。「私と私の民を殺すために、イスラエルの神の箱をこっちに回して来たのだ。」'),
('JPN', '撒母耳记上', 9, 5, 11, 'それで彼らは人を遣わして、ペリシテ人の領主を全員集め、「イスラエルの神の箱を送って、元の場所に戻っていただきましょう。私と私の民を殺すことがないように」と言った。町中に死の恐慌があったのである。神の手は、そこに非常に重くのしかかっていた。'),
('JPN', '撒母耳记上', 9, 5, 12, '死ななかった者は腫物で打たれ、助けを求める町の叫び声は天にまで上った。'),
('JPN', '撒母耳记上', 9, 6, 1, '主の箱は七か月間ペリシテ人の地にあった。'),
('JPN', '撒母耳记上', 9, 6, 2, 'ペリシテ人は祭司たちと占い師たちを呼び寄せて言った。「主の箱をどうしたらよいでしょうか。どのようにして、それを元の場所に送り返せるか、教えてください。」'),
('JPN', '撒母耳记上', 9, 6, 3, '彼らは答えた。「イスラエルの神の箱を送り返すのなら、何もつけないで送り返してはなりません。神に対して償いをしなければなりません。そうすれば、あなたがたは癒やされるでしょう。また、なぜ、神の手があなたがたから去らないかが分かるでしょう。」'),
('JPN', '撒母耳记上', 9, 6, 4, '人々は言った。「私たちが送るべき償いのものは何ですか。」彼らは言った。「ペリシテ人の領主の数に合わせて、五つの金の腫物、つまり五つの金のねずみです。彼ら全員、つまりあなたがたの領主たちに、同じわざわいが下ったのですから。'),
('JPN', '撒母耳记上', 9, 6, 5, 'あなたがたの腫物の像、つまり、この地を破滅させようとしているねずみの像を造り、それらをイスラエルの神に貢ぎとして献げなさい。もしかしたら神は、あなたがたと、あなたがたの神々、そしてあなたがたの地の上にのしかかっている、その手を軽くされるかもしれません。'),
('JPN', '撒母耳记上', 9, 6, 6, 'なぜ、あなたがたは、エジプト人とファラオが心を硬くしたように、心を硬くするのですか。神が彼らに対して力を働かせたときに、彼らはイスラエルを去らせ、イスラエルは出て行ったではありませんか。'),
('JPN', '撒母耳记上', 9, 6, 7, '今、一台の新しい車を用意し、くびきを付けたことのない、乳を飲ませている雌牛を二頭取り、雌牛を車につなぎ、その子牛は引き離して小屋に戻しなさい。'),
('JPN', '撒母耳记上', 9, 6, 8, 'また、主の箱を取って車に載せなさい。償いとして返す金の品物を鞍袋に入れて、そのそばに置きなさい。そして、それが行くがままに、去らせなければなりません。'),
('JPN', '撒母耳记上', 9, 6, 9, '注意して見ていなさい。その箱がその国境への道をベテ・シェメシュに上って行くなら、私たちにこの大きなわざわいを起こしたのはあの神です。もし行かないなら、神の手が私たちを打ったのではなく、私たちに偶然起こったことだと分かります。」'),
('JPN', '撒母耳记上', 9, 6, 10, '人々はそのようにした。彼らは乳を飲ませている雌牛を二頭取り、それを車につないだ。子牛は小屋に閉じ込めた。'),
('JPN', '撒母耳记上', 9, 6, 11, 'そして主の箱を車に載せ、また金のねずみ、すなわち腫物の像を入れた鞍袋を載せた。'),
('JPN', '撒母耳记上', 9, 6, 12, '雌牛は、ベテ・シェメシュへの道、一本の大路をまっすぐに進んだ。鳴きながら進み続け、右にも左にもそれなかった。ペリシテ人の領主たちは、ベテ・シェメシュの国境まで、その後について行った。'),
('JPN', '撒母耳记上', 9, 6, 13, 'ベテ・シェメシュの人たちは、谷間で小麦の刈り入れをしていたが、目を上げると、神の箱が見えた。彼らはそれを見て喜んだ。'),
('JPN', '撒母耳记上', 9, 6, 14, '車はベテ・シェメシュ人ヨシュアの畑に来て、そこにとどまった。そこには大きな石があった。人々は、車の木を割り、雌牛を全焼のささげ物として主に献げた。'),
('JPN', '撒母耳记上', 9, 6, 15, 'レビ人たちは、主の箱と、そばにあった金の品物の入っている鞍袋を降ろし、その大きな石の上に置いた。その日、ベテ・シェメシュの人たちは全焼のささげ物を献げ、いけにえを主に献げた。'),
('JPN', '撒母耳记上', 9, 6, 16, 'ペリシテ人の五人の領主は、これを見て、その日エクロンに帰った。'),
('JPN', '撒母耳记上', 9, 6, 17, 'ペリシテ人が償いとして主に返した金の腫物は、アシュドデのために一つ、ガザのために一つ、アシュケロンのために一つ、ガテのために一つ、エクロンのために一つであった。'),
('JPN', '撒母耳记上', 9, 6, 18, 'すなわち、金のねずみは、五人の領主に属するペリシテ人の町の総数によっていた。それは、砦の町と城壁のない村の両方を含んでいる。彼らが主の箱を置いたアベルの大きな台は、今日までベテ・シェメシュ人ヨシュアの畑にある。'),
('JPN', '撒母耳记上', 9, 6, 19, '主はベテ・シェメシュの人たちを打たれた。主の箱の中を見たからである。主は、民のうち七十人を、すなわち、千人に五人を打たれた。主が民を激しく打たれたので、民は喪に服した。'),
('JPN', '撒母耳记上', 9, 6, 20, 'ベテ・シェメシュの人たちは言った。「だれが、この聖なる神、主の前に立つことができるだろう。私たちのところから、だれのところに上って行くのだろうか。」'),
('JPN', '撒母耳记上', 9, 6, 21, '彼らはキルヤテ・エアリムの住民に使者を遣わして言った。「ペリシテ人が主の箱を返してよこしました。下って来て、あなたがたのところに運び上げてください。」'),
('JPN', '撒母耳记上', 9, 7, 1, 'キルヤテ・エアリムの人々は来て、主の箱を運び上げ、丘の上のアビナダブの家に運んだ。そして、主の箱を守るために彼の息子エルアザルを聖別した。'),
('JPN', '撒母耳记上', 9, 7, 2, '箱がキルヤテ・エアリムにとどまった日から長い年月がたって、二十年になった。イスラエルの全家は主を慕い求めていた。'),
('JPN', '撒母耳记上', 9, 7, 3, 'サムエルはイスラエルの全家に言った。「もしあなたがたが、心のすべてをもって主に立ち返るなら、あなたがたの間から異国の神々やアシュタロテを取り除きなさい。そして心を主に向け、主にのみ仕えなさい。そうすれば、主はあなたがたをペリシテ人の手から救い出してくださいます。」'),
('JPN', '撒母耳记上', 9, 7, 4, 'イスラエル人は、バアルやアシュタロテの神々を取り除き、主にのみ仕えた。'),
('JPN', '撒母耳记上', 9, 7, 5, 'サムエルは言った。「全イスラエルを、ミツパに集めなさい。私はあなたがたのために主に祈ります。」'),
('JPN', '撒母耳记上', 9, 7, 6, '彼らはミツパに集まり、水を汲んで主の前に注ぎ、その日は断食した。彼らはそこで、「私たちは主の前に罪ある者です」と言った。こうしてサムエルはミツパでイスラエル人をさばいた。'),
('JPN', '撒母耳记上', 9, 7, 7, 'イスラエル人がミツパに集まったことをペリシテ人が聞いたとき、ペリシテ人の領主たちはイスラエルに向かって上って来た。イスラエル人はこれを聞いて、ペリシテ人を恐れた。'),
('JPN', '撒母耳记上', 9, 7, 8, 'イスラエル人はサムエルに言った。「私たちから離れて黙っていないでください。私たちの神、主に叫ぶのをやめないでください。主が私たちをペリシテ人の手から救ってくださるようにと。」'),
('JPN', '撒母耳记上', 9, 7, 9, 'サムエルは、乳離れしていない子羊一匹を取り、焼き尽くす全焼のささげ物として主に献げた。サムエルはイスラエルのために主に叫んだ。すると主は彼に答えられた。'),
('JPN', '撒母耳记上', 9, 7, 10, 'サムエルが全焼のささげ物を献げていたとき、ペリシテ人がイスラエルと戦おうとして近づいて来た。しかし主は、その日ペリシテ人の上に大きな雷鳴をとどろかせ、彼らをかき乱したので、彼らはイスラエルに打ち負かされた。'),
('JPN', '撒母耳记上', 9, 7, 11, 'イスラエルの人々は、ミツパから出てペリシテ人を追い、彼らを討ってベテ・カルの下にまで行った。'),
('JPN', '撒母耳记上', 9, 7, 12, 'サムエルは一つの石を取り、ミツパとエシェンの間に置き、それにエベン・エゼルという名をつけ、「ここまで主が私たちを助けてくださった」と言った。'),
('JPN', '撒母耳记上', 9, 7, 13, 'ペリシテ人は征服され、二度とイスラエルの領土に入って来なかった。サムエルの時代を通して、主の手がペリシテ人の上にのしかかっていた。'),
('JPN', '撒母耳记上', 9, 7, 14, 'ペリシテ人がイスラエルから奪い取っていた町々は、エクロンからガテまでが、イスラエルに戻った。イスラエルはペリシテ人の手から、その領土を解放した。そのころ、イスラエルとアモリ人の間には平和があった。'),
('JPN', '撒母耳记上', 9, 7, 15, 'サムエルは、一生の間、イスラエルをさばいた。'),
('JPN', '撒母耳记上', 9, 7, 16, '彼は年ごとに、ベテル、ギルガル、ミツパを巡回し、これらすべての聖所でイスラエルをさばき、'),
('JPN', '撒母耳记上', 9, 7, 17, 'ラマに帰った。そこに自分の家があり、そこでイスラエルをさばいていたからである。彼はそこに主のために祭壇を築いた。'),
('JPN', '撒母耳记上', 9, 8, 1, 'サムエルは、年老いたとき、息子たちをイスラエルのさばきつかさとして任命した。'),
('JPN', '撒母耳记上', 9, 8, 2, '長男の名はヨエル、次男の名はアビヤであった。彼らはベエル・シェバでさばきつかさをしていた。'),
('JPN', '撒母耳记上', 9, 8, 3, 'しかし、この息子たちは父の道に歩まず、利得を追い求め、賄賂を受け取り、さばきを曲げていた。'),
('JPN', '撒母耳记上', 9, 8, 4, 'イスラエルの長老たちはみな集まり、ラマにいるサムエルのところにやって来て、'),
('JPN', '撒母耳记上', 9, 8, 5, '彼に言った。「ご覧ください。あなたはお年を召し、ご子息たちはあなたの道を歩んでいません。どうか今、ほかのすべての国民のように、私たちをさばく王を立ててください。」'),
('JPN', '撒母耳记上', 9, 8, 6, '彼らが、「私たちをさばく王を私たちに与えてください」と言ったとき、そのことばはサムエルの目には悪しきことであった。それでサムエルは主に祈った。'),
('JPN', '撒母耳记上', 9, 8, 7, '主はサムエルに言われた。「民があなたに言うことは何であれ、それを聞き入れよ。なぜなら彼らは、あなたを拒んだのではなく、わたしが王として彼らを治めることを拒んだのだから。'),
('JPN', '撒母耳记上', 9, 8, 8, 'わたしが彼らをエジプトから連れ上った日から今日に至るまで、彼らのしたことといえば、わたしを捨てて、ほかの神々に仕えることだった。そのように彼らは、あなたにもしているのだ。'),
('JPN', '撒母耳记上', 9, 8, 9, '今、彼らの声を聞き入れよ。ただし、彼らに自分たちを治める王の権利をはっきりと宣言せよ。」'),
('JPN', '撒母耳记上', 9, 8, 10, 'サムエルは、自分に王を求めるこの民に対して、主のすべてのことばを話した。'),
('JPN', '撒母耳记上', 9, 8, 11, '彼は言った。「あなたがたを治める王の権利はこうだ。あなたがたの息子たちを取り、戦車や軍馬に乗せ、自分の戦車の前を走らせる。'),
('JPN', '撒母耳记上', 9, 8, 12, 'また、自分のために千人隊の長や五十人隊の長として任命し、自分の耕地を耕させ、自分の刈り入れに従事させ、武具や戦車の部品を作らせる。'),
('JPN', '撒母耳记上', 9, 8, 13, 'また、あなたがたの娘たちを取り、香料を作る者や料理する者やパンを焼く者とする。'),
('JPN', '撒母耳记上', 9, 8, 14, 'あなたがたの畑やぶどう畑や良いオリーブ畑を没収し、自分の家来たちに与える。'),
('JPN', '撒母耳记上', 9, 8, 15, 'あなたがたの穀物とぶどう畑の十分の一を取り、廷臣や家来たちに与える。'),
('JPN', '撒母耳记上', 9, 8, 16, 'あなたがたの奴隷や女奴隷、それにあなたがたの子牛やろばの最も良いものを取り、自分の仕事をさせる。'),
('JPN', '撒母耳记上', 9, 8, 17, 'あなたがたの羊の群れの十分の一を取り、あなたがた自身は王の奴隷となる。'),
('JPN', '撒母耳记上', 9, 8, 18, 'その日、あなたがたが自分たちのために選んだ王のゆえに泣き叫んでも、その日、主はあなたがたに答えはしない。」'),
('JPN', '撒母耳记上', 9, 8, 19, 'しかし民は拒んで、サムエルの言うことを聞こうとしなかった。そして言った。「いや。どうしても、私たちの上には王が必要です。'),
('JPN', '撒母耳记上', 9, 8, 20, 'そうすれば私たちもまた、ほかのすべての国民のようになり、王が私たちをさばき、私たちの先に立って出陣し、私たちの戦いを戦ってくれるでしょう。」'),
('JPN', '撒母耳记上', 9, 8, 21, 'サムエルは、民のすべてのことばを聞いて、それを主の耳に入れた。'),
('JPN', '撒母耳记上', 9, 8, 22, '主はサムエルに言われた。「彼らの言うことを聞き、彼らのために王を立てよ。」それで、サムエルはイスラエルの人々に「それぞれ自分の町に帰りなさい」と言った。'),
('JPN', '撒母耳记上', 9, 9, 1, 'ベニヤミン人で、その名をキシュという人がいた。キシュはアビエルの子で、アビエルはツェロルの子、ツェロルはベコラテの子、ベコラテはベニヤミン人アフィアハの子であった。彼は有力者であった。'),
('JPN', '撒母耳记上', 9, 9, 2, 'キシュには一人の息子がいて、その名をサウルといった。彼は美しい若者で、イスラエル人の中で彼より美しい者はいなかった。彼は民のだれよりも、肩から上だけ高かった。'),
('JPN', '撒母耳记上', 9, 9, 3, 'あるとき、サウルの父キシュの雌ろば数頭がいなくなったので、キシュは息子サウルに言った。「しもべを一人連れて、雌ろばを捜しに行ってくれ。」'),
('JPN', '撒母耳记上', 9, 9, 4, 'サウルはエフライムの山'),
('JPN', '撒母耳记上', 9, 9, 5, '二人がツフの地にやって来たとき、サウルは一緒にいたしもべに言った。「さあ、もう帰ろう。父が雌ろばのことはさておき、私たちのほうを心配し始めるといけないから。」'),
('JPN', '撒母耳记上', 9, 9, 6, 'すると、しもべは言った。「ご覧ください。この町には神の人がいます。この人は敬われている人です。この人の言うことはみな、必ず実現します。今そこへ参りましょう。私たちが行く道を教えてくれるかもしれません。」'),
('JPN', '撒母耳记上', 9, 9, 7, 'サウルはしもべに言った。「もし行くとすると、その人に何を持って行こうか。私たちの袋には、パンもなくなったし、神の人に持って行く贈り物もない。何かあるか。」'),
('JPN', '撒母耳记上', 9, 9, 8, 'しもべは再びサウルに答えた。「ご覧ください。私の手に四分の一シェケルの銀があります。これを神の人に差し上げたら、私たちの行く道を教えてくださるでしょう。」'),
('JPN', '撒母耳记上', 9, 9, 9, '昔イスラエルでは、神のみこころを求めに行く人は「さあ、予見者のところへ行こう」とよく言っていた。今の預言者は、昔は予見者と呼ばれていたからである。'),
('JPN', '撒母耳记上', 9, 9, 10, 'サウルはしもべに言った。「それはよい。さあ、行こう。」こうして、彼らは神の人のいる町へ行った。'),
('JPN', '撒母耳记上', 9, 9, 11, '彼らがその町への坂道を上って行くと、水を汲みに出て来た娘たちに出会った。彼らは「予見者はここにおられますか」と尋ねた。'),
('JPN', '撒母耳记上', 9, 9, 12, 'すると娘たちは答えて言った。「はい。この先におられます。さあ、急いでください。今日、町に来られました。今日、高き所で民のためにいけにえをお献げになりますから。'),
('JPN', '撒母耳记上', 9, 9, 13, '町に入ると、あの方が見つかるでしょう。あの方が食事のために高き所に上られる前に。民は、あの方が来られるまで食事をしません。あの方がいけにえを祝福して、その後で、招かれた者たちが食事をすることになっているからです。今、上って行ってください。あの方は、すぐに見つかるでしょう。」'),
('JPN', '撒母耳记上', 9, 9, 14, '彼らが町へ上って行き、町に入りかかったとき、ちょうどサムエルが、高き所に上ろうとして彼らの方に向かって出て来た。'),
('JPN', '撒母耳记上', 9, 9, 15, '主は、サウルが来る前の日に、サムエルの耳を開いて告げておられた。'),
('JPN', '撒母耳记上', 9, 9, 16, '「明日の今ごろ、わたしはある人をベニヤミンの地からあなたのところに遣わす。あなたはその人に油を注ぎ、わたしの民イスラエルの君主とせよ。彼はわたしの民をペリシテ人の手から救う。民の叫びがわたしに届き、わたしが自分の民に目を留めたからだ。」'),
('JPN', '撒母耳记上', 9, 9, 17, 'サムエルがサウルを見るやいなや、主は彼に告げられた。「さあ、わたしがあなたに話した者だ。この者がわたしの民を支配するのだ。」'),
('JPN', '撒母耳记上', 9, 9, 18, 'サウルは、門の中でサムエルに近づいて、言った。「予見者の家はどこですか。教えてください。」'),
('JPN', '撒母耳记上', 9, 9, 19, 'サムエルはサウルに答えた。「私が予見者です。私より先に高き所に上りなさい。今日、あなたがたは私と一緒に食事をするのです。明日の朝、私があなたを送ります。あなたの心にあるすべてのことについて、話しましょう。'),
('JPN', '撒母耳记上', 9, 9, 20, '三日前にいなくなったあなたの雌ろばについては、もう気にかけないようにしてください。見つかっていますから。全イスラエルの思いは、だれに向けられているのでしょう。あなたと、あなたの父の全家にではありませんか。」'),
('JPN', '撒母耳记上', 9, 9, 21, 'サウルは答えて言った。「私はベニヤミン人で、イスラエルの最も小さい部族の出ではありませんか。私の家族は、ベニヤミンの部族のどの家族よりも、取るに足りないものではありませんか。どうしてこのようなことを私に言われるのですか。」'),
('JPN', '撒母耳记上', 9, 9, 22, 'サムエルはサウルとそのしもべを広間に連れて来て、三十人ほどの招かれた人たちの上座に着かせた。'),
('JPN', '撒母耳记上', 9, 9, 23, 'サムエルは料理人に、「取っておくようにと渡しておいた、ごちそうを出しなさい」と言った。'),
('JPN', '撒母耳记上', 9, 9, 24, '料理人は、もも肉とその上にある部分を取り出し、サウルの前に置いた。サムエルは言った。「これはあなたのために取っておいたものです。あなたの前に置いて、食べてください。その肉は、私が民を招いたと言って、この定められた時のため、あなたのために取り分けておいたものですから。」その日、サウルはサムエルと一緒に食事をした。'),
('JPN', '撒母耳记上', 9, 9, 25, '彼らは高き所から町に下って来た。それからサムエルはサウルと屋上で話をした。'),
('JPN', '撒母耳记上', 9, 9, 26, '彼らは朝早く起きた。夜が明けかかると、サムエルは、屋上にいるサウルに叫んだ。「起きてください。あなたを送りましょう。」サウルは起きて、サムエルと二人で外に出た。'),
('JPN', '撒母耳记上', 9, 9, 27, '二人が町外れへと下っていたとき、サムエルがサウルに「しもべに、私たちより先に行くように言ってください」と言ったので、しもべは先に行った。「あなたは、ここにしばらくとどまってください。神のことばをお聞かせしますから。」'),
('JPN', '撒母耳记上', 9, 10, 1, 'サムエルは油の壺を取ってサウルの頭に注ぎ、彼に口づけして言った。「主が、ご自分のゆずりの地と民を治める君主とするため、あなたに油を注がれたのではありませんか。'),
('JPN', '撒母耳记上', 9, 10, 2, '今日、私のもとを離れて行くとき、ベニヤミンの領内のツェルツァフにあるラケルの墓のそばで、二人の人に会うでしょう。彼らはあなたに、『捜し歩いておられた雌ろばは見つかりました。あなたの父上は、雌ろばのことはどうでもよくなり、息子のためにどうしたらよいのだろうと言って、あなたがたのことを心配しておられます』と言うでしょう。'),
('JPN', '撒母耳记上', 9, 10, 3, 'そこからなお進んで、タボルの樫の木のところまで行くと、そこで、神のもとに行こうとベテルに上って行く三人の人に会います。一人は子やぎを三匹持ち、一人は円形パンを三つ持ち、一人はぶどう酒の皮袋を一つ持っています。'),
('JPN', '撒母耳记上', 9, 10, 4, '彼らはあなたにあいさつをして、あなたにパンを二つくれます。彼らの手から受け取りなさい。'),
('JPN', '撒母耳记上', 9, 10, 5, 'それから、ペリシテ人の守備隊がいるギブア・エロヒムに着きます。その町に入るとき、琴、タンバリン、笛、竪琴を鳴らす者を先頭に、預言をしながら高き所から下って来る預言者の一団に出会います。'),
('JPN', '撒母耳记上', 9, 10, 6, '主の霊があなたの上に激しく下り、あなたも彼らと一緒に預言して、新しい人に変えられます。'),
('JPN', '撒母耳记上', 9, 10, 7, 'これらのしるしがあなたに起こったら、自分の力でできることをしなさい。神があなたとともにおられるのですから。'),
('JPN', '撒母耳记上', 9, 10, 8, '私より先にギルガルに下って行きなさい。私も全焼のささげ物と交わりのいけにえを献げるために、あなたのところへ下って行きます。私があなたのところに着くまで、そこで七日間待たなければなりません。それからあなたがなすべきことを教えます。」'),
('JPN', '撒母耳记上', 9, 10, 9, 'サウルがサムエルから去って行こうと背を向けたとき、神はサウルに新しい心を与えられた。これらすべてのしるしは、その日のうちに起こった。'),
('JPN', '撒母耳记上', 9, 10, 10, '彼らがそこからギブアに行くと、見よ、預言者の一団が彼の方にやって来た。すると、神の霊が彼の上に激しく下り、彼も彼らの間で預言した。'),
('JPN', '撒母耳记上', 9, 10, 11, '以前からサウルを知っている人たちはみな、彼が預言者たちと一緒に預言しているのを見た。民は互いに言った。「キシュの息子は、いったいどうしたことか。サウルも預言者の一人なのか。」'),
('JPN', '撒母耳记上', 9, 10, 12, 'そこにいた一人も、これに応じて、「彼らの父はだれだろう」と言った。こういうわけで、「サウルも預言者の一人なのか」ということが、語りぐさになった。'),
('JPN', '撒母耳记上', 9, 10, 13, 'サウルは預言を終えて、高き所に帰って来た。'),
('JPN', '撒母耳记上', 9, 10, 14, 'サウルのおじは、彼とそのしもべに言った。「どこに行っていたのか。」サウルは言った。「雌ろばを捜しにです。どこにもいないと分かったので、サムエルのところに行って来ました。」'),
('JPN', '撒母耳记上', 9, 10, 15, 'サウルのおじは言った。「サムエルはあなたがたに何と言ったか、私に話してくれ。」'),
('JPN', '撒母耳记上', 9, 10, 16, 'サウルはおじに言った。「雌ろばは見つかっていると、はっきり私たちに知らせてくれました。」しかし、サムエルが語った王位のことについては、おじに話さなかった。'),
('JPN', '撒母耳记上', 9, 10, 17, 'サムエルはミツパで、民を主のもとに呼び集め、'),
('JPN', '撒母耳记上', 9, 10, 18, 'イスラエル人に言った。「イスラエルの神、主はこう言われる。『イスラエルをエジプトから連れ上り、あなたがたを、エジプトの手と、あなたがたを圧迫していたすべての王国の手から救い出したのは、このわたしだ。』'),
('JPN', '撒母耳记上', 9, 10, 19, 'しかし、あなたがたは今日、すべてのわざわいと苦しみからあなたがたを救ってくださる、あなたがたの神を退けて、『いや、私たちの上に王を立ててください』と言った。今、部族ごと、分団ごとに、主の前に出なさい。」'),
('JPN', '撒母耳记上', 9, 10, 20, 'サムエルは、イスラエルの全部族を近づかせた。すると、ベニヤミンの部族がくじで取り分けられた。'),
('JPN', '撒母耳记上', 9, 10, 21, 'そして、ベニヤミンの部族を、その氏族ごとに近づかせた。すると、マテリの氏族がくじで取り分けられた。そして、キシュの息子サウルがくじで取り分けられた。人々はサウルを捜したが、見つからなかった。'),
('JPN', '撒母耳记上', 9, 10, 22, '人々はさらに、主に「あの人はもう、ここに来ているのですか」と尋ねた。主は「見よ、彼は荷物の間に隠れている」と言われた。'),
('JPN', '撒母耳记上', 9, 10, 23, '彼らは走って行って、そこから彼を連れて来た。サウルが民の中に立つと、民のだれよりも、肩から上だけ高かった。'),
('JPN', '撒母耳记上', 9, 10, 24, 'サムエルは民全体に言った。「主がお選びになったこの人を見なさい。民全体のうちに、彼のような者はいない。」民はみな、大声で叫んで、「王様万歳」と言った。'),
('JPN', '撒母耳记上', 9, 10, 25, 'サムエルは民に王権の定めについて語り、それを文書に記して主の前に納めた。それから、サムエルは民をみな、それぞれ自分の家へ帰した。'),
('JPN', '撒母耳记上', 9, 10, 26, 'サウルもギブアの自分の家へ帰って行った。神に心を動かされた勇者たちは、彼について行った。'),
('JPN', '撒母耳记上', 9, 10, 27, 'しかし、よこしまな者たちは、「こいつがどうしてわれわれを救えるのか」と言って軽蔑し、彼に贈り物を持って来なかった。しかし彼は黙っていた。'),
('JPN', '撒母耳记上', 9, 11, 1, 'さて、アンモン人ナハシュが上って来て、ヤベシュ・ギルアデに対して陣を敷いた。ヤベシュの人々はみな、ナハシュに言った。「私たちと契約を結んでください。そうすれば、あなたに仕えます。」'),
('JPN', '撒母耳记上', 9, 11, 2, 'アンモン人ナハシュは彼らに言った。「次の条件でおまえたちと契約を結ぼう。おまえたち皆の者の右の目をえぐり取ることだ。それをもってイスラエル全体に恥辱を負わせよう。」'),
('JPN', '撒母耳记上', 9, 11, 3, 'ヤベシュの長老たちは彼に言った。「イスラエルの国中に使者を遣わすため、七日の猶予を与えてください。もし、私たちを救う者がいなければ、あなたのところに出て行きます。」'),
('JPN', '撒母耳记上', 9, 11, 4, '使者たちはサウルのギブアに来て、これらのことばを民の耳に語った。民はみな、声をあげて泣いた。'),
('JPN', '撒母耳记上', 9, 11, 5, 'ちょうどそのとき、サウルが牛を追って畑から帰って来た。サウルは言った。「民が泣いているが、いったい何が起こったのか。」彼らは、ヤベシュの人々のことばを彼に告げた。'),
('JPN', '撒母耳记上', 9, 11, 6, 'サウルがこれらのことばを聞いたとき、神の霊がサウルの上に激しく下った。彼の怒りは激しく燃え上がった。'),
('JPN', '撒母耳记上', 9, 11, 7, '彼は一くびきの牛を取り、それを切り分け、使者に託してイスラエルの国中に送り、「サウルとサムエルに従って出て来ない者の牛は、このようにされる」と言った。主の恐れが民に下って、彼らは一斉に出て来た。'),
('JPN', '撒母耳记上', 9, 11, 8, 'サウルはベゼクで彼らを数えた。すると、イスラエルの人々は三十万人、ユダの人々は三万人であった。'),
('JPN', '撒母耳记上', 9, 11, 9, '彼らは、やって来た使者たちに言った。「ヤベシュ・ギルアデの人にこう言いなさい。明日、日が高くなるころ、あなたがたに救いがある。」使者たちは帰って行って、ヤベシュの人々に告げたので、彼らは喜んだ。'),
('JPN', '撒母耳记上', 9, 11, 10, 'ヤベシュの人々は言った。「私たちは、明日、あなたがたのところに出て行きます。あなたがたの良いと思うように私たちにしてください。」'),
('JPN', '撒母耳记上', 9, 11, 11, '翌日、サウルは兵を三組に分け、夜明けの見張りの時に陣営に突入し、昼までアンモン人を討った。生き残った者は散り散りになり、二人の者がともにいることはなかった。'),
('JPN', '撒母耳记上', 9, 11, 12, '民はサムエルに言った。「『サウルがわれわれを治めるのか』と言ったのはだれでしたか。その者たちを引き渡してください。彼らを殺します。」'),
('JPN', '撒母耳记上', 9, 11, 13, 'サウルは言った。「今日はだれも殺されてはならない。今日、主がイスラエルにおいて勝利をもたらしてくださったのだから。」'),
('JPN', '撒母耳记上', 9, 11, 14, 'サムエルは民に言った。「さあ、われわれはギルガルに行って、そこで王政を樹立しよう。」'),
('JPN', '撒母耳记上', 9, 11, 15, '民はみなギルガルに行き、ギルガルで、主の前にサウルを王とした。彼らはそこで、主の前に交わりのいけにえを献げた。サウルとイスラエルのすべての者は、そこで大いに喜んだ。'),
('JPN', '撒母耳记上', 9, 12, 1, 'サムエルは全イスラエルに言った。「見よ、あなたがたが私に言ったことを、私はことごとく聞き入れ、あなたがたの上に王を立てた。'),
('JPN', '撒母耳记上', 9, 12, 2, '今、見なさい。王はあなたがたの先に立って歩んでいる。私は年をとり、髪も白くなった。そして、私の息子たちは、あなたがたとともにいる。私は若いときから今日まで、あなたがたの先に立って歩んできた。'),
('JPN', '撒母耳记上', 9, 12, 3, 'さあ今、主と主に油注がれた者の前で、私を訴えなさい。私はだれかの牛を取っただろうか。だれかのろばを取っただろうか。だれかを虐げ、だれかを打ちたたいただろうか。だれかの手から賄賂を受け取って自分の目をくらましただろうか。もしそうなら、あなたがたにお返しする。」'),
('JPN', '撒母耳记上', 9, 12, 4, '彼らは言った。「あなたは私たちを虐げたことも、踏みにじったことも、人の手から何かを取ったこともありません。」'),
('JPN', '撒母耳记上', 9, 12, 5, 'サムエルは彼らに言った。「あなたがたが私の手に何も見出さなかったことについては、今日、あなたがたの間で主が証人であり、主に油注がれた者が証人である。」そこで、ある人が「証人は」と言うと、'),
('JPN', '撒母耳记上', 9, 12, 6, 'サムエルは「主である。モーセとアロンを立てて、あなたがたの先祖をエジプトの地から上らせた方である」と民に告げた。'),
('JPN', '撒母耳记上', 9, 12, 7, '「さあ、立ちなさい。私は、主があなたがたと、あなたがたの先祖に行われたすべての正義のみわざを、主の前であなたがたに説き明かそう。'),
('JPN', '撒母耳记上', 9, 12, 8, 'ヤコブがエジプトに行ったとき、あなたがたの先祖は主に叫んだ。主はモーセとアロンを遣わし、彼らはあなたがたの先祖をエジプトから導き出し、この場所に住まわせた。'),
('JPN', '撒母耳记上', 9, 12, 9, 'しかし、先祖たちは自分たちの神、主を忘れたので、主は彼らをハツォルの軍の長シセラの手、ペリシテ人の手、モアブの王の手に売り渡された。それで先祖たちは彼らと戦うことになったのだ。'),
('JPN', '撒母耳记上', 9, 12, 10, '先祖たちは主に叫んで、『私たちは主を捨て、バアルやアシュタロテの神々に仕えて罪を犯しました。今、私たちがあなたに仕えるため、敵の手から救い出してください』と言った。'),
('JPN', '撒母耳记上', 9, 12, 11, 'すると主は、エルバアルとバラクとエフタとサムエルを遣わし、あなたがたを周囲の敵の手から救い出してくださった。それで、あなたがたは安らかに住んだのだ。'),
('JPN', '撒母耳记上', 9, 12, 12, 'しかし、アンモン人の王ナハシュがあなたがたに向かって来るのを見たとき、あなたがたの神、主があなたがたの王であるのに、『いや、王が私たちを治めるのだ』と私に言った。'),
('JPN', '撒母耳记上', 9, 12, 13, '今、見なさい。あなたがたが求め、選んだ王だ。見なさい。主はあなたがたの上に王を置かれた。'),
('JPN', '撒母耳记上', 9, 12, 14, 'もし、あなたがたが主を恐れ、主に仕え、主の御声に聞き従い、主の命令に逆らわず、また、あなたがたも、あなたがたを治める王も、自分たちの神、主の後に従うなら、それでよい。'),
('JPN', '撒母耳记上', 9, 12, 15, 'しかし、もし、あなたがたが主の御声に聞き従わず、主の命令に逆らうなら、主の手が、あなたがたとあなたがたの先祖の上に下る。'),
('JPN', '撒母耳记上', 9, 12, 16, '今、しっかり立って、主があなたがたの目の前で行われる、この大きなみわざを見なさい。'),
('JPN', '撒母耳记上', 9, 12, 17, '今は小麦の刈り入れ時ではないか。主が雷と雨を下されるようにと、私は主を呼び求める。あなたがたは王を求めることで、主の目の前に犯した悪が大きかったことを認めて、心に留めなさい。」'),
('JPN', '撒母耳记上', 9, 12, 18, 'そしてサムエルは主を呼び求めた。すると、主はその日、雷と雨を下された。民はみな、主とサムエルを非常に恐れた。'),
('JPN', '撒母耳记上', 9, 12, 19, '民はみなサムエルに言った。「私たちが死なないように、しもべどものために、あなたの神、主に祈ってください。私たちは、王を求めることによって、私たちのあらゆる罪の上に悪を加えてしまったからです。」'),
('JPN', '撒母耳记上', 9, 12, 20, 'サムエルは民に言った。「恐れてはならない。あなたがたは、このすべての悪を行った。しかし主に従う道から外れず、心を尽くして主に仕えなさい。'),
('JPN', '撒母耳记上', 9, 12, 21, '役にも立たず、救い出すこともできない、空しいものを追う道へ外れてはならない。それらは、空しいものだ。'),
('JPN', '撒母耳记上', 9, 12, 22, '主は、ご自分の大いなる御名のために、ご自分の民を捨て去りはしない。主は、あなたがたをご自分の民とすることを良しとされたからだ。'),
('JPN', '撒母耳记上', 9, 12, 23, '私もまた、あなたがたのために祈るのをやめ、主の前に罪ある者となることなど、とてもできない。私はあなたがたに、良い正しい道を教えよう。'),
('JPN', '撒母耳记上', 9, 12, 24, 'ただ主を恐れ、心を尽くして、誠実に主に仕えなさい。主がどれほど大いなることをあなたがたになさったかを、よく見なさい。'),
('JPN', '撒母耳记上', 9, 12, 25, 'あなたがたが悪を重ねるなら、あなたがたも、あなたがたの王も滅ぼし尽くされる。」'),
('JPN', '撒母耳记上', 9, 13, 1, 'サウルは、ある年齢で王となり、二年間だけイスラエルを治めた。'),
('JPN', '撒母耳记上', 9, 13, 2, 'サウルは、自分のためにイスラエルから三千人を選んだ。二千人はサウルとともにミクマスとベテルの山地にいて、千人はヨナタンとともにベニヤミンのギブアにいた。残りの兵は、それぞれ自分の天幕に帰した。'),
('JPN', '撒母耳记上', 9, 13, 3, 'ヨナタンは、ゲバにいたペリシテ人の守備隊長を打ち殺した。サウルのほうは国中に角笛を吹き鳴らした。ペリシテ人たちは、だれかが「ヘブル人に思い知らせてやろう」と言うのを聞いた。'),
('JPN', '撒母耳记上', 9, 13, 4, '全イスラエルは、「サウルがペリシテ人の守備隊長を打ち殺し、しかも、イスラエルがペリシテ人の恨みを買った」ということを聞いた。兵はギルガルでサウルのもとに呼び集められた。'),
('JPN', '撒母耳记上', 9, 13, 5, 'ペリシテ人はイスラエル人と戦うために集まった。戦車三万、騎兵六千、それに海辺の砂のように数多くの兵たちであった。彼らは上って来て、ベテ・アベンの東、ミクマスに陣を敷いた。'),
('JPN', '撒母耳记上', 9, 13, 6, 'イスラエルの人々は、自分たちが危険なのを見てとった。兵たちがひどく追いつめられていたからである。兵たちは洞穴や、奥まったところ、岩間、地下室、水溜めの中に隠れた。'),
('JPN', '撒母耳记上', 9, 13, 7, 'あるヘブル人たちはヨルダン川を渡って、ガドの地、すなわちギルアデに行った。しかしサウルはなおギルガルにとどまり、兵たちはみな震えながら彼に従っていた。'),
('JPN', '撒母耳记上', 9, 13, 8, 'サウルは、サムエルがいることになっている例祭まで、七日間待ったが、サムエルはギルガルに来なかった。それで、兵たちはサウルから離れて散って行こうとした。'),
('JPN', '撒母耳记上', 9, 13, 9, 'サウルは、「全焼のささげ物と交わりのいけにえを私のところに持って来なさい」と言った。そして全焼のささげ物を献げた。'),
('JPN', '撒母耳记上', 9, 13, 10, '彼が全焼のささげ物を献げ終えたとき、なんと、サムエルが来た。サウルは迎えに出て、彼にあいさつした。'),
('JPN', '撒母耳记上', 9, 13, 11, 'サムエルは言った。「あなたは、何ということをしたのか。」サウルは答えた。「兵たちが私から離れて散って行こうとしていて、また、ペリシテ人がミクマスに集まっていたのに、あなたが毎年の例祭に来ていないのを見たからです。'),
('JPN', '撒母耳记上', 9, 13, 12, '今、ペリシテ人がギルガルにいる私に向かって下って来ようとしているのに、まだ私は主に嘆願していないと考え、あえて、全焼のささげ物を献げたのです。」'),
('JPN', '撒母耳记上', 9, 13, 13, 'サムエルはサウルに言った。「愚かなことをしたものだ。あなたは、あなたの神、主が命じた命令を守らなかった。主は今、イスラエルにあなたの王国を永遠に確立されたであろうに。'),
('JPN', '撒母耳记上', 9, 13, 14, 'しかし、今や、あなたの王国は立たない。主はご自分の心にかなう人を求め、主はその人をご自分の民の君主に任命しておられる。主があなたに命じられたことを、あなたが守らなかったからだ。」'),
('JPN', '撒母耳记上', 9, 13, 15, 'サムエルは立って、ギルガルからベニヤミンのギブアへ上って行った。サウルが彼とともにいた兵を数えると、おおよそ六百人であった。'),
('JPN', '撒母耳记上', 9, 13, 16, 'サウルと、息子ヨナタン、および彼らとともにいた兵は、ベニヤミンのゲバにとどまっていた。一方、ペリシテ人はミクマスに陣を敷いていた。'),
('JPN', '撒母耳记上', 9, 13, 17, 'ペリシテ人の陣営から、三つの組に分かれて略奪隊が出て来た。一つの組はオフラの道を進んでシュアルの地に向かい、'),
('JPN', '撒母耳记上', 9, 13, 18, '一つの組はベテ・ホロンの道を進み、一つの組は荒野の方、ツェボイムの谷を見下ろす国境の道を進んだ。'),
('JPN', '撒母耳记上', 9, 13, 19, 'さて、イスラエルの地には、どこにも鍛冶屋を見つけることができなかった。ヘブル人が剣や槍を作るといけない、とペリシテ人が言っていたからであった。'),
('JPN', '撒母耳记上', 9, 13, 20, 'イスラエルはみな、鋤や、鍬、斧、鎌を研ぐためにペリシテ人のところへ下って行っていた。'),
('JPN', '撒母耳记上', 9, 13, 21, '鎌や、鍬、三又の矛、斧、突き棒を直すのに、料金は一ピムであった。'),
('JPN', '撒母耳记上', 9, 13, 22, '戦いの日に、サウルやヨナタンと一緒にいた兵のうちだれの手にも、剣や槍はなかった。ただサウルと息子ヨナタンだけが持っていた。'),
('JPN', '撒母耳记上', 9, 13, 23, 'ペリシテ人の先陣はミクマスの渡りに出た。'),
('JPN', '撒母耳记上', 9, 14, 1, 'そのようなある日、サウルの息子ヨナタンは、道具持ちの若者に言った。「さあ、この向こう側のペリシテ人の先陣の方へ行こう。」しかし、ヨナタンは父にそのことを知らせなかった。'),
('JPN', '撒母耳记上', 9, 14, 2, 'サウルはギブアの外れで、ミグロンにある、ざくろの木の下に座っていた。彼とともにいた兵は約六百人であった。'),
('JPN', '撒母耳记上', 9, 14, 3, 'アヒヤは、エポデを身に着けていた。アヒヤはアヒトブの子で、アヒトブはイ・カボデの兄弟、イ・カボデはピネハスの子、ピネハスは、シロで主の祭司であったエリの子である。兵たちは、ヨナタンが出て行ったことを知らなかった。'),
('JPN', '撒母耳记上', 9, 14, 4, 'ヨナタンがペリシテ人の先陣の側に越えて行こうとしていた山峡には、手前側にも、向こう側にも、切り立った岩があって、一方の側の名はボツェツ、もう一方の側の名はセンネといった。'),
('JPN', '撒母耳记上', 9, 14, 5, '一方の岩は北側、ミクマスの側にあり、もう一方の岩は南側、ゲバの側にそそり立っていた。'),
('JPN', '撒母耳记上', 9, 14, 6, 'ヨナタンは道具持ちの若者に言った。「さあ、この無割礼の者どもの先陣のところへ渡って行こう。おそらく、主がわれわれに味方してくださるだろう。多くの人によっても、少しの人によっても、主がお救いになるのを妨げるものは何もない。」'),
('JPN', '撒母耳记上', 9, 14, 7, '道具持ちは言った。「何でも、お心のままになさってください。さあ、お進みください。私も一緒に参ります。お心のままに。」'),
('JPN', '撒母耳记上', 9, 14, 8, 'ヨナタンは言った。「さあ、あの者どものところに渡って行って、われわれの姿を現すのだ。'),
('JPN', '撒母耳记上', 9, 14, 9, 'もし彼らが『おれたちがおまえらのところに行くまで、じっとしていろ』と言ったら、その場に立ちとどまり、彼らのところに上って行かないでいよう。'),
('JPN', '撒母耳记上', 9, 14, 10, 'しかし、もし彼らが『おれたちのところに上って来い』と言ったら、上って行こう。主が彼らを、われわれの手に渡されたのだから。これが、われわれへのしるしだ。」'),
('JPN', '撒母耳记上', 9, 14, 11, '二人はペリシテ人の先陣に身を現した。するとペリシテ人が言った。「おい、ヘブル人が、隠れていた穴から出て来るぞ。」'),
('JPN', '撒母耳记上', 9, 14, 12, '先陣の者たちは、ヨナタンと道具持ちに呼びかけて言った。「おれたちのところに上って来い。思い知らせてやる。」ヨナタンは道具持ちに言った。「私について上って来なさい。主がイスラエルの手に彼らを渡されたのだ。」'),
('JPN', '撒母耳记上', 9, 14, 13, 'ヨナタンは手足を使ってよじ登り、道具持ちも後に続いた。ペリシテ人はヨナタンの前に倒れ、道具持ちがうしろで彼らを打ち殺した。'),
('JPN', '撒母耳记上', 9, 14, 14, 'ヨナタンと道具持ちが最初に討ち取ったのは約二十人で、一ツェメドのおおよそ半分の広さの場所で行われた。'),
('JPN', '撒母耳记上', 9, 14, 15, 'そして陣営にも野にも、すべての兵のうちに恐れが起こった。先陣の者、略奪隊さえ恐れおののいた。地は震え、非常な恐れとなった。'),
('JPN', '撒母耳记上', 9, 14, 16, 'ベニヤミンのギブアでサウルのために見張りをしていた者たちが見ると、大軍は震えおののいて右往左往していた。'),
('JPN', '撒母耳记上', 9, 14, 17, 'サウルは彼とともにいる兵に言った。「だれがわれわれのところから出て行ったかを、点呼して調べなさい。」彼らが点呼すると、ヨナタンと道具持ちがいなかった。'),
('JPN', '撒母耳记上', 9, 14, 18, 'サウルはアヒヤに言った。「神の箱を持って来なさい。」神の箱は、そのころ、イスラエル人の間にあったからである。'),
('JPN', '撒母耳记上', 9, 14, 19, 'サウルが祭司とまだ話している間に、ペリシテ人の陣営の騒動は、ますます大きくなっていった。サウルは祭司に「手を戻しなさい」と言った。'),
('JPN', '撒母耳记上', 9, 14, 20, 'サウルと、彼とともにいた兵がみな集まって戦場に行くと、そこでは剣をもって同士討ちをしていて、非常に大きな混乱が起こっていた。'),
('JPN', '撒母耳记上', 9, 14, 21, 'それまでペリシテ人について、彼らと一緒に陣営に上って来ていたヘブル人も転じて、サウルとヨナタンとともにいるイスラエル人の側につくようになった。'),
('JPN', '撒母耳记上', 9, 14, 22, 'また、エフライムの山地に隠れていたすべてのイスラエル人も、ペリシテ人が逃げたと聞いて、戦いに加わってペリシテ人に追い迫った。'),
('JPN', '撒母耳记上', 9, 14, 23, 'その日、主はイスラエルを救われた。そして、戦いはベテ・アベンに移った。'),
('JPN', '撒母耳记上', 9, 14, 24, 'さて、その日、イスラエル人はひどく苦しんでいた。サウルは、「夕方、私が敵に復讐するまで、食物を食べる者はのろわれよ」と言って、兵たちに誓わせていた。それで兵たちはだれも食物を口にしていなかったのであった。'),
('JPN', '撒母耳记上', 9, 14, 25, 'この地はどこでも、森に入って行くと、地面に蜜があった。'),
('JPN', '撒母耳记上', 9, 14, 26, '兵たちが森に入ると、なんと、蜜が滴っていたが、だれも手に付けて口に入れる者はいなかった。兵たちは誓いを恐れていたのである。'),
('JPN', '撒母耳记上', 9, 14, 27, 'しかし、ヨナタンは、父が兵たちに誓わせたことを聞いていなかった。彼は手にあった杖の先を伸ばして、蜜蜂の巣に浸し、それを手に付けて口に入れた。すると彼の目が輝いた。'),
('JPN', '撒母耳记上', 9, 14, 28, '兵の一人がそれを見て言った。「あなたの父上は、兵たちに堅く誓わせて、『今日、食物を食べる者はのろわれる』とおっしゃいました。それで兵たちは疲れているのです。」'),
('JPN', '撒母耳记上', 9, 14, 29, 'ヨナタンは言った。「父はこの国を悩ませている。ほら、この蜜を少し口にしたので、私の目は輝いている。'),
('JPN', '撒母耳记上', 9, 14, 30, 'もしも今日、兵たちが、自分たちが見つけた敵からの分捕り物を十分食べていたなら、今ごろは、もっと多くのペリシテ人を討ち取っていただろうに。」'),
('JPN', '撒母耳记上', 9, 14, 31, 'その日彼らは、ミクマスからアヤロンに至るまでペリシテ人を討った。それで兵たちはたいへん疲れていた。'),
('JPN', '撒母耳记上', 9, 14, 32, '兵たちは分捕り物に飛びかかり、羊、牛、若い牛を取り、その場で屠った。兵たちは血が付いたままで、それを食べた。'),
('JPN', '撒母耳记上', 9, 14, 33, 'すると、「ご覧ください。兵たちが血のままで食べて、主に罪を犯しています」と、サウルに告げる者がいた。サウルは言った。「おまえたちは裏切った。今、大きな石を転がして来なさい。」'),
('JPN', '撒母耳记上', 9, 14, 34, 'そしてサウルは言った。「兵の中に散って行って、彼らに言いなさい。『それぞれ自分の牛か羊を私のところに連れて来て、ここで屠って食べなさい。血のままで食べて主に罪を犯してはならない。』」兵はみな、その夜、それぞれ自分の手で牛を連れて来て、そこで屠った。'),
('JPN', '撒母耳记上', 9, 14, 35, 'サウルは主のために祭壇を築いた。これは、彼が主のために築いた最初の祭壇であった。'),
('JPN', '撒母耳记上', 9, 14, 36, 'サウルは言った。「夜、ペリシテ人を追って下り、明け方までに彼らからかすめ奪い、一人も残しておかないようにしよう。」すると兵は言った。「あなたが良いと思うようにしてください。」しかし祭司は言った。「ここで、われわれは神の前に出ましょう。」'),
('JPN', '撒母耳记上', 9, 14, 37, 'サウルは神に伺った。「私はペリシテ人を追って下って行くべきでしょうか。彼らをイスラエルの手に渡してくださるのでしょうか。」しかしその日、神は彼にお答えにならなかった。'),
('JPN', '撒母耳记上', 9, 14, 38, 'サウルは言った。「民のかしらたちはみな、ここに近寄りなさい。今日、どうしてこの罪が起こったのかを確かめてみなさい。'),
('JPN', '撒母耳记上', 9, 14, 39, 'まことに、イスラエルを救う主は生きておられる。たとえ、それが私の息子ヨナタンであっても、必ず死ななければならない。」しかし、民のうちだれも彼に答える者はいなかった。'),
('JPN', '撒母耳记上', 9, 14, 40, 'サウルはすべてのイスラエル人たちに言った。「おまえたちは、こちら側にいなさい。私と息子ヨナタンは、あちら側にいることにしよう。」民はサウルに言った。「あなたが良いと思うようにしてください。」'),
('JPN', '撒母耳记上', 9, 14, 41, 'サウルはイスラエルの神、主に「みこころをお示しください」と言った。すると、ヨナタンとサウルが取り分けられ、民は外れた。'),
('JPN', '撒母耳记上', 9, 14, 42, 'サウルは言った。「私か、私の息子ヨナタンかを決めてください。」するとヨナタンが取り分けられた。'),
('JPN', '撒母耳记上', 9, 14, 43, 'サウルはヨナタンに言った。「何をしたのか、私に話しなさい。」ヨナタンは彼に話した。「確かに、手にあった杖の先で、少しばかりの蜜を口にしました。この私が死ななければなりません。」'),
('JPN', '撒母耳记上', 9, 14, 44, 'サウルは言った。「神が幾重にも罰してくださるように。ヨナタン、おまえは必ず死ななければならない。」'),
('JPN', '撒母耳记上', 9, 14, 45, '民はサウルに言った。「この大勝利をイスラエルにもたらしたヨナタンが死ななければならないのですか。絶対にそんなことはあり得ません。主は生きておられます。あの方の髪の毛一本でも地に落ちてはなりません。今日、あの方は神とともにこれをなさったのです。」こうして民がヨナタンを救ったので、彼は死ななかった。'),
('JPN', '撒母耳记上', 9, 14, 46, 'サウルはペリシテ人を追うのをやめて引き揚げ、ペリシテ人は自分たちのところへ帰って行った。'),
('JPN', '撒母耳记上', 9, 14, 47, 'さてサウルは、イスラエルの王権を握ってから、周囲のすべての敵と戦った。モアブ、アンモン人、エドム、ツォバの王たち、ペリシテ人と戦い、どこに行っても彼らを敗走させた。'),
('JPN', '撒母耳记上', 9, 14, 48, '彼は勇気を奮って、アマレク人を討ち、イスラエル人を略奪者の手から救い出した。'),
('JPN', '撒母耳记上', 9, 14, 49, 'さて、サウルの息子は、ヨナタン、イシュウィ、マルキ・シュア、二人の娘の名は、姉がメラブ、妹がミカルであった。'),
('JPN', '撒母耳记上', 9, 14, 50, 'サウルの妻の名はアヒノアムで、アヒマアツの娘であった。軍の長の名はアブネルで、ネルの子でサウルのおじであった。'),
('JPN', '撒母耳记上', 9, 14, 51, 'キシュはサウルの父であり、アブネルの父ネルは、アビエルの子であった。'),
('JPN', '撒母耳记上', 9, 14, 52, 'サウルの一生の間、ペリシテ人との激しい戦いがあった。サウルは勇気のある者や、力のある者を見つけると、その人たちをみな、召しかかえることにしていた。'),
('JPN', '撒母耳记上', 9, 15, 1, 'サムエルはサウルに言った。「主は私を遣わして、あなたに油を注ぎ、主の民イスラエルの王とされた。今、主の言われることを聞きなさい。'),
('JPN', '撒母耳记上', 9, 15, 2, '万軍の主はこう言われる。『わたしは、イスラエルがエジプトから上って来る途中で、アマレクがイスラエルに対して行ったことを覚えている。'),
('JPN', '撒母耳记上', 9, 15, 3, '今、行ってアマレクを討ち、そのすべてのものを聖絶しなさい。容赦してはならない。男も女も、幼子も乳飲み子も、牛も羊も、らくだもろばも殺しなさい。』」'),
('JPN', '撒母耳记上', 9, 15, 4, 'サウルは兵を呼び集めた。テライムで彼らを数えると、歩兵が二十万、ユダの兵が一万であった。'),
('JPN', '撒母耳记上', 9, 15, 5, 'サウルはアマレクの町へ行って、谷で待ち伏せした。'),
('JPN', '撒母耳记上', 9, 15, 6, 'サウルはケニ人たちに言った。「さあ、アマレク人のもとを離れて下って行きなさい。私があなたがたを彼らと一緒にするといけないから。あなたがたは、イスラエル人がみなエジプトから上って来たとき、親切にしてくれたのです。」ケニ人はアマレク人の中から離れた。'),
('JPN', '撒母耳记上', 9, 15, 7, 'サウルは、ハビラからエジプトの国境にあるシュルに至るまで、アマレク人を討ち、'),
('JPN', '撒母耳记上', 9, 15, 8, 'アマレク人の王アガグを生け捕りにし、その民のすべてを剣の刃で聖絶した。'),
('JPN', '撒母耳记上', 9, 15, 9, 'サウルとその兵たちは、アガグと、肥えた羊や牛の最も良いもの、子羊とすべての最も良いものを惜しんで、これらを聖絶しようとしなかった。ただ、つまらない値打ちのないものだけを聖絶したのである。'),
('JPN', '撒母耳记上', 9, 15, 10, '主のことばがサムエルに臨んだ。'),
('JPN', '撒母耳记上', 9, 15, 11, '「わたしはサウルを王に任じたことを悔やむ。彼はわたしに背を向け、わたしのことばを守らなかったからだ。」それでサムエルは怒り、夜通し主に向かって叫んだ。'),
('JPN', '撒母耳记上', 9, 15, 12, '翌朝、サムエルはサウルに会いに行こうとして早く起きた。すると、サムエルに、「サウルはカルメルに来て、もう自分のために記念碑を立てました。そして向きを変えて進んで行き、ギルガルに下りました」という知らせがあった。'),
('JPN', '撒母耳记上', 9, 15, 13, 'サムエルはサウルのところに来た。サウルは彼に言った。「あなたが主に祝福されますように。私は主のことばを守りました。」'),
('JPN', '撒母耳记上', 9, 15, 14, 'サムエルは言った。「では、私の耳に入るこの羊の声、私に聞こえる牛の声は、いったい何ですか。」'),
('JPN', '撒母耳记上', 9, 15, 15, 'サウルは答えた。「アマレク人のところから連れて来ました。兵たちは、あなたの神、主に、いけにえを献げるために、羊と牛の最も良いものを惜しんだのです。しかし、残りの物は聖絶しました。」'),
('JPN', '撒母耳记上', 9, 15, 16, 'サムエルはサウルに言った。「やめなさい。昨夜、主が私に言われたことをあなたに知らせます。」サウルは彼に言った。「お話しください。」'),
('JPN', '撒母耳记上', 9, 15, 17, 'サムエルは言った。「あなたは、自分の目には小さい者であっても、イスラエルの諸部族のかしらではありませんか。主があなたに油を注ぎ、イスラエルの王とされたのです。'),
('JPN', '撒母耳记上', 9, 15, 18, '主はあなたに使命を与えて言われました。『行って、罪人アマレク人を聖絶せよ。彼らを絶滅させるまで戦え。』'),
('JPN', '撒母耳记上', 9, 15, 19, 'なぜ、あなたは主の御声に聞き従わず、分捕り物に飛びかかり、主の目に悪であることを行ったのですか。」'),
('JPN', '撒母耳记上', 9, 15, 20, 'サウルはサムエルに答えた。「私は、主の御声に聞き従い、主が私に授けられた使命の道を進みました。私はアマレク人の王アガグを連れて来て、アマレク人たちは聖絶しました。'),
('JPN', '撒母耳记上', 9, 15, 21, '兵たちは、ギルガルであなたの神、主にいけにえを献げるために、聖絶の物の中の最上のものとして、分捕り物の中から羊と牛を取ったのです。」'),
('JPN', '撒母耳记上', 9, 15, 22, 'サムエルは言った。「主は、全焼のささげ物やいけにえを、主の御声に聞き従うことほどに喜ばれるだろうか。見よ。聞き従うことは、いけにえにまさり、耳を傾けることは、雄羊の脂肪にまさる。'),
('JPN', '撒母耳记上', 9, 15, 23, '従わないことは占いの罪、高慢は偶像礼拝の悪。あなたが主のことばを退けたので、主もあなたを王位から退けた。」'),
('JPN', '撒母耳记上', 9, 15, 24, 'サウルはサムエルに言った。「私は罪を犯しました。兵たちを恐れて、彼らの声に聞き従い、主の命令と、あなたのことばに背いたからです。'),
('JPN', '撒母耳记上', 9, 15, 25, 'どうか今、私の罪を見逃してください。そして、私が主を礼拝することができるように、一緒に帰ってください。」'),
('JPN', '撒母耳记上', 9, 15, 26, 'サムエルはサウルに言った。「私はあなたと一緒に帰りません。あなたは主のことばを退け、主があなたをイスラエルの王位から退けられたからです。」'),
('JPN', '撒母耳记上', 9, 15, 27, 'サムエルが引き返して行こうとしたとき、サウルが彼の上着の裾をつかんだので、上着は裂けた。'),
('JPN', '撒母耳记上', 9, 15, 28, 'サムエルは彼に言った。「主は、今日、あなたからイスラエル王国を引き裂いて、これをあなたよりすぐれた隣人に与えられました。'),
('JPN', '撒母耳记上', 9, 15, 29, '実に、イスラエルの栄光である方は、偽ることもなく、悔やむこともない。この方は人間ではないので、悔やむことがない。」'),
('JPN', '撒母耳记上', 9, 15, 30, 'サウルは言った。「私は罪を犯しました。しかし、どうか今は、私の民の長老とイスラエルとの前で私を立ててください。どうか一緒に帰ってください。私はあなたの神、主を礼拝します。」'),
('JPN', '撒母耳记上', 9, 15, 31, 'サムエルはサウルについて帰り、サウルは主を礼拝した。'),
('JPN', '撒母耳记上', 9, 15, 32, 'サムエルは言った。「アマレクの王アガグを、私のところに連れて来なさい。」アガグは、喜び勇んで彼のもとに来た。アガグは「きっと、死の苦しみが去るだろう」と思ったのであった。'),
('JPN', '撒母耳记上', 9, 15, 33, 'サムエルは言った。「おまえの剣が、女たちから子を奪ったように、おまえの母も、女たちのうちで子を奪われた者となる。」こうしてサムエルは、ギルガルにおいて主の前で、アガグをずたずたに切った。'),
('JPN', '撒母耳记上', 9, 15, 34, 'サムエルはラマへ行き、サウルはサウルのギブアにある自分の家へ上って行った。'),
('JPN', '撒母耳记上', 9, 15, 35, 'サムエルは死ぬ日まで、再びサウルを見ることはなかった。しかしサムエルはサウルのことで悲しんだ。主も、サウルをイスラエルの王としたことを悔やまれた。'),
('JPN', '撒母耳记上', 9, 16, 1, '主はサムエルに言われた。「いつまであなたはサウルのことで悲しんでいるのか。わたしは彼をイスラエルの王位から退けている。角に油を満たせ。さあ、わたしはあなたをベツレヘム人エッサイのところに遣わす。彼の息子たちの中に、わたしのために王を見出したから。」'),
('JPN', '撒母耳记上', 9, 16, 2, 'サムエルは言った。「どうして私が行けるでしょうか。サウルが聞いたら、私を殺すでしょう。」主は言われた。「一頭の雌の子牛を手にし、『主にいけにえを献げるために来ました』と言い、'),
('JPN', '撒母耳记上', 9, 16, 3, 'エッサイを祝宴に招け。わたしが、あなたのなすべきことを教えよう。あなたはわたしのために、わたしが言う人に油を注げ。」'),
('JPN', '撒母耳记上', 9, 16, 4, 'サムエルは主がお告げになったとおりにして、ベツレヘムにやって来た。町の長老たちは身震いしながら彼を迎えて言った。「平和なことでおいでになったのですか。」')
on conflict (version, book, chapter, verse) do nothing;
insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('JPN', '撒母耳记上', 9, 16, 5, 'サムエルは言った。「平和なことです。主にいけにえを献げるために来ました。身を聖別して、一緒に祝宴に来てください。」そして、サムエルはエッサイと彼の息子たちを聖別し、彼らを祝宴に招いた。'),
('JPN', '撒母耳记上', 9, 16, 6, '彼らが来たとき、サムエルはエリアブを見て、「きっと、主の前にいるこの者が、主に油を注がれる者だ」と思った。'),
('JPN', '撒母耳记上', 9, 16, 7, '主はサムエルに言われた。「彼の容貌や背の高さを見てはならない。わたしは彼を退けている。人が見るようには見ないからだ。人はうわべを見るが、主は心を見る。」'),
('JPN', '撒母耳记上', 9, 16, 8, 'エッサイはアビナダブを呼んで、サムエルの前に進ませた。サムエルは「この者も主は選んでおられない」と言った。'),
('JPN', '撒母耳记上', 9, 16, 9, 'エッサイはシャンマを進ませたが、サムエルは「この者も主は選んでおられない」と言った。'),
('JPN', '撒母耳记上', 9, 16, 10, 'エッサイは七人の息子をサムエルの前に進ませたが、サムエルはエッサイに言った。「主はこの者たちを選んでおられない。」'),
('JPN', '撒母耳记上', 9, 16, 11, 'サムエルはエッサイに言った。「子どもたちはこれで全部ですか。」エッサイは言った。「まだ末の子が残っています。今、羊の番をしています。」サムエルはエッサイに言った。「人を遣わして、連れて来なさい。その子が来るまで、私たちはここを離れないから。」'),
('JPN', '撒母耳记上', 9, 16, 12, 'エッサイは人を遣わして、彼を連れて来させた。彼は血色が良く、目が美しく、姿も立派だった。主は言われた。「さあ、彼に油を注げ。この者がその人だ。」'),
('JPN', '撒母耳记上', 9, 16, 13, 'サムエルは油の角を取り、兄弟たちの真ん中で彼に油を注いだ。主の霊がその日以来、ダビデの上に激しく下った。サムエルは立ち上がってラマへ帰って行った。'),
('JPN', '撒母耳记上', 9, 16, 14, 'さて、主の霊はサウルを離れ去り、主からの、わざわいの霊が彼をおびえさせた。'),
('JPN', '撒母耳记上', 9, 16, 15, 'サウルの家来たちは彼に言った。「ご覧ください。わざわいをもたらす、神の霊が王をおびえさせています。'),
('JPN', '撒母耳记上', 9, 16, 16, 'わが君。どうか御前におりますこの家来どもに命じて、上手に竪琴を弾く者を探させてください。わざわいをもたらす、神の霊が王に臨むとき、その者が竪琴を手にして弾くと、王は良くなられるでしょう。」'),
('JPN', '撒母耳记上', 9, 16, 17, 'サウルは家来たちに言った。「私のために上手な弾き手を見つけて、私のところに連れて来なさい。」'),
('JPN', '撒母耳记上', 9, 16, 18, '家来の一人が答えた。「ご覧ください。ベツレヘム人エッサイの息子を見たことがあります。弦を上手に奏でることができ、勇士であり、戦士の出です。物事の判断ができ、体格も良い人です。主が彼とともにおられます。」'),
('JPN', '撒母耳记上', 9, 16, 19, 'サウルは使いをエッサイのところに送って、「羊とともにいるあなたの息子ダビデを、私のところによこしなさい」と言った。'),
('JPN', '撒母耳记上', 9, 16, 20, 'エッサイは、ろば一頭分のパンと、ぶどう酒の皮袋一つ、子やぎ一匹を取り、息子ダビデの手に託してサウルに送った。'),
('JPN', '撒母耳记上', 9, 16, 21, 'ダビデはサウルのもとに来て、彼に仕えた。サウルは彼がたいへん気に入り、ダビデはサウルの道具持ちとなった。'),
('JPN', '撒母耳记上', 9, 16, 22, 'サウルはエッサイのところに人を遣わして、「ダビデを私に仕えさせなさい。気に入ったから」と言った。'),
('JPN', '撒母耳记上', 9, 16, 23, '神の霊がサウルに臨むたびに、ダビデは竪琴を手に取って弾いた。するとサウルは元気を回復して、良くなり、わざわいの霊は彼を離れ去った。'),
('JPN', '撒母耳记上', 9, 17, 1, 'ペリシテ人は戦いのために軍隊を召集した。ユダのソコに集まり、ソコとアゼカの間にあるエフェス・ダミムに陣を敷いた。'),
('JPN', '撒母耳记上', 9, 17, 2, '一方、サウルとイスラエル人は集まってエラの谷に陣を敷き、ペリシテ人に対する戦いの備えをした。'),
('JPN', '撒母耳记上', 9, 17, 3, 'ペリシテ人は向かい側の山の上に構え、イスラエル人は手前側の山の上に構えた。その間には谷があった。'),
('JPN', '撒母耳记上', 9, 17, 4, '一人の代表戦士が、ペリシテ人の陣営から出て来た。その名はゴリヤテ。ガテの生まれで、その背の高さは六キュビト半。'),
('JPN', '撒母耳记上', 9, 17, 5, '頭には青銅のかぶとをかぶり、鱗綴じのよろいを着けていた。胸当ての重さは青銅で五千シェケル。'),
('JPN', '撒母耳记上', 9, 17, 6, '足には青銅のすね当てを着け、背には青銅の投げ槍を負っていた。'),
('JPN', '撒母耳记上', 9, 17, 7, '槍の柄は機織りの巻き棒のようであり、槍の穂先は鉄で、六百シェケルあった。盾持ちが彼の前を歩いていた。'),
('JPN', '撒母耳记上', 9, 17, 8, 'ゴリヤテは突っ立って、イスラエル人の陣列に向かって叫んだ。「何のために、おまえらは出て来て、戦いの備えをするのか。おれはペリシテ人、おまえらはサウルの奴隷どもではないか。一人を選んで、おれのところによこせ。'),
('JPN', '撒母耳记上', 9, 17, 9, 'おれと戦っておれを殺せるなら、おれたちはおまえらの奴隷になる。だが、おれが勝ってそいつを殺したら、おまえらがおれたちの奴隷になって、おれたちに仕えるのだ。」'),
('JPN', '撒母耳记上', 9, 17, 10, 'そのペリシテ人は言った。「今日、この日、おれがイスラエルの陣を愚弄してやる。一人をよこせ。ひとつ勝負をしようではないか。」'),
('JPN', '撒母耳记上', 9, 17, 11, 'サウルと全イスラエルは、ペリシテ人のことばを聞き、気をくじかれて非常に恐れた。'),
('JPN', '撒母耳记上', 9, 17, 12, 'さて、ダビデは、ユダのベツレヘム出身の、エッサイという名のエフラテ人の息子であった。エッサイには八人の息子がいた。この人はサウルの時代には、年をとって老人になっていた。'),
('JPN', '撒母耳记上', 9, 17, 13, 'エッサイの上の三人の息子たちは、サウルに従って戦いに出ていた。戦いに行っていた三人の息子の名は、長男エリアブ、次男アビナダブ、三男シャンマであった。'),
('JPN', '撒母耳记上', 9, 17, 14, 'ダビデは末っ子で、上の三人がサウルに従って出ていたのである。'),
('JPN', '撒母耳记上', 9, 17, 15, 'ダビデは、サウルのところへ行ったり、帰ったりしていた。ベツレヘムの父の羊を世話するためであった。'),
('JPN', '撒母耳记上', 9, 17, 16, '例のペリシテ人は、四十日間、朝早くと夕暮れに出て来て立ち構えた。'),
('JPN', '撒母耳记上', 9, 17, 17, 'エッサイは息子ダビデに言った。「さあ、兄さんたちのために、この炒り麦一エパと、このパン十個を取り、兄さんたちの陣営に急いで持って行きなさい。'),
('JPN', '撒母耳记上', 9, 17, 18, 'この十個のチーズは千人隊の長に届け、兄さんたちの安否を確認しなさい。そして、しるしを持って来なさい。'),
('JPN', '撒母耳记上', 9, 17, 19, 'サウルと兄さんたち、それにイスラエルの人はみな、エラの谷でペリシテ人と戦っているから。」'),
('JPN', '撒母耳记上', 9, 17, 20, 'ダビデは翌朝早く、羊を番人に預け、エッサイが命じたとおりに、言われた物を持って出かけた。彼が野営地に来ると、軍勢はときの声をあげて陣地に向かうところであった。'),
('JPN', '撒母耳记上', 9, 17, 21, 'イスラエル人とペリシテ人は、向かい合って陣を敷いていた。'),
('JPN', '撒母耳记上', 9, 17, 22, 'ダビデは、父からことづかった物を武器を守る者に預け、陣地に走って来て、兄たちに安否を尋ねた。'),
('JPN', '撒母耳记上', 9, 17, 23, 'ダビデが彼らと話していると、なんと、そのとき、あの代表戦士が、ペリシテ人の陣地から上って来た。ガテ出身のゴリヤテという名のペリシテ人であった。彼は前と同じことを語った。ダビデはこれを聞いた。'),
('JPN', '撒母耳记上', 9, 17, 24, 'イスラエルの人はみな、この男を見たとき、彼の前から逃げ、非常に恐れた。'),
('JPN', '撒母耳记上', 9, 17, 25, 'イスラエルの人々は言った。「この上って来た男を見たか。イスラエルをそしるために上って来たのだ。あれを討ち取る者がいれば、王はその人を大いに富ませ、その人に自分の娘を与え、その父の家にイスラエルでは何も義務を負わせないそうだ。」'),
('JPN', '撒母耳记上', 9, 17, 26, 'ダビデは、そばに立っている人たちに言った。「このペリシテ人を討ち取って、イスラエルの恥辱を取り除く者には、どうされるのですか。この無割礼のペリシテ人は何なのですか。生ける神の陣をそしるとは。」'),
('JPN', '撒母耳记上', 9, 17, 27, '兵たちは、先のことばのように、彼を討ち取った者には、これこれをされる、と言った。'),
('JPN', '撒母耳记上', 9, 17, 28, '兄のエリアブは、ダビデが人々と話しているのを聞いた。エリアブはダビデに怒りを燃やして言った。「いったい、おまえは、なぜやって来たのか。荒野にいるあのわずかな羊を、だれに預けて来たのか。私には、おまえのうぬぼれと心にある悪が分かっている。戦いを見にやって来たのではないのか。」'),
('JPN', '撒母耳记上', 9, 17, 29, 'ダビデは言った。「私が今、何をしたというのですか。一言、話しただけではありませんか。」'),
('JPN', '撒母耳记上', 9, 17, 30, 'ダビデは兄から別の人の方に向き直り、同じことを尋ねた。すると、兵たちは先ほどと同じ返事をした。'),
('JPN', '撒母耳记上', 9, 17, 31, 'ダビデが言ったことは人々の耳に入り、サウルに告げられた。それで、サウルはダビデを呼び寄せた。'),
('JPN', '撒母耳记上', 9, 17, 32, 'ダビデはサウルに言った。「あの男のために、だれも気を落としてはなりません。このしもべが行って、あのペリシテ人と戦います。」'),
('JPN', '撒母耳记上', 9, 17, 33, 'サウルはダビデに言った。「おまえは、あのペリシテ人のところへ行って、あれと戦うことはできない。おまえはまだ若いし、あれは若いときから戦士だったのだから。」'),
('JPN', '撒母耳记上', 9, 17, 34, 'ダビデはサウルに言った。「しもべは、父のために羊の群れを飼ってきました。獅子や熊が来て、群れの羊を取って行くと、'),
('JPN', '撒母耳记上', 9, 17, 35, 'しもべはその後を追って出て、それを打ち殺し、その口から羊を救い出します。それがしもべに襲いかかるようなときは、そのひげをつかみ、それを打って殺してしまいます。'),
('JPN', '撒母耳记上', 9, 17, 36, 'しもべは、獅子でも熊でも打ち殺しました。この無割礼のペリシテ人も、これらの獣の一匹のようになるでしょう。生ける神の陣をそしったのですから。」'),
('JPN', '撒母耳记上', 9, 17, 37, 'そして、ダビデは言った。「獅子や熊の爪からしもべを救い出してくださった主は、このペリシテ人の手からも私を救い出してくださいます。」サウルはダビデに言った。「行きなさい。主がおまえとともにいてくださるように。」'),
('JPN', '撒母耳记上', 9, 17, 38, 'サウルはダビデに自分のよろいかぶとを着けさせた。頭に青銅のかぶとをかぶらせて、それから身によろいを着けさせたのである。'),
('JPN', '撒母耳记上', 9, 17, 39, 'ダビデは、そのよろいの上にサウルの剣を帯びた。慣れていなかったので、ためしに歩いてみた。ダビデはサウルに言った。「これらのものを着けては、歩くこともできません。慣れていませんから。」ダビデはそれを脱いだ。'),
('JPN', '撒母耳记上', 9, 17, 40, 'そして自分の杖を手に取り、川から五つの滑らかな石を選んで、それを羊飼いの使う袋、投石袋に入れ、石投げを手にし、そのペリシテ人に近づいて行った。'),
('JPN', '撒母耳记上', 9, 17, 41, 'そのペリシテ人は盾持ちを前に立て、ダビデの方にじりじりと進んで来た。'),
('JPN', '撒母耳记上', 9, 17, 42, 'ペリシテ人は、ダビデに目を留めて彼を見つめ、彼を蔑んだ。ダビデが血色の良い、姿の美しい少年だったからである。'),
('JPN', '撒母耳记上', 9, 17, 43, 'ペリシテ人はダビデに言った。「おれは犬か。杖を持って向かって来るとは。」ペリシテ人は自分の神々によってダビデを呪った。'),
('JPN', '撒母耳记上', 9, 17, 44, 'ペリシテ人はダビデに言った。「さあ、来い。おまえの肉を空の鳥や野の獣にくれてやろう。」'),
('JPN', '撒母耳记上', 9, 17, 45, 'ダビデはペリシテ人に言った。「おまえは、剣と槍と投げ槍を持って私に向かって来るが、私は、おまえがそしったイスラエルの戦陣の神、万軍の主の御名によって、おまえに立ち向かう。'),
('JPN', '撒母耳记上', 9, 17, 46, '今日、主はおまえを私の手に渡される。私はおまえを殺しておまえの頭を胴体から離し、今日、ペリシテ人の軍勢の屍を、空の鳥、地の獣に与えてやる。すべての国は、イスラエルに神がおられることを知るだろう。'),
('JPN', '撒母耳记上', 9, 17, 47, 'ここに集まっているすべての者も、剣や槍がなくても、主が救いをもたらすことを知るだろう。この戦いは主の戦いだ。主は、おまえたちをわれわれの手に渡される。」'),
('JPN', '撒母耳记上', 9, 17, 48, 'そのとき、そのペリシテ人はダビデの方に近づき始めた。ダビデは、すばやく戦場を走って行き、ペリシテ人に立ち向かった。'),
('JPN', '撒母耳记上', 9, 17, 49, 'ダビデは手を袋の中に入れて、石を一つ取り、石投げでそれを放って、ペリシテ人の額を撃った。石は額に食い込み、彼はうつぶせに地面に倒れた。'),
('JPN', '撒母耳记上', 9, 17, 50, 'ダビデは、石投げと石一つでこのペリシテ人に勝ち、このペリシテ人を撃って、彼を殺した。ダビデの手に剣はなかったが。'),
('JPN', '撒母耳记上', 9, 17, 51, 'ダビデは走って行ってペリシテ人の上に立ち、彼の剣を奪ってさやから抜き、とどめを刺して首をはねた。ペリシテ人たちは、自分たちの勇士が死んだのを見て逃げた。'),
('JPN', '撒母耳记上', 9, 17, 52, 'イスラエルとユダの人々は立ち上がり、ときの声をあげて、ペリシテ人をガイの谷間に至るまで、そしてエクロンの門まで追った。それでペリシテ人は、シャアライムの道に、ガテとエクロンに至るまで、刺し殺されて倒れていた。'),
('JPN', '撒母耳记上', 9, 17, 53, 'イスラエル人はペリシテ人追撃から引き返して、ペリシテ人の陣営を略奪した。'),
('JPN', '撒母耳记上', 9, 17, 54, 'ダビデは、あのペリシテ人の首を取ってエルサレムに持ち帰った。しかし、武具は自分の天幕に置いた。'),
('JPN', '撒母耳记上', 9, 17, 55, 'サウルは、ダビデがあのペリシテ人に向かって出て行くのを見たとき、軍の長アブネルに言った。「アブネル、あの若者はだれの息子か。」アブネルは言った。「王様、お誓いしますが、私は存じません。」'),
('JPN', '撒母耳记上', 9, 17, 56, 'そこで、王は命じた。「あなたは、あの少年がだれの息子かを調べなさい。」'),
('JPN', '撒母耳记上', 9, 17, 57, 'ダビデがペリシテ人を討ち取って帰って来たとき、アブネルは彼をサウルの前に連れて来た。ダビデはペリシテ人の首を手にしていた。'),
('JPN', '撒母耳记上', 9, 17, 58, 'サウルは彼に言った。「若者よ、おまえはだれの息子か。」ダビデは言った。「あなたのしもべ、ベツレヘム人エッサイの息子です。」'),
('JPN', '撒母耳记上', 9, 18, 1, 'ダビデがサウルと語り終えたとき、ヨナタンの心はダビデの心に結びついた。ヨナタンは、自分自身のようにダビデを愛した。'),
('JPN', '撒母耳记上', 9, 18, 2, 'サウルはその日、ダビデを召しかかえ、父の家に帰らせなかった。'),
('JPN', '撒母耳记上', 9, 18, 3, 'ヨナタンは、自分自身のようにダビデを愛したので、ダビデと契約を結んだ。'),
('JPN', '撒母耳记上', 9, 18, 4, 'ヨナタンは着ていた上着を脱いで、それをダビデに与え、自分のよろいかぶと、さらに剣、弓、帯までも彼に与えた。'),
('JPN', '撒母耳记上', 9, 18, 5, 'ダビデは、サウルが遣わすところどこへでも出て行き、勝利を収めた。サウルは彼を戦士たちの長とした。このことは、すべての兵たちにも、サウルの家来たちにも喜ばれた。'),
('JPN', '撒母耳记上', 9, 18, 6, '皆が戻り、ダビデがあのペリシテ人を討ち取って帰って来たとき、女たちは、イスラエルのすべての町から、タンバリンや三弦の琴をもって、喜びつつ、歌い踊りながら出て来て、サウル王を迎えた。'),
('JPN', '撒母耳记上', 9, 18, 7, '女たちは、笑いながら歌い交わした。「サウルは千を討ち、ダビデは万を討った。」'),
('JPN', '撒母耳记上', 9, 18, 8, 'サウルは、このことばを聞いて激しく怒り、不機嫌になって言った。「ダビデには万と言い、私には千と言う。あれにないのは王位だけだ。」'),
('JPN', '撒母耳记上', 9, 18, 9, 'その日以来、サウルはダビデに目をつけるようになった。'),
('JPN', '撒母耳记上', 9, 18, 10, 'その翌日、わざわいをもたらす、神の霊がサウルに激しく下り、彼は家の中で狂いわめいた。ダビデはいつものように竪琴を手にして弾いたが、サウルの手には槍があった。'),
('JPN', '撒母耳记上', 9, 18, 11, 'サウルは槍を投げつけた。ダビデを壁に突き刺してやろうと思ったのである。ダビデはサウルの攻撃から二度も身をかわした。'),
('JPN', '撒母耳记上', 9, 18, 12, 'サウルはダビデを恐れた。それは、主がダビデとともにおられ、サウルを離れ去られたからである。'),
('JPN', '撒母耳记上', 9, 18, 13, 'サウルはダビデを自分のもとから離し、彼を千人隊の長にした。ダビデは兵の先に立って行動した。'),
('JPN', '撒母耳记上', 9, 18, 14, '主が彼とともにおられたので、ダビデは、行くところどこででも勝利を収めた。'),
('JPN', '撒母耳记上', 9, 18, 15, '彼が大勝利を収めるのを見て、サウルは彼を恐れた。'),
('JPN', '撒母耳记上', 9, 18, 16, 'イスラエルもユダも、皆がダビデを愛した。彼が彼らの先に立って行動したからである。'),
('JPN', '撒母耳记上', 9, 18, 17, 'サウルはダビデに言った。「これは、私の上の娘メラブだ。これをおまえの妻として与えよう。ただ、私のために勇敢にふるまい、主の戦いを戦ってくれ。」サウルは、自分の手を下さないで、ペリシテ人に手を下させよう、と思ったのである。'),
('JPN', '撒母耳记上', 9, 18, 18, 'ダビデはサウルに言った。「私は何者なのでしょう。私の家族、私の父の氏族もイスラエルでは何者なのでしょう。私が王の婿になるとは。」'),
('JPN', '撒母耳记上', 9, 18, 19, 'ところが、サウルの娘メラブをダビデに与えるというときになって、彼女はメホラ人のアデリエルに妻として与えられた。'),
('JPN', '撒母耳记上', 9, 18, 20, 'サウルの娘ミカルはダビデを愛していた。そのことがサウルに告げられた。そのことは、サウルの目には良いことに思えた。'),
('JPN', '撒母耳记上', 9, 18, 21, 'サウルは、「ミカルを彼にやろう。ミカルは彼にとって罠となり、ペリシテ人の手が彼に下るだろう」と思った。そして、サウルはもう一度ダビデに言った。「今日こそ、おまえは婿になるのだ。」'),
('JPN', '撒母耳记上', 9, 18, 22, 'サウルは家来たちに命じた。「ダビデにひそかにこう告げなさい。『ご覧ください。王はあなたが気に入り、家来たちもみな、あなたを愛しています。今、王の婿になってください。』」'),
('JPN', '撒母耳记上', 9, 18, 23, 'サウルの家来たちは、このことばをダビデの耳に入れた。ダビデは言った。「王の婿になるのがたやすいことに見えるのか。私は貧しく、身分の低い者だ。」'),
('JPN', '撒母耳记上', 9, 18, 24, 'サウルの家来たちは、ダビデがこのように言っています、と言ってサウルに報告した。'),
('JPN', '撒母耳记上', 9, 18, 25, 'サウルは言った。「ダビデにこう言うがよい。王は花嫁料を望んではいない。ただ王の敵に復讐するため、ペリシテ人の陽の皮百だけを望んでいると。」サウルは、ダビデをペリシテ人の手で倒そうと考えていた。'),
('JPN', '撒母耳记上', 9, 18, 26, 'サウルの家来たちはこのことばをダビデに告げた。王の婿になることは、ダビデの目には良いことに思えた。そこで、期限が過ぎる前に、'),
('JPN', '撒母耳记上', 9, 18, 27, 'ダビデは立って、部下と出て行き、ペリシテ人二百人を討って、その陽の皮を持ち帰った。こうしてダビデは、王の婿になるために、王に対して約束を果たした。サウルは娘ミカルを妻としてダビデに与えた。'),
('JPN', '撒母耳记上', 9, 18, 28, 'サウルは、主がダビデとともにおられ、サウルの娘ミカルがダビデを愛していることを見、また知った。'),
('JPN', '撒母耳记上', 9, 18, 29, 'サウルは、ますますダビデを恐れた。サウルはずっと、ダビデの敵となった。'),
('JPN', '撒母耳记上', 9, 18, 30, 'ペリシテ人の首長たちが出陣して来たが、彼らが出て来るたびに、ダビデはサウルの家来たちのすべてにまさる戦果をあげ、彼の名は大いに尊ばれた。'),
('JPN', '撒母耳记上', 9, 19, 1, 'サウルは、ダビデを殺すと、息子ヨナタンやすべての家来に告げた。しかし、サウルの息子ヨナタンはダビデを非常に愛していた。'),
('JPN', '撒母耳记上', 9, 19, 2, 'ヨナタンはダビデに告げた。「父サウルは、あなたを殺そうとしています。明日の朝は注意してください。隠れ場にとどまり、身を隠していてください。'),
('JPN', '撒母耳记上', 9, 19, 3, '私はあなたのいる野に出て行って、父のそばに立ち、あなたのことを父に話します。何か分かったら、あなたに知らせます。」'),
('JPN', '撒母耳记上', 9, 19, 4, 'ヨナタンはダビデを弁護し、父サウルに言った。「王よ、しもべダビデのことで罪を犯さないでください。彼はあなたに対して罪を犯してはいません。むしろ、彼のしたことは、あなたにとって大きな益となっています。'),
('JPN', '撒母耳记上', 9, 19, 5, '彼が自分のいのちをかけてペリシテ人を討ったので、主は大きな勝利をイスラエル全体にもたらしてくださったのです。あなたはそれを見て喜ばれました。なぜ、何の理由もなくダビデを殺し、咎のない者の血を流して、罪ある者となられるのですか。」'),
('JPN', '撒母耳记上', 9, 19, 6, 'サウルはヨナタンの言うことを聞き入れた。サウルは誓った。「主は生きておられる。あれは殺されることはない。」'),
('JPN', '撒母耳记上', 9, 19, 7, 'ヨナタンはダビデを呼んで、このことすべてを告げた。ヨナタンがダビデをサウルのところに連れて来たので、ダビデは以前のようにサウルに仕えることになった。'),
('JPN', '撒母耳记上', 9, 19, 8, '再び戦いが起こった。ダビデは出て行って、ペリシテ人と戦い、彼らを討って大損害を与えた。彼らはダビデの前から逃げた。'),
('JPN', '撒母耳记上', 9, 19, 9, 'わざわいをもたらす、主の霊がサウルに臨んだ。サウルは自分の家で座っていて、手には槍を持っていた。ダビデは竪琴を手にして弾いていた。'),
('JPN', '撒母耳记上', 9, 19, 10, 'サウルは槍でダビデを壁に突き刺そうとした。ダビデがサウルから身を避けたので、サウルは槍を壁に打ちつけた。ダビデは逃げ、その夜は難を逃れた。'),
('JPN', '撒母耳记上', 9, 19, 11, 'サウルはダビデの家に使者たちを遣わし、彼を見張らせ、朝に彼を殺そうとした。ダビデの妻ミカルはダビデに告げた。「今夜、自分のいのちを救わなければ、明日、あなたは殺されてしまいます。」'),
('JPN', '撒母耳记上', 9, 19, 12, 'そして、ミカルはダビデを窓から降ろし、彼は逃げて難を逃れた。'),
('JPN', '撒母耳记上', 9, 19, 13, 'ミカルはテラフィムを取って、寝床の上に置き、やぎの毛で編んだものを頭のところに置き、それを衣服でおおった。'),
('JPN', '撒母耳记上', 9, 19, 14, 'サウルはダビデを捕らえようと、使者たちを遣わした。ミカルは「あの人は病気です」と言った。'),
('JPN', '撒母耳记上', 9, 19, 15, 'サウルはダビデを見定めるために、同じ使者たちを遣わして言った。「あれを寝床のまま、私のところに連れて来い。あれを殺すのだ。」'),
('JPN', '撒母耳记上', 9, 19, 16, '使者たちが入って見ると、なんと、テラフィムが寝床にあり、やぎの毛で編んだものが頭のところにあった。'),
('JPN', '撒母耳记上', 9, 19, 17, 'サウルはミカルに言った。「なぜ、このようにして私をだまし、私の敵を逃がして、逃れさせたのか。」ミカルはサウルに言った。「あの人が、『逃がしてくれ。私がどうしておまえを殺せるだろうか』と私に言ったのです。」'),
('JPN', '撒母耳记上', 9, 19, 18, 'ダビデは逃げて、難を逃れ、ラマのサムエルのところに来た。そしてサウルが自分にしたこと一切をサムエルに告げた。彼とサムエルは、ナヨテに行って住んだ。'),
('JPN', '撒母耳记上', 9, 19, 19, 'するとサウルに「ダビデは、なんとラマのナヨテにいます」という知らせがあった。'),
('JPN', '撒母耳记上', 9, 19, 20, 'サウルはダビデを捕らえようと、使者たちを遣わした。彼らは、預言者の一団が預言し、サムエルがその監督をする者として立っているのを見た。神の霊がサウルの使者たちに臨み、彼らもまた、預言した。'),
('JPN', '撒母耳记上', 9, 19, 21, 'このことをサウルに告げる者がいたので、彼はほかの使者たちを遣わしたが、彼らもまた、預言した。サウルはさらに三度目の使者たちを遣わしたが、彼らもまた、預言した。'),
('JPN', '撒母耳记上', 9, 19, 22, 'サウル自身もラマに来た。彼はセクにある大きな井戸まで来て、「サムエルとダビデはどこにいるか」と尋ねた。すると、「今、ラマのナヨテにいます」という答えが返ってきた。'),
('JPN', '撒母耳记上', 9, 19, 23, 'サウルはそこへ、ラマのナヨテへ出て行った。彼にも神の霊が臨んだので、彼は預言しながら歩いて、ラマのナヨテまで来た。'),
('JPN', '撒母耳记上', 9, 19, 24, '彼もまた衣類を脱ぎ、サムエルの前で預言し、一昼夜、裸のまま倒れていた。このために、「サウルも預言者の一人なのか」と言われるようになった。'),
('JPN', '撒母耳记上', 9, 20, 1, 'ダビデはラマのナヨテから逃げて、ヨナタンのもとに来て言った。「私があなたの父上の前に何をし、私にどんな咎があり、どんな罪があるというのですか。父上が私のいのちを求めておられるとは。」'),
('JPN', '撒母耳记上', 9, 20, 2, 'ヨナタンは彼に言った。「とんでもないことです。あなたが死ぬはずはありません。父は、事の大小を問わず、私の耳に入れずに何かをするようなことはありません。どうして父が、このことを私に隠さなければならないでしょうか。そんなことはありません。」'),
('JPN', '撒母耳记上', 9, 20, 3, 'ダビデはなおも誓って言った。「父上は、私があなたのご好意を受けていることを、よくご存じです。『ヨナタンが悲しまないように、このことを知らせないでおこう』と思っておられるのです。けれども、主は生きておられます。あなたのたましいも生きておられます。私と死の間には、ほんの一歩の隔たりしかありません。」'),
('JPN', '撒母耳记上', 9, 20, 4, 'ヨナタンはダビデに言った。「あなたの言われることは、何でもあなたのためにします。」'),
('JPN', '撒母耳记上', 9, 20, 5, 'ダビデはヨナタンに言った。「明日はちょうど新月祭で、私は王と一緒に食事の席に着かなければなりません。でも、私を行かせて、三日目の夕方まで、野に隠れさせてください。'),
('JPN', '撒母耳记上', 9, 20, 6, 'もし、父上が私のことをとがめたら、おっしゃってください。『ダビデは自分の町ベツレヘムへ急いで行きたいと、しきりに頼みました。あそこで彼の氏族全体のために、年ごとのいけにえを献げることになっているからです』と。'),
('JPN', '撒母耳记上', 9, 20, 7, 'もし父上が『良し』とおっしゃれば、あなたのしもべは安全です。もし激しくお怒りになれば、私に害を加える決心をしておられると思ってください。'),
('JPN', '撒母耳记上', 9, 20, 8, 'どうか、このしもべに真実を尽くしてください。主に誓って、しもべと契約を結んでくださったのですから。もし私に咎があれば、あなたが私を殺してください。どうして父上のところにまで、私を連れ出す必要があるでしょうか。」'),
('JPN', '撒母耳记上', 9, 20, 9, 'ヨナタンは言った。「とんでもないことです。父があなたに害を加える決心をしていることが確かに分かったら、あなたに知らせないでおくはずはありません。」'),
('JPN', '撒母耳记上', 9, 20, 10, 'ダビデはヨナタンに言った。「もし父上が厳しい返事をなさったら、だれが私に知らせてくださいますか。」'),
('JPN', '撒母耳记上', 9, 20, 11, 'ヨナタンはダビデに言った。「野に出ましょう。」それで、二人は野に出た。'),
('JPN', '撒母耳记上', 9, 20, 12, 'ヨナタンはダビデに言った。「イスラエルの神、主にかけて誓います。明日かあさっての今ごろまでに、父がダビデに対して寛大であるかを探ってみます。寛大でなければ、必ず人を遣わして、あなたの耳に入れます。'),
('JPN', '撒母耳记上', 9, 20, 13, 'もし父が、あなたに害を加えようと思っているのに、それをあなたの耳に入れず、あなたを無事に逃がさなかったなら、主がこのヨナタンを幾重にも罰せられますように。主が父とともにおられたように、あなたとともにおられますように。'),
('JPN', '撒母耳记上', 9, 20, 14, 'もし私がこれ以上生きるべきではないのなら、あなたは、主の恵みを私に施して、私が死ぬことのないようにする必要はありません。'),
('JPN', '撒母耳记上', 9, 20, 15, 'しかし、あなたの恵みを私の家からとこしえに断たないでください。主がダビデの敵を地の面から一人残らず断たれるときにも。」'),
('JPN', '撒母耳记上', 9, 20, 16, 'ヨナタンはダビデの家と契約を結んだ。「主がダビデの敵に血の責めを問われますように。」'),
('JPN', '撒母耳记上', 9, 20, 17, 'ヨナタンは、ダビデに対する愛のゆえに、もう一度ダビデに誓わせた。ヨナタンは、自分を愛するほどにダビデを愛していたからである。'),
('JPN', '撒母耳记上', 9, 20, 18, 'ヨナタンはダビデに言った。「明日は新月祭です。あなたの席が空くので、あなたがいないことが分かるでしょう。'),
('JPN', '撒母耳记上', 9, 20, 19, '三日目に、日が暮れてから、あの事件の日に隠れた場所に行って、エゼルの石のそばにいてください。'),
('JPN', '撒母耳记上', 9, 20, 20, '私は的を射るように、三本の矢をそのあたりに放ちます。'),
('JPN', '撒母耳记上', 9, 20, 21, '私が子どもを遣わして、『行って、矢を見つけて来い』と言い、もし子どもに『それ、矢はおまえのこちら側にある。それを取って来い』と言ったら、出て来てください。主は生きておられます。あなたは安全で、何事もありませんから。'),
('JPN', '撒母耳记上', 9, 20, 22, 'しかし、私が少年に『それ、矢はおまえの向こう側だ』と言ったら、行ってください。主があなたを去らせるのです。'),
('JPN', '撒母耳记上', 9, 20, 23, '私とあなたが交わしたことばについては、主が私とあなたの間の永遠の証人です。」'),
('JPN', '撒母耳记上', 9, 20, 24, 'ダビデは野に隠れた。新月祭になって、王は食事の席に着いた。'),
('JPN', '撒母耳记上', 9, 20, 25, '王は、いつものように自分の席、つまり壁寄りの席に着いた。ヨナタンはその向かい側、アブネルはサウルの横の席に着いたが、ダビデの席は空いていた。'),
('JPN', '撒母耳记上', 9, 20, 26, 'しかし、その日、サウルは何も言わなかった。「思わぬことが起こって身を汚したのだろう。きっと汚れているためだろう」と思ったからであった。'),
('JPN', '撒母耳记上', 9, 20, 27, 'しかし、その翌日、新月祭の二日目にも、ダビデの席は空いていた。サウルは息子のヨナタンに言った。「どうしてエッサイの子は、昨日も今日も食事に来なかったのか。」'),
('JPN', '撒母耳记上', 9, 20, 28, 'ヨナタンはサウルに答えた。「ベツレヘムへ行かせてくれと、ダビデが私にしきりに頼みました。'),
('JPN', '撒母耳记上', 9, 20, 29, '『どうか、私を行かせてください。氏族の祝宴がその町であります。長兄が命じているのです。今、あなたのご好意を得ているなら、どうか私を行かせて、兄弟たちに会わせてください』と言ったのです。それで彼は王の食卓に来ていないのです。」'),
('JPN', '撒母耳记上', 9, 20, 30, 'サウルはヨナタンに怒りを燃やして言った。「この邪悪な気まぐれ女の息子め。おまえがエッサイの子に肩入れし、自分を辱め、母親の裸の恥をさらしているのを、この私が知らないとでも思っているのか。'),
('JPN', '撒母耳记上', 9, 20, 31, 'エッサイの子がこの地上に生きているかぎり、おまえも、おまえの王位も確立されないのだ。今、人を遣わして、あれを私のところに連れて来い。あれは死に値する。」'),
('JPN', '撒母耳记上', 9, 20, 32, 'ヨナタンは父サウルに答えて言った。「なぜ、彼は殺されなければならないのですか。何をしたというのですか。」'),
('JPN', '撒母耳记上', 9, 20, 33, 'すると、サウルは槍をヨナタンに投げつけて撃ち殺そうとした。それでヨナタンは、父がダビデを殺そうと決心しているのを知った。'),
('JPN', '撒母耳记上', 9, 20, 34, 'ヨナタンは怒りに燃えて食卓から立ち上がり、新月祭の二日目には食事をとらなかった。父がダビデを侮辱したので、ダビデのために悲しんだからである。'),
('JPN', '撒母耳记上', 9, 20, 35, '朝になると、ヨナタンは小さい子どもを連れて、ダビデと打ち合わせた時刻に野に出て行った。'),
('JPN', '撒母耳记上', 9, 20, 36, 'そして子どもに言った。「走って行って、私が射る矢を見つけておいで。」子どもが走って行くと、ヨナタンは、その子の向こうに矢を放った。'),
('JPN', '撒母耳记上', 9, 20, 37, '子どもがヨナタンの放った矢のところまで行くと、ヨナタンは子どものうしろから叫んだ。「矢は、おまえより、もっと向こうではないか。」'),
('JPN', '撒母耳记上', 9, 20, 38, 'ヨナタンは子どものうしろから、また叫んだ。「早く。急げ。立ち止まってはいけない。」その子どもは矢を拾って、主人ヨナタンのところに来た。'),
('JPN', '撒母耳记上', 9, 20, 39, '子どもは何も知らず、ヨナタンとダビデだけに、その意味が分かっていた。'),
('JPN', '撒母耳记上', 9, 20, 40, 'ヨナタンは自分の弓矢を子どもに渡し、「さあ、これを町に持って行っておくれ」と言った。'),
('JPN', '撒母耳记上', 9, 20, 41, '子どもが行くと、ダビデは南側から出て来て地にひれ伏し、三度礼をした。二人は口づけし、抱き合って泣いた。ダビデはいっそう激しく泣いた。'),
('JPN', '撒母耳记上', 9, 20, 42, 'ヨナタンはダビデに言った。「安心して行ってください。私たち二人は、『主が、私とあなた、また、私の子孫とあなたの子孫との間の永遠の証人です』と言って、主の御名によって誓ったのです。」そして、ダビデは立ち去った。ヨナタンは町へ帰って行った。'),
('JPN', '撒母耳记上', 9, 21, 1, 'ダビデはノブの祭司アヒメレクのところに来た。アヒメレクは震えながら、ダビデを迎えて言った。「なぜ、お一人で、だれもお供がいないのですか。」'),
('JPN', '撒母耳记上', 9, 21, 2, 'ダビデは祭司アヒメレクに言った。「王は、あることを命じて、『おまえを遣わし、おまえに命じたことについては、何も人に知らせてはならない』と私に言われました。若い者たちとは、しかじかの場所で落ち合うことにしています。'),
('JPN', '撒母耳记上', 9, 21, 3, '今、お手もとに何かあったら、パン五つでも、ある物を下さい。」'),
('JPN', '撒母耳记上', 9, 21, 4, '祭司はダビデに答えて言った。「手もとには、普通のパンはありません。ですが、もし若い者たちが女たちから身を遠ざけているなら、聖別されたパンはあります。」'),
('JPN', '撒母耳记上', 9, 21, 5, 'ダビデは祭司に答えて言った。「実際、私が以前戦いに出て行ったときと同じように、女たちは私たちから遠ざけられています。若い者たちのからだは聖別されています。普通の旅でもそうですから、まして今日、彼らのからだは聖別されています。」'),
('JPN', '撒母耳记上', 9, 21, 6, '祭司は彼に、聖別されたパンを与えた。そこには、温かいパンと置き換えるために、その日主の前から取り下げられた、臨在のパンしかなかったからである。'),
('JPN', '撒母耳记上', 9, 21, 7, '──その日、そこにはサウルのしもべの一人が主の前に引き止められていた。その名はドエグといい、エドム人で、サウルの牧者たちの長であった──'),
('JPN', '撒母耳记上', 9, 21, 8, 'ダビデはアヒメレクに言った。「ここには、あなたの手もとに、槍か剣はありませんか。私は自分の剣も武器も持って来なかったのです。王の命令があまりに急だったので。」'),
('JPN', '撒母耳记上', 9, 21, 9, '祭司は言った。「ご覧ください。あなたがエラの谷で討ち取ったペリシテ人ゴリヤテの剣が、エポデのうしろに布に包んであります。よろしければ、持って行ってください。ここには、それしかありませんから。」ダビデは言った。「それにまさるものはありません。私に下さい。」'),
('JPN', '撒母耳记上', 9, 21, 10, 'ダビデはその日、ただちにサウルから逃れ、ガテの王アキシュのところに来た。'),
('JPN', '撒母耳记上', 9, 21, 11, 'アキシュの家来たちはアキシュに言った。「この人は、かの地の王ダビデではありませんか。皆が踊りながら、『サウルは千を討ち、ダビデは万を討った』と言って歌っていたのは、この人のことではありませんか。」'),
('JPN', '撒母耳记上', 9, 21, 12, 'ダビデは、このことばを気にして、ガテの王アキシュを非常に恐れた。'),
('JPN', '撒母耳记上', 9, 21, 13, 'ダビデは彼らの前でおかしくなったかのようにふるまい、捕らえられて気が変になったふりをした。彼は門の扉に傷をつけたり、ひげによだれを垂らしたりした。'),
('JPN', '撒母耳记上', 9, 21, 14, 'アキシュは家来たちに言った。「おい、おまえたちも見ているように、この男は気がふれている。なぜ、私のところに連れて来たのか。'),
('JPN', '撒母耳记上', 9, 21, 15, '私のところに気がふれた者が不足しているとでもいうのか。私の前で気がふれているのを見せるために、この男を連れて来るとは。この男を私の家に入れようとでもいうのか。」'),
('JPN', '撒母耳记上', 9, 22, 1, 'ダビデはそこを去って、アドラムの洞穴に避難した。彼の兄弟たちや父の家の者はみな、これを聞いてダビデのところに下って来た。'),
('JPN', '撒母耳记上', 9, 22, 2, 'そして、困窮している者、負債のある者、不満のある者たちもみな、彼のところに集まって来たので、ダビデは彼らの長となった。約四百人の者が彼とともにいるようになった。'),
('JPN', '撒母耳记上', 9, 22, 3, 'ダビデはそこからモアブのミツパに行き、モアブの王に言った。「神が私にどのようなことをされるか分かるまで、どうか、父と母をあなたがたと一緒に住まわせてください。」'),
('JPN', '撒母耳记上', 9, 22, 4, 'ダビデは両親をモアブの王の前に連れて来た。彼らは、ダビデが要害にいる間、王のもとに住んだ。'),
('JPN', '撒母耳记上', 9, 22, 5, '預言者ガドはダビデに言った。「この要害にとどまっていないで、さあ、ユダの地に帰りなさい。」それで、ダビデはそこを出て、ハレテの森へやって来た。'),
('JPN', '撒母耳记上', 9, 22, 6, 'サウルは、ダビデおよび彼とともにいる者たちが見つかったことを聞いた。サウルはギブアにある高台のタマリスクの木の下で、槍を手にして座っていた。彼の家来たちはみな、彼のそばに立っていた。'),
('JPN', '撒母耳记上', 9, 22, 7, 'サウルは、そばに立っている家来たちに言った。「聞け、ベニヤミン人。エッサイの子が、おまえたち全員に畑やぶどう畑をくれたり、おまえたち全員を千人隊の長、百人隊の長にしたりするだろうか。'),
('JPN', '撒母耳记上', 9, 22, 8, 'それなのに、おまえたちはみな私に謀反を企てている。息子がエッサイの子と契約を結んでも、だれも私の耳に入れない。おまえたちのだれも、私のことを思って心を痛めることをせず、今日のように、息子が私のしもべを私に逆らわせて、待ち伏せさせても、私の耳に入れない。」'),
('JPN', '撒母耳记上', 9, 22, 9, 'サウルの家来たちのそばに立っていたエドム人ドエグが答えて言った。「私は、エッサイの子が、ノブのアヒトブの子アヒメレクのところに来たのを見ました。'),
('JPN', '撒母耳记上', 9, 22, 10, 'アヒメレクは彼のために主に伺って、彼に食糧を与え、ペリシテ人ゴリヤテの剣も与えました。」'),
('JPN', '撒母耳记上', 9, 22, 11, '王は人を遣わして、祭司アヒトブの子アヒメレクと、彼の父の家の者全員、すなわち、ノブにいる祭司たちを呼び寄せた。彼らはみな、王のところに来た。'),
('JPN', '撒母耳记上', 9, 22, 12, 'サウルは言った。「聞け、アヒトブの子よ。」彼は答えた。「はい、王様。ここにおります。」'),
('JPN', '撒母耳记上', 9, 22, 13, 'サウルは彼に言った。「おまえとエッサイの子は、なぜ私に謀反を企てるのか。おまえは彼にパンと剣を与え、彼のために神に伺い、そうして彼は今日のように私に逆らって待ち伏せしている。」'),
('JPN', '撒母耳记上', 9, 22, 14, 'アヒメレクは王に答えて言った。「あなたの家来の中に、ダビデほど忠実な者が、だれかいるでしょうか。ダビデは王の婿であり、あなたの護衛兵の長であり、あなたの家で重んじられているではありませんか。'),
('JPN', '撒母耳记上', 9, 22, 15, '私が彼のために神に伺うのは、今日に始まったことでしょうか。決して、そんなことはありません。王様。このしもべや、父の家の者全員に汚名を着せないでください。あなたのしもべは、この事件について、いっさい知らないのですから。」'),
('JPN', '撒母耳记上', 9, 22, 16, '王は言った。「アヒメレク、おまえは必ず死ななければならない。おまえも、おまえの父の家の者全員もだ。」'),
('JPN', '撒母耳记上', 9, 22, 17, '王は、そばに立っていた近衛兵たちに言った。「近寄って、主の祭司たちを殺せ。彼らはダビデにくみし、ダビデが逃げているのを知りながら、それを私の耳に入れなかったからだ。」しかし王の家来たちは、主の祭司たちに手を下して討ちかかろうとはしなかった。'),
('JPN', '撒母耳记上', 9, 22, 18, '王はドエグに言った。「おまえが行って祭司たちに討ちかかれ。」そこでエドム人ドエグが行って、祭司たちに討ちかかった。その日彼は、亜麻布のエポデを着ていた人を八十五人殺した。'),
('JPN', '撒母耳记上', 9, 22, 19, '彼は祭司の町ノブを、男も女も、幼子も乳飲み子も、剣の刃で討った。牛もろばも羊も、剣の刃で。'),
('JPN', '撒母耳记上', 9, 22, 20, 'アヒトブの子アヒメレクの息子のエブヤタルという名の人が、一人逃れてダビデのところに逃げて来た。'),
('JPN', '撒母耳记上', 9, 22, 21, 'エブヤタルはダビデに、サウルが主の祭司たちを殺したことを告げた。'),
('JPN', '撒母耳记上', 9, 22, 22, 'ダビデはエブヤタルに言った。「私はあの日、エドム人ドエグがあそこにいたので、彼がきっとサウルに知らせると思っていた。私が、あなたの父の家の者全員の死を引き起こしたのだ。'),
('JPN', '撒母耳记上', 9, 22, 23, '私と一緒にいなさい。恐れることはない。私のいのちを狙う者は、あなたのいのちを狙う。しかし私と一緒にいれば、あなたは安全だ。」'),
('JPN', '撒母耳记上', 9, 23, 1, '「今、ペリシテ人がケイラを攻めて、打ち場を略奪しています」と言って、ダビデに告げる者がいた。'),
('JPN', '撒母耳记上', 9, 23, 2, 'ダビデは主に伺って言った。「行って、このペリシテ人たちを討つべきでしょうか。」主はダビデに言われた。「行け。ペリシテ人を討ち、ケイラを救え。」'),
('JPN', '撒母耳记上', 9, 23, 3, 'ダビデの部下は彼に言った。「ご覧のとおり、私たちは、ここユダにいてさえ恐れているのに、ケイラのペリシテ人の陣地に向かって行けるでしょうか。」'),
('JPN', '撒母耳记上', 9, 23, 4, 'ダビデはもう一度、主に伺った。すると主は答えられた。「さあ、ケイラに下って行け。わたしがペリシテ人をあなたの手に渡すから。」'),
('JPN', '撒母耳记上', 9, 23, 5, 'ダビデとその部下はケイラに行き、ペリシテ人と戦い、彼らの家畜を奪い返し、ペリシテ人を討って大損害を与えた。こうしてダビデはケイラの住民を救った。'),
('JPN', '撒母耳记上', 9, 23, 6, 'アヒメレクの子エブヤタルは、ケイラのダビデのもとに逃げて来たとき、エポデを携えていた。'),
('JPN', '撒母耳记上', 9, 23, 7, '一方、ダビデがケイラに来たことがサウルに知らされると、サウルは、「神は彼を私の手に渡された。彼は扉とかんぬきのある町に入って、自分自身を閉じ込めてしまったのだから」と言った。'),
('JPN', '撒母耳记上', 9, 23, 8, 'サウルは、ケイラへ下ってダビデとその部下を攻めて封じ込めるため、兵をみな召集した。'),
('JPN', '撒母耳记上', 9, 23, 9, 'ダビデは、サウルが自分に害を加えようとしているのを知り、祭司エブヤタルに言った。「エポデを持って来なさい。」'),
('JPN', '撒母耳记上', 9, 23, 10, 'そしてダビデは言った。「イスラエルの神、主よ。しもべは、サウルがケイラに来て、私のことで、この町を破壊しようとしていることを確かに聞きました。'),
('JPN', '撒母耳记上', 9, 23, 11, 'ケイラの者たちは私を彼の手に引き渡すでしょうか。サウルは、しもべが聞いたとおり下って来るでしょうか。イスラエルの神、主よ。どうか、しもべにお告げください。」主は言われた。「彼は下って来る。」'),
('JPN', '撒母耳记上', 9, 23, 12, 'ダビデは言った。「ケイラの者たちは、私と私の部下をサウルの手に引き渡すでしょうか。」主は言われた。「彼らは引き渡す。」'),
('JPN', '撒母耳记上', 9, 23, 13, 'ダビデとその部下およそ六百人は立って、ケイラから出て行き、そこここと、さまよった。ダビデがケイラから逃れたことがサウルに告げられると、サウルは討伐をやめた。'),
('JPN', '撒母耳记上', 9, 23, 14, 'ダビデは、荒野にある要害に宿ったり、ジフの荒野の山地に宿ったりした。サウルは、毎日ダビデを追い続けたが、神はダビデをサウルの手に渡されなかった。'),
('JPN', '撒母耳记上', 9, 23, 15, 'ダビデは、サウルが自分のいのちを狙って、戦いに出て来たのを見た。そのとき、ダビデはジフの荒野のホレシュにいた。'),
('JPN', '撒母耳记上', 9, 23, 16, 'サウルの息子ヨナタンは、ホレシュのダビデのところに行って、神によってダビデを力づけた。'),
('JPN', '撒母耳记上', 9, 23, 17, '彼はダビデに言った。「恐れることはありません。父サウルの手が、あなたの身に及ぶことはないからです。あなたこそ、イスラエルの王となり、私はあなたの次に立つ者となるでしょう。父サウルも、そうなることを確かに知っているのです。」'),
('JPN', '撒母耳记上', 9, 23, 18, '二人は主の前で契約を結んだ。ダビデはホレシュにとどまり、ヨナタンは自分の家に帰った。'),
('JPN', '撒母耳记上', 9, 23, 19, 'ジフ人たちは、ギブアのサウルのところに上って行って、言った。「ダビデは私たちのところに隠れているのではありませんか。エシモンの南、ハキラの丘のホレシュにある要害に。'),
('JPN', '撒母耳记上', 9, 23, 20, '王よ。今、下って行こうとお思いでしたら、下って来てください。私たちが彼を王の手に引き渡します。」'),
('JPN', '撒母耳记上', 9, 23, 21, 'サウルは言った。「主の祝福があなたがたにあるように。あなたがたが私のことを思ってくれたからだ。'),
('JPN', '撒母耳记上', 9, 23, 22, 'さあ行って、さらに確かめてくれ。彼が足を運ぶ場所と、だれがそこで彼を見たかを、よく調べてくれ。彼は非常に悪賢いとの評判だから。'),
('JPN', '撒母耳记上', 9, 23, 23, '彼が潜んでいる隠れ場所をみな、よく調べて、確かな知らせを持って、ここに戻って来てくれ。そのとき、私はあなたがたと一緒に行く。彼がこの地にいるなら、ユダのすべての分団のうちから彼を捜し出す。」'),
('JPN', '撒母耳记上', 9, 23, 24, '彼らはサウルに先立ってジフへ行った。一方、ダビデとその部下は、エシモンの南のアラバにあるマオンの荒野にいた。'),
('JPN', '撒母耳记上', 9, 23, 25, 'サウルとその部下はダビデを捜しに出て行った。このことがダビデに知らされたので、彼は岩場に下り、マオンの荒野にとどまった。サウルはこれを聞き、マオンの荒野でダビデを追った。'),
('JPN', '撒母耳记上', 9, 23, 26, 'サウルは山の一方の側を進み、ダビデとその部下は山のもう一方の側を進んだ。ダビデは急いでサウルから逃れようとした。サウルとその部下が、ダビデとその部下を捕らえようと迫って来たとき、'),
('JPN', '撒母耳记上', 9, 23, 27, '一人の使者がサウルのもとに来て、「急いで来てください。ペリシテ人がこの国に襲いかかって来ました」と言った。'),
('JPN', '撒母耳记上', 9, 23, 28, 'サウルはダビデを追うのをやめて帰り、ペリシテ人の方に向かった。こういうわけで、この場所は「仕切りの岩山」と呼ばれた。'),
('JPN', '撒母耳记上', 9, 23, 29, 'ダビデはそこから上って行って、エン・ゲディの要害に住んだ。'),
('JPN', '撒母耳记上', 9, 24, 1, 'サウルがペリシテ人を追うのをやめて帰って来たとき、「ダビデが今、エン・ゲディの荒野にいます」と言って、彼に告げる者がいた。'),
('JPN', '撒母耳记上', 9, 24, 2, 'サウルは、イスラエル全体から三千人の精鋭を選り抜いて、エエリムの岩の東に、ダビデとその部下を捜しに出かけた。'),
('JPN', '撒母耳记上', 9, 24, 3, '道の傍らにある羊の群れの囲い場に来ると、そこに洞穴があった。サウルは用をたすために中に入った。そのとき、ダビデとその部下は、その洞穴の奥の方に座っていた。'),
('JPN', '撒母耳记上', 9, 24, 4, 'ダビデの部下はダビデに言った。「今日こそ、主があなた様に、『見よ、わたしはあなたの敵をあなたの手に渡す。彼をあなたの良いと思うようにせよ』と言われた、その日です。」ダビデは立ち上がり、サウルの上着の裾を、こっそり切り取った。'),
('JPN', '撒母耳记上', 9, 24, 5, '後になってダビデは、サウルの上着の裾を切り取ったことについて心を痛めた。'),
('JPN', '撒母耳记上', 9, 24, 6, '彼は部下に言った。「私が主に逆らって、主に油注がれた方、私の主君に対して、そのようなことをして手を下すなど、絶対にあり得ないことだ。彼は主に油注がれた方なのだから。」'),
('JPN', '撒母耳记上', 9, 24, 7, 'ダビデはこのことで部下を説き伏せ、彼らがサウルに襲いかかるのを許さなかった。サウルは、洞穴から出て道を歩いて行った。'),
('JPN', '撒母耳记上', 9, 24, 8, 'ダビデも洞穴から出て行き、サウルのうしろから呼びかけ、「王よ」と言った。サウルがうしろを振り向くと、ダビデは地にひれ伏して、礼をした。'),
('JPN', '撒母耳记上', 9, 24, 9, 'そしてダビデはサウルに言った。「なぜ、『ダビデがあなたに害を加えようとしている』と言う人のことばに、耳を傾けられるのですか。'),
('JPN', '撒母耳记上', 9, 24, 10, '今日、主が洞穴で私の手にあなたをお渡しになったのを、あなたの目はご覧になったのです。ある者はあなたを殺すようにと言ったのですが、私は、あなたのことを思って、『私の主君に手を下すことはしない。あの方は主に油注がれた方だから』と言いました。'),
('JPN', '撒母耳记上', 9, 24, 11, 'わが父よ。どうか、私の手にあるあなたの上着の裾をよくご覧ください。あなたの上着の裾を切り取りましたが、あなたを殺しはしませんでした。それによって、私の手に悪も背きもないことを、お分かりください。あなたに罪を犯していないのに、あなたは私のいのちを取ろうと狙っておられるのです。'),
('JPN', '撒母耳记上', 9, 24, 12, 'どうか、主が私とあなたの間をさばき、主が私のために、あなたに報いられますように。しかし、私はあなたを手にかけることはいたしません。'),
('JPN', '撒母耳记上', 9, 24, 13, '昔のことわざに『悪は悪者から出る』と言います。私はあなたを手にかけることはいたしません。'),
('JPN', '撒母耳记上', 9, 24, 14, 'イスラエルの王はだれを追って出て来られたのですか。だれを追いかけておられるのですか。死んだ犬の後でしょうか。一匹の蚤の後でしょうか。'),
('JPN', '撒母耳记上', 9, 24, 15, 'どうか主が、さばき人となって私とあなたの間をさばき、私の訴えを取り上げて擁護し、正しいさばきであなたの手から私を救ってくださいますように。」'),
('JPN', '撒母耳记上', 9, 24, 16, 'ダビデがこれらのことばをサウルに語り終えたとき、サウルは「これはおまえの声なのか。わが子ダビデよ」と言った。サウルは声をあげて泣いた。'),
('JPN', '撒母耳记上', 9, 24, 17, 'そしてダビデに言った。「おまえは私より正しい。私に良くしてくれたのに、私はおまえに悪い仕打ちをした。'),
('JPN', '撒母耳记上', 9, 24, 18, '私に良いことをしてくれたことを、今日、おまえは知らせてくれた。主が私をおまえの手に渡されたのに、私を殺さなかったのだから。'),
('JPN', '撒母耳记上', 9, 24, 19, '人が自分の敵を見つけたとき、その敵を無傷で去らせるだろうか。おまえが今日、私にしてくれたことの報いとして、主がおまえに幸いを与えられるように。'),
('JPN', '撒母耳记上', 9, 24, 20, 'おまえが必ず王になり、おまえの手によってイスラエル王国が確立することを、私は今、確かに知った。'),
('JPN', '撒母耳记上', 9, 24, 21, '今、主にかけて私に誓ってくれ。私の後の子孫を断たず、私の名を父の家から消し去らないことを。」'),
('JPN', '撒母耳记上', 9, 24, 22, 'ダビデはサウルに誓った。サウルは自分の家へ帰り、ダビデとその部下は要害へ上って行った。'),
('JPN', '撒母耳记上', 9, 25, 1, 'サムエルは死んだ。全イスラエルは集まって、彼のために悼み悲しみ、ラマにある彼の家に葬った。ダビデは立ってパランの荒野に下って行った。'),
('JPN', '撒母耳记上', 9, 25, 2, 'マオンに一人の人がいた。カルメルで事業をしていて、非常に裕福で、羊三千匹、やぎ千匹を持っていた。彼はカルメルで羊の毛の刈り取りをしていた。'),
('JPN', '撒母耳记上', 9, 25, 3, 'この人の名はナバルといい、妻の名はアビガイルといった。この女は賢明で姿が美しかったが、夫は頑迷で行状が悪かった。彼はカレブ人であった。'),
('JPN', '撒母耳记上', 9, 25, 4, 'ダビデは、ナバルがその羊の毛を刈っていることを荒野で聞いた。'),
('JPN', '撒母耳记上', 9, 25, 5, 'ダビデは十人の若者を遣わし、その若者たちに言った。「カルメルへ上って行ってナバルのところに着いたら、私の名で彼に安否を尋ね、'),
('JPN', '撒母耳记上', 9, 25, 6, 'わが同胞に、こう言いなさい。『あなたに平安がありますように。あなたの家に平安がありますように。また、あなたのすべてのものに平安がありますように。'),
('JPN', '撒母耳记上', 9, 25, 7, '今、羊の毛を刈る者たちが、あなたのところにいるのを聞きました。あなたの羊飼いたちは、私たちと一緒にいましたが、彼らに恥をかかせたことはありませんでした。彼らがカルメルにいる間中、何かが失われることもありませんでした。'),
('JPN', '撒母耳记上', 9, 25, 8, 'あなたの若者たちに尋ねてみてください。彼らはそう報告するでしょう。ですから、私の若者たちに親切にしてやってください。祝いの日に来たのですから。どうか、しもべたちと、あなたの子ダビデに、何かあなたの手もとにある物を与えてください。』」'),
('JPN', '撒母耳记上', 9, 25, 9, 'ダビデの若者たちは行って、言われたとおりのことをダビデの名によってナバルに告げ、答えを待った。'),
('JPN', '撒母耳记上', 9, 25, 10, 'ナバルはダビデの家来たちに答えて言った。「ダビデとは何者だ。エッサイの子とは何者だ。このごろは、主人のところから脱走する家来が多くなっている。'),
('JPN', '撒母耳记上', 9, 25, 11, '私のパンと水、それに羊の毛を刈り取る者たちのために屠った肉を取って、どこから来たかも分からない者どもに、くれてやらなければならないのか。」'),
('JPN', '撒母耳记上', 9, 25, 12, 'ダビデの若者たちは、もと来た道を引き返し、戻って来て、これら一部始終をダビデに報告した。'),
('JPN', '撒母耳记上', 9, 25, 13, 'ダビデは部下に「各自、自分の剣を帯びよ」と命じた。それで、みな剣を身に帯びた。ダビデも剣を帯びた。四百人ほどの者がダビデについて上って行き、二百人は荷物のところにとどまった。'),
('JPN', '撒母耳记上', 9, 25, 14, 'ナバルの妻アビガイルに、若者の一人が告げて言った。「ダビデがご主人様に祝福のあいさつをするために、荒野から使者たちを遣わしたのに、ご主人様は彼らをののしりました。'),
('JPN', '撒母耳记上', 9, 25, 15, 'あの人たちは私たちにとても良くしてくれたのです。私たちは恥をかかされたこともなく、野で一緒にいて行動をともにしていた間、何も失いませんでした。'),
('JPN', '撒母耳记上', 9, 25, 16, '一緒に羊を飼っている間は、夜も昼も、彼らは私たちのために防壁となってくれました。'),
('JPN', '撒母耳记上', 9, 25, 17, '今、あなたがどうすればよいか、よく考えてください。わざわいがご主人とその一家に及ぶことは、もう、はっきりしています。ご主人はよこしまな方ですから、だれも話しかけることができません。」'),
('JPN', '撒母耳记上', 9, 25, 18, 'アビガイルは急いでパン二百個、ぶどう酒の皮袋二つ、料理した羊五匹、炒り麦五セア、干しぶどう百房、干しいちじく二百個を取って、これをろばに載せ、'),
('JPN', '撒母耳记上', 9, 25, 19, '自分の若者たちに言った。「私の先を進みなさい。あなたがたについて行くから。」ただ、彼女は夫ナバルには何も告げなかった。'),
('JPN', '撒母耳记上', 9, 25, 20, 'アビガイルがろばに乗って山陰を下って行くと、ちょうど、ダビデとその部下が彼女の方に下って来るのに出会った。'),
('JPN', '撒母耳记上', 9, 25, 21, 'ダビデは、こう言ったばかりであった。「荒野で、あの男のものをすべて守ってやったので、その財産は何一つ失われなかったが、それは全く無駄だった。あの男は善に代えて悪を返した。'),
('JPN', '撒母耳记上', 9, 25, 22, 'もし私が明日の朝までに、あの男に属する者のうち小童一人でも残しておくなら、神がこのダビデを幾重にも罰せられるように。」'),
('JPN', '撒母耳记上', 9, 25, 23, 'アビガイルはダビデを見ると、急いでろばから降り、ダビデの前で顔を伏せて地面にひれ伏した。'),
('JPN', '撒母耳记上', 9, 25, 24, '彼女はダビデの足もとにひれ伏して言った。「ご主人様、あの責めは私にあります。どうか、はしためが、じかに申し上げることをお許しください。このはしためのことばをお聞きください。'),
('JPN', '撒母耳记上', 9, 25, 25, 'ご主人様、どうか、あのよこしまな者、ナバルのことなど気にかけないでください。あの者は名のとおりの男ですから。彼の名はナバルで、そのとおりの愚か者です。はしための私は、ご主人様がお遣わしになった若者たちに会ってはおりません。'),
('JPN', '撒母耳记上', 9, 25, 26, 'ご主人様。今、主は生きておられます。あなたのたましいも生きておられます。主は、あなたが血を流しに行かれるのを止め、ご自分の手で復讐なさることを止められました。あなたの敵、ご主人様に対して害を加えようとする者どもが、ナバルのようになりますように。'),
('JPN', '撒母耳记上', 9, 25, 27, '今、はしためが、ご主人様に持って参りましたこの贈り物を、ご主人様につき従う若者たちにお与えください。'),
('JPN', '撒母耳记上', 9, 25, 28, 'どうか、はしための背きをお赦しください。主は必ず、ご主人様のために、確かな家をお建てになるでしょう。ご主人様は主の戦いを戦っておられるのですから。あなたのうちには、一生の間、悪が見出されてはなりません。'),
('JPN', '撒母耳记上', 9, 25, 29, '人があなたを追って、いのちを狙おうとしても、ご主人様のいのちは、あなたの神、主によって、いのちの袋にしまわれています。あなたの敵のいのちは、主が石投げのくぼみに入れて投げつけられるでしょう。'),
('JPN', '撒母耳记上', 9, 25, 30, '主が、ご主人様について約束なさったすべての良いことをあなたに成し遂げ、あなたをイスラエルの君主に任じられたとき、'),
('JPN', '撒母耳记上', 9, 25, 31, '理由もなく血を流したり、ご主人様自身で復讐したりされたことが、つまずきとなり、ご主人様の心の妨げとなりませんように。主がご主人様を栄えさせてくださったら、このはしためを思い出してください。」'),
('JPN', '撒母耳记上', 9, 25, 32, 'ダビデはアビガイルに言った。「イスラエルの神、主がほめたたえられますように。主は今日、あなたを送り、私に会わせてくださった。'),
('JPN', '撒母耳记上', 9, 25, 33, 'あなたの判断がほめたたえられるように。また、あなたが、ほめたたえられるように。あなたは今日、私が人の血を流しに行き、私自身の手で復讐しようとするのをやめさせた。'),
('JPN', '撒母耳记上', 9, 25, 34, 'イスラエルの神、主は生きておられる。主は私を引き止めて、あなたに害を加えさせなかった。もし、あなたが急いで私に会いに来なかったなら、きっと、明け方までにナバルには小童が一人も残らなかっただろう。」'),
('JPN', '撒母耳记上', 9, 25, 35, 'ダビデはアビガイルの手から、彼女が持って来た物を受け取り、彼女に言った。「安心して、家へ上って行きなさい。見なさい。私はあなたの言うことを聞き、あなたの願いを受け入れた。」'),
('JPN', '撒母耳记上', 9, 25, 36, 'アビガイルがナバルのところに帰って来ると、ちょうどナバルは、自分の家で王の宴会のような宴会を開いていた。ナバルが上機嫌で、ひどく酔っていたので、アビガイルは明け方まで、何一つ彼に話さなかった。'),
('JPN', '撒母耳记上', 9, 25, 37, '朝になって、ナバルの酔いがさめたとき、妻がこれらの出来事を彼に告げると、彼は気を失って石のようになった。'),
('JPN', '撒母耳记上', 9, 25, 38, '十日ほどたって、主はナバルを打たれ、彼は死んだ。'),
('JPN', '撒母耳记上', 9, 25, 39, 'ダビデはナバルが死んだことを聞いて言った。「主がほめたたえられますように。主は、私がナバルの手から受けた恥辱に対する私の訴えを取り上げ、このしもべが悪を行うのを引き止めてくださった。主はナバルの悪の報いをその頭上に返された。」ダビデは人を遣わして、アビガイルに自分の妻になるよう申し入れた。'),
('JPN', '撒母耳记上', 9, 25, 40, 'ダビデのしもべたちはカルメルのアビガイルのところに来て、彼女に、「ダビデはあなたを妻として迎えるために私たちを遣わしました」と言った。'),
('JPN', '撒母耳记上', 9, 25, 41, '彼女はすぐに、地にひれ伏して礼をし、そして言った。「さあ。このはしためは、ご主人様のしもべたちの足を洗う女奴隷となりましょう。」'),
('JPN', '撒母耳记上', 9, 25, 42, 'アビガイルは急いで用意をして、ろばに乗り、彼女の五人の侍女を後に従え、ダビデの使者たちの後に従って行った。彼女はダビデの妻となった。'),
('JPN', '撒母耳记上', 9, 25, 43, 'ダビデはイズレエルの出であるアヒノアムを妻としていたので、二人ともダビデの妻となった。'),
('JPN', '撒母耳记上', 9, 25, 44, 'サウルはダビデの妻であった自分の娘ミカルを、ガリム出身のライシュの子パルティに与えていた。'),
('JPN', '撒母耳记上', 9, 26, 1, 'ジフ人がギブアにいるサウルのところに来て言った。「ダビデはエシモンの東にあるハキラの丘に隠れているのではないでしょうか。」'),
('JPN', '撒母耳记上', 9, 26, 2, 'サウルは立って、三千人のイスラエルの精鋭とともに、ジフの荒野へ下って行った。ジフの荒野でダビデを捜すためであった。'),
('JPN', '撒母耳记上', 9, 26, 3, 'サウルは、エシモンの東にあるハキラの丘で、道の傍らに陣を敷いた。一方、ダビデは荒野にとどまっていた。ダビデは、サウルが自分を追って荒野に来たのを見て、'),
('JPN', '撒母耳记上', 9, 26, 4, '偵察を送り、サウルが確かに来たことを知った。'),
('JPN', '撒母耳记上', 9, 26, 5, 'ダビデは立って、サウルが陣を敷いている場所にやって来た。そしてダビデは、サウルと、その軍の長ネルの子アブネルが寝ている場所を見つけた。サウルは幕営の中で寝ていて、兵たちは彼の周りに宿営していた。'),
('JPN', '撒母耳记上', 9, 26, 6, 'ダビデは、ヒッタイト人アヒメレクと、ヨアブの兄弟で、ツェルヤの子アビシャイに言った。「だれか、私と一緒に陣営のサウルのところへ下って行く者はいないか。」アビシャイが答えた。「私が一緒に下って参ります。」'),
('JPN', '撒母耳记上', 9, 26, 7, 'ダビデとアビシャイは夜、兵たちのところに来た。見ると、サウルは幕営の中で横になって寝ていて、彼の槍が、枕もとの地面に突き刺してあった。アブネルも兵たちも、その周りに眠っていた。'),
('JPN', '撒母耳记上', 9, 26, 8, 'アビシャイはダビデに言った。「神は今日、あなたの敵をあなたの手に渡されました。どうか私に、槍で一気に彼を地面に突き刺させてください。二度することはしません。」'),
('JPN', '撒母耳记上', 9, 26, 9, 'ダビデはアビシャイに言った。「殺してはならない。主に油注がれた方に手を下して、だれが罰を免れるだろうか。」'),
('JPN', '撒母耳记上', 9, 26, 10, 'ダビデは言った。「主は生きておられる。主は必ず彼を打たれる。時が来て死ぬか、戦いに下ったときに滅びるかだ。'),
('JPN', '撒母耳记上', 9, 26, 11, '私が主に逆らって、主に油注がれた方に手を下すなど、絶対にあり得ないことだ。さあ、今は、枕もとにある槍と水差しを取って、ここから出て行こう。」'),
('JPN', '撒母耳记上', 9, 26, 12, 'ダビデはサウルの枕もとの槍と水差しを取り、二人は立ち去ったが、だれ一人としてこれを見た者も、気づいた者も、目を覚ました者もいなかった。主が彼らを深い眠りに陥れられたので、みな眠り込んでいたのである。'),
('JPN', '撒母耳记上', 9, 26, 13, 'ダビデは向こう側へ渡って行き、遠く離れた山の頂上に立った。彼らの間には、大きな隔たりがあった。'),
('JPN', '撒母耳记上', 9, 26, 14, 'ダビデは、兵たちとネルの子アブネルに呼びかけて言った。「アブネル、返事をしないのか。」アブネルは答えて言った。「王を呼びつけるおまえはだれだ。」'),
('JPN', '撒母耳记上', 9, 26, 15, 'ダビデはアブネルに言った。「おまえは男ではないか。イスラエル中で、おまえに並ぶ者があるだろうか。おまえはなぜ、自分の主君である王を護衛していなかったのか。兵の一人が、おまえの主君である王を殺しに入り込んだのだ。'),
('JPN', '撒母耳记上', 9, 26, 16, 'おまえのやったことは良くない。主に誓って言うが、おまえたちは死に値する。おまえたちの主君、主に油注がれた方を護衛していなかったのだから。今、王の枕もとにあった槍と水差しが、どこにあるか見てみよ。」'),
('JPN', '撒母耳记上', 9, 26, 17, 'サウルはダビデの声と気づいて、言った。「わが子ダビデよ、これはおまえの声ではないか。」ダビデは答えた。「わが君、王様。私の声です。」'),
('JPN', '撒母耳记上', 9, 26, 18, 'そして言った。「なぜ、わが君はこのしもべの後を追われるのですか。私が何をしたというのですか。私の手に、どんな悪があるというのですか。'),
('JPN', '撒母耳记上', 9, 26, 19, 'わが君、王様。どうか今、しもべのことばを聞いてください。もし私に敵対するようあなたに誘いかけたのが主であれば、主がささげ物を受け入れられますように。しかし、それが人によるのであれば、その人たちが主の前でのろわれますように。彼らは今日、私を追い払って、主のゆずりの地にあずからせず、『行って、ほかの神々に仕えよ』と言っているからです。'),
('JPN', '撒母耳记上', 9, 26, 20, 'どうか今、私の血が主の御顔から離れた地に流されることがありませんように。イスラエルの王が、山でしゃこを追うように、一匹の蚤を狙って出て来ておられるのですから。」'),
('JPN', '撒母耳记上', 9, 26, 21, 'サウルは言った。「私が間違っていた。わが子ダビデよ、帰って来なさい。もう、おまえに害を加えない。今日、おまえが私のいのちを尊んでくれたのだから。本当に私は愚かなことをして、大変な間違いを犯した。」'),
('JPN', '撒母耳记上', 9, 26, 22, 'ダビデは答えて言った。「さあ、ここに王の槍があります。これを取りに、若者の一人をよこしてください。'),
('JPN', '撒母耳记上', 9, 26, 23, '主は一人ひとりに、その人の正しさと真実に応じて報いてくださいます。主は今日、あなたを私の手に渡されましたが、私は、主に油注がれた方に、この手を下したくはありませんでした。'),
('JPN', '撒母耳记上', 9, 26, 24, '今日、私があなたのいのちを大切にしたように、主は私のいのちを大切にして、すべての苦難から私を救い出してくださいます。」'),
('JPN', '撒母耳记上', 9, 26, 25, 'サウルはダビデに言った。「わが子ダビデよ、おまえに祝福があるように。おまえは多くのことをするだろうが、それはきっと成功する。」ダビデは自分の道を行き、サウルは自分のところへ帰って行った。'),
('JPN', '撒母耳记上', 9, 27, 1, 'ダビデは心の中で言った。「私はいつか、今にサウルの手によって滅ぼされるだろう。ペリシテ人の地に逃れるよりほかに道はない。そうすれば、サウルは、イスラエルの全領土内で私を捜すのをあきらめ、こうして私は彼の手から逃れられる。」'),
('JPN', '撒母耳记上', 9, 27, 2, 'ダビデは、一緒にいた六百人の者を連れて、ガテの王マオクの子アキシュのところへ渡って行った。'),
('JPN', '撒母耳记上', 9, 27, 3, 'ダビデとその部下たちは、それぞれ自分の家族とともに、ガテでアキシュのもとに住んだ。ダビデも、その二人の妻、イズレエル人アヒノアムと、ナバルの妻であったカルメル人アビガイルと一緒であった。'),
('JPN', '撒母耳记上', 9, 27, 4, 'ダビデがガテへ逃げたことが、サウルに知らされると、サウルは二度と彼を追おうとはしなかった。'),
('JPN', '撒母耳记上', 9, 27, 5, 'ダビデはアキシュに言った。「もし、私があなたのご好意を得ているなら、地方の町の一つの場所を私に下さい。そこに住みます。どうして、このしもべが王国の都に、あなたと一緒に住めるでしょう。」'),
('JPN', '撒母耳记上', 9, 27, 6, 'その日、アキシュはツィクラグをダビデに与えた。それゆえ、ツィクラグは今日まで、ユダの王たちに属している。'),
('JPN', '撒母耳记上', 9, 27, 7, 'ダビデがペリシテ人の地に住んでいた日数は一年四か月であった。'),
('JPN', '撒母耳记上', 9, 27, 8, 'ダビデは部下とともに上って行って、ゲシュル人、ゲゼル人、アマレク人を襲った。彼らは昔から、シュルの方、エジプトの地に及ぶ地域に住んでいた。'),
('JPN', '撒母耳记上', 9, 27, 9, 'ダビデはこれらの地方を討つと、男も女も生かしてはおかず、羊、牛、ろば、らくだ、また衣服などを奪って、アキシュのところに帰って来た。'),
('JPN', '撒母耳记上', 9, 27, 10, 'アキシュが「今日は、どこを襲ったのか」と尋ねると、ダビデはいつも、ユダのネゲブとか、エラフメエル人のネゲブとか、ケニ人のネゲブとか答えていた。'),
('JPN', '撒母耳记上', 9, 27, 11, 'ダビデは男も女も生かしておかず、ガテに一人も連れて来なかった。「彼らが『ダビデはこういうことをした』と言って、私たちのことを告げるといけない」と思ったからである。ダビデはペリシテ人の地に住んでいる間、いつも、このようなやり方をした。'),
('JPN', '撒母耳记上', 9, 27, 12, 'アキシュはダビデを信用して、こう思っていた。「彼は自分の同胞イスラエル人に、とても憎まれるようなことをしている。彼はいつまでも私のしもべでいるだろう。」'),
('JPN', '撒母耳记上', 9, 28, 1, 'そのころ、ペリシテ人はイスラエルと戦おうとして、軍隊を召集した。アキシュはダビデに言った。「承知してもらいたい。あなたと、あなたの部下は、私と一緒に出陣することになっている。」'),
('JPN', '撒母耳记上', 9, 28, 2, 'ダビデはアキシュに言った。「では、しもべがどうするか、お分かりになるでしょう。」アキシュはダビデに言った。「では、あなたをいつまでも、私の護衛に任命しておこう。」'),
('JPN', '撒母耳记上', 9, 28, 3, 'サムエルはすでに死に、全イスラエルは彼のために悼み悲しみ、彼を彼の町ラマに葬っていた。一方、サウルは国内から霊媒や口寄せを追い出していた。'),
('JPN', '撒母耳记上', 9, 28, 4, 'ペリシテ人は集まって、シュネムに来て陣を敷いた。サウルは全イスラエルを召集して、ギルボアに陣を敷いた。'),
('JPN', '撒母耳记上', 9, 28, 5, 'サウルはペリシテ人の陣営を見て恐れ、その心は激しく震えた。'),
('JPN', '撒母耳记上', 9, 28, 6, 'サウルは主に伺ったが、主は、夢によっても、ウリムによっても、預言者によってもお答えにならなかった。'),
('JPN', '撒母耳记上', 9, 28, 7, 'サウルは家来たちに言った。「霊媒をする女を探して来い。私が彼女のところに行って、彼女に尋ねてみよう。」家来たちはサウルに言った。「エン・ドルに霊媒をする女がいます。」'),
('JPN', '撒母耳记上', 9, 28, 8, 'サウルは変装して身なりを変え、二人の部下を連れて行った。彼らは夜、女のところにやって来た。サウルは言った。「私のために霊媒によって占い、私のために、私が言う人を呼び出してもらいたい。」'),
('JPN', '撒母耳记上', 9, 28, 9, '女は彼に言った。「あなたは、サウルがこの国から霊媒や口寄せを断ち切ったことをご存じのはずです。それなのに、なぜ、私のいのちに罠をかけて、私を殺そうとするのですか。」'),
('JPN', '撒母耳记上', 9, 28, 10, 'サウルは主にかけて彼女に誓って言った。「主は生きておられる。このことにより、あなたが咎を負うことは決してない。」'),
('JPN', '撒母耳记上', 9, 28, 11, '女は言った。「だれを呼び出しましょうか。」サウルは言った。「私のために、サムエルを呼び出してもらいたい。」'),
('JPN', '撒母耳记上', 9, 28, 12, '女はサムエルを見て大声で叫んだ。女はサウルに言った。「あなたはなぜ、私をだましたのですか。あなたはサウルですね。」'),
('JPN', '撒母耳记上', 9, 28, 13, '王は彼女に言った。「恐れることはない。何を見たのか。」女はサウルに言った。「神々しい方が地から上って来るのを見ました。」'),
('JPN', '撒母耳记上', 9, 28, 14, 'サウルは彼女に尋ねた。「どのような姿をしておられるか。」彼女は言った。「年老いた方が上って来られます。外套を着ておられます。」サウルは、その人がサムエルであることが分かって、地にひれ伏し、拝した。'),
('JPN', '撒母耳记上', 9, 28, 15, 'サムエルはサウルに言った。「なぜ、私を呼び出して、私を煩わすのか。」サウルは言った。「私は困りきっています。ペリシテ人が私を攻めて来るのに、神は私から去っておられます。預言者によっても、夢によっても、もう私に答えてくださらないのです。それで、私がどうすればよいか教えていただくために、あなたをお呼びしました。」'),
('JPN', '撒母耳记上', 9, 28, 16, 'サムエルは言った。「なぜ、私に尋ねるのか。主はあなたから去り、あなたの敵になられたのに。'),
('JPN', '撒母耳记上', 9, 28, 17, '主は、私を通して告げられたとおりのことをなさったのだ。主は、あなたの手から王位をはぎ取って、あなたの友ダビデに与えられた。'),
('JPN', '撒母耳记上', 9, 28, 18, 'あなたが主の御声に聞き従わず、主の燃える御怒りをもってアマレクを罰しなかったからだ。それゆえ、主は今日、このことをあなたにされたのだ。'),
('JPN', '撒母耳记上', 9, 28, 19, '主は、あなたと一緒にイスラエルをペリシテ人の手に渡される。明日、あなたもあなたの息子たちも、私と一緒になるだろう。主は、イスラエルの陣営をペリシテ人の手に渡されるのだ。」'),
('JPN', '撒母耳记上', 9, 28, 20, 'すると、サウルはただちに地面に倒れて棒のようになり、サムエルのことばにおびえた。しかも、その日一昼夜、何も食べていなかったので、力は失せていた。'),
('JPN', '撒母耳记上', 9, 28, 21, '女はサウルのところに来て、サウルが非常におじ惑っているのを見て彼に言った。「あなたのはしためは、あなたが言われたことに聞き従いました。私はいのちをかけて、あなたが言われたことばに従いました。'),
('JPN', '撒母耳记上', 9, 28, 22, '今度はあなたが、このはしためが申し上げることをお聞きください。パンを少し差し上げます。それをお食べください。お帰りのとき、元気になられるでしょう。」'),
('JPN', '撒母耳记上', 9, 28, 23, 'サウルはこれを断って、「食べたくない」と言った。しかし、彼の家来も女もしきりに勧めたので、サウルはその言うことを聞き入れて地面から立ち上がり、床の上に座った。'),
('JPN', '撒母耳记上', 9, 28, 24, '女の家に肥えた子牛がいたので、彼女は急いでそれを屠り、また、小麦粉を取って練り、種なしパンを焼いた。'),
('JPN', '撒母耳记上', 9, 28, 25, 'それをサウルと家来たちの前に差し出すと、彼らは食べた。そしてその夜、彼らは立ち去った。'),
('JPN', '撒母耳记上', 9, 29, 1, 'ペリシテ人は全軍をアフェクに集結し、イスラエル人はイズレエルにある泉のほとりに陣を敷いた。'),
('JPN', '撒母耳记上', 9, 29, 2, 'ペリシテ人の領主たちは、百人隊、千人隊を率いて進み、ダビデとその部下は、アキシュと一緒にその後に続いた。'),
('JPN', '撒母耳记上', 9, 29, 3, 'ペリシテ人の首長たちは言った。「このヘブル人たちは、いったい何なのですか。」アキシュはペリシテ人の首長たちに言った。「確かにこれは、イスラエルの王サウルの家来ダビデであるが、この一、二年、私のところにいる。私のところに落ちのびて来てから今日まで、私は彼に何の過ちも見出していない。」'),
('JPN', '撒母耳记上', 9, 29, 4, 'ペリシテ人の首長たちはアキシュに対して腹を立てた。ペリシテ人の首長たちは彼に言った。「この男を帰らせてほしい。あなたが指定した場所に帰し、私たちと一緒に戦いに行かせないでほしい。戦いの最中に、われわれに敵対する者となってはいけない。この男は、どのようにして自分の主君の好意を得るだろうか。ここにいる人たちの首を使わないだろうか。'),
('JPN', '撒母耳记上', 9, 29, 5, 'この男は、皆が踊りながら、『サウルは千を討ち、ダビデは万を討った』と歌っていたダビデではないか。」'),
('JPN', '撒母耳记上', 9, 29, 6, 'そこでアキシュはダビデを呼んで言った。「主は生きておられる。あなたは真っ直ぐな人だ。あなたには陣営で、私と行動をともにしてもらいたかった。あなたが私のところに来てから今日まで、あなたには何の悪いところも見つけなかったからだ。しかし、あの領主たちは、あなたを良いと思っていない。'),
('JPN', '撒母耳记上', 9, 29, 7, 'だから今、穏やかに帰ってくれ。ペリシテ人の領主たちが気に入らないことはしないでくれ。」'),
('JPN', '撒母耳记上', 9, 29, 8, 'ダビデはアキシュに言った。「私が何をしたというのですか。あなたに仕えた日から今日まで、しもべに何か過ちでも見出されたのですか。わが君、王様の敵と戦うために私が出陣できないとは。」'),
('JPN', '撒母耳记上', 9, 29, 9, 'アキシュはダビデに答えて言った。「私は、あなたが神の使いのように正しいということをよく知っている。だが、ペリシテ人の首長たちが『彼はわれわれと一緒に戦いに行ってはならない』と言ったのだ。'),
('JPN', '撒母耳记上', 9, 29, 10, 'さあ、一緒に来た自分の主君の家来たちと、明日の朝早く起きなさい。朝早く、明るくなり次第出発しなさい。」'),
('JPN', '撒母耳记上', 9, 29, 11, 'ダビデとその部下は、翌朝早く、ペリシテ人の地へ帰って行った。ペリシテ人はイズレエルへ上って行った。'),
('JPN', '撒母耳记上', 9, 30, 1, 'ダビデとその部下が三日目にツィクラグに帰ったとき、アマレク人はすでに、ネゲブとツィクラグを襲っていた。彼らはツィクラグを攻撃して、これを火で焼き払い、'),
('JPN', '撒母耳记上', 9, 30, 2, 'そこにいた女たちを、子どもも大人もみな捕らえ、一人も殺さず、自分たちのところへと連れ去っていた。'),
('JPN', '撒母耳记上', 9, 30, 3, 'ダビデとその部下が町に着いたとき、なんと、町は火で焼かれていて、彼らの妻も息子も娘も連れ去られていた。'),
('JPN', '撒母耳记上', 9, 30, 4, 'ダビデも、彼と一緒にいた兵たちも、声をあげて泣き、ついには泣く力もなくなった。'),
('JPN', '撒母耳记上', 9, 30, 5, 'ダビデの二人の妻、イズレエル人アヒノアムも、ナバルの妻であったカルメル人アビガイルも連れ去られていた。'),
('JPN', '撒母耳记上', 9, 30, 6, 'ダビデは大変な苦境に立たされた。兵がみな、自分たちの息子、娘たちのことで心を悩ませ、ダビデを石で打ち殺そうと言い出したからだった。しかし、ダビデは自分の神、主によって奮い立った。'),
('JPN', '撒母耳记上', 9, 30, 7, 'ダビデは、アヒメレクの子、祭司エブヤタルに言った。「エポデを持って来なさい。」エブヤタルはエポデをダビデのところに持って来た。'),
('JPN', '撒母耳记上', 9, 30, 8, 'ダビデは主に伺った。「あの略奪隊を追うべきでしょうか。追いつけるでしょうか。」すると、お答えになった。「追え。必ず追いつくことができる。必ず救い出すことができる。」'),
('JPN', '撒母耳记上', 9, 30, 9, 'ダビデは六百人の部下とともに出て行き、ベソル川まで来た。残ることになった者は、そこにとどまった。'),
('JPN', '撒母耳记上', 9, 30, 10, 'ダビデと四百人の者は追撃を続け、疲れきってベソル川を渡れなかった二百人の者が、そこにとどまった。'),
('JPN', '撒母耳记上', 9, 30, 11, '兵たちは野で一人のエジプト人を見つけ、ダビデのところに連れて来た。彼らは彼にパンをやって、食べさせ、水も飲ませた。'),
('JPN', '撒母耳记上', 9, 30, 12, 'さらに、ひとかたまりの干しいちじくと、二房の干しぶどうをやると、そのエジプト人はそれを食べて元気を回復した。彼は三日三晩、パンも食べず、水も飲んでいなかったのである。'),
('JPN', '撒母耳记上', 9, 30, 13, 'ダビデは彼に言った。「おまえはだれのものか。どこから来たのか。」すると答えた。「私はエジプトの若者で、アマレク人の奴隷です。私が三日前に病気になったので、主人は私を置き去りにしたのです。'),
('JPN', '撒母耳记上', 9, 30, 14, '私たちは、クレタ人のネゲブと、ユダに属する地と、カレブのネゲブを襲い、ツィクラグを火で焼き払いました。」'),
('JPN', '撒母耳记上', 9, 30, 15, 'ダビデは彼に言った。「その略奪隊のところに案内できるか。」彼は言った。「私を殺さず、主人の手に私を渡さないと、神にかけて私に誓ってください。そうすれば、あの略奪隊のところに案内いたします。」'),
('JPN', '撒母耳记上', 9, 30, 16, '彼はダビデを案内して行った。すると、なんと、アマレク人たちはその地いっぱいに散って食べたり飲んだりし、お祭り騒ぎをしていた。彼らがペリシテ人の地やユダの地から奪った分捕り物が、とても多かったからである。'),
('JPN', '撒母耳记上', 9, 30, 17, 'ダビデは、その夕暮れから次の夕方まで彼らを討った。らくだに乗って逃げた四百人の若者たちのほかは、一人も逃れることができなかった。'),
('JPN', '撒母耳记上', 9, 30, 18, 'ダビデは、アマレクが奪い取ったものをすべて取り戻した。ダビデは、二人の妻も救い出した。'),
('JPN', '撒母耳记上', 9, 30, 19, '子どもも大人も、息子たちも娘たちも、分捕られた物も、彼らが奪われたものは、何一つ失われなかった。ダビデは、これらすべてを取り返した。'),
('JPN', '撒母耳记上', 9, 30, 20, 'ダビデはまた、すべての羊と牛を奪った。兵たちは家畜の先に立って導き、「これはダビデの戦勝品だ」と言った。'),
('JPN', '撒母耳记上', 9, 30, 21, 'ダビデは、疲れてダビデについて来ることができずにベソル川のほとりにとどまっていた二百人の者のところに来た。彼らは、ダビデと彼に従った者たちを迎えに出て来た。ダビデは、この人たちに近づいて彼らの安否を尋ねた。'),
('JPN', '撒母耳记上', 9, 30, 22, 'ダビデと一緒に行った者たちのうち、意地の悪い、よこしまな者たちがみな、口々に言った。「彼らは一緒に行かなかったのだから、われわれが取り戻した分捕り物は、分けてやるわけにはいかない。ただ、それぞれ自分の妻と子どもを連れて行くがよい。」'),
('JPN', '撒母耳记上', 9, 30, 23, 'ダビデは言った。「兄弟たちよ。主が私たちに下さった物を、そのようにしてはならない。主が私たちを守り、私たちを襲った略奪隊を私たちの手に渡されたのだ。'),
('JPN', '撒母耳记上', 9, 30, 24, 'だれが、このことについて、あなたがたの言うことを聞くだろうか。戦いに下って行った者への分け前も、荷物のそばにとどまっていた者への分け前も同じだ。ともに同じく分け合わなければならない。」'),
('JPN', '撒母耳记上', 9, 30, 25, 'その日以来、ダビデはこれをイスラエルの掟とし、定めとした。今日もそうである。'),
('JPN', '撒母耳记上', 9, 30, 26, 'ダビデはツィクラグに帰って来て、友人であるユダの長老たちに戦勝品の一部を送って言った。「これはあなたがたへの贈り物で、主の敵からの戦勝品の一部です。」'),
('JPN', '撒母耳记上', 9, 30, 27, 'その送り先は、ベテルの人々、ラモテ・ネゲブの人々、ヤティルの人々、'),
('JPN', '撒母耳记上', 9, 30, 28, 'アロエルの人々、シフモテの人々、エシュテモアの人々、'),
('JPN', '撒母耳记上', 9, 30, 29, 'ラカルの人々、エラフメエル人の町々の人々、ケニ人の町々の人々、'),
('JPN', '撒母耳记上', 9, 30, 30, 'ホルマの人々、ボル・アシャンの人々、アタクの人々、'),
('JPN', '撒母耳记上', 9, 30, 31, 'ヘブロンの人々、すなわち、ダビデとその部下がさまよい歩いたすべての場所の人々であった。'),
('JPN', '撒母耳记上', 9, 31, 1, 'さて、ペリシテ人はイスラエルと戦った。イスラエルの人々はペリシテ人の前から逃げ、ギルボア山で刺されて倒れた。'),
('JPN', '撒母耳记上', 9, 31, 2, 'ペリシテ人はサウルとその息子たちに追い迫って、サウルの息子ヨナタン、アビナダブ、マルキ・シュアを打ち殺した。'),
('JPN', '撒母耳记上', 9, 31, 3, '攻撃はサウルに集中し、射手たちが彼を狙い撃ちにしたので、彼は射手たちのゆえにひどい傷を負った。'),
('JPN', '撒母耳记上', 9, 31, 4, 'サウルは道具持ちに言った。「おまえの剣を抜いて、私を刺し殺してくれ。さもないと、あの無割礼の者たちがやって来て、私を刺し殺し、私をなぶりものにするだろう。」しかし、道具持ちは非常に恐れて、とうていその気になれなかった。それでサウルは剣を取り、その上に倒れ込んだ。'),
('JPN', '撒母耳记上', 9, 31, 5, '道具持ちは、サウルが死んだのを見ると、自分も剣の上に身を伏せて、サウルとともに死んだ。'),
('JPN', '撒母耳记上', 9, 31, 6, 'こうしてその日、サウルと三人の息子、道具持ち、それに彼の部下たちはみな、ともに死んだ。'),
('JPN', '撒母耳记上', 9, 31, 7, '谷の向こう側とヨルダン川の向こう側にいたイスラエルの人々は、イスラエルの兵士たちが逃げ、サウルとその息子たちが死んだのを見て、町々を捨てて逃げた。それで、ペリシテ人がやって来て、そこに住んだ。'),
('JPN', '撒母耳记上', 9, 31, 8, '翌日、ペリシテ人が、刺し殺された者たちからはぎ取ろうとしてやって来たとき、サウルと三人の息子たちがギルボア山で倒れているのを見つけた。'),
('JPN', '撒母耳记上', 9, 31, 9, '彼らはサウルの首を切り、彼の武具をはぎ取った。そして、ペリシテ人の地の隅々にまで人を送り、彼らの偶像の宮と民とに告げ知らせた。'),
('JPN', '撒母耳记上', 9, 31, 10, '彼らはサウルの武具をアシュタロテの神殿に奉納し、彼の死体はベテ・シャンの城壁にさらした。'),
('JPN', '撒母耳记上', 9, 31, 11, 'ヤベシュ・ギルアデの住民は、ペリシテ人がサウルに行った仕打ちを聞いた。'),
('JPN', '撒母耳记上', 9, 31, 12, 'そこで勇士たちはみな立ち上がり、夜通し歩いて行き、サウルの死体と息子たちの死体をベテ・シャンの城壁から取り下ろし、ヤベシュに帰って来て、そこでそれらを焼いた。'),
('JPN', '撒母耳记上', 9, 31, 13, '彼らはその骨を取って、ヤベシュにあるタマリスクの木の下に葬り、七日間、断食した。'),
('JPN', '撒母耳记下', 10, 1, 1, 'サウルが死んだとき、ダビデはアマレク人を打ち破って帰って来ていた。その後ダビデは二日間、ツィクラグにとどまっていた。'),
('JPN', '撒母耳记下', 10, 1, 2, 'すると三日目に、見よ、一人の男がサウルのいた陣営からやって来た。衣は裂け、頭には土をかぶっていた。彼はダビデのところに来ると、地にひれ伏して礼をした。'),
('JPN', '撒母耳记下', 10, 1, 3, 'ダビデは言った。「どこから来たのか。」彼は言った。「イスラエルの陣営から逃れて来ました。」'),
('JPN', '撒母耳记下', 10, 1, 4, 'ダビデは彼に言った。「状況はどうか。話してくれ。」彼は言った。「兵たちは戦場から逃げ、しかも兵たちの多くの者が倒れて死にました。それに、サウルも、その子ヨナタンも死にました。」'),
('JPN', '撒母耳记下', 10, 1, 5, 'ダビデは、報告をもたらしたその若い者に言った。「サウルとその子ヨナタンが死んだことを、どのようにして知ったのか。」'),
('JPN', '撒母耳记下', 10, 1, 6, '報告をもたらしたその若い者は言った。「私は、たまたまギルボア山にいましたが、見ると、サウルは自分の槍にもたれ、戦車と騎兵が押し迫っていました。'),
('JPN', '撒母耳记下', 10, 1, 7, 'サウルが振り返って、私を見て呼びました。私が『はい』と答えると、'),
('JPN', '撒母耳记下', 10, 1, 8, '私に『おまえはだれだ』と言いましたので、『私はアマレク人です』と答えますと、'),
('JPN', '撒母耳记下', 10, 1, 9, '『さあ、近寄って、私を殺してくれ。激しいけいれんが起こっているが、息はまだ十分あるから』と言いました。'),
('JPN', '撒母耳记下', 10, 1, 10, '私は近寄って、あの方を殺しました。もう倒れて生き延びることができないと分かったからです。私は、頭にあった王冠と、腕に付いていた腕輪を取って、ここに、あなた様のところに持って参りました。」'),
('JPN', '撒母耳记下', 10, 1, 11, 'ダビデは自分の衣をつかんで引き裂いた。ともにいた家来たちもみな、そのようにした。'),
('JPN', '撒母耳记下', 10, 1, 12, '彼らは、サウルのため、その子ヨナタンのため、また主の民のため、イスラエルの家のために悼み悲しんで泣き、夕方まで断食した。サウルらが剣に倒れたからである。'),
('JPN', '撒母耳记下', 10, 1, 13, 'ダビデは自分に報告したその若い者に言った。「おまえはどこの者か。」彼は言った。「私はアマレク人で、寄留者の子です。」'),
('JPN', '撒母耳记下', 10, 1, 14, 'ダビデは彼に言った。「主に油注がれた方に手を下して殺すのを恐れなかったとは、どうしたことか。」'),
('JPN', '撒母耳记下', 10, 1, 15, 'ダビデは家来の一人を呼んで言った。「これに討ちかかれ。」彼がその若い者を討ったので、若い者は死んだ。'),
('JPN', '撒母耳记下', 10, 1, 16, 'ダビデは若い者に言った。「おまえの血は、おまえの頭上に降りかかれ。おまえ自身の口で、『私は主に油注がれた方を殺した』と証言したのだから。」'),
('JPN', '撒母耳记下', 10, 1, 17, 'ダビデは、サウルのため、その息子ヨナタンのために、次の哀歌を歌った。'),
('JPN', '撒母耳记下', 10, 1, 18, 'これはユダの子らに弓を教えるためのもので、『ヤシャルの書』にまさしく記されている。'),
('JPN', '撒母耳记下', 10, 1, 19, '「イスラエルよ、君主はおまえの高き所で殺された。ああ、勇士たちは倒れた。'),
('JPN', '撒母耳记下', 10, 1, 20, 'これをガテに告げるな。アシュケロンの通りに告げ知らせるな。ペリシテ人の娘らを喜ばせないために。無割礼の者の娘らが喜び躍ることがないために。'),
('JPN', '撒母耳记下', 10, 1, 21, 'ギルボアの山よ。高原の野よ。おまえたちの上に、露は降りるな。雨も降るな。そこでは勇士たちの盾が汚され、サウルの盾に油も塗られなかったからだ。'),
('JPN', '撒母耳记下', 10, 1, 22, '殺された者の血から、勇士たちの脂から、ヨナタンの弓は退くことがなく、サウルの剣も、空しく帰ることがなかった。'),
('JPN', '撒母耳记下', 10, 1, 23, 'サウルもヨナタンも、愛される、立派な人だった。生きているときも死ぬときも、二人は離れることはなく、鷲よりも速く、雄獅子よりも強かった。'),
('JPN', '撒母耳记下', 10, 1, 24, 'イスラエルの娘たちよ、サウルのために泣け。サウルは、紅の衣を華やかにおまえたちに着せ、おまえたちの装いに金の飾りを着けてくれた。'),
('JPN', '撒母耳记下', 10, 1, 25, 'ああ、勇士たちは戦いのさなかに倒れた。ヨナタンはおまえの高き所で殺された。'),
('JPN', '撒母耳记下', 10, 1, 26, 'あなたのために私はいたく悲しむ。私の兄弟ヨナタンよ。あなたは私を大いに喜び楽しませ、あなたの愛は、私にとって女の愛にもまさって、すばらしかった。'),
('JPN', '撒母耳记下', 10, 1, 27, 'ああ、勇士たちは倒れた。戦いの器は失せた。」'),
('JPN', '撒母耳记下', 10, 2, 1, 'この後、ダビデは主に伺った。「ユダの町のどれか一つへ上って行くべきでしょうか。」主は彼に「上って行け」と言われた。ダビデは、「どこに上ればよいでしょうか」と聞いた。主は「ヘブロンに」と言われた。'),
('JPN', '撒母耳记下', 10, 2, 2, 'ダビデは、二人の妻、イズレエル人アヒノアムと、カルメル人ナバルの妻であったアビガイルと一緒に、そこに上って行った。'),
('JPN', '撒母耳记下', 10, 2, 3, 'ダビデは、自分とともにいた人々を、その家族ごと連れて上った。彼らはヘブロンの町々に住んだ。'),
('JPN', '撒母耳记下', 10, 2, 4, 'ユダの人々がやって来て、そこでダビデに油を注ぎ、ユダの家の王とした。ヤベシュ・ギルアデの人々がサウルを葬ったことが、ダビデに知らされたとき、'),
('JPN', '撒母耳记下', 10, 2, 5, 'ダビデはヤベシュ・ギルアデの人々に使者たちを遣わし、彼らに言った。「あなたがたが主に祝福されるように。あなたがたは、あのような真実を尽くして主君サウルを葬った。'),
('JPN', '撒母耳记下', 10, 2, 6, '今、主があなたがたに恵みとまことを施してくださるように。あなたがたがそのようなことをしたので、この私もあなたがたに善をもって報いよう。'),
('JPN', '撒母耳记下', 10, 2, 7, '今、強くあれ。勇気ある者となれ。あなたがたの主君サウルは死んだが、ユダの家は私に油を注いで、自分たちの王としたからだ。」'),
('JPN', '撒母耳记下', 10, 2, 8, '一方、サウルの軍の長であったネルの子アブネルは、サウルの子イシュ・ボシェテを連れてマハナイムに行き、'),
('JPN', '撒母耳记下', 10, 2, 9, '彼をギルアデ、アッシュル人、およびイズレエル、そしてエフライムとベニヤミン、すなわち全イスラエルの王とした。'),
('JPN', '撒母耳记下', 10, 2, 10, 'サウルの子イシュ・ボシェテは、四十歳でイスラエルの王となり、二年間、王であった。しかし、ユダの家だけはダビデに従った。'),
('JPN', '撒母耳记下', 10, 2, 11, 'ダビデがヘブロンでユダの家の王であった期間は、七年六か月であった。'),
('JPN', '撒母耳记下', 10, 2, 12, 'ネルの子アブネルは、サウルの子イシュ・ボシェテの家来たちと一緒にマハナイムを出て、ギブオンへ向かった。'),
('JPN', '撒母耳记下', 10, 2, 13, '一方、ツェルヤの子ヨアブも、ダビデの家来たちと一緒に出て行った。こうして彼らはギブオンの池のそばで出会った。一方は池の手前側に、もう一方は池の向こう側にとどまった。'),
('JPN', '撒母耳记下', 10, 2, 14, 'アブネルはヨアブに言った。「さあ、若い者たちを出し、われわれの前で闘技をさせよう。」ヨアブは言った。「よし、そうしよう。」'),
('JPN', '撒母耳记下', 10, 2, 15, 'ベニヤミンの側、すなわちサウルの子イシュ・ボシェテの側から十二人、ダビデの家来たちから十二人が順番に出て行った。'),
('JPN', '撒母耳记下', 10, 2, 16, '彼らは互いに相手の頭をつかみ、相手の脇腹に剣を刺し、一つになって倒れた。それで、その場所はヘルカテ・ハ・ツリムと呼ばれた。それはギブオンにある。'),
('JPN', '撒母耳记下', 10, 2, 17, 'その日、戦いは激しさを極め、アブネルとイスラエルの兵士たちは、ダビデの家来たちに打ち負かされた。'),
('JPN', '撒母耳记下', 10, 2, 18, 'そこに、ツェルヤの三人の息子、ヨアブ、アビシャイ、アサエルがいた。アサエルは野のかもしかのように、足が速かった。'),
('JPN', '撒母耳记下', 10, 2, 19, 'アサエルはアブネルの後を追った。右にも左にもそれずに、アブネルを追った。'),
('JPN', '撒母耳记下', 10, 2, 20, 'アブネルは振り向いて言った。「おまえはアサエルか。」彼は答えた。「そうだ。」'),
('JPN', '撒母耳记下', 10, 2, 21, 'アブネルは彼に言った。「右か左にそれ、若い者の一人を捕らえ、その者からはぎ取れ。」しかしアサエルは、アブネルを追うのをやめず、ほかへ行こうとしなかった。'),
('JPN', '撒母耳记下', 10, 2, 22, 'アブネルはもう一度アサエルに言った。「私を追うのはやめ、ほかへ行け。なぜ、私がおまえを地に打ち倒さなければならないのか。どうやって、おまえの兄ヨアブに顔向けができるというのか。」'),
('JPN', '撒母耳记下', 10, 2, 23, 'アサエルはなおも拒んで、ほかへ行こうとしなかった。それでアブネルは、槍の石突きで彼の下腹を突いた。槍はアサエルを突き抜けた。アサエルはその場に倒れて、そこで死んだ。アサエルが倒れて死んだ場所に来た者はみな、立ち止まった。'),
('JPN', '撒母耳记下', 10, 2, 24, 'しかしヨアブとアビシャイは、アブネルの後を追った。太陽が沈んだとき、彼ら二人はギブオンの荒野への道を通り、ギアハの反対側にあるアンマの丘までやって来た。'),
('JPN', '撒母耳记下', 10, 2, 25, 'ベニヤミン人はアブネルに従って集まり、一団となって、一つの丘の頂に立った。'),
('JPN', '撒母耳记下', 10, 2, 26, 'アブネルはヨアブに呼びかけて言った。「いつまでも剣が人を食い尽くしてよいものか。その果ては、ひどいことになるのを知らないのか。いつになったら、兵たちに、自分の兄弟たちを追うのをやめて帰れ、と命じるつもりか。」'),
('JPN', '撒母耳记下', 10, 2, 27, 'ヨアブは言った。「神は生きておられる。もし、おまえが言い出さなかったなら、確かに兵たちは、明日の朝まで、それぞれ自分の兄弟たちを追うのをやめなかっただろう。」'),
('JPN', '撒母耳记下', 10, 2, 28, 'ヨアブは角笛を吹いた。それで兵たちはみな立ち止まり、それ以上イスラエルの後を追わず、戦いを続けることはなかった。'),
('JPN', '撒母耳记下', 10, 2, 29, 'アブネルとその部下たちは、一晩中アラバを通って行った。そしてヨルダン川を渡り、午前中歩き続けてマハナイムに着いた。'),
('JPN', '撒母耳记下', 10, 2, 30, '一方、ヨアブはアブネルを追うのをやめて帰った。兵たちを全部集めてみると、ダビデの家来十九人とアサエルがいなかった。'),
('JPN', '撒母耳记下', 10, 2, 31, 'ダビデの家来たちは、アブネルの部下であるベニヤミン人のうち三百六十人を討ち取っていた。'),
('JPN', '撒母耳记下', 10, 2, 32, '彼らはアサエルを運んで、ベツレヘムにある彼の父の墓に葬った。ヨアブとその部下たちは一晩中歩いて、夜明けごろヘブロンに着いた。'),
('JPN', '撒母耳记下', 10, 3, 1, 'サウルの家とダビデの家の間には、長く戦いが続いた。ダビデはますます強くなり、サウルの家はますます弱くなった。'),
('JPN', '撒母耳记下', 10, 3, 2, 'ダビデにはヘブロンで子が生まれた。長子はイズレエル人アヒノアムによるアムノン。'),
('JPN', '撒母耳记下', 10, 3, 3, '次男はカルメル人ナバルの妻であったアビガイルによるキルアブ。三男はゲシュルの王タルマイの娘マアカの子アブサロム。'),
('JPN', '撒母耳记下', 10, 3, 4, '四男はハギテの子アドニヤ。五男はアビタルの子シェファテヤ。'),
('JPN', '撒母耳记下', 10, 3, 5, '六男はダビデの妻エグラによるイテレアム。これらの子がヘブロンでダビデに生まれた。'),
('JPN', '撒母耳记下', 10, 3, 6, 'サウルの家とダビデの家が戦っている間に、アブネルがサウルの家で勢力を増していた。'),
('JPN', '撒母耳记下', 10, 3, 7, 'サウルには、アヤの娘で、名をリツパという側女がいた。イシュ・ボシェテはアブネルに言った。「あなたはなぜ、私の父の側女と通じたのか。」'),
('JPN', '撒母耳记下', 10, 3, 8, 'アブネルはイシュ・ボシェテのことばを聞くと、激しく怒って言った。「この私がユダの犬のかしらだとでも言うのか。今日、私はあなたの父サウルの家と、その兄弟と友人たちに真実を尽くして、あなたをダビデの手に渡さないでいる。それなのに今日、あなたは、あの女のことで私をとがめるのか。'),
('JPN', '撒母耳记下', 10, 3, 9, '主がダビデに誓われたとおりのことを、もし私がダビデのために果たさなかったなら、神がこのアブネルを幾重にも罰せられるように。'),
('JPN', '撒母耳记下', 10, 3, 10, 'それは、サウルの家から王位を移し、ダビデの王座を、ダンからベエル・シェバに至るイスラエルとユダの上に堅く立てるということだ。」'),
('JPN', '撒母耳记下', 10, 3, 11, 'イシュ・ボシェテはアブネルを恐れていたので、彼に、もはや一言も返すことができなかった。'),
('JPN', '撒母耳记下', 10, 3, 12, 'アブネルはダビデのところに使者を遣わして言った。「この国はだれのものでしょうか。私と契約を結んでください。ご覧ください。私は全イスラエルをあなたに移すのに協力します。」'),
('JPN', '撒母耳记下', 10, 3, 13, 'ダビデは言った。「よろしい。あなたと契約を結ぼう。しかし、条件が一つある。それは、あなたが私に会いに来るときは、まずサウルの娘ミカルを連れて来ること、そうでなければ私に会えないということだ。」'),
('JPN', '撒母耳记下', 10, 3, 14, 'ダビデはサウルの子イシュ・ボシェテに使者を遣わして言った。「私がペリシテ人の陽の皮百をもってめとった、私の妻ミカルを返していただきたい。」'),
('JPN', '撒母耳记下', 10, 3, 15, 'イシュ・ボシェテは人を遣わして、彼女をその夫、ライシュの子パルティエルから取り返した。'),
('JPN', '撒母耳记下', 10, 3, 16, '彼女の夫は泣きながら彼女の後を追ってバフリムまで来たが、アブネルが「行け。帰れ」と言ったので、彼は帰った。'),
('JPN', '撒母耳记下', 10, 3, 17, 'アブネルはイスラエルの長老たちと話してこう言った。「あなたがたは、かねてから、ダビデを自分たちの王とすることを願っていた。'),
('JPN', '撒母耳记下', 10, 3, 18, '今、それをしなさい。主がダビデについて、『わたしのしもべダビデの手によって、わたしはわたしの民イスラエルをペリシテ人の手、およびすべての敵の手から救う』と言われたからだ。」'),
('JPN', '撒母耳记下', 10, 3, 19, 'アブネルはまた、ベニヤミン人とじかに話し合った。それから、アブネルはまた、ヘブロンにいるダビデのところへ行き、イスラエルとベニヤミンの家全体が良いと思っていることを、すべて彼の耳に入れた。'),
('JPN', '撒母耳记下', 10, 3, 20, 'アブネルは二十人の部下とともにヘブロンのダビデのもとに来た。ダビデはアブネルとその部下のために祝宴を張った。'),
('JPN', '撒母耳记下', 10, 3, 21, 'アブネルはダビデに言った。「私は、全イスラエルをわが主、王のもとに集めに出かけます。彼らがあなたと契約を結び、あなたが、お望みどおりに王として治められるようにいたしましょう。」ダビデはアブネルを送り出し、アブネルは安心して出て行った。'),
('JPN', '撒母耳记下', 10, 3, 22, 'ちょうどそこへ、ダビデの家来たちとヨアブが略奪から帰り、たくさんの分捕り物を持って来た。しかし、アブネルはヘブロンのダビデのもとにはいなかった。ダビデがアブネルを送り出し、もう安心して出て行っていたからである。'),
('JPN', '撒母耳记下', 10, 3, 23, 'ヨアブと、彼とともにいた軍勢がみな帰って来たとき、「ネルの子アブネルが王のところに来たが、王がアブネルを送り出したので、彼は安心して出て行った」とヨアブに知らせる者があった。'),
('JPN', '撒母耳记下', 10, 3, 24, 'ヨアブは王のところに来て言った。「何ということをなさったのですか。ご覧ください。アブネルがあなたのところに来たのです。なぜ、彼を送り出して、出て行くままにされたのですか。'),
('JPN', '撒母耳记下', 10, 3, 25, 'あなたはネルの子アブネルのことをご存じのはずです。彼はあなたを惑わし、あなたの動静を探り、あなたのなさることを残らず知るために来たのです。」'),
('JPN', '撒母耳记下', 10, 3, 26, 'ヨアブはダビデのもとを出てから使者を遣わし、アブネルの後を追わせ、彼をシラの井戸から連れ戻させた。しかし、ダビデはそのことを知らなかった。'),
('JPN', '撒母耳记下', 10, 3, 27, 'アブネルはヘブロンに戻った。ヨアブは彼とひそかに話そうと、彼を門の内側に連れ込み、そこで彼の下腹を刺した。こうして、アブネルは、彼がヨアブの弟アサエルの血を流したことのゆえに死んだ。'),
('JPN', '撒母耳记下', 10, 3, 28, '後になって、ダビデはそのことを聞いて言った。「ネルの子アブネルの血については、私も私の王国も、主の前にとこしえまで潔白である。'),
('JPN', '撒母耳记下', 10, 3, 29, 'その血は、ヨアブの頭と彼の父の家の全員に降りかかるように。またヨアブの家には、漏出を病む者、皮膚をツァラアトに冒される者、糸巻きをつかむ者、剣で倒れる者、食に飢える者が絶えないように。」'),
('JPN', '撒母耳记下', 10, 3, 30, 'ヨアブとその兄弟アビシャイがアブネルを殺したのは、アブネルが彼らの弟アサエルをギブオンでの戦いで殺したからであった。'),
('JPN', '撒母耳记下', 10, 3, 31, 'ダビデは、ヨアブと彼とともにいたすべての兵に言った。「あなたがたの衣を引き裂き、粗布をまとい、アブネルの前で悼み悲しみなさい。」そして、ダビデ王は棺の後をついて行った。'),
('JPN', '撒母耳记下', 10, 3, 32, '彼らはアブネルをヘブロンに葬った。王はアブネルの墓で声をあげて泣き、民もみな泣いた。'),
('JPN', '撒母耳记下', 10, 3, 33, '王はアブネルのために哀歌を歌った。「愚か者が死ぬように、アブネルは死ななければならなかったのか。'),
('JPN', '撒母耳记下', 10, 3, 34, 'あなたの手足は縛られず、かせにもつながれずに。不正な者の前に倒れるように、あなたは倒れてしまったのか。」民はみな、さらに続けて彼のために泣いた。'),
('JPN', '撒母耳记下', 10, 3, 35, '民はみな、まだ日のあるうちにダビデに食事をとらせようとしてやって来たが、ダビデはこう誓った。「もし私が、日の沈む前に、パンでもほかの何でも口にすることがあれば、神がこの私を幾重にも罰せられますように。」'),
('JPN', '撒母耳记下', 10, 3, 36, '民はみな、そのことを認めて、それで良いと思った。王のしたことはすべて、民を満足させた。'),
('JPN', '撒母耳记下', 10, 3, 37, '民はみな、そして全イスラエルは、その日、ネルの子アブネルを殺したのは、王から出たことではないことを知った。'),
('JPN', '撒母耳记下', 10, 3, 38, '王は自分の家来たちに言った。「今日、イスラエルで一人の偉大な軍の将が倒れたのを知らないのか。'),
('JPN', '撒母耳记下', 10, 3, 39, 'この私は油注がれた王であるが、今日の私は無力だ。ツェルヤの子であるこれらの者たちは、私にとっては手ごわすぎる。主が、悪を行う者に、その悪にしたがって報いてくださるように。」'),
('JPN', '撒母耳记下', 10, 4, 1, 'サウルの子イシュ・ボシェテは、アブネルがヘブロンで死んだことを聞いて、気力を失った。全イスラエルもおじ惑った。'),
('JPN', '撒母耳记下', 10, 4, 2, 'サウルの子イシュ・ボシェテのもとに、二人の略奪隊の隊長がいた。一人の名はバアナ、もう一人の名はレカブといって、二人ともベニヤミン族のベエロテ人リンモンの息子であった。ベエロテもベニヤミンに属すると見なされていたのである。'),
('JPN', '撒母耳记下', 10, 4, 3, 'ベエロテ人はギタイムに逃げて、そこで寄留者となった。今日もそうである。'),
('JPN', '撒母耳记下', 10, 4, 4, 'さて、サウルの子ヨナタンに、足の不自由な息子が一人いた。その子が五歳のときのこと、サウルとヨナタンの悲報がイズレエルからもたらされ、彼の乳母は彼を抱いて逃げた。そのとき、あまりに急いで逃げたので、彼を落としてしまった。そのために足の萎えた者になったのであった。彼の名はメフィボシェテといった。'),
('JPN', '撒母耳记下', 10, 4, 5, 'さて、ベエロテ人リンモンの子のレカブとバアナが、日盛りのころ、イシュ・ボシェテの家にやって来た。そのとき、イシュ・ボシェテは昼寝をしていた。'),
('JPN', '撒母耳记下', 10, 4, 6, '彼らはやって来て、小麦を扱う者として家の中まで入り込み、彼の下腹を突いた。レカブとその兄弟バアナは逃げた。'),
('JPN', '撒母耳记下', 10, 4, 7, 'すなわち、彼らが家に入ったとき、イシュ・ボシェテが寝室の寝床で寝ていたので、彼らは彼を突き殺して首をはねた。彼らはその首を持って、一晩中アラバへの道を歩いて行った。'),
('JPN', '撒母耳记下', 10, 4, 8, '彼らはイシュ・ボシェテの首をヘブロンのダビデのもとに持って来て、王に言った。「ご覧ください。これは、あなたのいのちを狙っていたあなたの敵、サウルの子イシュ・ボシェテの首です。主は今日、わが主、王のために、サウルとその子孫に復讐されたのです。」'),
('JPN', '撒母耳记下', 10, 4, 9, 'ダビデは、ベエロテ人リンモンの子レカブとその兄弟バアナに答えて言った。「主は生きておられる。主は私のたましいを、あらゆる苦難から贖い出してくださった。'),
('JPN', '撒母耳记下', 10, 4, 10, 'かつて私に『ご覧ください。サウルは死にました』と告げて、自分では良い知らせをもたらしたつもりでいた者を、私は捕らえて、ツィクラグで殺した。それが、その良い知らせへの報いであった。'),
('JPN', '撒母耳记下', 10, 4, 11, 'まして、この悪者どもが、一人の正しい人を家の中で、しかも寝床の上で殺したとなれば、私は今、彼の血の責任をおまえたちに問い、この地からおまえたちを除き去らずにいられようか。」'),
('JPN', '撒母耳记下', 10, 4, 12, 'ダビデが命じたので、若い者たちは彼らを殺し、手足を切り離した。そしてヘブロンの池のほとりで木につるした。しかし、イシュ・ボシェテの首は、ヘブロンにあるアブネルの墓に持って行って葬った。'),
('JPN', '撒母耳记下', 10, 5, 1, 'イスラエルの全部族は、ヘブロンのダビデのもとに来てこう言った。「ご覧ください。私たちはあなたの骨肉です。'),
('JPN', '撒母耳记下', 10, 5, 2, 'これまで、サウルが私たちの王であったときでさえ、イスラエルを動かしていたのはあなたでした。主はあなたに言われました。『あなたがわたしの民イスラエルを牧し、あなたがイスラエルの君主となる』と。」'),
('JPN', '撒母耳记下', 10, 5, 3, 'イスラエルの全長老はヘブロンの王のもとに来た。ダビデ王はヘブロンで、主の御前に彼らと契約を結び、彼らはダビデに油を注いでイスラエルの王とした。'),
('JPN', '撒母耳记下', 10, 5, 4, 'ダビデは三十歳で王となり、四十年間、王であった。'),
('JPN', '撒母耳记下', 10, 5, 5, 'ヘブロンで七年六か月ユダを治め、エルサレムで三十三年イスラエルとユダの全体を治めた。'),
('JPN', '撒母耳记下', 10, 5, 6, '王とその部下は、エルサレムに、その地の住民エブス人のところに行った。すると彼らはダビデに言った。「おまえは、ここに攻めて来ることなどできない。目の見えない者どもや足の萎えた者どもでさえも、おまえを追い出せる。」彼らは「ダビデがここに攻めて来ることはできない」と考えていたのである。'),
('JPN', '撒母耳记下', 10, 5, 7, 'しかし、ダビデはシオンの要害を攻め取った。これがダビデの町である。'),
('JPN', '撒母耳记下', 10, 5, 8, 'その日ダビデは、「だれでもエブス人を討とうとする者は、水汲みの地下道を通って、ダビデの心が憎む『足の萎えた者どもや目の見えない者ども』を討て」と言った。それで、「目の見えない者や足の萎えた者は王宮に入ってはならない」と言われるようになった。'),
('JPN', '撒母耳记下', 10, 5, 9, 'ダビデはこの要害に住み、これを「ダビデの町」と呼んだ。ダビデはその周りに城壁を、ミロから一周するまで築いた。'),
('JPN', '撒母耳记下', 10, 5, 10, 'ダビデはますます大いなる者となり、万軍の神、主が彼とともにおられた。'),
('JPN', '撒母耳记下', 10, 5, 11, 'ツロの王ヒラムは、ダビデのもとに使者と、杉材、木工、石工を送った。彼らはダビデのために王宮を建てた。'),
('JPN', '撒母耳记下', 10, 5, 12, 'ダビデは、主が自分をイスラエルの王として堅く立て、主の民イスラエルのために、自分の王国を高めてくださったことを知った。'),
('JPN', '撒母耳记下', 10, 5, 13, 'ダビデは、ヘブロンから来た後、エルサレムで、さらに側女たちと妻たちを迎えた。ダビデにはさらに息子たち、娘たちが生まれた。'),
('JPN', '撒母耳记下', 10, 5, 14, 'エルサレムで彼に生まれた子の名は次のとおり。シャムア、ショバブ、ナタン、ソロモン、'),
('JPN', '撒母耳记下', 10, 5, 15, 'イブハル、エリシュア、ネフェグ、ヤフィア、'),
('JPN', '撒母耳记下', 10, 5, 16, 'エリシャマ、エルヤダ、エリフェレテ。'),
('JPN', '撒母耳记下', 10, 5, 17, 'ペリシテ人は、ダビデが油注がれてイスラエルの王となったことを聞いた。ペリシテ人はみな、ダビデを狙って攻め上って来た。ダビデはそれを聞き、要害に下って行った。'),
('JPN', '撒母耳记下', 10, 5, 18, '一方、ペリシテ人はやって来て、レファイムの谷間を侵略した。'),
('JPN', '撒母耳记下', 10, 5, 19, 'ダビデは主に伺った。「ペリシテ人のところに攻め上るべきでしょうか。彼らを私の手に渡してくださるでしょうか。」主はダビデに言われた。「攻め上れ。わたしは必ず、ペリシテ人をあなたの手に渡すから。」'),
('JPN', '撒母耳记下', 10, 5, 20, 'ダビデはバアル・ペラツィムにやって来た。ダビデはそこで彼らを討って、「主は、水が破れ出るように、私の前で私の敵を破られた」と言った。それゆえ、その場所の名はバアル・ペラツィムと呼ばれた。'),
('JPN', '撒母耳记下', 10, 5, 21, '彼らはそこに自分たちの偶像を置き去りにした。そこでダビデとその部下はそれらを運び去った。'),
('JPN', '撒母耳记下', 10, 5, 22, 'ペリシテ人は、またも攻め上り、レファイムの谷間を侵略した。'),
('JPN', '撒母耳记下', 10, 5, 23, 'ダビデが主に伺うと、主は言われた。「上って行くな。彼らのうしろに回り込み、バルサム樹の茂みの前から彼らに向かえ。'),
('JPN', '撒母耳记下', 10, 5, 24, 'バルサム樹の茂みの上で行進の音が聞こえたら、そのとき、あなたは攻め上れ。そのとき主はすでに、ペリシテ人の陣営を討つために、あなたより先に出ているからだ。」'),
('JPN', '撒母耳记下', 10, 5, 25, 'ダビデは主が彼に命じられたとおりにし、ゲバからゲゼルに至るまでのペリシテ人を討った。'),
('JPN', '撒母耳记下', 10, 6, 1, 'ダビデは再びイスラエルの精鋭三万をことごとく集めた。'),
('JPN', '撒母耳记下', 10, 6, 2, 'ダビデはユダのバアラから神の箱を運び上げようとして、自分とともにいたすべての兵と一緒に出かけた。神の箱は、ケルビムの上に座しておられる万軍の主の名でその名を呼ばれている。'),
('JPN', '撒母耳记下', 10, 6, 3, '彼らは、神の箱を新しい荷車に載せて、それを丘の上にあるアビナダブの家から移した。アビナダブの子、ウザとアフヨがその新しい荷車を御した。'),
('JPN', '撒母耳记下', 10, 6, 4, 'それを、丘の上にあるアビナダブの家から神の箱とともに移したとき、アフヨは箱の前を歩いていた。'),
('JPN', '撒母耳记下', 10, 6, 5, 'ダビデとイスラエルの全家は、竪琴、琴、タンバリン、カスタネット、シンバルを鳴らし、主の前で、すべての杉の木の枝をもって、喜び踊った。'),
('JPN', '撒母耳记下', 10, 6, 6, '彼らがナコンの打ち場まで来たとき、ウザは神の箱に手を伸ばして、それをつかんだ。牛がよろめいたからである。'),
('JPN', '撒母耳记下', 10, 6, 7, 'すると、主の怒りがウザに向かって燃え上がり、神はその過ちのために、彼をその場で打たれた。彼はそこで、神の箱の傍らで死んだ。'),
('JPN', '撒母耳记下', 10, 6, 8, 'ダビデの心は激した。主がウザに対して怒りを発せられたからである。その場所は今日までペレツ・ウザと呼ばれている。'),
('JPN', '撒母耳记下', 10, 6, 9, 'その日、ダビデは主を恐れて言った。「どうして、主の箱を私のところにお迎えできるだろうか。」'),
('JPN', '撒母耳记下', 10, 6, 10, 'ダビデは主の箱を自分のところ、ダビデの町に移したくなかった。そこでダビデは、ガテ人オベデ・エドムの家にそれを回した。'),
('JPN', '撒母耳记下', 10, 6, 11, '主の箱はガテ人オベデ・エドムの家に三か月とどまった。主はオベデ・エドムと彼の全家を祝福された。'),
('JPN', '撒母耳记下', 10, 6, 12, '「主が神の箱のことで、オベデ・エドムの家と彼に属するすべてのものを祝福された」という知らせがダビデ王にあった。ダビデは行って、喜びをもって神の箱をオベデ・エドムの家からダビデの町へ運び上げた。'),
('JPN', '撒母耳记下', 10, 6, 13, '主の箱を担ぐ者たちが六歩進んだとき、ダビデは、肥えた牛をいけにえとして献げた。'),
('JPN', '撒母耳记下', 10, 6, 14, 'ダビデは、主の前で力の限り跳ね回った。ダビデは亜麻布のエポデをまとっていた。'),
('JPN', '撒母耳记下', 10, 6, 15, 'ダビデとイスラエルの全家は、歓声をあげ、角笛を鳴らして、主の箱を運び上げた。'),
('JPN', '撒母耳记下', 10, 6, 16, '主の箱がダビデの町に入ろうとしていたとき、サウルの娘ミカルは窓から見下ろしていた。彼女はダビデ王が主の前で跳ねたり踊ったりしているのを見て、心の中で彼を蔑んだ。'),
('JPN', '撒母耳记下', 10, 6, 17, '人々は主の箱を運び込んで、ダビデがそのために張った天幕の真ん中の定められた場所にそれを置いた。ダビデは主の前に、全焼のささげ物と交わりのいけにえを献げた。'),
('JPN', '撒母耳记下', 10, 6, 18, 'ダビデは全焼のささげ物と交わりのいけにえを献げ終えて、万軍の主の御名によって民を祝福した。'),
('JPN', '撒母耳记下', 10, 6, 19, 'そしてすべての民、イスラエルのすべての群衆に、男にも女にも、それぞれ、輪形パン一つ、なつめ椰子の菓子一つ、干しぶどうの菓子一つを分け与えた。民はみな、それぞれ自分の家に帰った。'),
('JPN', '撒母耳记下', 10, 6, 20, 'ダビデが自分の家族を祝福しようと戻ると、サウルの娘ミカルがダビデを迎えに出て来て言った。「イスラエルの王は、今日、本当に威厳がございましたね。ごろつきが恥ずかしげもなく裸になるように、今日、あなたは自分の家来の女奴隷の目の前で裸になられて。」'),
('JPN', '撒母耳记下', 10, 6, 21, 'ダビデはミカルに言った。「あなたの父よりも、その全家よりも、むしろ私を選んで、主の民イスラエルの君主に任じられた主の前だ。私はその主の前で喜び踊るのだ。'),
('JPN', '撒母耳记下', 10, 6, 22, '私はこれより、もっと卑しめられ、自分の目に卑しくなるだろう。しかし、あなたの言う、その女奴隷たちに敬われるのだ。」'),
('JPN', '撒母耳记下', 10, 6, 23, 'サウルの娘ミカルには、死ぬまで子がなかった。'),
('JPN', '撒母耳记下', 10, 7, 1, '王が自分の家に住んでいたときのことである。主は、周囲のすべての敵から彼を守り、安息を与えておられた。'),
('JPN', '撒母耳记下', 10, 7, 2, '王は預言者ナタンに言った。「見なさい。この私が杉材の家に住んでいるのに、神の箱は天幕の中に宿っている。」'),
('JPN', '撒母耳记下', 10, 7, 3, 'ナタンは王に言った。「さあ、あなたの心にあることをみな行いなさい。主があなたとともにおられるのですから。」'),
('JPN', '撒母耳记下', 10, 7, 4, 'その夜のことである。次のような主のことばがナタンにあった。'),
('JPN', '撒母耳记下', 10, 7, 5, '「行って、わたしのしもべダビデに言え。『主はこう言われる。あなたがわたしのために、わたしの住む家を建てようというのか。'),
('JPN', '撒母耳记下', 10, 7, 6, 'わたしは、エジプトからイスラエルの子らを連れ上った日から今日まで、家に住んだことはなく、天幕、幕屋にいて、歩んできたのだ。'),
('JPN', '撒母耳记下', 10, 7, 7, 'わたしがイスラエルの子らのすべてと歩んだところどこででも、わたしが、わたしの民イスラエルを牧せよと命じたイスラエル部族の一つにでも、「なぜ、あなたがたはわたしのために杉材の家を建てなかったのか」と、一度でも言ったことがあっただろうか。』'),
('JPN', '撒母耳记下', 10, 7, 8, '今、わたしのしもべダビデにこう言え。『万軍の主はこう言われる。わたしはあなたを、羊の番をしていた牧場から取り、わが民イスラエルの君主とした。'),
('JPN', '撒母耳记下', 10, 7, 9, 'そして、あなたがどこに行っても、あなたとともにいて、あなたの前であなたのすべての敵を絶ち滅ぼした。わたしは地の大いなる者たちの名に等しい、大いなる名をあなたに与えてきた。'),
('JPN', '撒母耳记下', 10, 7, 10, 'わが民イスラエルのために、わたしは一つの場所を定め、民を住まわせてきた。それは、民がそこに住み、もはや恐れおののくことのないように、不正な者たちも、初めのころのように、重ねて民を苦しめることのないようにするためであった。'),
('JPN', '撒母耳记下', 10, 7, 11, 'それは、わたしが、わが民イスラエルの上にさばきつかさを任命して以来のことである。こうして、わたしはあなたにすべての敵からの安息を与えたのである。主はあなたに告げる。主があなたのために一つの家を造る、と。'),
('JPN', '撒母耳记下', 10, 7, 12, 'あなたの日数が満ち、あなたが先祖とともに眠りにつくとき、わたしは、あなたの身から出る世継ぎの子をあなたの後に起こし、彼の王国を確立させる。'),
('JPN', '撒母耳记下', 10, 7, 13, '彼はわたしの名のために一つの家を建て、わたしは彼の王国の王座をとこしえまでも堅く立てる。'),
('JPN', '撒母耳记下', 10, 7, 14, 'わたしは彼の父となり、彼はわたしの子となる。彼が不義を行ったときは、わたしは人の杖、人の子のむちをもって彼を懲らしめる。'),
('JPN', '撒母耳记下', 10, 7, 15, 'しかしわたしの恵みは、わたしが、あなたの前から取り除いたサウルからそれを取り去ったように、彼から取り去られることはない。'),
('JPN', '撒母耳记下', 10, 7, 16, 'あなたの家とあなたの王国は、あなたの前にとこしえまでも確かなものとなり、あなたの王座はとこしえまでも堅く立つ。』」'),
('JPN', '撒母耳记下', 10, 7, 17, 'ナタンはこれらすべてのことばを、この幻のすべてを、そのままダビデに告げた。'),
('JPN', '撒母耳记下', 10, 7, 18, 'ダビデ王は主の前に出て、座して言った。「神、主よ、私は何者でしょうか。私の家はいったい何なのでしょうか。あなたが私をここまで導いてくださったとは。'),
('JPN', '撒母耳记下', 10, 7, 19, '神、主よ。このことがなお、あなたの御目には小さなことでしたのに、あなたはこのしもべの家にも、はるか先のことまで告げてくださいました。神、主よ、これが人に対するみおしえなのでしょうか。'),
('JPN', '撒母耳记下', 10, 7, 20, 'ダビデはこの上、何を加えて、あなたに申し上げることができるでしょうか。神である主よ、あなたはこのしもべをよくご存じです。'),
('JPN', '撒母耳记下', 10, 7, 21, 'あなたは、ご自分のみことばのゆえに、そしてみこころのままに、この大いなることのすべてを行い、あなたのしもべに知らせてくださいました。'),
('JPN', '撒母耳记下', 10, 7, 22, 'それゆえ、申し上げます。神、主よ、あなたは大いなる方です。まことに、私たちが耳にするすべてにおいて、あなたのような方はほかになく、あなたのほかに神はいません。'),
('JPN', '撒母耳记下', 10, 7, 23, 'また、地上のどの国民があなたの民イスラエルのようでしょうか。御使いたちが行って、その民を御民として贖い、御名を置き、大いなる恐るべきことをあなたの国のために、あなたの民の前で彼らのために行われました。あなたは、彼らをご自分のためにエジプトから、異邦の民とその神々から贖い出されたのです。'),
('JPN', '撒母耳记下', 10, 7, 24, 'そして、あなたの民イスラエルを、ご自分のために、とこしえまでもあなたの民として立てられました。主よ、あなたは彼らの神となられました。'),
('JPN', '撒母耳记下', 10, 7, 25, '今、神である主よ。あなたが、このしもべとその家についてお語りになったことばを、とこしえまでも保ち、お語りになったとおりに行ってください。'),
('JPN', '撒母耳记下', 10, 7, 26, 'こうして、あなたの御名がとこしえまでも大いなるものとなり、『万軍の主はイスラエルを治める神』と言われますように。あなたのしもべダビデの家が御前に堅く立ちますように。'),
('JPN', '撒母耳记下', 10, 7, 27, 'イスラエルの神、万軍の主よ。あなたはこのしもべの耳を開き、『わたしがあなたのために一つの家を建てる』と言われました。それゆえ、このしもべは、この祈りをあなたに祈る勇気を得たのです。'),
('JPN', '撒母耳记下', 10, 7, 28, '今、神、主よ、あなたこそ神です。あなたのおことばは、まことです。あなたはこのしもべに、この良いことを約束してくださいました。'),
('JPN', '撒母耳记下', 10, 7, 29, '今、どうか、あなたのしもべの家を祝福して、御前にとこしえに続くようにしてください。神である主よ、あなたがお語りになったからです。あなたの祝福によって、あなたのしもべの家がとこしえに祝福されますように。」'),
('JPN', '撒母耳记下', 10, 8, 1, 'その後のことである。ダビデはペリシテ人を討って、これを屈服させた。ダビデはメテグ・ハ・アンマをペリシテ人の手から奪い取った。'),
('JPN', '撒母耳记下', 10, 8, 2, '彼はモアブを討ち、彼らを地面に伏させ、測り縄で彼らを測った。縄二本で測った者を殺し、縄一本で測った者を生かしておいた。モアブはダビデのしもべとなり、貢ぎ物を納める者となった。'),
('JPN', '撒母耳记下', 10, 8, 3, 'ツォバの王、レホブの子ハダドエゼルが、ユーフラテス川流域にその勢力を回復しようとして出て行ったとき、ダビデは彼を討った。'),
('JPN', '撒母耳记下', 10, 8, 4, 'ダビデは、彼から騎兵千七百、歩兵二万を取った。ダビデは、そのすべての戦車の馬の足の筋を切った。ただし、そのうち戦車百台分の馬は残した。'),
('JPN', '撒母耳记下', 10, 8, 5, 'ダマスコのアラムがツォバの王ハダドエゼルを助けに来たが、ダビデはアラムの二万二千人を討った。'),
('JPN', '撒母耳记下', 10, 8, 6, 'ダビデはダマスコのアラムに守備隊を置いた。アラムはダビデのしもべとなり、貢ぎ物を納める者となった。主は、ダビデの行く先々で、彼に勝利を与えられた。'),
('JPN', '撒母耳记下', 10, 8, 7, 'ダビデは、ハダドエゼルの家来たちが持っていた金の丸い小盾を奪い取り、エルサレムに持ち帰った。'),
('JPN', '撒母耳记下', 10, 8, 8, 'またダビデ王は、ハダドエゼルの町ベタフとベロタイから、非常に多くの青銅を奪い取った。'),
('JPN', '撒母耳记下', 10, 8, 9, 'ハマテの王トイは、ダビデがハダドエゼルの全軍勢を打ち破ったことを聞いた。'),
('JPN', '撒母耳记下', 10, 8, 10, 'トイは、息子ヨラムをダビデ王のもとに遣わし、安否を尋ね、ダビデがハダドエゼルと戦ってこれを打ち破ったことについて、祝福のことばを述べた。ハダドエゼルがトイにしばしば戦いを挑んでいたからである。ヨラムは銀の器、金の器、青銅の器を携えていた。'),
('JPN', '撒母耳记下', 10, 8, 11, 'ダビデ王は、それらもまた、主のために聖別した。彼が征服したすべての国々から取って聖別した銀や金、'),
('JPN', '撒母耳记下', 10, 8, 12, 'すなわち、アラム、モアブ、アンモン人、ペリシテ人、アマレクから取った物、およびツォバの王、レホブの子ハダドエゼルからの分捕り物と同様にした。'),
('JPN', '撒母耳记下', 10, 8, 13, 'ダビデが塩の谷でアラム人一万八千人を討って帰って来たとき、彼は名をあげた。'),
('JPN', '撒母耳记下', 10, 8, 14, '彼はエドムに守備隊を、エドム全土に守備隊を置いた。こうして、全エドムはダビデのしもべとなった。主は、ダビデの行く先々で、彼に勝利を与えられた。'),
('JPN', '撒母耳记下', 10, 8, 15, 'ダビデは全イスラエルを治めた。ダビデはその民のすべてにさばきと正義を行った。'),
('JPN', '撒母耳记下', 10, 8, 16, 'ツェルヤの子ヨアブは軍団長、アヒルデの子ヨシャファテは史官、'),
('JPN', '撒母耳记下', 10, 8, 17, 'アヒトブの子ツァドクとエブヤタルの子アヒメレクは祭司、セラヤは書記、'),
('JPN', '撒母耳记下', 10, 8, 18, 'エホヤダの子ベナヤはクレタ人とペレテ人の上に立つ者、ダビデの息子たちは祭司であった。'),
('JPN', '撒母耳记下', 10, 9, 1, 'ダビデは言った。「サウルの家の者で、まだ生き残っている人はいないか。私はヨナタンのゆえに、その人に真実を尽くしたい。」'),
('JPN', '撒母耳记下', 10, 9, 2, 'サウルの家にツィバという名のしもべがいて、ダビデのところに呼び出された。王は彼に言った。「あなたがツィバか。」彼は言った。「はい、あなた様のしもべです。」'),
('JPN', '撒母耳记下', 10, 9, 3, '王は言った。「サウルの家の者で、まだ、だれかいないか。私はその人に神の恵みを施そう。」ツィバは王に言った。「まだ、ヨナタンの息子で足の不自由な方がおられます。」'),
('JPN', '撒母耳记下', 10, 9, 4, '王は彼に言った。「その人は、どこにいるのか。」ツィバは王に言った。「お聞きください。ロ・デバルのアンミエルの子マキルの家におられます。」'),
('JPN', '撒母耳记下', 10, 9, 5, 'ダビデ王は人を送って、ロ・デバルのアンミエルの子マキルの家から彼を連れて来させた。'),
('JPN', '撒母耳记下', 10, 9, 6, 'サウルの子ヨナタンの子メフィボシェテは、ダビデのところに来て、ひれ伏して礼をした。ダビデは言った。「メフィボシェテか。」彼は言った。「はい、あなた様のしもべです。」'),
('JPN', '撒母耳记下', 10, 9, 7, 'ダビデは言った。「恐れることはない。私は、あなたの父ヨナタンのゆえに、あなたに恵みを施そう。あなたの祖父サウルの地所をすべてあなたに返そう。あなたはいつも私の食卓で食事をすることになる。」'),
('JPN', '撒母耳记下', 10, 9, 8, '彼は礼をして言った。「いったい、このしもべは何なのでしょうか。あなた様が、この死んだ犬のような私を顧みてくださるとは。」'),
('JPN', '撒母耳记下', 10, 9, 9, '王はサウルのしもべツィバを呼び寄せて言った。「サウルと、その一家の所有になっていた物をみな、私はあなたの主人の息子に与えた。'),
('JPN', '撒母耳记下', 10, 9, 10, 'あなたも、あなたの息子たちも、あなたの召使いたちも、彼のために土地を耕し、作物を持って来て、それがあなたの主人の息子のパン、また食物となる。あなたの主人の息子メフィボシェテは、いつも私の食卓で食事をすることになる。」ツィバには息子が十五人と召使いが二十人いた。'),
('JPN', '撒母耳记下', 10, 9, 11, 'ツィバは王に言った。「わが主、王がこのしもべに申しつけられたとおりに、このしもべはいたします。」メフィボシェテは王の息子たちの一人のように、王の食卓で食事をすることになった。'),
('JPN', '撒母耳记下', 10, 9, 12, 'メフィボシェテには、ミカという名の小さな子がいた。ツィバの家に住む者はみな、メフィボシェテのしもべとなった。'),
('JPN', '撒母耳记下', 10, 9, 13, 'メフィボシェテはエルサレムに住み、いつも王の食卓で食事をした。彼は両足がともに萎えていた。'),
('JPN', '撒母耳记下', 10, 10, 1, 'この後、アンモン人の王が死に、その子ハヌンが代わって王となった。'),
('JPN', '撒母耳记下', 10, 10, 2, 'ダビデは、「ナハシュの子ハヌンに真実を尽くそう。彼の父が私に真実を尽くしてくれたように」と言った。そして家来たちを通して彼の父の悔やみを言うために、ダビデは彼らを遣わした。ダビデの家来たちがアンモン人の地に着いたとき、'),
('JPN', '撒母耳记下', 10, 10, 3, 'アンモン人の首長たちは、主君ハヌンに言った。「ダビデがあなたのもとにお悔やみの使者を遣わしたからといって、彼が父君を敬っているとお考えですか。この町を調べ、探り、くつがえすために、ダビデはあなたのところに家来を遣わしたのではないでしょうか。」'),
('JPN', '撒母耳记下', 10, 10, 4, 'そこでハヌンはダビデの家来たちを捕らえ、ひげを半分剃り落とし、衣を半分に切って尻のあたりまでにして送り返した。'),
('JPN', '撒母耳记下', 10, 10, 5, 'ダビデにこのことが告げられたので、ダビデは彼らを迎えに人を遣わした。この人たちが非常に恥じていたからである。王は言った。「ひげが伸びるまでエリコにとどまり、それから帰って来なさい。」'),
('JPN', '撒母耳记下', 10, 10, 6, 'アンモン人は、自分たちがダビデに憎まれるようになったのを見てとった。そこでアンモン人は人を遣わして、ベテ・レホブのアラム人とツォバのアラム人の歩兵二万、マアカの王の兵士一千、トブの兵士一万二千を雇った。'),
('JPN', '撒母耳记下', 10, 10, 7, 'ダビデはこれを聞き、ヨアブと勇士たちの全軍を送った。'),
('JPN', '撒母耳记下', 10, 10, 8, 'アンモン人は出て来て、門の入り口で戦いの備えをした。ツォバとレホブのアラム人、およびトブとマアカの人たちは、彼らだけで野にいた。'),
('JPN', '撒母耳记下', 10, 10, 9, 'ヨアブは、自分の前とうしろに戦いの前線があるのを見て、イスラエルの精鋭全員からさらに兵を選び、アラム人に立ち向かう陣備えをし、'),
('JPN', '撒母耳记下', 10, 10, 10, '残りの兵を兄弟アビシャイの手に託して、アンモン人に立ち向かう陣備えをした。'),
('JPN', '撒母耳记下', 10, 10, 11, 'ヨアブは言った。「もしアラム人が私より強かったら、あなたが私を救ってくれ。もしアンモン人があなたより強かったら、私があなたを救いに行こう。'),
('JPN', '撒母耳记下', 10, 10, 12, '強くあれ。われわれの民のため、われわれの神の町々のために、奮い立とう。主が、御目にかなうことをされるのだ。」'),
('JPN', '撒母耳记下', 10, 10, 13, 'ヨアブと彼とともにいた兵たちがアラム人と戦おうとして近づいたとき、アラム人は彼の前から逃げた。'),
('JPN', '撒母耳记下', 10, 10, 14, 'アンモン人はアラム人が逃げるのを見ると、アビシャイの前から逃げて町に入った。そこでヨアブはアンモン人を討つのをやめて、エルサレムに帰った。'),
('JPN', '撒母耳记下', 10, 10, 15, 'アラム人は、自分たちがイスラエルに打ち負かされたのを見て、集結した。'),
('JPN', '撒母耳记下', 10, 10, 16, 'ハダドエゼルは人を遣わして、ユーフラテス川の向こうのアラム人に出て来させた。彼らは、ヘラムにやって来た。ハダドエゼルの軍の長ショバクが彼らを率いていた。'),
('JPN', '撒母耳记下', 10, 10, 17, 'このことが報告されると、ダビデはイスラエル全軍を集結させ、ヨルダン川を渡って、ヘラムへ進んだ。アラム人はダビデと対決する備えをし、彼と戦った。'),
('JPN', '撒母耳记下', 10, 10, 18, 'アラム人はイスラエルの前から逃げた。ダビデはアラムの戦車兵七百と騎兵四万を殺し、軍の長ショバクも討ったので、彼はそこで死んだ。'),
('JPN', '撒母耳记下', 10, 10, 19, 'ハダドエゼルに仕えていた王たちはみな、彼らがイスラエルに打ち負かされたのを見て、イスラエルと和を講じ、イスラエルに仕えるようになった。アラム人は恐れて、再びアンモン人を助けようとはしなかった。'),
('JPN', '撒母耳记下', 10, 11, 1, '年が改まり、王たちが出陣する時期になった。ダビデは、ヨアブと自分の家来たちとイスラエル全軍を送った。彼らはアンモン人を打ち負かし、ラバを包囲した。しかし、ダビデはエルサレムにとどまっていた。'),
('JPN', '撒母耳记下', 10, 11, 2, 'ある夕暮れ時、ダビデが床から起き上がり、王宮の屋上を歩いていると、一人の女が、からだを洗っているのが屋上から見えた。その女は非常に美しかった。'),
('JPN', '撒母耳记下', 10, 11, 3, 'ダビデは人を送ってその女について調べさせたところ、「あれはヒッタイト人ウリヤの妻で、エリアムの娘バテ・シェバです」との報告を受けた。'),
('JPN', '撒母耳记下', 10, 11, 4, 'ダビデは使いの者を送って、その女を召し入れた。彼女が彼のところに来たので、彼は彼女と寝た──彼女は月のものの汚れから身を聖別していた──それから彼女は自分の家に帰った。'),
('JPN', '撒母耳记下', 10, 11, 5, '女は身ごもった。それで彼女はダビデに人を送って告げた。「私は子を宿しました。」'),
('JPN', '撒母耳记下', 10, 11, 6, 'ダビデはヨアブのところに人を遣わして、「ヒッタイト人ウリヤを私のところに送れ」と言った。ヨアブはウリヤをダビデのところに送った。'),
('JPN', '撒母耳记下', 10, 11, 7, 'ウリヤがやって来ると、ダビデは、ヨアブは無事でいるか、また兵たちは無事か、さらに戦いはうまくいっているかと尋ねた。'),
('JPN', '撒母耳记下', 10, 11, 8, 'ダビデはウリヤに言った。「家に帰って、足を洗いなさい。」ウリヤが王宮から出て行くと、王からの贈り物が彼の後に続いた。'),
('JPN', '撒母耳记下', 10, 11, 9, 'しかしウリヤは、王宮の門のあたりで、自分の主君の家来たちみなと一緒に眠り、自分の家に帰らなかった。'),
('JPN', '撒母耳记下', 10, 11, 10, 'ダビデに「ウリヤは自分の家に帰らなかった」という知らせがあった。ダビデはウリヤに言った。「あなたは遠征して来たのではないか。なぜ、自分の家に帰らなかったのか。」'),
('JPN', '撒母耳记下', 10, 11, 11, 'ウリヤはダビデに言った。「神の箱も、イスラエルも、ユダも仮庵に住み、私の主人ヨアブも、私の主人の家来たちも戦場で野営しています。それなのに、私が家に帰り、食べたり飲んだりして、妻と寝るということができるでしょうか。あなたの前に、あなたのたましいの前に誓います。私は決してそのようなことをいたしません。」'),
('JPN', '撒母耳记下', 10, 11, 12, 'ダビデはウリヤに言った。「今日もここにとどまるがよい。明日になったら、あなたを送り出そう。」ウリヤはその日と翌日、エルサレムにとどまることになった。'),
('JPN', '撒母耳记下', 10, 11, 13, 'ダビデは彼を招いた。彼はダビデの前で食べて飲んだ。ダビデは彼を酔わせた。夕方、ウリヤは出て行って、自分の主君の家来たちと一緒に自分の寝床で寝た。しかし、自分の家には下って行かなかった。'),
('JPN', '撒母耳记下', 10, 11, 14, '朝になって、ダビデはヨアブに手紙を書き、それをウリヤに託して送った。'),
('JPN', '撒母耳记下', 10, 11, 15, '彼は、その手紙に次のように書いた。「ウリヤを激戦の真っ正面に出し、彼を残してあなたがたは退き、彼が討たれて死ぬようにせよ。」'),
('JPN', '撒母耳记下', 10, 11, 16, 'ヨアブは町を見張っていて、その町の力ある者たちがいると分かっている場所に、ウリヤを配置した。'),
('JPN', '撒母耳记下', 10, 11, 17, 'その町の者が出て来てヨアブと戦った。兵のうちダビデの家来たちが倒れ、ヒッタイト人ウリヤも死んだ。'),
('JPN', '撒母耳记下', 10, 11, 18, 'ヨアブは人を遣わして、戦いの一部始終をダビデに報告した。'),
('JPN', '撒母耳记下', 10, 11, 19, 'そのとき、ヨアブは使者に命じて言った。「戦いの一部始終を王に報告し終えたとき、'),
('JPN', '撒母耳记下', 10, 11, 20, 'もし王が憤って、おまえに、『どうして、おまえたちはそんなに町に近づいて戦ったのか。城壁の上から彼らが射かけてくるのを知らなかったのか。'),
('JPN', '撒母耳记下', 10, 11, 21, 'エルベシェテの子アビメレクを打ち殺したのは、だれであったか。一人の女が城壁の上からひき臼の上石を投げつけて、テベツで彼を殺したのではなかったか。どうして、そんなに城壁に近づいたのか』と言われたら、『あなたの家来、ヒッタイト人ウリヤも死にました』と言いなさい。」'),
('JPN', '撒母耳记下', 10, 11, 22, '使者は出かけて行き、ダビデのところに来て、ヨアブの伝言をすべて伝えた。'),
('JPN', '撒母耳记下', 10, 11, 23, '使者はダビデに言った。「敵は私たちより優勢で、私たちに向かって野に出て来ましたが、私たちは門の入り口まで彼らを攻めて行きました。'),
('JPN', '撒母耳记下', 10, 11, 24, '城壁の上から射手たちがあなたの家来たちに矢を射かけ、王の家来たちが死に、あなたの家来、ヒッタイト人ウリヤも死にました。」'),
('JPN', '撒母耳记下', 10, 11, 25, 'ダビデは使者に言った。「あなたはヨアブにこう言いなさい。『このことに心を痛めるな。剣はこちらの者も、あちらの者も食い尽くすものだ。あなたは町をいっそう激しく攻撃し、それを全滅させよ。』あなたは彼を力づけなさい。」'),
('JPN', '撒母耳记下', 10, 11, 26, 'ウリヤの妻は、自分の夫ウリヤが死んだことを聞き、自分の主人のために悼み悲しんだ。'),
('JPN', '撒母耳记下', 10, 11, 27, '喪が明けると、ダビデは人を遣わして、彼女を自分の家に迎え入れた。彼女は彼の妻となり、彼のために息子を産んだ。しかし、ダビデが行ったことは主のみこころを損なった。'),
('JPN', '撒母耳记下', 10, 12, 1, '主はナタンをダビデのところに遣わされた。ナタンはダビデのところに来て言った。「ある町に二人の人がいました。一人は富んでいる人、もう一人は貧しい人でした。'),
('JPN', '撒母耳记下', 10, 12, 2, '富んでいる人には、とても多くの羊と牛の群れがいましたが、'),
('JPN', '撒母耳记下', 10, 12, 3, '貧しい人は、自分で買ってきて育てた一匹の小さな雌の子羊のほかは、何も持っていませんでした。子羊は彼とその子どもたちと一緒に暮らし、彼と同じ食べ物を食べ、同じ杯から飲み、彼の懐で休み、まるで彼の娘のようでした。'),
('JPN', '撒母耳记下', 10, 12, 4, '一人の旅人が、富んでいる人のところにやって来ました。彼は、自分のところに来た旅人のために自分の羊や牛の群れから取って調理するのを惜しみ、貧しい人の雌の子羊を奪い取り、自分のところに来た人のために調理しました。」'),
('JPN', '撒母耳记下', 10, 12, 5, 'ダビデは、その男に対して激しい怒りを燃やし、ナタンに言った。「主は生きておられる。そんなことをした男は死に値する。'),
('JPN', '撒母耳记下', 10, 12, 6, 'その男は、あわれみの心もなく、そんなことをしたのだから、その雌の子羊を四倍にして償わなければならない。」'),
('JPN', '撒母耳记下', 10, 12, 7, 'ナタンはダビデに言った。「あなたがその男です。イスラエルの神、主はこう言われます。『わたしはあなたに油を注いで、イスラエルの王とした。また、わたしはサウルの手からあなたを救い出した。'),
('JPN', '撒母耳记下', 10, 12, 8, 'さらに、あなたの主君の家を与え、あなたの主君の妻たちをあなたの懐に渡し、イスラエルとユダの家も与えた。それでも少ないというのなら、あなたにもっと多くのものを増し加えたであろう。'),
('JPN', '撒母耳记下', 10, 12, 9, 'どうして、あなたは主のことばを蔑み、わたしの目に悪であることを行ったのか。あなたはヒッタイト人ウリヤを剣で殺し、彼の妻を奪って自分の妻にした。あなたが彼をアンモン人の剣で殺したのだ。'),
('JPN', '撒母耳记下', 10, 12, 10, '今や剣は、とこしえまでもあなたの家から離れない。あなたがわたしを蔑み、ヒッタイト人ウリヤの妻を奪い取り、自分の妻にしたからだ。』'),
('JPN', '撒母耳记下', 10, 12, 11, '主はこう言われる。『見よ、わたしはあなたの家の中から、あなたの上にわざわいを引き起こす。あなたの妻たちをあなたの目の前で奪い取り、あなたの隣人に与える。彼は、白昼公然と、あなたの妻たちと寝るようになる。'),
('JPN', '撒母耳记下', 10, 12, 12, 'あなたは隠れてそれをしたが、わたしはイスラエル全体の前で、白日のもとで、このことを行う。』」'),
('JPN', '撒母耳记下', 10, 12, 13, 'ダビデはナタンに言った。「私は主の前に罪ある者です。」ナタンはダビデに言った。「主も、あなたの罪を取り去ってくださった。あなたは死なない。'),
('JPN', '撒母耳记下', 10, 12, 14, 'しかし、あなたはこのことによって、主の敵に大いに侮りの心を起こさせたので、あなたに生まれる息子は必ず死ぬ。」'),
('JPN', '撒母耳记下', 10, 12, 15, 'ナタンは自分の家へ帰って行った。主は、ウリヤの妻がダビデに産んだ子を打たれたので、その子は病気になった。'),
('JPN', '撒母耳记下', 10, 12, 16, 'ダビデはその子のために神に願い求めた。ダビデは断食をして引きこもり、一晩中、地に伏していた。'),
('JPN', '撒母耳记下', 10, 12, 17, '彼の家の長老たちは彼のそばに立って、彼を地から起こそうとしたが、ダビデは起きようともせず、彼らと一緒に食事をとろうともしなかった。'),
('JPN', '撒母耳记下', 10, 12, 18, '七日目にその子は死んだ。ダビデの家来たちは、その子が死んだことをダビデに告げるのを恐れた。彼らは、「聞きなさい。王はあの子が生きているとき、われわれが話しても、言うことを聞いてくださらなかった。どうして、あの子どもが死んだことを王に言えるだろうか。王は何か悪いことをされるかもしれない」と言ったのである。'),
('JPN', '撒母耳记下', 10, 12, 19, 'ダビデは、家来たちが小声で話し合っているのを見て、子が死んだことを悟った。ダビデは家来たちに言った。「あの子は死んだのか。」彼らは言った。「亡くなられました。」'),
('JPN', '撒母耳记下', 10, 12, 20, 'ダビデは地から起き上がり、からだを洗って身に油を塗り、衣を替えて主の家に入り、礼拝をした。そして自分の家に帰り、食事の用意をさせて食事をとった。'),
('JPN', '撒母耳记下', 10, 12, 21, '家来たちは彼に言った。「あなたのなさったこのことは、いったいどういうことですか。お子様が生きておられるときは断食をして泣かれたのに、お子様が亡くなられると、起き上がり食事をされるとは。」'),
('JPN', '撒母耳记下', 10, 12, 22, 'ダビデは言った。「あの子がまだ生きているときに私が断食をして泣いたのは、もしかすると主が私をあわれんでくださり、あの子が生きるかもしれない、と思ったからだ。'),
('JPN', '撒母耳记下', 10, 12, 23, 'しかし今、あの子は死んでしまった。私はなぜ、断食をしなければならないのか。あの子をもう一度、呼び戻せるだろうか。私があの子のところに行くことはあっても、あの子は私のところに戻っては来ない。」'),
('JPN', '撒母耳记下', 10, 12, 24, 'ダビデは妻バテ・シェバを慰め、彼女のところに入り、彼女と寝た。彼女は男の子を産み、彼はその名をソロモンと名づけた。主は彼を愛されたので、'),
('JPN', '撒母耳记下', 10, 12, 25, '預言者ナタンを遣わし、主のために、その名をエディデヤと名づけさせた。'),
('JPN', '撒母耳记下', 10, 12, 26, 'さて、ヨアブはアンモン人のラバと戦い、この王の町を攻め取った。'),
('JPN', '撒母耳记下', 10, 12, 27, 'ヨアブはダビデに使者を遣わして言った。「私はラバと戦って、水の町を攻め取りました。'),
('JPN', '撒母耳记下', 10, 12, 28, '今、兵の残りの者たちを集めて、この町に対して陣を敷き、あなたがこれを攻め取ってください。私がこの町を取り、この町に私の名がつけられるといけませんから。」'),
('JPN', '撒母耳记下', 10, 12, 29, 'ダビデはすべての兵を集めてラバに進んで行き、これと戦って攻め取った。'),
('JPN', '撒母耳记下', 10, 12, 30, '彼は、彼らの王の冠をその頭から奪い取った。その重さは金一タラントで、宝石がはめ込まれていた。その冠はダビデの頭に置かれた。彼は、その町から非常に多くの分捕り物を持ち去った。'),
('JPN', '撒母耳记下', 10, 12, 31, '彼はその町にいた人々を連れ出して、石のこぎりや、鉄のつるはし、鉄の斧を使う仕事に就かせ、また、連れて行って、れんが作りの仕事をさせた。ダビデはアンモン人のすべての町に対して、いつもこのようにしていた。ダビデとすべての兵はエルサレムに帰った。'),
('JPN', '撒母耳记下', 10, 13, 1, 'その後のことである。ダビデの子アブサロムに、タマルという名の美しい妹がいた。ダビデの子アムノンは彼女に恋をした。'),
('JPN', '撒母耳记下', 10, 13, 2, 'アムノンは、妹タマルのゆえに苦しんで、病気になるほどであった。というのは、彼女が処女であって、アムノンには、彼女に何かをするということはとてもできないと思われたからである。'),
('JPN', '撒母耳记下', 10, 13, 3, 'アムノンには、ダビデの兄弟シムアの息子でヨナダブという名の友人がいた。ヨナダブは非常に知恵のある男であった。'),
('JPN', '撒母耳记下', 10, 13, 4, '彼はアムノンに言った。「王子様。なぜ、朝ごとにやつれていかれるのですか、そのわけを話してください。」アムノンは彼に言った。「私は、兄弟アブサロムの妹タマルを愛している。」'),
('JPN', '撒母耳记下', 10, 13, 5, 'ヨナダブは彼に言った。「床に伏せて、病気のふりをなさってください。父君が見舞いに来られたら、こう言うのです。『どうか、妹のタマルをよこして、私に食事をとらせるようにしてください。彼女が私の目の前で食事を作って、私はそれを見守り、彼女の手から食べたいのです。』」'),
('JPN', '撒母耳记下', 10, 13, 6, 'アムノンは床につき、仮病を使った。王が見舞いに来ると、アムノンは王に言った。「どうか、妹のタマルをよこし、目の前で団子を二つ作らせてください。私は彼女の手から食べたいのです。」'),
('JPN', '撒母耳记下', 10, 13, 7, 'ダビデは、タマルの家に人を遣わして言った。「兄さんのアムノンの家に行って、病人食を作ってあげなさい。」'),
('JPN', '撒母耳记下', 10, 13, 8, 'タマルが兄アムノンの家に行ったところ、彼は床についていた。彼女は生地を取ってそれをこね、彼の目の前で団子を作ってそれをゆでた。'),
('JPN', '撒母耳记下', 10, 13, 9, '彼女は鍋を取り、それを彼の前によそったが、彼は食べることを拒んだ。アムノンが「皆の者をここから出て行かせよ」と言ったので、みなアムノンのところから出て行った。'),
('JPN', '撒母耳记下', 10, 13, 10, 'アムノンはタマルに言った。「食事を寝室に持って来ておくれ。私はおまえの手からそれを食べたい。」タマルは、自分が作ったゆでた団子を兄のアムノンの寝室に持って来た。'),
('JPN', '撒母耳记下', 10, 13, 11, '彼女が食べさせようとして、彼に近づくと、彼は彼女を捕まえて言った。「妹よ、おいで。私と寝よう。」'),
('JPN', '撒母耳记下', 10, 13, 12, '彼女は言った。「いけません。兄上。乱暴してはいけません。イスラエルでは、こんなことはしません。こんな愚かなことをしないでください。'),
('JPN', '撒母耳记下', 10, 13, 13, '私は、この汚名をどこに持って行けるでしょうか。あなたも、イスラエルで愚か者のようになるのです。今、王に話してください。きっと、王は私があなたに会うのを拒まないでしょう。」'),
('JPN', '撒母耳记下', 10, 13, 14, 'しかし、アムノンは彼女の言うことを聞こうともせず、力ずくで彼女を辱めて、彼女と寝た。'),
('JPN', '撒母耳记下', 10, 13, 15, 'アムノンは、激しい憎しみにかられて、彼女を嫌った。その憎しみは、彼が抱いた恋よりも大きかった。アムノンは彼女に言った。「起きて、出て行け。」'),
('JPN', '撒母耳记下', 10, 13, 16, 'タマルは言った。「それはなりません。私を追い出すなど、あなたが私にしたあのことより、なおいっそう悪いことですから。」しかし、アムノンは彼女の言うことを聞こうともせず、'),
('JPN', '撒母耳记下', 10, 13, 17, '召使いの若い者を呼んで言った。「この女をここから外に追い出して、戸を閉めてくれ。」'),
('JPN', '撒母耳记下', 10, 13, 18, '彼女は、あや織りの長服を着ていた。昔、処女である王女たちはそのような身なりをしていたのである。召使いは彼女を外に追い出し、こうして戸を閉めてしまった。'),
('JPN', '撒母耳记下', 10, 13, 19, 'タマルは頭に灰をかぶり、身に着けていたあや織りの長服を引き裂き、手を頭に置いて、泣き叫びながら歩いて行った。'),
('JPN', '撒母耳记下', 10, 13, 20, '彼女の兄アブサロムは彼女に言った。「おまえの兄アムノンが、おまえと一緒にいたのか。妹よ、今は黙っていなさい。彼はおまえの兄なのだ。このことで心配しなくてもよい。」タマルは、兄アブサロムの家で、一人わびしく暮らしていた。'),
('JPN', '撒母耳记下', 10, 13, 21, 'ダビデ王は、事の一部始終を聞いて激しく怒った。'),
('JPN', '撒母耳记下', 10, 13, 22, 'アブサロムはアムノンに、このことが良いとも悪いとも何も言わなかった。アブサロムは、アムノンが妹タマルを辱めたことで、彼を憎んでいたからである。'),
('JPN', '撒母耳记下', 10, 13, 23, '満二年たって、アブサロムがエフライムの近くのバアル・ハツォルで羊の毛の刈り取りの祝いをしたとき、アブサロムは王の息子たち全員を招いた。'),
('JPN', '撒母耳记下', 10, 13, 24, 'アブサロムは王のもとに行き、こう言った。「ご覧ください。このしもべは羊の毛の刈り取りの祝いをすることにしました。どうか、王も家来たちも、このしもべと一緒においでください。」'),
('JPN', '撒母耳记下', 10, 13, 25, '王はアブサロムに言った。「いや、わが子よ。われわれ全員が行くのは良くない。あなたの重荷になってもいけないから。」アブサロムは、しきりに勧めたが、ダビデは行きたがらず、ただ彼に祝福を与えた。'),
('JPN', '撒母耳记下', 10, 13, 26, 'アブサロムは言った。「それなら、どうか、私の兄アムノンを私どもと一緒に行かせてください。」王は彼に言った。「なぜ、彼があなたと一緒に行かなければならないのか。」'),
('JPN', '撒母耳记下', 10, 13, 27, 'アブサロムがしきりに勧めたので、王はアムノンと王の息子たち全員を彼と一緒に行かせた。'),
('JPN', '撒母耳记下', 10, 13, 28, 'アブサロムは、自分に仕える若い者たちに命じて言った。「よく注意して、アムノンが酔って上機嫌になったとき、私が『アムノンを討て』と言ったら、彼を殺せ。恐れてはならない。この私が命じるのではないか。強くあれ。力ある者となれ。」'),
('JPN', '撒母耳记下', 10, 13, 29, 'アブサロムの若い者たちは、アブサロムが命じたとおりにアムノンにした。王の息子たちはみな立ち上がって、それぞれ自分のらばに乗って逃げた。'),
('JPN', '撒母耳记下', 10, 13, 30, '彼らがまだ道の途中にいたとき、ダビデのところに、「アブサロムは王のご子息たちを全員殺しました。残された方は一人もいらっしゃいません」という知らせが届いた。'),
('JPN', '撒母耳记下', 10, 13, 31, '王は立ち上がり、衣を引き裂き、地に伏した。傍らに立っていた家来たちもみな、衣を引き裂いた。'),
('JPN', '撒母耳记下', 10, 13, 32, 'ダビデの兄弟シムアの子ヨナダブは、証言をして言った。「王様。彼らが王のご子息である若者たちを全員殺したとお思いになりませんように。アムノンだけが死んだのです。それはアブサロムの命令によるもので、アムノンが妹のタマルを辱めた日から、胸に抱いていたことです。'),
('JPN', '撒母耳记下', 10, 13, 33, '今、王様。王子たち全員が殺された、という知らせを心に留めないでください。アムノンだけが死んだのです。」'),
('JPN', '撒母耳记下', 10, 13, 34, 'アブサロムは逃げた。見張りの若者が目を上げて見ると、見よ、うしろの山沿いの道から大勢の人々がやって来るところであった。'),
('JPN', '撒母耳记下', 10, 13, 35, 'ヨナダブは王に言った。「ご覧ください。王子たちが来られます。このしもべが申し上げたとおりになりました。」'),
('JPN', '撒母耳记下', 10, 13, 36, '彼が語り終えたとき、見よ、王子たちが来て、声をあげて泣いた。王もその家来たちもみな、非常に激しく泣いた。'),
('JPN', '撒母耳记下', 10, 13, 37, 'アブサロムは、ゲシュルの王アミフデの子タルマイのところに逃げた。ダビデは、毎日アムノンの死を嘆き悲しんでいた。'),
('JPN', '撒母耳记下', 10, 13, 38, 'アブサロムは、ゲシュルに逃げて行き、三年の間そこにいた。'),
('JPN', '撒母耳记下', 10, 13, 39, 'アブサロムのところに向かって出て行きたいという、ダビデ王の願いはなくなった。アムノンが死んだことについて慰めを得たからである。'),
('JPN', '撒母耳记下', 10, 14, 1, 'ツェルヤの子ヨアブは、王の心がアブサロムに向いていることを知った。'),
('JPN', '撒母耳记下', 10, 14, 2, 'ヨアブはテコアに人を遣わして、そこから知恵のある女を連れて来て、彼女に言った。「喪に服している者を装い、喪服を着て、身に油も塗らず、死んだ人のために長い間喪に服している女のようになって、'),
('JPN', '撒母耳记下', 10, 14, 3, '王のもとに行き、王にこのように話してください。」ヨアブは彼女の口にことばを与えた。'),
('JPN', '撒母耳记下', 10, 14, 4, 'テコアの女は、王に話したとき、地にひれ伏して礼をして言った。「お救いください。王様。」'),
('JPN', '撒母耳记下', 10, 14, 5, '王は彼女に言った。「いったい、どうしたのか。」彼女は答えた。「実はこの私はやもめで、夫は亡くなりました。'),
('JPN', '撒母耳记下', 10, 14, 6, 'このはしためには二人の息子がおりましたが、二人が野原でけんかをして、だれも二人を仲裁する者がいなかったので、一人が相手を打ち殺してしまいました。'),
('JPN', '撒母耳记下', 10, 14, 7, 'すると、お聞きください、親族全体がこのはしために詰め寄って、『兄弟を打った者を引き渡せ。彼が殺した兄弟のいのちのために、彼を殺し、この家の世継ぎも消し去ろう』と言います。残された私の一つの火種を消して、夫の名だけではなく、残りの者までも、この地に残さないようにするのです。」'),
('JPN', '撒母耳记下', 10, 14, 8, '王は女に言った。「家に帰りなさい。あなたのことで命令を出そう。」'),
('JPN', '撒母耳记下', 10, 14, 9, 'テコアの女は王に言った。「王様。刑罰は私と私の父の家に下り、王様と王位は罰を免れますように。」'),
('JPN', '撒母耳记下', 10, 14, 10, '王は言った。「あなたに文句を言う者がいるなら、その人を、私のところに連れて来なさい。もう二度とあなたを煩わすことはなくなる。」'),
('JPN', '撒母耳记下', 10, 14, 11, '彼女は言った。「どうか王様。あなたの神、主に心を留め、血の復讐をする者が殺すことを繰り返さず、私の息子を消し去らないようにしてください。」王は言った。「主は生きておられる。あなたの息子の髪の毛一本も決して地に落ちることはない。」'),
('JPN', '撒母耳记下', 10, 14, 12, '女は言った。「このはしために、一言、王様に申し上げさせてください。」王は言った。「言いなさい。」'),
('JPN', '撒母耳记下', 10, 14, 13, '女は言った。「あなた様はどうして、神の民に対してこのようなことを計られたのですか。王様は、先のようなことを語って、ご自分を咎ある者としておられます。王様は追放された者を戻しておられません。'),
('JPN', '撒母耳记下', 10, 14, 14, '私たちは、必ず死ぬ者です。私たちは地面にこぼれて、もう集めることができない水のようなものです。しかし、神はいのちを取り去らず、追放されている者が追放されたままにならないように、ご計画を立ててくださいます。'),
('JPN', '撒母耳记下', 10, 14, 15, '今、私が、このことを王様に話しに参りましたのも、人々が私を脅したからです。このはしためは、こう思いました。『王に申し上げよう。王は、このはしための願いをかなえてくださるかもしれない。'),
('JPN', '撒母耳记下', 10, 14, 16, '王は聞き入れて、私と私の息子を神のゆずりの地から消し去ろうとする者の手から、このはしためをきっと助け出してくださるから。』'),
('JPN', '撒母耳记下', 10, 14, 17, 'このはしためは、『王様のことばは私の慰めとなるに違いない』と思いました。王様は、神の使いのように、善と悪を聞き分けられるからです。あなた様の神、主が、あなたとともにおられますように。」'),
('JPN', '撒母耳记下', 10, 14, 18, '王は女に答えて言った。「私が尋ねることに、隠さずに答えなさい。」女は言った。「王様、どうぞお尋ねください。」'),
('JPN', '撒母耳记下', 10, 14, 19, '王は言った。「これはすべて、ヨアブの指図によるのであろう。」女は答えて言った。「王様、あなたのたましいは生きておられます。王様が言われることから、だれも右にも左にもそれることはできません。確かに王様の家来ヨアブが私に命じ、あの方がこのはしための口に、これらすべてのことばを授けたのです。'),
('JPN', '撒母耳记下', 10, 14, 20, '王様の家来ヨアブは、事の成り行きを変えるために、このことをしたのです。あなた様には、神の使いの知恵のような知恵があり、地上のすべてのことをご存じですから。」'),
('JPN', '撒母耳记下', 10, 14, 21, '王はヨアブに言った。「よろしい。その願いを聞き入れた。行って、若者アブサロムを連れ戻しなさい。」'),
('JPN', '撒母耳记下', 10, 14, 22, 'ヨアブは地にひれ伏して礼をし、王に祝福のことばを述べて言った。「今日、このしもべがご好意を受けていることが分かりました。王様。王が、このしもべの願いを聞き入れてくださったのですから。」'),
('JPN', '撒母耳记下', 10, 14, 23, 'ヨアブはすぐゲシュルに出かけて行き、アブサロムをエルサレムに連れて来た。'),
('JPN', '撒母耳记下', 10, 14, 24, '王は言った。「あれは自分の家に行ってもらおう。私の顔を見ることはならぬ。」アブサロムは自分の家に行き、王の顔を見ることはなかった。'),
('JPN', '撒母耳记下', 10, 14, 25, 'さて、イスラエルのどこにも、アブサロムほど、その美しさをほめそやされた者はいなかった。足の裏から頭の頂まで、彼には非の打ちどころがなかった。'),
('JPN', '撒母耳记下', 10, 14, 26, '彼は毎年、年の終わりに、頭が重いので髪の毛を刈っていたが、刈るときに髪の毛を量ると、王の秤で二百シェケルもあった。'),
('JPN', '撒母耳记下', 10, 14, 27, 'アブサロムに、三人の息子と一人の娘が生まれた。その娘の名はタマルといって美しい女であった。'),
('JPN', '撒母耳记下', 10, 14, 28, 'アブサロムは二年間エルサレムに住んでいたが、王の顔を見ることはなかった。'),
('JPN', '撒母耳记下', 10, 14, 29, 'アブサロムは、ヨアブを王のところに送ろうとして、ヨアブのもとに人を遣わしたが、彼は来ようとしなかった。アブサロムはもう一度、人を遣わしたが、ヨアブは来ようとしなかった。'),
('JPN', '撒母耳记下', 10, 14, 30, 'アブサロムは家来たちに言った。「見よ。ヨアブの畑は私の畑のそばにあり、そこには大麦が植えてある。行って、それに火をつけよ。」アブサロムの家来たちは畑に火をつけた。'),
('JPN', '撒母耳记下', 10, 14, 31, 'ヨアブは立ち上がり、アブサロムの家に来て、彼に言った。「なぜ、あなたの家来たちは私の畑に火をつけたのですか。」'),
('JPN', '撒母耳记下', 10, 14, 32, 'アブサロムはヨアブに答えた。「ほら、私はあなたのところに人を遣わし、ここに来るように言ったではないか。私はあなたを王のもとに遣わし、『なぜ、私をゲシュルから帰って来させたのですか。あそこにとどまっていたほうが、まだ、ましでした』と言ってもらいたかったのだ。今、私は王の顔を拝したい。もし私に咎があるなら、王に殺されてもかまわない。」'),
('JPN', '撒母耳记下', 10, 14, 33, 'ヨアブは王のところに行き、王に告げた。王はアブサロムを呼び寄せた。アブサロムは王のところに来て、王の前で地にひれ伏して礼をした。王はアブサロムに口づけした。'),
('JPN', '撒母耳记下', 10, 15, 1, 'その後、アブサロムは自分のために戦車と馬、そして自分の前に走る者五十人を手に入れた。'),
('JPN', '撒母耳记下', 10, 15, 2, 'アブサロムはいつも、朝早く、門に通じる道のそばに立っていた。さばきのために王のところに来て訴えようとする者がいると、アブサロムは、その一人ひとりを呼んで言っていた。「あなたはどこの町の者か。」その人が「このしもべはイスラエルのこれこれの部族の者です」と答えると、'),
('JPN', '撒母耳记下', 10, 15, 3, 'アブサロムは彼に、「聞きなさい。あなたの訴えは良いし、正しい。だが、王の側にはあなたのことを聞いてくれる者はいない」と言っていた。'),
('JPN', '撒母耳记下', 10, 15, 4, 'さらにアブサロムは、「だれか私をこの国のさばき人に立ててくれないだろうか。訴えや申し立てのある人がみな、私のところに来て、私がその訴えを正しくさばくのだが」と言っていた。'),
('JPN', '撒母耳记下', 10, 15, 5, '人が彼に近づいてひれ伏そうとすると、彼は手を伸ばし、その人を抱いて口づけしていた。'),
('JPN', '撒母耳记下', 10, 15, 6, 'アブサロムは、さばきのために王のところにやって来る、すべてのイスラエルの人にこのようにした。アブサロムはイスラエルの人々の心を盗んだ。'),
('JPN', '撒母耳记下', 10, 15, 7, '四年たって、アブサロムは王に言った。「私が主に立てた誓願を果たすために、どうか私をヘブロンに行かせてください。'),
('JPN', '撒母耳记下', 10, 15, 8, 'このしもべは、アラムのゲシュルにいたときに、『もし主が私を本当にエルサレムに連れ帰ってくださるなら、私は主に仕えます』と言って誓願を立てたのです。」'),
('JPN', '撒母耳记下', 10, 15, 9, '王は言った。「安心して行って来なさい。」彼は立って、ヘブロンに行った。'),
('JPN', '撒母耳记下', 10, 15, 10, 'アブサロムはイスラエルの全部族に、ひそかに人を遣わして言った。「角笛が鳴るのを聞いたら、『アブサロムがヘブロンで王になった』と言いなさい。」')
on conflict (version, book, chapter, verse) do nothing;
insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('JPN', '撒母耳记下', 10, 15, 11, 'アブサロムとともに、二百人の人々がエルサレムを出て行った。その人たちは、ただ単に招かれて行った者たちで、何も知らなかった。'),
('JPN', '撒母耳记下', 10, 15, 12, 'アブサロムは、いけにえを献げている間に、人を遣わして、ダビデの助言者ギロ人アヒトフェルを、彼の町ギロから呼び寄せた。この謀反は強く、アブサロムにくみする民が多くなった。'),
('JPN', '撒母耳记下', 10, 15, 13, 'ダビデのところに告げる者が来て、「イスラエルの人々の心はアブサロムになびいています」と言った。'),
('JPN', '撒母耳记下', 10, 15, 14, 'ダビデは、自分とともにエルサレムにいる家来全員に言った。「さあ、逃げよう。そうでないと、アブサロムから逃れる者はいなくなるだろう。すぐ出発しよう。彼がすばやく追いついて、私たちに害を加え、剣の刃でこの都を討つといけないから。」'),
('JPN', '撒母耳记下', 10, 15, 15, '王の家来たちは王に言った。「ご覧ください。私たち、あなたのしもべどもは、王様の選ばれるままにいたします。」'),
('JPN', '撒母耳记下', 10, 15, 16, '王は出て行き、家族のすべての者も王に従った。しかし王は、王宮の留守番に十人の側女を残した。'),
('JPN', '撒母耳记下', 10, 15, 17, '王と、王に従うすべての民は、出て行って町外れの家にとどまった。'),
('JPN', '撒母耳记下', 10, 15, 18, '王のすべての家来は王の傍らを進み、すべてのクレタ人と、すべてのペレテ人、そしてガテから王について来た六百人のガテ人がみな、王の前を進んだ。'),
('JPN', '撒母耳记下', 10, 15, 19, '王はガテ人イタイに言った。「どうして、あなたもわれわれと一緒に行くのか。戻って、あの王のところにとどまりなさい。あなたは異国人で、自分の国からの亡命者なのだから。'),
('JPN', '撒母耳记下', 10, 15, 20, 'あなたは昨日来たばかりなのに、今日、あなたをわれわれと一緒にさまよわせるのは忍びない。私はこれから、あてどもなく旅を続けるのだから。あなたの兄弟を連れて戻りなさい。恵みとまことがあなたとともにあるように。」'),
('JPN', '撒母耳记下', 10, 15, 21, 'イタイは王に答えて言った。「主は生きておられます。そして、王様も生きておられます。王様がおられるところに、生きるためでも死ぬためでも、このしもべも必ずそこにいます。」'),
('JPN', '撒母耳记下', 10, 15, 22, 'ダビデはイタイに言った。「では、進んで行きなさい。」ガテ人イタイは、彼の部下全員と、一緒にいた子どもたち全員を連れて、進んで行った。'),
('JPN', '撒母耳记下', 10, 15, 23, 'この民がみな進んで行くとき、国中は大きな声をあげて泣いた。王はキデロンの谷を渡り、この民もみな、荒野の方へ渡って行った。'),
('JPN', '撒母耳记下', 10, 15, 24, '見よ、ツァドクも、すべてのレビ人と一緒に神の契約の箱を担いでいた。民がみな都から出て行ってしまうまで、彼らは神の箱を降ろし、エブヤタルがささげ物を献げた。'),
('JPN', '撒母耳记下', 10, 15, 25, '王はツァドクに言った。「神の箱を都に戻しなさい。もし私が主の恵みをいただくことができれば、主は、私を連れ戻し、神の箱とその住まいを見させてくださるだろう。'),
('JPN', '撒母耳记下', 10, 15, 26, 'もし主が『あなたはわたしの心にかなわない』と言われるなら、どうか、主が良いと思われることをこの私にしてくださるように。」'),
('JPN', '撒母耳记下', 10, 15, 27, '王は祭司ツァドクに言った。「あなたは先見者ではないか。安心して都に帰りなさい。あなたがたの二人の息子、あなたの息子アヒマアツとエブヤタルの息子ヨナタンも、あなたがたと一緒に。'),
('JPN', '撒母耳记下', 10, 15, 28, '見なさい。私は、あなたがたから知らせのことばが来るまで、荒野の草原でゆっくり待とう。」'),
('JPN', '撒母耳记下', 10, 15, 29, 'ツァドクとエブヤタルは神の箱をエルサレムに持ち帰り、そこにとどまった。'),
('JPN', '撒母耳记下', 10, 15, 30, 'ダビデはオリーブ山の坂を登った。彼は泣きながら登り、その頭をおおい、裸足で登った。彼と一緒にいた民もみな、頭をおおい、泣きながら登った。'),
('JPN', '撒母耳记下', 10, 15, 31, 'そのときダビデは、「アヒトフェルがアブサロムの謀反に荷担している」と知らされた。ダビデは言った。「主よ、どうかアヒトフェルの助言を愚かなものにしてください。」'),
('JPN', '撒母耳记下', 10, 15, 32, 'ダビデが、神を礼拝する場所になっていた山の頂に来たとき、見よ、アルキ人フシャイが上着を引き裂き、頭に土をかぶってダビデに会いに来た。'),
('JPN', '撒母耳记下', 10, 15, 33, 'ダビデは彼に言った。「もしあなたが私と一緒に行くなら、あなたは私の重荷になる。'),
('JPN', '撒母耳记下', 10, 15, 34, 'しかしもし、あなたが都に戻って、アブサロムに『王よ、私はあなたのしもべになります。これまであなたの父上のしもべであったように、今、私はあなたのしもべになります』と言うなら、あなたは私のためにアヒトフェルの助言を打ち破ることになる。'),
('JPN', '撒母耳记下', 10, 15, 35, 'あそこには祭司のツァドクとエブヤタルも、あなたと一緒にいるではないか。あなたは王の家から聞くことは何でも、祭司のツァドクとエブヤタルに告げるのだ。'),
('JPN', '撒母耳记下', 10, 15, 36, '見よ、あそこには、彼らの二人の息子、ツァドクの子アヒマアツとエブヤタルの子ヨナタンが彼らとともにいる。二人をよこして、あなたがたが聞いたことを残らず私に伝えてくれ。」'),
('JPN', '撒母耳记下', 10, 15, 37, 'ダビデの友フシャイは都に帰った。そのころ、アブサロムもエルサレムに着いた。'),
('JPN', '撒母耳记下', 10, 16, 1, 'ダビデは山の頂から少し下った。見ると、メフィボシェテのしもべツィバが王を迎えに来ていた。彼は、鞍を置いた一くびきのろばに、パン二百個、干しぶどう百房、夏の果物百個、ぶどう酒一袋を載せていた。'),
('JPN', '撒母耳记下', 10, 16, 2, '王はツィバに言った。「これらは何のためか。」ツィバは言った。「二頭のろばは王の家族がお乗りになるため、パンと夏の果物は若者たちが食べるため、ぶどう酒は荒野で疲れた者が飲むためです。」'),
('JPN', '撒母耳记下', 10, 16, 3, '王は言った。「あなたの主人の息子はどこにいるのか。」ツィバは王に言った。「今、エルサレムにとどまっております。あの方は、『今日、イスラエルの家は、父の王国を私に返してくれる』と言っておりました。」'),
('JPN', '撒母耳记下', 10, 16, 4, '王はツィバに言った。「見よ、メフィボシェテのものはみな、あなたのものだ。」ツィバは言った。「王様。あなた様のご好意をいただくことができますように、伏してお願いいたします。」'),
('JPN', '撒母耳记下', 10, 16, 5, 'ダビデ王がバフリムまで来ると、見よ、サウルの家の一族の一人が、そこから出て来た。その名はゲラの子シムイで、盛んに呪いのことばを吐きながら出て来た。'),
('JPN', '撒母耳记下', 10, 16, 6, '彼は、ダビデとダビデ王のすべての家来たちに向かって石を投げつけた。兵たちと勇士たちはみな、王の右左にいた。'),
('JPN', '撒母耳记下', 10, 16, 7, 'シムイは呪ってこう言った。「出て行け、出て行け。血まみれの男、よこしまな者よ。'),
('JPN', '撒母耳记下', 10, 16, 8, '主がサウルの家のすべての血に報いたのだ。サウルに代わって王となったおまえに対して。主は息子アブサロムの手に王位を渡した。今、おまえはわざわいにあうのだ。おまえは血まみれの男なのだから。」'),
('JPN', '撒母耳记下', 10, 16, 9, 'ツェルヤの子アビシャイが王に言った。「この死んだ犬めが、わが主君である王を呪ってよいものでしょうか。行って、あの首をはねさせてください。」'),
('JPN', '撒母耳记下', 10, 16, 10, '王は言った。「ツェルヤの息子たちよ。これは私のことで、あなたがたに何の関わりがあるのか。彼が呪うのは、主が彼に『ダビデを呪え』と言われたからだ。だれが彼に『おまえは、どうしてこういうことをするのだ』と言えるだろうか。」'),
('JPN', '撒母耳记下', 10, 16, 11, 'ダビデはアビシャイと彼のすべての家来たちに言った。「見よ。私の身から出た私の息子さえ、私のいのちを狙っている。今、このベニヤミン人としては、なおさらのことだ。放っておきなさい。彼に呪わせなさい。主が彼に命じられたのだから。'),
('JPN', '撒母耳记下', 10, 16, 12, 'おそらく、主は私の心をご覧になるだろう。そして主は今日の彼の呪いに代えて、私に良いことをもって報いてくださるだろう。」'),
('JPN', '撒母耳记下', 10, 16, 13, 'ダビデとその部下たちは道を進んで行った。シムイは、山の中腹をダビデと並行して歩きながら、呪ったり、石を投げたり、土のちりをかけたりしていた。'),
('JPN', '撒母耳记下', 10, 16, 14, '王も、王とともに行った兵もみな、疲れたのでそこで一息ついた。'),
('JPN', '撒母耳记下', 10, 16, 15, 'アブサロムとすべての民、イスラエルの人々はエルサレムに入った。アヒトフェルも一緒であった。'),
('JPN', '撒母耳记下', 10, 16, 16, 'ダビデの友アルキ人フシャイがアブサロムのところに来たとき、フシャイはアブサロムに言った。「王様万歳。王様万歳。」'),
('JPN', '撒母耳记下', 10, 16, 17, 'アブサロムはフシャイに言った。「これが、あなたの友への忠誠の表れなのか。なぜあなたは、あなたの友と一緒に行かなかったのか。」'),
('JPN', '撒母耳记下', 10, 16, 18, 'フシャイはアブサロムに言った。「いいえ、主と、この民、イスラエルのすべての人々が選んだ方に私はつき、その方と一緒にとどまります。'),
('JPN', '撒母耳记下', 10, 16, 19, 'また、私はだれに仕えるべきでしょうか。私の友の子に仕えるべきではありませんか。私はあなた様の父上に仕えたように、あなた様にもお仕えいたします。」'),
('JPN', '撒母耳记下', 10, 16, 20, 'アブサロムはアヒトフェルに言った。「あなたがたで相談しなさい。われわれは、どうしたらよいだろうか。」'),
('JPN', '撒母耳记下', 10, 16, 21, 'アヒトフェルはアブサロムに言った。「父上が王宮の留守番に残した側女たちのところにお入りください。全イスラエルが、あなたは父上に憎まれるようなことをされたと聞くでしょう。あなたに、くみする者はみな、勇気を出すでしょう。」'),
('JPN', '撒母耳记下', 10, 16, 22, 'アブサロムのために屋上に天幕が張られ、アブサロムは全イスラエルの目の前で、父の側女たちのところに入った。'),
('JPN', '撒母耳记下', 10, 16, 23, '当時、アヒトフェルの進言する助言は、人が神のことばを伺って得ることばのようであった。アヒトフェルの助言はすべて、ダビデにもアブサロムにもそのように思われた。'),
('JPN', '撒母耳记下', 10, 17, 1, 'アヒトフェルはアブサロムに言った。「私に一万二千人を選ばせてください。私は今夜すぐに、ダビデの後を追い始めます。'),
('JPN', '撒母耳记下', 10, 17, 2, '私は、彼が疲れて気力を失っている間に、彼を襲い、彼を震え上がらせます。彼と一緒にいるすべての民は逃げるでしょう。私は王だけを打ち殺します。'),
('JPN', '撒母耳记下', 10, 17, 3, '私は兵全員をあなたのもとに連れ戻します。すべての者が帰って来るとき、民はみな、穏やかになるでしょう。あなたが求めているのは、ただ一人の人だけですから。」'),
('JPN', '撒母耳记下', 10, 17, 4, 'このことばは、アブサロムとイスラエルの全長老の気に入るところとなった。'),
('JPN', '撒母耳记下', 10, 17, 5, 'アブサロムは言った。「アルキ人フシャイを呼び出し、彼の言うことも聞いてみよう。」'),
('JPN', '撒母耳记下', 10, 17, 6, 'フシャイがアブサロムのところに来ると、アブサロムは彼に言った。「アヒトフェルはこのように語ったが、われわれは彼のことばに従ってよいものだろうか。もしそうでなければ、あなたが語りなさい。」'),
('JPN', '撒母耳记下', 10, 17, 7, 'フシャイはアブサロムに言った。「このたびアヒトフェルの進言した助言は良くありません。」'),
('JPN', '撒母耳记下', 10, 17, 8, 'フシャイは言った。「あなたは父上とその部下が戦士であることをご存じです。彼らは、野で子を奪われた雌熊のように気が荒くなっています。また、あなたの父上は戦いに慣れた方ですから、兵たちと一緒には夜を過ごさないでしょう。'),
('JPN', '撒母耳记下', 10, 17, 9, 'きっと今、洞穴かどこか、そんな場所に隠れているに違いありません。もし、兵たちのある者が最初に倒れたら、それを聞く者は『アブサロムに従う兵たちのうちに、打たれた者が出た』と言うでしょう。'),
('JPN', '撒母耳记下', 10, 17, 10, 'たとえ、獅子のような心を持つ力ある者でも、気がくじけます。全イスラエルは、あなたの父上が勇士であり、彼とともにいる者が力ある者であるのをよく知っています。'),
('JPN', '撒母耳记下', 10, 17, 11, '私の助言はこうです。全イスラエルをダンからベエル・シェバに至るまで、海辺の砂のように数多くあなたのところに集めて、あなた自身が戦いに出られることです。'),
('JPN', '撒母耳记下', 10, 17, 12, 'われわれは彼が見つかる場所に行って、そこで露が地面に降りるように彼を襲うのです。そうすれば、彼や、ともにいるすべての兵たちのうちには、一人も残る者はありません。'),
('JPN', '撒母耳记下', 10, 17, 13, 'もし彼がどこかの町に入るなら、イスラエル中の者がその町に縄をかけ、その町を川まで引きずって行って、そこに一つの石ころも残らないようにしましょう。」'),
('JPN', '撒母耳记下', 10, 17, 14, 'アブサロムとイスラエルの人々はみな言った。「アルキ人フシャイの助言は、アヒトフェルの助言よりも良い。」これは、主がアブサロムにわざわいをもたらそうとして、主がアヒトフェルのすぐれた助言を打ち破ろうと定めておられたからである。'),
('JPN', '撒母耳记下', 10, 17, 15, 'フシャイは祭司ツァドクとエブヤタルに言った。「アヒトフェルは、アブサロムとイスラエルの長老たちにこれこれの助言をしたが、私は、これこれの助言をした。'),
('JPN', '撒母耳记下', 10, 17, 16, '今、急いで人を遣わして、ダビデに、『今夜は荒野の渡し場で夜を過ごしてはいけません。必ず、あちらへ渡って行かなければなりません。そうでないと、王をはじめ、一緒にいる民全員にわざわいが降りかかるでしょう』と告げなさい。」'),
('JPN', '撒母耳记下', 10, 17, 17, 'ヨナタンとアヒマアツはエン・ロゲルにとどまっていたが、一人の女奴隷が行って彼らに告げ、彼らがダビデ王に告げに行くようになっていた。これは、彼らが都に入るのを見られないようにするためであった。'),
('JPN', '撒母耳记下', 10, 17, 18, 'ところが、ある若者が彼らを見て、アブサロムに告げた。彼ら二人は急いで去り、バフリムに住むある人の家に行った。その人の庭に井戸があったので、彼らはその中に降りた。'),
('JPN', '撒母耳记下', 10, 17, 19, 'その人の妻は覆いを持って来て、井戸の口の上に広げ、その上に麦をまき散らしたので、だれにも知られなかった。'),
('JPN', '撒母耳记下', 10, 17, 20, 'アブサロムの家来たちが、その女の家に来て言った。「アヒマアツとヨナタンはどこにいるのか。」女は彼らに言った。「あの人たちは、ここを通り過ぎて川の方へ行きました。」彼らは、捜したが見つけることができなかったので、エルサレムへ帰った。'),
('JPN', '撒母耳记下', 10, 17, 21, '彼らが去った後、二人は井戸から上がって来て、ダビデ王に知らせに行った。彼らはダビデに言った。「さあ、急いで川を渡り始めてください。アヒトフェルがあなたがたに対して、これこれのことを進言したからです。」'),
('JPN', '撒母耳记下', 10, 17, 22, 'ダビデと、ダビデのもとにいたすべての者たちは、ヨルダン川を渡り始めた。夜明けまでにヨルダン川を渡りきれなかった者は一人もいなかった。'),
('JPN', '撒母耳记下', 10, 17, 23, 'アヒトフェルは、自分の助言が実行されないのを見ると、ろばに鞍を置いて自分の町の家に帰り、家を整理して首をくくって死んだ。彼は彼の父の墓に葬られた。'),
('JPN', '撒母耳记下', 10, 17, 24, 'ダビデがマハナイムに着いたとき、アブサロムは、彼とともにいるイスラエルのすべての人々とヨルダン川を渡った。'),
('JPN', '撒母耳记下', 10, 17, 25, 'アブサロムはアマサをヨアブの代わりに軍団長に任命していた。アマサは、アスリエル人イテラという人の息子で、イテラは、ヨアブの母ツェルヤの妹ナハシュの娘アビガルと結婚していた。'),
('JPN', '撒母耳记下', 10, 17, 26, 'イスラエルとアブサロムはギルアデの地に陣を敷いた。'),
('JPN', '撒母耳记下', 10, 17, 27, 'ダビデがマハナイムに来たとき、アンモン人でラバ出身のナハシュの息子ショビと、ロ・デバル出身のアンミエルの息子マキルと、ロゲリム出身のギルアデ人バルジライは、'),
('JPN', '撒母耳记下', 10, 17, 28, '寝台、鉢、土器、小麦、大麦、小麦粉、炒り麦、そら豆、レンズ豆、炒り豆、'),
('JPN', '撒母耳记下', 10, 17, 29, '蜂蜜、凝乳、羊、チーズを、ダビデと彼とともにいた民の食糧として持って来た。彼らが「民は荒野で飢えて疲れ、渇いています」と言ったからである。'),
('JPN', '撒母耳记下', 10, 18, 1, 'ダビデは自分とともにいる兵を調べて、彼らの上に千人隊の長、百人隊の長を任命した。'),
('JPN', '撒母耳记下', 10, 18, 2, 'ダビデは兵の三分の一をヨアブの指揮のもとに、三分の一をヨアブの兄弟である、ツェルヤの子アビシャイの指揮のもとに、三分の一をガテ人イタイの指揮のもとに配置した。王は兵たちに言った。「私自身も、あなたがたと一緒に出陣する。」'),
('JPN', '撒母耳记下', 10, 18, 3, '兵たちは言った。「王様が出陣してはいけません。私たちがどんなに逃げても、彼らは私たちのことは何とも思わないでしょう。私たちの半分が死んでも、彼らは私たちのことは心に留めないでしょう。しかし、今、あなたは私たちの一万人に当たります。今、あなたは町にいて私たちを助けてくださるほうがよいのです。」'),
('JPN', '撒母耳记下', 10, 18, 4, '王は彼らに言った。「あなたがたが良いと思うことを、私はしよう。」王は門のそばに立ち、兵はみな、百人、千人ごとに出て行った。'),
('JPN', '撒母耳记下', 10, 18, 5, '王はヨアブ、アビシャイ、イタイに命じて言った。「私に免じて、若者アブサロムをゆるやかに扱ってくれ。」兵はみな、王が隊長たち全員にアブサロムのことについて命じているのを聞いていた。'),
('JPN', '撒母耳记下', 10, 18, 6, '兵たちはイスラエルに対抗するために戦場へ出て行った。戦いはエフライムの森で行われた。'),
('JPN', '撒母耳记下', 10, 18, 7, 'イスラエルの兵たちは、そこでダビデの家来たちに打ち負かされ、その日その場所で多くの者が倒れ、その数は二万人となった。'),
('JPN', '撒母耳记下', 10, 18, 8, '戦いはこの地一帯に広がり、この日、剣よりも密林のほうが多くの者を食い尽くした。'),
('JPN', '撒母耳记下', 10, 18, 9, 'アブサロムはダビデの家来たちに出会った。アブサロムはらばに乗っていたが、らばが大きな樫の木の、茂った枝の下を通った。すると、アブサロムの頭が樫の木に引っ掛かり、彼は宙づりになった。彼が乗っていたらばはそのまま行ってしまった。'),
('JPN', '撒母耳记下', 10, 18, 10, 'ある男がそれを見て、ヨアブに告げて言った。「今、アブサロムが樫の木に引っ掛かっているのを見ました。」'),
('JPN', '撒母耳记下', 10, 18, 11, 'ヨアブは、これを告げた男に言った。「いったい、おまえはそれを見ていて、なぜその場で地に打ち落とさなかったのか。私はおまえに銀十枚と帯一本を与えたのに。」'),
('JPN', '撒母耳记下', 10, 18, 12, 'その男はヨアブに言った。「たとえ、私の手に銀千枚をいただいても、王のご子息に手は下せません。王が私たちが聞いているところで、あなたとアビシャイとイタイに、『私のために若者アブサロムを守ってくれ』と言って、お命じになったからです。'),
('JPN', '撒母耳记下', 10, 18, 13, 'もし、私が偽って彼のいのちに対して事を起こしていたとしても、王には何も隠すことはできません。あなたは素知らぬ顔をなさるでしょうが。」'),
('JPN', '撒母耳记下', 10, 18, 14, 'ヨアブは、「こうしておまえとぐずぐずしてはいられない」と言って、手に三本の槍を取り、まだ樫の木の真ん中に引っ掛かったまま生きていたアブサロムの心臓を突き通した。'),
('JPN', '撒母耳记下', 10, 18, 15, 'ヨアブの道具持ちの十人の若者たちも、アブサロムを取り巻いて彼を打ち殺した。'),
('JPN', '撒母耳记下', 10, 18, 16, 'ヨアブが角笛を吹き鳴らすと、兵たちはイスラエルを追うのをやめて帰って来た。ヨアブが兵たちを引き止めたからである。'),
('JPN', '撒母耳记下', 10, 18, 17, '彼らはアブサロムを取り降ろし、森の中の深い穴に投げ込み、その上に非常に大きな石塚を積み上げた。イスラエルはみな、それぞれ自分の天幕に逃げ帰っていた。'),
('JPN', '撒母耳记下', 10, 18, 18, 'アブサロムは生きていた間、王の谷に自分のために一本の柱を立てていた。「私の名を覚えてくれる息子が私にはいないから」と言っていたからである。彼はその柱に自分の名をつけていた。それは、アブサロムの記念碑と呼ばれた。今日もそうである。'),
('JPN', '撒母耳记下', 10, 18, 19, 'ツァドクの子アヒマアツは言った。「私は王のところへ走って行って、主が敵の手から王を救って、王のために正しいさばきをされたことを伝えたいのですが。」'),
('JPN', '撒母耳记下', 10, 18, 20, 'ヨアブは彼に言った。「今日、伝えるのではない。ほかの日に伝えよ。今日は伝えないのがよい。王子が死んだのだから。」'),
('JPN', '撒母耳记下', 10, 18, 21, 'ヨアブはクシュ人に言った。「行って、あなたの見たことを王に告げよ。」クシュ人はヨアブに礼をして、走り去った。'),
('JPN', '撒母耳记下', 10, 18, 22, 'ツァドクの子アヒマアツは再びヨアブに言った。「どんなことがあっても、やはり私もクシュ人の後を追って走って行きたいのです。」ヨアブは言った。「わが子よ、なぜ、あなたは走って行きたいのか。知らせに対して、何のほうびも得られないのに。」'),
('JPN', '撒母耳记下', 10, 18, 23, '「しかし、どんなことがあっても、走って行きたいのです。」ヨアブは「走って行け」と言った。アヒマアツは低地への道を走って行き、クシュ人を追い越した。'),
('JPN', '撒母耳记下', 10, 18, 24, 'ダビデは外門と内門の間に座っていた。見張りが城壁の門の屋根に上り、目を上げて見ていると、見よ、ただ一人で走って来る男がいた。'),
('JPN', '撒母耳记下', 10, 18, 25, '見張りが王に大声で告げると、王は言った。「ただ一人なら、吉報だろう。」その者がしだいに近づいて来た。'),
('JPN', '撒母耳记下', 10, 18, 26, '見張りは、別の男が走って来るのを見た。見張りは門衛に叫んだ。「あそこにも、一人で走って来る男がいる。」王は言った。「それも吉報を持って来ているのだろう。」'),
('JPN', '撒母耳记下', 10, 18, 27, '見張りは言った。「最初の者の走り方は、ツァドクの子アヒマアツのもののように見えます。」王は言った。「あれは良い男だ。良い知らせを持って来るだろう。」'),
('JPN', '撒母耳记下', 10, 18, 28, 'アヒマアツは王に「平安がありますように」と叫んで、地にひれ伏して、王に礼をした。彼は言った。「あなたの神、主がほめたたえられますように。主は、王様に手向かった者どもを引き渡してくださいました。」'),
('JPN', '撒母耳记下', 10, 18, 29, '王は言った。「若者アブサロムは無事か。」アヒマアツは言った。「ヨアブが王の家来であるこのしもべを遣わしたとき、何か大騒ぎが起こるのを見ましたが、私は何があったのか知りません。」'),
('JPN', '撒母耳记下', 10, 18, 30, '王は言った。「わきへ退いて、ここに立っていなさい。」彼はわきに退いて立っていた。'),
('JPN', '撒母耳记下', 10, 18, 31, '見ると、クシュ人がやって来て言った。「王様にお知らせいたします。主は、今日、あなた様に立ち向かうすべての者の手から、あなた様を救って、あなた様のために正しいさばきをされました。」'),
('JPN', '撒母耳记下', 10, 18, 32, '王はクシュ人に言った。「若者アブサロムは無事か。」クシュ人は言った。「王様の敵、あなた様に立ち向かって害を加えようとする者はみな、あの若者のようになりますように。」'),
('JPN', '撒母耳记下', 10, 18, 33, '王は身を震わせ、門の屋上に上り、そこで泣いた。彼は泣きながら、こう言い続けた。「わが子アブサロム。わが子、わが子アブサロムよ。ああ、私がおまえに代わって死ねばよかったのに。アブサロム。わが子よ、わが子よ。」'),
('JPN', '撒母耳记下', 10, 19, 1, 'そのようなときに、ヨアブに、「今、王は泣いて、アブサロムのために喪に服しておられる」という知らせがあった。'),
('JPN', '撒母耳记下', 10, 19, 2, 'その日の勝利は、すべての兵たちの嘆きとなった。その日兵たちは、王が息子のために悲しんでいるということを聞いたからである。'),
('JPN', '撒母耳记下', 10, 19, 3, '兵たちはその日、まるで戦場から逃げて恥じている兵がこっそり帰るように、町にこっそり帰って来た。'),
('JPN', '撒母耳记下', 10, 19, 4, '王は顔をおおい、大声で、「わが子アブサロム、アブサロムよ。わが子よ、わが子よ」と叫んでいた。'),
('JPN', '撒母耳记下', 10, 19, 5, 'ヨアブは王の家に来て言った。「今日あなたのいのちと、あなたの息子、娘たちのいのち、そして妻や側女たちのいのちを救ってくれたあなたの家来たち全員に、あなたは今日、恥をかかせられました。'),
('JPN', '撒母耳记下', 10, 19, 6, 'あなたは、あなたを憎む者を愛し、あなたを愛する者を憎まれるからです。あなたは今日、隊長たちも家来たちも、あなたにとっては取るに足りないものであることを明らかにされました。今、私は知りました。もしアブサロムが生き、われわれがみな今日死んだなら、それはあなたの目にかなったのでしょう。'),
('JPN', '撒母耳记下', 10, 19, 7, 'さあ今、立って外に行き、あなたの家来たちの心に語ってください。私は主によって誓います。あなたが外においでにならなければ、今夜、だれ一人あなたのそばにとどまらないでしょう。そうなれば、そのわざわいは、あなたの幼いころから今に至るまでにあなたに降りかかった、どんなわざわいよりもひどいものとなるでしょう。」'),
('JPN', '撒母耳记下', 10, 19, 8, '王は立って、門のところに座った。人々はすべての兵たちに「見なさい。王は門のところに座っておられる」と知らせた。兵たちはみな王の前にやって来た。一方、イスラエルは、それぞれ自分たちの天幕に逃げ帰っていた。'),
('JPN', '撒母耳记下', 10, 19, 9, 'イスラエルの全部族の間で、民はみなこう言って争っていた。「王が敵の手から、われわれを救い出してくださったのだ。われわれをペリシテ人の手から助け出してくださったのは王だ。ところが今、王はアブサロムのいるところから国外に逃げておられる。'),
('JPN', '撒母耳记下', 10, 19, 10, 'われわれが油を注いで王としたアブサロムは、戦いで死んでしまった。あなたがたは今、王を連れ戻すために、なぜ何もしないでいるのか。」'),
('JPN', '撒母耳记下', 10, 19, 11, 'ダビデ王は、祭司ツァドクとエブヤタルに人を遣わして言った。「ユダの長老たちにこう告げなさい。『全イスラエルの言っていることが、ここの家にいる王の耳に届いたのに、あなたがたは、なぜ王をその王宮に連れ戻すことをいつまでもためらっているのか。'),
('JPN', '撒母耳记下', 10, 19, 12, 'あなたがたは、私の兄弟、私の骨肉だ。なぜ王を連れ戻すのをいつまでもためらっているのか。』'),
('JPN', '撒母耳记下', 10, 19, 13, 'アマサにも言わなければならない。『あなたは私の骨肉ではないか。もしあなたが、ヨアブに代わってこれからいつまでも、私の軍の長にならないなら、神がこの私を幾重にも罰せられるように。』」'),
('JPN', '撒母耳记下', 10, 19, 14, 'すべてのユダの人々は、あたかも一人の人のように心を動かされた。彼らは王のもとに人を遣わして、「あなたも家来たちもみな、お帰りください」と言った。'),
('JPN', '撒母耳记下', 10, 19, 15, '王は帰途につき、ヨルダン川までやって来た。一方、ユダの人々は、王を迎えてヨルダン川を渡らせるためにギルガルに来た。'),
('JPN', '撒母耳记下', 10, 19, 16, 'バフリム出身のベニヤミン人、ゲラの子シムイは、ダビデ王を迎えようと、急いでユダの人々と一緒に下って来た。'),
('JPN', '撒母耳记下', 10, 19, 17, '彼は千人のベニヤミン人を連れていた。サウルの家のしもべツィバも、十五人の息子、二十人の召使いを連れて、王が見ている前でヨルダン川に駆けつけた。'),
('JPN', '撒母耳记下', 10, 19, 18, 'そして、王の家族を渡らせるため、また王の目にかなうことをするために、渡しを整えた。ゲラの子シムイはヨルダン川を渡って行き、王の前に倒れ伏して、'),
('JPN', '撒母耳记下', 10, 19, 19, '王に言った。「わが君、どうか私の咎を罰しないでください。王様がエルサレムから出て行かれた日に、このしもべが犯した咎を、思い出さないでください。王様、心に留めないでください。'),
('JPN', '撒母耳记下', 10, 19, 20, 'このしもべは、自分が罪を犯したことを知っています。ご覧ください。今日、ヨセフのすべての家に先立って、わが君、王様を迎えに下って参りました。」'),
('JPN', '撒母耳记下', 10, 19, 21, 'ツェルヤの子アビシャイは口をはさんで言った。「シムイは、主に油注がれた方を呪ったので、そのために死に値するのではありませんか。」'),
('JPN', '撒母耳记下', 10, 19, 22, 'ダビデは言った。「ツェルヤの息子たちよ。あれは私のことで、あなたがたに何の関わりがあるのか。あなたがたが、今日、私に敵対する者になろうとするとは。今日、イスラエルのうちで人が殺されてよいだろうか。私が今日イスラエルの王であることを、私が知らないとでもいうのか。」'),
('JPN', '撒母耳记下', 10, 19, 23, '王はシムイに言った。「あなたは死ぬことはない。」王は彼にそう誓った。'),
('JPN', '撒母耳记下', 10, 19, 24, 'サウルの孫メフィボシェテは、王を迎えに下って来た。彼は、王が出て行った日から無事に帰って来た日まで、自分の足の手入れもせず、ひげも剃らず、衣服も洗っていなかった。'),
('JPN', '撒母耳记下', 10, 19, 25, '彼が王を迎えにエルサレムから来たとき、王は彼に言った。「メフィボシェテよ、あなたはなぜ、私とともに来なかったのか。」'),
('JPN', '撒母耳记下', 10, 19, 26, '彼は言った。「わが君、王様。家来が私をたぶらかしたのです。このしもべは『ろばに鞍を置き、それに乗って、王と一緒に行こう』と言ったのです。しもべは足の萎えた者ですから。'),
('JPN', '撒母耳记下', 10, 19, 27, '彼がこのしもべのことを王様に中傷したのです。しかし、王様は神の使いのような方ですから、お気に召すようにしてください。'),
('JPN', '撒母耳记下', 10, 19, 28, '私の父の家の者はみな、王様から見れば、死刑に当たる者にすぎなかったのですが、あなたは、このしもべをあなたの食卓で食事をする者のうちに入れてくださいました。ですから、この私に、どうして重ねて王様に訴える権利があるでしょう。」'),
('JPN', '撒母耳记下', 10, 19, 29, '王は彼に言った。「あなたはなぜ、自分のことをまだ語るのか。私は決めている。あなたとツィバとで地所を分けるのだ。」'),
('JPN', '撒母耳记下', 10, 19, 30, 'メフィボシェテは王に言った。「王様が無事に王宮に帰られた後なら、彼が全部取ってもかまいません。」'),
('JPN', '撒母耳记下', 10, 19, 31, '一方、ギルアデ人バルジライはロゲリムから下って来た。そして、ヨルダン川で王を見送るために、王とともにヨルダン川まで進んで来た。'),
('JPN', '撒母耳记下', 10, 19, 32, 'このバルジライは、たいへん年をとっていて八十歳であった。彼は王がマハナイムにいる間、王を養っていた。非常に裕福な人だったからである。'),
('JPN', '撒母耳记下', 10, 19, 33, '王はバルジライに言った。「私と一緒に渡って行ってください。エルサレムの私のもとで、あなたを養います。」'),
('JPN', '撒母耳记下', 10, 19, 34, 'バルジライは王に言った。「王様とともにエルサレムへ上って行っても、私はあと何年生きられるでしょう。'),
('JPN', '撒母耳记下', 10, 19, 35, '私は今、八十歳です。私に善し悪しが分かるでしょうか。しもべは食べる物も飲む物も味わうことができません。歌う男や女の声を聞くことさえできません。どうして、この上、しもべが王様の重荷になれるでしょう。'),
('JPN', '撒母耳记下', 10, 19, 36, 'このしもべは、王様とともにヨルダン川をほんの少しだけ進んで参りましょう。王様は、そのような報酬を、どうしてこの私に下さらなければならないのでしょう。'),
('JPN', '撒母耳记下', 10, 19, 37, 'このしもべを帰らせてください。私は自分の町で、父と母の墓の近くで死にたいのです。ご覧ください。ここに、あなたのしもべキムハムがおります。彼が、王様と一緒に渡って参ります。どうか彼に、あなたの良いと思われることをなさってください。」'),
('JPN', '撒母耳记下', 10, 19, 38, '王は言った。「キムハムは私と一緒に渡って行けばよい。私は、あなたが良いと思うことを彼にしよう。あなたが私にしてほしいことは何でも、あなたにしてあげよう。」'),
('JPN', '撒母耳记下', 10, 19, 39, 'こうして、民はみなヨルダン川を渡り、王も渡った。王はバルジライに別れの口づけをして、彼を祝福した。それで、バルジライは自分の町へ帰って行った。'),
('JPN', '撒母耳记下', 10, 19, 40, 'それから、王はギルガルへ進み、キムハムも王とともに進んだ。ユダのすべての民とイスラエルの民の半分が、王とともに進んだ。'),
('JPN', '撒母耳记下', 10, 19, 41, 'するとそこに、イスラエルのすべての人が王のところにやって来て、王に言った。「われわれの同胞、ユダの人々は、なぜ、あなたを奪い去り、王とその家族に、また王とともにいるダビデの部下たちに、ヨルダン川を渡らせたのですか。」'),
('JPN', '撒母耳记下', 10, 19, 42, 'ユダのすべての人々はイスラエルの人々に答えた。「王は、われわれの身内だからだ。なぜ、このことでそんなに怒るのか。いったい、われわれが王の食物を食べたとでもいうのか。王が何かわれわれに贈り物をしたとでもいうのか。」'),
('JPN', '撒母耳记下', 10, 19, 43, 'イスラエルの人々はユダの人々に答えて言った。「われわれは、王のうちに十の分を持っている。だからダビデにも、あなたがたよりも多くを持っている。なぜ、われわれをないがしろにするのか。われわれの王を連れ戻そうと最初に言い出したのは、われわれではないか。」しかし、ユダの人々のことばは、イスラエルの人々のことばより激しかった。'),
('JPN', '撒母耳记下', 10, 20, 1, 'たまたまそこに、よこしまな者で、名をシェバという者がいた。彼はベニヤミン人ビクリの息子であった。彼は角笛を吹き鳴らして言った。「ダビデのうちには、われわれのための割り当て地はない。エッサイの子のうちには、われわれのためのゆずりの地はない。イスラエルよ、それぞれ自分の天幕に帰れ。」'),
('JPN', '撒母耳记下', 10, 20, 2, 'すべてのイスラエルの人々は、ダビデから離れ、ビクリの子シェバに従って行った。しかし、ユダの人々はヨルダン川からエルサレムまで、自分たちの王につき従って行った。'),
('JPN', '撒母耳记下', 10, 20, 3, 'ダビデはエルサレムの自分の王宮に入った。王は、王宮の留守番に残しておいた十人の側女をとり、監視つきの家を与えて養ったが、彼女たちのところには通わなかった。彼女たちは、一生、やもめとなって、死ぬ日まで閉じ込められていた。'),
('JPN', '撒母耳记下', 10, 20, 4, '王はアマサに言った。「私のために、ユダの人々を三日のうちに召集し、あなたも、ここに帰って来なさい。」'),
('JPN', '撒母耳记下', 10, 20, 5, 'アマサは、ユダの人々を召集するために出て行ったが、指定された期限に間に合わなかった。'),
('JPN', '撒母耳记下', 10, 20, 6, 'ダビデはアビシャイに言った。「今や、ビクリの子シェバは、アブサロムよりも、もっとひどいわざわいを、われわれに仕掛けるに違いない。あなたは、主君の家来を引き連れて彼を追いなさい。さもないと、彼は城壁のある町に入って、逃れてしまうだろう。」'),
('JPN', '撒母耳记下', 10, 20, 7, 'ヨアブの部下、クレタ人、ペレテ人、そしてすべての勇士たちは、アビシャイの後に続いて出て行った。彼らはエルサレムを出て、ビクリの子シェバの後を追った。'),
('JPN', '撒母耳记下', 10, 20, 8, '彼らがギブオンにある大きな石のそばに来たとき、アマサが彼らの前にやって来た。ヨアブは自分のよろいを身に着け、さやに収めた剣を腰の上に帯で結び付けていた。彼が進み出ると、剣が落ちた。'),
('JPN', '撒母耳记下', 10, 20, 9, 'ヨアブはアマサに「兄弟、おまえは無事か」と言って、アマサに口づけしようとして、右手でアマサのひげをつかんだ。'),
('JPN', '撒母耳记下', 10, 20, 10, 'アマサはヨアブの手にある剣に気をつけていなかった。ヨアブは彼の下腹を突いた。それで、はらわたが地面に流れ出た。この一突きでアマサは死んだ。ヨアブとその兄弟アビシャイは、ビクリの子シェバの後を追った。'),
('JPN', '撒母耳记下', 10, 20, 11, 'ヨアブに仕える若者の一人がアマサのそばに立って言った。「ヨアブにつく者、ダビデに味方する者は、ヨアブに従え。」'),
('JPN', '撒母耳记下', 10, 20, 12, 'アマサは大路の真ん中で、血まみれになって転がっていた。この若者は、兵がみな立ち止まるのを見て、アマサを大路から野原に運んだ。そして、その傍らを通る者がみな立ち止まるのを見ると、彼の上に衣を掛けた。'),
('JPN', '撒母耳记下', 10, 20, 13, 'アマサが大路から移されると、みなヨアブの後について進み、ビクリの子シェバを追った。'),
('JPN', '撒母耳记下', 10, 20, 14, 'シェバはイスラエルの全部族のうちを通って、アベル・ベテ・マアカへ行った。すべてのベリ人が集まって来て、彼に従った。'),
('JPN', '撒母耳记下', 10, 20, 15, '人々はアベル・ベテ・マアカに来て、彼を包囲し、この町に向かって塁を築いた。それは外壁に向かって立てられた。ヨアブにつく兵はみな、城壁を破壊して倒そうとしていた。'),
('JPN', '撒母耳记下', 10, 20, 16, 'この町から、一人の知恵のある女が叫んだ。「聞いてください。聞いてください。ヨアブにこう言ってください。『ここまで近づいてください。あなたにお話ししたいのです。』」'),
('JPN', '撒母耳记下', 10, 20, 17, 'ヨアブが彼女の方に近づくと、この女は言った。「あなたがヨアブですか。」彼は言った。「そうだ。」女は言った。「このはしためのことばを聞いてください。」彼は言った。「よし、聞こう。」'),
('JPN', '撒母耳记下', 10, 20, 18, '女は言った。「昔、人々は『アベルで尋ねよ』と言って、事を決めました。'),
('JPN', '撒母耳记下', 10, 20, 19, '私は、イスラエルのうちで平和な、忠実な者の一人です。あなたは、イスラエルの母である町を滅ぼそうとしておられます。あなたはなぜ、主のゆずりの地を、吞み尽くそうとされるのですか。」'),
('JPN', '撒母耳记下', 10, 20, 20, 'ヨアブは答えて言った。「とんでもない。吞み尽くしたり滅ぼしたりするなど、とんでもないことだ。'),
('JPN', '撒母耳记下', 10, 20, 21, 'そうではない。実はビクリの息子で、その名をシェバというエフライムの山地の出である男が、ダビデ王に手向かったのだ。この男だけを引き渡してくれたら、私はこの町から引き揚げよう。」女はヨアブに言った。「では、その男の首を城壁の上からあなたのところに投げ落としてごらんにいれます。」'),
('JPN', '撒母耳记下', 10, 20, 22, 'この女は知恵を用いて、民全員のところに行った。それで彼らはビクリの子シェバの首をはね、それをヨアブのもとに投げた。ヨアブは角笛を吹き鳴らし、人々は町から散って行き、それぞれ自分の天幕に帰った。ヨアブはエルサレムの王のところに戻った。'),
('JPN', '撒母耳记下', 10, 20, 23, 'さて、ヨアブはイスラエルの全軍の長であった。エホヤダの子ベナヤはクレタ人とペレテ人の長、'),
('JPN', '撒母耳记下', 10, 20, 24, 'アドラムは役務長官、アヒルデの子ヨシャファテは史官、'),
('JPN', '撒母耳记下', 10, 20, 25, 'シェワは書記、ツァドクとエブヤタルは祭司、'),
('JPN', '撒母耳记下', 10, 20, 26, 'ヤイル人イラもダビデの祭司であった。'),
('JPN', '撒母耳记下', 10, 21, 1, 'ダビデの時代に、三年間引き続いて飢饉が起こった。それで、ダビデは主の御顔を求めた。主は言われた。「サウルとその一族に、血の責任がある。彼がギブオン人たちを殺戮したからだ。」'),
('JPN', '撒母耳记下', 10, 21, 2, '王はギブオン人たちを呼び出し、彼らに話した。このギブオンの人たちは、イスラエル人ではなくアモリ人の生き残りで、イスラエル人は彼らと盟約を結んでいた。だが、サウルはイスラエルとユダの人々への熱心のあまり、彼らを討とうとしたのである。'),
('JPN', '撒母耳记下', 10, 21, 3, 'ダビデはギブオン人たちに言った。「あなたがたのために、私は何をすべきであろうか。私が何をもって宥めを行ったら、主のゆずりの地が祝福されるだろうか。」'),
('JPN', '撒母耳记下', 10, 21, 4, 'ギブオン人たちは彼に言った。「私たちと、サウルおよびその一族との間の問題は、銀や金のことではありません。また、私たちがイスラエルのうちで人を殺すことでもありません。」ダビデは言った。「私があなたがたに何をしたらよいと思うのか。」'),
('JPN', '撒母耳记下', 10, 21, 5, '彼らは王に言った。「私たちを絶ち滅ぼそうとした者、私たちを根絶やしにしてイスラエルの領土のどこにも、いさせないように企んだ者、'),
('JPN', '撒母耳记下', 10, 21, 6, 'その者の息子の七人を私たちに引き渡してください。私たちは主が選ばれたサウルのギブアで、主のために彼らをさらし者にします。」王は言った。「引き渡そう。」'),
('JPN', '撒母耳记下', 10, 21, 7, '王は、サウルの子ヨナタンの子メフィボシェテを惜しんだ。それは、ダビデとサウルの子ヨナタンの間で主に誓った誓いのためであった。'),
('JPN', '撒母耳记下', 10, 21, 8, '王は、アヤの娘リツパがサウルに産んだ二人の息子アルモニとメフィボシェテ、それに、サウルの娘メラブがメホラ人バルジライの息子アデリエルに産んだ五人の息子を取って、'),
('JPN', '撒母耳记下', 10, 21, 9, '彼らをギブオン人の手に渡した。彼らは、この者たちを山の上で主の前に、さらし者にした。これら七人は一緒に倒れた。彼らは、刈り入れ時の初め、大麦の刈り入れの始まったころ殺された。'),
('JPN', '撒母耳记下', 10, 21, 10, 'アヤの娘リツパは、粗布を手に取って、それを岩の上に敷いて座り、刈り入れの始まりから雨が天から彼らの上に降るときまで、昼には空の鳥が、夜には野の獣が死体に近寄らないようにした。'),
('JPN', '撒母耳记下', 10, 21, 11, 'サウルの側女アヤの娘リツパのしたことはダビデに知らされた。'),
('JPN', '撒母耳记下', 10, 21, 12, 'ダビデは行って、サウルの骨とその息子ヨナタンの骨を、ヤベシュ・ギルアデの者たちのところから持って来た。これは、ペリシテ人がサウルをギルボアで討った日に、二人をさらし者にしたベテ・シャンの広場から、ヤベシュ・ギルアデの者たちが盗んで行ったものであった。'),
('JPN', '撒母耳记下', 10, 21, 13, 'ダビデはサウルの骨とその息子ヨナタンの骨をそこから携えて上った。人々は、さらし者にされた者たちの骨を集めた。'),
('JPN', '撒母耳记下', 10, 21, 14, '彼らはサウルとその息子ヨナタンの骨を、ベニヤミンの地のツェラにあるサウルの父キシュの墓に葬り、すべて王が命じたとおりにした。その後、神はこの国の祈りに心を動かされた。'),
('JPN', '撒母耳记下', 10, 21, 15, 'ペリシテ人が再びイスラエルに戦いを仕掛けたことがあった。ダビデは自分の家来たちを連れて下り、ペリシテ人と戦ったが、ダビデは疲れていた。'),
('JPN', '撒母耳记下', 10, 21, 16, 'ラファの子孫の一人であったイシュビ・ベノブは、「ダビデを討つ」と言った。彼の槍の重さは青銅で三百シェケル。そして彼は新しい剣を帯びていた。'),
('JPN', '撒母耳记下', 10, 21, 17, 'ツェルヤの子アビシャイはダビデを助け、このペリシテ人を打ち殺した。そのとき、ダビデの部下たちは彼に誓って言った。「あなたは、もうこれから、われわれと一緒に戦いに出ないでください。あなたがイスラエルのともしびを消さないために。」'),
('JPN', '撒母耳记下', 10, 21, 18, 'その後のこと、ゴブで再びペリシテ人との戦いがあった。そのとき、フシャ人シベカイは、ラファの子孫のサフを打ち殺した。'),
('JPN', '撒母耳记下', 10, 21, 19, 'ゴブでペリシテ人との戦いが再びあったとき、ベツレヘム人ヤイルの子エルハナンは、ガテ人ゴリヤテを打ち殺した。ゴリヤテの槍の柄は、機織りの巻き棒のようであった。'),
('JPN', '撒母耳记下', 10, 21, 20, '再びガテで戦いがあったとき、手の指、足の指が六本ずつで、合計二十四本指の闘士がいた。彼もラファの子孫であった。'),
('JPN', '撒母耳记下', 10, 21, 21, '彼はイスラエルをそしったが、ダビデの兄弟シムアの子ヨナタンが彼を打ち殺した。'),
('JPN', '撒母耳记下', 10, 21, 22, 'これら四人はガテのラファの子孫で、ダビデとその家来たちの手にかかって倒れた。'),
('JPN', '撒母耳记下', 10, 22, 1, '主がダビデを、すべての敵の手、特にサウルの手から救い出された日に、彼はこの歌のことばを主に歌った。'),
('JPN', '撒母耳记下', 10, 22, 2, '彼は言った。「主よ、わが巌、わが砦、わが救い主よ、'),
('JPN', '撒母耳记下', 10, 22, 3, '身を避ける、わが岩なる神よ。わが盾、わが救いの角、わがやぐら、わが逃れ場、わが救い主、あなたは私を暴虐から救われます。'),
('JPN', '撒母耳记下', 10, 22, 4, 'ほめたたえられる方、この主を呼び求めると、私は敵から救われる。'),
('JPN', '撒母耳记下', 10, 22, 5, '死の波は私を取り巻き、滅びの激流は私をおびえさせた。'),
('JPN', '撒母耳记下', 10, 22, 6, 'よみの綱は私を取り囲み、死の罠は私に立ち向かった。'),
('JPN', '撒母耳记下', 10, 22, 7, '私は苦しみの中で主を呼び求め、わが神に叫んだ。主はその宮で私の声を聞かれ、私の叫びは御耳に届いた。'),
('JPN', '撒母耳记下', 10, 22, 8, '地は揺るぎ、動いた。天の基も震え、揺れた。主が怒られたからだ。'),
('JPN', '撒母耳记下', 10, 22, 9, '煙は鼻から立ち上り、その口から出る火は貪り食い、炭火は主から燃え上がった。'),
('JPN', '撒母耳记下', 10, 22, 10, '主は、天を押し曲げて降りて来られた。黒雲をその足の下にして。'),
('JPN', '撒母耳记下', 10, 22, 11, '主は、ケルビムに乗って飛び、風の翼の上に自らを現された。'),
('JPN', '撒母耳记下', 10, 22, 12, '主は、闇をご自分の周りで仮庵とされた。水の集まり、濃い雲を。'),
('JPN', '撒母耳记下', 10, 22, 13, '御前の輝きから、炭火が燃え上がった。'),
('JPN', '撒母耳记下', 10, 22, 14, '主は天から雷鳴を響かせ、いと高き方は御声を発せられた。'),
('JPN', '撒母耳记下', 10, 22, 15, '主は矢を放って、彼らを散らし、稲妻を放って、かき乱された。'),
('JPN', '撒母耳记下', 10, 22, 16, 'こうして、海の底が現れ、地の基があらわにされた。主のとがめにより、その鼻の荒い息吹によって。'),
('JPN', '撒母耳记下', 10, 22, 17, '主は、高い所から御手を伸ばして私を捕らえ、大水から、私を引き上げられました。'),
('JPN', '撒母耳记下', 10, 22, 18, '主は、力ある敵から私を救い出されました。私を憎む者どもからも。彼らは私より強かったのです。'),
('JPN', '撒母耳记下', 10, 22, 19, '私のわざわいの日に彼らは立ちはだかりました。けれども、主は私の支えとなられました。'),
('JPN', '撒母耳记下', 10, 22, 20, '主は私を広いところに連れ出し、私を助け出されました。主が私を喜びとされたからです。'),
('JPN', '撒母耳记下', 10, 22, 21, '主は、私の義にしたがって私に報い、手のきよさにしたがって顧みてくださいました。'),
('JPN', '撒母耳记下', 10, 22, 22, '私は主の道を守り、私の神に対して悪を行いませんでした。'),
('JPN', '撒母耳记下', 10, 22, 23, '主のすべてのさばきは私の前にあり、主の掟から、私は遠ざかりませんでした。'),
('JPN', '撒母耳记下', 10, 22, 24, '私は主に対して全き者。自分の咎から身を守ります。'),
('JPN', '撒母耳记下', 10, 22, 25, '主は私の義にしたがって顧みてくださいました。御目の前の、私のきよさにしたがって。'),
('JPN', '撒母耳记下', 10, 22, 26, 'あなたは、恵み深い者には恵み深く、全き者には全き方。'),
('JPN', '撒母耳记下', 10, 22, 27, '清い者には清く、曲がった者にはねじ曲げる方。'),
('JPN', '撒母耳记下', 10, 22, 28, '苦しむ民を、あなたは救われますが、御目を高ぶる者に向け、これを低くされます。'),
('JPN', '撒母耳记下', 10, 22, 29, '主よ、まことにあなたは私のともしび。主は私の闇を照らされます。'),
('JPN', '撒母耳记下', 10, 22, 30, 'あなたによって、私は防塞を突き破り、私の神によって、城壁を跳び越えます。'),
('JPN', '撒母耳记下', 10, 22, 31, '神、その道は完全。主のことばは純粋。主は、すべて主に身を避ける者の盾。'),
('JPN', '撒母耳记下', 10, 22, 32, '主のほかに、だれが神でしょうか。私たちの神のほかに、だれが岩でしょうか。'),
('JPN', '撒母耳记下', 10, 22, 33, '神は私の力強い砦。私の道を全きものとされます。'),
('JPN', '撒母耳记下', 10, 22, 34, '主は、私の足を雌鹿のようにし、高い所に立たせてくださいます。'),
('JPN', '撒母耳记下', 10, 22, 35, '戦いのために私の手を鍛え、腕が青銅の弓も引けるようにされます。'),
('JPN', '撒母耳记下', 10, 22, 36, 'あなたは御救いの盾を私に下さいます。あなたの謙遜は私を大きくします。'),
('JPN', '撒母耳记下', 10, 22, 37, 'あなたは私の歩みを広げられ、私のくるぶしはゆるみません。'),
('JPN', '撒母耳记下', 10, 22, 38, '私は、敵を追ってこれを根絶やしにし、絶ち滅ぼすまでは引き返しませんでした。'),
('JPN', '撒母耳记下', 10, 22, 39, '私が彼らを絶ち滅ぼし、打ち砕いたので、彼らは立てず、私の足もとに倒れました。'),
('JPN', '撒母耳记下', 10, 22, 40, 'あなたは、戦いのために私に力を帯びさせ、向かい立つ者を、私のもとにひれ伏させました。'),
('JPN', '撒母耳记下', 10, 22, 41, 'あなたは、敵が、私を憎む者どもが私に背を見せるようにされました。私は彼らを滅ぼしました。'),
('JPN', '撒母耳记下', 10, 22, 42, '彼らが主に目を留めても、救う者はなく、答えもありませんでした。'),
('JPN', '撒母耳记下', 10, 22, 43, '地のちりのように、私は彼らを打ち砕き、道の泥のように、粉々に砕いて踏みつけました。'),
('JPN', '撒母耳记下', 10, 22, 44, 'あなたは、民の争いから私を助け出し、国々のかしらとして保たれました。私の知らなかった民が私に仕えます。'),
('JPN', '撒母耳记下', 10, 22, 45, '異国の人々は私にへつらい、耳で聞くとすぐ、私に聞き従います。'),
('JPN', '撒母耳记下', 10, 22, 46, '異国の人々は打ちしおれ、砦から震えて出て来ます。'),
('JPN', '撒母耳记下', 10, 22, 47, '主は生きておられる。ほむべきかな、わが岩。あがむべきかな、わが救いの岩なる神。'),
('JPN', '撒母耳记下', 10, 22, 48, 'この神は私のために、復讐する方。諸国の民を私のもとに下らせる方。'),
('JPN', '撒母耳记下', 10, 22, 49, '神は、敵から私を携え出される方。あなたは、向かい立つ者から私を引き上げ、不法を行う者から私を救い出してくださいます。'),
('JPN', '撒母耳记下', 10, 22, 50, 'それゆえ、主よ、私は国々の間であなたをほめたたえます。あなたの御名をほめ歌います。'),
('JPN', '撒母耳记下', 10, 22, 51, '主は、ご自分の王に救いを増し加え、主に油注がれた者ダビデとその裔に、とこしえに恵みを施されます。」'),
('JPN', '撒母耳记下', 10, 23, 1, 'これはダビデの最後のことばである。エッサイの子ダビデの告げたことば。いと高き方によって上げられた者、ヤコブの神に油注がれた者の告げたことば。イスラエルの歌の歌い手。'),
('JPN', '撒母耳记下', 10, 23, 2, '「主の霊は私を通して語り、そのことばは私の舌の上にある。'),
('JPN', '撒母耳记下', 10, 23, 3, 'イスラエルの神は仰せられた。イスラエルの岩は私に語られた。『義をもって人を治める者、神を恐れて治める者。'),
('JPN', '撒母耳记下', 10, 23, 4, 'その者は、太陽が昇る朝の光、雲一つない朝の光のようだ。雨の後に、地の若草を照らす光のようだ。』'),
('JPN', '撒母耳记下', 10, 23, 5, 'まことに私の家は、このように神とともにある。神が永遠の契約を私と立てられたからだ。それは、すべてのことにおいて備えられ、また守られる。神は、私の救いと願いを、すべて育んでくださるではないか。'),
('JPN', '撒母耳记下', 10, 23, 6, 'よこしまな者たちはみな、根こそぎにされた茨のようだ。それらは手に取ることができない。'),
('JPN', '撒母耳记下', 10, 23, 7, '彼らを打つ者はだれも、槍の刃や柄で武装する。彼らはその場で、火で焼き尽くされる。」'),
('JPN', '撒母耳记下', 10, 23, 8, 'ダビデの勇士たちの名は次のとおりである。補佐官のかしら、タハクモニ人ヨシェブ・バシェベテ。彼は槍を振るって一度に八百人を刺し殺した。'),
('JPN', '撒母耳记下', 10, 23, 9, '彼の次は、アホアハ人ドドの子エルアザル。ダビデにつく三勇士の一人であった。彼らがペリシテ人をそしったとき、ペリシテ人は戦うためにそこに集まった。イスラエル人は退いたが、'),
('JPN', '撒母耳记下', 10, 23, 10, '彼は立ち上がり、自分の手が疲れて、手が剣にくっつくまでにペリシテ人を討った。主はその日、大勝利をもたらされた。兵たちが彼のところに引き返して来たのは、ただ、はぎ取るためであった。'),
('JPN', '撒母耳记下', 10, 23, 11, '彼の次はアラル人アゲの子シャンマ。ペリシテ人が隊をなして集まったとき、そこにはレンズ豆が豊かに実った一つの畑があった。兵はペリシテ人の前から逃げたが、'),
('JPN', '撒母耳记下', 10, 23, 12, '彼はその畑の真ん中に踏みとどまってこれを守り、ペリシテ人を討った。主は大勝利をもたらされた。'),
('JPN', '撒母耳记下', 10, 23, 13, '三十人のかしらのうちのこの三人は、刈り入れのころ、アドラムの洞穴にいるダビデのところに下って来た。ペリシテ人の一隊は、レファイムの谷間に陣を敷いていた。'),
('JPN', '撒母耳记下', 10, 23, 14, 'そのときダビデは要害にいて、ペリシテ人の先陣はそのときベツレヘムにいた。'),
('JPN', '撒母耳记下', 10, 23, 15, 'ダビデは切に望んで、「だれかが私に、ベツレヘムの門にある井戸の水を飲ませてくれたらよいのだが」と言った。'),
('JPN', '撒母耳记下', 10, 23, 16, '三人の勇士はペリシテ人の陣営を突き破って、ベツレヘムの門にある井戸から水を汲み、それを携えてダビデのところに持って来た。しかしダビデはそれを飲もうとはせず、それを主の前に注いで、'),
('JPN', '撒母耳记下', 10, 23, 17, 'こう言った。「主よ。そんなことをするなど、私には絶対にできません。これは、いのちをかけて行って来た人たちの血ではありませんか。」彼はそれを飲もうとはしなかった。三勇士は、そのようなことまでしたのである。'),
('JPN', '撒母耳记下', 10, 23, 18, 'さて、ツェルヤの子ヨアブの兄弟アビシャイは三十人のかしらであった。彼は槍を振るって三百人を刺し殺し、あの三人とともに名をあげた。'),
('JPN', '撒母耳记下', 10, 23, 19, '彼は三十人の中で最も誉れが高かったので、彼らの長になったが、あの三人には及ばなかった。'),
('JPN', '撒母耳记下', 10, 23, 20, 'エホヤダの子ベナヤは、カブツェエル出身で、多くの手柄を立てた力ある人であった。彼はモアブの英雄二人を打ち殺した。また、ある雪の日に、洞穴の中に降りて行って雄獅子を打ち殺した。'),
('JPN', '撒母耳记下', 10, 23, 21, '彼はまた、例の堂々としたエジプト人を打ち殺した。このエジプト人は、手に槍を持っていた。ベナヤは杖を持ってその男のところに下って行き、エジプト人の手から槍をもぎ取って、その槍で彼を殺した。'),
('JPN', '撒母耳记下', 10, 23, 22, 'エホヤダの子ベナヤはこれらのことをして、三勇士とともに名をあげた。'),
('JPN', '撒母耳记下', 10, 23, 23, '彼はあの三十人の中でも最も誉れが高かったが、あの三人には及ばなかった。ダビデは彼を自分の護衛長にした。'),
('JPN', '撒母耳记下', 10, 23, 24, 'ヨアブの兄弟アサエルは、例の三十人とともにいた。ベツレヘム出身のドドの子エルハナン。'),
('JPN', '撒母耳记下', 10, 23, 25, 'ハロデ人シャンマ。ハロデ人エリカ。'),
('JPN', '撒母耳记下', 10, 23, 26, 'ペレテ人ヘレツ。テコア人イケシュの子イラ。'),
('JPN', '撒母耳记下', 10, 23, 27, 'アナトテ人アビエゼル。フシャ人メブナイ。'),
('JPN', '撒母耳记下', 10, 23, 28, 'アホアハ人ツァルモン。ネトファ人マフライ。'),
('JPN', '撒母耳记下', 10, 23, 29, 'ネトファ人バアナの子ヘレブ。ベニヤミンのギブア出身のリバイの子イタイ。'),
('JPN', '撒母耳记下', 10, 23, 30, 'ピルアトン人ベナヤ。ガアシュの谷の出であるヒダイ。'),
('JPN', '撒母耳记下', 10, 23, 31, 'アルバト人アビ・アルボン。バルフム人アズマウェテ。'),
('JPN', '撒母耳记下', 10, 23, 32, 'シャアルビム人エルヤフバとヨナタン、ヤシェンの子たち。'),
('JPN', '撒母耳记下', 10, 23, 33, 'ハラル人シャンマ。アラル人シャラルの子アヒアム。'),
('JPN', '撒母耳记下', 10, 23, 34, 'マアカ人アハスバイの子エリフェレテ。ギロ人アヒトフェルの子エリアム。'),
('JPN', '撒母耳记下', 10, 23, 35, 'カルメル人ヘツライ。アラブ人パアライ。'),
('JPN', '撒母耳记下', 10, 23, 36, 'ツォバ出身のナタンの子イグアル。ガド人バニ。'),
('JPN', '撒母耳记下', 10, 23, 37, 'アンモン人ツェレク。ツェルヤの子ヨアブの道具持ち、ベエロテ人ナフライ。'),
('JPN', '撒母耳记下', 10, 23, 38, 'エテル人イラ。エテル人ガレブ。'),
('JPN', '撒母耳记下', 10, 23, 39, 'ヒッタイト人ウリヤ。合計三十七人。'),
('JPN', '撒母耳记下', 10, 24, 1, 'さて、再び主の怒りがイスラエルに対して燃え上がり、ダビデをそそのかして、彼らに向かわせた。「さあ、イスラエルとユダの人口を数えよ」と。'),
('JPN', '撒母耳记下', 10, 24, 2, '王はともにいた軍の長ヨアブに言った。「さあ、ダンからベエル・シェバに至るまでのイスラエルの全部族の間を行き巡り、民を登録し、私に民の数を知らせよ。」'),
('JPN', '撒母耳记下', 10, 24, 3, 'ヨアブは王に言った。「あなたの神、主が、この民を百倍にも増やしてくださいますように。わが主、王の目が、親しくこれをご覧になりますように。ところで、わが主、王は、なぜこのようなことを望まれるのですか。」'),
('JPN', '撒母耳记下', 10, 24, 4, 'しかし、ヨアブと軍の高官たちへの王のことばは激しかった。ヨアブと軍の高官たちは、イスラエルの民を登録するために王の前から出て行った。'),
('JPN', '撒母耳记下', 10, 24, 5, '彼らはヨルダン川を渡って、ガドの谷の真ん中にある町、ヤゼルに向かって右側にあるアロエルに宿営し、'),
('JPN', '撒母耳记下', 10, 24, 6, 'ギルアデとタフティム・ホデシの地に行き、さらにダン・ヤアンに行き、シドンに回った。'),
('JPN', '撒母耳记下', 10, 24, 7, 'そしてツロの要塞に行き、ヒビ人やカナン人のすべての町に行き、ユダのネゲブへ出て行って、ベエル・シェバに至った。'),
('JPN', '撒母耳记下', 10, 24, 8, '彼らは全土を行き巡り、九か月と二十日の後にエルサレムに帰って来た。'),
('JPN', '撒母耳记下', 10, 24, 9, 'ヨアブは兵の登録人数を王に報告した。イスラエルには剣を使う兵士が八十万人おり、ユダの兵士は五十万人であった。'),
('JPN', '撒母耳记下', 10, 24, 10, 'ダビデは、民を数えた後で、良心のとがめを感じた。ダビデは主に言った。「私は、このようなことをして、大きな罪を犯しました。主よ、今、このしもべの咎を取り去ってください。私は本当に愚かなことをしました。」'),
('JPN', '撒母耳记下', 10, 24, 11, '朝ダビデが起きると、主のことばがダビデの先見者である預言者ガドにあった。'),
('JPN', '撒母耳记下', 10, 24, 12, '「行ってダビデに告げよ。『主はこう言われる。わたしはあなたに三つのことを負わせる。そのうちの一つを選べ。わたしはあなたに対してそれを行う。』」'),
('JPN', '撒母耳记下', 10, 24, 13, 'ガドはダビデのもとに行き、彼に告げた。「七年間の飢饉が、あなたの国に来るのがよいか。三か月間、あなたが敵の前を逃げ、敵があなたを追うのがよいか。三日間、あなたの国に疫病があるのがよいか。今、よく考えて、私を遣わされた方に何と答えたらよいかを決めなさい。」'),
('JPN', '撒母耳记下', 10, 24, 14, 'ダビデはガドに言った。「それは私には非常に辛いことです。主の手に陥らせてください。主のあわれみは深いからです。私が人の手には陥らないようにしてください。」'),
('JPN', '撒母耳记下', 10, 24, 15, '主は、その朝から定められた時まで、イスラエルに疫病を下された。ダンからベエル・シェバに至るまで、民のうち七万人が死んだ。'),
('JPN', '撒母耳记下', 10, 24, 16, '御使いは、エルサレムを滅ぼそうと手を伸ばした。主はわざわいを下すことを思い直し、民を滅ぼす御使いに言われた。「もう十分だ。手を引け。」主の使いは、エブス人アラウナの打ち場の傍らにいた。'),
('JPN', '撒母耳记下', 10, 24, 17, 'ダビデは、民を打っている御使いを見たとき、主に言った。「ご覧ください。この私に罪があるのです。私が悪いことをしたのです。この羊の群れがいったい何をしたでしょうか。どうか、あなたの御手が、私と私の父の家に下りますように。」'),
('JPN', '撒母耳记下', 10, 24, 18, 'その日、ガドはダビデのところに来て、彼に言った。「上って行って、エブス人アラウナの打ち場に、主のために祭壇を築きなさい。」'),
('JPN', '撒母耳记下', 10, 24, 19, 'ダビデは、ガドのことばにしたがって、主が命じられたとおりに上って行った。'),
('JPN', '撒母耳记下', 10, 24, 20, 'アラウナが見下ろすと、王とその家来たちが自分の方に進んで来るのが見えた。アラウナは出て行き、地にひれ伏して、王に礼をした。'),
('JPN', '撒母耳记下', 10, 24, 21, 'アラウナは言った。「なぜ、わが主、王は、しもべのところにおいでになったのですか。」ダビデは言った。「あなたの打ち場を買って、主のために祭壇を築きたい。そうすれば民への主の罰は終わるだろう。」'),
('JPN', '撒母耳记下', 10, 24, 22, 'アラウナはダビデに言った。「わが主、王よ。お気に召す物を取って、お献げください。ご覧ください。ここに全焼のささげ物のための牛がいます。薪にできる打穀機や牛の用具もあります。'),
('JPN', '撒母耳记下', 10, 24, 23, '王よ、このアラウナはすべてを王に差し上げます。」アラウナはさらに王に言った。「あなたの神、主が、あなたを受け入れてくださいますように。」'),
('JPN', '撒母耳记下', 10, 24, 24, 'しかし王はアラウナに言った。「いや、私は代金を払って、あなたから買いたい。費用もかけずに、私の神、主に全焼のささげ物を献げたくはない。」そしてダビデは、打ち場と牛を銀五十シェケルで買った。'),
('JPN', '撒母耳记下', 10, 24, 25, 'ダビデは、そこに主のために祭壇を築き、全焼のささげ物と交わりのいけにえを献げた。主が、この国のための祈りに心を動かされたので、イスラエルへの主の罰は終わった。'),
('JPN', '列王纪上', 11, 1, 1, 'ダビデ王は年を重ねて老人になっていた。そのため衣をいくら着せても温まらなかった。'),
('JPN', '列王纪上', 11, 1, 2, '家来たちは王に言った。「王のために一人の若い処女を探し、御前に仕えて世話をするようにし、王の懐に寝させて王が温まるようにいたしましょう。」'),
('JPN', '列王纪上', 11, 1, 3, 'こうして彼らは、イスラエルの国中に美しい娘を探し求め、シュネム人の女アビシャグを見つけて、王のもとに連れて来た。'),
('JPN', '列王纪上', 11, 1, 4, 'この娘は非常に美しかった。彼女は王の世話をするようになり、彼に仕えたが、王は彼女を知ることがなかった。'),
('JPN', '列王纪上', 11, 1, 5, 'ときに、ハギテの子アドニヤは、「私が王になる」と言って野心を抱き、戦車、騎兵、それに自分の前に走る者五十人を手に入れた。'),
('JPN', '列王纪上', 11, 1, 6, '彼の父は、「おまえは、どうしてこんなことをしたのか」と言って、彼のことで心を痛めたことは一度もなかった。そのうえ、彼は非常に体格も良く、アブサロムの次に生まれた子であった。'),
('JPN', '列王纪上', 11, 1, 7, '彼がツェルヤの子ヨアブと祭司エブヤタルに相談をしたので、彼らはアドニヤを支持するようになった。'),
('JPN', '列王纪上', 11, 1, 8, 'しかし、祭司ツァドクとエホヤダの子ベナヤと預言者ナタン、それにシムイとレイ、およびダビデの勇士たちは、アドニヤにくみしなかった。'),
('JPN', '列王纪上', 11, 1, 9, 'アドニヤは、エン・ロゲルの近くにあるゾヘレテの石のそばで、羊、牛、肥えた家畜をいけにえとして献げ、王の息子たちである自分のすべての兄弟たちと、王の家来であるユダのすべての人々を招いた。'),
('JPN', '列王纪上', 11, 1, 10, 'しかし、預言者ナタン、ベナヤ、勇士たち、そして自分の兄弟ソロモンは招かなかった。'),
('JPN', '列王纪上', 11, 1, 11, 'そこで、ナタンはソロモンの母バテ・シェバにこう言った。「われらの君ダビデが知らないうちに、ハギテの子アドニヤが王になったことを、あなたは聞いていないのですか。'),
('JPN', '列王纪上', 11, 1, 12, 'さあ今、あなたに助言をしますから、自分のいのちと、自分の子ソロモンのいのちを救いなさい。'),
('JPN', '列王纪上', 11, 1, 13, 'すぐにダビデ王のもとに行って、『王様。あなたは、このはしために、「必ずあなたの子ソロモンが私の跡を継いで王となる。彼が私の王座に就く」と誓われたではありませんか。それなのに、なぜアドニヤが王となったのですか』と言いなさい。'),
('JPN', '列王纪上', 11, 1, 14, 'あなたがまだそこで王と話している間に、私もあなたの後から入って行って、あなたのことばが確かであることを保証しましょう。」'),
('JPN', '列王纪上', 11, 1, 15, 'バテ・シェバは寝室の王のもとに行った。王は非常に年老いていて、シュネム人の女アビシャグが王に仕えていた。'),
('JPN', '列王纪上', 11, 1, 16, 'バテ・シェバがひざまずいて、王に礼をすると、王は「何の用か」と言った。'),
('JPN', '列王纪上', 11, 1, 17, '彼女は答えた。「わが君。あなたは、あなたの神、主にかけて、『必ずあなたの子ソロモンが私の跡を継いで王となる。彼が私の王座に就く』と、このはしためにお誓いになりました。'),
('JPN', '列王纪上', 11, 1, 18, 'それなのに今、ご覧ください、アドニヤが王となっています。王様、あなたはそれをご存じではないのです。'),
('JPN', '列王纪上', 11, 1, 19, '彼は、雄牛や肥えた家畜や羊をたくさん、いけにえとして献げ、王のすべてのお子様と、祭司エブヤタル、それに軍の長ヨアブを招いたのに、あなたのしもべソロモンは招きませんでした。'),
('JPN', '列王纪上', 11, 1, 20, '王様。王様の跡を継いで王座に就くのはだれと告げられるのかと、今や、全イスラエルの目はあなたの上に注がれています。'),
('JPN', '列王纪上', 11, 1, 21, 'このままですと、王様がご先祖とともに眠りにつかれるとき、私と私の子ソロモンは罪ある者と見なされるでしょう。」'),
('JPN', '列王纪上', 11, 1, 22, '彼女がまだ王と話しているうちに、預言者ナタンが入って来た。'),
('JPN', '列王纪上', 11, 1, 23, '家来たちは、「預言者ナタンが参りました」と言って王に告げた。彼は王の前に出て、地にひれ伏し、王に礼をした。'),
('JPN', '列王纪上', 11, 1, 24, 'ナタンは言った。「王よ。あなたは『アドニヤが私の跡を継いで王となる。彼が私の王座に就く』とおっしゃったのでしょうか。'),
('JPN', '列王纪上', 11, 1, 25, '実は今日、彼は下って行って、雄牛や肥えた家畜や羊をたくさん、いけにえとして献げ、王のお子様すべてと、軍の長たち、そして祭司エブヤタルを招きました。彼らは彼の前で食べたり飲んだりしながら、『アドニヤ王、万歳』と叫びました。'),
('JPN', '列王纪上', 11, 1, 26, 'しかしあなたのしもべのこの私や、祭司ツァドク、エホヤダの子ベナヤ、それに、あなたのしもべソロモンは招きませんでした。'),
('JPN', '列王纪上', 11, 1, 27, 'このことは、王から出たことなのですか。あなたは、だれが王の跡を継いで王座に就くのかを、このしもべに告げておられません。」'),
('JPN', '列王纪上', 11, 1, 28, 'ダビデ王は答えた。「バテ・シェバをここに。」彼女が王の前に来て、王の前に立つと、'),
('JPN', '列王纪上', 11, 1, 29, '王は誓って言った。「主は生きておられる。主は私のたましいをあらゆる苦難から贖い出してくださった。'),
('JPN', '列王纪上', 11, 1, 30, '私がイスラエルの神、主にかけて、『必ずあなたの子ソロモンが私の跡を継いで王となる。彼が私に代わって王座に就く』とあなたに誓ったとおり、今日、必ずそのとおりにしよう。」'),
('JPN', '列王纪上', 11, 1, 31, 'バテ・シェバは地にひれ伏して王に礼をし、そして言った。「わが君、ダビデ王様。いつまでも生きられますように。」'),
('JPN', '列王纪上', 11, 1, 32, 'それからダビデ王は「祭司ツァドクと預言者ナタン、それにエホヤダの子ベナヤをここに呼べ」と言った。彼らが王の前に来ると、'),
('JPN', '列王纪上', 11, 1, 33, '王は彼らに言った。「おまえたちの主君の家来たちを連れて、私の子ソロモンを私の雌ろばに乗せ、彼を連れてギホンへ下れ。'),
('JPN', '列王纪上', 11, 1, 34, '祭司ツァドクと預言者ナタンは、そこで彼に油を注いでイスラエルの王とせよ。そうして、角笛を吹き鳴らし、『ソロモン王、万歳』と叫べ。'),
('JPN', '列王纪上', 11, 1, 35, 'それから彼の後に従って上れ。彼は来て、私の王座に就き、私に代わって王となる。私は彼をイスラエルとユダの君主に任命する。」'),
('JPN', '列王纪上', 11, 1, 36, 'エホヤダの子ベナヤが王に答えて言った。「アーメン。王の神、主も、そう言われますように。'),
('JPN', '列王纪上', 11, 1, 37, '主が王とともにおられたように、ソロモンとともにいて、その王座を、わが君ダビデ王の王座よりもすぐれたものとされますように。」'),
('JPN', '列王纪上', 11, 1, 38, 'そこで、祭司ツァドク、預言者ナタン、エホヤダの子ベナヤ、それにクレタ人とペレテ人が下って行き、ソロモンをダビデ王の雌ろばに乗せ、彼を連れてギホンへ行った。'),
('JPN', '列王纪上', 11, 1, 39, '祭司ツァドクは天幕の中から油の角を取って来て、ソロモンに油を注いだ。彼らが角笛を吹き鳴らすと、民はみな、「ソロモン王、万歳」と言った。'),
('JPN', '列王纪上', 11, 1, 40, '民はみな、彼の後に従って上って来た。民が笛を吹き鳴らしながら、大いに喜んで歌ったので、地がその声で裂けた。'),
('JPN', '列王纪上', 11, 1, 41, 'アドニヤと、彼とともにいた客はみな、食事を終えたとき、これを聞いた。ヨアブは角笛の音を聞いて言った。「なぜ、都で騒々しい音がするのか。」'),
('JPN', '列王纪上', 11, 1, 42, '彼がまだそう言っているうちに、祭司エブヤタルの子ヨナタンがやって来た。アドニヤは言った。「入れ。おまえは勇敢な男だから、良い知らせを持って来たのだろう。」'),
('JPN', '列王纪上', 11, 1, 43, 'ヨナタンはアドニヤに答えた。「いいえ、われらの君、ダビデ王はソロモンを王とされました。'),
('JPN', '列王纪上', 11, 1, 44, 'ダビデ王は、祭司ツァドク、預言者ナタン、エホヤダの子ベナヤ、それに、クレタ人とペレテ人をソロモンにつけて送り出されました。彼らはソロモンを王の雌ろばに乗せ、'),
('JPN', '列王纪上', 11, 1, 45, '祭司ツァドクと預言者ナタンが、ギホンで彼に油を注いで王としました。こうして彼らが喜びながら、そこから上って来たので、都が騒々しくなったのです。あなたがたが聞いたあの物音がそれです。'),
('JPN', '列王纪上', 11, 1, 46, 'しかも、ソロモンはすでに王の座に就きました。'),
('JPN', '列王纪上', 11, 1, 47, 'そのうえ、王の家来たちが来て、『神がソロモンの名をあなたの名よりもすぐれたものとし、その王座をあなたの王座よりも大いなるものとされますように』と、われらの君、ダビデ王に祝福のことばを述べました。すると、王は寝台の上でひれ伏されました。'),
('JPN', '列王纪上', 11, 1, 48, 'また、王はこう言われました。『イスラエルの神、主がほめたたえられるように。主は今日、私の王座に就く者を与え、私がこの目で見るようにしてくださった。』」'),
('JPN', '列王纪上', 11, 1, 49, 'アドニヤの客たちはみな身震いして立ち上がり、それぞれ帰途についた。'),
('JPN', '列王纪上', 11, 1, 50, 'アドニヤもソロモンを恐れて立ち上がり、行って祭壇の角をつかんだ。'),
('JPN', '列王纪上', 11, 1, 51, 'そのとき、ソロモンに次のような知らせがあった。「アドニヤはソロモン王を恐れ、祭壇の角をしっかり握って、『ソロモン王がまず、このしもべを剣で殺さないと私に誓ってくださるように』と言っています。」'),
('JPN', '列王纪上', 11, 1, 52, 'すると、ソロモンは言った。「彼が立派な人物であれば、その髪の毛一本も地に落ちることはない。しかし、彼のうちに悪が見つかれば、彼は死ななければならない。」'),
('JPN', '列王纪上', 11, 1, 53, 'それから、ソロモン王は人を遣わして、アドニヤを祭壇から降ろさせた。アドニヤが来てソロモン王に礼をすると、ソロモンは彼に言った。「家に帰りなさい。」'),
('JPN', '列王纪上', 11, 2, 1, 'ダビデの死ぬ日が近づいたとき、彼は息子のソロモンに次のように命じた。'),
('JPN', '列王纪上', 11, 2, 2, '「私は世のすべての人が行く道を行こうとしている。あなたは強く、男らしくありなさい。'),
('JPN', '列王纪上', 11, 2, 3, 'あなたの神、主への務めを守り、モーセの律法の書に書かれているとおりに、主の掟と命令と定めとさとしを守って主の道に歩みなさい。あなたが何をしても、どこへ向かっても、栄えるためだ。'),
('JPN', '列王纪上', 11, 2, 4, 'そうすれば、主は私についてお告げになった約束を果たしてくださるだろう。すなわち『もし、あなたの息子たちが彼らの道を守り、心を尽くし、いのちを尽くして、誠実にわたしの前に歩むなら、あなたには、イスラエルの王座から人が断たれることはない』。'),
('JPN', '列王纪上', 11, 2, 5, 'また、あなたはツェルヤの子ヨアブが私にしたこと、すなわち、彼がイスラエルの二人の軍の長、ネルの子アブネルとエテルの子アマサにしたことを知っている。ヨアブは彼らを虐殺し、平和なときに戦いの血を流し、自分の腰の帯と足のくつに戦いの血をつけたのだ。'),
('JPN', '列王纪上', 11, 2, 6, 'だから、あなたは自分の知恵にしたがって行動しなさい。彼の白髪頭を安らかによみに下らせてはならない。'),
('JPN', '列王纪上', 11, 2, 7, 'しかし、ギルアデ人バルジライの子たちには恵みを施してやり、彼らをあなたの食卓に連ならせなさい。彼らは、私があなたの兄弟アブサロムの前から逃げたとき、私の近くに来てくれたのだから。'),
('JPN', '列王纪上', 11, 2, 8, 'また、あなたのそばに、バフリム出身のベニヤミン人ゲラの子シムイがいる。彼は、私がマハナイムに行ったとき、非常に激しく私を呪った。だが、彼は私を迎えにヨルダン川に下って来たので、私は主にかけて、『おまえを剣で殺すことはない』と彼に誓った。'),
('JPN', '列王纪上', 11, 2, 9, 'しかし今は、彼を咎のない者としてはならない。あなたは知恵の人だから、どうすれば彼の白髪頭を血に染めてよみに下らせられるかが分かるだろう。」'),
('JPN', '列王纪上', 11, 2, 10, 'こうして、ダビデは先祖とともに眠りにつき、ダビデの町に葬られた。'),
('JPN', '列王纪上', 11, 2, 11, 'ダビデがイスラエルの王であった期間は四十年であった。ヘブロンで七年治め、エルサレムで三十三年治めた。'),
('JPN', '列王纪上', 11, 2, 12, 'ソロモンは父ダビデの王座に就き、その王位は確立した。'),
('JPN', '列王纪上', 11, 2, 13, 'あるとき、ハギテの子アドニヤがソロモンの母バテ・シェバのところにやって来た。バテ・シェバは「平和なことで来たのですか」と尋ねた。彼は「平和なことです」と答えて、'),
('JPN', '列王纪上', 11, 2, 14, 'さらに言った。「お話ししたいことがあるのですが。」すると彼女は言った。「話してごらんなさい。」'),
('JPN', '列王纪上', 11, 2, 15, '彼は言った。「ご存じのように、王位は私のものでしたし、イスラエルはみな私が王になるのを期待していました。それなのに、王位は転じて、私の弟のものとなりました。主によって彼のものとなったからです。'),
('JPN', '列王纪上', 11, 2, 16, '今、あなたに一つのお願いがあります。断らないでください。」バテ・シェバは彼に言った。「話してごらんなさい。」'),
('JPN', '列王纪上', 11, 2, 17, '彼は言った。「どうかソロモン王に頼んでください。あなたからなら断らないでしょうから。王がシュネム人の女アビシャグを、私に妻として与えてくださるように。」'),
('JPN', '列王纪上', 11, 2, 18, 'そこで、バテ・シェバは「いいでしょう。私から王にあなたのことを話します」と言った。'),
('JPN', '列王纪上', 11, 2, 19, 'バテ・シェバは、アドニヤのことを話すために、ソロモン王のところに行った。王は立ち上がって彼女を迎え、彼女に礼をして、自分の王座に座った。王の母のために席が設けられ、彼女は王の右に座った。'),
('JPN', '列王纪上', 11, 2, 20, '彼女は言った。「あなたに一つの小さなお願いがあります。断らないでください。」王は彼女に言った。「母上、その願い事を聞かせてください。断ることはしませんから。」'),
('JPN', '列王纪上', 11, 2, 21, '彼女は言った。「シュネム人の女アビシャグを、あなたの兄アドニヤに妻として与えてやってください。」'),
('JPN', '列王纪上', 11, 2, 22, 'ソロモン王は母に答えた。「なぜ、アドニヤのためにシュネム人の女アビシャグを願うのですか。彼は私の兄ですから、彼のためには王位を願ったほうがよいのではありませんか。彼のためにも、祭司エブヤタルやツェルヤの子ヨアブのためにも。」'),
('JPN', '列王纪上', 11, 2, 23, 'ソロモン王は主にかけて次のように誓った。「アドニヤがこういうことを言ってもなお自分のいのちを失わなかったなら、神がこの私を幾重にも罰せられるように。'),
('JPN', '列王纪上', 11, 2, 24, '主は生きておられる。主は私を父ダビデの王座に就かせて、私を堅く立て、約束どおり私のために家を建ててくださった。アドニヤは今日殺されなければならない。」'),
('JPN', '列王纪上', 11, 2, 25, 'こうしてソロモン王は、エホヤダの子ベナヤを遣わしてアドニヤを討ち取らせたので、彼は死んだ。'),
('JPN', '列王纪上', 11, 2, 26, 'それから、王は祭司エブヤタルに言った。「アナトテの自分の地所に帰れ。おまえは死に値する者だが、今日はおまえを殺さない。おまえは私の父ダビデの前で神である主の箱を担ぎ、父といつも苦しみをともにしたからだ。」'),
('JPN', '列王纪上', 11, 2, 27, 'こうして、ソロモンはエブヤタルを主の祭司の職から追放した。シロでエリの家族について語られた主のことばは、こうして成就した。'),
('JPN', '列王纪上', 11, 2, 28, 'この知らせがヨアブのところに伝わった。ヨアブはアブサロムにはつかなかったが、アドニヤについていたのである。ヨアブは主の天幕に逃げ、祭壇の角をつかんだ。'),
('JPN', '列王纪上', 11, 2, 29, 'ソロモン王に「ヨアブが主の天幕に逃げて、今、祭壇の傍らにいる」という知らせがあった。するとソロモンは、「行って彼を討ち取れ」と命じて、エホヤダの子ベナヤを遣わした。'),
('JPN', '列王纪上', 11, 2, 30, 'ベナヤは主の天幕に入って、彼に言った。「王がこう言われる。『外に出よ。』」彼は「いや、ここで死ぬ」と言った。ベナヤは王にこのことを報告した。「ヨアブはこう私に答えました。」'),
('JPN', '列王纪上', 11, 2, 31, '王は彼に言った。「彼が言ったとおりにせよ。彼を討ち取って葬れ。こうして、ヨアブが理由もなく流した血の責任を、私と、私の父の家から取り除け。'),
('JPN', '列王纪上', 11, 2, 32, '主は、彼が流した血を彼の頭に注ぎ返される。彼は自分よりも正しく善良な二人の者に討ちかかり、剣で虐殺したからだ。彼は私の父ダビデが知らないうちに、イスラエルの軍の長である、ネルの子アブネルと、ユダの軍の長である、エテルの子アマサを虐殺したのだ。'),
('JPN', '列王纪上', 11, 2, 33, '二人の血は永遠にヨアブの頭と彼の子孫の頭に注ぎ返され、ダビデとその子孫、および、その家と王座には、とこしえまでも主から平安があるように。」'),
('JPN', '列王纪上', 11, 2, 34, 'エホヤダの子ベナヤは上って行き、彼を打って殺した。ヨアブは荒野にある自分の家に葬られた。'),
('JPN', '列王纪上', 11, 2, 35, '王はエホヤダの子ベナヤを彼の代わりに軍団長とした。また、王は祭司ツァドクをエブヤタルの代わりとした。'),
('JPN', '列王纪上', 11, 2, 36, '王は人を遣わしてシムイを呼び寄せ、彼に言った。「エルサレムに自分の家を建て、そこに住むがよい。だが、そこからどこへも出てはならない。'),
('JPN', '列王纪上', 11, 2, 37, '出て行ってキデロンの谷を渡った日には、おまえは必ず死ななければならないと覚悟しておけ。おまえの血の責任はおまえ自身の頭上に降りかかるのだ。」'),
('JPN', '列王纪上', 11, 2, 38, 'シムイは王に言った。「よろしゅうございます。しもべは王様のおっしゃるとおりにいたします。」このようにしてシムイは、何日もの間エルサレムに住んだ。'),
('JPN', '列王纪上', 11, 2, 39, 'それから三年たったころ、シムイの二人の奴隷が、ガテの王マアカの子アキシュのところへ逃げた。シムイに「あなたの奴隷たちが今、ガテにいる」という知らせがあったので、'),
('JPN', '列王纪上', 11, 2, 40, 'シムイはすぐ、ろばに鞍を置き、奴隷たちを捜しにガテのアキシュのところへ行った。シムイは行って、奴隷たちをガテから連れ戻した。'),
('JPN', '列王纪上', 11, 2, 41, 'シムイがエルサレムからガテに行って帰って来たことが、ソロモンに知らされた。'),
('JPN', '列王纪上', 11, 2, 42, 'すると、王は人を遣わし、シムイを呼び出して言った。「私はおまえに、主にかけて誓わせ、『おまえが出て、どこかへ行った日には、おまえは必ず死ななければならないと覚悟しておけ』と警告しておいたではないか。すると、おまえは私に『よろしゅうございます。従います』と言った。'),
('JPN', '列王纪上', 11, 2, 43, 'それなのになぜ、主への誓いと、私がおまえに命じた命令を守らなかったのか。」'),
('JPN', '列王纪上', 11, 2, 44, '王はまたシムイに言った。「おまえは心の中で、自分が私の父ダビデに対して行ったすべての悪をよく知っているはずだ。主はおまえの悪をおまえの頭に返される。'),
('JPN', '列王纪上', 11, 2, 45, 'しかし、ソロモン王は祝福され、ダビデの王座は主の前でとこしえまでも堅く立つ。」'),
('JPN', '列王纪上', 11, 2, 46, '王はエホヤダの子ベナヤに命じた。ベナヤは出て行ってシムイを討ち取り、シムイは死んだ。こうして、王国はソロモンによって確立した。'),
('JPN', '列王纪上', 11, 3, 1, 'ソロモンはエジプトの王ファラオと姻戚の関係を結んだ。彼はファラオの娘をめとり、ダビデの町に連れて来て、自分の家と主の家、およびエルサレムの周りの城壁を築き終えるまで、そこにとどまらせた。'),
('JPN', '列王纪上', 11, 3, 2, '当時はまだ、主の御名のために家が建てられていなかったので、民はただ、高き所でいけにえを献げていた。'),
('JPN', '列王纪上', 11, 3, 3, 'ソロモンは主を愛し、父ダビデの掟に歩んでいた。ただし、彼は高き所でいけにえを献げ、香をたいていた。'),
('JPN', '列王纪上', 11, 3, 4, '王はいけにえを献げようとギブオンへ行った。そこが最も重要な高き所だったからである。ソロモンはそこの祭壇の上で千匹の全焼のささげ物を献げた。'),
('JPN', '列王纪上', 11, 3, 5, 'ギブオンで主は夜の夢のうちにソロモンに現れた。神は仰せられた。「あなたに何を与えようか。願え。」'),
('JPN', '列王纪上', 11, 3, 6, 'ソロモンは言った。「あなたは、あなたのしもべ、私の父ダビデに大いなる恵みを施されました。父があなたに対し真実と正義と真心をもって、あなたの御前に歩んだからです。あなたはこの大いなる恵みを父のために保ち、今日のように、その王座に着いている子を彼にお与えになりました。'),
('JPN', '列王纪上', 11, 3, 7, 'わが神、主よ。今あなたは私の父ダビデに代わって、このしもべを王とされました。しかし私は小さな子どもで、出入りする術を知りません。'),
('JPN', '列王纪上', 11, 3, 8, 'そのうえ、しもべは、あなたが選んだあなたの民の中にいます。あまりにも多くて、数えることも調べることもできないほど大勢の民です。'),
('JPN', '列王纪上', 11, 3, 9, '善悪を判断してあなたの民をさばくために、聞き分ける心をしもべに与えてください。さもなければ、だれに、この大勢のあなたの民をさばくことができるでしょうか。」'),
('JPN', '列王纪上', 11, 3, 10, 'これは主のみこころにかなった。ソロモンがこのことを願ったからである。'),
('JPN', '列王纪上', 11, 3, 11, '神は彼に仰せられた。「あなたがこのことを願い、自分のために長寿を願わず、自分のために富を願わず、あなたの敵のいのちさえ願わず、むしろ、自分のために正しい訴えを聞き分ける判断力を願ったので、'),
('JPN', '列王纪上', 11, 3, 12, '見よ、わたしはあなたが言ったとおりにする。見よ。わたしはあなたに、知恵と判断の心を与える。あなたより前に、あなたのような者はなく、あなたの後に、あなたのような者は起こらない。'),
('JPN', '列王纪上', 11, 3, 13, 'そのうえ、あなたが願わなかったもの、富と誉れもあなたに与える。あなたが生きているかぎり、王たちの中であなたに並ぶ者は一人もいない。'),
('JPN', '列王纪上', 11, 3, 14, 'また、あなたの父ダビデが歩んだように、あなたもわたしの掟と命令を守ってわたしの道に歩むなら、あなたの日々を長くしよう。」'),
('JPN', '列王纪上', 11, 3, 15, 'ソロモンが目を覚ますと、見よ、それは夢であった。彼はエルサレムに行き、主の契約の箱の前に立って、全焼のささげ物を献げ、交わりのいけにえを献げ、すべての家来たちのために祝宴を開いた。'),
('JPN', '列王纪上', 11, 3, 16, 'そのころ、二人の遊女が王のところに来て、その前に立った。'),
('JPN', '列王纪上', 11, 3, 17, 'その一人が言った。「わが君、お願いがございます。実は、私とこの女とは同じ家に住んでいますが、私はこの女と一緒に家にいるとき、子を産みました。'),
('JPN', '列王纪上', 11, 3, 18, '私が子を産んで三日たつと、この女も子を産みました。家には私たちのほか、だれも一緒にいた者はなく、私たち二人だけが家にいました。'),
('JPN', '列王纪上', 11, 3, 19, 'ところが、夜の間に、この女の産んだ子が死にました。この女が自分の子の上に伏したからです。'),
('JPN', '列王纪上', 11, 3, 20, 'この女は夜中に起きて、このはしためが眠っている間に、私のそばから私の子を取って自分の懐に寝かせ、死んだ自分の子を私の懐に寝かせました。'),
('JPN', '列王纪上', 11, 3, 21, '朝、私が子どもに乳を飲ませようとして起きると、どうでしょう、その子は死んでいるではありませんか。朝、その子をよく見てみると、なんとまあ、その子は私が産んだ子ではありませんでした。」'),
('JPN', '列王纪上', 11, 3, 22, 'すると、もう一人の女が言った。「いいえ、生きているのが私の子で、死んでいるのがあなたの子です。」先の女は言った。「いいえ、死んだのがあなたの子で、生きているのが私の子です。」女たちは王の前で言い合った。'),
('JPN', '列王纪上', 11, 3, 23, 'そこで王は言った。「一人は『生きているのが私の子で、死んだのがあなたの子だ』と言い、また、もう一人は『いや、死んだのがあなたの子で、生きているのが私の子だ』と言う。」'),
('JPN', '列王纪上', 11, 3, 24, '王が「剣をここに持って来なさい」と言ったので、剣が王の前に差し出された。'),
('JPN', '列王纪上', 11, 3, 25, '王は言った。「生きている子を二つに切り分け、半分をこちらに、もう半分をそちらに与えよ。」'),
('JPN', '列王纪上', 11, 3, 26, 'すると生きている子の母親は、自分の子を哀れに思って胸が熱くなり、王に申し立てて言った。「わが君、お願いです。どうか、その生きている子をあの女にお与えください。決してその子を殺さないでください。」しかしもう一人の女は、「それを私のものにも、あなたのものにもしないで、断ち切ってください」と言った。'),
('JPN', '列王纪上', 11, 3, 27, 'そこで王は宣告を下して言った。「生きている子を初めのほうの女に与えよ。決してその子を殺してはならない。彼女がその子の母親である。」'),
('JPN', '列王纪上', 11, 3, 28, '全イスラエルは、王が下したさばきを聞いて、王を恐れた。神の知恵が彼のうちにあって、さばきをするのを見たからである。'),
('JPN', '列王纪上', 11, 4, 1, 'こうして、ソロモン王は全イスラエルの王となった。'),
('JPN', '列王纪上', 11, 4, 2, '彼の高官たちは次のとおり。ツァドクの子アザルヤは祭司、'),
('JPN', '列王纪上', 11, 4, 3, 'シシャの子たちのエリホレフとアヒヤは書記、アヒルデの子ヨシャファテは史官、'),
('JPN', '列王纪上', 11, 4, 4, 'エホヤダの子ベナヤは軍団長、ツァドクとエブヤタルは祭司、'),
('JPN', '列王纪上', 11, 4, 5, 'ナタンの子アザルヤは政務長官、ナタンの子ザブデは祭司で王の友、'),
('JPN', '列王纪上', 11, 4, 6, 'アヒシャルは宮廷長官、アブダの子アドニラムは役務長官。'),
('JPN', '列王纪上', 11, 4, 7, 'ソロモンは、イスラエル全土に十二人の守護を置いた。彼らは王とその一族に食糧を納めた。一年に一か月分の食糧を各自が納めることになっていたのである。'),
('JPN', '列王纪上', 11, 4, 8, '彼らの名は次のとおり。エフライムの山地にはフルの子。'),
('JPN', '列王纪上', 11, 4, 9, 'マカツ、シャアルビム、ベテ・シェメシュ、エロン・ベテ・ハナンにはデケルの子。'),
('JPN', '列王纪上', 11, 4, 10, 'アルボテにはヘセデの子。彼はソコと、ヘフェルの全地を任されていた。'),
('JPN', '列王纪上', 11, 4, 11, 'ドルの全高地にはアビナダブの子。ソロモンの娘タファテが彼の妻であった。'),
('JPN', '列王纪上', 11, 4, 12, 'タアナク、メギド、またイズレエルの下ツァレタンのそばのベテ・シェアンの全域、ベテ・シェアンからアベル・メホラ、ヨクメアムの向こうまでの地には、アヒルデの子バアナ。'),
('JPN', '列王纪上', 11, 4, 13, 'ラモテ・ギルアデにはゲベルの子。彼はギルアデにあるマナセの子ヤイルの町々と、バシャンにあるアルゴブの地域で、城壁と青銅のかんぬきを備えた六十の大きな町を任されていた。'),
('JPN', '列王纪上', 11, 4, 14, 'マハナイムにはイドの子アヒナダブ。'),
('JPN', '列王纪上', 11, 4, 15, 'ナフタリにはアヒマアツ。彼も、ソロモンの娘バセマテを妻としていた。'),
('JPN', '列王纪上', 11, 4, 16, 'アシェルとベアロテにはフシャイの子バアナ。'),
('JPN', '列王纪上', 11, 4, 17, 'イッサカルにはパルアハの子ヨシャファテ。'),
('JPN', '列王纪上', 11, 4, 18, 'ベニヤミンにはエラの子シムイ。'),
('JPN', '列王纪上', 11, 4, 19, 'アモリ人の王シホンとバシャンの王オグの領地であったギルアデの地には、ウリの子ゲベル。彼は、その地で唯一の守護であった。'),
('JPN', '列王纪上', 11, 4, 20, 'ユダとイスラエルの人々は海辺の砂のように多くなり、食べたり飲んだりして、楽しんでいた。'),
('JPN', '列王纪上', 11, 4, 21, 'ソロモンは、あの大河からペリシテ人の地、さらにエジプトの国境に至る、すべての王国を支配した。これらの王国は、ソロモンの一生の間、貢ぎ物を持って来て彼に仕えた。'),
('JPN', '列王纪上', 11, 4, 22, 'ソロモンの一日分の食糧は、上質の小麦粉三十コル、小麦粉六十コル。'),
('JPN', '列王纪上', 11, 4, 23, 'それに、肥えた牛十頭、放牧の牛二十頭、羊百匹。そのほか、雄鹿、かもしか、のろ鹿、そして肥えた鳥であった。'),
('JPN', '列王纪上', 11, 4, 24, 'これはソロモンが、あの大河の西側、ティフサフからガザまでの全土、すなわち大河の西側のすべての王たちを支配し、周辺のすべての地方に平和があったからである。'),
('JPN', '列王纪上', 11, 4, 25, 'ユダとイスラエルは、ソロモンの治世中、ダンからベエル・シェバに至るまでのどこでも、それぞれ自分のぶどうの木の下や、いちじくの木の下で安心して暮らした。'),
('JPN', '列王纪上', 11, 4, 26, 'ソロモンは、戦車用の馬のために馬屋四万、騎兵一万二千を持っていた。'),
('JPN', '列王纪上', 11, 4, 27, '守護たちはそれぞれ自分の当番月に、ソロモン王、およびソロモン王の食卓に連なるすべての者たちのために食糧を納め、不足させなかった。'),
('JPN', '列王纪上', 11, 4, 28, 'また彼らは、引き馬や早馬のために、それぞれ割り当てにしたがって、所定の場所に大麦と藁を持って来た。'),
('JPN', '列王纪上', 11, 4, 29, '神は、ソロモンに非常に豊かな知恵と英知と、海辺の砂浜のように広い心を与えられた。'),
('JPN', '列王纪上', 11, 4, 30, 'ソロモンの知恵は、東のすべての人々の知恵と、エジプト人のすべての知恵にまさっていた。'),
('JPN', '列王纪上', 11, 4, 31, '彼は、どの人よりも、すなわち、エズラフ人エタンや、マホルの息子たちのヘマン、カルコル、ダルダよりも知恵があった。そのため、彼の名声は周辺のすべての国々に広まった。'),
('JPN', '列王纪上', 11, 4, 32, 'ソロモンは三千の箴言を語り、彼の歌は千五首もあった。'),
('JPN', '列王纪上', 11, 4, 33, '彼は、レバノンにある杉の木から、石垣に生えるヒソプに至るまでの草木について語り、獣、鳥、這うもの、そして魚についても語った。'),
('JPN', '列王纪上', 11, 4, 34, '彼の知恵のうわさを聞いた世界のすべての王たちのもとから、あらゆる国の人々が、ソロモンの知恵を聞くためにやって来た。'),
('JPN', '列王纪上', 11, 5, 1, 'さて、ツロの王ヒラムは、ソロモンが油注がれて、彼の父に代わって王となったことを聞いて、自分の家来たちをソロモンのところへ遣わした。ヒラムはダビデと常に友情を保っていたからである。'),
('JPN', '列王纪上', 11, 5, 2, 'そこで、ソロモンはヒラムのもとに人を遣わして言った。'),
('JPN', '列王纪上', 11, 5, 3, '「ご存じのように、私の父ダビデは、周りからいつも戦いを挑まれていたため、主が彼らを私の足の裏の下に置かれるまで、私の父の神、主の御名のために神殿を建てることができませんでした。'),
('JPN', '列王纪上', 11, 5, 4, 'しかし今や、私の神、主は、周囲の者から私を守って安息を与えてくださり、敵対する者もなく、わざわいを起こす者もありません。'),
('JPN', '列王纪上', 11, 5, 5, '今私は、私の神、主の御名のために神殿を建てようと思っています。主が私の父ダビデに、『わたしがあなたの代わりに王座に就かせるあなたの子、彼がわたしの名のために家を建てる』と言われたとおりです。'),
('JPN', '列王纪上', 11, 5, 6, 'どうか、私のために、レバノンから杉を切り出すように命じてください。私の家来たちも、あなたの家来たちと一緒に働きます。私はあなたの家来たちに、あなたが言われるとおりの賃金を払います。ご存じのように、私たちの中にはシドン人のように木を切ることに熟練した者がいませんから。」'),
('JPN', '列王纪上', 11, 5, 7, 'ヒラムはソロモンの申し出を聞いて、大いに喜んで言った。「今日、主がほめたたえられますように。主は、この大いなる民を治める、知恵のある子をダビデにお与えになった。」'),
('JPN', '列王纪上', 11, 5, 8, 'ヒラムはソロモンのもとに人を遣わして言った。「あなたが言い送られたことを聞きました。私は、杉の木材ともみの木材なら、何なりとあなたのお望みどおりにいたしましょう。'),
('JPN', '列王纪上', 11, 5, 9, '私の家来たちは、それをレバノンから海へ下らせます。私はそれをいかだに組んで、海路、あなたが指定される場所まで送り、そこでそれを解かせましょう。それを受け取ってください。それから、あなたは私の一族に食物を与えて、私の望みをかなえてください。」'),
('JPN', '列王纪上', 11, 5, 10, 'こうしてヒラムは、ソロモンに杉の木材ともみの木材を、彼が望むだけ与えた。'),
('JPN', '列王纪上', 11, 5, 11, 'ソロモンはヒラムに、その一族の食糧として、小麦二万コルと上質のオリーブ油二十コルを与えた。ソロモンは、これだけの物を毎年ヒラムに与えた。'),
('JPN', '列王纪上', 11, 5, 12, '主は約束どおり、ソロモンに知恵を授けられた。ヒラムとソロモンとの間には平和が保たれ、二人は契約を結んだ。'),
('JPN', '列王纪上', 11, 5, 13, 'ソロモン王は全イスラエルから役務者を徴用した。役務者は三万人であった。'),
('JPN', '列王纪上', 11, 5, 14, 'ソロモンは、彼らを一か月交代で一万人ずつレバノンに送った。一か月はレバノンに、二か月は家にいるようにした。役務長官はアドニラムであった。'),
('JPN', '列王纪上', 11, 5, 15, 'ソロモンには荷を担ぐ者が七万人、山で石を切り出す者が八万人いた。'),
('JPN', '列王纪上', 11, 5, 16, 'そのほか、ソロモンには工事の監督をする長が三千三百人いて、工事に携わる民を指揮していた。'),
('JPN', '列王纪上', 11, 5, 17, '王は、切り石を神殿の礎に据えるために、大きな石、高価な石を切り出すように命じた。'),
('JPN', '列王纪上', 11, 5, 18, 'ソロモンの建築者たち、ヒラムの建築者たち、そしてゲバル人たちは石を切り、神殿を建てるために木材と石材を準備した。'),
('JPN', '列王纪上', 11, 6, 1, 'イスラエル人がエジプトの地を出てから四百八十年目、ソロモンがイスラエルの王となってから四年目のジブの月、すなわち第二の月に、ソロモンは主の家の建築に取りかかった。'),
('JPN', '列王纪上', 11, 6, 2, 'ソロモン王が主のために建てた神殿は、長さ六十キュビト、幅二十キュビト、高さ三十キュビトであった。'),
('JPN', '列王纪上', 11, 6, 3, '神殿の本殿の前に付く玄関は、長さが神殿の幅と同じ二十キュビト、幅が神殿の前で十キュビトであった。'),
('JPN', '列王纪上', 11, 6, 4, '神殿には格子を取り付けた窓を作った。'),
('JPN', '列王纪上', 11, 6, 5, 'さらに、神殿の壁に、すなわち神殿の壁の周り、本殿と内殿の周りに、脇屋を建て巡らした。こうして階段式の脇間を周りに作った。'),
('JPN', '列王纪上', 11, 6, 6, '脇屋の一階は幅五キュビト、二階は幅六キュビト、三階は幅七キュビトであった。それは、神殿の外周りの壁に段を作り、神殿の壁を梁で支えずにすむようにするためであった。'),
('JPN', '列王纪上', 11, 6, 7, '神殿が建てられたとき、石切り場で完全に仕上げられた石で建てられたので、工事中、槌や斧や、いかなる鉄の道具の音も、いっさい神殿の中では聞こえなかった。'),
('JPN', '列王纪上', 11, 6, 8, '二階の脇間に通じる入り口は神殿の右側にあり、螺旋階段で二階に、また二階から三階に上るようになっていた。'),
('JPN', '列王纪上', 11, 6, 9, 'ソロモンは神殿を建て、これを完成させるにあたって、神殿の屋根を杉材でできた雨水溝の列でおおった。'),
('JPN', '列王纪上', 11, 6, 10, '神殿の側面に脇屋を建て巡らし、その各階の高さは五キュビトにして、これを杉材で神殿に固定させた。'),
('JPN', '列王纪上', 11, 6, 11, 'そのとき、ソロモンに次のような主のことばがあった。'),
('JPN', '列王纪上', 11, 6, 12, '「あなたが建てているこの神殿のことであるが、もし、あなたがわたしの掟に歩み、わたしの定めを行い、わたしのすべての命令を守り、これによって歩むなら、わたしはあなたについてあなたの父ダビデに約束したことを成就しよう。'),
('JPN', '列王纪上', 11, 6, 13, 'わたしはイスラエルの子らのただ中に住み、わたしの民イスラエルを捨てることはしない。」'),
('JPN', '列王纪上', 11, 6, 14, 'こうして、ソロモンは神殿を建て、これを完成させた。'),
('JPN', '列王纪上', 11, 6, 15, '彼は神殿の内側の壁を杉の板でおおい、神殿の床から天井の壁に至るまで、内側を板でおおった。なお神殿の床は、もみの板でおおった。'),
('JPN', '列王纪上', 11, 6, 16, 'それから、彼は神殿の奥の部分二十キュビトを、床から天井の壁に至るまで杉の板でおおった。このようにして、彼は神殿に内殿、すなわち至聖所を設けた。'),
('JPN', '列王纪上', 11, 6, 17, '神殿の手前側の本殿は四十キュビトであった。'),
('JPN', '列王纪上', 11, 6, 18, '神殿内部の杉の板には、瓢簞模様と花模様が浮き彫りにされていて、すべては杉の板で、石は見えなかった。'),
('JPN', '列王纪上', 11, 6, 19, '内殿は神殿内部の奥に、主の契約の箱を置くために設けた。'),
('JPN', '列王纪上', 11, 6, 20, '内殿の内部は、長さ二十キュビト、幅二十キュビト、高さ二十キュビトで、純金でこれをおおった。さらに杉材の祭壇も純金でおおった。'),
('JPN', '列王纪上', 11, 6, 21, 'ソロモンは神殿の内側を純金でおおい、内殿の前に金の鎖を渡し、これに金をかぶせた。'),
('JPN', '列王纪上', 11, 6, 22, '神殿全体を隅々まで金でおおい、内殿に関わる祭壇も全体を金でおおった。'),
('JPN', '列王纪上', 11, 6, 23, '内殿の中にオリーブ材で二つのケルビムを作った。その高さは十キュビトであった。'),
('JPN', '列王纪上', 11, 6, 24, 'ケルビムの一方の翼は五キュビト、もう一方の翼も五キュビト。翼の端から翼の端までは十キュビトであった。'),
('JPN', '列王纪上', 11, 6, 25, 'もう片方のケルビムも十キュビトあり、両方のケルビムは全く同じ寸法、同じ形であった。'),
('JPN', '列王纪上', 11, 6, 26, '片方のケルビムの高さは十キュビト、もう片方のケルビムも同じであった。'),
('JPN', '列王纪上', 11, 6, 27, 'ケルビムは神殿内部に置かれた。ケルビムは翼を広げていて、片方のケルビムの翼は一方の壁に届き、もう片方のケルビムの翼はもう一方の壁に届き、また両者の翼は神殿の真ん中に届いて、翼と翼が触れ合っていた。'),
('JPN', '列王纪上', 11, 6, 28, 'ソロモンはこのケルビムに金をかぶせた。'),
('JPN', '列王纪上', 11, 6, 29, '神殿の四方のすべての壁には、奥の間も外の間も、ケルビムとなつめ椰子の木と花模様の浮き彫りを彫った。'),
('JPN', '列王纪上', 11, 6, 30, '神殿の床は、奥の間も外の間も金でおおった。'),
('JPN', '列王纪上', 11, 6, 31, 'ソロモンは内殿の入り口を、オリーブ材の扉と五角形の戸口の柱で作った。'),
('JPN', '列王纪上', 11, 6, 32, 'その二つのオリーブ材の扉に、ケルビムとなつめ椰子の木と花模様の浮き彫りを彫り、金でおおった。ケルビムとなつめ椰子の木の上に金を張り付けたのである。'),
('JPN', '列王纪上', 11, 6, 33, '同じように、本殿の入り口にも四角形のオリーブ材で戸口の柱を作った。'),
('JPN', '列王纪上', 11, 6, 34, 'また、もみの木で二つの扉を作った。片方の扉の二枚の戸は折り畳み戸、もう片方の扉の二枚の戸も折り畳み戸であった。'),
('JPN', '列王纪上', 11, 6, 35, 'ケルビムとなつめ椰子の木と花模様を彫り付け、その彫り物の上に、ぴったりと金を張り付けた。'),
('JPN', '列王纪上', 11, 6, 36, 'それからソロモンは、切り石三段と杉の角材一段の仕切りで内庭を造った。'),
('JPN', '列王纪上', 11, 6, 37, '第四年のジブの月に、主の宮の礎を据え、'),
('JPN', '列王纪上', 11, 6, 38, '第十一年のブルの月、すなわち第八の月に、神殿のすべての部分が設計どおりに完成した。七年かけて建てたのである。'),
('JPN', '列王纪上', 11, 7, 1, 'また、ソロモンは十三年をかけて自分の宮殿を建て、その宮殿のすべてを完成させた。'),
('JPN', '列王纪上', 11, 7, 2, '彼は「レバノンの森の宮殿」を建てた。その長さは百キュビト、幅は五十キュビト、高さは三十キュビトで、それは四列の杉材の柱の上にあり、その柱の上には杉材の梁があった。'),
('JPN', '列王纪上', 11, 7, 3, 'また、四十五本の柱の上にある階段式脇間の屋根は、杉材で葺かれていた。柱は一列に十五本ずつあった。'),
('JPN', '列王纪上', 11, 7, 4, '戸口は三列あり、三段になって向かい合っていた。'),
('JPN', '列王纪上', 11, 7, 5, '戸口の扉と戸口の柱はすべて四角形で、三段になって向かい合っていた。'),
('JPN', '列王纪上', 11, 7, 6, 'また彼は、柱の広間を造った。その長さは五十キュビト、その幅は三十キュビトであった。その前に玄関があり、その前に柱とひさしがあった。'),
('JPN', '列王纪上', 11, 7, 7, 'また、さばきをするための王座の広間、すなわち、さばきの広間を造り、床の隅々から天井まで杉材を張り詰めた。'),
('JPN', '列王纪上', 11, 7, 8, '彼の住む家はその広間のうしろの庭にあり、同じ造りであった。ソロモンは、彼が妻としたファラオの娘のためにも、この広間と同じような家を建てた。'),
('JPN', '列王纪上', 11, 7, 9, 'これらはすべて内側も外側も、のこぎりで寸法どおりに切りそろえられた、高価な石で造られていた。礎から軒に至るまで、さらに外庭から大庭に至るまで、そうであった。'),
('JPN', '列王纪上', 11, 7, 10, '礎は高価な石、大きな石で、八キュビトも十キュビトもあった。'),
('JPN', '列王纪上', 11, 7, 11, 'その上には、寸法どおりに切りそろえられた高価な石と杉材が使われた。'),
('JPN', '列王纪上', 11, 7, 12, '大庭の周囲には、三段の切り石と一段の杉の角材が使われ、主の宮の内庭や、神殿の玄関広間と同じであった。'),
('JPN', '列王纪上', 11, 7, 13, 'ソロモンは人を遣わして、ツロからヒラムを呼んで来た。'),
('JPN', '列王纪上', 11, 7, 14, '彼はナフタリ部族のやもめの子であった。彼の父はツロの人で、青銅の細工師であった。ヒラムは青銅の細工物全般について、知恵と英知と知識に満ちていた。彼はソロモン王のもとに来て、その一切の細工を行った。'),
('JPN', '列王纪上', 11, 7, 15, '彼は青銅で二本の柱を鋳造した。片方の柱の高さは十八キュビト。もう片方の柱の周囲は、ひもで測って十二キュビトであった。'),
('JPN', '列王纪上', 11, 7, 16, '彼は青銅で鋳造した二つの柱頭を作って、柱の頂に載せた。片方の柱頭の高さは五キュビト、もう片方の柱頭の高さも五キュビトであった。'),
('JPN', '列王纪上', 11, 7, 17, '柱の頂の柱頭に取り付ける、鎖で編んで房になった格子細工の網を、片方の柱頭に七つ、もう片方の柱頭に七つ作った。'),
('JPN', '列王纪上', 11, 7, 18, 'こうして彼は柱を作り、柱の頂にある柱頭をおおうため、青銅のざくろが格子網の上を二段に取り巻くようにし、もう片方の柱頭にも同じようにした。'),
('JPN', '列王纪上', 11, 7, 19, 'この玄関広間にある柱の頂にある柱頭は、ゆりの花の細工で、それは四キュビトであった。'),
('JPN', '列王纪上', 11, 7, 20, '二本の柱の上にある柱頭の格子網のあたりで、丸い突出部の周りには、二百個のざくろが、両方の柱頭に段をなして並んでいた。'),
('JPN', '列王纪上', 11, 7, 21, 'この柱を本殿の玄関広間の前に立てた。彼は右側に立てた柱にヤキンという名をつけ、左側に立てた柱にボアズという名をつけた。'),
('JPN', '列王纪上', 11, 7, 22, 'この柱の頂の上には、ゆりの花の細工があった。こうして、柱の造作は完成した。'),
('JPN', '列王纪上', 11, 7, 23, 'それから、彼は鋳物の「海」を作った。縁から縁まで十キュビト。円形で、高さは五キュビト。周囲は測り縄で巻いて三十キュビトであった。'),
('JPN', '列王纪上', 11, 7, 24, 'その縁の下に沿って、瓢簞模様が周りを取り巻いていた。一キュビトにつき十ずつの割合でその「海」の周りを取り巻いていた。この瓢箪模様は二段になっていて、「海」を鋳たときに鋳込んだものである。'),
('JPN', '列王纪上', 11, 7, 25, '「海」は十二頭の牛の上に据えられていた。三頭は北を向き、三頭は西を向き、三頭は南を向き、三頭は東を向いていた。「海」はこれらの牛の上に載せられていて、牛の後部はすべて内側を向いていた。'),
('JPN', '列王纪上', 11, 7, 26, '「海」の厚さは一手幅あり、その縁は杯の縁のように、ゆりの花の形をしていた。その容量は二千バテであった。'),
('JPN', '列王纪上', 11, 7, 27, '彼は青銅で十個の台を作った。それぞれの台は長さ四キュビト、幅四キュビト、高さ三キュビトであった。'),
('JPN', '列王纪上', 11, 7, 28, 'この台の構造は次のとおり。台には鏡板があり、鏡板は枠にはめられていた。'),
('JPN', '列王纪上', 11, 7, 29, '枠にはめられている鏡板の上には、雄獅子と牛とケルビムがあり、雄獅子と牛の上下にある枠の表面には花模様が施されていた。'),
('JPN', '列王纪上', 11, 7, 30, '台には、それぞれ、青銅の車輪が四つと、青銅の軸が付いていて、台の四隅には洗盤の支えがあり、その支えは洗盤の下にあって、それぞれの表面に花模様が鋳込まれていた。'),
('JPN', '列王纪上', 11, 7, 31, '洗盤の口は冠の内側にあって、一キュビト上に出ていた。その口は丸く、花模様の細工が施され、一キュビト半あった。またその口の上にも彫刻がしてあり、枠の鏡板は四角で、丸くなかった。'),
('JPN', '列王纪上', 11, 7, 32, '四つの車輪は鏡板の下にあり、車軸は台に取り付けられ、一つの車輪の高さは一キュビト半であった。'),
('JPN', '列王纪上', 11, 7, 33, 'その車輪の作りは戦車の車輪の作りと同じで、車軸も輪縁も輻も轂も、みな鋳物であった。'),
('JPN', '列王纪上', 11, 7, 34, 'それぞれの台の四隅には、四本の支えがあり、支えと台は一体となっていた。'),
('JPN', '列王纪上', 11, 7, 35, '台の上部には高さ半キュビトの丸い部分が取り巻いていて、その台の上の支えと鏡板は一体となっていた。'),
('JPN', '列王纪上', 11, 7, 36, 'その支えの表面と鏡板には、それぞれの場所に、ケルビムと雄獅子となつめ椰子の木を刻み、その周囲には花模様を刻んだ。'),
('JPN', '列王纪上', 11, 7, 37, '彼は以上のように十個の台を作った。それらはすべて同じように鋳造され、同じ寸法、同じ形であった。'),
('JPN', '列王纪上', 11, 7, 38, 'それから、彼は青銅で十個の洗盤を作った。洗盤の容量はそれぞれ四十バテ、大きさはそれぞれ四キュビトであった。洗盤はそれぞれの台に一個ずつ、十個の台の上にあった。'),
('JPN', '列王纪上', 11, 7, 39, '彼はその台の五個を神殿の右側に、五個を神殿の左側に置き、「海」を神殿の右側、東南の方角に置いた。'),
('JPN', '列王纪上', 11, 7, 40, 'さらにヒラムは灰壺と十能と鉢を作った。こうして、ヒラムは、ソロモン王のために主の宮でなすべきすべての仕事を完了した。'),
('JPN', '列王纪上', 11, 7, 41, 'すなわち、二本の柱と、二本の柱の頂にある丸い柱頭、および柱の頂にある丸い二つの柱頭をおおう二つの格子細工、'),
('JPN', '列王纪上', 11, 7, 42, 'また、二つの格子細工に取り付ける四百個のざくろ、すなわち、柱の先端にある丸い二つの柱頭をおおうそれぞれの格子細工のための二段のざくろ、'),
('JPN', '列王纪上', 11, 7, 43, 'また、十個の台と、その台の上の十個の洗盤、'),
('JPN', '列王纪上', 11, 7, 44, '「海」一つと、その「海」の下の十二頭の牛、'),
('JPN', '列王纪上', 11, 7, 45, 'そして、灰壺と十能と鉢である。ヒラムがソロモン王のため、主の宮のために作ったこれらのすべての物は、磨きをかけた青銅であった。'),
('JPN', '列王纪上', 11, 7, 46, '王は、ヨルダンの低地、スコテとツァレタンの間にある粘土の地でこれらを鋳造した。'),
('JPN', '列王纪上', 11, 7, 47, 'ソロモンは、すべての用具を配置した。非常に大量だったので、青銅の重さは量られなかった。'),
('JPN', '列王纪上', 11, 7, 48, 'また、ソロモンは主の宮にあるあらゆる物を作った。金の祭壇と、臨在のパンを載せる金の机、'),
('JPN', '列王纪上', 11, 7, 49, '内殿の前、右側に五つ、左側に五つ置かれる純金の燭台、金の飾り花、ともしび皿、芯切りばさみを作った。'),
('JPN', '列王纪上', 11, 7, 50, 'また純金の皿と、芯取りばさみ、鉢、平皿、火皿を純金で作った。至聖所に通じる神殿内部の扉のちょうつがい、神殿の本殿に通じる扉のちょうつがいも金で作った。'),
('JPN', '列王纪上', 11, 7, 51, 'こうして、ソロモン王が主の宮のためにしたすべての工事が完了した。ソロモンは父ダビデが聖別した物、すなわち、銀、金、各種の用具類を運び入れ、主の宮の宝物倉に納めた。'),
('JPN', '列王纪上', 11, 8, 1, 'それからソロモンは、イスラエルの長老たち、および、イスラエルの部族のかしらたちと一族の長たちをすべて、エルサレムのソロモン王のもとに召集した。ダビデの町シオンから主の契約の箱を運び上げるためであった。'),
('JPN', '列王纪上', 11, 8, 2, 'イスラエルのすべての人々は、エタニムの月、すなわち第七の新月の祭りにソロモン王のもとに集まった。'),
('JPN', '列王纪上', 11, 8, 3, 'イスラエルの長老全員が到着すると、祭司たちは箱を担ぎ、'),
('JPN', '列王纪上', 11, 8, 4, '主の箱と、会見の天幕と、天幕にあったすべての聖なる用具を運び上げた。これらの物を祭司たちとレビ人たちが運び上げた。'),
('JPN', '列王纪上', 11, 8, 5, 'ソロモン王と、王のところに集まったイスラエルの全会衆は、ともに箱の前に行き、羊や牛をいけにえとして献げた。その数はあまりにも多く、数えることも調べることもできなかった。'),
('JPN', '列王纪上', 11, 8, 6, '祭司たちは、主の契約の箱を、定められた場所、すなわち神殿の内殿である至聖所のケルビムの翼の下に運び入れた。'),
('JPN', '列王纪上', 11, 8, 7, 'ケルビムは、箱の一定の場所の上に翼を広げるのである。こうしてケルビムは箱とその担ぎ棒を上からおおった。'),
('JPN', '列王纪上', 11, 8, 8, 'その担ぎ棒は長かったので、棒の先が内殿の前の聖所からは見えていたが、外からは見えなかった。それは今日までそこにある。'),
('JPN', '列王纪上', 11, 8, 9, '箱の中には、二枚の石の板のほかには何も入っていなかった。これは、イスラエルの子らがエジプトの地から出て来たとき、主が彼らと契約を結ばれた際に、モーセがホレブでそこに納めたものである。'),
('JPN', '列王纪上', 11, 8, 10, '祭司たちが聖所から出て来たとき、雲が主の宮に満ちた。'),
('JPN', '列王纪上', 11, 8, 11, '祭司たちは、その雲のために、立って仕えることができなかった。主の栄光が主の宮に満ちたからである。'),
('JPN', '列王纪上', 11, 8, 12, 'そのとき、ソロモンは言った。「主は、黒雲の中に住む、と言われました。'),
('JPN', '列王纪上', 11, 8, 13, '私は、あなたの御住まいである家を、確かに建てました。御座がとこしえに据えられる場所を。」'),
('JPN', '列王纪上', 11, 8, 14, 'それから王は振り向いて、イスラエルの全会衆を祝福した。イスラエルの全会衆は起立していた。'),
('JPN', '列王纪上', 11, 8, 15, '彼は言った。「イスラエルの神、主がほめたたえられますように。主は御口をもって私の父ダビデに語り、御手をもってこれを成し遂げて、こう言われた。'),
('JPN', '列王纪上', 11, 8, 16, '『わたしの民イスラエルをエジプトから導き出した日からこのかた、わたしは、わたしの名を置く家を建てるために、イスラエルの全部族のうちのどの町も選ばなかった。わたしはダビデを選び、わたしの民イスラエルの上に立てた。』'),
('JPN', '列王纪上', 11, 8, 17, 'それで私の父ダビデの心にはいつも、イスラエルの神、主の御名のために家を建てたいという思いがあった。'),
('JPN', '列王纪上', 11, 8, 18, 'ところが主は、私の父ダビデにこう言われた。『あなたの心にはいつも、わたしの名のために家を建てたいという思いがあった。その思いがあなたの心にあったことは、良いことである。'),
('JPN', '列王纪上', 11, 8, 19, 'しかし、あなたはその家を建ててはならない。あなたの腰から生まれ出るあなたの子が、わたしの名のために家を建てるのだ。』'),
('JPN', '列王纪上', 11, 8, 20, '主はお告げになった約束を果たされたので、私は主の約束どおりに父ダビデに代わって立ち、イスラエルの王座に就いた。そしてイスラエルの神、主の御名のためにこの家を建て、'),
('JPN', '列王纪上', 11, 8, 21, '主の契約が納められている箱のために、そこに場所を設けた。その契約は、主が私たちの先祖をエジプトの地から導き出されたときに、彼らと結ばれたものである。」'),
('JPN', '列王纪上', 11, 8, 22, 'ソロモンはイスラエルの全会衆の前で、主の祭壇の前に立ち、天に向かって両手を伸べ広げて、'),
('JPN', '列王纪上', 11, 8, 23, 'こう言った。「イスラエルの神、主よ。上は天、下は地にも、あなたのような神はほかにありません。あなたは、心を尽くして御前に歩むあなたのしもべたちに対し、契約と恵みを守られる方です。'),
('JPN', '列王纪上', 11, 8, 24, 'あなたは、あなたのしもべ、私の父ダビデに約束したことを、ダビデのために守ってくださいました。あなたは御口をもって語り、また、今日のように御手をもってこれを成し遂げられました。'),
('JPN', '列王纪上', 11, 8, 25, 'そこで今、イスラエルの神、主よ。あなたのしもべ、私の父ダビデに約束されたことを、ダビデのために守ってください。『あなたがわたしの前に歩んだように、あなたの子孫がその道を守り、わたしの前に歩みさえするなら、あなたには、イスラエルの王座に就く者がわたしの前から断たれることはない』と言われたことを。'),
('JPN', '列王纪上', 11, 8, 26, '今、イスラエルの神よ。どうかあなたのしもべ、私の父ダビデに約束されたおことばが堅く立てられますように。'),
('JPN', '列王纪上', 11, 8, 27, 'それにしても、神は、はたして地の上に住まわれるでしょうか。実に、天も、天の天も、あなたをお入れすることはできません。まして私が建てたこの宮など、なおさらのことです。'),
('JPN', '列王纪上', 11, 8, 28, 'あなたのしもべの祈りと願いに御顔を向けてください。私の神、主よ。あなたのしもべが、今日、御前にささげる叫びと祈りを聞いてください。'),
('JPN', '列王纪上', 11, 8, 29, 'そして、この宮、すなわち『わたしの名をそこに置く』とあなたが言われたこの場所に、夜も昼も御目を開き、あなたのしもべがこの場所に向かってささげる祈りを聞いてください。'),
('JPN', '列王纪上', 11, 8, 30, 'あなたのしもべとあなたの民イスラエルが、この場所に向かってささげる願いを聞いてください。あなたご自身が、あなたの御住まいの場所、天においてこれを聞いてください。聞いて、お赦しください。'),
('JPN', '列王纪上', 11, 8, 31, 'ある人が隣人に罪を犯して、のろいの誓いを立てるよう求められ、この宮の中にある、あなたの祭壇の前に来て誓うなら、'),
('JPN', '列王纪上', 11, 8, 32, 'あなたご自身が天でこれを聞き、あなたのしもべたちにさばきを行って、悪い者にはその生き方への報いとしてその頭上に悪を下し、正しい者にはその正しさにしたがって義をもって報いてください。'),
('JPN', '列王纪上', 11, 8, 33, 'あなたの民イスラエルが、あなたの前に罪ある者となって敵に打ち負かされたとき、彼らがあなたに立ち返り、御名をほめたたえ、この宮であなたに祈り願うなら、'),
('JPN', '列王纪上', 11, 8, 34, 'あなたご自身が天でこれを聞き、あなたの民イスラエルの罪を赦し、あなたが彼らの先祖にお与えになった地に、彼らを帰らせてください。'),
('JPN', '列王纪上', 11, 8, 35, '彼らがあなたの前に罪ある者となって、天が閉ざされ雨が降らなくなったとき、彼らがこの場所に向かって祈り、御名をほめたたえ、あなたが苦しませたことによって彼らがその罪から立ち返るなら、'),
('JPN', '列王纪上', 11, 8, 36, 'あなたご自身が天でこれを聞き、あなたのしもべたち、あなたの民イスラエルの罪を赦してください。彼らの歩むべき良い道を彼らに教え、あなたの民に相続地としてお与えになったあなたの地に雨を降らせてください。'),
('JPN', '列王纪上', 11, 8, 37, 'この地に飢饉が起こり、疫病や立ち枯れや黒穂病、いなごやその若虫が発生したときでも、敵がこの地の町々を攻め囲んだときでも、どのようなわざわい、どのような病気であっても、'),
('JPN', '列王纪上', 11, 8, 38, 'だれでもあなたの民イスラエルが、それぞれ自分の心の痛みを知って、この宮に向かって両手を伸べ広げて祈るなら、どのような祈り、どのような願いであっても、'),
('JPN', '列王纪上', 11, 8, 39, 'あなたご自身が、御座が据えられた場所である天で聞いて、赦し、また、かなえてください。一人ひとりに、そのすべての生き方にしたがって報いてください。あなたはその心をご存じです。あなただけが、すべての人の子の心をご存じだからです。'),
('JPN', '列王纪上', 11, 8, 40, 'そうして、あなたが私たちの先祖にお与えになった大地の上で彼らが生き続ける間、いつもあなたを恐れるようにしてください。'),
('JPN', '列王纪上', 11, 8, 41, '同様に、あなたの民イスラエルの者でない異国人についても、その人があなたの御名のゆえに、遠方の地から来て、'),
('JPN', '列王纪上', 11, 8, 42, '彼らが、あなたの大いなる御名と力強い御手と伸ばされた御腕について聞き、やって来てこの宮に向かって祈るなら、'),
('JPN', '列王纪上', 11, 8, 43, 'あなたご自身が、あなたの御座が据えられた場所である天でこれを聞き、その異国人があなたに向かって願うことをすべて、かなえてください。そうすれば、地上のあらゆる民が御名を知り、あなたの民イスラエルと同じようにあなたを恐れるようになり、私が建てたこの宮で御名が呼び求められなければならないことを知るでしょう。'),
('JPN', '列王纪上', 11, 8, 44, 'あなたの民が敵との戦いのために出て行くとき、遣わされる道で、あなたがお選びになった都、私が御名のために建てた宮に向かって主に祈るなら、'),
('JPN', '列王纪上', 11, 8, 45, '天で彼らの祈りと願いを聞いて、彼らの言い分を聞き入れてやってください。'),
('JPN', '列王纪上', 11, 8, 46, '罪に陥らない人は一人もいません。ですから、彼らがあなたの前に罪ある者となったために、あなたが怒って彼らを敵に渡し、彼らが、遠くであれ近くであれ敵国に捕虜として捕らわれて行き、'),
('JPN', '列王纪上', 11, 8, 47, '捕らわれて行った地で我に返り、その捕囚の地であなたに立ち返ってあわれみを乞い、『私たちは罪ある者です。不義をなし、悪を行いました』と言い、'),
('JPN', '列王纪上', 11, 8, 48, '捕らわれて行った敵国で、心のすべて、たましいのすべてをもって、あなたに立ち返り、あなたが彼らの先祖にお与えになった彼らの地、あなたがお選びになったこの都、私が御名のために建てたこの宮に向かって、あなたに祈るなら、'),
('JPN', '列王纪上', 11, 8, 49, 'あなたの御座が据えられた場所である天で、彼らの祈りと願いを聞き、彼らの訴えをかなえて、'),
('JPN', '列王纪上', 11, 8, 50, 'あなたの前に罪ある者となったあなたの民を赦し、あなたに背いた、彼らのすべての背きを赦し、彼らを捕らえて行った者たちの前で彼らをあわれみ、その者たちがあなたの民をあわれむようにしてください。'),
('JPN', '列王纪上', 11, 8, 51, '彼らはあなたの民であり、あなたがエジプトから、鉄の炉の中から導き出された、ご自分のゆずりの民だからです。'),
('JPN', '列王纪上', 11, 8, 52, 'どうか、あなたのしもべの願いと、あなたの民イスラエルの願いに御目を開き、彼らがあなたを呼び求めるとき、いつもその願いを聞き入れてください。'),
('JPN', '列王纪上', 11, 8, 53, 'あなたが彼らを地上のあらゆる民から選り分けて、ご自分のものとされたのですから。神、主よ。あなたが私たちの先祖をエジプトから導き出されたとき、あなたのしもべモーセを通してお告げになったとおりです。」'),
('JPN', '列王纪上', 11, 8, 54, 'こうしてソロモンは、この祈りと願いをことごとく主にささげ終えた。彼は、それまでひざまずいて、天に向かって両手を伸べ広げていた主の祭壇の前から立ち上がり、'),
('JPN', '列王纪上', 11, 8, 55, 'まっすぐに立って、イスラエルの全会衆を大声で祝福して言った。'),
('JPN', '列王纪上', 11, 8, 56, '「主がほめたたえられますように。主は約束どおり、ご自分の民イスラエルに安住の地を与えてくださいました。しもべモーセを通してお告げになった良い約束はみな、一つも、地に落ちることはありませんでした。'),
('JPN', '列王纪上', 11, 8, 57, '私たちの神、主が、私たちの先祖とともにいてくださったように、私たちとともにいて、私たちを見放さず、私たちをお見捨てになることがありませんように。'),
('JPN', '列王纪上', 11, 8, 58, '私たちの心を主に傾けさせ、私たちが主のすべての道に歩み、私たちの先祖にお命じになった命令と掟と定めを守らせてくださいますように。'),
('JPN', '列王纪上', 11, 8, 59, '私が主の御前で願ったこれらのことばが、昼も夜も、私たちの神、主のみそば近くにあって、日常のことにおいても、しもべの訴えや、御民イスラエルの訴えを正しくかなえてくださいますように。'),
('JPN', '列王纪上', 11, 8, 60, 'こうして、ついに地上のあらゆる民が、主こそ神であり、ほかに神はいないことを知るに至りますように。'),
('JPN', '列王纪上', 11, 8, 61, 'あなたがたは、今日のように、私たちの神、主と心を一つにし、主の掟に歩み、主の命令を守らなければならないのです。」'),
('JPN', '列王纪上', 11, 8, 62, 'それから、王と、一緒にいたすべてのイスラエル人は、主の前にいけにえを献げた。'),
('JPN', '列王纪上', 11, 8, 63, 'ソロモンは主へのいけにえとして、牛二万二千頭と羊十二万匹の交わりのいけにえを献げた。こうして、王とすべてのイスラエルの人々は主の宮を奉献した。'),
('JPN', '列王纪上', 11, 8, 64, 'その日、王は主の宮の前庭の中央部を聖別し、そこで全焼のささげ物と、穀物のささげ物と、交わりのいけにえの脂肪を献げた。主の前にあった青銅の祭壇は、全焼のささげ物と、穀物のささげ物と、交わりのいけにえの脂肪を受け入れるには小さすぎたからである。'),
('JPN', '列王纪上', 11, 8, 65, 'ソロモンはこのとき、ともにいた全イスラエル、すなわち、レボ・ハマテからエジプト川に至るまでの大会衆と一緒に、七日と七日の十四日間、私たちの神、主の前で祭りを行った。'),
('JPN', '列王纪上', 11, 8, 66, '八日目に王は民を帰らせた。民は王に祝福のことばを述べ、主がそのしもべダビデと、その民イスラエルに下さったすべての恵みを喜び、心満たされて、彼らの天幕に帰って行った。'),
('JPN', '列王纪上', 11, 9, 1, 'ソロモンが、主の宮と王宮、および、ソロモンが造りたいと望んでいたすべてのものを完成させたとき、'),
('JPN', '列王纪上', 11, 9, 2, '主は、かつてギブオンで現れたときのように、ソロモンに再び現れた。'),
('JPN', '列王纪上', 11, 9, 3, '主は彼に言われた。「あなたがわたしの前で願った祈りと願いをわたしは聞いた。わたしは、あなたがわたしの名をとこしえに置くために建てたこの宮を聖別した。わたしの目と心は、いつもそこにある。'),
('JPN', '列王纪上', 11, 9, 4, 'もしあなたが、あなたの父ダビデが歩んだように、全き心と正直さをもってわたしの前に歩み、わたしがあなたに命じたことすべてをそのまま実行し、わたしの掟と定めを守るなら、'),
('JPN', '列王纪上', 11, 9, 5, 'わたしが、あなたの父ダビデに『あなたには、イスラエルの王座から人が断たれることはない』と約束したとおり、あなたの王国の王座をイスラエルの上にとこしえに立たせよう。'),
('JPN', '列王纪上', 11, 9, 6, 'もし、あなたがたとあなたがたの子孫が、わたしに背を向けて離れ、あなたがたの前に置いたわたしの命令とわたしの掟を守らずに、行ってほかの神々に仕え、それを拝むなら、'),
('JPN', '列王纪上', 11, 9, 7, 'わたしは彼らに与えた地の面からイスラエルを断ち切り、わたしがわたしの名のために聖別した宮をわたしの前から投げ捨てる。イスラエルは、すべての民の間で物笑いの種となり、嘲りの的となる。'),
('JPN', '列王纪上', 11, 9, 8, 'この宮は廃墟となり、そのそばを通り過ぎる者はみな驚き恐れてささやき、『何のために、主はこの地とこの宮に、このような仕打ちをされたのだろう』と言う。'),
('JPN', '列王纪上', 11, 9, 9, '人々は、『彼らは、エジプトの地から自分たちの先祖を導き出した彼らの神、主を捨ててほかの神々に頼り、それを拝み、それに仕えた。そのため主はこのすべてのわざわいを彼らに下されたのだ』と言う。」'),
('JPN', '列王纪上', 11, 9, 10, 'ソロモンが主の宮と王宮との二つの家を二十年かけて建て終えたとき、'),
('JPN', '列王纪上', 11, 9, 11, 'ツロの王ヒラムが、ソロモンの要請に応じて、杉の木材、もみの木材、および金を用立てたので、ソロモン王はガリラヤ地方の二十の町をヒラムに与えた。'),
('JPN', '列王纪上', 11, 9, 12, 'ヒラムはツロからやって来て、ソロモンが彼に与えた町々を見たが、彼はそれらが気に入らなかった。'),
('JPN', '列王纪上', 11, 9, 13, '彼は、「兄弟よ。あなたが私に下さったこの町々は、いったい何ですか」と言った。そのため、これらの町々はカブルの地と呼ばれ、今日に至っている。'),
('JPN', '列王纪上', 11, 9, 14, 'ヒラムは王に金百二十タラントを贈っていた。'),
('JPN', '列王纪上', 11, 9, 15, 'ソロモン王は役務者を徴用して次のような事業をした。彼は主の宮と自分の宮殿、ミロとエルサレムの城壁、ハツォルとメギドとゲゼルを築き直した。'),
('JPN', '列王纪上', 11, 9, 16, 'かつてエジプトの王ファラオは、上って来てゲゼルを攻め取り、これを火で焼き、この町に住んでいたカナン人を殺して、ソロモンの妻である自分の娘に結婚の贈り物としてこの町を与えた。'),
('JPN', '列王纪上', 11, 9, 17, 'ソロモンはこのゲゼルを築き直したのである。また、下ベテ・ホロン、'),
('JPN', '列王纪上', 11, 9, 18, 'バアラテ、この地の荒野にあるタデモル、'),
('JPN', '列王纪上', 11, 9, 19, 'ソロモンの所有するすべての倉庫の町々、戦車のための町々、騎兵のための町々、またソロモンがエルサレム、レバノン、および彼の全領地に建てたいと切に願っていたものを建てた。'),
('JPN', '列王纪上', 11, 9, 20, 'イスラエル人ではない、アモリ人、ヒッタイト人、ペリジ人、ヒビ人、エブス人の生き残りの民すべて、'),
('JPN', '列王纪上', 11, 9, 21, 'すなわち、この地に残されていた人々、イスラエル人が聖絶できなかった人々の子孫を、ソロモンは強制労働に徴用した。今日に至るまで、そうである。'),
('JPN', '列王纪上', 11, 9, 22, 'しかし、ソロモンはイスラエル人を奴隷にはしなかった。彼らは戦士であり、彼の家来であり、隊長であり、補佐官であり、戦車隊や騎兵隊の長だったからである。'),
('JPN', '列王纪上', 11, 9, 23, 'ソロモンには工事の監督をする長が五百五十人いて、工事に携わる民を指揮していた。'),
('JPN', '列王纪上', 11, 9, 24, 'ファラオの娘が、ダビデの町から、ソロモンが彼女のために建てた家に上って来たとき、ソロモンはミロを建てた。'),
('JPN', '列王纪上', 11, 9, 25, 'ソロモンは、主のために築いた祭壇の上に、一年に三度、全焼のささげ物と交わりのいけにえを献げ、それらとともに主の前で香をたいた。彼は神殿を完成させた。'),
('JPN', '列王纪上', 11, 9, 26, 'また、ソロモン王は、エドムの地の葦の海の岸辺にあるエイラトに近いエツヨン・ゲベルに船団を設けた。'),
('JPN', '列王纪上', 11, 9, 27, 'ヒラムはこの船団に、自分のしもべで海に詳しい水夫たちを、ソロモンのしもべたちと一緒に送り込んだ。'),
('JPN', '列王纪上', 11, 9, 28, '彼らはオフィルへ行き、そこから四百二十タラントの金を取って、ソロモン王のもとに運んだ。'),
('JPN', '列王纪上', 11, 10, 1, 'ときに、シェバの女王は、主の御名によるソロモンの名声を聞き、難問をもって彼を試そうとしてやって来た。'),
('JPN', '列王纪上', 11, 10, 2, '彼女は非常に大勢の従者を率い、バルサム油と非常に多くの金および宝石をらくだに載せて、エルサレムにやって来た。彼女はソロモンのところに来ると、心にあることをすべて彼に問いかけた。'),
('JPN', '列王纪上', 11, 10, 3, 'ソロモンは、彼女のすべての問いに答えた。王が分からなくて、彼女に答えられなかったことは何一つなかった。'),
('JPN', '列王纪上', 11, 10, 4, 'シェバの女王は、ソロモンのすべての知恵と、彼が建てた宮殿と、'),
('JPN', '列王纪上', 11, 10, 5, 'その食卓の料理、列席の家来たち、給仕たちの態度とその服装、献酌官たち、そして彼が主の宮で献げた全焼のささげ物を見て、息も止まるばかりであった。'),
('JPN', '列王纪上', 11, 10, 6, '彼女は王に言った。「私が国であなたの事績とあなたの知恵について聞き及んでいたことは、本当でした。'),
('JPN', '列王纪上', 11, 10, 7, '私は自分で来て、自分の目で見るまでは、そのことを信じなかったのですが、なんと、私にはその半分も知らされていなかったのです。あなたの知恵と繁栄は、私が聞いていたうわさより、はるかにまさっています。'),
('JPN', '列王纪上', 11, 10, 8, 'なんと幸せなことでしょう。あなたにつく人たちは。なんと幸せなことでしょう。いつもあなたの前に立って、あなたの知恵を聞くことができる、このあなたの家来たちは。'),
('JPN', '列王纪上', 11, 10, 9, 'あなたの神、主がほめたたえられますように。主はあなたを喜び、イスラエルの王座にあなたを就かせられました。主はイスラエルをとこしえに愛しておられるので、あなたを王とし、公正と正義を行わせるのです。」'),
('JPN', '列王纪上', 11, 10, 10, '彼女は百二十タラントの金と、非常に多くのバルサム油と宝石を王に贈った。シェバの女王がソロモン王に贈ったほど多くのバルサム油は、二度と入って来なかった。'),
('JPN', '列王纪上', 11, 10, 11, 'また、オフィルから金を積んで来たヒラムの船団は、非常に多くの白檀の木材と宝石を、オフィルから運んで来た。'),
('JPN', '列王纪上', 11, 10, 12, '王はこの白檀の木材で、主の宮と王宮のための柱を作り、歌い手たちのための竪琴と琴を作った。今日まで、このような白檀の木材が入って来たことはなく、見られたこともなかった。'),
('JPN', '列王纪上', 11, 10, 13, 'ソロモン王は、シェバの女王が求めたものは何でもその望みのままに与えた。さらに、ソロモン王の豊かさにふさわしいものも彼女に与えた。彼女は家来たちを連れて、自分の国へ帰って行った。'),
('JPN', '列王纪上', 11, 10, 14, '一年間にソロモンのところに入って来た金の重さは、金の目方で六百六十六タラントであった。'),
('JPN', '列王纪上', 11, 10, 15, 'このほかに、隊商から得たもの、貿易商人の商いで得たもの、アラビアのすべての王たち、およびその地の総督たちからのものがあった。'),
('JPN', '列王纪上', 11, 10, 16, 'ソロモン王は、延べ金で大盾二百を作り、その大盾一つに六百シェケルの金を使った。'),
('JPN', '列王纪上', 11, 10, 17, 'また延べ金で盾三百を作り、その盾一つに三ミナの金を使った。王はそれらを「レバノンの森の宮殿」に置いた。'),
('JPN', '列王纪上', 11, 10, 18, '王は大きな象牙の王座を作り、これに純粋な金をかぶせた。'),
('JPN', '列王纪上', 11, 10, 19, '王座には六つの段があり、その王座の背の上部は丸かった。座席の両側に肘掛けがあり、その肘掛けのわきには二頭の雄獅子が立っていた。'),
('JPN', '列王纪上', 11, 10, 20, 'また、十二頭の雄獅子が六つの段の両側に立っていた。このような物は、どこの王国でも作られたことがなかった。'),
('JPN', '列王纪上', 11, 10, 21, 'ソロモン王が飲み物に用いる器はすべて金であった。「レバノンの森の宮殿」にあった器もすべて純金で、銀の物はなかった。銀は、ソロモンの時代には価値あるものとは見なされていなかった。'),
('JPN', '列王纪上', 11, 10, 22, '王が海にヒラムの船団のほかにタルシシュの船団を持っていて、三年に一度、タルシシュの船団が金、銀、象牙、猿、孔雀を運んで来たからである。'),
('JPN', '列王纪上', 11, 10, 23, 'ソロモン王は、富と知恵において、地上のどの王よりもまさっていた。'),
('JPN', '列王纪上', 11, 10, 24, '全世界は、神がソロモンの心に授けられた知恵を聞こうとして、彼に謁見を求めた。'),
('JPN', '列王纪上', 11, 10, 25, '彼らはそれぞれ贈り物として、銀の器、金の器、衣服、武器、バルサム油、馬、ろばなどを、毎年携えて来た。'),
('JPN', '列王纪上', 11, 10, 26, 'ソロモンは戦車と騎兵を集め、戦車千四百台と騎兵一万二千人を所有した。彼はこれらを戦車の町々、およびエルサレムの王のもとに配置した。'),
('JPN', '列王纪上', 11, 10, 27, '王はエルサレムで銀を石のように用い、杉の木をシェフェラのいちじく桑の木のように大量に用いた。'),
('JPN', '列王纪上', 11, 10, 28, 'ソロモンが所有していた馬は、エジプトとクエから輸入されたもので、王の商人たちが、代価を払ってクエから手に入れたものであった。'),
('JPN', '列王纪上', 11, 10, 29, '戦車はエジプトから銀六百、馬は銀百五十で買い上げられて、輸入された。同様に、ヒッタイト人のすべての王やアラムの王たちにも、王の商人たちの仲買で輸出された。'),
('JPN', '列王纪上', 11, 11, 1, 'ソロモン王は、ファラオの娘のほかに多くの異国人の女、すなわちモアブ人の女、アンモン人の女、エドム人の女、シドン人の女、ヒッタイト人の女を愛した。'),
('JPN', '列王纪上', 11, 11, 2, 'この女たちは、主がかつてイスラエル人に、「あなたがたは彼らの中に入ってはならない。彼らをあなたがたの中に入れてもいけない。さもないと、彼らは必ずあなたがたの心を転じて彼らの神々に従わせる」と言われた、その国々の者であった。しかし、ソロモンは彼女たちを愛して離れなかった。'),
('JPN', '列王纪上', 11, 11, 3, '彼には、七百人の王妃としての妻と、三百人の側女がいた。その妻たちが彼の心を転じた。'),
('JPN', '列王纪上', 11, 11, 4, 'ソロモンが年をとったとき、その妻たちが彼の心をほかの神々の方へ向けたので、彼の心は父ダビデの心と違って、彼の神、主と一つにはなっていなかった。'),
('JPN', '列王纪上', 11, 11, 5, 'ソロモンは、シドン人の女神アシュタロテと、アンモン人の、あの忌むべき神ミルコムに従った。'),
('JPN', '列王纪上', 11, 11, 6, 'こうしてソロモンは、主の目に悪であることを行い、父ダビデのようには主に従い通さなかった。'),
('JPN', '列王纪上', 11, 11, 7, '当時ソロモンは、モアブの忌むべきケモシュのために、エルサレムの東にある山の上に高き所を築いた。アンモン人の、忌むべきモレクのためにも、そうした。'),
('JPN', '列王纪上', 11, 11, 8, '彼は異国人であるすべての妻のためにも同じようにしたので、彼女たちは自分の神々に香をたき、いけにえを献げた。'),
('JPN', '列王纪上', 11, 11, 9, '主はソロモンに怒りを発せられた。それは彼の心がイスラエルの神、主から離れたからである。主が二度も彼に現れ、'),
('JPN', '列王纪上', 11, 11, 10, 'このことについて、ほかの神々に従っていってはならないと命じておられたのに、彼が主の命令を守らなかったのである。'),
('JPN', '列王纪上', 11, 11, 11, 'そのため、主はソロモンに言われた。「あなたがこのようにふるまい、わたしが命じたわたしの契約と掟を守らなかったので、わたしは王国をあなたから引き裂いて、あなたの家来に与える。'),
('JPN', '列王纪上', 11, 11, 12, 'しかし、あなたの父ダビデに免じて、あなたが生きている間はそうしない。あなたの子の手から、それを引き裂く。'),
('JPN', '列王纪上', 11, 11, 13, 'ただし、王国のすべてを引き裂くのではなく、わたしのしもべダビデと、わたしが選んだエルサレムのために、一つの部族だけをあなたの子に与える。」'),
('JPN', '列王纪上', 11, 11, 14, 'こうして主は、ソロモンに敵対する者としてエドム人ハダドを起こされた。彼はエドムの王の子孫であった。'),
('JPN', '列王纪上', 11, 11, 15, 'ダビデがかつてエドムにいたころ、軍の長ヨアブが戦死者を葬りに上って行き、エドムの男子をみな打ち殺したことがあった。'),
('JPN', '列王纪上', 11, 11, 16, 'ヨアブは全イスラエルとともに六か月の間そこにとどまり、エドムの男子をみな絶ち滅ぼしたのである。'),
('JPN', '列王纪上', 11, 11, 17, 'しかしそのとき、ハダドは、彼の父のしもべである数人のエドム人と逃げてエジプトへ行った。当時、ハダドは少年であった。'),
('JPN', '列王纪上', 11, 11, 18, '彼らはミディアンを出発してパランまで行き、パランから何人かの従者を従えてエジプトへ、エジプトの王ファラオのところへ行った。するとファラオは彼に家を与え、食糧を支給し、さらに土地も与えた。'),
('JPN', '列王纪上', 11, 11, 19, 'ハダドはファラオにことのほか気に入られ、ファラオは自分の妻の妹、王妃タフペネスの妹を彼に妻として与えた。'),
('JPN', '列王纪上', 11, 11, 20, 'タフペネスの妹は、彼に男の子ゲヌバテを産んだ。タフペネスはその子をファラオの宮殿で育てた。ゲヌバテは、ファラオの宮殿でファラオの子どもたちと一緒にいた。'),
('JPN', '列王纪上', 11, 11, 21, 'ハダドは、ダビデが先祖とともに眠りについたこと、また軍の長ヨアブも死んだことを、エジプトで聞いた。そこでハダドがファラオに「私を国へ帰らせてください」と言うと、'),
('JPN', '列王纪上', 11, 11, 22, 'ファラオは彼に言った。「おまえは、私に何か不満があるのか。自分の国へ帰ることを求めるとは。」するとハダドは、「違います。ただ、とにかく私を帰らせてください」と答えたのである。'),
('JPN', '列王纪上', 11, 11, 23, '神はまた、ソロモンに敵対する者として、エリヤダの子レゾンを起こされた。彼は、自分の主人、ツォバの王ハダドエゼルのもとから逃亡した者であった。'),
('JPN', '列王纪上', 11, 11, 24, 'ダビデがハダドエゼルの兵士たちを殺害した後、レゾンは人々を自分のところに集め、略奪隊の隊長となった。彼らはダマスコに行ってそこに住み、ダマスコを支配した。'),
('JPN', '列王纪上', 11, 11, 25, '彼は、ソロモンが生きている間、ハダドのように悪を行ってイスラエルに敵対し、イスラエルを憎んだ。こうして彼はアラムを支配した。'),
('JPN', '列王纪上', 11, 11, 26, 'ツェレダ出身のエフライム人、ネバテの子ヤロブアムはソロモンの家来であった。彼の母の名はツェルアといい、やもめであった。ところが彼も王に反逆した。'),
('JPN', '列王纪上', 11, 11, 27, '彼が王に反逆するようになった事情はこうである。ソロモンはミロを建て、彼の父ダビデの町の破れ口をふさいでいた。'),
('JPN', '列王纪上', 11, 11, 28, 'ヤロブアムは手腕家であった。ソロモンはこの若者の働きぶりを見て、ヨセフの家のすべての役務を管理させた。'),
('JPN', '列王纪上', 11, 11, 29, 'そのころ、ヤロブアムがエルサレムから出て来ると、シロ人で預言者であるアヒヤが道で彼に会った。アヒヤは新しい外套を着ていた。彼ら二人だけが野にいた。'),
('JPN', '列王纪上', 11, 11, 30, 'アヒヤは着ていた新しい外套をつかみ、それを十二切れに引き裂き、'),
('JPN', '列王纪上', 11, 11, 31, 'ヤロブアムに言った。「十切れを取りなさい。イスラエルの神、主はこう言われる。『見よ。わたしはソロモンの手から王国を引き裂き、十部族をあなたに与える。'),
('JPN', '列王纪上', 11, 11, 32, 'ただし、ソロモンには一つの部族だけ残る。それは、わたしのしもべダビデと、わたしがイスラエルの全部族の中から選んだ都、エルサレムに免じてのことである。'),
('JPN', '列王纪上', 11, 11, 33, 'というのは、人々がわたしを捨て、シドン人の女神アシュタロテや、モアブの神ケモシュや、アンモン人の神ミルコムを拝み、父ダビデのようには、わたしの目にかなうことを行わず、わたしの掟と定めを守らず、わたしの道に歩まなかったからである。'),
('JPN', '列王纪上', 11, 11, 34, 'しかし、わたしはソロモンの手から王国のすべてを取り上げることはしない。わたしが選び、わたしの命令と掟を守った、わたしのしもべダビデに免じて、ソロモンが生きている間は、彼を君主としておく。'),
('JPN', '列王纪上', 11, 11, 35, 'わたしは彼の子の手から王位を取り上げ、十部族をあなたに与える。'),
('JPN', '列王纪上', 11, 11, 36, '彼の子には一つの部族を与える。それは、わたしの名を置くために選んだ都エルサレムで、わたしのしもべダビデが、わたしの前にいつも一つのともしびを保つためである。'),
('JPN', '列王纪上', 11, 11, 37, 'わたしがあなたを召したなら、あなたは自分の望むとおりに王となり、イスラエルを治める王とならなければならない。'),
('JPN', '列王纪上', 11, 11, 38, 'もし、わたしが命じるすべてのことにあなたが聞き従い、わたしの道に歩み、わたしのしもべダビデが行ったように、わたしの掟と命令を守って、わたしの目にかなうことを行うなら、わたしはあなたとともにいて、わたしがダビデのために建てたように、確かな家をあなたのために建て、イスラエルをあなたに与える。'),
('JPN', '列王纪上', 11, 11, 39, 'このために、わたしはダビデの子孫を苦しめる。しかし、それを永久に続けはしない。』」'),
('JPN', '列王纪上', 11, 11, 40, 'ソロモンはヤロブアムを殺そうとしたが、ヤロブアムは立ち去ってエジプトに逃れ、エジプトの王シシャクのもとに行き、ソロモンが死ぬまでエジプトにいた。'),
('JPN', '列王纪上', 11, 11, 41, 'ソロモンについてのその他の事柄、彼が行ったすべてのこと、および彼の知恵、それは『ソロモンの事績の書』に確かに記されている。'),
('JPN', '列王纪上', 11, 11, 42, 'ソロモンがエルサレムで全イスラエルの王であった期間は、四十年であった。'),
('JPN', '列王纪上', 11, 11, 43, 'ソロモンは先祖とともに眠りにつき、父ダビデの町に葬られた。彼の子レハブアムが代わって王となった。'),
('JPN', '列王纪上', 11, 12, 1, 'レハブアムはシェケムに行った。全イスラエルが彼を王とするために、シェケムに来ていたからである。'),
('JPN', '列王纪上', 11, 12, 2, 'ネバテの子ヤロブアムは、まだソロモン王の顔を避けてエジプトに逃れていた間に、レハブアムのことを聞いた。そのとき、ヤロブアムはエジプトに住んでいた。'),
('JPN', '列王纪上', 11, 12, 3, '人々は使者を遣わして、彼を呼び寄せた。ヤロブアムは、イスラエルの全会衆とともにレハブアムのところに来て言った。'),
('JPN', '列王纪上', 11, 12, 4, '「あなたの父上は、私たちのくびきを重くしました。今、あなたは、父上が私たちに負わせた過酷な労働と重いくびきを軽くしてください。そうすれば、私たちはあなたに仕えます。」'),
('JPN', '列王纪上', 11, 12, 5, 'するとレハブアムは彼らに、「行け。三日たったら私のところに戻って来るがよい」と言った。そこで民は出て行った。'),
('JPN', '列王纪上', 11, 12, 6, 'レハブアム王は、父ソロモンが生きている間ソロモンに仕えていた長老たちに、「この民にどう返答したらよいと思うか」と相談した。'),
('JPN', '列王纪上', 11, 12, 7, '彼らは王に答えた。「今日、もしあなたがこの民のしもべとなって彼らに仕え、彼らに答えて親切なことばをかけてやるなら、彼らはいつまでも、あなたのしもべとなるでしょう。」'),
('JPN', '列王纪上', 11, 12, 8, 'しかし、王はこの長老たちが与えた助言を退け、自分とともに育ち、自分に仕えている若者たちにこう相談した。'),
('JPN', '列王纪上', 11, 12, 9, '「この民に何と返答したらよいと思うか。私に『あなたの父上が私たちに負わせたくびきを軽くしてください』と言ってきたのだが。」'),
('JPN', '列王纪上', 11, 12, 10, '彼とともに育った若者たちは答えた。「『あなたの父上は私たちのくびきを重くしました。けれども、あなたはそれを軽くしてください』と言ってきたこの民には、こう答えたらよいでしょう。彼らにこう言いなさい。『私の小指は父の腰よりも太い。'),
('JPN', '列王纪上', 11, 12, 11, '私の父がおまえたちに重いくびきを負わせたのであれば、私はおまえたちのくびきをもっと重くする。私の父がおまえたちをむちで懲らしめたのであれば、私はサソリでおまえたちを懲らしめる』と。」'),
('JPN', '列王纪上', 11, 12, 12, 'ヤロブアムとすべての民は、三日目にレハブアムのところに来た。王が「三日目に私のところに戻って来るがよい」と命じたからである。'),
('JPN', '列王纪上', 11, 12, 13, '王は民に厳しく答え、長老たちが彼に与えた助言を退け、'),
('JPN', '列王纪上', 11, 12, 14, '若者たちの助言どおりに彼らに答えた。「私の父がおまえたちのくびきを重くしたのなら、私はおまえたちのくびきをもっと重くする。私の父がおまえたちをむちで懲らしめたのなら、私はサソリでおまえたちを懲らしめる。」'),
('JPN', '列王纪上', 11, 12, 15, '王は民の願いを聞き入れなかった。かつて主がシロ人アヒヤを通してネバテの子ヤロブアムにお告げになった約束を実現しようと、主がそう仕向けられたからである。'),
('JPN', '列王纪上', 11, 12, 16, '全イスラエルは、王が自分たちに耳を貸さないのを見てとった。そこで、民は王にことばを返した。「ダビデのうちには、われわれのためのどんな割り当て地があろうか。エッサイの子のうちには、われわれのためのゆずりの地はない。イスラエルよ、自分たちの天幕に帰れ。ダビデよ、今、あなたの家を見よ。」イスラエルは自分たちの天幕に帰って行った。'),
('JPN', '列王纪上', 11, 12, 17, 'ただし、ユダの町々に住んでいるイスラエルの子らにとっては、レハブアムがその王であった。'),
('JPN', '列王纪上', 11, 12, 18, 'レハブアム王は役務長官アドラムを遣わしたが、全イスラエルは彼を石で打ち殺した。レハブアム王はやっとの思いで戦車に乗り込み、エルサレムに逃げた。'),
('JPN', '列王纪上', 11, 12, 19, 'このようにして、イスラエルはダビデの家に背いた。今日もそうである。'),
('JPN', '列王纪上', 11, 12, 20, '全イスラエルは、ヤロブアムが戻って来たことを聞いたので、人を遣わして彼を会衆のところに招き、彼を全イスラエルの王とした。ユダの部族以外には、ダビデの家に従う者はいなかった。'),
('JPN', '列王纪上', 11, 12, 21, 'レハブアムはエルサレムに帰り、ユダの全家とベニヤミンの部族から選り抜きの戦士十八万を召集し、王位をソロモンの子レハブアムのもとに取り戻すため、イスラエルの家と戦おうとした。'),
('JPN', '列王纪上', 11, 12, 22, 'すると、神の人シェマヤに次のような神のことばがあった。'),
('JPN', '列王纪上', 11, 12, 23, '「ユダの王、ソロモンの子レハブアム、ユダとベニヤミンの全家、およびそのほかの民に告げよ。'),
('JPN', '列王纪上', 11, 12, 24, '『主はこう言われる。上って行ってはならない。あなたがたの兄弟であるイスラエルの人々と戦ってはならない。それぞれ自分の家に帰れ。わたしが、こうなるように仕向けたのだから。』」そこで、彼らは主のことばに聞き従い、主のことばのとおりに帰って行った。'),
('JPN', '列王纪上', 11, 12, 25, 'ヤロブアムはエフライムの山地にシェケムを築き直し、そこに住んだ。さらに、彼はそこから出て、ペヌエルを築き直した。'),
('JPN', '列王纪上', 11, 12, 26, 'ヤロブアムは心に思った。「今のままなら、この王国はダビデの家に帰るだろう。'),
('JPN', '列王纪上', 11, 12, 27, 'この民が、エルサレムにある主の宮でいけにえを献げるために上ることになっているなら、この民の心は彼らの主君、ユダの王レハブアムに再び帰り、彼らは私を殺して、ユダの王レハブアムのもとに帰るだろう。」'),
('JPN', '列王纪上', 11, 12, 28, 'そこで王は相談して金の子牛を二つ造り、彼らに言った。「もうエルサレムに上る必要はない。イスラエルよ。ここに、あなたをエジプトから連れ上った、あなたの神々がおられる。」'),
('JPN', '列王纪上', 11, 12, 29, 'それから彼は一つをベテルに据え、もう一つをダンに置いた。'),
('JPN', '列王纪上', 11, 12, 30, 'このことは罪となった。民はこの一つを礼拝するためダンまで行った。'),
('JPN', '列王纪上', 11, 12, 31, 'それから彼は高き所の宮を造り、レビの子孫でない一般の民の中から祭司を任命した。'),
('JPN', '列王纪上', 11, 12, 32, 'そのうえ、ヤロブアムはユダにある祭りに倣って、祭りの日を第八の月の十五日と定め、祭壇でささげ物を献げた。こうして彼は、ベテルで自分が造った子牛にいけにえを献げた。また、彼が造った高き所の祭司たちをベテルに常駐させた。'),
('JPN', '列王纪上', 11, 12, 33, '彼は、自分で勝手に考え出した月である第八の月の十五日に、ベテルに造った祭壇でいけにえを献げた。このように、彼はイスラエルの人々のために祭りの日を定め、祭壇でいけにえを献げ、香をたいた。'),
('JPN', '列王纪上', 11, 13, 1, '一人の神の人が、主の命令によってユダからベテルにやって来た。ちょうどそのとき、ヤロブアムは香をたくために祭壇のそばに立っていた。'),
('JPN', '列王纪上', 11, 13, 2, 'すると、この人は主の命令によって祭壇に向かい、これに呼びかけて言った。「祭壇よ、祭壇よ、主はこう言われる。『見よ、一人の男の子がダビデの家に生まれる。その名はヨシヤ。彼は、おまえの上で香をたく高き所の祭司たちを、いけにえとしておまえの上に献げ、人の骨がおまえの上で焼かれる。』」'),
('JPN', '列王纪上', 11, 13, 3, 'その日、彼は一つのしるしを与えて、次のように言った。「これが主の告げられたしるしである。見よ、祭壇は裂け、その上の灰はこぼれ出る。」'),
('JPN', '列王纪上', 11, 13, 4, 'ヤロブアム王は、ベテルの祭壇に向かって叫んでいる神の人のことばを聞いたとき、祭壇から手を伸ばして「彼を捕らえよ」と言った。すると、彼に向けて伸ばしていた手はしなび、戻すことができなくなった。'),
('JPN', '列王纪上', 11, 13, 5, '神の人が主のことばによって与えたしるしのとおり、祭壇は裂け、灰は祭壇からこぼれ出た。'),
('JPN', '列王纪上', 11, 13, 6, 'そこで、王はこの神の人に向かって言った。「どうか、あなたの神、主にお願いして、私のために祈ってください。そうすれば、私の手は元に戻るでしょう。」神の人が主に願ったので、王の手は元に戻り、前と同じようになった。'),
('JPN', '列王纪上', 11, 13, 7, '王は神の人に言った。「私と一緒に宮殿に来て、食事をして元気をつけてください。あなたに贈り物をしたいのです。」'),
('JPN', '列王纪上', 11, 13, 8, 'すると神の人は王に言った。「たとえ、あなたの宮殿の半分を私に下さっても、私はあなたと一緒に参りません。また、この場所ではパンも食べず、水も飲みません。'),
('JPN', '列王纪上', 11, 13, 9, 'というのは、主のことばによって、『パンを食べてはならない。水も飲んではならない。また、もと来た道を通って帰ってはならない』と命じられているからです。」'),
('JPN', '列王纪上', 11, 13, 10, 'こうして、彼はベテルに来たときの道は通らず、ほかの道を通って帰った。'),
('JPN', '列王纪上', 11, 13, 11, '一人の年老いた預言者がベテルに住んでいた。その息子たちが来て、その日、ベテルで神の人がしたことを残らず彼に話した。また、彼らは、この人が王に告げたことばも父に話した。'),
('JPN', '列王纪上', 11, 13, 12, 'すると父は「その人はどの道を行ったか」と彼らに尋ねた。息子たちは、ユダから来た神の人が行った道を知っていた。'),
('JPN', '列王纪上', 11, 13, 13, '父は息子たちに「ろばに鞍を置いてくれ」と言った。彼らがろばに鞍を置くと、父はろばに乗り、'),
('JPN', '列王纪上', 11, 13, 14, '神の人の後を追って行った。そして、その人が樫の木の下に座っているのを見つけると、「ユダからおいでになった神の人はあなたですか」と尋ねた。その人は「私です」と答えた。'),
('JPN', '列王纪上', 11, 13, 15, '彼はその人に「私と一緒に家に来て、パンを食べてください」と言った。')
on conflict (version, book, chapter, verse) do nothing;
insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('JPN', '列王纪上', 11, 13, 16, 'するとその人は言った。「私は、あなたと一緒に引き返して、あなたと一緒に行くことはできません。また、この場所では、あなたと一緒にパンも食べず、水も飲みません。'),
('JPN', '列王纪上', 11, 13, 17, 'というのは、私は主のことばによって、『そこではパンを食べてはならない。水も飲んではならない。もと来た道を通って帰ってはならない』と言われているからです。」'),
('JPN', '列王纪上', 11, 13, 18, '彼はその人に言った。「私もあなたと同じく預言者です。御使いが主のことばを受けて、私に『その人をあなたの家に連れ帰り、パンを食べさせ、水を飲ませよ』と告げました。」こうして彼はその人をだました。'),
('JPN', '列王纪上', 11, 13, 19, 'そこで、その人は彼と一緒に帰り、彼の家でパンを食べ、水を飲んだ。'),
('JPN', '列王纪上', 11, 13, 20, '彼らが食卓に着いていたとき、その人を連れ戻した預言者に主のことばがあったので、'),
('JPN', '列王纪上', 11, 13, 21, '彼は、ユダから来た神の人に呼びかけて言った。「主はこう言われる。『あなたは主のことばに背き、あなたの神、主が命じた命令を守らず、'),
('JPN', '列王纪上', 11, 13, 22, '引き返して、主があなたに、パンを食べてはならない、水も飲んではならないと言った場所でパンを食べ、水を飲んだので、あなたの亡骸は、あなたの先祖の墓には入らない。』」'),
('JPN', '列王纪上', 11, 13, 23, '彼はパンを食べ、水を飲んだ後、彼が連れ帰った預言者のために、ろばに鞍を置いた。'),
('JPN', '列王纪上', 11, 13, 24, 'その人が出て行くと、獅子が道でその人に会い、その人を殺した。死体は道に放り出され、ろばは、そのそばに立っていた。獅子も死体のそばに立っていた。'),
('JPN', '列王纪上', 11, 13, 25, 'そこを人々が通りかかり、道に放り出されている死体と、その死体のそばに立っている獅子を見た。彼らは、あの年老いた預言者の住んでいる町に行って、このことを話した。'),
('JPN', '列王纪上', 11, 13, 26, 'その人を途中から連れ帰ったあの預言者は、それを聞いて言った。「それは、主のことばに背いた神の人だ。主が彼に告げたことばどおりに、主が彼を獅子に渡され、獅子が彼を裂いて殺したのだ。」'),
('JPN', '列王纪上', 11, 13, 27, 'そして、息子たちに「ろばに鞍を置いてくれ」と言ったので、彼らは鞍を置いた。'),
('JPN', '列王纪上', 11, 13, 28, '彼は出かけて行って、道に放り出されている死体と、その死体のそばに立っている、ろばと獅子を見つけた。獅子はその死体を食べず、ろばを引き裂いてもいなかった。'),
('JPN', '列王纪上', 11, 13, 29, 'そこで、年老いた預言者は神の人の遺体を取り上げ、それをろばに乗せて自分の町に持ち帰り、悼み悲しんで葬った。'),
('JPN', '列王纪上', 11, 13, 30, '彼が遺体を自分の墓に納めると、皆はその人のために、「ああ、わが兄弟」と言って悼み悲しんだ。'),
('JPN', '列王纪上', 11, 13, 31, '彼はその人を葬った後、息子たちに言った。「私が死んだら、あの神の人を葬った墓に私を葬り、あの人の骨のそばに私の骨を納めてくれ。'),
('JPN', '列王纪上', 11, 13, 32, 'あの人が主のことばにしたがって、ベテルにある祭壇とサマリアの町々にあるすべての高き所の宮に向かって叫んだことばは、必ず成就するからだ。」'),
('JPN', '列王纪上', 11, 13, 33, 'このことがあった後も、ヤロブアムは悪い道から立ち返ることをせず、引き続き一般の民の中から高き所の祭司たちを任命し、だれでも志願する者を任職して高き所の祭司にした。'),
('JPN', '列王纪上', 11, 13, 34, 'このことは、ヤロブアムの家の罪となり、ついには大地の面から根絶やしにされることとなった。'),
('JPN', '列王纪上', 11, 14, 1, 'このころ、ヤロブアムの子アビヤが病気になったので、'),
('JPN', '列王纪上', 11, 14, 2, 'ヤロブアムは妻に言った。「さあ、変装し、ヤロブアムの妻だと分からないようにしてシロへ行ってくれ。そこには、私がこの民の王となることを私に告げた預言者アヒヤがいる。'),
('JPN', '列王纪上', 11, 14, 3, 'パン十個と菓子数個、それに蜜の瓶を持って彼のところへ行ってくれ。彼は子どもがどうなるか教えてくれるだろう。」'),
('JPN', '列王纪上', 11, 14, 4, 'ヤロブアムの妻は言われたとおりにして、シロへ出かけ、アヒヤの家に行ったが、アヒヤは年をとって目がこわばり、見ることができなかった。'),
('JPN', '列王纪上', 11, 14, 5, 'しかし、主はアヒヤに言われた。「今、ヤロブアムの妻が来て、子どものことをあなたに尋ねようとしている。その子が病気だからだ。あなたは、これこれのことを彼女に告げなければならない。入って来るときには、彼女はほかの女のようなふりをしている。」'),
('JPN', '列王纪上', 11, 14, 6, 'アヒヤは、戸口に入って来る彼女の足音を聞いて言った。「入りなさい、ヤロブアムの妻よ。なぜ、ほかの女のようなふりをしているのですか。私はあなたに厳しいことを伝えなければなりません。'),
('JPN', '列王纪上', 11, 14, 7, '行って、ヤロブアムに言いなさい。イスラエルの神、主はこう言われる。『わたしは民の中からあなたを高く上げ、わたしの民イスラエルを治める君主とし、'),
('JPN', '列王纪上', 11, 14, 8, 'ダビデの家から王国を引き裂いて、あなたに与えた。しかしあなたは、わたしのしもべダビデのようではなかった。ダビデはわたしの命令を守り、心を尽くしてわたしに従い、ただ、わたしの目にかなうことだけを行った。'),
('JPN', '列王纪上', 11, 14, 9, 'ところがあなたは、これまでのだれよりも悪いことをした。行って自分のためにほかの神々や鋳物の像を造り、わたしの怒りを引き起こし、わたしをあなたのうしろに捨て去った。'),
('JPN', '列王纪上', 11, 14, 10, 'だから、見よ、わたしはヤロブアムの家にわざわいをもたらす。イスラエルの中の、ヤロブアムに属する小童から奴隷や自由な者に至るまで絶ち滅ぼし、人が糞を残らず焼き去るように、ヤロブアムの家の跡を除き去る。'),
('JPN', '列王纪上', 11, 14, 11, 'ヤロブアムに属する者は、町で死ぬなら犬がこれを食らい、野で死ぬなら空の鳥がこれを食らう。』主が、こう言われたのです。'),
('JPN', '列王纪上', 11, 14, 12, 'さあ、家に帰りなさい。あなたの足が町に入るとき、その子は死にます。'),
('JPN', '列王纪上', 11, 14, 13, '全イスラエルがその子のために悼み悲しんで葬るでしょう。ヤロブアムの家の者で墓に葬られるのは、彼だけです。ヤロブアムの家の中で、彼だけに、イスラエルの神、主のみこころにかなうことがあったからです。'),
('JPN', '列王纪上', 11, 14, 14, '主はご自分のためにイスラエルの上に一人の王を起こされます。彼はその日、いや、今にもヤロブアムの家を絶ち滅ぼします。'),
('JPN', '列王纪上', 11, 14, 15, '主はイスラエルを打って、水に揺らぐ葦のようにし、彼らの先祖に与えられたこの良い地の面からイスラエルを引き抜き、あの大河の向こうに散らされるでしょう。彼らがアシェラ像を造って主の怒りを引き起こしたからです。'),
('JPN', '列王纪上', 11, 14, 16, 'ヤロブアムが自分で犯した罪と、彼がイスラエルに犯させた罪のゆえに、主はイスラエルを捨てられるのです。」'),
('JPN', '列王纪上', 11, 14, 17, 'ヤロブアムの妻は立ち去って、ティルツァに着いた。彼女が家の敷居をまたいだとき、その子は死んだ。'),
('JPN', '列王纪上', 11, 14, 18, '人々はその子を葬り、全イスラエルは彼のために悼み悲しんだ。主がそのしもべ、預言者アヒヤによって語られたことばのとおりであった。'),
('JPN', '列王纪上', 11, 14, 19, 'ヤロブアムについてのその他の事柄、彼がいかに戦い、いかに治めたかは、『イスラエルの王の歴代誌』にまさしく記されている。'),
('JPN', '列王纪上', 11, 14, 20, 'ヤロブアムが王であった期間は二十二年であった。彼は先祖とともに眠りにつき、その子ナダブが代わって王となった。'),
('JPN', '列王纪上', 11, 14, 21, 'ユダではソロモンの子レハブアムが王になっていた。レハブアムは四十一歳で王となり、主がご自分の名を置くためにイスラエルの全部族の中から選ばれた都、エルサレムで十七年間、王であった。彼の母の名はナアマといい、アンモン人であった。'),
('JPN', '列王纪上', 11, 14, 22, 'ユダの人々は主の目に悪であることを行い、彼らが犯した罪によって、その先祖たちが行ったすべてのこと以上に主のねたみを引き起こした。'),
('JPN', '列王纪上', 11, 14, 23, '彼らも、すべての高い丘の上や青々と茂るあらゆる木の下に、高き所や、石の柱や、アシェラ像を立てた。'),
('JPN', '列王纪上', 11, 14, 24, 'この国には神殿男娼もいた。彼らは、主がイスラエルの子らの前から追い払われた異邦の民の、すべての忌み嫌うべき慣わしをまねて行っていた。'),
('JPN', '列王纪上', 11, 14, 25, 'レハブアム王の第五年に、エジプトの王シシャクがエルサレムに攻め上って来て、'),
('JPN', '列王纪上', 11, 14, 26, '主の宮の財宝と王宮の財宝を奪い取った。彼は何もかも奪い取った。ソロモンが作った金の盾もすべて奪い取った。'),
('JPN', '列王纪上', 11, 14, 27, 'レハブアム王は、その代わりに青銅の盾を作り、これを王宮の門を守る近衛兵の隊長の手に託した。'),
('JPN', '列王纪上', 11, 14, 28, '王が主の宮に入るたびに、近衛兵がこれを運び、また近衛兵の控え室に戻した。'),
('JPN', '列王纪上', 11, 14, 29, 'レハブアムについてのその他の事柄、彼が行ったすべてのこと、それは『ユダの王の歴代誌』に確かに記されている。'),
('JPN', '列王纪上', 11, 14, 30, 'レハブアムとヤロブアムの間には、いつも戦いがあった。'),
('JPN', '列王纪上', 11, 14, 31, 'レハブアムは先祖とともに眠りにつき、先祖とともにダビデの町に葬られた。彼の母の名はナアマといい、アンモン人であった。彼の子アビヤムが代わって王となった。'),
('JPN', '列王纪上', 11, 15, 1, 'ネバテの子ヤロブアムの第十八年に、アビヤムがユダの王となり、'),
('JPN', '列王纪上', 11, 15, 2, 'エルサレムで三年間、王であった。彼の母の名はマアカといい、アブサロムの娘であった。'),
('JPN', '列王纪上', 11, 15, 3, '彼は、かつて自分の父が行ったあらゆる罪のうちを歩み、彼の心は父祖ダビデの心のように、彼の神、主と一つにはなっていなかった。'),
('JPN', '列王纪上', 11, 15, 4, 'しかし、ダビデに免じて、彼の神、主は、彼のためにエルサレムに一つのともしびを与えて、彼の跡を継ぐ子を起こし、エルサレムを堅く立てられた。'),
('JPN', '列王纪上', 11, 15, 5, 'それは、ダビデが主の目にかなうことを行い、ヒッタイト人ウリヤのことのほかは、一生の間、主が命じられたすべてのことからそれなかったからである。'),
('JPN', '列王纪上', 11, 15, 6, 'レハブアムとヤロブアムの間には、彼の一生の間、戦いがあった。'),
('JPN', '列王纪上', 11, 15, 7, 'アビヤムについてのその他の事柄、彼が行ったすべてのこと、それは『ユダの王の歴代誌』に確かに記されている。アビヤムとヤロブアムの間には戦いがあった。'),
('JPN', '列王纪上', 11, 15, 8, 'アビヤムは先祖とともに眠りにつき、人々は彼をダビデの町に葬った。彼の子アサが代わって王となった。'),
('JPN', '列王纪上', 11, 15, 9, 'イスラエルの王ヤロブアムの第二十年に、ユダの王アサが王となった。'),
('JPN', '列王纪上', 11, 15, 10, '彼はエルサレムで四十一年間、王であった。彼の母の名はマアカといい、アブサロムの娘であった。'),
('JPN', '列王纪上', 11, 15, 11, 'アサは父祖ダビデのように、主の目にかなうことを行った。'),
('JPN', '列王纪上', 11, 15, 12, '彼は神殿男娼を国から追放し、先祖たちが造った偶像をことごとく取り除いた。'),
('JPN', '列王纪上', 11, 15, 13, 'また、母マアカがアシェラのために憎むべき像を造ったので、彼女を皇太后の位から退けた。アサはその憎むべき像を切り倒し、これをキデロンの谷で焼いた。'),
('JPN', '列王纪上', 11, 15, 14, '高き所は取り除かれなかったが、アサの心は生涯、主とともにあり、全きものであった。'),
('JPN', '列王纪上', 11, 15, 15, '彼は、父が聖別した物と自分が聖別した物、銀、金、器を、主の宮に運び入れた。'),
('JPN', '列王纪上', 11, 15, 16, 'アサとイスラエルの王バアシャの間には、彼らが生きている間、戦いがあった。'),
('JPN', '列王纪上', 11, 15, 17, 'イスラエルの王バアシャはユダに上って来て、ラマを築き直し、ユダの王アサのもとにだれも出入りできないようにした。'),
('JPN', '列王纪上', 11, 15, 18, 'アサは、主の宮の宝物倉と王宮の宝物倉に残っていた銀と金をことごとく取って、自分の家来たちの手に渡した。アサ王は、彼らをダマスコに住んでいたアラムの王、ヘズヨンの子タブリンモンの子ベン・ハダドのもとに遣わして言った。'),
('JPN', '列王纪上', 11, 15, 19, '「私の父とあなたの父上の間にあったように、私とあなたの間にも盟約を結びましょう。ご覧ください。私はあなたに銀と金の贈り物をしました。どうか、イスラエルの王バアシャとの盟約を破棄して、彼が私のもとから離れ去るようにしてください。」'),
('JPN', '列王纪上', 11, 15, 20, 'ベン・ハダドはアサ王の願いを聞き入れ、自分の配下の軍の高官たちをイスラエルの町々に差し向け、イヨンと、ダンと、アベル・ベテ・マアカ、およびキネレテ全域とナフタリの全土を攻撃した。'),
('JPN', '列王纪上', 11, 15, 21, 'バアシャはこれを聞くと、ラマを築き直すのを中止して、ティルツァにとどまった。'),
('JPN', '列王纪上', 11, 15, 22, 'そこで、アサ王はユダ全土にもれなく布告し、バアシャが建築に用いたラマの石材と木材を運び出させた。アサ王は、これを用いてベニヤミンのゲバとミツパを建てた。'),
('JPN', '列王纪上', 11, 15, 23, 'アサのその他のすべての事柄、すべての功績、彼が行ったすべてのことや彼が建てた町々のこと、それは『ユダの王の歴代誌』に確かに記されている。ただ、彼は年をとってから、両足とも病気になった。'),
('JPN', '列王纪上', 11, 15, 24, 'アサは先祖とともに眠りにつき、先祖とともに父ダビデの町に葬られた。彼の子ヨシャファテが代わって王となった。'),
('JPN', '列王纪上', 11, 15, 25, 'ユダの王アサの第二年に、ヤロブアムの子ナダブがイスラエルの王となり、二年間イスラエルの王であった。'),
('JPN', '列王纪上', 11, 15, 26, '彼は主の目に悪であることを行い、彼の父の道に歩み、父がイスラエルに犯させた罪の道を歩んだ。'),
('JPN', '列王纪上', 11, 15, 27, 'イッサカルの家のアヒヤの子バアシャは、彼に謀反を企てた。バアシャはペリシテ人のギベトンで彼を討った。ナダブとイスラエル全軍はギベトンを攻め囲んでいたのである。'),
('JPN', '列王纪上', 11, 15, 28, 'こうして、バアシャはユダの王アサの第三年にナダブを殺し、彼に代わって王となった。'),
('JPN', '列王纪上', 11, 15, 29, '彼は王となったとき、ヤロブアムの全家を討ち、ヤロブアムに属する息ある者を一人も残さず、根絶やしにした。主がそのしもべ、シロ人アヒヤを通して言われたことばのとおりであった。'),
('JPN', '列王纪上', 11, 15, 30, 'これはヤロブアムが犯した罪のゆえ、またイスラエルに犯させた罪のゆえであり、彼が引き起こしたイスラエルの神、主の怒りによるものであった。'),
('JPN', '列王纪上', 11, 15, 31, 'ナダブについてのその他の事柄、彼が行ったすべてのこと、それは『イスラエルの王の歴代誌』に確かに記されている。'),
('JPN', '列王纪上', 11, 15, 32, 'アサとイスラエルの王バアシャの間には、彼らが生きている間、戦いがあった。'),
('JPN', '列王纪上', 11, 15, 33, 'ユダの王アサの第三年に、アヒヤの子バアシャがティルツァで全イスラエルの王となった。治世は二十四年であった。'),
('JPN', '列王纪上', 11, 15, 34, '彼は主の目に悪であることを行い、ヤロブアムの道に歩み、ヤロブアムがイスラエルに犯させた罪の道に歩んだ。'),
('JPN', '列王纪上', 11, 16, 1, 'そのとき、ハナニの子エフーに、バアシャに対する次のような主のことばがあった。'),
('JPN', '列王纪上', 11, 16, 2, '「わたしは、あなたをちりから引き上げ、わたしの民イスラエルの君主としたが、あなたはヤロブアムの道に歩み、わたしの民イスラエルに罪を犯させ、その罪によってわたしの怒りを引き起こした。'),
('JPN', '列王纪上', 11, 16, 3, '今、わたしはバアシャとその家を除き去り、あなたの家をネバテの子ヤロブアムの家のようにする。'),
('JPN', '列王纪上', 11, 16, 4, 'バアシャに属する者で、町で死ぬ者は犬がこれを食らい、野で死ぬ者は空の鳥がこれを食らう。」'),
('JPN', '列王纪上', 11, 16, 5, 'バアシャについてのその他の事柄、彼が行ったこと、その功績、それは『イスラエルの王の歴代誌』に確かに記されている。'),
('JPN', '列王纪上', 11, 16, 6, 'バアシャは先祖とともに眠りにつき、ティルツァに葬られた。彼の子エラが代わって王となった。'),
('JPN', '列王纪上', 11, 16, 7, '主のことばはまた、ハナニの子、預言者エフーを通してバアシャとその家に向けられた。それは、彼が主の目に悪であるすべてのことを行い、その手のわざによって主の怒りを引き起こしてヤロブアムの家のようになり、また彼がヤロブアムを打ち殺したからである。'),
('JPN', '列王纪上', 11, 16, 8, 'ユダの王アサの第二十六年に、バアシャの子エラがティルツァでイスラエルの王となった。治世は二年であった。'),
('JPN', '列王纪上', 11, 16, 9, '彼がティルツァにいて、ティルツァの宮廷長官アルツァの家で酒を飲んで酔っていたとき、彼の家来で、戦車隊の半分の長であるジムリが彼に謀反を企てた。'),
('JPN', '列王纪上', 11, 16, 10, 'ユダの王アサの第二十七年に、ジムリが入って来てエラを打ち殺し、彼に代わって王となった。'),
('JPN', '列王纪上', 11, 16, 11, 'ジムリは王となり王座に就くと、すぐにバアシャの全家を討ち、小童から親類、友人に至るまで、一人も残さなかった。'),
('JPN', '列王纪上', 11, 16, 12, 'こうして、ジムリはバアシャの全家を根絶やしにした。預言者エフーを通してバアシャに言われた主のことばのとおりであった。'),
('JPN', '列王纪上', 11, 16, 13, 'これは、バアシャのすべての罪とその子エラの罪のゆえであり、彼らが罪を犯し、また彼らがイスラエルに罪を犯させ、彼らの空しい神々によってイスラエルの神、主の怒りを引き起こしたためである。'),
('JPN', '列王纪上', 11, 16, 14, 'エラについてのその他の事柄、彼が行ったすべてのこと、それは『イスラエルの王の歴代誌』に確かに記されている。'),
('JPN', '列王纪上', 11, 16, 15, 'ユダの王アサの第二十七年に、ジムリが七日間ティルツァで王となった。そのとき、兵はペリシテ人のギベトンに対して陣を敷いていた。'),
('JPN', '列王纪上', 11, 16, 16, '陣を敷いていたこの兵は、「ジムリが謀反を起こして王を打ち殺した」と言われるのを聞いた。すると、全イスラエルはその日、その陣営で軍の長オムリをイスラエルの王とした。'),
('JPN', '列王纪上', 11, 16, 17, 'オムリは全イスラエルとともにギベトンから上って来て、ティルツァを包囲した。'),
('JPN', '列王纪上', 11, 16, 18, 'ジムリは町が攻め取られるのを見ると、王宮の高殿に入り、自ら王宮に火を放って死んだ。'),
('JPN', '列王纪上', 11, 16, 19, 'これは、彼が罪を犯して主の目に悪であることを行い、ヤロブアムの道に歩んだその罪のゆえであり、イスラエルに罪を犯させた彼の罪のゆえであった。'),
('JPN', '列王纪上', 11, 16, 20, 'ジムリについてのその他の事柄、彼が企てた謀反、それは『イスラエルの王の歴代誌』に確かに記されている。'),
('JPN', '列王纪上', 11, 16, 21, '当時、イスラエルの民は二派に分裂していた。民の半分はギナテの子ティブニに従って彼を王にしようとし、もう半分はオムリに従った。'),
('JPN', '列王纪上', 11, 16, 22, 'オムリに従った民は、ギナテの子ティブニに従った民より強かったので、ティブニが死ぬとオムリが王となった。'),
('JPN', '列王纪上', 11, 16, 23, 'ユダの王アサの第三十一年に、オムリはイスラエルの王となり、十二年間、王であった。六年間はティルツァで王であった。'),
('JPN', '列王纪上', 11, 16, 24, '彼は銀二タラントでシェメルからサマリアの山を買い、その山に町を建て、彼が建てたこの町の名を、その山の持ち主であったシェメルの名にちなんでサマリアと呼んだ。'),
('JPN', '列王纪上', 11, 16, 25, 'オムリは主の目に悪であることを行い、彼以前のだれよりも悪いことをした。'),
('JPN', '列王纪上', 11, 16, 26, '彼はネバテの子ヤロブアムのすべての道に歩み、イスラエルに罪を犯させ、彼らの空しい神々によってイスラエルの神、主の怒りを引き起こした。'),
('JPN', '列王纪上', 11, 16, 27, 'オムリが行ったその他の事柄、彼が立てた功績、それは『イスラエルの王の歴代誌』に確かに記されている。'),
('JPN', '列王纪上', 11, 16, 28, 'オムリは先祖とともに眠りにつき、サマリアに葬られた。彼の子アハブが代わって王となった。'),
('JPN', '列王纪上', 11, 16, 29, 'オムリの子アハブは、ユダの王アサの第三十八年に、イスラエルの王となった。オムリの子アハブはサマリアで二十二年間、イスラエルの王であった。'),
('JPN', '列王纪上', 11, 16, 30, 'オムリの子アハブは、彼以前のだれよりも主の目に悪であることを行った。'),
('JPN', '列王纪上', 11, 16, 31, '彼にとっては、ネバテの子ヤロブアムの罪のうちを歩むことは軽いことであった。それどころか彼は、シドン人の王エテバアルの娘イゼベルを妻とし、行ってバアルに仕え、それを拝んだ。'),
('JPN', '列王纪上', 11, 16, 32, 'さらに彼は、サマリアに建てたバアルの神殿に、バアルのために祭壇を築いた。'),
('JPN', '列王纪上', 11, 16, 33, 'アハブはアシェラ像も造った。こうしてアハブは、彼以前の、イスラエルのすべての王たちにもまして、ますますイスラエルの神、主の怒りを引き起こすようなことを行った。'),
('JPN', '列王纪上', 11, 16, 34, '彼の時代に、ベテル人ヒエルがエリコを再建した。彼は、その礎を据えたとき長子アビラムを失い、門を建てたとき末の子セグブを失った。ヌンの子ヨシュアを通して語られた主のことばのとおりであった。'),
('JPN', '列王纪上', 11, 17, 1, 'ギルアデの住民であるティシュベ人エリヤはアハブに言った。「私が仕えているイスラエルの神、主は生きておられる。私のことばによるのでなければ、ここ数年の間、露も降りず、雨も降らない。」'),
('JPN', '列王纪上', 11, 17, 2, 'それから、エリヤに次のような主のことばがあった。'),
('JPN', '列王纪上', 11, 17, 3, '「ここを去って東へ向かい、ヨルダン川の東にあるケリテ川のほとりに身を隠せ。'),
('JPN', '列王纪上', 11, 17, 4, 'あなたはその川の水を飲むことになる。わたしは烏に、そこであなたを養うように命じた。」'),
('JPN', '列王纪上', 11, 17, 5, 'そこでエリヤは行って、主のことばどおりにした。彼はヨルダン川の東にあるケリテ川のほとりに行って住んだ。'),
('JPN', '列王纪上', 11, 17, 6, '何羽かの烏が、朝、彼のところにパンと肉を、また夕方にパンと肉を運んで来た。彼はその川から水を飲んだ。'),
('JPN', '列王纪上', 11, 17, 7, 'しかし、しばらくすると、その川が涸れた。その地方に雨が降らなかったからである。'),
('JPN', '列王纪上', 11, 17, 8, 'すると、彼に次のような主のことばがあった。'),
('JPN', '列王纪上', 11, 17, 9, '「さあ、シドンのツァレファテに行き、そこに住め。見よ。わたしはそこの一人のやもめに命じて、あなたを養うようにしている。」'),
('JPN', '列王纪上', 11, 17, 10, '彼はツァレファテへ出て行った。その町の門に着くと、ちょうどそこに、薪を拾い集めている一人のやもめがいた。そこで、エリヤは彼女に声をかけて言った。「水差しにほんの少しの水を持って来て、私に飲ませてください。」'),
('JPN', '列王纪上', 11, 17, 11, '彼女が取りに行こうとすると、エリヤは彼女を呼んで言った。「一口のパンも持って来てください。」'),
('JPN', '列王纪上', 11, 17, 12, '彼女は答えた。「あなたの神、主は生きておられます。私には焼いたパンはありません。ただ、かめの中に一握りの粉と、壺の中にほんの少しの油があるだけです。ご覧のとおり、二、三本の薪を集め、帰って行って、私と息子のためにそれを調理し、それを食べて死のうとしているのです。」'),
('JPN', '列王纪上', 11, 17, 13, 'エリヤは彼女に言った。「恐れてはいけません。行って、あなたが言ったようにしなさい。しかし、まず私のためにそれで小さなパン菓子を作り、私のところに持って来なさい。その後で、あなたとあなたの子どものために作りなさい。'),
('JPN', '列王纪上', 11, 17, 14, 'イスラエルの神、主が、こう言われるからです。『主が地の上に雨を降らせる日まで、そのかめの粉は尽きず、その壺の油はなくならない。』」'),
('JPN', '列王纪上', 11, 17, 15, '彼女は行って、エリヤのことばのとおりにした。彼女と彼、および彼女の家族も、長い間それを食べた。'),
('JPN', '列王纪上', 11, 17, 16, 'エリヤを通して言われた主のことばのとおり、かめの粉は尽きず、壺の油はなくならなかった。'),
('JPN', '列王纪上', 11, 17, 17, 'これらのことの後、この家の女主人の息子が病気になった。その子の病気は非常に重くなり、ついに息を引き取った。'),
('JPN', '列王纪上', 11, 17, 18, '彼女はエリヤに言った。「神の人よ、あなたはいったい私に何をしようとされるのですか。あなたは私の咎を思い起こさせ、私の息子を死なせるために来られたのですか。」'),
('JPN', '列王纪上', 11, 17, 19, '彼は「あなたの息子を渡しなさい」と彼女に言って、その子を彼女の懐から受け取り、彼が泊まっていた屋上の部屋に抱えて上がり、その子を自分の寝床の上に寝かせた。'),
('JPN', '列王纪上', 11, 17, 20, '彼は主に叫んで祈った。「私の神、主よ。私が世話になっている、このやもめにさえもわざわいを下して、彼女の息子を死なせるのですか。」'),
('JPN', '列王纪上', 11, 17, 21, 'そして、彼は三度その子の上に身を伏せて、主に叫んで祈った。「私の神、主よ。どうか、この子のいのちをこの子のうちに戻してください。」'),
('JPN', '列王纪上', 11, 17, 22, '主はエリヤの願いを聞かれたので、子どものいのちがその子のうちに戻り、その子は生き返った。'),
('JPN', '列王纪上', 11, 17, 23, 'エリヤはその子を抱いて、屋上の部屋から家の中に下りて、その子の母親に渡した。エリヤは言った。「ご覧なさい。あなたの息子は生きています。」'),
('JPN', '列王纪上', 11, 17, 24, 'その女はエリヤに言った。「今、私はあなたが神の人であり、あなたの口にある主のことばが真実であることを知りました。」'),
('JPN', '列王纪上', 11, 18, 1, 'かなりの日数を経て、三年目に、次のような主のことばがエリヤにあった。「アハブに会いに行け。わたしはこの地の上に雨を降らせよう。」'),
('JPN', '列王纪上', 11, 18, 2, 'そこで、エリヤはアハブに会いに出かけた。そのころ、サマリアでは飢饉がひどかった。'),
('JPN', '列王纪上', 11, 18, 3, 'アハブは宮廷長官オバデヤを呼び寄せた。オバデヤは主を深く恐れていた。'),
('JPN', '列王纪上', 11, 18, 4, 'かつてイゼベルが主の預言者たちを殺したときに、オバデヤは百人の預言者たちを救い出し、五十人ずつ洞穴の中にかくまい、パンと水で彼らを養ったのである。'),
('JPN', '列王纪上', 11, 18, 5, 'アハブはオバデヤに言った。「国内のすべての水の泉や、すべての川に行ってみよ。馬とらばを生かしておく草が見つかり、家畜を絶やさないですむかもしれない。」'),
('JPN', '列王纪上', 11, 18, 6, '二人はこの国を分けて巡り歩くことにし、アハブは一人で一つの道を行き、オバデヤは一人で別の道を行った。'),
('JPN', '列王纪上', 11, 18, 7, 'オバデヤがその道にいたところ、エリヤが彼に会いに来た。オバデヤにはそれがエリヤだと分かったので、ひれ伏して言った。「あなたは私の主人エリヤではありませんか。」'),
('JPN', '列王纪上', 11, 18, 8, 'エリヤは彼に答えた。「そうです。行って、エリヤがここにいると、あなたの主人に言いなさい。」'),
('JPN', '列王纪上', 11, 18, 9, 'すると、オバデヤは言った。「私にどんな罪があると言うのですか。あなたがこのしもべをアハブの手に渡し、殺そうとされるとは。'),
('JPN', '列王纪上', 11, 18, 10, 'あなたの神、主は生きておられます。私の主人があなたを捜すために人を遣わさなかった民や王国は一つもありません。その王国や民が、あなたはいないと言うと、主人は彼らに、あなたが見つからないという誓いをさせています。'),
('JPN', '列王纪上', 11, 18, 11, '今、あなたは『行って、エリヤがここにいるとあなたの主人に言え』と言われます。'),
('JPN', '列王纪上', 11, 18, 12, '私があなたから離れて行っている間に、主の霊はあなたを私の知らないところに連れて行くでしょう。私はアハブに知らせに行きますが、あなたを見つけられなければ、彼は私を殺すでしょう。しもべは子どものころから主を恐れています。'),
('JPN', '列王纪上', 11, 18, 13, 'あなたには、イゼベルが主の預言者たちを殺したとき、私のしたことが知らされていないのですか。私は主の預言者百人を五十人ずつ洞穴に隠し、パンと水で彼らを養ったのです。'),
('JPN', '列王纪上', 11, 18, 14, '今、あなたは『行って、エリヤがここにいるとあなたの主人に言え』と言われます。彼は私を殺すでしょう。」'),
('JPN', '列王纪上', 11, 18, 15, 'すると、エリヤは言った。「私が仕えている万軍の主は生きておられます。私は必ず、今日、アハブの前に出ます。」'),
('JPN', '列王纪上', 11, 18, 16, 'オバデヤは行ってアハブに会い、彼に告げたので、アハブはエリヤに会うためにやって来た。'),
('JPN', '列王纪上', 11, 18, 17, 'アハブがエリヤを見るやいなや、アハブは彼に言った。「おまえか、イスラエルにわざわいをもたらす者は。」'),
('JPN', '列王纪上', 11, 18, 18, 'エリヤは言った。「私はイスラエルにわざわいをもたらしてはいない。あなたとあなたの父の家こそ、そうだ。現に、あなたがたは主の命令を捨て、あなたはバアルの神々に従っている。'),
('JPN', '列王纪上', 11, 18, 19, '今、人を遣わして、カルメル山の私のところに、全イスラエル、ならびにイゼベルの食卓に着く、四百五十人のバアルの預言者と四百人のアシェラの預言者を集めなさい。」'),
('JPN', '列王纪上', 11, 18, 20, 'そこで、アハブはイスラエルのすべての人々に使者を遣わして、預言者たちをカルメル山に集めた。'),
('JPN', '列王纪上', 11, 18, 21, 'エリヤは皆の前に進み出て言った。「おまえたちは、いつまで、どっちつかずによろめいているのか。もし主が神であれば、主に従い、もしバアルが神であれば、バアルに従え。」しかし、民は一言も彼に答えなかった。'),
('JPN', '列王纪上', 11, 18, 22, 'そこで、エリヤは民に向かって言った。「私一人が主の預言者として残っている。バアルの預言者は四百五十人だ。'),
('JPN', '列王纪上', 11, 18, 23, '私たちのために、彼らに二頭の雄牛を用意させよ。彼らに、自分たちで一頭の雄牛を選び、それを切り裂いて薪の上に載せるようにさせよ。火をつけてはならない。私は、もう一頭の雄牛を同じようにし、薪の上に載せて、火をつけずにおく。'),
('JPN', '列王纪上', 11, 18, 24, 'おまえたちは自分たちの神の名を呼べ。私は主の名を呼ぶ。そのとき、火をもって答える神、その方が神である。」民はみな答えて、「それがよい」と言った。'),
('JPN', '列王纪上', 11, 18, 25, 'エリヤはバアルの預言者たちに言った。「おまえたちで一頭の雄牛を選び、おまえたちのほうから、まず始めよ。人数が多いのだから。おまえたちの神の名を呼べ。ただし、火をつけてはならない。」'),
('JPN', '列王纪上', 11, 18, 26, 'そこで彼らは、与えられた雄牛を取って、それを整え、朝から真昼までバアルの名を呼んだ。「バアルよ、私たちに答えてください。」しかし何の声もなく、答える者もなかった。そこで彼らは、自分たちが造った祭壇のあたりで踊り回った。'),
('JPN', '列王纪上', 11, 18, 27, '真昼になると、エリヤは彼らを嘲って言った。「もっと大声で呼んでみよ。彼は神なのだから。きっと何かに没頭しているか、席を外しているか、旅に出ているのだろう。もしかすると寝ているのかもしれないから、起こしたらよいだろう。」'),
('JPN', '列王纪上', 11, 18, 28, '彼らはますます大声で叫び、彼らの慣わしによって、剣や槍で、血を流すまで自分たちの身を傷つけた。'),
('JPN', '列王纪上', 11, 18, 29, 'このようにして、昼も過ぎ、ささげ物を献げる時まで騒ぎ立てたが、何の声もなく、答える者もなく、注目する者もなかった。'),
('JPN', '列王纪上', 11, 18, 30, 'エリヤが民全体に「私のそばに近寄りなさい」と言ったので、民はみな彼に近寄って来た。彼は、壊れていた主の祭壇を築き直した。'),
('JPN', '列王纪上', 11, 18, 31, 'エリヤは、主がかつて「あなたの名はイスラエルとなる」と言われたヤコブの子たちの部族の数にしたがって、十二の石を取った。'),
('JPN', '列王纪上', 11, 18, 32, 'その石で、彼は主の御名によって一つの祭壇を築き、その祭壇の周りに、二セアの種が入るほどの溝を掘った。'),
('JPN', '列王纪上', 11, 18, 33, 'それから彼は薪を並べ、一頭の雄牛を切り裂いて薪の上に載せ、'),
('JPN', '列王纪上', 11, 18, 34, '「四つのかめに水を満たし、この全焼のささげ物と薪の上に注げ」と命じた。それから「もう一度それをせよ」と言ったので、彼らはもう一度そうした。さらに、彼が「三度目をせよ」と言ったので、彼らは三度目をした。'),
('JPN', '列王纪上', 11, 18, 35, '水は祭壇の周りに流れ出した。彼は溝にも水を満たした。'),
('JPN', '列王纪上', 11, 18, 36, 'ささげ物を献げるころになると、預言者エリヤは進み出て言った。「アブラハム、イサク、イスラエルの神、主よ。あなたがイスラエルにおいて神であり、私があなたのしもべであり、あなたのおことばによって私がこれらすべてのことを行ったということが、今日、明らかになりますように。'),
('JPN', '列王纪上', 11, 18, 37, '私に答えてください。主よ、私に答えてください。そうすればこの民は、主よ、あなたこそ神であり、あなたが彼らの心を翻してくださったことを知るでしょう。」'),
('JPN', '列王纪上', 11, 18, 38, 'すると、主の火が降り、全焼のささげ物と薪と石と土を焼き尽くし、溝の水もなめ尽くした。'),
('JPN', '列王纪上', 11, 18, 39, '民はみな、これを見てひれ伏し、「主こそ神です。主こそ神です」と言った。'),
('JPN', '列王纪上', 11, 18, 40, 'そこでエリヤは彼らに命じた。「バアルの預言者たちを捕らえよ。一人も逃すな。」彼らがバアルの預言者たちを捕らえると、エリヤは彼らをキション川に連れて下り、そこで彼らを殺した。'),
('JPN', '列王纪上', 11, 18, 41, 'エリヤはアハブに言った。「上って行って、食べたり飲んだりしなさい。激しい大雨の音がするから。」'),
('JPN', '列王纪上', 11, 18, 42, 'そこで、アハブは食べたり飲んだりするために上って行った。エリヤはカルメル山の頂上に登り、地にひざまずいて自分の顔を膝の間にうずめた。'),
('JPN', '列王纪上', 11, 18, 43, '彼は若い者に言った。「さあ、上って行って、海の方をよく見なさい。」若い者は上って、見たが、「何もありません」と言った。するとエリヤは「もう一度、上りなさい」と言って、それを七回繰り返した。'),
('JPN', '列王纪上', 11, 18, 44, '七回目に若い者は、「ご覧ください。人の手のひらほどの小さな濃い雲が海から上っています」と言った。エリヤは言った。「上って行って、アハブに言いなさい。『大雨に閉じ込められないうちに、車を整えて下って行きなさい。』」'),
('JPN', '列王纪上', 11, 18, 45, 'しばらくすると、空は濃い雲と風で暗くなり、やがて激しい大雨となった。アハブは車に乗って、イズレエルへ行った。'),
('JPN', '列王纪上', 11, 18, 46, '主の手がエリヤの上に下ったので、彼は裾をたくし上げて、イズレエルの入り口までアハブの前を走って行った。'),
('JPN', '列王纪上', 11, 19, 1, 'アハブは、エリヤがしたことと、預言者たちを剣で皆殺しにしたこととの一部始終をイゼベルに告げた。'),
('JPN', '列王纪上', 11, 19, 2, 'すると、イゼベルは使者をエリヤのところに遣わして言った。「もし私が、明日の今ごろまでに、おまえのいのちをあの者たちの一人のいのちのようにしなかったなら、神々がこの私を幾重にも罰せられるように。」'),
('JPN', '列王纪上', 11, 19, 3, '彼はそれを知って立ち、自分のいのちを救うため立ち去った。ユダのベエル・シェバに来たとき、若い者をそこに残し、'),
('JPN', '列王纪上', 11, 19, 4, '自分は荒野に、一日の道のりを入って行った。彼は、エニシダの木の陰に座り、自分の死を願って言った。「主よ、もう十分です。私のいのちを取ってください。私は父祖たちにまさっていませんから。」'),
('JPN', '列王纪上', 11, 19, 5, '彼がエニシダの木の下で横になって眠っていると、見よ、一人の御使いが彼に触れ、「起きて食べなさい」と言った。'),
('JPN', '列王纪上', 11, 19, 6, '彼が見ると、見よ、彼の頭のところに、焼け石で焼いたパン菓子一つと、水の入った壺があった。彼はそれを食べて飲み、再び横になった。'),
('JPN', '列王纪上', 11, 19, 7, '主の使いがもう一度戻って来て彼に触れ、「起きて食べなさい。旅の道のりはまだ長いのだから」と言った。'),
('JPN', '列王纪上', 11, 19, 8, '彼は起きて食べ、そして飲んだ。そしてこの食べ物に力を得て、四十日四十夜歩いて、神の山ホレブに着いた。'),
('JPN', '列王纪上', 11, 19, 9, '彼はそこにある洞穴に入り、そこで一夜を過ごした。すると、主のことばが彼にあった。主は「エリヤよ、ここで何をしているのか」と言われた。'),
('JPN', '列王纪上', 11, 19, 10, 'エリヤは答えた。「私は万軍の神、主に熱心に仕えました。しかし、イスラエルの子らはあなたとの契約を捨て、あなたの祭壇を壊し、あなたの預言者たちを剣で殺しました。ただ私だけが残りましたが、彼らは私のいのちを取ろうと狙っています。」'),
('JPN', '列王纪上', 11, 19, 11, '主は言われた。「外に出て、山の上で主の前に立て。」するとそのとき、主が通り過ぎた。主の前で激しい大風が山々を裂き、岩々を砕いた。しかし、風の中に主はおられなかった。風の後に地震が起こったが、地震の中にも主はおられなかった。'),
('JPN', '列王纪上', 11, 19, 12, '地震の後に火があったが、火の中にも主はおられなかった。しかし火の後に、かすかな細い声があった。'),
('JPN', '列王纪上', 11, 19, 13, 'エリヤはこれを聞くと、すぐに外套で顔をおおい、外に出て洞穴の入り口に立った。すると声がして、こう言った。「エリヤよ、ここで何をしているのか。」'),
('JPN', '列王纪上', 11, 19, 14, 'エリヤは答えた。「私は万軍の神、主に熱心に仕えました。しかし、イスラエルの子らはあなたとの契約を捨て、あなたの祭壇を壊し、あなたの預言者たちを剣で殺しました。ただ私だけが残りましたが、彼らは私のいのちを取ろうと狙っています。」'),
('JPN', '列王纪上', 11, 19, 15, '主は彼に言われた。「さあ、ダマスコの荒野へ帰って行け。そこに行き、ハザエルに油を注いで、アラムの王とせよ。'),
('JPN', '列王纪上', 11, 19, 16, 'また、ニムシの子エフーに油を注いで、イスラエルの王とせよ。また、アベル・メホラ出身のシャファテの子エリシャに油を注いで、あなたに代わる預言者とせよ。'),
('JPN', '列王纪上', 11, 19, 17, 'ハザエルの剣を逃れる者をエフーが殺し、エフーの剣を逃れる者をエリシャが殺す。'),
('JPN', '列王纪上', 11, 19, 18, 'しかし、わたしはイスラエルの中に七千人を残している。これらの者はみな、バアルに膝をかがめず、バアルに口づけしなかった者たちである。」'),
('JPN', '列王纪上', 11, 19, 19, 'エリヤはそこを去って、シャファテの子エリシャを見つけた。エリシャは、十二くびきの牛を先に立て、その十二番目のくびきのそばで耕していた。エリヤが彼のところを通り過ぎるとき自分の外套を彼に掛けたので、'),
('JPN', '列王纪上', 11, 19, 20, 'エリシャは牛を放って、エリヤの後を追いかけて言った。「私の父と母に口づけさせてください。それから、あなたに従って行きますから。」エリヤは彼に言った。「行って来なさい。私があなたに何をしたか。」'),
('JPN', '列王纪上', 11, 19, 21, 'エリシャは引き返して、一くびきの牛を取り、それを殺して、牛の用具でその肉を調理し、人々に与えてそれを食べさせた。それから彼は立ってエリヤについて行き、彼に仕えた。'),
('JPN', '列王纪上', 11, 20, 1, 'アラムの王ベン・ハダドは彼の全軍勢を集めた。彼には三十二人の王と、馬と戦車があった。彼はサマリアに上り、これを包囲して攻め、'),
('JPN', '列王纪上', 11, 20, 2, '町に使者たちを遣わして、イスラエルの王アハブに'),
('JPN', '列王纪上', 11, 20, 3, 'こう言った。「ベン・ハダドはこう言われる。『おまえの銀と金は私のもの。おまえの妻たちや子どもたちの、最も美しい者も私のものだ。』」'),
('JPN', '列王纪上', 11, 20, 4, 'イスラエルの王は答えた。「王よ、仰せのとおりです。この私、および、私に属するものはすべてあなたのものです。」'),
('JPN', '列王纪上', 11, 20, 5, '使者たちは再び戻って来て言った。「ベン・ハダドはこう言われる。『私はおまえに人を遣わし、おまえの銀と金、および、おまえの妻たちや子どもたちを私に与えよ、と言った。'),
('JPN', '列王纪上', 11, 20, 6, '明日の今ごろ、私の家来たちを遣わす。彼らは、おまえの家とおまえの家来たちの家の中を探し、たとえ、おまえが一番大事にしているものさえ、手をかけて奪い取るだろう。』」'),
('JPN', '列王纪上', 11, 20, 7, 'イスラエルの王は国のすべての長老たちを呼び寄せて言った。「あの男が、こんなにひどいことを要求しているのを知ってほしい。彼は人を遣わして、私の妻たちや子どもたち、および、私の銀や金を求めたが、私はそれを断りきれなかった。」'),
('JPN', '列王纪上', 11, 20, 8, 'すると長老たちや民はみな、彼に言った。「聞かないでください。承諾しないでください。」'),
('JPN', '列王纪上', 11, 20, 9, 'そこで、彼はベン・ハダドの使者たちに言った。「王に言ってくれ。『初めにあなたがこのしもべにお求めになったことは、すべてそのようにいたしますが、このたびのことはできません。』」使者たちは帰って行って、このことを報告した。'),
('JPN', '列王纪上', 11, 20, 10, 'するとベン・ハダドは、彼のところに人を遣わして言った。「サマリアのちりが私に従うすべての民の手を満たすほどでもあったら、神々がこの私を幾重にも罰せられるように。」'),
('JPN', '列王纪上', 11, 20, 11, 'イスラエルの王は答えた。「こう伝えてくれ。『武装しようとする者は、武装を解く者のように誇ってはならない。』」'),
('JPN', '列王纪上', 11, 20, 12, 'ベン・ハダドは、このことばを聞いたとき、王たちと仮小屋で酒を飲んでいたが、家来たちに「配置につけ」と命じたので、彼らはこの町に向かう配置についた。'),
('JPN', '列王纪上', 11, 20, 13, 'ちょうどそのころ、一人の預言者がイスラエルの王アハブに近づいて言った。「主はこう言われる。『あなたは、この大いなる軍勢を見たか。見よ、わたしは今日、これをあなたの手に引き渡す。こうしてあなたは、わたしこそ主であることを知る。』」'),
('JPN', '列王纪上', 11, 20, 14, 'アハブが「それは、だれによってでしょうか」と尋ねると、その預言者は言った。「主はこう言われる。『諸州の首長に属する若い者たちによって。』」アハブが「だれが戦いを仕掛けるのでしょうか」と尋ねると、「あなたです」と答えた。'),
('JPN', '列王纪上', 11, 20, 15, '彼が諸州の首長に属する若い者たちを調べてみると、二百三十二人いた。そのほか、すべての兵、すべてのイスラエル人を調べたところ、七千人いた。'),
('JPN', '列王纪上', 11, 20, 16, '彼らは真昼ごろ出陣した。そのとき、ベン・ハダドは味方の三十二人の王と仮小屋で酒を飲んで酔っていた。'),
('JPN', '列王纪上', 11, 20, 17, '諸州の首長に属する若い者たちが最初に出陣した。ベン・ハダドが人を遣わすと、彼は「人々がサマリアから出て来ています」との報告を受けた。'),
('JPN', '列王纪上', 11, 20, 18, '彼は言った。「和平のために出て来ても生け捕りにし、戦うために出て来ても生け捕りにせよ。」'),
('JPN', '列王纪上', 11, 20, 19, '町から出て来たのは、諸州の首長に属する若い者たちと、これに続く軍勢であった。'),
('JPN', '列王纪上', 11, 20, 20, '彼らはそれぞれ相手に打ち勝ったので、アラム人は逃げ、イスラエル人は追った。アラムの王ベン・ハダドは馬に乗り、騎兵たちと一緒に逃れた。'),
('JPN', '列王纪上', 11, 20, 21, 'イスラエルの王も出陣し、馬と戦車を討ち、アラム人を討って大損害を与えた。'),
('JPN', '列王纪上', 11, 20, 22, 'その後、あの預言者がイスラエルの王に近寄って言った。「さあ、奮い立って、これからなすべきことをよく考えなさい。来年の今ごろ、アラムの王があなたを攻めに上って来るからです。」'),
('JPN', '列王纪上', 11, 20, 23, 'そのころ、アラムの王の家来たちは王に言った。「彼らの神々は山の神です。だから、彼らは私たちより強いのです。しかし、私たちが平地で彼らと戦うなら、きっと私たちのほうが彼らより強いでしょう。'),
('JPN', '列王纪上', 11, 20, 24, 'このようにしてください。王たちをそれぞれ、その地位から退かせ、王たちの代わりに総督を任命し、'),
('JPN', '列王纪上', 11, 20, 25, 'あなたは失っただけの軍勢と馬と戦車を補充してください。彼らと平地で戦うなら、きっと私たちのほうが彼らより強いでしょう。」王は彼らの言うことを聞き入れて、そのようにした。'),
('JPN', '列王纪上', 11, 20, 26, '年が改まると、ベン・ハダドはアラム人を召集し、イスラエルと戦うためにアフェクに上って来た。'),
('JPN', '列王纪上', 11, 20, 27, '一方、イスラエル人も召集され、食糧を受けて、彼らを迎え撃つために出て行った。イスラエル人は彼らと向かい合って、二つの小さなやぎの群れのように陣を敷いたが、アラム人はその地に満ちていた。'),
('JPN', '列王纪上', 11, 20, 28, 'ときに、一人の神の人が近づいて来て、イスラエルの王に言った。「主はこう言われる。『アラム人が、主は山の神であって低地の神ではない、と言っているので、わたしはこの大いなる軍勢をすべてあなたの手に渡す。そうしてあなたがたは、わたしこそ主であることを知る。』」'),
('JPN', '列王纪上', 11, 20, 29, '両軍は互いに向かい合って、七日間、陣を敷いていた。七日目になって戦いに臨んだが、イスラエル人は一日のうちにアラムの歩兵十万人を打ち殺した。'),
('JPN', '列王纪上', 11, 20, 30, '生き残った者たちはアフェクの町に逃げたが、その生き残った二万七千人の上に城壁が崩れ落ちた。ベン・ハダドは逃げて町に入り、奥の間に入った。'),
('JPN', '列王纪上', 11, 20, 31, '家来たちは彼に言った。「イスラエルの家の王たちは恵み深い王である、と聞いています。それで、私たちの腰に粗布をまとい、首に縄をかけ、イスラエルの王のもとに出て行かせてください。そうすれば、あなたのいのちを助けてくれるかもしれません。」'),
('JPN', '列王纪上', 11, 20, 32, 'こうして彼らは腰に粗布をまとい、首に縄をかけ、イスラエルの王のもとに行って願った。「あなたのしもべ、ベン・ハダドが『どうか私のいのちを助けてください』と申しています。」するとアハブは言った。「彼はまだ生きているのか。彼は私の兄弟だ。」'),
('JPN', '列王纪上', 11, 20, 33, 'この人々は、これは吉兆だと見て、すぐにそのことばにより事が決まったと思い、「ベン・ハダドはあなたの兄弟です」と言った。王は言った。「行って、彼を連れて来なさい。」ベン・ハダドが王のところに出て来ると、王は彼を戦車に乗せた。'),
('JPN', '列王纪上', 11, 20, 34, 'ベン・ハダドは彼に言った。「私の父が、あなたの父上から奪い取った町々をお返しします。あなたは私の父がサマリアにしたように、ダマスコに市場を設けることもできます。」「では、契約を結んで、あなたを帰そう。」こうして、アハブは彼と契約を結び、彼を去らせた。'),
('JPN', '列王纪上', 11, 20, 35, '預言者の仲間の一人が、主のことばにしたがって、自分の仲間に「私を打ってくれ」と言った。しかし、その人は彼を打つことを拒んだ。'),
('JPN', '列王纪上', 11, 20, 36, 'そこで彼はその人に言った。「あなたは主の御声に聞き従わなかったので、あなたが私のところから出て行くと、すぐ獅子があなたを殺す。」その人が彼のそばから立ち去ると、獅子がその人を見つけて殺した。'),
('JPN', '列王纪上', 11, 20, 37, '彼はもう一人の人に会ったので、「私を打ってくれ」と頼んだ。すると、その人は彼を打って傷を負わせた。'),
('JPN', '列王纪上', 11, 20, 38, 'それから、その預言者は行って、道端で王を待っていた。彼は目の上に包帯をして、だれだか分からないようにしていた。'),
('JPN', '列王纪上', 11, 20, 39, '王が通りかかったとき、彼は王に叫んで言った。「しもべが戦場に出て行くと、ちょうどそこに、ある人が一人の者を連れてやって来て、こう言いました。『この者を見張れ。もし、この者を逃がしでもしたら、この者のいのちの代わりにおまえのいのちを取るか、または、銀一タラントを払わせるぞ。』'),
('JPN', '列王纪上', 11, 20, 40, 'ところが、しもべがあれやこれやしているうちに、その人はいなくなってしまいました。」すると、イスラエルの王は彼に言った。「おまえは、そのとおりにさばかれる。おまえ自身が決めたとおりに。」'),
('JPN', '列王纪上', 11, 20, 41, '彼は急いで目から包帯を取った。そのとき、イスラエルの王は彼が預言者の一人であることに気づいた。'),
('JPN', '列王纪上', 11, 20, 42, '彼は王に言った。「主はこう言われる。『わたしが聖絶しようとした者をあなたが逃がしたので、あなたのいのちは彼のいのちの代わりとなり、あなたの民は彼の民の代わりとなる。』」'),
('JPN', '列王纪上', 11, 20, 43, 'イスラエルの王は不機嫌になり、激しく怒って自分の宮殿に戻って行き、サマリアに着いた。'),
('JPN', '列王纪上', 11, 21, 1, 'これらのことがあった後のことである。イズレエル人ナボテはイズレエルにぶどう畑を持っていた。それはサマリアの王アハブの宮殿のそばにあった。'),
('JPN', '列王纪上', 11, 21, 2, 'アハブはナボテに次のように頼んだ。「おまえのぶどう畑を私に譲ってもらいたい。あれは私の宮殿のすぐ隣にあるので、私の野菜畑にしたいのだが。その代わりに、あれよりもっと良いぶどう畑を与えよう。もしおまえが良いと思うなら、それ相当の代価を銀で支払おう。」'),
('JPN', '列王纪上', 11, 21, 3, 'ナボテはアハブに言った。「私の先祖のゆずりの地をあなたに譲るなど、主にかけてあり得ないことです。」'),
('JPN', '列王纪上', 11, 21, 4, 'アハブは不機嫌になり、激しく怒って自分の宮殿に入った。イズレエル人ナボテが彼に「私の先祖のゆずりの地はあなたに譲れません」と言ったからである。アハブは寝台に横になり、顔を背けて食事もしようとしなかった。'),
('JPN', '列王纪上', 11, 21, 5, '彼の妻イゼベルは彼のもとに来て言った。「どうしてそんなに不機嫌で、食事もなさらないのですか。」'),
('JPN', '列王纪上', 11, 21, 6, 'そこで、アハブは彼女に言った。「私がイズレエル人ナボテに『金を払うから、おまえのぶどう畑を譲ってほしい。あるいは、おまえが望むなら、代わりのぶどう畑をやってもよい』と言ったのに、彼は『私のぶどう畑はあなたに譲れません』と答えたからだ。」'),
('JPN', '列王纪上', 11, 21, 7, '妻イゼベルは彼に言った。「今、あなたはイスラエルの王権を得ています。さあ、起きて食事をし、元気を出してください。この私がイズレエル人ナボテのぶどう畑を、あなたのために手に入れてあげましょう。」'),
('JPN', '列王纪上', 11, 21, 8, '彼女はアハブの名で手紙を書き、彼の印で封印し、ナボテの町に住む長老たちとおもだった人々にその手紙を送った。'),
('JPN', '列王纪上', 11, 21, 9, '彼女は手紙にこう書いた。「断食を布告し、ナボテを民の前に引き出して座らせ、'),
('JPN', '列王纪上', 11, 21, 10, '彼の前に二人のよこしまな者を座らせて、彼らに『おまえは神と王を呪った』と証言させなさい。そして、彼を外に引き出し、石打ちにして殺しなさい。」'),
('JPN', '列王纪上', 11, 21, 11, 'そこで、その町の人々、その町に住んでいる長老たちとおもだった人々は、イゼベルが彼らに言ってよこしたとおり、彼女が手紙に書き送ったとおりに行った。'),
('JPN', '列王纪上', 11, 21, 12, '彼らは断食を布告し、ナボテを民の前に引き出して座らせた。'),
('JPN', '列王纪上', 11, 21, 13, 'そこに、二人のよこしまな者が入って来て、彼の前に座った。よこしまな者たちは民の前で、「ナボテは神と王を呪った」と証言した。そこで人々は彼を町の外に引き出し、石打ちにして殺した。'),
('JPN', '列王纪上', 11, 21, 14, 'こうして、彼らはイゼベルに「ナボテは石打ちにされて死にました」と言ってよこした。'),
('JPN', '列王纪上', 11, 21, 15, 'イゼベルはナボテが石打ちにされて殺されたことを聞くとすぐ、アハブに言った。「起きて、イズレエル人ナボテが代金と引き替えで譲ることを拒んだ、あのぶどう畑を取り上げなさい。もうナボテは生きていません。死んだのです。」'),
('JPN', '列王纪上', 11, 21, 16, 'アハブはナボテが死んだと聞いてすぐ、立って、イズレエル人ナボテのぶどう畑を取り上げようと下って行った。'),
('JPN', '列王纪上', 11, 21, 17, 'そのとき、ティシュベ人エリヤに次のような主のことばがあった。'),
('JPN', '列王纪上', 11, 21, 18, '「さあ、サマリアにいるイスラエルの王アハブに会いに下って行け。今、彼はナボテのぶどう畑を取り上げようと、そこに下って来ている。'),
('JPN', '列王纪上', 11, 21, 19, '彼にこう言え。『主はこう言われる。あなたは人殺しをしたうえに、奪い取ったのか。』また、彼に言え。『主はこう言われる。犬たちがナボテの血をなめた、その場所で、その犬たちがあなたの血をなめる。』」'),
('JPN', '列王纪上', 11, 21, 20, 'アハブがエリヤに「おまえは私を見つけたのか、わが敵よ」と言うと、エリヤは答えた。「そうだ。あなたが主の目に悪であることを行うことに身を任せたので、見つけたのだ。'),
('JPN', '列王纪上', 11, 21, 21, '『今わたしは、あなたにわざわいをもたらす。わたしはあなたの子孫を除き去り、イスラエルの中の、アハブに属する小童から奴隷や自由の者に至るまで絶ち滅ぼし、'),
('JPN', '列王纪上', 11, 21, 22, 'あなたの家をネバテの子ヤロブアムの家のようにし、アヒヤの子バアシャの家のようにする。それは、あなたが引き起こしたわたしの怒りのゆえであり、あなたがイスラエルに罪を犯させたためだ。』'),
('JPN', '列王纪上', 11, 21, 23, 'また、イゼベルについても主はこう言われる。『犬がイズレエルの領地でイゼベルを食らう。'),
('JPN', '列王纪上', 11, 21, 24, 'アハブに属する者で、町で死ぬ者は犬がこれを食らい、野で死ぬ者は空の鳥がこれを食らう。』」'),
('JPN', '列王纪上', 11, 21, 25, 'アハブのように、自らを裏切って主の目に悪であることを行った者は、だれもいなかった。彼の妻イゼベルが彼をそそのかしたのである。'),
('JPN', '列王纪上', 11, 21, 26, '彼は、主がイスラエル人の前から追い払われたアモリ人がしたのと全く同じように、偶像につき従い、非常に忌まわしいことを行った。'),
('JPN', '列王纪上', 11, 21, 27, 'アハブはこれらのことばを聞くとすぐ、自分の外套を裂き、身に粗布をまとって断食をした。彼は粗布をまとって伏し、打ちひしがれて歩いた。'),
('JPN', '列王纪上', 11, 21, 28, 'そのとき、ティシュベ人エリヤに次のような主のことばがあった。'),
('JPN', '列王纪上', 11, 21, 29, '「あなたは、アハブがわたしの前にへりくだっているのを見たか。彼がわたしの前にへりくだっているので、彼の生きている間はわざわいを下さない。しかし、彼の子の時代に、彼の家にわざわいを下す。」'),
('JPN', '列王纪上', 11, 22, 1, 'アラムとイスラエルの間に戦いがないまま、三年が過ぎた。'),
('JPN', '列王纪上', 11, 22, 2, 'しかし、三年目になって、ユダの王ヨシャファテがイスラエルの王のところに下って来ると、'),
('JPN', '列王纪上', 11, 22, 3, 'イスラエルの王は自分の家来たちに言った。「おまえたちは、ラモテ・ギルアデがわれわれのものであることをよく知っているではないか。それなのに、われわれはためらっていて、それをアラムの王の手から奪い返していない。」'),
('JPN', '列王纪上', 11, 22, 4, 'そして、彼はヨシャファテに言った。「私とともにラモテ･ギルアデに戦いに行ってくれませんか。」ヨシャファテはイスラエルの王に言った。「私とあなたは一つ、私の民とあなたの民は一つ、私の馬とあなたの馬は一つです。」'),
('JPN', '列王纪上', 11, 22, 5, 'ヨシャファテはイスラエルの王に言った。「まず、主のことばを伺ってください。」'),
('JPN', '列王纪上', 11, 22, 6, 'イスラエルの王は約四百人の預言者を集めて、彼らに尋ねた。「私はラモテ・ギルアデに戦いに行くべきか。それとも、やめるべきか。」彼らは答えた。「あなたは攻め上ってください。主は王様の手にこれを渡されます。」'),
('JPN', '列王纪上', 11, 22, 7, 'ヨシャファテは、「ここには、われわれがみこころを求めることのできる主の預言者が、ほかにいないのですか」と言った。'),
('JPN', '列王纪上', 11, 22, 8, 'イスラエルの王はヨシャファテに答えた。「ほかにもう一人、主に伺うことのできる者がいます。しかし、私は彼を憎んでいます。彼は私について良いことは預言せず、悪いことばかりを預言するからです。イムラの子ミカヤです。」ヨシャファテは言った。「王よ、そういうふうには言わないでください。」'),
('JPN', '列王纪上', 11, 22, 9, 'イスラエルの王は一人の宦官を呼び、「急いでイムラの子ミカヤを連れて来い」と命じた。'),
('JPN', '列王纪上', 11, 22, 10, 'イスラエルの王とユダの王ヨシャファテは、それぞれ王服をまとって、サマリアの門の入り口にある打ち場の王の座に着いていた。預言者はみな、彼らの前で預言していた。'),
('JPN', '列王纪上', 11, 22, 11, 'ケナアナの子ゼデキヤは、王のために鉄の角を作って言った。「主はこう言われます。『これらの角で、あなたはアラムを突いて、絶ち滅ぼさなければならない。』」'),
('JPN', '列王纪上', 11, 22, 12, '預言者たちはみな、同じように預言した。「あなたはラモテ・ギルアデに攻め上って勝利を得てください。主は王の手にこれを渡されます。」'),
('JPN', '列王纪上', 11, 22, 13, 'ミカヤを呼びに行った使者はミカヤに告げた。「いいですか。預言者たちは口をそろえて、王に対して良いことを述べています。どうか、あなたも彼らと同じように語り、良いことを述べてください。」'),
('JPN', '列王纪上', 11, 22, 14, 'ミカヤは答えた。「主は生きておられる。主が私に告げられることを、そのまま述べよう。」'),
('JPN', '列王纪上', 11, 22, 15, '彼が王のもとに着くと、王は彼に言った。「ミカヤ、われわれはラモテ･ギルアデに戦いに行くべきか。それとも、やめるべきか。」彼は王に答えた。「あなたは攻め上って勝利を得なさい。主は王の手にこれを渡されます。」'),
('JPN', '列王纪上', 11, 22, 16, '王は彼に言った。「私が何度おまえに誓わせたら、おまえは主の名によって真実だけを私に告げるようになるのか。」'),
('JPN', '列王纪上', 11, 22, 17, '彼は答えた。「私は全イスラエルが山々に散らされているのを見た。まるで、羊飼いのいない羊の群れのように。そのとき主はこう言われた。『彼らには主人がいない。彼らをそれぞれ自分の家に無事に帰らせよ。』」'),
('JPN', '列王纪上', 11, 22, 18, 'イスラエルの王はヨシャファテに言った。「あなたに言ったではありませんか。彼は私について良いことは預言せず、悪いことばかりを預言すると。」'),
('JPN', '列王纪上', 11, 22, 19, 'ミカヤは言った。「それゆえ、主のことばを聞きなさい。私は主が御座に着き、天の万軍がその右左に立っているのを見ました。'),
('JPN', '列王纪上', 11, 22, 20, 'そして、主は言われました。『アハブを惑わして攻め上らせ、ラモテ･ギルアデで倒れさせるのはだれか。』すると、ある者はああしよう、別の者はこうしようと言いました。'),
('JPN', '列王纪上', 11, 22, 21, 'ひとりの霊が進み出て、主の前に立ち、『この私が彼を惑わします』と言うと、主は彼に『どのようにやるのか』とお尋ねになりました。'),
('JPN', '列王纪上', 11, 22, 22, '彼は答えました。『私が出て行って、彼のすべての預言者の口で偽りを言う霊となります。』主は『きっとあなたは惑わすことができる。出て行って、そのとおりにせよ』と言われました。'),
('JPN', '列王纪上', 11, 22, 23, '今ご覧のとおり、主はここにいるあなたのすべての預言者の口に、偽りを言う霊を授けられました。主はあなたに下るわざわいを告げられたのです。」'),
('JPN', '列王纪上', 11, 22, 24, 'ケナアナの子ゼデキヤが近寄って来て、ミカヤの頬を殴りつけて言った。「どのようにして、主の霊が私を離れ、おまえに語ったというのか。」'),
('JPN', '列王纪上', 11, 22, 25, 'ミカヤは答えた。「あなたが奥の間に入って身を隠すその日に、あなたは思い知ることになる。」'),
('JPN', '列王纪上', 11, 22, 26, 'イスラエルの王は言った。「ミカヤを捕らえよ。町の長アモンと王の子ヨアシュのもとに連れて行き、'),
('JPN', '列王纪上', 11, 22, 27, '王がこう命じたと言え。『この男を獄屋に入れ、私が無事に帰るまで、わずかなパンと、わずかな水だけ与えておけ。』」'),
('JPN', '列王纪上', 11, 22, 28, 'ミカヤは言った。「もしも、あなたが無事に戻って来ることがあるなら、主は私によって語られなかったということです。」そして、「すべての民よ、聞きなさい」と言った。'),
('JPN', '列王纪上', 11, 22, 29, 'イスラエルの王とユダの王ヨシャファテは、ラモテ･ギルアデに攻め上った。'),
('JPN', '列王纪上', 11, 22, 30, 'イスラエルの王はヨシャファテに言った。「私は変装して戦いに行きます。しかし、あなたは自分の王服を着ていてください。」イスラエルの王は変装して戦いに行った。'),
('JPN', '列王纪上', 11, 22, 31, 'アラムの王は、自分の配下の戦車隊長たち三十二人に次のように命じた。「兵とも将軍とも戦うな。ただイスラエルの王だけを狙って戦え。」'),
('JPN', '列王纪上', 11, 22, 32, '戦車隊長たちはヨシャファテを見つけたとき、「きっと、あれがイスラエルの王に違いない」と思ったので、彼の方に向きを変え、戦おうとした。ヨシャファテは助けを叫び求めた。'),
('JPN', '列王纪上', 11, 22, 33, '戦車隊長たちは、彼がイスラエルの王ではないことを知り、彼を追うことをやめて引き返した。'),
('JPN', '列王纪上', 11, 22, 34, 'そのとき、ある一人の兵士が何気なく弓を引くと、イスラエルの王の胸当てと草摺の間を射抜いた。王は自分の戦車の御者に言った。「手綱を返して、私を陣営から出させてくれ。傷を負ってしまったから。」'),
('JPN', '列王纪上', 11, 22, 35, 'その日、戦いは激しくなった。王はアラムに向かって、戦車の中で立っていたが、夕方になって死んだ。傷から出た血が戦車のくぼみに流れた。'),
('JPN', '列王纪上', 11, 22, 36, '日没のころ、陣営の中に「それぞれ自分の町、自分の国へ帰れ」という叫び声が伝わった。'),
('JPN', '列王纪上', 11, 22, 37, '王は死んでサマリアに運ばれた。人々はサマリアで王を葬った。'),
('JPN', '列王纪上', 11, 22, 38, 'それから戦車をサマリアの池で洗った。犬が彼の血をなめ、遊女たちがそこで身を洗った。主が語られたことばのとおりであった。'),
('JPN', '列王纪上', 11, 22, 39, 'アハブについてのその他の事柄、彼が行ったすべてのこと、彼が建てた象牙の家、彼が建てたすべての町、それは『イスラエルの王の歴代誌』に確かに記されている。'),
('JPN', '列王纪上', 11, 22, 40, 'アハブは先祖とともに眠りにつき、その子アハズヤが代わって王となった。'),
('JPN', '列王纪上', 11, 22, 41, 'アサの子ヨシャファテがユダの王となったのは、イスラエルの王アハブの第四年であった。'),
('JPN', '列王纪上', 11, 22, 42, 'ヨシャファテは三十五歳で王となり、エルサレムで二十五年間、王であった。その母の名はアズバといい、シルヒの娘であった。'),
('JPN', '列王纪上', 11, 22, 43, '彼はその父アサのすべての道に歩み、そこから外れることなく、主の目にかなうことを行った。しかし、高き所は取り除かなかった。民はなおも、その高き所でいけにえを献げたり、犠牲を供えたりしていた。'),
('JPN', '列王纪上', 11, 22, 44, 'ヨシャファテはイスラエルの王と友好関係を保っていた。'),
('JPN', '列王纪上', 11, 22, 45, 'ヨシャファテについてのその他の事柄、彼が立てた功績とその戦績、それは『ユダの王の歴代誌』に確かに記されている。'),
('JPN', '列王纪上', 11, 22, 46, '彼は、父アサの時代にまだ残っていた神殿男娼をこの国から除き去った。'),
('JPN', '列王纪上', 11, 22, 47, 'そのころ、エドムには王がなく、守護が王であった。'),
('JPN', '列王纪上', 11, 22, 48, 'ヨシャファテはタルシシュの船団をつくり、金を得るためにオフィルに行こうとしたが、行けなかった。船団がエツヨン・ゲベルで難破したからである。'),
('JPN', '列王纪上', 11, 22, 49, 'そのとき、アハブの子アハズヤはヨシャファテに、「私の家来をあなたの家来と一緒に船で行かせましょう」と言ったが、ヨシャファテは同意しなかった。'),
('JPN', '列王纪上', 11, 22, 50, 'ヨシャファテは先祖とともに眠りにつき、先祖とともに父ダビデの町に葬られた。その子ヨラムが代わって王となった。'),
('JPN', '列王纪上', 11, 22, 51, 'アハブの子アハズヤは、ユダの王ヨシャファテの第十七年にサマリアでイスラエルの王となり、二年間イスラエルの王であった。'),
('JPN', '列王纪上', 11, 22, 52, '彼は主の目に悪であることを行い、彼の父の道と彼の母の道、それに、イスラエルに罪を犯させた、ネバテの子ヤロブアムの道に歩んだ。'),
('JPN', '列王纪上', 11, 22, 53, '彼はバアルに仕え、それを拝み、彼の父が行ったのと全く同じように行って、イスラエルの神、主の怒りを引き起こした。'),
('JPN', '列王纪下', 12, 1, 1, 'アハブの死後、モアブがイスラエルに背いた。'),
('JPN', '列王纪下', 12, 1, 2, 'アハズヤは、サマリアにあった彼の屋上の部屋の欄干から落ちて重体に陥った。彼は使者たちを遣わし、「行って、エクロンの神、バアル・ゼブブに、私のこの病が治るかどうか伺いを立てよ」と命じた。'),
('JPN', '列王纪下', 12, 1, 3, 'そのころ、主の使いがティシュベ人エリヤに告げた。「さあ、上って行って、サマリアの王の使者たちに会い、彼らにこう言え。『あなたがたがエクロンの神、バアル・ゼブブに伺いを立てに行くのは、イスラエルに神がいないためか。'),
('JPN', '列王纪下', 12, 1, 4, 'それゆえ、主はこう言われる。あなたは上ったその寝台から降りることはない。あなたは必ず死ぬ。』」そこでエリヤは出て行った。'),
('JPN', '列王纪下', 12, 1, 5, '使者たちがアハズヤのもとに戻って来たので、彼は「なぜおまえたちは帰って来たのか」と彼らに尋ねた。'),
('JPN', '列王纪下', 12, 1, 6, '彼らは答えた。「ある人が私たちに会いに上って来て言いました。『自分たちを遣わした王のところに帰って、彼にこう告げなさい。主はこう言われる。あなたが人を遣わして、エクロンの神、バアル・ゼブブに伺いを立てるのは、イスラエルに神がいないためか。それゆえ、あなたは上ったその寝台から降りることはない。あなたは必ず死ぬ。』」'),
('JPN', '列王纪下', 12, 1, 7, 'アハズヤは彼らに尋ねた。「おまえたちに会いに上って来て、そんなことを告げたのはどんな男か。」'),
('JPN', '列王纪下', 12, 1, 8, '彼らが「毛衣を着て、腰に革の帯を締めた人でした」と答えると、アハズヤは「それはティシュベ人エリヤだ」と言った。'),
('JPN', '列王纪下', 12, 1, 9, 'そこでアハズヤは、五十人隊の長を、その部下五十人とともにエリヤのところに遣わした。隊長がエリヤのところに上って行くと、そのとき、エリヤは山の頂に座っていた。隊長はエリヤに言った。「神の人よ、王のお告げです。下りて来てください。」'),
('JPN', '列王纪下', 12, 1, 10, 'エリヤはその五十人隊の長に答えて言った。「私が神の人であるなら、天から火が下って来て、あなたとあなたの部下五十人を焼き尽くすだろう。」すると、天から火が下って来て、彼とその部下五十人を焼き尽くした。'),
('JPN', '列王纪下', 12, 1, 11, '王はまた、もう一人の五十人隊の長を、その部下五十人とともにエリヤのところに遣わした。隊長はエリヤに言った。「神の人よ、王がこう言われます。急いで下りて来てください。」'),
('JPN', '列王纪下', 12, 1, 12, 'エリヤは彼らに答えた。「私が神の人であるなら、天から火が下って来て、あなたとあなたの部下五十人を焼き尽くすだろう。」すると、天から神の火が下って来て、彼とその部下五十人を焼き尽くした。'),
('JPN', '列王纪下', 12, 1, 13, '王はまた、第三の五十人隊の長と、その部下五十人を遣わした。この三人目の五十人隊の長は上って行き、エリヤの前にひざまずき、懇願して言った。「神の人よ、どうか私のいのちと、このあなたのしもべ五十人のいのちをお助けください。'),
('JPN', '列王纪下', 12, 1, 14, 'ご承知のように、天から火が下って来て、先の二人の五十人隊の長とそれぞれの部下五十人を、焼き尽くしてしまいました。今、私のいのちをお助けください。」'),
('JPN', '列王纪下', 12, 1, 15, '主の使いがエリヤに「彼と一緒に下って行け。彼を恐れてはならない」と言ったので、エリヤは立って、彼と一緒に王のところに下って行き、'),
('JPN', '列王纪下', 12, 1, 16, '王に言った。「主はこう言われる。『あなたが使者たちをエクロンの神、バアル・ゼブブに伺いを立てに遣わしたのは、イスラエルにみことばを伺う神がいないためか。それゆえ、あなたは上ったその寝台から降りることはない。あなたは必ず死ぬ。』」'),
('JPN', '列王纪下', 12, 1, 17, '王は、エリヤが告げた主のことばのとおりに死んだ。そしてヨラムが代わって王となった。それはユダの王ヨシャファテの子ヨラムの第二年のことであった。アハズヤには息子がいなかったからである。'),
('JPN', '列王纪下', 12, 1, 18, 'アハズヤが行ったその他の事柄、それは『イスラエルの王の歴代誌』に確かに記されている。'),
('JPN', '列王纪下', 12, 2, 1, '主がエリヤを竜巻に乗せて天に上げようとされたときのこと、エリヤはエリシャを連れてギルガルから出て行った。'),
('JPN', '列王纪下', 12, 2, 2, 'エリヤはエリシャに「ここにとどまっていなさい。主が私をベテルに遣わされたから」と言った。しかしエリシャは言った。「主は生きておられます。あなたのたましいも生きています。私は決してあなたから離れません。」こうして、彼らはベテルに下って行った。'),
('JPN', '列王纪下', 12, 2, 3, 'すると、ベテルの預言者の仲間たちがエリシャのところに出て来て、彼に言った。「今日、主があなたの主人をあなたから取り上げられることを知っていますか。」エリシャは、「私も知っていますが、黙っていてください」と答えた。'),
('JPN', '列王纪下', 12, 2, 4, 'エリヤは彼に「エリシャ、ここにとどまっていなさい。主が私をエリコに遣わされたから」と言った。しかし彼は言った。「主は生きておられます。あなたのたましいも生きています。私は決してあなたから離れません。」こうして、彼らはエリコにやって来た。'),
('JPN', '列王纪下', 12, 2, 5, 'するとエリコの預言者の仲間たちがエリシャに近づいて来て、彼に言った。「今日、主があなたの主人をあなたから取り上げられることを知っていますか。」エリシャは、「私も知っていますが、黙っていてください」と答えた。'),
('JPN', '列王纪下', 12, 2, 6, 'エリヤは彼に「ここにとどまっていなさい。主が私をヨルダンへ遣わされたから」と言った。しかし彼は言った。「主は生きておられます。あなたのたましいも生きています。私は決してあなたから離れません。」こうして、二人は進んで行った。'),
('JPN', '列王纪下', 12, 2, 7, '一方、預言者の仲間たちのうち五十人は、行って遠く離れて立った。二人がヨルダン川のほとりに立ったとき、'),
('JPN', '列王纪下', 12, 2, 8, 'エリヤは自分の外套を取り、それを丸めて水を打った。すると、水が両側に分かれたので、二人は乾いた土の上を渡った。'),
('JPN', '列王纪下', 12, 2, 9, '渡り終えると、エリヤはエリシャに言った。「あなたのために何をしようか。私があなたのところから取り去られる前に求めなさい。」するとエリシャは、「では、あなたの霊のうちから、二倍の分を私のものにしてください」と言った。'),
('JPN', '列王纪下', 12, 2, 10, 'エリヤは言った。「あなたは難しい注文をする。しかし、私があなたのところから取り去られるとき、あなたが私を見ることができれば、そのことはあなたにかなえられるだろう。できないなら、そうはならない。」'),
('JPN', '列王纪下', 12, 2, 11, 'こうして、彼らがなお進みながら話していると、なんと、火の戦車と火の馬が現れ、この二人の間を分け隔て、エリヤは竜巻に乗って天へ上って行った。'),
('JPN', '列王纪下', 12, 2, 12, 'エリシャはこれを見て、「わが父、わが父、イスラエルの戦車と騎兵たち」と叫び続けたが、エリヤはもう見えなかった。彼は自分の衣をつかみ、それを二つに引き裂いた。'),
('JPN', '列王纪下', 12, 2, 13, 'それから、彼はエリヤの身から落ちた外套を拾い上げ、引き返してヨルダン川の岸辺に立った。'),
('JPN', '列王纪下', 12, 2, 14, '彼は、エリヤの身から落ちた外套を取って水を打ち、「エリヤの神、主はどこにおられるのですか」と言った。エリシャが水を打つと、水が両側に分かれ、彼はそこを渡った。'),
('JPN', '列王纪下', 12, 2, 15, 'エリコの預言者の仲間たちは、遠くから彼を見て、「エリヤの霊がエリシャの上にとどまっている」と言って、彼を迎えに行き、地にひれ伏して礼をした。'),
('JPN', '列王纪下', 12, 2, 16, '彼らはエリシャに言った。「しもべたちのところに五十人の力ある者がいます。どうか彼らにあなたのご主人を捜しに行かせてください。主の霊がエリヤを運んで、どこかの山か谷に投げたかもしれません。」するとエリシャは、「行かせてはいけません」と言った。'),
('JPN', '列王纪下', 12, 2, 17, 'しかし、彼らがしつこく彼に願ったので、ついにエリシャは、「行かせなさい」と言った。そこで、彼らは五十人を送り出した。彼らは三日間捜したが、エリヤを見つけることができなかった。'),
('JPN', '列王纪下', 12, 2, 18, '彼らは、エリコにとどまっていたエリシャのところへ帰って来た。エリシャは彼らに言った。「行かないようにと、あなたがたに言ったではありませんか。」'),
('JPN', '列王纪下', 12, 2, 19, 'さて、この町の人々はエリシャに言った。「あなた様もご覧のとおり、この町は住むのには良いのですが、水が悪く、この土地は流産を引き起こします。」'),
('JPN', '列王纪下', 12, 2, 20, 'するとエリシャは言った。「新しい皿に塩を盛って、私のところに持って来なさい。」人々は彼のところにそれを持って来た。'),
('JPN', '列王纪下', 12, 2, 21, 'エリシャは水の源のところに行って、塩をそこに投げ込んで言った。「主はこう言われる。『わたしはこの水を癒やした。ここからは、もう、死も流産も起こらない。』」'),
('JPN', '列王纪下', 12, 2, 22, 'こうして水は良くなり、今日に至っている。エリシャが言ったことばのとおりである。'),
('JPN', '列王纪下', 12, 2, 23, 'エリシャはそこからベテルへ上って行った。彼が道を上って行くと、その町から小さい子どもたちが出て来て彼をからかい、「上って来い、はげ頭。上って来い、はげ頭」と言ったので、'),
('JPN', '列王纪下', 12, 2, 24, '彼は向き直って彼らをにらみつけ、主の名によって彼らをのろった。すると、森の中から二頭の雌熊が出て来て、子どもたちのうち四十二人をかき裂いた。'),
('JPN', '列王纪下', 12, 2, 25, 'こうして彼は、そこからカルメル山に行き、そこからさらに、サマリアに帰った。'),
('JPN', '列王纪下', 12, 3, 1, 'アハブの子ヨラムは、ユダの王ヨシャファテの第十八年に、サマリアでイスラエルの王となり、十二年間、王であった。'),
('JPN', '列王纪下', 12, 3, 2, '彼は主の目に悪であることを行ったが、彼の父母ほどではなかった。彼は、父が作ったバアルの石の柱を取り除いた。'),
('JPN', '列王纪下', 12, 3, 3, 'しかし彼は、イスラエルに罪を犯させたネバテの子ヤロブアムの罪に執着し、それから離れることがなかった。'),
('JPN', '列王纪下', 12, 3, 4, 'さて、モアブの王メシャは羊を飼っていて、子羊十万匹と、雄羊十万匹分の羊毛をイスラエルの王に貢ぎ物として納めていた。'),
('JPN', '列王纪下', 12, 3, 5, 'しかしアハブが死ぬと、モアブの王はイスラエルの王に背いた。'),
('JPN', '列王纪下', 12, 3, 6, 'そこで、ヨラム王はその日にサマリアを出発し、すべてのイスラエル人を動員した。'),
('JPN', '列王纪下', 12, 3, 7, 'そして、ユダの王ヨシャファテに人を遣わして言った。「モアブの王が私に背きました。私と一緒にモアブに戦いに行ってくれませんか。」ユダの王は言った。「行きましょう。私とあなたは一つ、私の民とあなたの民は一つ、私の馬とあなたの馬は一つです。」'),
('JPN', '列王纪下', 12, 3, 8, 'そして言った。「どの道を上って行きましょうか。」するとヨラムは、「エドムの荒野の道を」と答えた。'),
('JPN', '列王纪下', 12, 3, 9, 'こうして、イスラエルの王は、ユダの王とエドムの王と一緒に出かけたが、七日間も回り道をしたので、陣営の者と、後について来る動物たちのための水がなくなった。'),
('JPN', '列王纪下', 12, 3, 10, 'イスラエルの王は、「ああ、主がこの三人の王を呼び集めたのは、モアブの手に渡すためだったのだ」と言った。'),
('JPN', '列王纪下', 12, 3, 11, 'ヨシャファテは言った。「ここには、主のみこころを求めることができる主の預言者はいないのですか。」すると、イスラエルの王の家来の一人が答えた。「ここには、シャファテの子エリシャがいます。エリヤの手に水を注いだ者です。」'),
('JPN', '列王纪下', 12, 3, 12, 'ヨシャファテが、「主のことばは彼とともにあります」と言ったので、イスラエルの王と、ヨシャファテと、エドムの王は彼のところに下って行った。'),
('JPN', '列王纪下', 12, 3, 13, 'エリシャはイスラエルの王に言った。「私とあなたの間に何の関わりがあるでしょうか。あなたの父の預言者たちや、母の預言者たちのところに行かれたらよいでしょう。」すると、イスラエルの王は彼に言った。「いや、モアブの手に渡すために、この三人の王を呼び集めたのは、主だ。」'),
('JPN', '列王纪下', 12, 3, 14, 'エリシャは言った。「私が仕えている万軍の主は生きておられます。もし私がユダの王ヨシャファテの顔を立てるのでなければ、私は決してあなたに目も留めず、あなたに会うこともしなかったでしょう。'),
('JPN', '列王纪下', 12, 3, 15, 'しかし今、竪琴を弾く者をここに連れて来てください。」竪琴を弾く者が竪琴を弾き鳴らすと、主の手がエリシャの上に下り、'),
('JPN', '列王纪下', 12, 3, 16, '彼は次のように言った。「主はこう言われます。『この涸れた谷にはたくさんの水がたまる。』'),
('JPN', '列王纪下', 12, 3, 17, '主がこう言われるからです。『風を見ず、大雨を見なくても、この涸れた谷には水があふれる。あなたがたも、あなたがたの家畜も、動物もこれを飲む。』'),
('JPN', '列王纪下', 12, 3, 18, 'これは主の目には小さなことです。主はモアブをあなたがたの手に渡されます。'),
('JPN', '列王纪下', 12, 3, 19, 'あなたがたは、城壁のある町々、立派な町々をことごとく打ち破り、すべての良い木を切り倒し、すべての水の源をふさぎ、すべての良い畑を石をもって荒らすでしょう。」'),
('JPN', '列王纪下', 12, 3, 20, '朝になって、ささげ物を献げるころ、なんと、水がエドムの方から流れて来て、この地は水で満たされた。'),
('JPN', '列王纪下', 12, 3, 21, 'モアブ人はみな、王たちが自分たちを攻めに上って来たことを聞いた。よろいを着けることができる者はすべて呼び集められ、国境の守備に就いた。'),
('JPN', '列王纪下', 12, 3, 22, '翌朝早く起きてみると、太陽が水の面を照らしていた。モアブ人は、向こう側の水が血のように赤いのを見て、'),
('JPN', '列王纪下', 12, 3, 23, 'こう言った。「これは血だ。きっと王たちが切り合って、同士討ちをしたに違いない。さあ今、モアブよ、分捕りに行こう。」'),
('JPN', '列王纪下', 12, 3, 24, '彼らがイスラエルの陣営に攻め入ると、イスラエルは立ってモアブ人を討った。モアブ人はイスラエルの前から逃げた。イスラエルは攻め入って、モアブ人を討った。'),
('JPN', '列王纪下', 12, 3, 25, 'さらに、彼らは町々を破壊し、すべての良い畑にだれもが石を投げ捨てて石だらけにし、すべての水の源をふさぎ、すべての良い木を切り倒した。ただキル・ハレセテにある石だけが残ったが、その町も石を投げる者たちが取り囲み、これを打ち破った。'),
('JPN', '列王纪下', 12, 3, 26, 'モアブの王は、戦いが自分に不利になっていくのを見て、剣を使う者七百人を引き連れ、エドムの王のところに突き入ろうとしたが、果たせなかった。'),
('JPN', '列王纪下', 12, 3, 27, 'そこで、彼は自分に代わって王となる長男を取り、その子を城壁の上で全焼のささげ物として献げた。このことのゆえに、イスラエル人に対する激しい怒りが起こった。そこでイスラエル人は、そこから引き揚げて、自分の国へ帰って行った。'),
('JPN', '列王纪下', 12, 4, 1, '預言者の仲間の妻の一人がエリシャに叫んで言った。「あなたのしもべである私の夫が死にました。ご存じのように、あなたのしもべは主を恐れていました。ところが、債権者が来て、私の二人の子どもを自分の奴隷にしようとしています。」'),
('JPN', '列王纪下', 12, 4, 2, 'エリシャは彼女に言った。「何をしてあげようか。私に話しなさい。あなたには、家の中に何があるのか。」彼女は答えた。「はしためには、家の中に何もありません。ただ、油の壺一つしかありません。」'),
('JPN', '列王纪下', 12, 4, 3, 'すると、彼は言った。「外に行って、近所の皆から、器を借りて来なさい。空の器を。それも、一つや二つではいけません。'),
('JPN', '列王纪下', 12, 4, 4, '家に入ったら、あなたと子どもたちの背後の戸を閉めなさい。そしてすべての器に油を注ぎ入れなさい。いっぱいになったものは、わきに置きなさい。」'),
('JPN', '列王纪下', 12, 4, 5, 'そこで、彼女は彼のもとから去って行き、彼女と子どもたちが入った背後の戸を閉めた。そして、子どもたちが次々と自分のところに持って来る器に油を注ぎ入れた。'),
('JPN', '列王纪下', 12, 4, 6, '器がどれもいっぱいになったので、彼女は子どもの一人に言った。「もっと器を持って来なさい。」その子どもが彼女に、「もう器はありません」と言うと、油は止まった。'),
('JPN', '列王纪下', 12, 4, 7, '彼女が神の人に知らせに行くと、彼は言った。「行ってその油を売り、あなたの負債を払いなさい。その残りで、あなたと子どもたちは暮らしていけます。」'),
('JPN', '列王纪下', 12, 4, 8, 'ある日、エリシャがシュネムを通りかかると、そこに一人の裕福な女がいて、彼を食事に引き止めた。それ以来、エリシャはそこを通りかかるたびに、そこに寄って食事をするようになった。'),
('JPN', '列王纪下', 12, 4, 9, '女は夫に言った。「いつも私たちのところに立ち寄って行かれるあの方は、きっと神の聖なる方に違いありません。'),
('JPN', '列王纪下', 12, 4, 10, 'ですから、屋上に壁のある小さな部屋を作り、あの方のために寝台と机と椅子と燭台を置きましょう。あの方が私たちのところに来られるたびに、そこを使っていただけますから。」'),
('JPN', '列王纪下', 12, 4, 11, 'ある日、エリシャはそこに来て、その屋上の部屋に入って横になった。'),
('JPN', '列王纪下', 12, 4, 12, '彼は若者ゲハジに言った。「ここのシュネムの女を呼びなさい。」ゲハジが呼ぶと、彼女はゲハジの前に立った。'),
('JPN', '列王纪下', 12, 4, 13, 'エリシャはゲハジに言った。「彼女にこう伝えなさい。『本当に、あなたはこのように、私たちのことで一生懸命骨折ってくれたが、あなたのために何をしたらよいか。王か軍の長に、何か話してほしいことでもあるか』と。」彼女はそれにこう答えた。「私は私の民の間で、幸せに暮らしております。」'),
('JPN', '列王纪下', 12, 4, 14, 'エリシャが「では、彼女のために何をしたらよいだろうか」と言うと、ゲハジは言った。「彼女には子がなく、それに、彼女の夫も年をとっています。」'),
('JPN', '列王纪下', 12, 4, 15, 'エリシャが、「彼女を呼んで来なさい」と言ったので、ゲハジが彼女を呼ぶと、彼女は入り口のところに立った。'),
('JPN', '列王纪下', 12, 4, 16, 'エリシャは言った。「来年の今ごろ、あなたは男の子を抱くようになる。」すると彼女は言った。「いいえ、ご主人様。神の人よ、このはしために偽りを言わないでください。」'),
('JPN', '列王纪下', 12, 4, 17, 'しかし、この女は身ごもり、エリシャが彼女に告げたとおり、翌年のちょうどそのころに男の子を産んだ。'),
('JPN', '列王纪下', 12, 4, 18, 'その子が大きくなって、ある日、刈り入れをする者たちと一緒にいる、父のところに出て行ったとき、'),
('JPN', '列王纪下', 12, 4, 19, '父親に、「頭が、頭が」と言った。父親は若者に、「この子を母親のところに抱いて行ってくれ」と命じた。'),
('JPN', '列王纪下', 12, 4, 20, '若者はその子を抱き、母親のところに連れて行った。この子は昼まで母親の膝の上に休んでいたが、ついに死んでしまった。'),
('JPN', '列王纪下', 12, 4, 21, '彼女は屋上に上がって、神の人の寝台にその子を寝かせ、戸を閉めて出て行った。'),
('JPN', '列王纪下', 12, 4, 22, '彼女は夫に呼びかけて言った。「どうか、若者一人と、雌ろば一頭を私のために出してください。私は急いで神の人のところに行って、すぐに戻って来ますから。」'),
('JPN', '列王纪下', 12, 4, 23, 'すると彼は、「どうして、今日あの人のところに行くのか。新月祭でもなく、安息日でもないのに」と言ったが、彼女は「かまいません」と答えた。'),
('JPN', '列王纪下', 12, 4, 24, '彼女は雌ろばに鞍を置き、若者に命じた。「手綱を引いて進みなさい。私が命じなければ、手綱を緩めてはいけません。」'),
('JPN', '列王纪下', 12, 4, 25, 'こうして彼女は出かけて、カルメル山の神の人のところへ行った。神の人は、遠くから彼女を見つけると、若者ゲハジに言った。「見なさい。あのシュネムの女があそこに来ている。'),
('JPN', '列王纪下', 12, 4, 26, 'さあ、走って行って彼女を迎え、言いなさい。『あなたは無事ですか。あなたのご主人は無事ですか。お子さんは無事ですか』と。」彼女はそれにこう答えた。「無事です。」'),
('JPN', '列王纪下', 12, 4, 27, 'それから彼女は山の上にいる神の人のところに来て、彼の足にすがりついた。ゲハジが彼女を追い払おうと近寄ると、神の人は言った。「そのままにしておきなさい。彼女の心に悩みがあるのだから。主はそれを私に隠し、まだ私に知らせておられないのだ。」'),
('JPN', '列王纪下', 12, 4, 28, '彼女は言った。「私がご主人様に子どもを求めたでしょうか。この私にそんな気休めを言わないでくださいと申し上げたではありませんか。」'),
('JPN', '列王纪下', 12, 4, 29, 'そこでエリシャはゲハジに言った。「腰に帯を締め、手に私の杖を持って行きなさい。たとえだれかに会っても、あいさつしてはならない。たとえだれかがあいさつしても、答えてはならない。そして、私の杖をあの子の頭の上に置きなさい。」'),
('JPN', '列王纪下', 12, 4, 30, 'その子の母親は言った。「主は生きておられます。あなたのたましいも生きています。私は決してあなたを離しません。」エリシャは立ち上がり、彼女の後について行った。'),
('JPN', '列王纪下', 12, 4, 31, 'ゲハジは二人より先に行って、その杖を子どもの頭の上に置いたが、何の声もなく、何の応答もなかった。そこで引き返してエリシャに会い、「子どもは目を覚ましませんでした」と報告した。'),
('JPN', '列王纪下', 12, 4, 32, 'エリシャが家に着くと、その子は寝台の上に死んで横たわっていた。'),
('JPN', '列王纪下', 12, 4, 33, 'エリシャは中に入り、戸を閉めて、二人だけになって主に祈った。'),
('JPN', '列王纪下', 12, 4, 34, 'それから、寝台の上に上がり、その子の上に身を伏せ、自分の口をその子の口の上に、自分の目をその子の目の上に、自分の両手をその子の両手の上に重ねて、その子の上に身をかがめた。すると、その子のからだが温かくなってきた。'),
('JPN', '列王纪下', 12, 4, 35, 'それからエリシャは降りて、部屋の中をあちらこちらと歩き回り、また寝台の上に上がり、子どもの上に身をかがめると、子どもは七回くしゃみをして目を開けた。'),
('JPN', '列王纪下', 12, 4, 36, '彼はゲハジを呼んで、「あのシュネムの女を呼んで来なさい」と言った。ゲハジが彼女を呼んだので、彼女はエリシャのところに来た。そこでエリシャは、「あなたの子どもを抱き上げなさい」と言った。'),
('JPN', '列王纪下', 12, 4, 37, '彼女は入って来て彼の足もとにひれ伏し、地にひれ伏した。そして、子どもを抱き上げて出て行った。'),
('JPN', '列王纪下', 12, 4, 38, 'エリシャがギルガルに帰って来たとき、この地に飢饉が起こった。預言者の仲間たちが彼の前に座っていたので、彼は若者に命じた。「大きな釜を火にかけ、預言者の仲間たちのために煮物を作りなさい。」'),
('JPN', '列王纪下', 12, 4, 39, '彼らの一人が食用の草を摘みに野に出て行くと、野生のつる草を見つけたので、そのつるから野生の瓜を前掛けにいっぱい取って帰って来た。そして、彼はそれを煮物の釜の中に刻んで入れた。彼らはそれが何であるかを知らなかった。'),
('JPN', '列王纪下', 12, 4, 40, '彼らは皆に食べさせようとして、これをよそった。皆はその煮物を口にするやいなや、こう叫んだ。「神の人よ、釜の中に毒が入っています。」彼らは食べることができなかった。'),
('JPN', '列王纪下', 12, 4, 41, 'エリシャは言った。「では、麦粉を持って来なさい。」彼はそれを釜に投げ入れて言った。「これをよそって、この人たちに食べさせなさい。」そのときにはもう、釜の中には悪い物はなくなっていた。'),
('JPN', '列王纪下', 12, 4, 42, 'ある人がバアル・シャリシャから、初穂のパンである大麦のパン二十個と、新穀一袋を、神の人のところに持って来た。神の人は「この人たちに与えて食べさせなさい」と命じた。'),
('JPN', '列王纪下', 12, 4, 43, '彼の召使いは、「これだけで、どうして百人もの人に分けられるでしょうか」と言った。しかし、エリシャは言った。「この人たちに与えて食べさせなさい。主はこう言われる。『彼らは食べて残すだろう。』」'),
('JPN', '列王纪下', 12, 4, 44, 'そこで、召使いが彼らに配ると、彼らは食べて残した。主のことばのとおりであった。'),
('JPN', '列王纪下', 12, 5, 1, 'アラムの王の軍の長ナアマンは、その主君に重んじられ、尊敬されていた。それは、主が以前に、彼を通してアラムに勝利を与えられたからであった。この人は勇士であったが、ツァラアトに冒されていた。'),
('JPN', '列王纪下', 12, 5, 2, 'アラムはかつて略奪に出たとき、イスラエルの地から一人の若い娘を捕らえて来ていた。彼女はナアマンの妻に仕えていた。'),
('JPN', '列王纪下', 12, 5, 3, '彼女は女主人に言った。「もし、ご主人様がサマリアにいる預言者のところに行かれたら、きっと、その方がご主人様のツァラアトを治してくださるでしょう。」'),
('JPN', '列王纪下', 12, 5, 4, 'そこで、ナアマンはその主君のところに行き、イスラエルの地から来た娘がこれこれのことを言いました、と告げた。'),
('JPN', '列王纪下', 12, 5, 5, 'アラムの王は言った。「行って来なさい。私がイスラエルの王に宛てて手紙を送ろう。」そこで、ナアマンは、銀十タラントと金六千シェケルと晴れ着十着を持って出かけた。'),
('JPN', '列王纪下', 12, 5, 6, '彼はイスラエルの王宛ての次のような手紙を持って行った。「この手紙があなたに届きましたら、家臣のナアマンをあなたのところに送りましたので、彼のツァラアトを治してくださいますように。」'),
('JPN', '列王纪下', 12, 5, 7, 'イスラエルの王はこの手紙を読むと、自分の衣を引き裂いて言った。「私は殺したり、生かしたりすることのできる神であろうか。この人はこの男を送って、ツァラアトを治せと言う。しかし、考えてみよ。彼は私に言いがかりをつけようとしているのだ。」'),
('JPN', '列王纪下', 12, 5, 8, '神の人エリシャは、イスラエルの王が衣を引き裂いたことを聞くと、王のもとに人を遣わして言った。「あなたはどうして衣を引き裂いたりなさるのですか。その男を私のところによこしてください。そうすれば、彼はイスラエルに預言者がいることを知るでしょう。」'),
('JPN', '列王纪下', 12, 5, 9, 'こうして、ナアマンは馬と戦車でやって来て、エリシャの家の入り口に立った。'),
('JPN', '列王纪下', 12, 5, 10, 'エリシャは、彼に使者を遣わして言った。「ヨルダン川へ行って七回あなたの身を洗いなさい。そうすれば、あなたのからだは元どおりになって、きよくなります。」'),
('JPN', '列王纪下', 12, 5, 11, 'しかしナアマンは激怒して去り、そして言った。「何ということだ。私は、彼がきっと出て来て立ち、彼の神、主の名を呼んで、この患部の上で手を動かし、ツァラアトに冒されたこの者を治してくれると思っていた。'),
('JPN', '列王纪下', 12, 5, 12, 'ダマスコの川、アマナやパルパルは、イスラエルのすべての川にまさっているではないか。これらの川で身を洗って、私がきよくなれないというのか。」こうして、彼は憤って帰途についた。'),
('JPN', '列王纪下', 12, 5, 13, 'そのとき、彼のしもべたちが近づいて彼に言った。「わが父よ。難しいことを、あの預言者があなたに命じたのでしたら、あなたはきっとそれをなさったのではありませんか。あの人は『身を洗ってきよくなりなさい』と言っただけではありませんか。」'),
('JPN', '列王纪下', 12, 5, 14, 'そこで、ナアマンは下って行き、神の人が言ったとおりに、ヨルダン川に七回身を浸した。すると彼のからだは元どおりになって、幼子のからだのようになり、きよくなった。'),
('JPN', '列王纪下', 12, 5, 15, 'ナアマンはその一行の者すべてを連れて神の人のところに引き返して来て、彼の前に立って言った。「私は今、イスラエルのほか、全世界のどこにも神はおられないことを知りました。どうか今、あなたのしもべからの贈り物を受け取ってください。」'),
('JPN', '列王纪下', 12, 5, 16, '神の人は言った。「私が仕えている主は生きておられます。私は決して受け取りません。」ナアマンは、受け取らせようとしてしきりに勧めたが、神の人は断った。'),
('JPN', '列王纪下', 12, 5, 17, 'そこでナアマンは言った。「それなら、どうか二頭のらばに載せるだけの土をしもべに与えてください。しもべはこれからはもう、主以外のほかの神々に全焼のささげ物やいけにえを献げません。'),
('JPN', '列王纪下', 12, 5, 18, 'どうか、主が次のことについてしもべをお赦しくださいますように。私の主君がリンモンの神殿に入って、そこでひれ伏すために私の手を頼みにします。それで私もリンモンの神殿でひれ伏します。私がリンモンの神殿でひれ伏すとき、どうか、主がこのことについてしもべをお赦しくださいますように。」'),
('JPN', '列王纪下', 12, 5, 19, 'エリシャは彼に言った。「安心して行きなさい。」そこでナアマンは彼から離れ、かなりの道のりを進んで行った。'),
('JPN', '列王纪下', 12, 5, 20, 'そのとき、神の人エリシャに仕える若者ゲハジはこう考えた。「何としたことか。私の主人は、あのアラム人ナアマンが持って来た物を受け取ろうとはしなかった。主は生きておられる。私は彼の後を追いかけて、絶対に何かをもらって来よう。」'),
('JPN', '列王纪下', 12, 5, 21, 'ゲハジはナアマンの後を追いかけて行った。ナアマンは、うしろから駆けて来る者を見つけると、戦車から降りて彼を迎え、「何か変わったことでも」と尋ねた。'),
('JPN', '列王纪下', 12, 5, 22, 'そこで、ゲハジは言った。「変わったことはありませんが、私の主人は私を送り出してこう言っています。『たった今、エフライムの山地から、預言者の仲間の二人の若者が私のところにやって来たので、どうか、銀一タラントと晴れ着二着を彼らに与えてやってください。』」'),
('JPN', '列王纪下', 12, 5, 23, 'するとナアマンは、「ぜひ、二タラントを取ってください」と言ってしきりに勧め、二つの袋に入れた銀二タラントと、晴れ着二着を自分の二人の若者に渡した。そこで彼らはそれを背負ってゲハジの先に立って進んだ。'),
('JPN', '列王纪下', 12, 5, 24, 'ゲハジは丘に着くと、それを二人の者から受け取って家の中にしまい込み、彼らを帰らせたので、彼らは去って行った。'),
('JPN', '列王纪下', 12, 5, 25, '彼が家に入って主人の前に立つと、エリシャは彼に言った。「ゲハジ。おまえはどこへ行って来たのか。」彼は答えた。「しもべはどこへも行っていません。」'),
('JPN', '列王纪下', 12, 5, 26, 'エリシャは彼に言った。「あの人がおまえを迎えに戦車から降りたとき、私の心はおまえと一緒に歩んでいたではないか。今は金を受け、衣服を受け、オリーブ油やぶどう畑、羊や牛、男女の奴隷を受ける時だろうか。'),
('JPN', '列王纪下', 12, 5, 27, 'ナアマンのツァラアトは、いつまでもおまえとおまえの子孫にまといつく。」ゲハジはツァラアトに冒され、雪のようになって、エリシャの前から去って行った。'),
('JPN', '列王纪下', 12, 6, 1, '預言者の仲間たちがエリシャに、「ご覧のとおり、私たちがあなたと一緒に住んでいるこの場所は狭くなりましたので、'),
('JPN', '列王纪下', 12, 6, 2, 'ヨルダン川に行きましょう。そこから各自一本ずつ梁にする木を切り出して、そこに私たちの住む場所を作りましょう」と言うと、エリシャは「行きなさい」と言った。'),
('JPN', '列王纪下', 12, 6, 3, 'すると一人が、「どうか、ぜひ、しもべたちと一緒に来てください」と言ったので、エリシャは「では、私も行こう」と言って、'),
('JPN', '列王纪下', 12, 6, 4, '彼らと一緒に出かけた。彼らはヨルダン川に着くと、木を切り倒した。'),
('JPN', '列王纪下', 12, 6, 5, '一人が梁にする木を切り倒しているとき、斧の頭が水の中に落ちてしまった。彼は叫んだ。「ああ、主よ、あれは借り物です。」'),
('JPN', '列王纪下', 12, 6, 6, '神の人は言った。「どこに落ちたのか。」彼がその場所を示すと、エリシャは一本の枝を切ってそこに投げ込み、斧の頭を浮かばせた。'),
('JPN', '列王纪下', 12, 6, 7, '彼が「それを拾い上げなさい」と言ったので、その人は手を伸ばして、それを取り上げた。'),
('JPN', '列王纪下', 12, 6, 8, 'さて、アラムの王がイスラエルと戦っていたとき、彼は家来たちと相談して言った。「これこれの場所に陣を敷こう。」'),
('JPN', '列王纪下', 12, 6, 9, 'そのとき、神の人はイスラエルの王のもとに人を遣わして言った。「あの場所を通らないように注意しなさい。あそこにはアラム人が下って来ますから。」'),
('JPN', '列王纪下', 12, 6, 10, 'イスラエルの王は、神の人が告げたその場所に人を遣わした。神の人が警告すると、王はそこを警戒した。このようなことは一度や二度ではなかった。'),
('JPN', '列王纪下', 12, 6, 11, 'このことで、アラムの王の心は激しく動揺した。彼は家来たちを呼んで言った。「われわれのうちのだれがイスラエルの王と通じているのか、おまえたちは私に告げないのか。」'),
('JPN', '列王纪下', 12, 6, 12, 'すると家来の一人が言った。「いいえ、わが主、王よ。イスラエルにいる預言者エリシャが、あなたが寝室の中で語られることばまでもイスラエルの王に告げているのです。」'),
('JPN', '列王纪下', 12, 6, 13, '王は言った。「行って、彼がどこにいるかを突き止めよ。人を遣わして、彼を捕まえよう。」そのうちに、「今、彼はドタンにいる」という知らせが王にもたらされた。'),
('JPN', '列王纪下', 12, 6, 14, 'そこで、王は馬と戦車と大軍をそこに送った。彼らは夜のうちに来て、その町を包囲した。'),
('JPN', '列王纪下', 12, 6, 15, '神の人の召使いが、朝早く起きて外に出ると、なんと、馬と戦車の軍隊がその町を包囲していた。若者がエリシャに、「ああ、ご主人様。どうしたらよいのでしょう」と言った。'),
('JPN', '列王纪下', 12, 6, 16, 'すると彼は、「恐れるな。私たちとともにいる者は、彼らとともにいる者よりも多いのだから」と言った。'),
('JPN', '列王纪下', 12, 6, 17, 'そして、エリシャは祈って主に願った。「どうか、彼の目を開いて、見えるようにしてください。」主がその若者の目を開かれたので、彼が見ると、なんと、火の馬と戦車がエリシャを取り巻いて山に満ちていた。'),
('JPN', '列王纪下', 12, 6, 18, 'アラム人がエリシャに向かって下って来たとき、彼は主に祈って言った。「どうか、この民を打って目をくらませてください。」そこで主はエリシャのことばのとおり、彼らを打って目をくらまされた。'),
('JPN', '列王纪下', 12, 6, 19, 'エリシャは彼らに言った。「こちらの道でもない。あちらの町でもない。私について来なさい。あなたがたの捜している人のところへ連れて行ってあげよう。」こうして、彼らをサマリアへ連れて行った。'),
('JPN', '列王纪下', 12, 6, 20, '彼らがサマリアに着くと、エリシャは言った。「主よ、この者たちの目を開いて、見えるようにしてください。」主が彼らの目を開き、彼らが見ると、なんと、自分たちはサマリアの真ん中に来ていた。'),
('JPN', '列王纪下', 12, 6, 21, 'イスラエルの王は彼らを見て、エリシャに言った。「私が打ち殺しましょうか。私が打ち殺しましょうか。わが父よ。」'),
('JPN', '列王纪下', 12, 6, 22, 'エリシャは言った。「打ち殺してはなりません。あなたは、捕虜にした者を自分の剣と弓で打ち殺しますか。彼らにパンと水を与え、食べたり飲んだりさせて、彼らの主君のもとに行かせなさい。」'),
('JPN', '列王纪下', 12, 6, 23, 'そこで、王は彼らのために盛大なもてなしをして、彼らが食べたり飲んだりした後、彼らを帰した。こうして彼らは自分たちの主君のもとに戻って行った。それ以来、アラムの略奪隊は二度とイスラエルの地に侵入しなかった。'),
('JPN', '列王纪下', 12, 6, 24, 'この後、アラムの王ベン・ハダドは全軍を召集し、サマリアに上って来て、これを包囲した。'),
('JPN', '列王纪下', 12, 6, 25, 'サマリアには大飢饉が起こっていて、また彼らが包囲していたので、ろばの頭一つが銀八十シェケルで売られ、鳩の糞一カブの四分の一が銀五シェケルで売られるようになった。'),
('JPN', '列王纪下', 12, 6, 26, 'イスラエルの王が城壁の上を通りかかると、一人の女が彼に叫んだ。「わが主、王よ。お救いください。」'),
('JPN', '列王纪下', 12, 6, 27, '王は言った。「主があなたを救わないのなら、どのようにして、私があなたを救うことができるだろうか。打ち場の物をもってか。それとも、踏み場の物をもってか。」'),
('JPN', '列王纪下', 12, 6, 28, 'それから王は彼女に尋ねた。「いったい、どうしたというのか。」彼女は答えた。「この女が私に『あなたの子どもをよこしなさい。私たちは今日、それを食べて、明日は私の子どもを食べましょう』と言ったのです。'),
('JPN', '列王纪下', 12, 6, 29, 'それで私たちは、私の子どもを煮て食べました。その翌日、私は彼女に『さあ、あなたの子どもをよこしなさい。私たちはそれを食べましょう』と言ったのですが、彼女は自分の子どもを隠してしまったのです。」'),
('JPN', '列王纪下', 12, 6, 30, '王はこの女の言うことを聞くと、自分の衣を引き裂いた。彼は城壁の上を通っていたので、民が見ると、なんと、王は衣の下に粗布を着ていた。'),
('JPN', '列王纪下', 12, 6, 31, '彼は言った。「今日、シャファテの子エリシャの首が彼の上についていれば、神がこの私を幾重にも罰せられますように。」'),
('JPN', '列王纪下', 12, 6, 32, 'エリシャは自分の家に座っていて、長老たちも彼と一緒に座っていた。王は一人の者を自分のもとから遣わした。しかし、その使者がエリシャのところに着く前に、エリシャは長老たちに言った。「あの人殺しが、私の首をはねに人を遣わしたのを知っていますか。気をつけなさい。使者が来たら戸を閉め、戸を押しても入れないようにしなさい。そのうしろに、彼の主君の足音がするではありませんか。」'),
('JPN', '列王纪下', 12, 6, 33, '彼がまだ彼らと話しているうちに、使者が彼のところに下って来て言った。「見よ、これは主からのわざわいだ。これ以上、私は何を主に期待しなければならないのか。」'),
('JPN', '列王纪下', 12, 7, 1, 'エリシャは言った。「主のことばを聞きなさい。主はこう言われる。『明日の今ごろ、サマリアの門で、上等の小麦粉一セアが一シェケルで、大麦二セアが一シェケルで売られるようになる。』」'),
('JPN', '列王纪下', 12, 7, 2, 'しかし、侍従で、王が頼みにしていた者が、神の人に答えて言った。「たとえ主が天に窓を作られたとしても、そんなことがあるだろうか。」そこで、エリシャは言った。「確かに、あなたは自分の目でそれを見るが、それを食べることはできない。」'),
('JPN', '列王纪下', 12, 7, 3, 'さて、ツァラアトに冒された四人の人が、町の門の入り口にいた。彼らは互いに言った。「われわれはどうして死ぬまでここに座っていなければならないのか。'),
('JPN', '列王纪下', 12, 7, 4, 'たとえ町に入ろうと言ったところで、町は食糧難だから、われわれはそこで死ななければならない。ここに座っていても死ぬだけだ。さあ今、アラムの陣営に入り込もう。もし彼らがわれわれを生かしておいてくれるなら、われわれは生き延びられる。もし殺すなら、そのときは死ぬまでのことだ。」'),
('JPN', '列王纪下', 12, 7, 5, 'こうして、彼らはアラムの陣営に行こうと、夕暮れになって立ち上がり、アラムの陣営の端まで来た。すると、なんと、そこにはだれもいなかった。'),
('JPN', '列王纪下', 12, 7, 6, 'これは、主がアラムの陣営に、戦車の響き、馬のいななき、大軍勢の騒ぎを聞かせたので、彼らが口々に「見よ。イスラエルの王が、ヒッタイト人の王たち、エジプトの王たちを雇って、われわれを襲って来る」と言い、'),
('JPN', '列王纪下', 12, 7, 7, '夕暮れに立って逃げ、自分たちの天幕や馬やろば、陣営をそのまま置き去りにして、いのちからがら逃げ去ったからであった。'),
('JPN', '列王纪下', 12, 7, 8, 'ツァラアトに冒されたこの人たちは、陣営の端に来て、一つの天幕に入って食べたり飲んだりし、そこから銀や金や衣服を持ち出して隠した。また戻って来てはほかの天幕に入り、そこからも持ち出して隠した。'),
('JPN', '列王纪下', 12, 7, 9, '彼らは互いに言った。「われわれのしていることは正しくない。今日は良い知らせの日なのに、われわれはためらっている。もし明け方まで待っていたら、罰を受けるだろう。さあ、行こう。行って王の家に知らせよう。」'),
('JPN', '列王纪下', 12, 7, 10, '彼らは町に入って門衛を呼び、彼らに告げた。「われわれがアラムの陣営に入ってみると、なんとそこにはだれの姿もなく、人の声もありませんでした。ただ、馬やろばがつながれたままで、天幕もそっくりそのままでした。」'),
('JPN', '列王纪下', 12, 7, 11, 'そこで門衛たちは叫んで、門内の王の家に告げた。'),
('JPN', '列王纪下', 12, 7, 12, '王は夜中に起きて家来たちに言った。「アラム人がわれわれに対して謀ったことをおまえたちに教えよう。彼らはわれわれが飢えているのを知っているので、陣営から出て行って野に隠れ、『イスラエル人が町から出たら生け捕りにし、それから町に押し入ろう』と考えているのだ。」'),
('JPN', '列王纪下', 12, 7, 13, 'すると、家来の一人が答えた。「それでは、だれかにこの町に残っている馬の中から五頭を取らせ、遣わして調べさせてみましょう。どうせ、この町に残っているイスラエルのすべての民衆も、すでに滅んだイスラエルのすべての民衆と同じ目にあうのですから。」'),
('JPN', '列王纪下', 12, 7, 14, '彼らが二台分の戦車の馬を取ると、王は「行って確かめて来い」と命じて、アラムの軍勢を追わせた。'),
('JPN', '列王纪下', 12, 7, 15, '彼らはアラム人を追って、ヨルダン川まで行った。ところが、なんと、道はいたるところ、アラム人が慌てて逃げるときに捨てていった衣服や武具でいっぱいであった。使者たちは帰って来て、このことを王に報告した。'),
('JPN', '列王纪下', 12, 7, 16, 'そこで、民は出て行ってアラムの陣営をかすめ奪ったので、主のことばのとおり、上等の小麦粉一セアが一シェケルで、大麦二セアが一シェケルで売られた。'),
('JPN', '列王纪下', 12, 7, 17, '王は例の侍従、頼みにしていた侍従を門の管理に当たらせたが、民が門で彼を踏みつけたので、彼は死んだ。王が神の人のところに下って行ったときに、神の人が告げたことばのとおりであった。'),
('JPN', '列王纪下', 12, 7, 18, 'かつて神の人が王に、「明日の今ごろ、サマリアの門で、大麦二セアが一シェケルで、上等の小麦粉一セアが一シェケルで売られるようになる」と言ったときに、'),
('JPN', '列王纪下', 12, 7, 19, '侍従は神の人に答えて、「たとえ主が天に窓を作られるにしても、そんなことがあるだろうか」と言った。そこで、エリシャは「確かに、あなたは自分の目でそれを見るが、それを食べることはできない」と言った。'),
('JPN', '列王纪下', 12, 7, 20, 'そのとおりのことが彼に実現した。民が門で彼を踏みつけたので、彼は死んだ。'),
('JPN', '列王纪下', 12, 8, 1, 'エリシャは、かつて子どもを生き返らせてやったあの女に言った。「あなたは家族の者たちと一緒にここを去り、とどまりたいところに、しばらく寄留していなさい。主が飢饉を起こされたので、この国は七年間、飢えに見舞われるから。」'),
('JPN', '列王纪下', 12, 8, 2, 'この女は神の人のことばにしたがって出発し、家族を連れてペリシテ人の地に行き、七年間滞在した。'),
('JPN', '列王纪下', 12, 8, 3, '七年たった後、彼女はペリシテ人の地から戻って来て、自分の家と畑を得ようと王に訴え出た。'),
('JPN', '列王纪下', 12, 8, 4, 'そのころ、王は神の人に仕える若者ゲハジに、「エリシャが行った大いなるわざを、残らず私に聞かせてくれ」と話していた。'),
('JPN', '列王纪下', 12, 8, 5, '彼が王に、死人を生き返らせたあの出来事を話していると、ちょうどそこに、子どもを生き返らせてもらった女が、自分の家と畑のことについて王に訴えに来た。ゲハジは言った。「王様、これがその女です。そしてこれが、エリシャが生き返らせた子どもです。」'),
('JPN', '列王纪下', 12, 8, 6, '王が彼女に尋ねると、彼女は王にそのことを話した。すると王は彼女のために、一人の宦官に「彼女のすべての物と、彼女がこの地を離れた日から今日までの畑の収穫のすべてを、返してやりなさい」と命じたのであった。'),
('JPN', '列王纪下', 12, 8, 7, 'さて、エリシャがダマスコに行ったとき、アラムの王ベン・ハダドは病気であった。すると彼に「神の人がここまで来ている」という知らせがあった。'),
('JPN', '列王纪下', 12, 8, 8, '王はハザエルに言った。「贈り物を持って行って、神の人を迎え、私のこの病気が治るかどうか、あの人を通して主のみこころを求めてくれ。」'),
('JPN', '列王纪下', 12, 8, 9, 'そこで、ハザエルはダマスコのあらゆる良い物をらくだ四十頭に載せて、贈り物として携え、神の人を迎えに行った。彼は神の人の前に来て立ち、こう言った。「あなたの子、アラムの王ベン・ハダドが、『この病気は治るであろうか』と言って、あなたのところへ私を遣わしました。」'),
('JPN', '列王纪下', 12, 8, 10, 'エリシャは彼に言った。「行って、『あなたは必ず治る』と彼に告げなさい。しかし、主は私に、彼が必ず死ぬことも示された。」'),
('JPN', '列王纪下', 12, 8, 11, '神の人は、彼が恥じるほどじっと彼を見つめ、そして泣き出したので、'),
('JPN', '列王纪下', 12, 8, 12, 'ハザエルは尋ねた。「ご主人様はなぜ泣くのですか。」エリシャは答えた。「私は、あなたがイスラエル人に害を加えようとしていることを知っているからだ。あなたはイスラエル人の要塞に火を放ち、その若い男たちを剣で切り殺し、幼子たちを八つ裂きにし、妊婦たちを切り裂くだろう。」'),
('JPN', '列王纪下', 12, 8, 13, 'ハザエルは言った。「しもべは犬にすぎないのに、どうして、そんな大それたことができるでしょう。」しかし、エリシャは言った。「主は私に、あなたがアラムの王になると示されたのだ。」'),
('JPN', '列王纪下', 12, 8, 14, '彼はエリシャのもとを去り、自分の主君のところに帰った。王が彼に、「エリシャはあなたに何と言ったか」と尋ねると、彼は「あなたは必ず治ると言いました」と答えた。'),
('JPN', '列王纪下', 12, 8, 15, 'しかし、翌日、ハザエルは厚い布を取って水に浸し、王の顔にかぶせたので、王は死んだ。こうして、ハザエルは彼に代わって王となった。'),
('JPN', '列王纪下', 12, 8, 16, 'イスラエルの王アハブの子ヨラムの第五年、ヨシャファテがまだユダの王であったとき、ユダの王ヨシャファテの子ヨラムが王として治めるようになった。'),
('JPN', '列王纪下', 12, 8, 17, '彼は三十二歳で王となり、エルサレムで八年間、王であった。'),
('JPN', '列王纪下', 12, 8, 18, '彼はアハブの家の者がしたように、イスラエルの王たちの道に歩んだ。アハブの娘が彼の妻だったからである。彼は主の目に悪であることを行った。'),
('JPN', '列王纪下', 12, 8, 19, 'しかし、主はそのしもべダビデに免じて、ユダを滅ぼすことを望まれなかった。主はダビデとその子孫に常にともしびを与えると彼に約束されたからである。'),
('JPN', '列王纪下', 12, 8, 20, 'ヨラムの時代に、エドムが背いてユダの支配から脱し、自分たちの上に王を立てた。'),
('JPN', '列王纪下', 12, 8, 21, 'ヨラムは、すべての戦車を率いてツァイルへ渡って行き、夜襲を試みて、彼を包囲していたエドムと戦車隊長たちを討った。ところが、ヨラムの兵たちは自分たちの天幕に逃げ帰った。'),
('JPN', '列王纪下', 12, 8, 22, 'エドムは背いてユダの支配から脱した。今日もそうである。リブナもそのときに背こうとした。'),
('JPN', '列王纪下', 12, 8, 23, 'ヨラムについてのその他の事柄、彼が行ったすべてのこと、それは『ユダの王の歴代誌』に確かに記されている。'),
('JPN', '列王纪下', 12, 8, 24, 'ヨラムは先祖とともに眠りにつき、先祖とともにダビデの町に葬られた。彼の子アハズヤが代わって王となった。'),
('JPN', '列王纪下', 12, 8, 25, 'イスラエルの王アハブの子ヨラムの第十二年に、ユダの王ヨラムの子アハズヤが王となった。'),
('JPN', '列王纪下', 12, 8, 26, 'アハズヤは二十二歳で王となり、エルサレムで一年間、王であった。彼の母の名はアタルヤといい、イスラエルの王オムリの孫娘であった。'),
('JPN', '列王纪下', 12, 8, 27, '彼はアハブの家の道に歩み、アハブの家に倣って主の目の前に悪であることを行った。彼自身、アハブ家の婿だったからである。'),
('JPN', '列王纪下', 12, 8, 28, '彼はアハブの子ヨラムとともに、アラムの王ハザエルと戦うため、ラモテ・ギルアデに行った。アラム人はヨラムを討った。'),
('JPN', '列王纪下', 12, 8, 29, 'ヨラム王は、アラムの王ハザエルと戦ったときにラマでアラム人に負わされた傷を癒やすため、イズレエルに帰った。ユダの王ヨラムの子アハズヤは、アハブの子ヨラムが弱っていたので、彼を見舞いにイズレエルに下って行った。'),
('JPN', '列王纪下', 12, 9, 1, '預言者エリシャは預言者の仲間たちの一人を呼んで言った。「腰に帯を締め、手にこの油の壺を持って、ラモテ･ギルアデに行きなさい。'),
('JPN', '列王纪下', 12, 9, 2, 'そこに行ったら、ニムシの子ヨシャファテの子エフーを見つけなさい。家に入って、その同僚たちの中から彼を立たせ、奥の間に連れて行き、'),
('JPN', '列王纪下', 12, 9, 3, '油の壺を取って、彼の頭の上に油を注いで言いなさい。『主はこう言われる。わたしはあなたに油を注いでイスラエルの王とする。』それから、戸を開け、ぐずぐずしていないで逃げなさい。」'),
('JPN', '列王纪下', 12, 9, 4, 'その若者、預言者に仕える若者は、ラモテ・ギルアデに行った。'),
('JPN', '列王纪下', 12, 9, 5, '彼が来てみると、ちょうど、軍の高官たちが会議中であった。彼は言った。「隊長、申し上げることがございます。」エフーは言った。「このわれわれのうちのだれにか。」若者は「隊長、あなたにです」と答えた。'),
('JPN', '列王纪下', 12, 9, 6, 'エフーは立って、家に入った。そこで若者は油をエフーの頭に注いで言った。「イスラエルの神、主はこう言われる。『わたしはあなたに油を注いで、主の民イスラエルの王とする。'),
('JPN', '列王纪下', 12, 9, 7, 'あなたは、主君アハブの家の者を打ち殺さなければならない。こうしてわたしは、わたしのしもべである預言者たちの血、イゼベルによって流されたすべての主のしもべたちの血の復讐をする。'),
('JPN', '列王纪下', 12, 9, 8, 'それでアハブの家はことごとく滅び失せる。わたしは、イスラエルの中の、アハブに属する小童から奴隷や自由の者に至るまでを絶ち滅ぼし、'),
('JPN', '列王纪下', 12, 9, 9, 'アハブの家をネバテの子ヤロブアムの家のように、またアヒヤの子バアシャの家のようにする。'),
('JPN', '列王纪下', 12, 9, 10, '犬がイズレエルの地所でイゼベルを食らい、彼女を葬る者はだれもいない。』」こう言って、彼は戸を開けて逃げた。'),
('JPN', '列王纪下', 12, 9, 11, 'エフーが彼の主君の家来たちのところに出て来ると、一人が彼に尋ねた。「何事もなかったのですか。あの気のふれた者は何のために来たのですか。」すると、エフーは彼らに答えた。「あなたたちは、あの男も、あの男の言ったこともよく知っているはずだ。」'),
('JPN', '列王纪下', 12, 9, 12, '彼らは言った。「噓でしょう。われわれに教えてください。」そこで、彼は答えた。「あの男は私にこんなことを言った。『主はこう言われる。わたしはあなたに油を注いで、イスラエルの王とする』と。」'),
('JPN', '列王纪下', 12, 9, 13, 'すると、彼らはみな大急ぎで自分の上着を脱ぎ、入り口の階段にいた彼の足もとに敷き、角笛を吹き鳴らして、「エフーは王である」と言った。'),
('JPN', '列王纪下', 12, 9, 14, 'こうして、ニムシの子ヨシャファテの子エフーは、ヨラムに対して謀反を起こした。先にヨラムはイスラエル全軍を率いて、ラモテ･ギルアデでアラムの王ハザエルを防いだが、'),
('JPN', '列王纪下', 12, 9, 15, 'ヨラム王は、アラムの王ハザエルと戦ったときにアラム人に負わされた傷を癒やすため、イズレエルに帰っていたのである。エフーは言った。「もし、これがあなたたちの本心であるなら、だれもこの町から逃れ出て、イズレエルに知らせに行ってはならない。」'),
('JPN', '列王纪下', 12, 9, 16, 'それからエフーは車に乗ってイズレエルへ行った。ヨラムがそこで床についていて、ユダの王アハズヤもヨラムを見舞いに下っていたからである。'),
('JPN', '列王纪下', 12, 9, 17, 'イズレエルのやぐらの上に、一人の見張りが立っていたが、エフーの軍勢がやって来るのを見て、「軍勢が見える」と言った。ヨラムは、「騎兵一人を選んで彼らを迎えに送り、元気かどうか尋ねさせなさい」と言った。'),
('JPN', '列王纪下', 12, 9, 18, 'そこで、騎兵は彼を迎えに行き、こう言った。「王が、元気かどうか尋ねておられます。」エフーは言った。「元気かどうか、おまえの知ったことではない。私のうしろについて来い。」一方、見張りは報告して言った。「使者は彼らのところに着きましたが、帰って来ません。」'),
('JPN', '列王纪下', 12, 9, 19, 'そこでヨラムは、もう一人の騎兵を送った。彼は彼らのところに行って言った。「王が、元気かどうか尋ねておられます。」すると、エフーは言った。「元気かどうか、おまえの知ったことではない。私のうしろについて来い。」'),
('JPN', '列王纪下', 12, 9, 20, '見張りはまた報告した。「あれは彼らのところに着きましたが、帰って来ません。しかし、車の御し方は、ニムシの子エフーの御し方に似ています。狂ったように御しています。」'),
('JPN', '列王纪下', 12, 9, 21, 'ヨラムは「馬をつけよ」と命じた。馬が戦車につけられると、イスラエルの王ヨラムとユダの王アハズヤは、それぞれ自分の戦車に乗って出て行った。彼らはエフーを迎えに出て行き、イズレエル人ナボテの所有地で彼に出会った。'),
('JPN', '列王纪下', 12, 9, 22, 'ヨラムはエフーを見ると、「エフー、元気か」と尋ねた。エフーは答えた。「何が元気か。あなたの母イゼベルの姦淫と呪術が盛んに行われているのに。」'),
('JPN', '列王纪下', 12, 9, 23, 'それでヨラムは手綱を返して逃げ、アハズヤに「裏切りだ、アハズヤ」と叫んだ。'),
('JPN', '列王纪下', 12, 9, 24, 'エフーは力いっぱい弓を引き絞り、ヨラムの胸を射た。矢は彼の心臓を射抜いたので、彼は戦車の中に崩れ落ちた。'),
('JPN', '列王纪下', 12, 9, 25, 'エフーは侍従のビデカルに命じた。「彼を運んで、イズレエル人ナボテの所有地であった畑に投げ捨てよ。思い起こすがよい。私とあなたが馬に乗って彼の父アハブの後に並んで従って行ったときに、主が彼についてこの宣告を下されたことを。'),
('JPN', '列王纪下', 12, 9, 26, '『わたしは、昨日、ナボテの血とその子たちの血を確かに見届けた──主のことば──。わたしは、この地所であなたに報復する──主のことば。』それで今、彼を運んで、主が語られたとおり、あの地所に彼を投げ捨てよ。」'),
('JPN', '列王纪下', 12, 9, 27, 'ユダの王アハズヤはこれを見ると、ベテ・ハ・ガンの道へ逃げた。エフーはその後を追いかけて、「あいつも討ち取れ」と叫んだので、彼らはイブレアムのそばのグルの坂道で、車の上の彼に傷を負わせた。それでも彼はメギドに逃げたが、そこで死んだ。'),
('JPN', '列王纪下', 12, 9, 28, '彼の家来たちは彼を車に乗せて、エルサレムに運び、ダビデの町の彼の墓に先祖とともに葬った。'),
('JPN', '列王纪下', 12, 9, 29, 'アハズヤはアハブの子ヨラムの第十一年に、ユダの王となっていた。'),
('JPN', '列王纪下', 12, 9, 30, 'エフーがイズレエルに来たとき、イゼベルはこれを聞いて、目の縁を塗り、髪を結い直して、窓から見下ろしていた。'),
('JPN', '列王纪下', 12, 9, 31, 'エフーが門に入って来たので、彼女は「お元気ですか。主君殺しのジムリ」と言った。'),
('JPN', '列王纪下', 12, 9, 32, '彼は窓を見上げて、「だれか私にくみする者はいないか。だれかいないか」と言った。二、三人の宦官が彼を見下ろしていたので、'),
('JPN', '列王纪下', 12, 9, 33, '彼が「その女を突き落とせ」と言うと、彼らは彼女を突き落とし、彼女の血が壁や馬にはねかかった。エフーは彼女を踏みつけた。'),
('JPN', '列王纪下', 12, 9, 34, '彼は中に入って食べたり飲んだりし、それから言った。「あののろわれた女の世話をしてやれ。彼女を葬ってやれ。あれは王の娘だから。」'),
('JPN', '列王纪下', 12, 9, 35, '彼らが彼女を葬りに行ってみると、彼女の頭蓋骨と両足と両手首しか残っていなかったので、'),
('JPN', '列王纪下', 12, 9, 36, '帰って来てエフーにこのことを知らせた。するとエフーは言った。「これは、主がそのしもべティシュベ人エリヤによって語られたことばのとおりだ。『イズレエルの地所で犬がイゼベルの肉を食らい、'),
('JPN', '列王纪下', 12, 9, 37, 'イゼベルの死体は、イズレエルの地所で畑の上にまかれた肥やしのようになり、だれもこれがイゼベルだと言えなくなる。』」'),
('JPN', '列王纪下', 12, 10, 1, 'アハブにはサマリアに七十人の子どもがあった。エフーは手紙を書いてサマリアに送り、イズレエルの長たちや長老たち、および、アハブの子の養育係たちにこう伝えた。'),
('JPN', '列王纪下', 12, 10, 2, '「この手紙が届いたら、あなたがたのところに、あなたがたの主君の子どもたちがいて、戦車や馬も、城壁のある町や武器も、あなたがたのところにあるのだから、すぐ、'),
('JPN', '列王纪下', 12, 10, 3, 'あなたがたの主君の子どもの中から最も善良で真っ直ぐな人物を選んで、その父の王座に就かせ、あなたがたの主君の家のために戦え。」'),
('JPN', '列王纪下', 12, 10, 4, '彼らは非常に恐れて言った。「二人の王たちでさえ、彼に当たることができなかったのに、どうしてこのわれわれが当たることができるだろうか。」'),
('JPN', '列王纪下', 12, 10, 5, 'そこで、宮廷長官、町のつかさ、長老たち、および養育係たちは、エフーに人を送って言った。「私どもはあなたのしもべです。あなたが私どもにお命じになることは何でもいたしますが、だれも王に立てるつもりはありません。あなたのお気に召すようにしてください。」'),
('JPN', '列王纪下', 12, 10, 6, 'エフーは再び彼らに手紙を書いてこう言った。「もしあなたがたが私に味方し、私の声に聞くのなら、あなたがたの主君の子どもたちの首を取り、明日の今ごろ、イズレエルの私のもとに持って来るように。」そのころ、王の子どもたち七十人は、彼らを養育していた町のおもだった人たちのもとにいた。'),
('JPN', '列王纪下', 12, 10, 7, 'その手紙が彼らに届くと、彼らは王の子どもたちを捕らえ、その七十人を切り殺し、その首をいくつかのかごに入れ、それをイズレエルのエフーのもとに送り届けた。'),
('JPN', '列王纪下', 12, 10, 8, '使者が来て、「彼らは王の子どもたちの首を持って参りました」とエフーに報告した。すると彼は、「それを二つに分けて積み重ね、朝まで門の入り口に置いておけ」と命じた。'),
('JPN', '列王纪下', 12, 10, 9, '朝になるとエフーは出て行き、立ってすべての民に言った。「あなたたちに罪はない。聞きなさい。私が主君に対して謀反を起こして、彼を殺したのだ。しかし、これらの者を皆殺しにしたのはだれか。'),
('JPN', '列王纪下', 12, 10, 10, 'だから知れ。主がアハブの家について告げられた主のことばは一つも地に落ちないことを。主は、そのしもべエリヤによってお告げになったことをなされたのだ。」'),
('JPN', '列王纪下', 12, 10, 11, 'エフーは、アハブの家に属する者でイズレエルに残っていたすべての者、身分の高い者、親しい者、その祭司たちをみな打ち殺し、一人も生き残る者がないまでにした。'),
('JPN', '列王纪下', 12, 10, 12, 'それから、エフーは立ってサマリアへ行った。その途中、羊飼いのベテ・エケデというところで、'),
('JPN', '列王纪下', 12, 10, 13, 'エフーはユダの王アハズヤの身内の者たちに出会った。彼が「おまえたちはだれか」と聞くと、彼らは、「私たちはアハズヤの身内の者です。王の子どもたちと、王母の子どもたちの安否を尋ねに下って来ました」と答えた。'),
('JPN', '列王纪下', 12, 10, 14, 'エフーが「彼らを生け捕りにせよ」と言ったので、人々は彼らを生け捕りにした。そして、ベテ･エケデの水溜め場で彼ら四十二人を殺し、一人も残さなかった。'),
('JPN', '列王纪下', 12, 10, 15, '彼がそこを去って行くと、彼を迎えに来たレカブの子ヨナダブに出会った。エフーは彼にあいさつして言った。「あなたの心は、私の心があなたの心に対してそうであるように、真っ直ぐですか。」ヨナダブは、「そうです」と答えた。「そうなら、こちらに手を伸ばしなさい。」ヨナダブが手を差し出すと、エフーは彼を戦車の上に引き上げて、'),
('JPN', '列王纪下', 12, 10, 16, '「私と一緒に来て、主に対する私の熱心さを見なさい」と言った。エフーは彼を自分の戦車に乗せて、'),
('JPN', '列王纪下', 12, 10, 17, 'サマリアに行った。エフーは、アハブに属する者でサマリアに残っていた者を皆殺しにし、その一族を根絶やしにした。主がエリヤにお告げになったことばのとおりであった。'),
('JPN', '列王纪下', 12, 10, 18, 'エフーはすべての民を集めて、彼らに言った。「アハブは少ししかバアルに仕えなかったが、エフーは大いに仕えるつもりだ。'),
('JPN', '列王纪下', 12, 10, 19, 'だから今、バアルの預言者や、その信者、およびその祭司たちをみな、私のところに呼び寄せよ。一人も欠けてはならない。私は大いなるいけにえをバアルに献げるつもりである。列席しない者は、だれも生かしてはおかない。」エフーは、バアルの信者たちを滅ぼすために、策略をめぐらしたのである。'),
('JPN', '列王纪下', 12, 10, 20, 'エフーが、「バアルのためにきよめの集会を催せ」と命じると、彼らはこれを布告した。'),
('JPN', '列王纪下', 12, 10, 21, 'エフーが全イスラエルに人を遣わしたので、バアルの信者たちがみなやって来た。残っていて、来なかった者は一人もいなかった。彼らがバアルの神殿に入ると、バアルの神殿は端から端までいっぱいになった。'),
('JPN', '列王纪下', 12, 10, 22, 'エフーが衣装係に、「バアルの信者すべてに祭服を出してやれ」と命じたので、彼らのために祭服を取り出した。'),
('JPN', '列王纪下', 12, 10, 23, 'エフーとレカブの子ヨナダブは、バアルの神殿に入り、バアルの信者たちに言った。「よく見回して、ここには主のしもべがあなたがたと一緒に一人もおらず、ただバアルの信者たちだけがいるようにせよ。」'),
('JPN', '列王纪下', 12, 10, 24, 'こうして彼らは、いけにえと全焼のささげ物を献げる準備をした。エフーは八十人の者を神殿の外に配置して言った。「私がおまえたちの手に渡す者を一人でも逃す者があれば、そのいのちを、逃れた者のいのちに代える。」'),
('JPN', '列王纪下', 12, 10, 25, '全焼のささげ物を献げ終えたとき、エフーは近衛兵と侍従たちに言った。「入って行って、彼らを討ち取れ。一人も外に出すな。」そこで、近衛兵と侍従たちは剣の刃で彼らを討って投げ捨て、バアルの神殿の奥の間にまで踏み込んだ。'),
('JPN', '列王纪下', 12, 10, 26, 'そして、バアルの神殿の石の柱を運び出して、これを焼き、'),
('JPN', '列王纪下', 12, 10, 27, 'バアルの石の柱を打ち壊し、バアルの神殿も打ち壊し、これを便所とした。それは今日まで残っている。'),
('JPN', '列王纪下', 12, 10, 28, 'このようにして、エフーはバアルをイスラエルから根絶やしにした。'),
('JPN', '列王纪下', 12, 10, 29, 'ただしエフーは、イスラエルに罪を犯させたネバテの子ヤロブアムの罪、すなわち、ベテルとダンにあった金の子牛に仕えることから離れようとはしなかった。'),
('JPN', '列王纪下', 12, 10, 30, '主はエフーに言われた。「あなたはわたしの目にかなったことをよくやり遂げ、アハブの家に対して、わたしが心に定めたことをことごとく行ったので、あなたの子孫は四代目まで、イスラエルの王座に就く。」'),
('JPN', '列王纪下', 12, 10, 31, 'しかしエフーは、心を尽くしてイスラエルの神、主の律法に歩もうと心がけることをせず、イスラエルに罪を犯させたヤロブアムの罪から離れなかった。'),
('JPN', '列王纪下', 12, 10, 32, 'そのころ、主はイスラエルを少しずつ削り始めておられた。ハザエルがイスラエルの全領土で彼らを打ち破ったのである。'),
('JPN', '列王纪下', 12, 10, 33, 'すなわち、ヨルダン川の東側、ガド人、ルベン人、マナセ人のギルアデ全土、つまり、アルノン川のほとりにあるアロエルからギルアデ、バシャンの地方にまで及んだ。'),
('JPN', '列王纪下', 12, 10, 34, 'エフーについてのその他の事柄、彼が行ったすべてのこと、彼のすべての功績、それは『イスラエルの王の歴代誌』に確かに記されている。'),
('JPN', '列王纪下', 12, 10, 35, 'エフーは先祖とともに眠りにつき、人々は彼をサマリアに葬った。彼の子エホアハズが代わって王となった。'),
('JPN', '列王纪下', 12, 10, 36, 'エフーがサマリアでイスラエルの王であった期間は二十八年であった。'),
('JPN', '列王纪下', 12, 11, 1, 'アハズヤの母アタルヤは、自分の子が死んだと知ると、ただちに王の一族全員を滅ぼした。'),
('JPN', '列王纪下', 12, 11, 2, 'しかし、ヨラム王の娘で、アハズヤの姉妹のエホシェバは、殺される王の子たちの中からアハズヤの子ヨアシュをこっそり連れ出し、寝具をしまう小部屋にその子とその乳母を入れた。人々が彼をアタルヤから隠したので、彼は殺されなかった。'),
('JPN', '列王纪下', 12, 11, 3, '彼は乳母とともに、主の宮に六年間、身を隠していた。その間、アタルヤが国を治めていた。'),
('JPN', '列王纪下', 12, 11, 4, '七年目に、エホヤダは人を遣わして、カリ人と近衛兵それぞれの百人隊の長たちを主の宮の自分のもとに来させ、彼らと契約を結んで主の宮で彼らに誓いを立てさせ、彼らに王の子を見せた。'),
('JPN', '列王纪下', 12, 11, 5, '彼は命じた。「あなたがたのなすべきことはこうだ。あなたがたのうちの三分の一は、安息日に務めに当たり、王宮の護衛の任務につく。'),
('JPN', '列王纪下', 12, 11, 6, '三分の一はスルの門に、もう三分の一は近衛兵舎の裏の門にいるように。あなたがたは交互に王宮の護衛の任務につく。'),
('JPN', '列王纪下', 12, 11, 7, 'あなたがたのうち二組は、みな安息日に務めに当たらない者であるが、主の宮で王の護衛の任務につかなければならない。'),
('JPN', '列王纪下', 12, 11, 8, 'それぞれ武器を手にして王の周りを囲め。その列を侵す者は殺されなければならない。あなたがたは、王が出るときにも入るときにも、王とともにいなさい。」'),
('JPN', '列王纪下', 12, 11, 9, '百人隊の長たちは、すべて祭司エホヤダが命じたとおりに行った。彼らは、それぞれ自分の部下たちを、安息日に務めに当たる者も、安息日に務めに当たらない者も、祭司エホヤダのところに連れて来た。'),
('JPN', '列王纪下', 12, 11, 10, '祭司は百人隊の長たちに、主の宮にあったダビデ王の槍と丸い小盾を与えた。'),
('JPN', '列王纪下', 12, 11, 11, '近衛兵たちはそれぞれ武器を手にして、神殿の右側から神殿の左側まで、祭壇と神殿に向かって王の周りに立った。'),
('JPN', '列王纪下', 12, 11, 12, 'エホヤダは王の子を連れ出し、王冠をかぶらせ、さとしの書を渡した。こうして人々は彼を王と宣言し、彼に油を注ぎ、手をたたいて「王様万歳」と叫んだ。'),
('JPN', '列王纪下', 12, 11, 13, 'アタルヤは近衛兵と民の声を聞いて、主の宮の民のところに行った。'),
('JPN', '列王纪下', 12, 11, 14, '彼女が見ると、なんと、王が定めのとおりに柱のそばに立っていた。王の傍らに隊長たちやラッパ奏者たちがいて、民衆がみな喜んでラッパを吹き鳴らしていた。アタルヤは自分の衣を引き裂き、「謀反だ、謀反だ」と叫んだ。'),
('JPN', '列王纪下', 12, 11, 15, '祭司エホヤダは、部隊を委ねられた百人隊の長たちに命じた。「この女を列の間から連れ出せ。この女に従って来る者は剣で殺せ。」祭司が「この女は主の宮で殺されてはならない」と言ったからである。'),
('JPN', '列王纪下', 12, 11, 16, '彼らは彼女を取り押さえた。彼女が馬の出入り口を通って王宮に着くと、彼女はそこで殺された。'),
('JPN', '列王纪下', 12, 11, 17, 'エホヤダは、主と、王および民との間で、彼らが主の民となるという契約を結ばせ、王と民との間でも契約を結ばせた。'),
('JPN', '列王纪下', 12, 11, 18, '民衆はみなバアルの神殿に行って、それを打ち壊した。彼らはその祭壇と像を徹底的に打ち砕き、バアルの祭司マタンを祭壇の前で殺した。祭司エホヤダは主の宮に管理人を置いた。'),
('JPN', '列王纪下', 12, 11, 19, '彼は百人隊の長たち、カリ人、近衛兵たちと民衆すべてを率いた。彼らは王を主の宮から連れて下り、近衛兵の門を通って王宮に入った。王は王の座に着いた。'),
('JPN', '列王纪下', 12, 11, 20, '民衆はみな喜んだ。アタルヤは王宮で剣で殺され、この町は平穏となった。'),
('JPN', '列王纪下', 12, 11, 21, 'ヨアシュは七歳で王となった。'),
('JPN', '列王纪下', 12, 12, 1, 'ヨアシュはエフーの第七年に王となり、エルサレムで四十年間、王であった。彼の母の名はツィブヤといい、ベエル・シェバ出身であった。'),
('JPN', '列王纪下', 12, 12, 2, 'ヨアシュは、祭司エホヤダが彼を教えた間、いつも主の目にかなうことを行った。'),
('JPN', '列王纪下', 12, 12, 3, 'ただし、高き所は取り除かれなかった。民はなおも、その高き所でいけにえを献げたり、犠牲を供えたりしていた。'),
('JPN', '列王纪下', 12, 12, 4, 'ヨアシュは祭司たちに言った。「主の宮に献げられる、聖別された金のすべて、すなわち、それぞれに割り当てを課せられた金や、自発的に主の宮に献げられる金のすべては、'),
('JPN', '列王纪下', 12, 12, 5, '祭司たちが、それぞれ自分の担当する者から受け取りなさい。神殿のどこかが破損していれば、その破損の修繕にそれを充てなければならない。」'),
('JPN', '列王纪下', 12, 12, 6, 'しかし、ヨアシュ王の第二十三年になっても、祭司たちは神殿の破損を修理しなかった。'),
('JPN', '列王纪下', 12, 12, 7, 'ヨアシュ王は、祭司エホヤダと祭司たちを呼んで、彼らに言った。「なぜ、神殿の破損を修理しないのか。もう、あなたがたは、自分の担当する者たちから金を受け取ってはならない。神殿の破損にそれを充てなければならないからだ。」'),
('JPN', '列王纪下', 12, 12, 8, '祭司たちは、民から金を受け取らないことと、神殿の破損の修理に責任を持たないことに同意した。'),
('JPN', '列王纪下', 12, 12, 9, '祭司エホヤダは、一つの箱を取り、そのふたに穴を開け、それを祭壇のわき、主の宮の入り口の右側に置いた。こうして、入り口を守る祭司たちは、主の宮に納められる金をみな、そこに入れた。'),
('JPN', '列王纪下', 12, 12, 10, '箱の中に金が多くなるのを確認すると、王の書記と大祭司は上って来て、それを袋に入れ、主の宮に納められている金を計算した。'),
('JPN', '列王纪下', 12, 12, 11, 'こうして、勘定された金は、主の宮で工事をしている監督者たちの手に渡された。彼らは、それを主の宮を造る木工と建築する者たち、'),
('JPN', '列王纪下', 12, 12, 12, '石工、石切り工に支払い、また、主の宮の破損修理のための木材や切り石を買うために支払った。つまり、金は神殿修理のための出費のすべてに充てられた。'),
('JPN', '列王纪下', 12, 12, 13, 'ただし、主の宮のための銀の皿、芯取りばさみ、鉢、ラッパなど、いかなる金の用具、銀の用具も、主の宮に納められる金で作られることはなかった。'),
('JPN', '列王纪下', 12, 12, 14, 'その金は、工事する者たちに渡され、彼らはそれと引き替えに主の宮を修理したからである。'),
('JPN', '列王纪下', 12, 12, 15, 'また、工事する者に支払うように金を渡した人々が精算を求められることはなかった。彼らが忠実に働いていたからである。'),
('JPN', '列王纪下', 12, 12, 16, '代償のささげ物の金と、罪のきよめのささげ物の金は、主の宮に納められず、祭司たちのものとなった。'),
('JPN', '列王纪下', 12, 12, 17, 'そのとき、アラムの王ハザエルが上って来てガテを攻め、これを取った。さらに、ハザエルはエルサレムを目指して攻め上った。'),
('JPN', '列王纪下', 12, 12, 18, 'ユダの王ヨアシュは、自分の先祖であるユダの王ヨシャファテ、ヨラム、アハズヤが聖別して献げたすべての物、および自分自身が聖別して献げた物、主の宮と王宮の宝物倉にあるすべての金を取って、アラムの王ハザエルに送った。するとハザエルはエルサレムから去って行った。'),
('JPN', '列王纪下', 12, 12, 19, 'ヨアシュについてのその他の事柄、彼が行ったすべてのこと、それは『ユダの王の歴代誌』に確かに記されている。'),
('JPN', '列王纪下', 12, 12, 20, 'ヨアシュの家来たちは立ち上がって謀反を起こし、シラに下って行くヨアシュをベテ・ミロで打ち殺した。'),
('JPN', '列王纪下', 12, 12, 21, '彼の家来シムアテの子ヨザバデとショメルの子エホザバデが彼を討ったので、彼は死んだ。人々は彼をダビデの町に先祖とともに葬った。彼の子アマツヤが代わって王となった。'),
('JPN', '列王纪下', 12, 13, 1, 'ユダの王アハズヤの子ヨアシュの第二十三年に、エフーの子エホアハズがサマリアでイスラエルの王となり、十七年間、王であった。'),
('JPN', '列王纪下', 12, 13, 2, '彼は主の目に悪であることを行い、イスラエルに罪を犯させたネバテの子ヤロブアムの罪を犯し続け、それから離れなかった。'),
('JPN', '列王纪下', 12, 13, 3, 'そのため、主の怒りがイスラエルに向かって燃え上がり、主は彼らをアラムの王ハザエル、および、ハザエルの子ベン・ハダドの手に絶えず渡しておられた。'),
('JPN', '列王纪下', 12, 13, 4, 'しかし、エホアハズが主に願ったので、主はこれを聞き入れられた。アラムの王の虐げによって、イスラエルが虐げられているのをご覧になったからである。'),
('JPN', '列王纪下', 12, 13, 5, '主がイスラエルに一人の救う者を与えられたので、彼らはアラムの支配を脱した。こうしてイスラエル人は以前のように、自分たちの天幕に住むようになった。'),
('JPN', '列王纪下', 12, 13, 6, 'それにもかかわらず、彼らは、イスラエルに罪を犯させたヤロブアム家の罪から離れず、なおそれを行い続け、アシェラ像もサマリアに立ったままであった。'),
('JPN', '列王纪下', 12, 13, 7, 'また、アラムの王が彼らを滅ぼして、打穀のときのちりのようにしたので、エホアハズには騎兵五十、戦車十、歩兵一万の軍隊しか残されていなかった。'),
('JPN', '列王纪下', 12, 13, 8, 'エホアハズについてのその他の事柄、彼が行ったすべてのこと、その功績、それは『イスラエルの王の歴代誌』に確かに記されている。'),
('JPN', '列王纪下', 12, 13, 9, 'エホアハズは先祖とともに眠りにつき、人々は彼をサマリアに葬った。彼の子ヨアシュが代わって王となった。'),
('JPN', '列王纪下', 12, 13, 10, 'ユダの王ヨアシュの第三十七年に、エホアハズの子ヨアシュがサマリアでイスラエルの王となり、十六年間、王であった。'),
('JPN', '列王纪下', 12, 13, 11, '彼は主の目に悪であることを行い、イスラエルに罪を犯させたネバテの子ヤロブアムのすべての罪から離れず、なおそれを行い続けた。'),
('JPN', '列王纪下', 12, 13, 12, 'ヨアシュについてのその他の事柄、彼が行ったすべてのこと、ユダの王アマツヤと戦ったその功績、それは『イスラエルの王の歴代誌』に確かに記されている。'),
('JPN', '列王纪下', 12, 13, 13, 'ヨアシュは先祖とともに眠りにつき、ヤロブアムがその王座に就いた。ヨアシュはイスラエルの王たちとともにサマリアに葬られた。'),
('JPN', '列王纪下', 12, 13, 14, 'エリシャが死の病をわずらっていたときのことである。イスラエルの王ヨアシュは、彼のところに下って行き、彼の上に泣き伏して、「わが父、わが父。イスラエルの戦車と騎兵たち」と叫んだ。'),
('JPN', '列王纪下', 12, 13, 15, 'エリシャが王に「弓と矢を持って来なさい」と言ったので、王は弓と矢をエリシャのところに持って来た。'),
('JPN', '列王纪下', 12, 13, 16, 'エリシャはイスラエルの王に「弓に手をかけなさい」と言ったので、王は手をかけた。すると、エリシャは自分の手を王の手の上に置いて、'),
('JPN', '列王纪下', 12, 13, 17, '「東側の窓を開けなさい」と言った。王が開けると、エリシャはさらに言った。「矢を射なさい。」彼が矢を射ると、エリシャは言った。「主の勝利の矢、アラムに対する勝利の矢。あなたはアフェクでアラムを討ち、これを絶ち滅ぼす。」'),
('JPN', '列王纪下', 12, 13, 18, 'それからエリシャは、「矢を取りなさい」と言ったので、イスラエルの王は取った。そしてエリシャは王に「それで地面を打ちなさい」と言った。すると彼は三回打ったが、それでやめた。'),
('JPN', '列王纪下', 12, 13, 19, '神の人は彼に激怒して言った。「あなたは五回も六回も打つべきだった。そうすれば、あなたはアラムを討って、絶ち滅ぼすことになっただろう。しかし、今は三回だけアラムを討つことになる。」'),
('JPN', '列王纪下', 12, 13, 20, 'こうして、エリシャは死んで葬られた。モアブの略奪隊は、年が改まるたびにこの国に侵入していた。'),
('JPN', '列王纪下', 12, 13, 21, '人々が、一人の人を葬ろうとしていたちょうどそのとき、略奪隊を見たので、その人をエリシャの墓に投げ入れて去って行った。その人がエリシャの骨に触れるやいなや、その人は生き返り、自分の足で立ち上がった。'),
('JPN', '列王纪下', 12, 13, 22, 'アラムの王ハザエルは、エホアハズの生きている間中、イスラエル人を虐げたが、'),
('JPN', '列王纪下', 12, 13, 23, '主は、アブラハム、イサク、ヤコブとの契約のゆえに、彼らを恵み、あわれみ、顧みて、彼らを滅ぼし尽くすことは望まず、今日まで、御顔を背けて彼らを捨てることはなさらなかった。'),
('JPN', '列王纪下', 12, 13, 24, 'アラムの王ハザエルは死に、その子ベン・ハダドが代わって王となった。'),
('JPN', '列王纪下', 12, 13, 25, 'エホアハズの子ヨアシュは、その父エホアハズの手からハザエルが攻め取った町々を、ハザエルの子ベン・ハダドの手から取り返した。ヨアシュは三度彼を打ち破って、イスラエルの町々を取り返した。'),
('JPN', '列王纪下', 12, 14, 1, 'イスラエルの王エホアハズの子ヨアシュの第二年に、ユダの王ヨアシュの子アマツヤが王となった。'),
('JPN', '列王纪下', 12, 14, 2, '彼は二十五歳で王となり、エルサレムで二十九年間、王であった。彼の母の名はエホアダンといい、エルサレム出身であった。'),
('JPN', '列王纪下', 12, 14, 3, '彼は主の目にかなうことを行った。ただし、彼の父祖ダビデのようではなく、すべて父ヨアシュが行ったとおりに行った。'),
('JPN', '列王纪下', 12, 14, 4, 'すなわち、高き所は取り除かれなかった。民はなおも、その高き所でいけにえを献げたり、犠牲を供えたりしていた。'),
('JPN', '列王纪下', 12, 14, 5, '王国が彼の手によって強くなると、彼は、自分の父である王を討った家来たちを打ち殺した。'),
('JPN', '列王纪下', 12, 14, 6, 'しかし、その殺害者の子どもたちは殺さなかった。モーセの律法の書に記されているところに基づいてのことであった。主はその中でこう命じておられた。「父が子のゆえに殺されてはならない。子が父のゆえに殺されてはならない。人が殺されるのは、ただ自分の罪過のゆえでなければならない。」'),
('JPN', '列王纪下', 12, 14, 7, 'アマツヤは塩の谷で一万人のエドム人を討って、セラを取り、その場所をヨクテエルと呼んだ。今日もそうである。'),
('JPN', '列王纪下', 12, 14, 8, 'そのときアマツヤは、エフーの子エホアハズの子、イスラエルの王ヨアシュに使者を送って言った。「さあ、直接、対決しようではないか。」'),
('JPN', '列王纪下', 12, 14, 9, 'イスラエルの王ヨアシュは、ユダの王アマツヤに人を遣わして言った。「レバノンのあざみが、レバノンの杉に人を遣わして、『あなたの娘を私の息子の妻にくれないか』と言ったが、レバノンの野の獣が通り過ぎて、そのあざみを踏みにじった。'),
('JPN', '列王纪下', 12, 14, 10, 'あなたはエドムを打ち破って、心が高ぶっている。誇ってもよいが、自分の家にとどまっていなさい。なぜ、あえてわざわいを引き起こし、あなたもユダもともに倒れようとするのか。」'),
('JPN', '列王纪下', 12, 14, 11, 'しかし、アマツヤが聞き入れなかったので、イスラエルの王ヨアシュは攻め上った。彼とユダの王アマツヤは、ユダのベテ・シェメシュで直接、対決した。'),
('JPN', '列王纪下', 12, 14, 12, 'ユダはイスラエルに打ち負かされ、それぞれ自分の天幕に逃げ帰った。'),
('JPN', '列王纪下', 12, 14, 13, 'イスラエルの王ヨアシュは、アハズヤの子ヨアシュの子、ユダの王アマツヤをベテ・シェメシュで捕らえ、エルサレムにやって来た。そして、エルサレムの城壁をエフライムの門から隅の門まで、四百キュビトにわたって打ち壊した。'),
('JPN', '列王纪下', 12, 14, 14, '彼は、主の宮と王宮の宝物倉にあったすべての金と銀、すべての器、および人質を取って、サマリアに帰った。'),
('JPN', '列王纪下', 12, 14, 15, 'ヨアシュが行ったその他の事柄、その功績、ユダの王アマツヤと戦った戦績、それは『イスラエルの王の歴代誌』に確かに記されている。'),
('JPN', '列王纪下', 12, 14, 16, 'ヨアシュは先祖とともに眠りにつき、イスラエルの王たちとともにサマリアに葬られた。彼の子ヤロブアムが代わって王となった。'),
('JPN', '列王纪下', 12, 14, 17, 'ユダの王ヨアシュの子アマツヤは、イスラエルの王エホアハズの子ヨアシュの死後、なお十五年生きた。'),
('JPN', '列王纪下', 12, 14, 18, 'アマツヤについてのその他の事柄、それは『ユダの王の歴代誌』に確かに記されている。'),
('JPN', '列王纪下', 12, 14, 19, 'エルサレムで人々が彼に対して謀反を企てた。彼はラキシュに逃げたが、人々はラキシュに追っ手を送り、そこで彼を殺した。'),
('JPN', '列王纪下', 12, 14, 20, '彼らは彼を馬に乗せて運んだ。彼はエルサレムで先祖とともに、ダビデの町に葬られた。'),
('JPN', '列王纪下', 12, 14, 21, 'ユダの民はみな、当時十六歳であったアザルヤを立てて、その父アマツヤの代わりに王とした。'),
('JPN', '列王纪下', 12, 14, 22, '彼は、アマツヤが先祖とともに眠った後、エイラトを築き直し、それをユダに復帰させた。'),
('JPN', '列王纪下', 12, 14, 23, 'ユダの王ヨアシュの子アマツヤの第十五年に、イスラエルの王ヨアシュの子ヤロブアムが王となり、サマリアで四十一年間、王であった。'),
('JPN', '列王纪下', 12, 14, 24, '彼は主の目に悪であることを行い、イスラエルに罪を犯させたネバテの子ヤロブアムのすべての罪から離れなかった。'),
('JPN', '列王纪下', 12, 14, 25, '彼は、レボ・ハマテからアラバの海までイスラエルの領土を回復した。それは、イスラエルの神、主が、そのしもべ、ガテ・ヘフェル出身の預言者、アミタイの子ヨナを通して語られたことばのとおりであった。'),
('JPN', '列王纪下', 12, 14, 26, 'イスラエルの苦しみが非常に激しいのを、主がご覧になったからである。そこには、奴隷も自由な者もいなくなり、イスラエルを助ける者もいなかった。'),
('JPN', '列王纪下', 12, 14, 27, '主はイスラエルの名を天の下から消し去ろうとは言っておられなかった。それで、ヨアシュの子ヤロブアムによって彼らを救われたのである。'),
('JPN', '列王纪下', 12, 14, 28, 'ヤロブアムについてのその他の事柄、彼が行ったすべてのこと、彼が戦いであげた功績、すなわち、かつてユダのものであったダマスコとハマテをイスラエルに取り戻したこと、それは『イスラエルの王の歴代誌』に確かに記されている。'),
('JPN', '列王纪下', 12, 14, 29, 'ヤロブアムは、彼の先祖たち、イスラエルの王たちとともに眠り、その子ゼカリヤが代わって王となった。'),
('JPN', '列王纪下', 12, 15, 1, 'イスラエルの王ヤロブアムの第二十七年に、ユダの王アマツヤの子アザルヤが王となった。'),
('JPN', '列王纪下', 12, 15, 2, '彼は十六歳で王となり、エルサレムで五十二年間、王であった。彼の母の名はエコルヤといい、エルサレム出身であった。'),
('JPN', '列王纪下', 12, 15, 3, '彼は、すべて父アマツヤが行ったとおりに、主の目にかなうことを行った。'),
('JPN', '列王纪下', 12, 15, 4, 'ただし、高き所は取り除かれなかった。民はなおも、その高き所でいけにえを献げたり、犠牲を供えたりしていた。'),
('JPN', '列王纪下', 12, 15, 5, '主が王を打たれたので、彼は死ぬ日までツァラアトに冒された者となり、隔離された家に住んだ。王の子ヨタムが宮殿を管理し、民衆をさばいた。'),
('JPN', '列王纪下', 12, 15, 6, 'アザルヤについてのその他の事柄、彼が行ったすべてのこと、それは『ユダの王の歴代誌』に確かに記されている。'),
('JPN', '列王纪下', 12, 15, 7, 'アザルヤは彼の先祖とともに眠りについた。人々は彼をダビデの町に先祖とともに葬った。彼の子ヨタムが代わって王となった。'),
('JPN', '列王纪下', 12, 15, 8, 'ユダの王アザルヤの第三十八年に、ヤロブアムの子ゼカリヤがサマリアでイスラエルの王となり、六か月の間、王であった。'),
('JPN', '列王纪下', 12, 15, 9, '彼は先祖たちがしたように、主の目に悪であることを行い、イスラエルに罪を犯させたネバテの子ヤロブアムの罪から離れなかった。'),
('JPN', '列王纪下', 12, 15, 10, 'ヤベシュの子シャルムは、彼に対して謀反を企て、民の前で彼を打ち殺し、彼に代わって王となった。'),
('JPN', '列王纪下', 12, 15, 11, 'ゼカリヤについてのその他の事柄は、『イスラエルの王の歴代誌』にまさしく記されている。'),
('JPN', '列王纪下', 12, 15, 12, '主がかつてエフーに告げられたことばは、「あなたの子孫は四代までイスラエルの王座に着く」ということであったが、はたして、そのとおりになった。'),
('JPN', '列王纪下', 12, 15, 13, 'ヤベシュの子シャルムは、ユダの王ウジヤの第三十九年に王となり、サマリアで一か月間、王であった。'),
('JPN', '列王纪下', 12, 15, 14, 'ガディの子メナヘムは、ティルツァから上ってサマリアに至り、ヤベシュの子シャルムをサマリアで打ち、彼を殺して、彼に代わって王となった。'),
('JPN', '列王纪下', 12, 15, 15, 'シャルムについてのその他の事柄、彼が企てた謀反は、『イスラエルの王の歴代誌』にまさしく記されている。'),
('JPN', '列王纪下', 12, 15, 16, 'そのとき、メナヘムはティルツァから出て、ティフサフとその住民、その領地を討った。彼らが城門を開かなかったので、その中のすべての妊婦たちを打ち殺して切り裂いた。'),
('JPN', '列王纪下', 12, 15, 17, 'ユダの王アザルヤの第三十九年に、ガディの子メナヘムがイスラエルの王となり、サマリアで十年間、王であった。'),
('JPN', '列王纪下', 12, 15, 18, '彼は主の目に悪であることを行い、一生の間、イスラエルに罪を犯させたネバテの子ヤロブアムの罪から離れなかった。'),
('JPN', '列王纪下', 12, 15, 19, 'アッシリアの王プルがこの国に来たとき、メナヘムは銀千タラントをプルに与えた。プルの援助によって、王国を強くするためであった。'),
('JPN', '列王纪下', 12, 15, 20, 'メナヘムは、イスラエルのすべての有力者にそれぞれ銀五十シェケルを供出させ、これをアッシリアの王に与えたので、アッシリアの王は引き返し、この国にとどまらなかった。'),
('JPN', '列王纪下', 12, 15, 21, 'メナヘムについてのその他の事柄、彼が行ったすべてのこと、それは『イスラエルの王の歴代誌』に確かに記されている。'),
('JPN', '列王纪下', 12, 15, 22, 'メナヘムは先祖とともに眠りにつき、その子ペカフヤが代わって王となった。'),
('JPN', '列王纪下', 12, 15, 23, 'ユダの王アザルヤの第五十年に、メナヘムの子ペカフヤがサマリアでイスラエルの王となり、二年間、王であった。'),
('JPN', '列王纪下', 12, 15, 24, '彼は主の目に悪であることを行い、イスラエルに罪を犯させたネバテの子ヤロブアムの罪から離れなかった。'),
('JPN', '列王纪下', 12, 15, 25, '彼の侍従、レマルヤの子ペカは、彼に対して謀反を企て、サマリアの王宮の高殿で、ペカフヤとアルゴブとアルエを打ち殺した。ペカには五十人のギルアデ人が加わっていた。ペカはペカフヤを殺し、彼に代わって王となった。'),
('JPN', '列王纪下', 12, 15, 26, 'ペカフヤについてのその他の事柄、彼が行ったすべてのことは、『イスラエルの王の歴代誌』にまさしく記されている。'),
('JPN', '列王纪下', 12, 15, 27, 'ユダの王アザルヤの第五十二年に、レマルヤの子ペカがサマリアでイスラエルの王となり、二十年間、王であった。'),
('JPN', '列王纪下', 12, 15, 28, '彼は主の目に悪であることを行い、イスラエルに罪を犯させたネバテの子ヤロブアムの罪から離れなかった。'),
('JPN', '列王纪下', 12, 15, 29, 'イスラエルの王ペカの時代に、アッシリアの王ティグラト・ピレセルが来て、イヨン、アベル・ベテ・マアカ、ヤノアハ、ケデシュ、ハツォル、ギルアデ、ガリラヤ、ナフタリの全土を占領し、その住民をアッシリアへ捕らえ移した。'),
('JPN', '列王纪下', 12, 15, 30, 'そのとき、エラの子ホセアはレマルヤの子ペカに対して謀反を企て、彼を打ち殺して、ウジヤの子ヨタムの第二十年に、彼に代わって王となった。'),
('JPN', '列王纪下', 12, 15, 31, 'ペカについてのその他の事柄、彼が行ったすべてのことは、『イスラエルの王の歴代誌』にまさしく記されている。'),
('JPN', '列王纪下', 12, 15, 32, 'イスラエルの王レマルヤの子ペカの第二年に、ユダの王ウジヤの子ヨタムが王となった。'),
('JPN', '列王纪下', 12, 15, 33, '彼は二十五歳で王となり、エルサレムで十六年間、王であった。彼の母の名はエルシャといい、ツァドクの娘であった。'),
('JPN', '列王纪下', 12, 15, 34, '彼は、すべて父ウジヤが行ったとおりに、主の目にかなうことを行った。'),
('JPN', '列王纪下', 12, 15, 35, 'ただし、高き所は取り除かれなかった。民はなおも、高き所でいけにえを献げたり、犠牲を供えたりしていた。彼は主の宮の上の門を建てた。'),
('JPN', '列王纪下', 12, 15, 36, 'ヨタムが行ったその他の事柄、それは『ユダの王の歴代誌』に確かに記されている。'),
('JPN', '列王纪下', 12, 15, 37, 'そのころ、主はアラムの王レツィンとレマルヤの子ペカを、ユダに対して送り始められた。'),
('JPN', '列王纪下', 12, 15, 38, 'ヨタムは先祖とともに眠りにつき、先祖とともにその父ダビデの町に葬られた。彼の子アハズが代わって王となった。'),
('JPN', '列王纪下', 12, 16, 1, 'レマルヤの子ペカの第十七年に、ユダの王ヨタムの子アハズが王となった。'),
('JPN', '列王纪下', 12, 16, 2, 'アハズは二十歳で王となり、エルサレムで十六年間、王であった。彼はその父祖ダビデとは違って、彼の神、主の目にかなうことを行わず、'),
('JPN', '列王纪下', 12, 16, 3, 'イスラエルの王たちの道に歩み、主がイスラエルの子らの前から追い払われた異邦の民の、忌み嫌うべき慣わしをまねて、自分の子どもに火の中を通らせることまでした。'),
('JPN', '列王纪下', 12, 16, 4, '彼は高き所、丘の上、青々と茂るあらゆる木の下でいけにえを献げ、犠牲を供えた。'),
('JPN', '列王纪下', 12, 16, 5, 'そのころ、アラムの王レツィンと、イスラエルの王レマルヤの子ペカが、戦いのためにエルサレムに上って来て、アハズを包囲したが、攻め切れなかった。'),
('JPN', '列王纪下', 12, 16, 6, 'このとき、アラムの王レツィンはエイラトをアラムに復帰させ、ユダの人々をエイラトから追い払った。ところが、エドム人がエイラトに来て、そこに住みついた。今日もそのままである。'),
('JPN', '列王纪下', 12, 16, 7, 'アハズは使者たちをアッシリアの王ティグラト・ピレセルに遣わして言った。「私はあなたのしもべであり、あなたの子です。どうか上って来て、私を攻めているアラムの王とイスラエルの王の手から救ってください。」'),
('JPN', '列王纪下', 12, 16, 8, 'アハズが主の宮と王宮の宝物倉にある銀と金を取り出して、それを贈り物としてアッシリアの王に送ったので、'),
('JPN', '列王纪下', 12, 16, 9, 'アッシリアの王は彼の願いを聞き入れた。アッシリアの王はダマスコに攻め上り、これを取り、その住民をキルへ捕らえ移した。彼はレツィンを殺した。'),
('JPN', '列王纪下', 12, 16, 10, 'アハズ王は、アッシリアの王ティグラト・ピレセルに会うためダマスコに行ったとき、ダマスコにある祭壇を見た。アハズ王は、祭壇の図面とその模型を、詳細な作り方と一緒に祭司ウリヤに送った。'),
('JPN', '列王纪下', 12, 16, 11, '祭司ウリヤは、アハズ王がダマスコから送ったものとそっくりの祭壇を築いた。祭司ウリヤは、アハズ王がダマスコから帰って来るまでに、そのようにした。'),
('JPN', '列王纪下', 12, 16, 12, '王はダマスコから帰って来た。その祭壇を見て、王は祭壇に近づき、その上に上った。'),
('JPN', '列王纪下', 12, 16, 13, '彼は全焼のささげ物と、穀物のささげ物を焼いて煙にし、注ぎのささげ物を注ぎ、自分のための交わりのいけにえの血をこの祭壇に振りかけた。'),
('JPN', '列王纪下', 12, 16, 14, '主の前にあった青銅の祭壇は、神殿の前から、すなわち、この祭壇と主の神殿の間から動かし、この祭壇の北側に置いた。'),
('JPN', '列王纪下', 12, 16, 15, 'それから、アハズ王は祭司ウリヤに次のように命じた。「朝の全焼のささげ物と夕方の穀物のささげ物、また、王の全焼のささげ物と穀物のささげ物、この国の民全体の全焼のささげ物と穀物のささげ物、ならびにこれらに添える注ぎのささげ物を、この大いなる祭壇の上で焼いて煙にせよ。また全焼のささげ物の血といけにえの血は、すべてこの祭壇の上に振りかけなければならない。青銅の祭壇は、私が伺いを立てるためのものとする。」'),
('JPN', '列王纪下', 12, 16, 16, '祭司ウリヤは、すべてアハズ王が命じたとおりに行った。'),
('JPN', '列王纪下', 12, 16, 17, 'アハズ王は、車輪付きの台の鏡板を切り離し、その台の上から洗盤を外し、またその下にある青銅の牛の上から「海」も降ろして、それを敷き石の上に置いた。'),
('JPN', '列王纪下', 12, 16, 18, '彼は、宮の中に造られていた安息日用の覆いのある通路も、外側の王の出入り口も、アッシリアの王のために主の宮から取り除いた。'),
('JPN', '列王纪下', 12, 16, 19, 'アハズが行ったその他の事柄、それは『ユダの王の歴代誌』に確かに記されている。'),
('JPN', '列王纪下', 12, 16, 20, 'アハズは先祖とともに眠りにつき、先祖とともにダビデの町に葬られた。彼の子ヒゼキヤが代わって王となった。'),
('JPN', '列王纪下', 12, 17, 1, 'ユダの王アハズの第十二年に、エラの子ホセアがサマリアでイスラエルの王となり、九年間、王であった。'),
('JPN', '列王纪下', 12, 17, 2, '彼は主の目に悪であることを行ったが、彼以前のイスラエルの王たちのようではなかった。'),
('JPN', '列王纪下', 12, 17, 3, 'アッシリアの王シャルマネセルが攻め上って来た。そのとき、ホセアは彼に服従して、貢ぎ物を納めた。'),
('JPN', '列王纪下', 12, 17, 4, 'しかし、アッシリアの王はホセアの謀反に気がついた。ホセアがエジプトの王ソに使者たちを遣わし、アッシリアの王には年々の貢ぎ物を納めなかったからである。そこで、アッシリアの王は彼を捕らえて牢獄につないだ。'),
('JPN', '列王纪下', 12, 17, 5, 'アッシリアの王はこの国全土に攻め上り、サマリアに攻め上って、三年間これを包囲した。'),
('JPN', '列王纪下', 12, 17, 6, 'ホセアの第九年に、アッシリアの王はサマリアを取り、イスラエル人をアッシリアに捕らえ移し、彼らをハラフと、ゴザンの川ハボルのほとり、またメディアの町々に住まわせた。'),
('JPN', '列王纪下', 12, 17, 7, 'こうなったのは、イスラエルの子らが、自分たちをエジプトの地から連れ上り、エジプトの王ファラオの支配下から解放した自分たちの神、主に対して罪を犯し、ほかの神々を恐れ、'),
('JPN', '列王纪下', 12, 17, 8, '主がイスラエルの子らの前から追い払われた異邦の民の風習、イスラエルの王たちが取り入れた風習にしたがって歩んだからである。'),
('JPN', '列王纪下', 12, 17, 9, 'イスラエルの子らは、自分たちの神、主に対して、正しくないことをひそかに行い、見張りのやぐらから城壁のある町に至るまで、すべての町に高き所を築き、'),
('JPN', '列王纪下', 12, 17, 10, 'すべての小高い丘の上や、青々と茂るどの木の下にも石の柱やアシェラ像を立て、'),
('JPN', '列王纪下', 12, 17, 11, '主が彼らの前から移された異邦の民のように、すべての高き所で犠牲を供え、悪事を行って主の怒りを引き起こした。'),
('JPN', '列王纪下', 12, 17, 12, '主が彼らに「このようなことをしてはならない」と命じておられたのに、彼らは偶像に仕えたのである。'),
('JPN', '列王纪下', 12, 17, 13, '主はすべての預言者とすべての先見者を通して、イスラエルとユダに次のように警告された。「あなたがたは悪の道から立ち返れ。わたしがあなたがたの先祖たちに命じ、また、わたしのしもべである預言者たちを通してあなたがたに伝えた律法全体にしたがって、わたしの命令と掟を守れ。」'),
('JPN', '列王纪下', 12, 17, 14, 'しかし、彼らはこれを聞き入れず、彼らの神、主を信じなかった彼らの先祖たちのように、うなじを固くした。'),
('JPN', '列王纪下', 12, 17, 15, '彼らは主の掟と、彼らの先祖たちと結ばれた主の契約と、彼らに与えられた主の警告を蔑み、空しいものに従って歩んだので、自分たちも空しいものとなり、主が倣ってはならないと命じられた、周囲の異邦の民に倣って歩んだ。'),
('JPN', '列王纪下', 12, 17, 16, '彼らの神、主のすべての命令を捨て、自分たちのために、鋳物の像、二頭の子牛の像を造り、さらにアシェラ像を造り、天の万象を拝み、バアルに仕えた。')
on conflict (version, book, chapter, verse) do nothing;
insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('JPN', '列王纪下', 12, 17, 17, 'また、自分たちの息子や娘たちに火の中を通らせ、占いをし、まじないをし、主の目に悪であることを行うことに身を任せ、主の怒りを引き起こした。'),
('JPN', '列王纪下', 12, 17, 18, 'そのため主はイスラエルに対して激しく怒り、彼らを御前から除かれた。ただユダの部族だけが残った。'),
('JPN', '列王纪下', 12, 17, 19, 'ユダも、彼らの神、主の命令を守らず、イスラエルが取り入れた風習にしたがって歩んだ。'),
('JPN', '列王纪下', 12, 17, 20, 'そのため主はイスラエルのすべての子孫を蔑み、彼らを苦しめ、略奪者たちの手に渡し、ついに彼らを御前から投げ捨てられた。'),
('JPN', '列王纪下', 12, 17, 21, '主がイスラエルをダビデの家から引き裂かれたとき、彼らはネバテの子ヤロブアムを王としたが、ヤロブアムはイスラエルを主に従わないように仕向け、そうして彼らに大きな罪を犯させた。'),
('JPN', '列王纪下', 12, 17, 22, 'イスラエルの人々は、ヤロブアムが行ったすべての罪に歩み、それから離れなかったので、'),
('JPN', '列王纪下', 12, 17, 23, '主は、そのしもべであるすべての預言者を通して告げられたとおり、ついにイスラエルを御前から除かれた。こうして、イスラエルは自分の土地からアッシリアに引いて行かれた。今日もそのままである。'),
('JPN', '列王纪下', 12, 17, 24, 'アッシリアの王は、バビロン、クテ、アワ、ハマテ、そしてセファルワイムから人々を連れて来て、イスラエル人の代わりにサマリアの町々に住まわせた。こうして、彼らはサマリアを占領して、その町々に住んだ。'),
('JPN', '列王纪下', 12, 17, 25, '彼らはそこに住み始めたとき、主を恐れなかったので、主は彼らの中に獅子を送り込まれた。獅子は彼らの何人かを殺した。'),
('JPN', '列王纪下', 12, 17, 26, '彼らはアッシリアの王に次のように報告した。「あなたがサマリアの町々に移した諸国の民は、この土地の神についての慣わしを知りません。それで、神が彼らのうちに獅子を送り込みました。今、獅子が彼らを殺しています。彼らがこの土地の神についての慣わしを知らないからです。」'),
('JPN', '列王纪下', 12, 17, 27, 'そこで、アッシリアの王は次のように命じた。「おまえたちがそこから捕らえ移した祭司の一人を、そこに連れて行け。行かせて、そこに住まわせ、その土地の神についての慣わしを教えさせよ。」'),
('JPN', '列王纪下', 12, 17, 28, 'こうして、サマリアから捕らえ移された祭司の一人が来てベテルに住み、どのようにして主を礼拝するべきかを教えた。'),
('JPN', '列王纪下', 12, 17, 29, 'しかし、それぞれの民は、それぞれ自分たちの神々を造り、サマリア人が造った高き所の宮にそれを安置した。それぞれの民は自分が住む町々でそのようにした。'),
('JPN', '列王纪下', 12, 17, 30, 'バビロンの人々はスコテ・ベノテを造り、クテの人々はネルガルを造り、ハマテの人々はアシマを造り、'),
('JPN', '列王纪下', 12, 17, 31, 'アワ人はニブハズとタルタクを造り、セファルワイム人はセファルワイムの神々、アデラメレクとアナメレクに自分たちの子どもを火で焼いて献げた。'),
('JPN', '列王纪下', 12, 17, 32, '彼らは主を礼拝したが、自分たちの中から高き所の祭司たちを自分たちで任命し、この祭司たちが彼らのために高き所の宮で祭儀を行った。'),
('JPN', '列王纪下', 12, 17, 33, '彼らは主を礼拝しながら、同時に、自分たちが移される前にいた国々の慣わしによって、自分たちの神々にも仕えていた。'),
('JPN', '列王纪下', 12, 17, 34, '彼らは今日まで、以前の慣わしのとおりに行っている。彼らは主を恐れることはなく、主がイスラエルと名をつけたヤコブの子たちに命じられた、掟や定めや律法や命令のとおりに行うこともない。'),
('JPN', '列王纪下', 12, 17, 35, '主はイスラエル人と契約を結び、次のように命じられた。「ほかの神々を恐れてはならない。これを拝み、これに仕えてはならない。これにいけにえを献げてはならない。'),
('JPN', '列王纪下', 12, 17, 36, '大きな力と、伸ばされた腕をもって、あなたがたをエジプトの地から連れ上った主だけを恐れ、主を礼拝し、主にいけにえを献げなければならない。'),
('JPN', '列王纪下', 12, 17, 37, '主があなたがたのために書き記した掟と定めと律法と命令をいつも守り行わなければならない。ほかの神々を恐れてはならない。'),
('JPN', '列王纪下', 12, 17, 38, 'わたしがあなたがたと結んだ契約を忘れてはならない。ほかの神々を恐れてはならない。'),
('JPN', '列王纪下', 12, 17, 39, 'あなたがたの神、主だけを恐れなければならない。主はすべての敵の手からあなたがたを救い出される。」'),
('JPN', '列王纪下', 12, 17, 40, 'しかし、彼らは聞かず、以前の彼らの慣わしのとおりに行った。'),
('JPN', '列王纪下', 12, 17, 41, 'このようにして、これらの民は主を礼拝すると同時に、彼らの刻んだ像にも仕えた。その子たちも、孫たちも、その先祖たちがしたとおりに行った。今日もそうである。'),
('JPN', '列王纪下', 12, 18, 1, 'イスラエルの王エラの子ホセアの第三年に、ユダの王アハズの子ヒゼキヤが王となった。'),
('JPN', '列王纪下', 12, 18, 2, '彼は二十五歳で王となり、エルサレムで二十九年間、王であった。彼の母の名はアビといい、ゼカリヤの娘であった。'),
('JPN', '列王纪下', 12, 18, 3, '彼は、すべて父祖ダビデが行ったとおりに、主の目にかなうことを行った。'),
('JPN', '列王纪下', 12, 18, 4, '高き所を取り除き、石の柱を打ち砕き、アシェラ像を切り倒し、モーセが作った青銅の蛇を砕いた。そのころまで、イスラエル人がこれに犠牲を供えていたからである。これはネフシュタンと呼ばれていた。'),
('JPN', '列王纪下', 12, 18, 5, '彼はイスラエルの神、主に信頼していた。彼の後にも前にも、ユダの王たちの中で、彼ほどの者はだれもいなかった。'),
('JPN', '列王纪下', 12, 18, 6, '彼は主に堅くつき従って離れることなく、主がモーセに命じられた命令を守った。'),
('JPN', '列王纪下', 12, 18, 7, '主は彼とともにおられた。彼はどこへ出て行っても成功を収めた。彼はアッシリアの王に反逆し、彼に仕えなかった。'),
('JPN', '列王纪下', 12, 18, 8, '彼はペリシテ人を討ってガザにまで至り、見張りのやぐらから城壁のある町に至るその領土を打ち破った。'),
('JPN', '列王纪下', 12, 18, 9, 'ヒゼキヤ王の第四年、イスラエルの王エラの子ホセアの第七年に、アッシリアの王シャルマネセルがサマリアに攻め上って来て、これを包囲し、'),
('JPN', '列王纪下', 12, 18, 10, '三年後にこれを攻め取った。すなわち、ヒゼキヤの第六年、イスラエルの王ホセアの第九年に、サマリアは攻め取られた。'),
('JPN', '列王纪下', 12, 18, 11, 'アッシリアの王はイスラエル人をアッシリアに捕らえ移し、彼らをハラフと、ゴザンの川ハボルのほとり、またメディアの町々に定住させた。'),
('JPN', '列王纪下', 12, 18, 12, 'これは、彼らが彼らの神、主の御声に聞き従わず、その契約を破り、主のしもべモーセが命じたすべてのことに聞き従わず、これを行わなかったからである。'),
('JPN', '列王纪下', 12, 18, 13, 'ヒゼキヤ王の第十四年に、アッシリアの王センナケリブが、ユダのすべての城壁のある町々に攻め上り、これを取った。'),
('JPN', '列王纪下', 12, 18, 14, 'ユダの王ヒゼキヤは、ラキシュのアッシリアの王のところに人を遣わして言った。「私は過ちを犯しました。私のところから引き揚げてください。あなたが私に課せられるものは何でも負いますから。」そこで、アッシリアの王はユダの王ヒゼキヤに、銀三百タラントと金三十タラントを要求した。'),
('JPN', '列王纪下', 12, 18, 15, 'ヒゼキヤは、主の宮と王宮の宝物倉にある銀をすべて渡した。'),
('JPN', '列王纪下', 12, 18, 16, 'そのとき、ユダの王ヒゼキヤは、自分が主の神殿の扉と柱に張り付けた金を剝ぎ取り、これをアッシリアの王に渡した。'),
('JPN', '列王纪下', 12, 18, 17, 'アッシリアの王は、タルタン、ラブ・サリス、およびラブ・シャケを、大軍とともにラキシュからエルサレムのヒゼキヤ王のところへ送った。彼らはエルサレムに上って来た。彼らは上って来ると、布さらしの野への大路にある、上の池の水道のそばに立った。'),
('JPN', '列王纪下', 12, 18, 18, '彼らが王に呼びかけたので、ヒルキヤの子である宮廷長官エルヤキム、書記シェブナ、およびアサフの子である史官ヨアフは、彼らのところに出て行った。'),
('JPN', '列王纪下', 12, 18, 19, 'ラブ・シャケは彼らに言った。「ヒゼキヤに伝えよ。大王、アッシリアの王がこう言っておられる。『いったい、おまえは何に拠り頼んでいるのか。'),
('JPN', '列王纪下', 12, 18, 20, '口先だけのことばが、戦略であり戦力だというのか。今おまえは、だれに拠り頼んでいるのか。私に反逆しているが。'),
('JPN', '列王纪下', 12, 18, 21, '今おまえは、あの傷んだ葦の杖、エジプトに拠り頼んでいるが、それは、それに寄りかかる者の手を刺し貫くだけだ。エジプトの王ファラオは、すべて彼に拠り頼む者にそうするのだ。'),
('JPN', '列王纪下', 12, 18, 22, 'おまえたちは私に「われわれは、われわれの神、主に拠り頼む」と言う。その主とは、ヒゼキヤがその高き所と祭壇を取り除いて、ユダとエルサレムに「エルサレムにあるこの祭壇の前で拝め」と言った、そういう主ではないか。'),
('JPN', '列王纪下', 12, 18, 23, 'さあ今、私の主君、アッシリアの王と賭けをしないか。もし、おまえのほうで乗り手をそろえることができるのなら、おまえに二千頭の馬を与えよう。'),
('JPN', '列王纪下', 12, 18, 24, 'おまえは戦車と騎兵のことでエジプトに拠り頼んでいるが、私の主君の最も小さい家来である総督一人さえ追い返せないのだ。'),
('JPN', '列王纪下', 12, 18, 25, '今、私がこの場所を滅ぼすために上って来たのは、主を差し置いてのことであろうか。主が私に「この国に攻め上って、これを滅ぼせ」と言われたのだ。』」'),
('JPN', '列王纪下', 12, 18, 26, 'ヒルキヤの子エルヤキムとシェブナとヨアフは、ラブ・シャケに言った。「どうか、しもべたちにはアラム語で話してください。われわれはアラム語が分かりますから。城壁の上にいる民が聞いているところでは、われわれにユダのことばで話さないでください。」'),
('JPN', '列王纪下', 12, 18, 27, 'ラブ・シャケは彼らに言った。「私の主君がこれらのことを告げに私を遣わされたのは、おまえの主君や、おまえのためだろうか。むしろ、城壁の上に座っている者たちのためではないか。彼らはおまえたちと一緒に、自分の糞を食らい、自分の尿を飲むようになるのだ。」'),
('JPN', '列王纪下', 12, 18, 28, 'ラブ・シャケは突っ立って、ユダのことばで大声で叫んで、こう告げた。「大王、アッシリアの王のことばを聞け。'),
('JPN', '列王纪下', 12, 18, 29, '王はこう言っておられる。『ヒゼキヤにごまかされるな。あれは、おまえたちを私の手から救い出すことができないからだ。'),
('JPN', '列王纪下', 12, 18, 30, 'ヒゼキヤは、「主が必ずわれわれを救い出してくださる。この都は決してアッシリアの王の手に渡されることはない」と言って、おまえたちに主を信頼させようとするが、そうはさせない。』'),
('JPN', '列王纪下', 12, 18, 31, 'ヒゼキヤの言うことを聞くな。アッシリアの王はこう言っておられるからだ。『私と和を結び、私に降伏せよ。そうすれば、おまえたちはみな、自分のぶどうと自分のいちじくを食べ、自分の井戸の水を飲めるようになる。'),
('JPN', '列王纪下', 12, 18, 32, 'その後私は来て、おまえたちの国と同じような国におまえたちを連れて行く。そこは穀物と新しいぶどう酒の地、パンとぶどう畑の地、オリーブの木と蜜の地である。おまえたちが生き延びて死ぬことのないようにするためである。たとえヒゼキヤが、「主はわれわれを救い出してくださる」と言って、おまえたちをそそのかしても、ヒゼキヤに聞き従ってはならない。'),
('JPN', '列王纪下', 12, 18, 33, '国々の神々は、それぞれ自分の国をアッシリアの王の手から救い出しただろうか。'),
('JPN', '列王纪下', 12, 18, 34, 'ハマテやアルパデの神々は今、どこにいるのか。セファルワイムやヘナやイワの神々はどこにいるのか。彼らはサマリアを私の手から救い出したか。'),
('JPN', '列王纪下', 12, 18, 35, '国々のすべての神々のうち、だれが自分たちの国を私の手から救い出したか。主がエルサレムを私の手から救い出せるとでもいうのか。』」'),
('JPN', '列王纪下', 12, 18, 36, '民は黙って、彼に一言も答えなかった。「彼に答えるな」というのが、王の命令だったからである。'),
('JPN', '列王纪下', 12, 18, 37, 'ヒルキヤの子である宮廷長官エルヤキム、書記シェブナ、アサフの子である史官ヨアフは、自分たちの衣を引き裂いてヒゼキヤのもとに行き、ラブ･シャケのことばを告げた。'),
('JPN', '列王纪下', 12, 19, 1, 'ヒゼキヤ王はこれを聞くと衣を引き裂き、粗布を身にまとって主の宮に入った。'),
('JPN', '列王纪下', 12, 19, 2, '彼は、宮廷長官エルヤキム、書記シェブナ、年長の祭司たちに粗布を身にまとわせて、アモツの子、預言者イザヤのところに遣わした。'),
('JPN', '列王纪下', 12, 19, 3, '彼らはイザヤに言った。「ヒゼキヤはこう言っております。『今日は、苦難と懲らしめと屈辱の日です。子どもが生まれようとしているのに、それを産み出す力がないからです。'),
('JPN', '列王纪下', 12, 19, 4, 'おそらく、あなたの神、主は、ラブ・シャケのすべてのことばを聞かれたことでしょう。彼の主君、アッシリアの王が、生ける神をそしるために彼を遣わしたのです。あなたの神、主は、お聞きになったそのことばをとがめられます。あなたは、まだいる残りの者のために祈りの声をあげてください。』」'),
('JPN', '列王纪下', 12, 19, 5, 'ヒゼキヤ王の家来たちがイザヤのもとに来たとき、'),
('JPN', '列王纪下', 12, 19, 6, 'イザヤは彼らに言った。「あなたがたの主君にこう言いなさい。『主はこう言われる。あなたが聞いたあのことば、アッシリアの王の若い者たちがわたしをののしった、あのことばを恐れるな。'),
('JPN', '列王纪下', 12, 19, 7, '今、わたしは彼のうちに霊を置く。彼は、あるうわさを聞いて、自分の国に引き揚げる。わたしはその国で彼を剣で倒す。』」'),
('JPN', '列王纪下', 12, 19, 8, 'ラブ・シャケは退いて、リブナを攻めていたアッシリアの王と落ち合った。王がラキシュから移動したことを聞いていたからである。'),
('JPN', '列王纪下', 12, 19, 9, '王は、クシュの王ティルハカについて、「今、彼はあなたと戦うために出て来ている」との知らせを聞くと、再び使者たちをヒゼキヤに遣わして言った。'),
('JPN', '列王纪下', 12, 19, 10, '「ユダの王ヒゼキヤにこう伝えよ。『おまえが信頼するおまえの神にだまされてはいけない。エルサレムはアッシリアの王の手に渡されないと言っているが。'),
('JPN', '列王纪下', 12, 19, 11, 'おまえは、アッシリアの王たちがすべての国々にしたこと、それらを絶滅させたことを確かに聞いている。それでも、おまえだけは救い出されるというのか。'),
('JPN', '列王纪下', 12, 19, 12, '私の先祖は、ゴザン、ハラン、レツェフ、またテラサルにいたエデンの人々を滅ぼしたが、その国々の神々は彼らを救い出したか。'),
('JPN', '列王纪下', 12, 19, 13, 'ハマテの王、アルパデの王、セファルワイムの町の王、ヘナやイワの王はどこにいるか。』」'),
('JPN', '列王纪下', 12, 19, 14, 'ヒゼキヤは、使者の手からその手紙を受け取って読み、主の宮に上って行き、それを主の前に広げた。'),
('JPN', '列王纪下', 12, 19, 15, 'ヒゼキヤは主の前で祈った。「ケルビムの上に座しておられるイスラエルの神、主よ。ただ、あなただけが、地のすべての王国の神です。あなたが天と地を造られました。'),
('JPN', '列王纪下', 12, 19, 16, '主よ。御耳を傾けて聞いてください。主よ。御目を開いてご覧ください。生ける神をそしるために言ってよこしたセンナケリブのことばを聞いてください。'),
('JPN', '列王纪下', 12, 19, 17, '主よ。アッシリアの王たちが、国々とその国土を廃墟としたのは事実です。'),
('JPN', '列王纪下', 12, 19, 18, '彼らはその神々を火に投げ込みました。それらが神ではなく、人の手のわざ、木や石にすぎなかったので、彼らはこれを滅ぼすことができたのです。'),
('JPN', '列王纪下', 12, 19, 19, '私たちの神、主よ。どうか今、私たちを彼の手から救ってください。そうすれば、地のすべての王国は、主よ、あなただけが神であることを知るでしょう。」'),
('JPN', '列王纪下', 12, 19, 20, 'アモツの子イザヤはヒゼキヤのところに人を送って言った。「イスラエルの神、主はこう言われる。『あなたがアッシリアの王センナケリブについて、わたしに祈ったことを、わたしは聞いた。』'),
('JPN', '列王纪下', 12, 19, 21, '主が彼について語られたことばは、このとおりである。『処女である娘シオンはおまえを蔑み、おまえを嘲る。娘エルサレムはおまえのうしろで頭を振る。'),
('JPN', '列王纪下', 12, 19, 22, 'おまえはだれをそしり、だれをののしったのか。だれに向かって声をあげ、高慢な目を上げたのか。イスラエルの聖なる者に対してだ。'),
('JPN', '列王纪下', 12, 19, 23, 'おまえは使者たちを通して、主をそしって言った。「多くの戦車を率いて、私は山々の頂に、レバノンの奥深くへ上って行った。そのそびえる杉の木と美しいもみの木を切り倒し、その果ての高地、木の茂った園にまで入って行った。'),
('JPN', '列王纪下', 12, 19, 24, '私は井戸を掘って、他国の水を飲み、足の裏でエジプトのすべての川を干上がらせた」と。'),
('JPN', '列王纪下', 12, 19, 25, 'おまえは聞かなかったのか。遠い昔に、わたしがそれをなし、大昔に、わたしがそれを計画し、今、それを果たしたことを。それで、おまえは城壁のある町々を荒らして廃墟の石くれの山としたのだ。'),
('JPN', '列王纪下', 12, 19, 26, 'その住民は力失せ、打ちのめされて恥を見て、野の草や青菜、育つ前に干からびる屋根の草のようになった。'),
('JPN', '列王纪下', 12, 19, 27, 'おまえが座るのも、出て行くのも、おまえが入るのも、わたしはよく知っている。わたしに向かっていきり立つのも。'),
('JPN', '列王纪下', 12, 19, 28, 'おまえがわたしに向かっていきり立ち、おまえの安逸がわたしの耳に届いたので、わたしはおまえの鼻に鉤輪を、口にくつわをはめ、おまえを、もと来た道に引き戻す。』'),
('JPN', '列王纪下', 12, 19, 29, 'あなたへのしるしは、このとおりである。『今年は、落ち穂から生えたものを食べ、二年目は、それから生えたものを食べ、三年目は、種を蒔いて刈り入れ、ぶどう畑を作ってその実を食べる。'),
('JPN', '列王纪下', 12, 19, 30, 'ユダの家の中の逃れの者、残された者は下に根を張り、上に実を結ぶ。'),
('JPN', '列王纪下', 12, 19, 31, 'エルサレムから残りの者が、シオンの山から、逃れの者が出て来るからである。万軍の主の熱心がこれを成し遂げる。』'),
('JPN', '列王纪下', 12, 19, 32, 'それゆえ、アッシリアの王について、主はこう言われる。『彼はこの都に侵入しない。また、ここに矢を放たず、これに盾をもって迫らず、塁を築いてこれを攻めることもない。'),
('JPN', '列王纪下', 12, 19, 33, '彼は、もと来た道を引き返し、この都には入らない──主のことば──。'),
('JPN', '列王纪下', 12, 19, 34, 'わたしはこの都を守って、これを救う。わたしのために、わたしのしもべダビデのために。』」'),
('JPN', '列王纪下', 12, 19, 35, 'その夜、主の使いが出て行き、アッシリアの陣営で十八万五千人を打ち殺した。人々が翌朝早く起きて見ると、なんと、彼らはみな死体となっていた。'),
('JPN', '列王纪下', 12, 19, 36, 'アッシリアの王センナケリブは陣をたたんで去り、帰ってニネベに住んだ。'),
('JPN', '列王纪下', 12, 19, 37, '彼が自分の神ニスロクの神殿で拝んでいたとき、その息子たち、アデラメレクとサルエツェルは、剣で彼を打ち殺した。彼らはアララテの地へ逃れ、彼の子エサル・ハドンが代わって王となった。'),
('JPN', '列王纪下', 12, 20, 1, 'そのころ、ヒゼキヤは病気になって死にかかっていた。そこへ、アモツの子、預言者イザヤが来て、彼に言った。「主はこう言われる。『あなたの家を整理せよ。あなたは死ぬ。治らない。』」'),
('JPN', '列王纪下', 12, 20, 2, 'ヒゼキヤは顔を壁に向け、主に祈った。'),
('JPN', '列王纪下', 12, 20, 3, '「ああ、主よ、どうか思い出してください。私が真実と全き心をもって、あなたの御前に歩み、あなたの御目にかなうことを行ってきたことを。」ヒゼキヤは大声で泣いた。'),
('JPN', '列王纪下', 12, 20, 4, 'イザヤがまだ中庭を出ないうちに、次のような主のことばが彼にあった。'),
('JPN', '列王纪下', 12, 20, 5, '「引き返して、わたしの民の君主ヒゼキヤに告げよ。あなたの父ダビデの神、主はこう言われます。『わたしはあなたの祈りを聞いた。あなたの涙も見た。見よ、わたしはあなたを癒やす。あなたは三日目に主の宮に上る。'),
('JPN', '列王纪下', 12, 20, 6, 'わたしは、あなたの寿命にもう十五年を加える。わたしはアッシリアの王の手からあなたとこの都を救い出し、わたしのために、わたしのしもべダビデのためにこの都を守る。』」'),
('JPN', '列王纪下', 12, 20, 7, 'イザヤが「ひとかたまりの干しいちじくを持って来なさい」と命じたので、人々はそれを持って来て腫物に当てた。すると彼は治った。'),
('JPN', '列王纪下', 12, 20, 8, 'ヒゼキヤはイザヤに言った。「主が私を癒やしてくださり、私が三日目に主の宮に上れるしるしは何ですか。」'),
('JPN', '列王纪下', 12, 20, 9, 'イザヤは言った。「次のことが、あなたへの主からのしるしです。主は約束したことを成就されます。影が十度進むか、十度戻るかです。」'),
('JPN', '列王纪下', 12, 20, 10, 'ヒゼキヤは答えた。「影が十度伸びるのは容易なことです。むしろ、影が十度後に戻るようにしてください。」'),
('JPN', '列王纪下', 12, 20, 11, '預言者イザヤが主に祈ると、主は、アハズの日時計に落ちた日時計の影を十度後に戻された。'),
('JPN', '列王纪下', 12, 20, 12, 'そのころ、バルアダンの子、バビロンの王メロダク・バルアダンは使者を遣わして、手紙と贈り物をヒゼキヤに届けた。ヒゼキヤが病気だったことを聞いていたからである。'),
('JPN', '列王纪下', 12, 20, 13, 'ヒゼキヤは彼らを歓迎して、すべての宝庫、銀、金、香料、高価な油、武器庫、彼の宝物倉にあるすべての物を彼らに見せた。ヒゼキヤがその家の中、および国中で、彼らに見せなかった物は一つもなかった。'),
('JPN', '列王纪下', 12, 20, 14, '預言者イザヤはヒゼキヤ王のところに来て、彼に尋ねた。「あの人たちは何と言いましたか。どこから来たのですか。」ヒゼキヤは「遠い国、バビロンから来ました」と答えた。'),
('JPN', '列王纪下', 12, 20, 15, 'イザヤは言った。「彼らはあなたの家で何を見たのですか。」ヒゼキヤは答えた。「私の家の中のすべての物を見ました。私の宝物倉の中で彼らに見せなかった物は一つもありません。」'),
('JPN', '列王纪下', 12, 20, 16, 'イザヤはヒゼキヤに言った。「主のことばを聞きなさい。'),
('JPN', '列王纪下', 12, 20, 17, '見よ。あなたの家にある物、あなたの父祖たちが今日まで蓄えてきた物がすべて、バビロンへ運び去られる日々が来る。何一つ残されることはない──主は言われる──。'),
('JPN', '列王纪下', 12, 20, 18, 'また、あなたが生む、あなた自身の息子たちの中には、捕らえられてバビロンの王の宮殿で宦官となる者がいる。」'),
('JPN', '列王纪下', 12, 20, 19, 'ヒゼキヤはイザヤに言った。「あなたが告げてくれた主のことばはありがたい。」彼は、自分が生きている間は平和と安定があるのではないか、と思ったのである。'),
('JPN', '列王纪下', 12, 20, 20, 'ヒゼキヤについてのその他の事柄、彼のすべての功績、彼が貯水池と水道を造り、都に水を引いたこと、それは『ユダの王の歴代誌』に確かに記されている。'),
('JPN', '列王纪下', 12, 20, 21, 'ヒゼキヤは先祖とともに眠りにつき、その子マナセが代わって王となった。'),
('JPN', '列王纪下', 12, 21, 1, 'マナセは十二歳で王となり、エルサレムで五十五年間、王であった。彼の母の名はヘフツィ・バハといった。'),
('JPN', '列王纪下', 12, 21, 2, '彼は、主がイスラエルの子らの前から追い払われた異邦の民の忌み嫌うべき慣わしをまねて、主の目に悪であることを行った。'),
('JPN', '列王纪下', 12, 21, 3, '彼は父ヒゼキヤが打ち壊した高き所を築き直し、イスラエルの王アハブがしたように、バアルのためにいくつもの祭壇を築き、アシェラ像を造り、天の万象を拝んでこれに仕えた。'),
('JPN', '列王纪下', 12, 21, 4, 'こうして彼は、主がかつて「エルサレムにわたしの名を置く」と言われた主の宮に、いくつもの祭壇を築いた。'),
('JPN', '列王纪下', 12, 21, 5, '主の宮の二つの庭には、天の万象のために祭壇を築いた。'),
('JPN', '列王纪下', 12, 21, 6, 'また、自分の子どもに火の中を通らせ、卜占をし、まじないをし、霊媒や口寄せをし、主の目に悪であることを行って、いつも主の怒りを引き起こしていた。'),
('JPN', '列王纪下', 12, 21, 7, '彼はまた、自分が造ったアシェラの彫像を宮に安置した。主はかつてこの宮について、ダビデとその子ソロモンに言われた。「わたしは、この宮に、そしてわたしがイスラエルの全部族の中から選んだエルサレムに、わたしの名をとこしえに置く。'),
('JPN', '列王纪下', 12, 21, 8, 'もし彼らが、わたしの命じたすべてのこと、わたしのしもべモーセが彼らに命じたすべての律法を守り行いさえするなら、わたしはもう二度と、彼らの先祖たちに与えた地からイスラエルの足を迷い出させない。」'),
('JPN', '列王纪下', 12, 21, 9, 'しかし、彼らはこれに聞き従わなかった。マナセは彼らを迷わせて、主がイスラエルの子らの前で根絶やしにされた異邦の民よりも、さらに悪いことを行わせた。'),
('JPN', '列王纪下', 12, 21, 10, '主は、そのしもべである預言者たちによって、次のように告げられた。'),
('JPN', '列王纪下', 12, 21, 11, '「ユダの王マナセは、これらの忌み嫌うべきことを行い、実に彼以前にいたアモリ人が行ったすべてのことよりもさらに悪いことを行い、その偶像でユダにまで罪を犯させた。'),
('JPN', '列王纪下', 12, 21, 12, 'それゆえ、イスラエルの神、主はこう言われる。見よ、わたしはエルサレムとユダにわざわいをもたらす。だれでもそれを聞く者は、両耳が鳴る。'),
('JPN', '列王纪下', 12, 21, 13, 'わたしは、サマリアに使った測り縄と、アハブの家に使った重りをエルサレムの上に伸ばし、人が皿をぬぐい、それをぬぐって伏せるように、わたしはエルサレムをぬぐい去る。'),
('JPN', '列王纪下', 12, 21, 14, 'わたしは、わたしのゆずりの民の残りの者を捨て去り、彼らを敵の手に渡す。彼らはそのすべての敵の餌食となって奪い取られる。'),
('JPN', '列王纪下', 12, 21, 15, 'それは、彼らの先祖たちがエジプトを出た日から今日まで、わたしの目に悪であることを行って、わたしの怒りを引き起こしたからである。」'),
('JPN', '列王纪下', 12, 21, 16, 'マナセは、ユダに罪を犯させて、主の目に悪であることを行わせた罪だけでなく、咎のない者の血まで多量に流したが、それはエルサレムの隅々に満ちるほどであった。'),
('JPN', '列王纪下', 12, 21, 17, 'マナセについてのその他の事柄、彼が行ったすべてのこと、彼が犯した罪、それは『ユダの王の歴代誌』に確かに記されている。'),
('JPN', '列王纪下', 12, 21, 18, 'マナセは先祖とともに眠りにつき、その家の園、ウザの園に葬られた。彼の子アモンが代わって王となった。'),
('JPN', '列王纪下', 12, 21, 19, 'アモンは二十二歳で王となり、エルサレムで二年間、王であった。彼の母の名はメシュレメテといい、ヨテバ出身のハルツの娘であった。'),
('JPN', '列王纪下', 12, 21, 20, '彼はその父マナセが行ったように、主の目に悪であることを行った。'),
('JPN', '列王纪下', 12, 21, 21, '彼は父の歩んだすべての道に歩み、父が仕えた偶像に仕え、それらを拝み、'),
('JPN', '列王纪下', 12, 21, 22, '彼の父祖の神、主を捨てて、主の道に歩もうとはしなかった。'),
('JPN', '列王纪下', 12, 21, 23, 'アモンの家来たちは彼に謀反を起こし、その宮殿の中で王を殺した。'),
('JPN', '列王纪下', 12, 21, 24, 'しかし、民衆はアモン王に謀反を起こした者をみな打ち殺した。民衆はアモンの子ヨシヤを代わりに王とした。'),
('JPN', '列王纪下', 12, 21, 25, 'アモンが行ったその他の事柄、それは『ユダの王の歴代誌』に確かに記されている。'),
('JPN', '列王纪下', 12, 21, 26, '人々は彼をウザの園にある彼の墓に葬った。彼の子ヨシヤが代わって王となった。'),
('JPN', '列王纪下', 12, 22, 1, 'ヨシヤは八歳で王となり、エルサレムで三十一年間、王であった。彼の母の名はエディダといい、ボツカテ出身のアダヤの娘であった。'),
('JPN', '列王纪下', 12, 22, 2, '彼は主の目にかなうことを行い、父祖ダビデのすべての道に歩み、右にも左にもそれなかった。'),
('JPN', '列王纪下', 12, 22, 3, 'ヨシヤ王の第十八年に、王は、メシュラムの子アツァルヤの子である書記シャファンを主の宮に遣わして言った。'),
('JPN', '列王纪下', 12, 22, 4, '「大祭司ヒルキヤのもとに上って行き、主の宮に納められていた金、すなわち、入り口を守る者たちが民から集めたものを彼に計算させよ。'),
('JPN', '列王纪下', 12, 22, 5, '彼らが主の宮で工事をしている監督者たちにそれを手渡すようにせよ。そして、監督者たちは、神殿の破損の修理をするために、主の宮で工事をしている者たちにそれを渡すようにせよ。'),
('JPN', '列王纪下', 12, 22, 6, '大工、建築する者、石工に渡し、神殿の修理のための木材や切り石を買わせよ。'),
('JPN', '列王纪下', 12, 22, 7, 'ただし、彼らの手に渡した金の精算がなされる必要はない。彼らは忠実に働いているからである。」'),
('JPN', '列王纪下', 12, 22, 8, 'そのとき、大祭司ヒルキヤは書記シャファンに、「主の宮で律法の書を見つけました」と言った。そしてヒルキヤがその書物をシャファンに渡したので、彼はそれを読んだ。'),
('JPN', '列王纪下', 12, 22, 9, '書記シャファンは王のもとに行って、王に報告した。「しもべたちは、神殿にあった金を取り出して、これを主の宮で工事している監督者たちの手に渡しました。」'),
('JPN', '列王纪下', 12, 22, 10, 'さらに書記シャファンは王に告げた。「祭司ヒルキヤが私に一つの書物を渡してくれました。」シャファンは王の前でそれを読み上げた。'),
('JPN', '列王纪下', 12, 22, 11, '王は律法の書のことばを聞いたとき、自分の衣を引き裂いた。'),
('JPN', '列王纪下', 12, 22, 12, '王は祭司ヒルキヤ、シャファンの子アヒカム、ミカヤの子アクボル、書記シャファン、王の家来アサヤに次のように命じた。'),
('JPN', '列王纪下', 12, 22, 13, '「行って、この見つかった書物のことばについて、私のため、民のため、ユダ全体のために、主を求めよ。私たちの先祖たちがこの書物のことばに聞き従わず、すべて私たちについて記されているとおりに行わなかったために、私たちに向かって燃え上がった主の憤りが激しいからだ。」'),
('JPN', '列王纪下', 12, 22, 14, 'そこで、祭司ヒルキヤ、アヒカム、アクボル、シャファン、アサヤは、女預言者フルダのもとに行った。彼女は、ハルハスの子ティクワの子である装束係シャルムの妻で、エルサレムの第二区に住んでいた。彼らが彼女に伝えると、'),
('JPN', '列王纪下', 12, 22, 15, '彼女は彼らに答えた。「イスラエルの神である主はこう言われます。『あなたがたをわたしのもとに遣わした人に言え。'),
('JPN', '列王纪下', 12, 22, 16, '主はこう言われる。見よ。わたしは、ユダの王が読み上げた書物のすべてのことばどおりに、この場所とその住民の上にわざわいをもたらす。'),
('JPN', '列王纪下', 12, 22, 17, '彼らはわたしを捨て、ほかの神々に犠牲を供え、自分たちのすべての手のわざで、わたしの怒りを引き起こした。こうして、わたしの憤りはこの場所に燃え上がり、消えることはない。』'),
('JPN', '列王纪下', 12, 22, 18, '主を求めるためにあなたがたを遣わしたユダの王には、こう言いなさい。『あなたが聞いたことばについて、イスラエルの神である主は、こう言われる。'),
('JPN', '列王纪下', 12, 22, 19, 'あなたは、わたしがこの場所とその住民について、これは恐怖のもととなり、ののしりの的となると告げたのを聞いた。そのとき、あなたは心を痛めて主の前にへりくだり、自分の衣を引き裂いてわたしの前で泣いたので、わたしもまた、あなたの願いを聞き入れる──主のことば──。'),
('JPN', '列王纪下', 12, 22, 20, 'それゆえ、見よ、わたしはあなたを先祖たちのもとに集める。あなたは平安のうちに自分の墓に集められる。あなたは自分の目で、わたしがこの場所にもたらす、すべてのわざわいを見ることはない。』」彼らはそれを王に報告した。'),
('JPN', '列王纪下', 12, 23, 1, '王は使者を遣わして、ユダとエルサレムのすべての長老たちを彼のところに集めた。'),
('JPN', '列王纪下', 12, 23, 2, '王は、ユダのすべての人々、エルサレムのすべての住民、祭司と預言者、および下の者から上の者まで、すべての民とともに主の宮に上り、主の宮で見つかった契約の書のことばをすべて彼らに読み聞かせた。'),
('JPN', '列王纪下', 12, 23, 3, 'それから王は柱のわきに立ち、主の前に契約を結び、主に従って歩み、心を尽くし、いのちを尽くして主の命令と証しと掟を守り、この書物に記されているこの契約のことばを実行することを誓った。民もみなこの契約に加わった。'),
('JPN', '列王纪下', 12, 23, 4, '王は大祭司ヒルキヤと次席祭司たち、および、入り口を守る者たちに命じて、バアルやアシェラや天の万象のために作られた祭具をことごとく主の神殿から運び出し、エルサレムの郊外、キデロンの野でそれらを焼き、その灰をベテルへ持って行った。'),
('JPN', '列王纪下', 12, 23, 5, '彼はまた、偶像に仕える祭司たちを取り除いた。ユダの王たちが任命して、ユダの町々やエルサレム周辺の高き所で犠牲を供えていた祭司たちである。バアルや太陽や月や星座や天の万象に犠牲を供える者たちも取り除いた。'),
('JPN', '列王纪下', 12, 23, 6, '彼はまた、アシェラ像を主の宮からエルサレム郊外のキデロンの谷に運び出し、それをキデロンの谷で焼いた。それを粉々に砕いて灰にし、その灰を共同墓地にまき散らした。'),
('JPN', '列王纪下', 12, 23, 7, 'さらに、主の宮の中にあった神殿男娼の家を打ち壊した。そこでは、女たちがアシェラ像のために覆いを織っていた。'),
('JPN', '列王纪下', 12, 23, 8, '彼はユダの町々から祭司たちをみな連れて来て、祭司たちが犠牲を供えていたゲバからベエル・シェバに至るまでの高き所を汚し、門にあった高き所を打ち壊した。それは町の長ヨシュアの門の入り口にあり、町の門に入る人の左側にあった。'),
('JPN', '列王纪下', 12, 23, 9, '高き所の祭司たちは、エルサレムの主の祭壇に上ることはなかったが、その兄弟たちの間で種なしパンを食べていた。'),
('JPN', '列王纪下', 12, 23, 10, '彼はベン・ヒノムの谷にあるトフェトを汚し、だれも、自分の息子や娘に火の中を通らせてモレクに献げることのないようにした。'),
('JPN', '列王纪下', 12, 23, 11, 'それから、ユダの王たちが太陽に献納した馬を、主の宮の入り口、前庭にある宦官ネタン・メレクの部屋のそばから取り除き、太陽の車を火で焼いた。'),
('JPN', '列王纪下', 12, 23, 12, '王は、ユダの王たちがアハズの屋上の部屋の上に造った祭壇と、マナセが主の宮の二つの庭に造った祭壇を、そこから外して打ち壊し、砕いた。そうして、その灰をキデロンの谷に投げ捨てた。'),
('JPN', '列王纪下', 12, 23, 13, '王は、エルサレムの東、破壊の山の南にあった高き所を汚れたものとした。これは、イスラエルの王ソロモンが、シドン人の忌むべき女神アシュタロテ、モアブの忌むべき神ケモシュ、アンモン人の忌み嫌うべき神ミルコムのために築いたものであった。'),
('JPN', '列王纪下', 12, 23, 14, 'また、石の柱を打ち砕き、アシェラ像を切り倒し、その場所を人の骨で満たした。'),
('JPN', '列王纪下', 12, 23, 15, 'さらに彼は、ベテルにある祭壇と、イスラエルに罪を犯させたネバテの子ヤロブアムが造った高き所、すなわち、その祭壇も高き所も打ち壊し、さらに高き所を焼いて粉々に砕いて灰にし、アシェラ像も焼いた。'),
('JPN', '列王纪下', 12, 23, 16, 'ヨシヤが振り向くと、山の中に墓があるのが見えた。そこで彼は人を遣わしてその墓から骨を取り出し、それを祭壇の上で焼き、祭壇を汚れたものとした。かつて、神の人がこのことを預言して叫んだ主のことばのとおりであった。'),
('JPN', '列王纪下', 12, 23, 17, 'ヨシヤは言った。「あそこに見える石碑は何か。」すると、町の人々は彼に答えた。「ユダから出て来て、あなたがベテルの祭壇に対してされたこれらのことを預言した神の人の墓です。」'),
('JPN', '列王纪下', 12, 23, 18, '王は言った。「そのままにしておけ。だれも彼の骨を移してはならない。」そこで人々は彼の骨を、サマリアから出て来たあの預言者の骨と一緒にそのままにしておいた。'),
('JPN', '列王纪下', 12, 23, 19, 'ヨシヤはまた、イスラエルの王たちが造って主の怒りを引き起こした、サマリアの町々の高き所の宮もすべて取り除き、彼がベテルでしたのと全く同じことを、それらに対しても行った。'),
('JPN', '列王纪下', 12, 23, 20, '彼は、そこにいた高き所の祭司たちをみな、祭壇の上で屠り、その祭壇の上で人の骨を焼いた。こうして、彼はエルサレムに帰った。'),
('JPN', '列王纪下', 12, 23, 21, '王は民全体に次のように命じた。「この契約の書に記されているとおり、あなたがたの神、主に、過越のいけにえを献げよ。」'),
('JPN', '列王纪下', 12, 23, 22, '実に、さばきつかさたちがイスラエルをさばいた時代以来、イスラエルの王たちとユダの王たちのどの時代にも、このような過越のいけにえが献げられたことはなかった。'),
('JPN', '列王纪下', 12, 23, 23, 'ただ、ヨシヤ王の第十八年に、エルサレムでこの過越のいけにえが主に献げられただけであった。'),
('JPN', '列王纪下', 12, 23, 24, 'さらにヨシヤは、霊媒、口寄せ、テラフィム、偶像、それに、ユダの地とエルサレムに見られるすべての忌むべき物も除き去った。こうして、彼は祭司ヒルキヤが主の宮で見つけた書物に記されている律法のことばを実行した。'),
('JPN', '列王纪下', 12, 23, 25, 'ヨシヤのようにモーセのすべての律法にしたがって、心のすべて、たましいのすべて、力のすべてをもって主に立ち返った王は、彼より前にはいなかった。彼の後にも彼のような者は、一人も起こらなかった。'),
('JPN', '列王纪下', 12, 23, 26, 'それにもかかわらず、マナセが引き起こした主のすべての怒りのゆえに、主はユダに向けて燃やした激しい怒りを収めようとはされなかった。'),
('JPN', '列王纪下', 12, 23, 27, '主は言われた。「わたしがイスラエルを除いたのと同じように、ユダもわたしの前から除く。わたしが選んだこの都エルサレムも、わたしの名を置くと言ったこの宮も、わたしは退ける。」'),
('JPN', '列王纪下', 12, 23, 28, 'ヨシヤについてのその他の事柄、彼が行ったすべてのこと、それは『ユダの王の歴代誌』に確かに記されている。'),
('JPN', '列王纪下', 12, 23, 29, '彼の時代に、エジプトの王ファラオ・ネコが、アッシリアの王のもとに行こうと、ユーフラテス川を目指して上って来た。そこで、ヨシヤ王は彼を迎え撃ちに行ったが、ファラオ・ネコはメギドで彼に出会った際、彼を殺した。'),
('JPN', '列王纪下', 12, 23, 30, 'ヨシヤの家来たちは、彼の遺体を戦車に載せ、メギドからエルサレムに運んで、彼の墓に葬った。その国の民は、ヨシヤの子エホアハズを選んで油を注ぎ、彼の父に代えて王とした。'),
('JPN', '列王纪下', 12, 23, 31, 'エホアハズは二十三歳で王となり、エルサレムで三か月間、王であった。彼の母の名はハムタルといい、リブナ出身のエレミヤの娘であった。'),
('JPN', '列王纪下', 12, 23, 32, '彼は、すべてその先祖たちがしたように、主の目に悪であることを行った。'),
('JPN', '列王纪下', 12, 23, 33, 'ファラオ・ネコは、エルサレムで王であった彼をハマテの地リブラに幽閉し、この国に銀百タラントと金一タラントの科料を課した。'),
('JPN', '列王纪下', 12, 23, 34, 'それから、ファラオ・ネコは、ヨシヤの子エルヤキムをその父ヨシヤに代えて王とし、その名をエホヤキムと改めさせた。エホアハズは捕らえられ、エジプトに行き、そこで死んだ。'),
('JPN', '列王纪下', 12, 23, 35, 'エホヤキムは銀と金をファラオに贈った。ただし、ファラオの要求するだけの銀を贈るために、この国に税を課さなければならなかった。彼は、ファラオ・ネコに贈るために、一人ひとりに税を割り当て、銀と金を民衆から取り立てた。'),
('JPN', '列王纪下', 12, 23, 36, 'エホヤキムは二十五歳で王となり、エルサレムで十一年間、王であった。彼の母の名はゼブダといい、ルマ出身のペダヤの娘であった。'),
('JPN', '列王纪下', 12, 23, 37, '彼は、すべてその先祖たちがしたように、主の目に悪であることを行った。'),
('JPN', '列王纪下', 12, 24, 1, 'エホヤキムの時代に、バビロンの王ネブカドネツァルが攻め上って来た。エホヤキムは三年間彼のしもべとなったが、その後、再び彼に反逆した。'),
('JPN', '列王纪下', 12, 24, 2, 'そこで主は、カルデア人の略奪隊、アラムの略奪隊、モアブの略奪隊、アンモン人の略奪隊を遣わしてエホヤキムを攻められた。ユダを攻めて滅ぼすために彼らを遣わされたのである。主がそのしもべである預言者たちによって告げられたことばのとおりであった。'),
('JPN', '列王纪下', 12, 24, 3, '実に、このようなことがユダに起こったのは、ユダを主の前から除くという主の命によることであり、それはマナセが犯したすべての罪のゆえ、'),
('JPN', '列王纪下', 12, 24, 4, 'また、マナセが流した咎のない者の血のためであった。マナセはエルサレムを咎のない者の血で満たした。そのため主は赦そうとはされなかったのである。'),
('JPN', '列王纪下', 12, 24, 5, 'エホヤキムについてのその他の事柄、彼が行ったすべてのこと、それは『ユダの王の歴代誌』に確かに記されている。'),
('JPN', '列王纪下', 12, 24, 6, 'エホヤキムは先祖とともに眠りにつき、その子エホヤキンが代わって王となった。'),
('JPN', '列王纪下', 12, 24, 7, 'エジプトの王は自分の国から再び出て来ることがなかった。バビロンの王が、エジプト川から大河ユーフラテスに至るまで、かつてエジプトの王に属していた全領土を占領したからである。'),
('JPN', '列王纪下', 12, 24, 8, 'エホヤキンは十八歳で王となり、エルサレムで三か月間、王であった。彼の母の名はネフシュタといい、エルサレム出身のエルナタンの娘であった。'),
('JPN', '列王纪下', 12, 24, 9, '彼は、すべて先祖たちがしたように、主の目に悪であることを行った。'),
('JPN', '列王纪下', 12, 24, 10, 'そのころ、バビロンの王ネブカドネツァルの家来たちがエルサレムに攻め上り、都は包囲された。'),
('JPN', '列王纪下', 12, 24, 11, 'バビロンの王ネブカドネツァルが都にやって来たとき、彼の家来たちは都を包囲していた。'),
('JPN', '列王纪下', 12, 24, 12, 'ユダの王エホヤキンは、その母、家来たち、高官たち、宦官たちと一緒にバビロンの王に降伏したので、バビロンの王は、その治世の第八年に、彼を捕虜にした。'),
('JPN', '列王纪下', 12, 24, 13, 'バビロンの王は、主の宮の財宝と王宮の財宝をことごとく運び出し、主の神殿の中にあるイスラエルの王ソロモンが作ったすべての金の用具を切り裂いた。主が告げられたとおりであった。'),
('JPN', '列王纪下', 12, 24, 14, '彼はエルサレムのすべて、すなわち、すべての高官、すべての有力者一万人、それに職人や鍛冶もみな、捕囚として捕らえ移した。貧しい民衆のほかは残されなかった。'),
('JPN', '列王纪下', 12, 24, 15, '彼はさらに、エホヤキンをバビロンへ引いて行き、王の母、王の妻たち、その宦官たち、この国のおもだった人々を、捕囚としてエルサレムからバビロンへ行かせた。'),
('JPN', '列王纪下', 12, 24, 16, 'バビロンの王は、すべての勇士たち七千人と、職人、鍛冶千人からなる勇敢な戦士たちすべてを、捕囚としてバビロンへ連れて行った。'),
('JPN', '列王纪下', 12, 24, 17, 'バビロンの王は、エホヤキンのおじマタンヤをエホヤキンの代わりに王とし、その名をゼデキヤと改めさせた。'),
('JPN', '列王纪下', 12, 24, 18, 'ゼデキヤは二十一歳で王となり、エルサレムで十一年間、王であった。彼の母の名はハムタルといい、リブナ出身のエレミヤの娘であった。'),
('JPN', '列王纪下', 12, 24, 19, '彼は、すべてエホヤキムがしたように、主の目に悪であることを行った。'),
('JPN', '列王纪下', 12, 24, 20, '実に、エルサレムとユダが主の前から投げ捨てられるに至ったのは、主の怒りによることであったのである。その後、ゼデキヤはバビロンの王に反逆した。'),
('JPN', '列王纪下', 12, 25, 1, 'ゼデキヤの治世の第九年、第十の月の十日に、バビロンの王ネブカドネツァルは、その全軍勢を率いてエルサレムを攻めに来て、これに対して陣を敷き、周囲に塁を築いた。'),
('JPN', '列王纪下', 12, 25, 2, 'こうして都はゼデキヤ王の第十一年まで包囲されていた。'),
('JPN', '列王纪下', 12, 25, 3, '第四の月の九日、都の中で食糧難がひどくなり、民衆に食物がなくなった。'),
('JPN', '列王纪下', 12, 25, 4, 'そのとき、都は破られ、戦士たちはみな夜のうちに、王の園に近い二重の城壁の間にある、門の道から出て行った。カルデア人が都を包囲していたので、王はアラバへの道を進んだ。'),
('JPN', '列王纪下', 12, 25, 5, 'カルデアの軍勢は王の後を追い、エリコの草原で彼に追いついた。すると、王の軍隊はみな王から離れて散ってしまった。'),
('JPN', '列王纪下', 12, 25, 6, 'カルデアの軍勢は王を捕らえ、リブラにいるバビロンの王のところに彼を連れ上り、彼に宣告を下した。'),
('JPN', '列王纪下', 12, 25, 7, '彼らはゼデキヤの息子たちを彼の目の前で虐殺した。王はゼデキヤの目をつぶし、青銅の足かせをはめて、バビロンへ連れて行った。'),
('JPN', '列王纪下', 12, 25, 8, '第五の月の七日、バビロンの王ネブカドネツァル王の第十九年のこと、バビロンの王の家来、親衛隊の長ネブザルアダンがエルサレムに来て、'),
('JPN', '列王纪下', 12, 25, 9, '主の宮と王宮とエルサレムのすべての家を焼き、そのおもだった建物をことごとく火で焼いた。'),
('JPN', '列王纪下', 12, 25, 10, '親衛隊の長と一緒にいたカルデアの全軍勢は、エルサレムを取り巻く城壁を打ち壊した。'),
('JPN', '列王纪下', 12, 25, 11, '親衛隊の長ネブザルアダンは、都に残されていた残りの民と、バビロンの王に降伏した投降者たちと、残りの群衆を捕らえ移した。'),
('JPN', '列王纪下', 12, 25, 12, 'しかし、親衛隊の長はその地の貧しい民の一部を残し、ぶどうを作る者と農夫にした。'),
('JPN', '列王纪下', 12, 25, 13, 'カルデア人は、主の宮の青銅の柱と、車輪付きの台と、主の宮にある青銅の「海」を砕いて、その青銅をバビロンへ運んだ。'),
('JPN', '列王纪下', 12, 25, 14, 'また、灰壺、十能、芯取りばさみ、平皿、奉仕に用いるすべての青銅の器具を奪った。'),
('JPN', '列王纪下', 12, 25, 15, 'また親衛隊の長は、火皿、鉢など、純金や純銀のものを奪った。'),
('JPN', '列王纪下', 12, 25, 16, 'ソロモンが主の宮のために作った二本の柱、一つの「海」、車輪付きの台、これらすべての物の青銅の重さは、量りきれなかった。'),
('JPN', '列王纪下', 12, 25, 17, '一本の柱の高さは十八キュビト、その上の柱頭は青銅、その柱頭の高さは三キュビトであった。柱頭の周りに格子細工とざくろがあって、すべて青銅であった。もう一つの柱も、格子細工もこれと同様であった。'),
('JPN', '列王纪下', 12, 25, 18, '親衛隊の長は、祭司のかしらセラヤと次席祭司ゼパニヤと三人の入り口を守る者を捕らえ、'),
('JPN', '列王纪下', 12, 25, 19, '戦士たちの指揮官であった一人の宦官、都にいた王の五人の側近、民衆を徴兵する軍の長の書記、そして都にいた民衆六十人を、都から連れ去った。'),
('JPN', '列王纪下', 12, 25, 20, '親衛隊の長ネブザルアダンは彼らを捕らえ、リブラにいるバビロンの王のところへ連れて行った。'),
('JPN', '列王纪下', 12, 25, 21, 'バビロンの王はハマテの地のリブラで、彼らを打ち殺した。こうして、ユダはその国から捕らえ移された。'),
('JPN', '列王纪下', 12, 25, 22, 'バビロンの王ネブカドネツァルは、彼が残したユダの地の残りの民の上に、シャファンの子アヒカムの子ゲダルヤを総督として任命した。'),
('JPN', '列王纪下', 12, 25, 23, '軍の高官たちとその部下たちはみな、バビロンの王がゲダルヤを総督としたことを聞いて、ミツパにいるゲダルヤのもとに来た。それは、ネタンヤの子イシュマエル、カレアハの子ヨハナン、ネトファ人タンフメテの子セラヤ、マアカ人の子ヤアザンヤ、彼らとその部下たちであった。'),
('JPN', '列王纪下', 12, 25, 24, 'ゲダルヤは彼らとその部下たちに誓って、彼らに言った。「カルデア人の家来たちを恐れてはならない。この地に住んで、バビロンの王に仕えなさい。そうすれば、あなたがたは幸せになる。」'),
('JPN', '列王纪下', 12, 25, 25, 'ところが第七の月に、王族の一人、エリシャマの子ネタンヤの子イシュマエルは、十人の部下とともに来て、ゲダルヤを打ち殺し、ミツパで彼と一緒にいたユダの人たちとカルデア人たちを打ち殺した。'),
('JPN', '列王纪下', 12, 25, 26, 'そこで民はみな、身分の下の者から上の者まで、軍の高官たちとともに、立ってエジプトへ行った。カルデア人を恐れたからである。'),
('JPN', '列王纪下', 12, 25, 27, 'ユダの王エホヤキンが捕らえ移されて三十七年目の第十二の月の二十七日、バビロンの王エビル・メロダクは、王となったその年のうちにユダの王エホヤキンを牢獄から呼び戻し、'),
('JPN', '列王纪下', 12, 25, 28, '優しいことばをかけ、バビロンで彼とともにいた王たちの位よりも、彼の位を高くした。'),
('JPN', '列王纪下', 12, 25, 29, '彼は囚人の服を脱ぎ、その一生の間、いつも王の前で食事をした。'),
('JPN', '列王纪下', 12, 25, 30, '彼の生活費はその日々の分を、一生の間、いつも王から支給されていた。'),
('JPN', '历代志上', 13, 1, 1, 'アダム、セツ、エノシュ、'),
('JPN', '历代志上', 13, 1, 2, 'ケナン、マハラルエル、ヤレデ、'),
('JPN', '历代志上', 13, 1, 3, 'エノク、メトシェラ、レメク、'),
('JPN', '历代志上', 13, 1, 4, 'ノア、セム、ハム、それにヤフェテ。'),
('JPN', '历代志上', 13, 1, 5, 'ヤフェテの子らはゴメル、マゴグ、マダイ、ヤワン、トバル、メシェク、ティラス。'),
('JPN', '历代志上', 13, 1, 6, 'ゴメルの子らはアシュケナズ、ディファテ、トガルマ。'),
('JPN', '历代志上', 13, 1, 7, 'ヤワンの子らはエリシャ、タルシシュ、キティム、ロダニム。'),
('JPN', '历代志上', 13, 1, 8, 'ハムの子らはクシュ、ミツライム、プテ、カナン。'),
('JPN', '历代志上', 13, 1, 9, 'クシュの子らはセバ、ハビラ、サブタ、ラアマ、サブテカ。ラアマの子らはシェバ、デダン。'),
('JPN', '历代志上', 13, 1, 10, 'このクシュがニムロデを生んだ。ニムロデは地上で最初の勇士となった。'),
('JPN', '历代志上', 13, 1, 11, 'ミツライムが生んだのは、ルディ人、アナミム人、レハビム人、ナフトヒム人、'),
('JPN', '历代志上', 13, 1, 12, 'パテロス人、カスルヒム人、カフトル人。このカスルヒム人からペリシテ人が出た。'),
('JPN', '历代志上', 13, 1, 13, 'カナンが生んだのは、長子シドン、ヒッタイト、'),
('JPN', '历代志上', 13, 1, 14, 'エブス人、アモリ人、ギルガシ人、'),
('JPN', '历代志上', 13, 1, 15, 'ヒビ人、アルキ人、シニ人、'),
('JPN', '历代志上', 13, 1, 16, 'アルワデ人、ツェマリ人、ハマテ人。'),
('JPN', '历代志上', 13, 1, 17, 'セムの子らは、エラム、アッシュル、アルパクシャデ、ルデ、アラム、ウツ、フル、ゲテル、メシェク。'),
('JPN', '历代志上', 13, 1, 18, 'アルパクシャデはシェラフを生み、シェラフはエベルを生んだ。'),
('JPN', '历代志上', 13, 1, 19, 'エベルには二人の息子が生まれ、一人の名はペレグであった。その時代に地が分けられたからである。彼の兄弟の名はヨクタンであった。'),
('JPN', '历代志上', 13, 1, 20, 'ヨクタンが生んだのは、アルモダデ、シェレフ、ハツァルマベテ、エラフ、'),
('JPN', '历代志上', 13, 1, 21, 'ハドラム、ウザル、ディクラ、'),
('JPN', '历代志上', 13, 1, 22, 'エバル、アビマエル、シェバ、'),
('JPN', '历代志上', 13, 1, 23, 'オフィル、ハビラ、ヨバブ。これらはみな、ヨクタンの子であった。'),
('JPN', '历代志上', 13, 1, 24, 'セム、アルパクシャデ、シェラフ、'),
('JPN', '历代志上', 13, 1, 25, 'エベル、ペレグ、レウ、'),
('JPN', '历代志上', 13, 1, 26, 'セルグ、ナホル、テラ、'),
('JPN', '历代志上', 13, 1, 27, 'アブラム、すなわちアブラハム。'),
('JPN', '历代志上', 13, 1, 28, 'アブラハムの子は、イサク、イシュマエル。'),
('JPN', '历代志上', 13, 1, 29, 'これは彼らの系図である。イシュマエルの長子はネバヨテ。それからケダル、アデベエル、ミブサム、'),
('JPN', '历代志上', 13, 1, 30, 'ミシュマ、ドマ、マサ、ハダド、テマ、'),
('JPN', '历代志上', 13, 1, 31, 'エトル、ナフィシュ、ケデマ。これらがイシュマエルの子である。'),
('JPN', '历代志上', 13, 1, 32, 'アブラハムの側女ケトラの子。彼女は、ジムラン、ヨクシャン、メダン、ミディアン、イシュバク、シュアハを産んだ。ヨクシャンの子は、シェバ、デダン。'),
('JPN', '历代志上', 13, 1, 33, 'ミディアンの子は、エファ、エフェル、ハノク、アビダ、エルダア。これらはみな、ケトラの子であった。'),
('JPN', '历代志上', 13, 1, 34, 'アブラハムはイサクを生んだ。イサクの子は、エサウ、イスラエル。'),
('JPN', '历代志上', 13, 1, 35, 'エサウの子は、エリファズ、レウエル、エウシュ、ヤラム、コラ。'),
('JPN', '历代志上', 13, 1, 36, 'エリファズの子は、テマン、オマル、ツェフィ、ガタム、ケナズ、そして、ティムナによるアマレク。'),
('JPN', '历代志上', 13, 1, 37, 'レウエルの子は、ナハテ、ゼラフ、シャンマ、ミザ。'),
('JPN', '历代志上', 13, 1, 38, 'セイルの子は、ロタン、ショバル、ツィブオン、アナ、ディション、エツェル、ディシャン。'),
('JPN', '历代志上', 13, 1, 39, 'ロタンの子は、ホリ、ホマム。ロタンの妹はティムナ。'),
('JPN', '历代志上', 13, 1, 40, 'ショバルの子は、アルヤン、マナハテ、エバル、シェフィ、オナム。ツィブオンの子は、アヤ、アナ。'),
('JPN', '历代志上', 13, 1, 41, 'アナの子は、ディション。ディションの子は、ハムラン、エシュバン、イテラン、ケラン。'),
('JPN', '历代志上', 13, 1, 42, 'エツェルの子は、ビルハン、ザアワン、ヤアカン。ディションの子は、ウツ、アラン。'),
('JPN', '历代志上', 13, 1, 43, 'イスラエルの子らを王が治める以前、エドムの地で王として治めた者は次のとおりである。ベオルの子ベラ。彼の町の名はディンハバであった。'),
('JPN', '历代志上', 13, 1, 44, 'ベラが死ぬと、ボツラ出身のゼラフの子ヨバブが代わりに王となった。'),
('JPN', '历代志上', 13, 1, 45, 'ヨバブが死ぬと、テマン人の地から出たフシャムが代わりに王となった。'),
('JPN', '历代志上', 13, 1, 46, 'フシャムが死ぬと、モアブの野でミディアン人を打ち破った、ベダデの子ハダドが代わりに王となった。その町の名はアウィテであった。'),
('JPN', '历代志上', 13, 1, 47, 'ハダドが死ぬと、マスレカ出身のサムラが代わりに王となった。'),
('JPN', '历代志上', 13, 1, 48, 'サムラが死ぬと、レホボテ・ハ・ナハル出身のシャウルが代わりに王となった。'),
('JPN', '历代志上', 13, 1, 49, 'シャウルが死ぬと、アクボルの子バアル・ハナンが代わりに王となった。'),
('JPN', '历代志上', 13, 1, 50, 'バアル・ハナンが死ぬと、ハダドが代わりに王となった。彼の町の名はパイであった。妻の名はメヘタブエルで、メ・ザハブの娘マテレデの娘であった。'),
('JPN', '历代志上', 13, 1, 51, 'そして、ハダドも死んだ。エドムの首長たちは、首長ティムナ、首長アルワ、首長エテテ、'),
('JPN', '历代志上', 13, 1, 52, '首長オホリバマ、首長エラ、首長ピノン、'),
('JPN', '历代志上', 13, 1, 53, '首長ケナズ、首長テマン、首長ミブツァル、'),
('JPN', '历代志上', 13, 1, 54, '首長マグディエル、首長イラム。これらはエドムの首長である。'),
('JPN', '历代志上', 13, 2, 1, 'イスラエルの子は次のとおりである。ルベン、シメオン、レビ、ユダ、イッサカル、ゼブルン、'),
('JPN', '历代志上', 13, 2, 2, 'ダン、ヨセフ、ベニヤミン、ナフタリ、ガド、アシェル。'),
('JPN', '历代志上', 13, 2, 3, 'ユダの子はエル、オナン、シェラ。この三人は、カナンの女シュアの娘から彼に生まれた。しかし、長子エルは主の目に悪しき者であったので、主が彼を殺された。'),
('JPN', '历代志上', 13, 2, 4, 'ユダの嫁タマルは彼にペレツとゼラフを産んだ。ユダの子は全部で五人。'),
('JPN', '历代志上', 13, 2, 5, 'ペレツの子は、ヘツロン、ハムル。'),
('JPN', '历代志上', 13, 2, 6, 'ゼラフの子は、ジムリ、エタン、ヘマン、カルコル、ダラで、全部で五人。'),
('JPN', '历代志上', 13, 2, 7, 'カルミの子は、聖絶の物のことで主の信頼を裏切り、イスラエルにわざわいをもたらす者となったアカル。'),
('JPN', '历代志上', 13, 2, 8, 'エタンの子は、アザルヤ。'),
('JPN', '历代志上', 13, 2, 9, 'ヘツロンの子として生まれた者は、エラフメエル、ラム、カレブ。'),
('JPN', '历代志上', 13, 2, 10, 'ラムはアミナダブを生み、アミナダブはユダ族の首長ナフションを生み、'),
('JPN', '历代志上', 13, 2, 11, 'ナフションはサルマを生み、サルマはボアズを生み、'),
('JPN', '历代志上', 13, 2, 12, 'ボアズはオベデを生み、オベデはエッサイを生んだ。'),
('JPN', '历代志上', 13, 2, 13, 'エッサイは、長子エリアブ、次男アビナダブ、三男シムア、'),
('JPN', '历代志上', 13, 2, 14, '四男ネタンエル、五男ラダイ、'),
('JPN', '历代志上', 13, 2, 15, '六男オツェム、七男ダビデを生んだ。'),
('JPN', '历代志上', 13, 2, 16, '彼らの姉妹はツェルヤとアビガイル。ツェルヤの子は、アビシャイ、ヨアブ、アサエルの三人であった。'),
('JPN', '历代志上', 13, 2, 17, 'アビガイルはアマサを産んだが、アマサの父はイシュマエル人エテルであった。'),
('JPN', '历代志上', 13, 2, 18, 'ヘツロンの子カレブは、妻アズバとエリオテによって子を生んだ。その子たちは、エシェル、ショバブ、アルドン。'),
('JPN', '历代志上', 13, 2, 19, 'アズバが死んだので、カレブはエフラテを妻とした。彼女はカレブにフルを産んだ。'),
('JPN', '历代志上', 13, 2, 20, 'フルはウリを生み、ウリはベツァルエルを生んだ。'),
('JPN', '历代志上', 13, 2, 21, 'その後、ヘツロンはギルアデの父マキルの娘のところに行き、彼女を妻とした。彼は六十歳であった。彼女はヘツロンにセグブを産んだ。'),
('JPN', '历代志上', 13, 2, 22, 'セグブはヤイルを生んだ。彼はギルアデの地に二十三の町を持っていた。'),
('JPN', '历代志上', 13, 2, 23, 'ところが、ゲシュルとアラムは、その中からハボテ・ヤイル、およびケナテとそれに属する村々など六十の町を取った。これらはみな、ギルアデの父マキルの子であった。'),
('JPN', '历代志上', 13, 2, 24, 'ヘツロンがエフラテのカレブで死んだ後、ヘツロンの妻アビヤは、彼にテコアの父アシュフルを産んだ。'),
('JPN', '历代志上', 13, 2, 25, 'ヘツロンの長子エラフメエルの子は、長子ラム、ブナ、オレン、オツェム、アヒヤ。'),
('JPN', '历代志上', 13, 2, 26, 'エラフメエルには、もう一人の妻がいた。彼女の名はアタラといって、オナムの母であった。'),
('JPN', '历代志上', 13, 2, 27, 'エラフメエルの長子ラムの子は、マアツ、ヤミン、エケル。'),
('JPN', '历代志上', 13, 2, 28, 'オナムの子は、シャンマイ、ヤダ。シャンマイの子は、ナダブ、アビシュル。'),
('JPN', '历代志上', 13, 2, 29, 'アビシュルの妻の名はアビハイルで、彼女はアフバンとモリデを産んだ。'),
('JPN', '历代志上', 13, 2, 30, 'ナダブの子はセレデとアパイムで、セレデは子がないままで死んだ。'),
('JPN', '历代志上', 13, 2, 31, 'アパイムの子はイシュイ。イシュイの子はシェシャン。シェシャンの子はアフライ。'),
('JPN', '历代志上', 13, 2, 32, 'シャンマイの兄弟ヤダの子はエテルとヨナタンで、エテルは子がないままで死んだ。'),
('JPN', '历代志上', 13, 2, 33, 'ヨナタンの子はペレテとザザ。これがエラフメエルの子孫である。'),
('JPN', '历代志上', 13, 2, 34, 'シェシャンには息子がなく、娘だけであった。シェシャンにはエジプト人のしもべがいて、その名はヤルハといった。'),
('JPN', '历代志上', 13, 2, 35, 'シェシャンは彼の娘をそのしもべヤルハに妻として与えたので、彼女はアタイを産んだ。'),
('JPN', '历代志上', 13, 2, 36, 'アタイはナタンを生み、ナタンはザバデを生み、'),
('JPN', '历代志上', 13, 2, 37, 'ザバデはエフラルを生み、エフラルはオベデを生み、'),
('JPN', '历代志上', 13, 2, 38, 'オベデはエフーを生み、エフーはアザルヤを生み、'),
('JPN', '历代志上', 13, 2, 39, 'アザルヤはヘレツを生み、ヘレツはエルアサを生み、'),
('JPN', '历代志上', 13, 2, 40, 'エルアサはシスマイを生み、シスマイはシャルムを生み、'),
('JPN', '历代志上', 13, 2, 41, 'シャルムはエカムヤを生み、エカムヤはエリシャマを生んだ。'),
('JPN', '历代志上', 13, 2, 42, 'エラフメエルの兄弟カレブの子は、長子メシャ。彼はジフの父であった。ヘブロンの父マレシャの子。'),
('JPN', '历代志上', 13, 2, 43, 'ヘブロンの子は、コラ、タプアハ、レケム、シェマ。'),
('JPN', '历代志上', 13, 2, 44, 'シェマは、ヨルコアムの父ラハムを生み、レケムはシャンマイを生んだ。'),
('JPN', '历代志上', 13, 2, 45, 'シャンマイの子はマオン。マオンはベテ・ツルの父であった。'),
('JPN', '历代志上', 13, 2, 46, 'カレブの側女エファは、ハラン、モツァ、ガゼズを産んだ。ハランはガゼズを生んだ。'),
('JPN', '历代志上', 13, 2, 47, 'ヤフダイの子は、レゲム、ヨタム、ゲシャン、ペレテ、エファ、シャアフ。'),
('JPN', '历代志上', 13, 2, 48, 'カレブの側女マアカは、シェベルとティルハナを産み、'),
('JPN', '历代志上', 13, 2, 49, 'マデマナの父シャアフと、マクベナの父でありギブアの父であるシェワを産んだ。カレブの娘はアクサであった。'),
('JPN', '历代志上', 13, 2, 50, 'カレブの子孫は次のとおりである。エフラテによる長子フルの子は、キルヤテ・エアリムの父ショバル、'),
('JPN', '历代志上', 13, 2, 51, 'ベツレヘムの父サルマ、ベテ・ガデルの父ハレフ。'),
('JPN', '历代志上', 13, 2, 52, 'キルヤテ・エアリムの父ショバルの子は、ハ・ロエ、メヌホテ人の半分。'),
('JPN', '历代志上', 13, 2, 53, 'キルヤテ・エアリムの諸氏族は、エテル人、プテ人、シュマ人、ミシュラ人で、彼らの中からツォルア人とエシュタオル人が出た。'),
('JPN', '历代志上', 13, 2, 54, 'サルマの子孫は、ベツレヘム、ネトファ人、アテロテ・ベテ・ヨアブ、マナハテ人の半氏族、ツォルア人。'),
('JPN', '历代志上', 13, 2, 55, 'ヤベツに住んでいた書記の諸氏族のティルアテ人、シムア人、スカテ人。彼らはレカブ家の父祖ハマテから出たケニ人である。'),
('JPN', '历代志上', 13, 3, 1, 'ヘブロンで生まれたダビデの子は次のとおりである。長子はイズレエル人アヒノアムによるアムノン。次男はカルメル人アビガイルによるダニエル。'),
('JPN', '历代志上', 13, 3, 2, '三男はゲシュルの王タルマイの娘マアカの子アブサロム。四男はハギテの子アドニヤ。'),
('JPN', '历代志上', 13, 3, 3, '五男はアビタルによるシェファテヤ。六男はダビデの妻エグラによるイテレアム。'),
('JPN', '历代志上', 13, 3, 4, '六人の子がヘブロンで生まれた。ダビデはそこで七年六か月王であり、エルサレムで三十三年間王であった。'),
('JPN', '历代志上', 13, 3, 5, 'エルサレムで彼に生まれた者は次のとおりである。シャムア、ショバブ、ナタン、ソロモン。この四人はアンミエルの娘バテ・シュアによる子である。'),
('JPN', '历代志上', 13, 3, 6, 'またイブハル、エリシャマ、エリフェレテ、'),
('JPN', '历代志上', 13, 3, 7, 'ノガハ、ネフェグ、ヤフィア、'),
('JPN', '历代志上', 13, 3, 8, 'エリシャマ、エルヤダ、エリフェレテの九人。'),
('JPN', '历代志上', 13, 3, 9, 'みなダビデの子であるが、ほかに側女たちの子もあり、タマルは彼らの姉妹であった。'),
('JPN', '历代志上', 13, 3, 10, 'ソロモンの子はレハブアム。その子はアビヤ、その子はアサ、その子はヨシャファテ、'),
('JPN', '历代志上', 13, 3, 11, 'その子はヨラム、その子はアハズヤ、その子はヨアシュ、'),
('JPN', '历代志上', 13, 3, 12, 'その子はアマツヤ、その子はアザルヤ、その子はヨタム、'),
('JPN', '历代志上', 13, 3, 13, 'その子はアハズ、その子はヒゼキヤ、その子はマナセ、'),
('JPN', '历代志上', 13, 3, 14, 'その子はアモン、その子はヨシヤ。'),
('JPN', '历代志上', 13, 3, 15, 'ヨシヤの子は、長子ヨハナン、次男エホヤキム、三男ゼデキヤ、四男シャルム。'),
('JPN', '历代志上', 13, 3, 16, 'エホヤキムの子孫は、その子エコンヤ、その子ゼデキヤ。'),
('JPN', '历代志上', 13, 3, 17, '捕らわれ人エコンヤの子は、その子シェアルティエル、'),
('JPN', '历代志上', 13, 3, 18, 'マルキラム、ペダヤ、シェンアツァル、エカムヤ、ホシャマ、ネダブヤ。'),
('JPN', '历代志上', 13, 3, 19, 'ペダヤの子は、ゼルバベル、シムイ。ゼルバベルの子は、メシュラム、ハナンヤ、彼らの姉妹シェロミテ。'),
('JPN', '历代志上', 13, 3, 20, 'それにハシュバ、オヘル、ベレクヤ、ハサデヤ、ユシャブ・ヘセデの五人。'),
('JPN', '历代志上', 13, 3, 21, 'ハナンヤの子は、ペラテヤ、エシャヤ、レファヤの子ら、アルナンの子ら、オバデヤの子ら、シェカンヤの子ら。'),
('JPN', '历代志上', 13, 3, 22, 'シェカンヤの子は、シェマヤと、その子である、ハトシュ、イグアル、バリアハ、ネアルヤ、シャファテの六人。'),
('JPN', '历代志上', 13, 3, 23, 'ネアルヤの子は、エルヨエナイ、ヒゼキヤ、アズリカムの三人。'),
('JPN', '历代志上', 13, 3, 24, 'エルヨエナイの子は、ホダウヤ、エルヤシブ、ペラヤ、アクブ、ヨハナン、デラヤ、アナニの七人。'),
('JPN', '历代志上', 13, 4, 1, 'ユダの子は、ペレツ、ヘツロン、カルミ、フル、ショバル。'),
('JPN', '历代志上', 13, 4, 2, 'ショバルの子レアヤはヤハテを生み、ヤハテはアフマイとラハデを生んだ。これらはツォルア人の諸氏族である。'),
('JPN', '历代志上', 13, 4, 3, 'エタムの父の子は次のとおりである。イズレエル、イシュマ、イデバシュ。彼らの姉妹の名はハツレルポニ。'),
('JPN', '历代志上', 13, 4, 4, 'ゲドルの父ペヌエルとフシャの父エゼル。これらがベツレヘムの父、エフラテの長子フルの子である。'),
('JPN', '历代志上', 13, 4, 5, 'テコアの父アシュフルには二人の妻、ヘルアとナアラがいた。'),
('JPN', '历代志上', 13, 4, 6, 'ナアラは彼に、アフザム、ヘフェル、テメニ、アハシュタリを産んだ。これらがナアラの子である。'),
('JPN', '历代志上', 13, 4, 7, 'ヘルアの子は、ツェレテ、ツォハル、エテナン。'),
('JPN', '历代志上', 13, 4, 8, 'コツは、アヌブ、ツォベバ、それにハルムの子アハルヘルの諸氏族を生んだ。'),
('JPN', '历代志上', 13, 4, 9, 'ヤベツは彼の兄弟たちの中で最も重んじられた。彼の母は、「私が痛みのうちにこの子を産んだから」と言って、彼にヤベツという名をつけていた。'),
('JPN', '历代志上', 13, 4, 10, 'ヤベツはイスラエルの神に呼び求めて言った。「私を大いに祝福し、私の地境を広げてくださいますように。御手が私とともにあってわざわいから遠ざけ、私が痛みを覚えることのないようにしてください。」神は彼の願ったことをかなえられた。'),
('JPN', '历代志上', 13, 4, 11, 'シュハの兄弟ケルブはメヒルを生んだ。メヒルはエシュトンの父であった。'),
('JPN', '历代志上', 13, 4, 12, 'エシュトンは、ベテ・ラファ、パセアハ、イル・ナハシュの父テヒナを生んだ。これらはレカの人々である。'),
('JPN', '历代志上', 13, 4, 13, 'ケナズの子はオテニエルとセラヤ。オテニエルの子はハタテとメオノタイ。'),
('JPN', '历代志上', 13, 4, 14, 'メオノタイはオフラを生み、セラヤはゲ・ハラシムの父ヨアブを生んだ。彼らは職人であった。')
on conflict (version, book, chapter, verse) do nothing;
